-- NodeSpec Community Edition: reference registries + starter technology
-- catalog (119 entries, full enrichment depth). Generated by
-- scripts/oss/gen-starter-seed.mjs from the live stack; curation list:
-- scripts/oss/starter-catalog-ids.txt.
-- The squashed schema migration is
-- schema-only, so every migration-seeded row the app needs travels here.
-- Users add their own catalog entries freely — this is a starting set,
-- not a wall.

-- node_roles.can_contain is self-referential and the technology affinity
-- trigger wants roles present first, so pg_dump row order cannot satisfy
-- the m5 triggers. USER triggers are disabled for the load (table-owner
-- privilege only — no superuser needed); FK constraints stay enforced,
-- and the load order satisfies them. The DO block at the end re-runs the
-- canonical-gate checks, so nothing is taken on trust.
ALTER TABLE public.node_roles DISABLE TRIGGER USER;
ALTER TABLE public.technology_catalog DISABLE TRIGGER USER;

-- ── node_roles (86 rows, complete) ──
INSERT INTO public.node_roles VALUES ('game-server', 'Game Server', 'Authoritative game server managing game state, physics, and multiplayer synchronization', 'Server', '#ef4444', 'icon', 'Game Development', false, NULL, '[]', '{}', '[{"name": "client_connections", "required": true, "direction": "in"}, {"name": "state_updates", "required": true, "direction": "out"}, {"name": "persistence", "required": false, "direction": "out"}]', '["event", "request_response", "data_write"]', 470, '2026-05-11 04:11:59.813555+00', '2026-08-30 12:07:22.409228+00', NULL, '{}', false, NULL, 'Choose for authoritative server-side game logic managing state, physics, and multiplayer synchronization. Examples: a Photon server for real-time multiplayer, a Nakama server for matchmaking, a custom Go server for turn-based games. Unlike a Backend Service, a Game Server handles tick-rate simulation and client reconciliation.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('shared-library', 'Shared Library', 'Reusable code package consumed as a dependency by other services', 'Library', '#6366f1', 'icon', 'Logical', false, NULL, '[]', '{}', '[{"name": "exports", "required": true, "direction": "out"}, {"name": "Module Import", "direction": "in"}]', '["dependency"]', 250, '2026-05-11 04:10:11.941145+00', '2026-08-30 12:07:22.409228+00', NULL, '{}', false, NULL, 'Choose for reusable code packages consumed as dependencies by other services rather than deployed independently. Examples: a shared TypeScript validation library, a Python SDK for your internal API, a Go utility package. Unlike a Backend Service, a Shared Library has no runtime process -- it is imported at build time.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('embedded-device', 'Embedded Device', 'Physical embedded target (MCU, SoC, or development board)', 'Cpu', '#64748b', 'icon', 'Hardware', false, NULL, '[]', '{}', '[{"name": "bus-in", "direction": "in"}, {"name": "bus-out", "direction": "out"}]', '["ipc"]', 30, '2026-05-11 04:02:28.563016+00', '2026-08-30 12:07:22.409228+00', NULL, '{hardware,embedded,device}', false, NULL, NULL, NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('ai-agent-service', 'AI Agent Service', 'Autonomous AI agent with tool-use capabilities and multi-step reasoning', 'Bot', '#8b5cf6', 'icon', 'AI & ML', false, NULL, '[]', '{}', '[{"name": "prompt", "required": true, "direction": "in"}, {"name": "tool_calls", "required": true, "direction": "out"}, {"name": "result", "required": true, "direction": "out"}]', '["request_response", "event"]', 280, '2026-05-11 04:10:11.941145+00', '2026-08-30 12:07:22.409228+00', NULL, '{ai,agent,tools,reasoning}', false, NULL, 'Choose for autonomous agents that chain multiple tool calls and reasoning steps to accomplish goals. Examples: a LangGraph agent that searches docs + writes code + runs tests, a CrewAI multi-agent team for research, an AutoGen conversational agent. Unlike a simple AI Service (single call), an AI Agent Service orchestrates multi-step reasoning loops.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('certificate-manager', 'Certificate Manager', 'TLS/SSL certificate lifecycle management', 'shield', '#059669', 'service', 'Networking', false, NULL, '[]', '{}', '[{"name": "cert-in", "direction": "in"}, {"name": "cert-out", "direction": "out"}]', '[]', 48, '2026-05-12 02:51:27.394642+00', '2026-08-30 12:07:22.38638+00', NULL, '{security,tls}', false, NULL, 'Choose when you need automated TLS/SSL certificate provisioning, renewal, and lifecycle management ΓÇö securing HTTPS endpoints and service-to-service mTLS.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('data-warehouse', 'Data Warehouse', 'Analytical data warehouse for OLAP queries, reporting, and business intelligence', 'Warehouse', '#0ea5e9', 'icon', 'Database', false, NULL, '[]', '{}', '[{"name": "ingest", "required": true, "direction": "in"}, {"name": "query", "required": true, "direction": "out"}]', '["data_write", "data_read"]', 37, '2026-05-11 04:10:38.518873+00', '2026-08-30 12:07:22.409228+00', NULL, '{analytics,olap,bigquery,redshift,synapse,aws,gcp,cloud-managed}', false, NULL, 'Choose for analytical workloads over large historical datasets with columnar storage. Examples: Snowflake for business intelligence queries, BigQuery for petabyte-scale analytics, Redshift for data team reporting. Unlike a transactional Database, a Data Warehouse is optimized for complex aggregations over massive read-mostly datasets.', NULL, 'build', 'data');
INSERT INTO public.node_roles VALUES ('supabase', 'Supabase (Managed)', 'The fully managed Supabase product (Postgres database, Auth, Storage, Edge Functions, Realtime, Vector) operated by Supabase. ONE node represents the whole product; declare which services the architecture uses in its configuration. For self-hosting, use the individual OSS component technologies inside your own container instead.', 'Database', '#3ecf8e', 'container', 'Platform', true, 'infrastructure', '{"natures": [], "roleIds": ["auth-provider", "database", "object-storage", "realtime-service", "serverless-function"], "providers": [], "interfaceKinds": []}', '{}', '[{"name": "Client API", "direction": "in"}, {"name": "Service Calls", "direction": "out"}]', '[]', 1, '2026-05-11 04:03:18.847549+00', '2026-08-30 12:07:24.25826+00', 'hosting', '{platform,baas,managed,postgres,auth,edge-functions,storage,realtime}', false, NULL, 'Choose when Supabase hosts the backend for you (the out-of-box supabase.com product). Configure which services are used — using only a portion is expected. For self-hosted Supabase, place the OSS components (supabase-db, supabase-auth, supabase-storage, supabase-edge-functions) inside your own Docker/Kubernetes container instead.', NULL, 'host', 'service');
INSERT INTO public.node_roles VALUES ('firmware-service', 'Firmware Service', 'Firmware management service for OTA updates and device provisioning', 'Binary', '#0ea5e9', 'icon', 'Hardware', false, NULL, '[]', '{}', '[{"name": "hardware-in", "direction": "in"}, {"name": "telemetry-out", "direction": "out"}]', '["ipc", "data_read"]', 17, '2026-05-11 04:02:28.563016+00', '2026-08-30 12:07:22.409228+00', NULL, '{compute,embedded,firmware}', false, NULL, 'Choose for firmware management services handling OTA updates and device provisioning. Examples: a service managing ESP32 firmware versions, an OTA update server for IoT fleet management. Unlike a Backend Service, a Firmware Service specifically manages device software lifecycle.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('game-engine-project', 'Game Engine Project', 'Deprecated: use game-client instead — the game itself (the Unity/Godot/Unreal project) is a buildable node, not a workspace container. Game engine project containing gameplay, physics, and rendering systems', 'Gamepad2', '#ec4899', 'container', 'Game Development', true, 'logical', '["backend-service", "database", "frontend-app", "game-client", "game-server", "inference-service", "queue", "realtime-service", "shared-library", "vector-database", "worker"]', '{}', '[]', '[]', 1, '2026-05-11 04:02:28.563016+00', '2026-08-30 12:07:22.533535+00', 'logical-boundary', '{game,engine,container}', true, NULL, 'Choose for the game engine project containing gameplay systems, rendering, physics, and asset management. Examples: a Unity project with scenes and scripts, an Unreal project with blueprints and C++ gameplay code. This represents the entire game development workspace.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('sensor', 'Sensor', 'Physical sensor collecting environmental data (temperature, motion, pressure, etc.)', 'Thermometer', '#22c55e', 'icon', 'Hardware', false, NULL, '[]', '{}', '[{"name": "readings", "required": true, "direction": "out"}]', '["ipc", "event"]', 400, '2026-05-11 04:11:37.367043+00', '2026-08-30 12:07:22.409228+00', NULL, '{}', false, NULL, 'Choose for physical sensor hardware that collects environmental data. Examples: a temperature probe, a motion detector, a pressure sensor, a camera module. Sensors feed data to Microcontrollers or IoT Gateways.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('message-broker', 'Message Broker', 'Asynchronous message routing and delivery', 'mail', '#a855f7', 'queue', 'Messaging', false, NULL, '[]', '{}', '[{"name": "Publish", "direction": "in"}, {"name": "Subscribe", "direction": "out"}]', '["queue"]', 50, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{messaging,rabbitmq,kafka,sns,nats,async,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for a message routing hub that owns exchanges, bindings, and delivery guarantees between producers and consumers. Examples: RabbitMQ, ActiveMQ, Amazon MQ.', NULL, 'build', 'queue');
INSERT INTO public.node_roles VALUES ('event-stream', 'Event Stream', 'Distributed event streaming platform', 'activity', '#7c3aed', 'queue', 'Messaging', false, NULL, '[]', '{}', '[{"name": "Produce", "direction": "in"}, {"name": "Consume", "direction": "out"}]', '["event"]', 51, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{messaging,kafka,kinesis,eventbridge,streaming,realtime,aws,azure,gcp,cloud-managed}', false, NULL, 'When you need Kafka, Pulsar, or Kinesis-style ordered event streaming with replay and partitioning.', NULL, 'build', 'event_bus');
INSERT INTO public.node_roles VALUES ('aws', 'AWS', 'Amazon Web Services cloud platform providing compute, storage, messaging, and database services', 'Cloud', '#ff9900', 'container', 'Platform', true, 'infrastructure', '{"natures": ["build", "call", "engine", "integrate"], "roleIds": [], "providers": ["aws"], "interfaceKinds": ["auth", "data", "event_bus", "object_store", "queue", "service", "telemetry"]}', '{"iacTool": {"type": "enum", "label": "IaC tool", "options": ["terraform", "opentofu", "pulumi", "provider-native", "cdk"], "description": "The infrastructure-as-code tool EVERY declarative node in this platform is provisioned with — inherited by contained nodes and named verbatim in their task packets. Terraform is the ecosystem default (BSL-licensed since 2023; OpenTofu is the Linux Foundation fork under MPL); provider-native = CloudFormation/Bicep/Config-Connector. Leave unset only if undecided — packets will then instruct the AI to confirm rather than assume"}, "costTags": {"type": "boolean", "label": "Enforce cost-allocation tags", "default": true, "description": "project/env/owner tags on every child resource — IaC-enforced, reads in Cost Explorer"}, "environment": {"type": "enum", "label": "Environment", "default": "production", "options": ["dev", "staging", "production"], "description": "Drives sizing/HA defaults children inherit"}, "iamBaseline": {"type": "enum", "label": "IAM baseline", "default": "identity-center-sso", "options": ["identity-center-sso", "iam-users-mfa", "oidc-federation-only"], "description": "Account access model — Identity Center setup is a CONSOLE step; role/policy wiring is IaC"}, "accountAlias": {"type": "string", "label": "Account alias", "description": "Which AWS account/environment this container represents (e.g. myapp-prod)"}, "budgetAlerts": {"type": "boolean", "label": "Budget alerts", "default": true, "description": "AWS Budgets alarm wiring (IaC) — the notification email confirm is a console step"}, "primaryRegion": {"type": "string", "label": "Primary region", "default": "us-east-1", "description": "Default region children deploy into unless they say otherwise — IaC reads this"}}', '[]', '[]', 2, '2026-05-11 04:03:18.847549+00', '2026-08-30 12:07:22.439057+00', 'hosting', '{platform,cloud,managed,lambda,s3,rds,sqs,eventbridge,ec2,ecs,amazon}', false, 'aws', 'Choose when your architecture is built on AWS and you want to represent the platform container with its managed capabilities (Lambda, S3, SQS, RDS, EventBridge). Drag this onto the canvas to set up an AWS-centric deployment context.', NULL, 'host', 'service');
INSERT INTO public.node_roles VALUES ('frontend-app', 'Frontend Application', 'Client-side web application or SPA', 'monitor', '#3b82f6', 'service', 'Services', false, NULL, '[]', '{"renderMode": {"type": "enum", "label": "Render mode", "default": "hybrid", "options": ["static-ssg", "server-ssr", "client-spa", "hybrid"], "description": "How pages are produced. A statically-generated site is a render mode of a frontend app, not a different kind of node."}}', '[{"name": "HTTP In", "direction": "in"}, {"name": "API Call", "direction": "out"}, {"name": "Module Dependency", "direction": "out"}, {"name": "Service Import", "direction": "in"}]', '["request_response", "event"]', 1, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{client-facing,ui}', false, NULL, 'Choose for client-rendered web applications (SPAs) or server-rendered apps where the browser is the primary runtime. Examples: a React dashboard, a Next.js marketing site, an Angular enterprise portal. Unlike a Static Site, a Frontend Application may include client-side routing, state management, and API calls.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('microservice-boundary', 'Microservice Boundary', 'Logical grouping of related services', 'box', '#64748b', 'container', 'Logical', true, 'logical', '["auth-provider", "backend-service", "cache", "database", "event-stream", "graph-db", "logging", "message-broker", "monitoring", "realtime-service", "scheduled-trigger", "search-engine", "time-series-db", "vector-database", "worker"]', '{"domain": {"type": "string", "label": "Business Domain", "required": true, "description": "Domain this service belongs to"}, "apiGateway": {"type": "string", "label": "API Gateway", "description": "Kong, Ambassador, AWS API Gateway, etc."}, "serviceRegistry": {"type": "string", "label": "Service Registry", "description": "Consul, Eureka, etcd, etc."}, "authenticationMethod": {"type": "string", "label": "Authentication Method", "default": "jwt", "description": "jwt, oauth2, api-key, mtls"}, "communicationProtocol": {"type": "string", "label": "Communication Protocol", "default": "rest", "description": "rest, graphql, grpc, message-queue"}}', '[]', '[]', 130, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.38638+00', 'logical-boundary', '{logical-boundary}', false, NULL, 'Choose for logical grouping of services that form a single deployable microservice. Examples: a boundary around an API + worker + database that deploy together, a team-owned service group. Unlike a Bounded Context (conceptual), a Microservice Boundary defines a deployment and ownership unit.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('gateway-device', 'IoT Gateway', 'Edge gateway device bridging local IoT devices to cloud services via protocol translation', 'Router', '#0ea5e9', 'container', 'Hardware', true, 'infrastructure', '["sensor", "actuator", "microcontroller", "firmware-service"]', '{}', '[{"name": "local_bus", "required": true, "direction": "in"}, {"name": "cloud_uplink", "required": true, "direction": "out"}]', '["ipc", "request_response", "event"]', 430, '2026-05-11 04:11:37.367043+00', '2026-08-30 12:07:22.409228+00', 'hosting', '{}', false, NULL, 'Choose for edge gateway hardware that bridges local IoT devices to cloud services. Examples: an AWS IoT Greengrass core, a Raspberry Pi running MQTT broker, an industrial edge gateway aggregating factory sensors. Unlike a Microcontroller (single-purpose), an IoT Gateway routes and translates protocols between local devices and the cloud.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('robot', 'Robot', 'Robotic system integrating sensors, actuators, controllers, and ROS 2 nodes', 'Bot', '#14b8a6', 'container', 'Hardware', true, 'infrastructure', '["sensor", "actuator", "microcontroller", "ros2-node", "firmware-service"]', '{}', '[{"name": "commands", "required": true, "direction": "in"}, {"name": "telemetry", "required": true, "direction": "out"}]', '["ipc", "ipc", "event"]', 440, '2026-05-11 04:11:37.367043+00', '2026-08-30 12:07:22.409228+00', 'hosting', '{}', false, NULL, 'Choose for complete robotic systems integrating sensors, actuators, controllers, and software nodes. Examples: a warehouse robot, a drone platform, a surgical robot, a self-driving vehicle subsystem.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('feature-store', 'Feature Store', 'ML feature store for online/offline feature serving, versioning, and discovery', 'Layers', '#a855f7', 'icon', 'AI & ML', false, NULL, '[]', '{}', '[{"name": "register", "required": true, "direction": "in"}, {"name": "serve", "required": true, "direction": "out"}]', '["data_write", "data_read", "request_response"]', 39, '2026-05-11 04:10:38.518873+00', '2026-08-30 12:07:22.409228+00', NULL, '{ml,features,serving}', false, NULL, 'Choose for centralized feature computation, storage, and serving for ML models. Examples: Feast serving real-time user features, Tecton computing features from streaming data, Vertex AI Feature Store for team collaboration. Unlike a Database, a Feature Store manages feature versioning, point-in-time correctness, and online/offline serving.', NULL, 'build', 'data');
INSERT INTO public.node_roles VALUES ('object-storage', 'Object Storage', 'Blob and object storage for files, images, backups, and unstructured data', 'hard-drive', '#F59E0B', 'service', 'Database', false, NULL, '[]', '{"region": {"type": "string", "label": "Region", "default": "us-east-1", "description": "Geographic region"}, "buckets": {"type": "array", "label": "Buckets / Containers", "description": "Object storage buckets or containers"}, "encryption": {"type": "string", "label": "Encryption", "default": "AES256", "description": "Server-side encryption method"}, "versioning": {"type": "boolean", "label": "Versioning", "default": false, "description": "Enable object versioning"}, "accessControl": {"type": "string", "label": "Access Control", "default": "private", "description": "Access policy: private, public-read, or acl-based"}}', '[{"name": "Upload In", "required": true, "direction": "in"}, {"name": "Download Out", "direction": "out"}]', '["data_read", "request_response"]', 32, '2026-02-20 14:51:11.165373+00', '2026-08-30 12:07:22.409228+00', NULL, '{data-store,storage,aws,azure,cloudflare,gcp,supabase,cloud-managed}', false, NULL, 'Choose for files, images, videos, backups, and any unstructured binary data. Examples: S3 for user uploads, GCS for ML training datasets, Azure Blob for document archives. Unlike a Database, Object Storage is optimized for large binary blobs with flat namespace access.', NULL, 'build', 'object_store');
INSERT INTO public.node_roles VALUES ('secret-manager', 'Secret Manager', 'Centralized secrets and key management', 'lock', '#7c3aed', 'service', 'Networking', false, NULL, '[]', '{}', '[{"name": "secret-in", "direction": "in"}, {"name": "secret-out", "direction": "out"}]', '[]', 47, '2026-05-12 02:51:27.394642+00', '2026-08-30 12:07:22.38638+00', NULL, '{security,secrets}', false, NULL, 'Choose when you need centralized secrets storage with access control, rotation policies, and audit logging ΓÇö API keys, database credentials, certificates.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('cloudflare', 'Cloudflare', 'Cloudflare platform providing edge workers, R2 storage, and CDN services', 'Globe', '#f38020', 'container', 'Platform', true, 'infrastructure', '{"natures": ["build", "call", "engine", "integrate"], "roleIds": [], "providers": ["cloudflare"], "interfaceKinds": ["auth", "data", "event_bus", "object_store", "queue", "service", "telemetry"]}', '{}', '[]', '[]', 4, '2026-05-11 04:03:18.847549+00', '2026-08-30 12:07:22.439057+00', 'hosting', '{platform,edge,cdn,workers,r2,kv,pages}', false, 'cloudflare', 'Choose when your architecture uses Cloudflare for edge compute (Workers), storage (R2), and CDN capabilities as a cohesive platform.', NULL, 'host', 'service');
INSERT INTO public.node_roles VALUES ('mobile-app', 'Mobile Application', 'Native or cross-platform mobile app', 'smartphone', '#8b5cf6', 'service', 'Services', false, NULL, '[]', '{}', '[{"name": "API Call", "direction": "out"}, {"name": "Push Notification", "direction": "in"}]', '["request_response", "event"]', 3, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{client-facing,ui}', false, NULL, 'Choose for native or cross-platform mobile apps deployed via app stores. Examples: an iOS banking app in Swift, a React Native fitness tracker, a Flutter e-commerce app. Unlike a Frontend Application, a Mobile App runs on device hardware with access to sensors, push notifications, and offline storage.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('waf', 'WAF', 'Web Application Firewall for traffic filtering', 'shield', '#dc2626', 'service', 'Networking', false, NULL, '[]', '{}', '[{"name": "traffic-in", "direction": "in"}, {"name": "traffic-out", "direction": "out"}]', '[]', 46, '2026-05-12 02:51:27.394642+00', '2026-08-30 12:07:22.38638+00', NULL, '{security,filtering}', false, NULL, 'Choose when you need HTTP-layer threat filtering, request inspection, or rate limiting ΓÇö protecting web applications from OWASP top-10 attacks and bot traffic.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('model-registry', 'Model Registry', 'ML model version registry for tracking, staging, and deploying model artifacts', 'Archive', '#d946ef', 'icon', 'AI & ML', false, NULL, '[]', '{}', '[{"name": "register", "required": true, "direction": "in"}, {"name": "fetch", "required": true, "direction": "out"}]', '["data_write", "data_read"]', 40, '2026-05-11 04:10:38.518873+00', '2026-08-30 12:07:22.409228+00', NULL, '{ml,versioning,models}', false, NULL, 'Choose for tracking, versioning, and staging model artifacts through their lifecycle. Examples: MLflow Model Registry for experiment tracking, Weights & Biases for model comparison, Neptune for team collaboration on model versions. Unlike Object Storage (raw files), a Model Registry provides model lineage, stage transitions, and deployment metadata.', NULL, 'build', 'data');
INSERT INTO public.node_roles VALUES ('dns', 'DNS', 'DNS management and routing service', 'globe', '#2563eb', 'service', 'Networking', false, NULL, '[]', '{}', '[{"name": "dns-in", "direction": "in"}, {"name": "dns-out", "direction": "out"}]', '[]', 45, '2026-05-12 02:51:27.394642+00', '2026-08-30 12:07:22.38638+00', NULL, '{networking,resolution}', false, NULL, 'Choose when you need domain name resolution, routing configuration, or traffic management at the DNS layer ΓÇö hosted zones, record sets, or DNS-based failover.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('auth-provider', 'Auth Provider', 'Authentication and identity management service', 'lock', '#059669', 'service', 'Networking', false, NULL, '[]', '{}', '[{"name": "Auth Request", "direction": "in"}, {"name": "Token", "direction": "out"}]', '["auth"]', 60, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{auth,identity,oauth,cognito,auth0,sso,iam,aws,azure,firebase,gcp,supabase,cloud-managed}', false, NULL, 'Choose for identity verification, session management, and access control as a dedicated concern. Examples: Auth0 for social login, Keycloak for enterprise SSO, Supabase Auth for email/password. Unlike embedding auth logic in a Backend Service, a dedicated Auth Provider centralizes user management and token issuance.', NULL, 'build', 'auth');
INSERT INTO public.node_roles VALUES ('load-balancer', 'Load Balancer', 'Traffic distribution across service instances', 'git-merge', '#0369a1', 'service', 'Networking', false, NULL, '[]', '{}', '[{"name": "Traffic In", "direction": "in"}, {"name": "Backend", "direction": "out"}]', '["request_response"]', 25, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{networking,api,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for distributing traffic across multiple instances of a service for availability and scale. Examples: AWS ALB routing to ECS tasks, NGINX upstream balancing, HAProxy for database read replicas. Unlike an API Gateway, a Load Balancer focuses on traffic distribution rather than request transformation or policy.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('event-store', 'Event Store', 'Append-only event log for event sourcing, CQRS projections, and temporal queries', 'ScrollText', '#84cc16', 'icon', 'Database', false, NULL, '[]', '{}', '[{"name": "append", "required": true, "direction": "in"}, {"name": "stream", "required": true, "direction": "out"}]', '["event", "event", "data_read"]', 38, '2026-05-11 04:10:38.518873+00', '2026-08-30 12:07:22.409228+00', NULL, '{event-sourcing,cqrs,append-only,messaging}', false, NULL, 'When you need event sourcing or CQRS with append-only logs (EventStoreDB, Axon). State is rebuilt from event history.', NULL, 'build', 'data');
INSERT INTO public.node_roles VALUES ('iac-workflow', 'IaC Workflow', 'Infrastructure as Code provisioning workflow', 'cloud', '#6366f1', 'service', 'Automation', false, NULL, '[]', '{}', '[{"name": "trigger-in", "direction": "in"}, {"name": "infra-out", "direction": "out"}]', '[]', 52, '2026-05-12 02:51:44.466481+00', '2026-08-30 12:07:22.38638+00', NULL, '{iac,terraform,provisioning}', false, NULL, 'Choose when you need infrastructure provisioning or configuration managed as code ΓÇö Terraform, Pulumi, CloudFormation, or database migration orchestration (Flyway, Liquibase).', NULL, 'engine', 'service');
INSERT INTO public.node_roles VALUES ('hypervisor', 'Hypervisor Cluster', 'Virtualization platform (vSphere, Hyper-V, Proxmox)', 'server', '#0f172a', 'container', 'Infrastructure', true, 'infrastructure', '["virtual-machine", "vpc", "k8s-cluster", "docker-compose", "docker-container", "backend-service", "worker", "database", "cache", "vector-database"]', '{"platform": {"type": "string", "label": "Platform", "default": "vmware-vsphere", "description": "vmware-vsphere, hyper-v, proxmox, kvm"}, "haEnabled": {"type": "boolean", "label": "High Availability", "default": true, "description": "Enable automatic VM failover"}, "hostCount": {"type": "number", "label": "Host Count", "default": 3, "description": "Number of hosts in cluster"}, "clusterName": {"type": "string", "label": "Cluster Name", "required": true, "description": "Virtualization cluster identifier"}}', '[]', '[]', 48, '2026-02-08 21:38:04.485552+00', '2026-08-30 12:07:22.38638+00', 'hosting', '{}', false, NULL, NULL, NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('vector-database', 'Vector Database', 'Stores and queries vector embeddings for semantic search and similarity-based retrieval', 'database', '#0ECF83', 'service', 'Database', false, NULL, '[]', '{"host": {"type": "string", "label": "Host", "default": "localhost", "description": "Database host address"}, "port": {"type": "number", "label": "Port", "description": "Database port number"}, "indexName": {"type": "string", "label": "Index Name", "description": "Primary vector index name"}, "distanceMetric": {"type": "string", "label": "Distance Metric", "description": "Similarity metric (cosine, dotproduct, euclidean)"}, "embeddingDimension": {"type": "number", "label": "Embedding Dimension", "description": "Vector dimension size (e.g. 1536 for text-embedding-ada-002)"}}', '[{"name": "Upsert", "direction": "in"}, {"name": "Query", "direction": "in"}, {"name": "Results", "direction": "out"}]', '["request_response"]', 35, '2026-03-12 23:28:27.7584+00', '2026-08-30 12:07:22.409228+00', NULL, '{data-store,vector-search}', false, NULL, 'Choose for storing and querying vector embeddings for semantic similarity search. Examples: Pinecone for RAG retrieval, pgvector for embedding-augmented PostgreSQL, Weaviate for multimodal search. Unlike a Database, a Vector Database is optimized for approximate nearest neighbor (ANN) queries over high-dimensional embeddings.', NULL, 'build', 'data');
INSERT INTO public.node_roles VALUES ('external-service', 'External Service', 'Third-party API or SaaS integration', 'external-link', '#6b7280', 'external', 'External', false, NULL, '[]', '{}', '[{"name": "API Call", "direction": "out"}]', '["request_response"]', 90, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{external}', false, NULL, 'Choose for any third-party API or SaaS that your system integrates with but does not own. Examples: Stripe for payments, SendGrid for email, Twilio for SMS, a partner company''s REST API. This represents an external dependency boundary -- you consume it but cannot modify it.', NULL, 'call', 'service');
INSERT INTO public.node_roles VALUES ('external-data', 'External Data Source', 'External data feed or import source', 'download', '#9ca3af', 'external', 'External', false, NULL, '[]', '{}', '[{"name": "Data Feed", "direction": "in"}]', '["request_response", "event"]', 91, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{external}', false, NULL, 'Choose for external data feeds or import sources that your system ingests. Examples: a government open-data API, a stock market feed, a partner SFTP drop, a third-party CSV export. Unlike an External Service (which you call for actions), an External Data Source provides data you pull or receive.', NULL, 'call', 'service');
INSERT INTO public.node_roles VALUES ('inference-service', 'AI / Inference Service', 'AI model inference endpoint, whether calling external AI APIs (OpenAI, Anthropic) or serving self-hosted models (TensorFlow Serving, TorchServe, vLLM).', 'Brain', '#ec4899', 'icon', 'AI & ML', false, NULL, '[]', '{}', '[{"name": "input", "required": true, "direction": "in"}, {"name": "prediction", "required": true, "direction": "out"}]', '["request_response", "data_read"]', 290, '2026-05-11 04:10:11.941145+00', '2026-08-30 12:07:22.409228+00', NULL, '{ai,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose when you need AI/ML model inference — whether via a gateway proxy that routes to multiple LLM providers (e.g. LiteLLM), a self-hosted runtime serving open-source models (e.g. Ollama, vLLM), or a managed inference endpoint. Covers all inference deployment topologies.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('cache', 'Cache', 'In-memory data caching layer', 'hard-drive', '#ef4444', 'cache', 'Database', false, NULL, '[]', '{"host": {"type": "string", "label": "Host", "default": "localhost", "description": "Cache server host address"}, "port": {"type": "number", "label": "Port", "default": 6379, "description": "Cache server port number"}, "keyPrefix": {"type": "string", "label": "Key Prefix", "description": "Namespace prefix for cache keys"}, "maxMemory": {"type": "string", "label": "Max Memory", "description": "Maximum memory allocation (e.g., 512mb, 2gb)"}, "persistence": {"type": "boolean", "label": "Persistence", "default": false, "description": "Whether data is persisted to disk"}, "evictionPolicy": {"type": "string", "label": "Eviction Policy", "default": "lru", "description": "Cache eviction strategy (e.g., LRU, LFU, TTL)"}}', '[{"name": "Get/Set", "direction": "in"}]', '["data_read"]', 36, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{caching,redis,memcached,elasticache,memorystore,in-memory,azure,cloudflare,gcp,cloud-managed,aws}', false, NULL, 'Choose for high-speed, in-memory data access to reduce latency on hot paths. Examples: Redis caching session data, Memcached storing API response fragments, Cloudflare KV for edge config. Unlike a Database, a Cache is ephemeral -- data loss is acceptable and expected.', NULL, 'build', 'data');
INSERT INTO public.node_roles VALUES ('application-module', 'Application Module', 'Logical module within an application', 'package', '#334155', 'container', 'Logical', true, 'logical', '["auth-provider", "backend-service", "cache", "database", "event-stream", "frontend-app", "graph-db", "logging", "message-broker", "monitoring", "realtime-service", "scheduled-trigger", "time-series-db", "vector-database", "worker"]', '{"moduleName": {"type": "string", "label": "Module Name", "required": true, "description": "Unique module identifier"}, "moduleType": {"type": "string", "label": "Module Type", "default": "feature", "description": "feature, core, or plugin"}, "visibility": {"type": "string", "label": "Visibility", "default": "internal", "description": "internal or public"}, "dependencies": {"type": "array", "label": "Dependencies", "description": "Other modules this depends on"}, "testCoverage": {"type": "number", "label": "Test Coverage (%)", "default": 0, "description": "Code coverage percentage"}}', '[]', '[]', 132, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.38638+00', 'logical-boundary', '{logical-boundary}', false, NULL, 'Choose for logical modules within a single application that group related functionality. Examples: a "notifications" module in a monolith, a "reporting" module, a feature folder in a frontend app. Unlike a Bounded Context (domain boundary), an Application Module is an internal organizational unit.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('ecs-cluster', 'ECS Cluster', 'AWS ECS container cluster', 'box', '#ff9900', 'container', 'Infrastructure', true, 'orchestration', '["application-module", "backend-service", "bounded-context", "cache", "database", "event-stream", "inference-service", "load-balancer", "logging", "message-broker", "microservice-boundary", "monitoring", "realtime-service", "scheduled-trigger", "search-engine", "service-mesh", "software-layer", "vector-database", "worker"]', '{"taskCount": {"type": "number", "label": "Task Count", "default": 2, "description": "Number of running tasks"}, "clusterArn": {"type": "string", "label": "Cluster ARN", "description": "ECS cluster Amazon Resource Name"}, "launchType": {"type": "string", "label": "Launch Type", "default": "FARGATE", "description": "FARGATE or EC2"}}', '[]', '[]', 113, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.489787+00', 'hosting', '{aws,cloud-managed}', false, 'aws', 'Choose for AWS ECS container orchestration boundaries. Examples: an ECS cluster running Fargate tasks, an EC2-backed ECS cluster with auto-scaling. An ECS Cluster contains task definitions and services that run your containers.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('microcontroller', 'Microcontroller', 'Embedded MCU running firmware for real-time control and sensor aggregation', 'Cpu', '#6366f1', 'icon', 'Hardware', false, NULL, '[]', '{}', '[{"name": "gpio", "required": true, "direction": "in"}, {"name": "bus_out", "required": true, "direction": "out"}]', '["ipc", "ipc"]', 420, '2026-05-11 04:11:37.367043+00', '2026-08-30 12:07:22.409228+00', NULL, '{}', false, NULL, 'Choose for embedded MCUs running firmware for real-time control and sensor aggregation. Examples: an ESP32 collecting sensor data, an Arduino controlling actuators, an STM32 running an RTOS. Unlike a Virtual Machine, a Microcontroller runs bare-metal or RTOS firmware with direct hardware access.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('cli-tool', 'CLI Tool', 'Command-line interface application for developer or operator interaction', 'Terminal', '#64748b', 'icon', 'External', false, NULL, '[]', '{}', '[{"name": "commands", "required": true, "direction": "in"}, {"name": "api_calls", "required": true, "direction": "out"}]', '["request_response", "ipc"]', 300, '2026-05-11 04:10:11.941145+00', '2026-08-30 12:07:22.409228+00', NULL, '{command-line,terminal,scripts}', false, NULL, 'Choose for terminal-based tools that developers or operators run locally. Examples: a Go CLI for managing deployments (like the AWS CLI), a Rust tool for linting config files, a Node.js scaffolding generator. Unlike a Backend Service, a CLI Tool runs on the user''s machine and exits after completing its task.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('queue', 'Message Queue', 'Point-to-point message queue for asynchronous task dispatch and work distribution', 'ListOrdered', '#f97316', 'icon', 'Messaging', false, NULL, '[]', '{}', '[{"name": "enqueue", "required": true, "direction": "in"}, {"name": "dequeue", "required": true, "direction": "out"}]', '["queue", "queue"]', 310, '2026-05-11 04:10:38.518873+00', '2026-08-30 12:07:22.409228+00', NULL, '{messaging,async,sqs,service-bus,fifo,aws,cloud-managed}', false, NULL, 'When you need point-to-point job dispatch (SQS, Bull, Celery). One producer, one consumer per message.', NULL, 'build', 'queue');
INSERT INTO public.node_roles VALUES ('ros2-node', 'ROS 2 Node', 'ROS 2 computation node communicating via topics, services, and actions', 'Network', '#059669', 'icon', 'Hardware', false, NULL, '[]', '{}', '[{"name": "subscribe", "required": true, "direction": "in"}, {"name": "publish", "required": true, "direction": "out"}]', '["event", "event", "request_response"]', 450, '2026-05-11 04:11:37.367043+00', '2026-08-30 12:07:22.409228+00', NULL, '{}', false, NULL, 'Choose for ROS 2 computation nodes communicating via topics, services, and actions within a robotic system. Examples: a navigation planner node, a LIDAR processing node, a motor controller node. Unlike a Backend Service, a ROS 2 Node uses the ROS 2 middleware (DDS) rather than HTTP.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('api-gateway', 'API Gateway', 'Request routing, rate limiting, and API management', 'shield', '#0284c7', 'api', 'Networking', false, NULL, '[]', '{}', '[{"name": "Public In", "direction": "in"}, {"name": "Service Route", "direction": "out"}]', '["request_response"]', 24, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{networking,api,gateway,routing,rate-limiting,apigee,kong,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for centralized request routing, rate limiting, authentication, and API versioning that sits in front of multiple backend services. Examples: Kong managing microservice traffic, AWS API Gateway throttling public APIs, NGINX routing /api/* to different services. Unlike a Load Balancer, an API Gateway applies request transformation, auth checks, and policy enforcement.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('ml-pipeline', 'ML Pipeline', 'Triggered batch job over data: preparation, training, or evaluation.', 'git-branch', '#db2777', 'service', 'AI & ML', false, NULL, '[]', '{"stage": {"type": "enum", "label": "Pipeline stage", "default": "training", "options": ["data-prep", "training", "evaluation", "full-lifecycle"], "description": "Which part of the ML lifecycle this job runs. Prep/train/eval are stages of one pipeline shape, not different node types."}}', '[{"name": "Data In", "direction": "in"}, {"name": "Model Out", "direction": "out"}]', '["request_response", "event"]', 71, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{ml,training,automation,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for a triggered batch job over data — preparation, model training, or evaluation. Select the stage rather than modelling each as its own node type.', NULL, 'engine', 'service');
INSERT INTO public.node_roles VALUES ('monitoring', 'Monitoring', 'Application and infrastructure monitoring', 'activity', '#0891b2', 'service', 'Observability', false, NULL, '[]', '{}', '[{"name": "Metrics In", "direction": "in"}, {"name": "Alert", "direction": "out"}]', '["request_response", "event"]', 80, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{observability,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for metrics collection, alerting, and system health dashboards. Examples: Prometheus + Grafana for infrastructure metrics, Datadog for APM, CloudWatch Metrics for AWS resource health. Unlike Logging (discrete events), Monitoring tracks continuous numeric measurements over time.', NULL, 'build', 'telemetry');
INSERT INTO public.node_roles VALUES ('logging', 'Logging', 'Centralized log aggregation and analysis', 'file-text', '#0e7490', 'service', 'Observability', false, NULL, '[]', '{}', '[{"name": "Log In", "direction": "in"}, {"name": "Query", "direction": "out"}]', '["request_response"]', 81, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{observability,logs,aggregation,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for centralized log aggregation, search, and analysis. Examples: CloudWatch Logs for AWS services, Datadog Logs for cross-service correlation, ELK Stack for full-text log search. Logging captures discrete events and textual output from your running systems.', NULL, 'build', 'telemetry');
INSERT INTO public.node_roles VALUES ('scheduled-trigger', 'Scheduled Trigger', 'Infrastructure scheduler that triggers jobs on a cron or time-based schedule', 'Timer', '#f97316', 'icon', 'Automation', false, NULL, '[]', '{}', '[{"name": "trigger-out", "direction": "out"}]', '["event"]', 14, '2026-05-11 04:02:28.563016+00', '2026-08-30 12:07:28.809178+00', NULL, '{automation,scheduling,trigger,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for infrastructure-level time-based triggers that fire on a cron schedule. Examples: AWS EventBridge Scheduler invoking a Lambda nightly, a Kubernetes CronJob running database backups, GCP Cloud Scheduler pinging an endpoint hourly. Unlike a Scheduler Service (application-level), a Scheduled Trigger is a simple fire-and-forget timer.', NULL, 'engine', 'service');
INSERT INTO public.node_roles VALUES ('bounded-context', 'Bounded Context', 'DDD bounded context boundary', 'hexagon', '#475569', 'container', 'Logical', true, 'logical', '["backend-service", "cache", "database", "event-stream", "graph-db", "message-broker", "microservice-boundary", "scheduled-trigger", "vector-database", "worker"]', '{"domain": {"type": "string", "label": "Domain Name", "required": true, "description": "Business domain (e.g., Order Management)"}, "aggregates": {"type": "array", "label": "Aggregate Roots", "description": "Key domain entities"}, "domainEvents": {"type": "array", "label": "Domain Events", "description": "Events published by this context"}, "anticorruptionLayer": {"type": "boolean", "label": "Anti-Corruption Layer", "default": false, "description": "Protect domain model from external changes"}}', '[]', '[]', 131, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.38638+00', 'logical-boundary', '{logical-boundary}', false, NULL, 'Choose for DDD bounded context boundaries that encapsulate a cohesive domain model. Examples: an "Orders" context owning order lifecycle, a "Billing" context owning payment logic. Unlike an Application Module, a Bounded Context defines a linguistic and data ownership boundary between teams or domains.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('container-registry', 'Container Registry', 'Stores and serves container images and OCI artifacts for deployment pipelines.', 'package', '#0891b2', 'service', 'Infrastructure', false, NULL, '[]', '{}', '[{"name": "push", "direction": "in"}, {"name": "pull", "direction": "out"}]', '[]', 65, '2026-08-30 12:07:22.38638+00', '2026-08-30 12:07:22.38638+00', NULL, '{registry,images,oci,artifacts}', false, NULL, 'Choose for storing container images that deployment targets pull from. A registry is not a bucket — it serves an image protocol, not object keys.', NULL, 'build', 'object_store');
INSERT INTO public.node_roles VALUES ('file-share', 'File Share', 'Shared network filesystem mounted by multiple workloads (SMB/NFS semantics).', 'folder', '#059669', 'service', 'Database', false, NULL, '[]', '{}', '[{"name": "mount", "direction": "in"}]', '[]', 28, '2026-08-30 12:07:22.38638+00', '2026-08-30 12:07:22.38638+00', NULL, '{filesystem,nfs,smb,shared-storage}', false, NULL, 'Choose when several workloads mount the SAME filesystem and read/write files by path. Object storage is the choice when access is by key over HTTP.', NULL, 'build', 'object_store');
INSERT INTO public.node_roles VALUES ('serverless-function', 'Serverless Function', 'Serverless or edge-deployed function (AWS Lambda, Cloudflare Workers, Deno Deploy, etc.)', 'zap', '#ff9900', 'service', 'Services', false, NULL, '[]', '{"handler": {"type": "string", "label": "Handler", "default": "index.handler", "required": true, "description": "Function entry point"}, "runtime": {"type": "string", "label": "Runtime", "default": "nodejs20.x", "required": true, "description": "nodejs20.x, python3.11, etc."}, "timeout": {"type": "number", "label": "Timeout (seconds)", "default": 30, "description": "Max execution time"}, "triggers": {"type": "array", "label": "Event Triggers", "description": "API Gateway, S3, DynamoDB, etc."}, "memorySize": {"type": "number", "label": "Memory (MB)", "default": 128, "description": "RAM allocation (128-10240)"}, "environment": {"type": "object", "label": "Environment Variables", "description": "Key-value configuration"}}', '[]', '[]', 121, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.38638+00', NULL, '{edge,serverless,lambda,cloud-functions,workers,faas,compute,aws,azure,cloudflare,gcp,supabase,cloud-managed}', false, NULL, 'When you need stateless, event-driven compute that scales to zero. Covers both cloud functions (Lambda, Cloud Functions) and edge functions (Cloudflare Workers, Deno Deploy).', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('software-layer', 'Software Layer', 'Architectural layer grouping (presentation, business, data)', 'layers', '#475569', 'container', 'Logical', true, 'logical', '["backend-service", "cache", "database", "frontend-app", "scheduled-trigger", "vector-database", "worker"]', '{"layerType": {"type": "string", "label": "Layer Type", "default": "business", "description": "presentation, business, data, infrastructure, or domain"}, "allowedDependencies": {"type": "array", "label": "Allowed Dependencies", "description": "Layers this layer can depend on"}, "prohibitedDependencies": {"type": "array", "label": "Prohibited Dependencies", "description": "Layers this layer must NOT depend on"}}', '[]', '[]', 150, '2026-02-08 21:38:04.485552+00', '2026-08-30 12:07:22.38638+00', 'logical-boundary', '{logical-boundary}', false, NULL, 'Choose for architectural layers that enforce dependency direction (e.g., presentation → business → data). Examples: a "domain layer" containing pure business logic, a "persistence layer" wrapping database access. Unlike a Bounded Context (vertical slice), a Software Layer is a horizontal cross-cutting tier.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('game-client', 'Game Client', 'Game client application handling rendering, input, and local simulation', 'Gamepad2', '#f59e0b', 'icon', 'Game Development', false, NULL, '[]', '{}', '[{"name": "server_sync", "required": true, "direction": "in"}, {"name": "player_input", "required": true, "direction": "out"}]', '["event", "request_response"]', 460, '2026-05-11 04:11:59.813555+00', '2026-08-30 12:07:22.533535+00', NULL, '{}', false, NULL, 'Choose for the game itself — the playable build produced by a game engine project (Unity, Godot, Unreal). Bind the engine as the technology; gameplay systems, scenes, physics, and assets are this node''s implementation work. Pair with a game-server node for authoritative multiplayer (Nakama, Photon, or a custom server), and with ordinary backend/database nodes for accounts, leaderboards, and persistence.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('embedded-system', 'Embedded System', 'Embedded system boundary containing device, firmware, and sensor subsystems', 'cpu', '#0f172a', 'container', 'Logical', true, 'logical', '["backend-service", "database", "embedded-device", "firmware-service", "frontend-app", "vector-database", "worker"]', '{"systemType": {"type": "string", "label": "System Type", "default": "real-time", "description": "real-time, soft-real-time, general-purpose"}, "powerBudget": {"type": "string", "label": "Power Budget", "description": "Maximum power consumption (e.g., 10W)"}, "certifications": {"type": "array", "label": "Certifications", "description": "DO-178C, IEC 61508, ISO 26262, etc."}, "debugInterface": {"type": "string", "label": "Debug Interface", "default": "JTAG", "description": "JTAG, SWD, UART, none"}, "operatingTemperature": {"type": "string", "label": "Operating Temperature", "default": "-40C to 85C", "description": "Temperature range (e.g., -40C to 85C)"}}', '[]', '[]', 47, '2026-02-08 21:38:04.485552+00', '2026-08-30 12:07:22.38638+00', 'logical-boundary', '{}', false, NULL, 'Choose for grouping device, firmware, and sensor subsystems into a cohesive embedded system boundary. Examples: an IoT device containing MCU + sensors + firmware, a robotics subsystem with motor controllers. Unlike other logical groups, an Embedded System boundary implies hardware-software co-design.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('docker-swarm', 'Docker Swarm', 'Docker Swarm container orchestration cluster', 'layers', '#2496ed', 'container', 'Infrastructure', true, 'orchestration', '["application-module", "backend-service", "bounded-context", "cache", "database", "docker-container", "event-stream", "inference-service", "load-balancer", "message-broker", "microservice-boundary", "realtime-service", "scheduled-trigger", "search-engine", "service-mesh", "software-layer", "vector-database", "worker"]', '{"autolock": {"type": "boolean", "label": "Auto-lock", "default": true, "description": "Require unlock key on manager restart"}, "workerCount": {"type": "number", "label": "Worker Nodes", "default": 5, "description": "Number of worker nodes"}, "managerCount": {"type": "number", "label": "Manager Nodes", "default": 3, "description": "Number of manager nodes"}, "overlayNetworks": {"type": "array", "label": "Overlay Networks", "default": ["app-network"], "description": "Custom overlay networks"}}', '[]', '[]', 72, '2026-02-08 21:38:04.485552+00', '2026-08-30 12:07:22.38638+00', 'hosting', '{}', false, NULL, NULL, NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('vpc', 'VPC / Virtual Network', 'Cloud virtual private network boundary', 'cloud', '#1e40af', 'container', 'Infrastructure', true, 'infrastructure', '["api-gateway", "application-module", "auth-provider", "backend-service", "bounded-context", "cache", "cdn", "database", "docker-compose", "docker-container", "docker-swarm", "ecs-cluster", "event-stream", "graph-db", "inference-service", "k8s-cluster", "k8s-namespace", "load-balancer", "logging", "message-broker", "microservice-boundary", "ml-pipeline", "monitoring", "object-storage", "realtime-service", "scheduled-trigger", "search-engine", "serverless-function", "service-mesh", "software-layer", "subnet", "time-series-db", "vector-database", "worker"]', '{"tags": {"type": "object", "label": "Resource Tags", "description": "Key-value pairs for organization and billing"}, "region": {"type": "string", "label": "Region", "required": true, "description": "Geographic region (e.g., us-east-1)"}, "cidrBlock": {"type": "string", "label": "CIDR Block", "default": "10.0.0.0/16", "required": true, "description": "IP address range (e.g., 10.0.0.0/16)"}, "natGateway": {"type": "boolean", "label": "NAT Gateway", "default": false, "description": "Allow private subnets to access internet"}, "flowLogsEnabled": {"type": "boolean", "label": "Flow Logs", "default": false, "description": "Enable traffic flow logging"}, "internetGateway": {"type": "boolean", "label": "Internet Gateway", "default": true, "description": "Allow internet access"}, "enableDnsSupport": {"type": "boolean", "label": "DNS Support", "default": true, "description": "Enable DNS server"}, "enableDnsHostnames": {"type": "boolean", "label": "DNS Hostnames", "default": true, "description": "Allow instances to receive DNS hostnames"}}', '[]', '[]', 100, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.38638+00', 'hosting', '{infrastructure-container,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for network-isolated virtual private cloud boundaries. Examples: an AWS VPC containing your production subnets, a GCP VPC with custom IP ranges. A VPC contains subnets and defines network routing and security group boundaries.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('docker-compose', 'Docker Compose', 'Multi-container Docker application', 'layers', '#2496ed', 'container', 'Infrastructure', true, 'orchestration', '["api-gateway", "application-module", "auth-provider", "backend-service", "bounded-context", "cache", "database", "docker-container", "event-stream", "frontend-app", "graph-db", "inference-service", "load-balancer", "logging", "message-broker", "microservice-boundary", "ml-pipeline", "monitoring", "realtime-service", "scheduled-trigger", "search-engine", "service-mesh", "software-layer", "time-series-db", "vector-database", "worker", "object-storage", "serverless-function"]', '{"secrets": {"type": "array", "label": "Secrets", "description": "Secret management configuration"}, "version": {"type": "string", "label": "Compose Version", "default": "3.8", "description": "Docker Compose file version"}, "volumes": {"type": "array", "label": "Named Volumes", "description": "Persistent volume definitions"}, "networks": {"type": "array", "label": "Networks", "description": "Docker networks"}}', '[]', '[]', 112, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:24.245143+00', 'hosting', '{orchestration-container}', false, NULL, 'Choose for multi-container application stacks defined in a single compose file. Examples: a dev environment with app + database + redis, a CI test stack, a local microservice ensemble. Unlike a Kubernetes Cluster, Docker Compose is for simpler orchestration without production-grade scheduling.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('virtual-machine', 'Virtual Machine', 'Generic VM instance on any hypervisor', 'monitor', '#475569', 'container', 'Infrastructure', true, 'infrastructure', '["api-gateway", "application-module", "backend-service", "bounded-context", "cache", "database", "docker-compose", "docker-container", "event-stream", "graph-db", "k8s-cluster", "message-broker", "microservice-boundary", "ml-pipeline", "realtime-service", "scheduled-trigger", "search-engine", "service-mesh", "software-layer", "time-series-db", "vector-database", "worker"]', '{"diskGB": {"type": "number", "label": "Disk Size (GB)", "default": 100, "description": "Primary disk size"}, "osType": {"type": "string", "label": "OS Type", "default": "linux", "description": "linux, windows, or other"}, "cpuCores": {"type": "number", "label": "CPU Cores", "default": 4, "description": "Number of virtual CPUs"}, "diskType": {"type": "string", "label": "Disk Type", "default": "ssd", "description": "ssd, nvme, or hdd"}, "memoryGB": {"type": "number", "label": "Memory (GB)", "default": 16, "description": "RAM in gigabytes"}, "osVersion": {"type": "string", "label": "OS Version", "default": "Ubuntu 22.04 LTS", "description": "Operating system version"}, "hypervisor": {"type": "string", "label": "Hypervisor", "default": "vmware", "description": "vmware, hyper-v, kvm, xen, virtualbox"}}', '[]', '[]', 49, '2026-02-08 21:38:04.485552+00', '2026-08-30 12:07:22.38638+00', 'hosting', '{compute,vm,azure,cloud-managed}', false, NULL, 'Choose for generic virtual machine instances on any cloud or hypervisor. Examples: an EC2 instance running a legacy app, a GCE VM for a database, an Azure VM for a Windows service. Unlike containers, VMs provide full OS isolation and are suitable for stateful or legacy workloads.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('subnet', 'Subnet', 'Network subnet within a VPC', 'layers', '#1d4ed8', 'container', 'Infrastructure', true, 'infrastructure', '["api-gateway", "application-module", "auth-provider", "backend-service", "bounded-context", "cache", "database", "docker-container", "event-stream", "graph-db", "k8s-cluster", "load-balancer", "message-broker", "microservice-boundary", "object-storage", "realtime-service", "scheduled-trigger", "search-engine", "serverless-function", "service-mesh", "software-layer", "time-series-db", "vector-database", "worker"]', '{"cidrBlock": {"type": "string", "label": "CIDR Block", "required": true, "description": "IP address range for the subnet"}, "subnetType": {"type": "string", "label": "Subnet Type", "default": "public", "description": "public or private"}, "routeTableId": {"type": "string", "label": "Route Table ID", "description": "Associated route table"}, "availabilityZone": {"type": "string", "label": "Availability Zone", "required": true, "description": "Physical location (e.g., us-east-1a)"}, "autoAssignPublicIp": {"type": "boolean", "label": "Auto-assign Public IP", "default": false, "description": "Automatically assign public IPs"}}', '[]', '[]', 101, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.38638+00', 'hosting', '{infrastructure-container,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for network segments within a VPC that define availability zones and routing. Examples: a public subnet with internet gateway access, a private subnet for databases, a subnet per AZ for high availability. Subnets contain the actual compute resources (VMs, containers, functions).', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('k8s-cluster', 'Kubernetes Cluster', 'Kubernetes cluster boundary', 'box', '#326ce5', 'container', 'Infrastructure', true, 'orchestration', '["api-gateway", "application-module", "auth-provider", "backend-service", "bounded-context", "cache", "database", "event-stream", "graph-db", "inference-service", "k8s-namespace", "load-balancer", "logging", "message-broker", "microservice-boundary", "ml-pipeline", "monitoring", "realtime-service", "scheduled-trigger", "search-engine", "service-mesh", "software-layer", "time-series-db", "vector-database", "worker"]', '{"version": {"type": "string", "label": "Kubernetes Version", "default": "1.28", "required": true, "description": "Cluster version (e.g., 1.28)"}, "nodeType": {"type": "string", "label": "Node Instance Type", "default": "t3.medium", "description": "Instance type for nodes"}, "nodeCount": {"type": "number", "label": "Node Count", "default": 3, "required": true, "description": "Number of worker nodes"}, "monitoring": {"type": "string", "label": "Monitoring Stack", "default": "Prometheus", "description": "Prometheus, Datadog, etc."}, "networking": {"type": "string", "label": "CNI Plugin", "default": "calico", "description": "Network plugin (calico, flannel, weave)"}, "certManager": {"type": "boolean", "label": "Cert Manager", "default": true, "description": "Automatic TLS certificate management"}, "rbacEnabled": {"type": "boolean", "label": "RBAC Enabled", "default": true, "description": "Role-based access control"}, "ingressController": {"type": "string", "label": "Ingress Controller", "default": "nginx", "description": "nginx, traefik, or istio"}}', '[]', '[]', 110, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.38638+00', 'hosting', '{orchestration-container,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for Kubernetes cluster boundaries that host namespaces and workloads. Examples: an EKS cluster for production services, a GKE cluster for the data team, a self-managed k8s cluster on bare metal. A Kubernetes Cluster contains Namespaces which contain services.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('k8s-namespace', 'Kubernetes Namespace', 'Kubernetes namespace isolation boundary', 'folder', '#326ce5', 'container', 'Infrastructure', true, 'orchestration', '["api-gateway", "application-module", "auth-provider", "backend-service", "bounded-context", "cache", "database", "event-stream", "graph-db", "inference-service", "load-balancer", "logging", "message-broker", "microservice-boundary", "ml-pipeline", "monitoring", "object-storage", "realtime-service", "scheduled-trigger", "search-engine", "service-mesh", "software-layer", "time-series-db", "vector-database", "worker"]', '{"cpuLimit": {"type": "string", "label": "CPU Limit", "default": "10", "description": "Max CPU cores (e.g., 10)"}, "podLimit": {"type": "number", "label": "Pod Limit", "default": 100, "description": "Maximum number of pods"}, "cpuRequest": {"type": "string", "label": "CPU Request", "default": "2", "description": "Total CPU requests (e.g., 2)"}, "limitRanges": {"type": "boolean", "label": "Limit Ranges", "default": true, "description": "Set default per-pod resource limits"}, "memoryLimit": {"type": "string", "label": "Memory Limit", "default": "20Gi", "description": "Max memory (e.g., 20Gi)"}, "rbacEnabled": {"type": "boolean", "label": "RBAC", "default": true, "description": "Role-based access control"}, "memoryRequest": {"type": "string", "label": "Memory Request", "default": "4Gi", "description": "Total memory requests (e.g., 4Gi)"}, "resourceQuota": {"type": "boolean", "label": "Resource Quota", "default": true, "description": "Enforce resource limits"}, "networkPolicies": {"type": "array", "label": "Network Policies", "default": ["deny-all-ingress"], "description": "Network security policies"}}', '[]', '[]', 111, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.38638+00', 'hosting', '{orchestration-container,aws,cloud-managed}', false, NULL, 'Choose for Kubernetes namespace isolation within a cluster. Examples: a "production" namespace, a "staging" namespace, a per-team namespace for multi-tenancy. Namespaces provide resource quotas, network policies, and RBAC boundaries within a cluster.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('worker', 'Background Worker', 'Background worker service that consumes jobs and events to perform domain work', 'cog', '#f59e0b', 'service', 'Services', false, NULL, '[]', '{}', '[{"name": "Queue In", "direction": "in"}, {"name": "Database", "direction": "out"}, {"name": "Internal Dependency", "direction": "out"}, {"name": "Service Import", "direction": "in"}]', '["event"]', 11, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{compute,async,background,aws,gcp,cloud-managed}', false, NULL, 'Choose for background processes that consume jobs from queues or react to events without direct client-facing HTTP. Examples: an image resizer pulling from SQS, a payment processor consuming Kafka events, a PDF generator draining a Redis queue. Unlike a Backend Service, a Worker has no HTTP endpoint -- it pulls or subscribes to work.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('docker-container', 'Docker Container', 'Single Docker container runtime', 'box', '#2496ed', 'container', 'Infrastructure', true, 'runtime', '["api-gateway", "auth-provider", "backend-service", "cache", "database", "frontend-app", "graph-db", "inference-service", "message-broker", "realtime-service", "scheduled-trigger", "search-engine", "time-series-db", "vector-database", "worker"]', '{"ports": {"type": "array", "label": "Exposed Ports", "description": "Container ports to expose"}, "volumes": {"type": "array", "label": "Volume Mounts", "description": "Persistent storage paths"}, "cpuLimit": {"type": "string", "label": "CPU Limit", "description": "Max CPU (e.g., 1.5 cores)"}, "baseImage": {"type": "string", "label": "Base Image", "required": true, "description": "Docker image (e.g., node:20-alpine)"}, "memoryLimit": {"type": "string", "label": "Memory Limit", "description": "Max memory (e.g., 512m, 2g)"}, "restartPolicy": {"type": "string", "label": "Restart Policy", "default": "unless-stopped", "description": "always, unless-stopped, on-failure"}, "environmentVariables": {"type": "object", "label": "Environment Variables", "description": "Key-value configuration pairs"}}', '[]', '[]', 120, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.38638+00', 'hosting', '{aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for single containerized application instances. Examples: a Docker container running your API server, a sidecar container for log collection, a container in an ECS task definition. This represents one running container image.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('config-store', 'Configuration Store', 'Centralized runtime configuration and feature flags, read by services at startup.', 'sliders', '#7c3aed', 'service', 'Networking', false, NULL, '[]', '{}', '[{"name": "read", "direction": "in"}]', '[]', 36, '2026-08-30 12:07:22.38638+00', '2026-08-30 12:07:22.38638+00', NULL, '{configuration,feature-flags,settings}', false, NULL, 'Choose for centralized non-secret configuration and feature flags. Secrets belong in a secret manager; this is the store services read ordinary settings from.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('key-management', 'Key Management Service', 'Manages cryptographic keys and performs encrypt/decrypt/sign operations.', 'key', '#b45309', 'service', 'Networking', false, NULL, '[]', '{}', '[{"name": "crypto", "direction": "in"}]', '[]', 37, '2026-08-30 12:07:22.38638+00', '2026-08-30 12:07:22.38638+00', NULL, '{kms,encryption,keys,crypto}', false, NULL, 'Choose when the system manages encryption keys or delegates crypto operations. A KMS is neither an auth provider nor a secret store — it holds keys, not credentials.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('bi-analytics', 'BI & Analytics', 'Governed semantic layer and business-intelligence reporting over warehouse data.', 'bar-chart-3', '#0284c7', 'service', 'External', false, NULL, '[]', '{}', '[{"name": "query", "direction": "out"}]', '[]', 95, '2026-08-30 12:07:22.38638+00', '2026-08-30 12:07:22.38638+00', NULL, '{bi,analytics,reporting,semantic-layer}', false, NULL, 'Choose for a governed BI or semantic layer that reads from a warehouse. Distinct from monitoring, which watches the system rather than the business.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('ci-cd-pipeline', 'CI/CD Pipeline', 'Automated build, test and deployment pipeline triggered by commits, tags or schedules.', 'git-merge', '#f59e0b', 'service', 'Automation', false, NULL, '[]', '{"stages": {"type": "multiselect", "label": "Stages", "options": ["build", "test", "security-scan", "deploy-staging", "deploy-production", "release"], "description": "What this pipeline actually does. One pipeline definition is one node — CI and CD stages of the same workflow are not separate nodes."}}', '[{"name": "trigger-in", "direction": "in"}, {"name": "output-out", "direction": "out"}]', '[]', 50, '2026-08-30 12:07:22.38638+00', '2026-08-30 12:07:22.38638+00', NULL, '{ci,cd,automation,build,deploy}', false, NULL, 'Choose for automated build/test/deploy workflows triggered by commits, tags or schedules. Select which stages it runs rather than modelling CI and CD as separate nodes.', NULL, 'engine', 'service');
INSERT INTO public.node_roles VALUES ('network-firewall', 'Network Firewall', 'Network-layer traffic filtering and egress control (L3/L4 rules, threat intelligence).', 'shield', '#dc2626', 'service', 'Networking', false, NULL, '[]', '{}', '[{"name": "ingress", "direction": "in"}, {"name": "egress", "direction": "out"}]', '[]', 35, '2026-08-30 12:07:22.38638+00', '2026-08-30 12:07:22.38638+00', NULL, '{network,security,firewall,egress}', false, NULL, 'Choose for network-layer filtering and egress control across a VPC or subnet. Distinct from a WAF, which inspects HTTP application traffic.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('webhook-handler', 'Webhook Handler', 'HTTP callback endpoint that receives and processes external event notifications', 'Webhook', '#f59e0b', 'icon', 'External', false, NULL, '[]', '{}', '[{"name": "inbound", "required": true, "direction": "in"}, {"name": "processed", "required": false, "direction": "out"}]', '["request_response", "event"]', 260, '2026-05-11 04:10:11.941145+00', '2026-08-30 12:07:22.409228+00', NULL, '{http,callback,events,integration}', false, NULL, 'Choose for HTTP endpoints that receive inbound event notifications from external services. Examples: a Stripe payment confirmation endpoint, a GitHub push event receiver, a Twilio SMS callback. Unlike a Backend Service, a Webhook Handler is purpose-built for a single inbound event contract with idempotency and retry handling.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('azure', 'Azure', 'Microsoft Azure cloud platform providing compute, storage, messaging, and database services', 'cloud', '#0078D4', 'container', 'Platform', true, 'infrastructure', '{"natures": ["build", "call", "engine", "integrate"], "roleIds": [], "providers": ["azure"], "interfaceKinds": ["auth", "data", "event_bus", "object_store", "queue", "service", "telemetry"]}', '{"iacTool": {"type": "enum", "label": "IaC tool", "options": ["terraform", "opentofu", "pulumi", "provider-native", "cdk"], "description": "The infrastructure-as-code tool EVERY declarative node in this platform is provisioned with — inherited by contained nodes and named verbatim in their task packets. Terraform is the ecosystem default (BSL-licensed since 2023; OpenTofu is the Linux Foundation fork under MPL); provider-native = CloudFormation/Bicep/Config-Connector. Leave unset only if undecided — packets will then instruct the AI to confirm rather than assume"}, "tagPolicy": {"type": "boolean", "label": "Enforce resource tags", "default": true, "description": "project/env/owner tags on every child resource — IaC-enforced, reads in Cost Management"}, "environment": {"type": "enum", "label": "Environment", "default": "production", "options": ["dev", "staging", "production"], "description": "Drives sizing/HA defaults children inherit"}, "budgetAlerts": {"type": "boolean", "label": "Budget alerts", "default": true, "description": "Cost Management budget wiring (IaC); the notification confirm is a console step"}, "primaryRegion": {"type": "string", "label": "Primary region", "default": "eastus", "description": "Default region children deploy into unless they say otherwise — Bicep/Terraform reads this"}, "resourceGroup": {"type": "string", "label": "Default resource group", "description": "Resource group children are created in unless they override — the unit of lifecycle and RBAC in Azure"}, "identityBaseline": {"type": "enum", "label": "Identity baseline", "default": "managed-identity-preferred", "options": ["managed-identity-preferred", "service-principals", "workload-identity-federation"], "description": "How children authenticate to each other. Managed identity removes stored secrets entirely — the Entra ID setup is a CONSOLE step, the role assignments are IaC"}, "policyAssignment": {"type": "string", "label": "Azure Policy initiative", "description": "Policy initiative assigned at this scope (e.g. CIS, custom deny-public-IP). Children must be provisioned to satisfy it or deployment fails"}, "subscriptionName": {"type": "string", "label": "Subscription", "description": "Which Azure subscription/environment this container represents (e.g. myapp-prod). Children deploy into it"}}', '[]', '[]', 5, '2026-05-13 02:08:25.219645+00', '2026-08-30 12:07:22.439057+00', 'hosting', '{cloud,platform,azure,functions,cosmos-db,blob-storage,service-bus,event-grid,microsoft}', false, 'azure', 'Choose when your architecture is built on Microsoft Azure and you want to represent the platform container with its managed capabilities (Functions, Cosmos DB, Blob Storage, Service Bus, Event Grid). Drag this onto the canvas to set up an Azure-centric deployment context.', NULL, 'host', 'service');
INSERT INTO public.node_roles VALUES ('actuator', 'Actuator', 'Physical actuator executing control commands (motors, valves, relays, displays)', 'Cog', '#f97316', 'icon', 'Hardware', false, NULL, '[]', '{}', '[{"name": "commands", "required": true, "direction": "in"}, {"name": "status", "required": false, "direction": "out"}]', '["ipc", "event"]', 410, '2026-05-11 04:11:37.367043+00', '2026-08-30 12:07:22.409228+00', NULL, '{}', false, NULL, 'Choose for physical output devices that execute control commands. Examples: a servo motor, a relay switch, an LED display, a hydraulic valve. Actuators receive commands from Microcontrollers or control systems.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('realtime-service', 'Realtime Service', 'Service managing persistent connections, real-time channels, and live data streams', 'Radio', '#10b981', 'icon', 'Services', false, NULL, '[]', '{}', '[{"name": "clients", "direction": "in"}, {"name": "data-source", "direction": "out"}]', '["event", "event"]', 15, '2026-05-11 03:51:52.288378+00', '2026-08-30 12:07:22.409228+00', NULL, '{networking,realtime,api}', false, NULL, 'Choose for services maintaining persistent bidirectional connections for live data push. Examples: a chat server over WebSockets, a live stock ticker via SSE, a collaborative editor with CRDTs. Unlike a Backend Service (request-response), a Realtime Service holds open connections and pushes data proactively.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('cdn', 'CDN', 'Content delivery network edge node', 'globe', '#0ea5e9', 'service', 'Networking', false, NULL, '[]', '{}', '[{"name": "Origin", "direction": "in"}, {"name": "Edge", "direction": "out"}]', '["request_response"]', 13, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{cdn,cloudfront,edge,distribution,caching,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for distributing static assets globally to reduce latency. Examples: CloudFront serving images, Cloudflare caching API responses, Fastly accelerating a video platform. Unlike a Load Balancer, a CDN caches content at edge locations and serves it without hitting your origin.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('graph-db', 'Graph Database', 'Graph-based data storage for relationship queries', 'share-2', '#ea580c', 'service', 'Database', false, NULL, '[]', '{"host": {"type": "string", "label": "Host", "default": "localhost", "description": "Database host address"}, "port": {"type": "number", "label": "Port", "default": 7687, "description": "Database port number"}, "nodeLabels": {"type": "array", "label": "Node Labels", "description": "Graph node labels / vertex types"}, "queryLanguage": {"type": "string", "label": "Query Language", "default": "cypher", "description": "Primary query language (e.g., Cypher, Gremlin, SPARQL)"}, "relationshipTypes": {"type": "array", "label": "Relationship Types", "description": "Edge / relationship types in the graph"}}', '[{"name": "Query", "direction": "in"}]', '["request_response"]', 34, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{data-store}', false, NULL, 'Choose for relationship-first data where traversals and pattern matching are primary access patterns. Examples: Neo4j for social networks, knowledge graphs, or fraud detection. Unlike a relational Database, a Graph Database excels at multi-hop traversals without expensive JOINs.', NULL, 'build', 'data');
INSERT INTO public.node_roles VALUES ('time-series-db', 'Time Series DB', 'Optimized storage for time-stamped data', 'trending-up', '#d97706', 'service', 'Database', false, NULL, '[]', '{"host": {"type": "string", "label": "Host", "default": "localhost", "description": "Database host address"}, "port": {"type": "number", "label": "Port", "default": 8086, "description": "Database port number"}, "precision": {"type": "string", "label": "Precision", "default": "ns", "description": "Timestamp precision (ns, us, ms, s)"}, "measurements": {"type": "array", "label": "Measurements", "description": "Time-series measurements / metrics collected"}, "retentionPolicy": {"type": "string", "label": "Retention Policy", "description": "Data retention duration (e.g., 30d, 1y, infinite)"}}', '[{"name": "Write", "direction": "in"}, {"name": "Query", "direction": "out"}]', '["request_response"]', 33, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{data-store}', false, NULL, 'Choose for metrics, IoT readings, and any data naturally indexed by timestamp. Examples: InfluxDB for server metrics, TimescaleDB for financial tick data. Unlike a general Database, a Time Series DB is optimized for high-ingest append workloads and time-windowed aggregations.', NULL, 'build', 'data');
INSERT INTO public.node_roles VALUES ('backend-service', 'Backend Service', 'Server-side application or microservice', 'server', '#10b981', 'service', 'Services', false, NULL, '[]', '{}', '[{"name": "HTTP In", "direction": "in"}, {"name": "Database", "direction": "out"}, {"name": "Cache", "direction": "out"}, {"name": "Module Dependency", "direction": "out"}, {"name": "Service Import", "direction": "in"}]', '["request_response", "event"]', 10, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{compute,backend,aws,azure,gcp,cloud-managed}', false, NULL, 'Choose for long-running server applications that expose HTTP endpoints and contain core business logic. Examples: a REST API powering a mobile app, a GraphQL server aggregating multiple data sources, a monolithic Rails or Express app. Unlike an Edge Function, a Backend Service runs in a persistent process with full runtime access (file system, long connections, background threads).', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('database', 'Database', 'Persistent data storage (relational or document)', 'database', '#f59e0b', 'service', 'Database', false, NULL, '[]', '{"host": {"type": "string", "label": "Host", "default": "localhost", "description": "Database host address"}, "port": {"type": "number", "label": "Port", "description": "Database port number"}, "engine": {"type": "string", "label": "Database Engine", "description": "Specific engine or version (e.g., PostgreSQL 16, MongoDB 7)"}, "tables": {"type": "array", "label": "Tables / Collections", "description": "Database tables (relational) or collections (NoSQL) with their key fields"}, "replication": {"type": "string", "label": "Replication", "description": "Replication strategy (e.g., primary-replica, multi-master)"}, "connectionPooling": {"type": "boolean", "label": "Connection Pooling", "default": true, "description": "Whether connection pooling is enabled"}}', '[{"name": "Query", "direction": "in"}, {"name": "Replication", "direction": "out"}]', '["data_read"]', 30, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{data-store,relational,sql,postgres,mysql,nosql,document,rds,cloud-sql,dynamodb,cosmos-db,firestore,aws,azure,firebase,gcp,supabase,cloud-managed}', false, NULL, 'Choose for persistent structured data storage (relational or document). Examples: PostgreSQL for transactional data, MongoDB for flexible document schemas, MySQL for a WordPress backend. This is the default choice when your service needs durable, queryable data with ACID guarantees.', NULL, 'build', 'data');
INSERT INTO public.node_roles VALUES ('search-engine', 'Search Engine', 'Full-text search and analytics engine', 'search', '#fbbf24', 'service', 'Database', false, NULL, '[]', '{"host": {"type": "string", "label": "Host", "default": "localhost", "description": "Search engine host address"}, "port": {"type": "number", "label": "Port", "default": 9200, "description": "Search engine port number"}, "indices": {"type": "array", "label": "Indices", "description": "Search indices and their mapping fields"}, "analyzer": {"type": "string", "label": "Default Analyzer", "description": "Default text analyzer for indexing"}}', '[{"name": "Index", "direction": "in"}, {"name": "Search", "direction": "out"}]', '["request_response"]', 31, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{search,elasticsearch,opensearch,full-text,indexing,aws,cloud-managed}', false, NULL, 'Choose for full-text search, fuzzy matching, and analytics over large document collections. Examples: Elasticsearch powering product search, OpenSearch for log analytics, Algolia for autocomplete. Unlike a Database, a Search Engine is optimized for read-heavy, text-matching workloads rather than transactional writes.', NULL, 'build', 'data');
INSERT INTO public.node_roles VALUES ('mobile-device', 'Mobile Device', 'Physical mobile device (iOS or Android) that hosts native apps, local databases, background workers, and on-device services.', 'smartphone', '#1e293b', 'container', 'Infrastructure', true, 'runtime', '["actuator", "backend-service", "cache", "database", "frontend-app", "inference-service", "mobile-app", "sensor", "vector-database", "worker"]', '{"platform": {"type": "string", "label": "Platform", "default": "ios", "description": "ios, android, or cross-platform"}, "osMinVersion": {"type": "string", "label": "Minimum OS Version", "default": "16.0", "description": "Minimum supported OS version (e.g., 16.0 for iOS, 13 for Android)"}, "biometricAuth": {"type": "boolean", "label": "Biometric Auth", "default": false, "description": "Use Face ID / Touch ID / Fingerprint"}, "deviceCategory": {"type": "string", "label": "Device Category", "default": "phone", "description": "phone, tablet, watch, or tv"}, "offlineCapable": {"type": "boolean", "label": "Offline Capable", "default": true, "description": "App works without network connectivity"}, "pushNotifications": {"type": "boolean", "label": "Push Notifications", "default": true, "description": "Enable push notification support (APNs/FCM)"}}', '[{"name": "API Call", "direction": "out"}, {"name": "Push Notification", "direction": "in"}]', '["request_response", "event"]', 5, '2026-02-22 17:09:28.092748+00', '2026-08-30 12:07:22.409228+00', 'hosting', '{client-facing,ui,offline-capable}', false, NULL, 'Choose for the physical mobile device hardware that hosts native apps. Examples: an iPhone running your iOS app, an Android tablet hosting your fleet management app. Unlike a Mobile App (the software), a Mobile Device represents the physical hardware and its OS environment.', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('desktop-app', 'Desktop Application', 'Native desktop application (Electron, Tauri, etc.)', 'monitor', '#64748b', 'container', 'Services', false, NULL, '[]', '{"framework": {"type": "string", "label": "Framework", "default": "electron", "description": "electron, tauri, maui"}, "platforms": {"type": "array", "label": "Target Platforms", "default": ["windows", "macos", "linux"], "description": "windows, macos, linux, ios, android"}, "autoUpdater": {"type": "boolean", "label": "Auto Updater", "default": true, "description": "Enable automatic updates"}, "signingEnabled": {"type": "boolean", "label": "Code Signing", "default": true, "description": "Sign executables for distribution"}}', '[{"name": "IPC", "direction": "in"}, {"name": "API Call", "direction": "out"}]', '["request_response", "ipc"]', 4, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.409228+00', NULL, '{client-facing,ui}', false, NULL, 'Choose for native desktop applications distributed as installable binaries. Examples: a VS Code-like editor in Electron, a Rust-powered system tool in Tauri, a .NET MAUI enterprise app. Unlike a Frontend Application, a Desktop App has full OS access (file system, system tray, native menus).', NULL, 'build', 'service');
INSERT INTO public.node_roles VALUES ('vercel', 'Vercel', 'Managed hosting platform for frontend-first apps: git-push deploys, preview environments per PR, Vercel Functions (Fluid Compute), edge network and first-party Next.js support.', 'Cloud', '#000000', 'container', 'Platform', true, 'infrastructure', '{"natures": ["build", "call"], "roleIds": [], "providers": ["vercel"], "interfaceKinds": ["data", "service", "telemetry"]}', '{"team": {"type": "string", "label": "Team / scope", "description": "Vercel team the project lives under (billing + access boundary)"}, "environment": {"type": "enum", "label": "Environment", "default": "production", "options": ["production", "preview", "development"], "description": "Scopes contained nodes — preview deployments are per-PR by default"}}', '[]', '[]', 7, '2026-08-30 12:07:22.195594+00', '2026-08-30 12:07:22.439057+00', 'hosting', '{platform,hosting,paas,vercel,nextjs,frontend,preview-deploys,serverless}', false, 'vercel', 'Managed hosting platform that deploys and runs your app straight from the repository. Choose when the product is frontend-first (Next.js especially): git-push deploys, per-PR preview environments and Vercel Functions (Fluid Compute — the deprecated Edge Functions runtime is being migrated out) cover the app tier without infrastructure work.', NULL, 'host', 'service');
INSERT INTO public.node_roles VALUES ('netlify', 'Netlify', 'Managed hosting platform for static-first sites and Jamstack apps: git deploys, deploy previews, Netlify Functions, forms and edge handlers.', 'Cloud', '#00C7B7', 'container', 'Platform', true, 'infrastructure', '{"natures": ["build", "call"], "roleIds": [], "providers": ["netlify"], "interfaceKinds": ["service", "telemetry"]}', '{"team": {"type": "string", "label": "Team", "description": "Netlify team (billing + access boundary)"}, "environment": {"type": "enum", "label": "Environment", "default": "production", "options": ["production", "deploy-preview", "branch-deploy"]}}', '[]', '[]', 8, '2026-08-30 12:07:22.195594+00', '2026-08-30 12:07:22.439057+00', 'hosting', '{platform,hosting,paas,netlify,jamstack,static,deploy-previews}', false, 'netlify', 'Managed hosting platform that deploys and runs your site straight from the repository. Choose for static-first/Jamstack builds: git deploys, deploy previews, Netlify Functions and forms — strongest when most of the product is prerendered.', NULL, 'host', 'service');
INSERT INTO public.node_roles VALUES ('railway', 'Railway', 'Managed app platform that runs full stacks from git or Docker images: services, managed Postgres/Redis/MySQL, cron, private networking and per-environment config.', 'Cloud', '#853BCE', 'container', 'Platform', true, 'infrastructure', '{"natures": ["build", "call", "engine"], "roleIds": [], "providers": ["railway"], "interfaceKinds": ["data", "queue", "service", "telemetry"]}', '{"region": {"type": "string", "label": "Region", "description": "Deployment region for contained services"}, "environment": {"type": "enum", "label": "Environment", "default": "production", "options": ["production", "staging", "pr-environments"], "description": "Railway environments scope every contained service''s config"}}', '[]', '[]', 9, '2026-08-30 12:07:22.195594+00', '2026-08-30 12:07:22.439057+00', 'hosting', '{platform,hosting,paas,railway,postgres,docker,full-stack}', false, 'railway', 'Managed app platform that runs your full stack — services plus managed databases — from git or Docker images. Choose when a product team wants backend services, Postgres/Redis and cron in one place with per-environment config and no cloud-console overhead.', NULL, 'host', 'service');
INSERT INTO public.node_roles VALUES ('render', 'Render', 'Managed app platform: web services, background workers, cron jobs, managed Postgres/Redis (Key Value), static sites and preview environments.', 'Cloud', '#46E3B7', 'container', 'Platform', true, 'infrastructure', '{"natures": ["build", "call", "engine"], "roleIds": [], "providers": ["render"], "interfaceKinds": ["data", "queue", "service", "telemetry"]}', '{"region": {"type": "string", "label": "Region", "description": "Region for contained services and databases"}, "environment": {"type": "enum", "label": "Environment", "default": "production", "options": ["production", "preview"]}}', '[]', '[]', 10, '2026-08-30 12:07:22.195594+00', '2026-08-30 12:07:22.439057+00', 'hosting', '{platform,hosting,paas,render,postgres,workers,cron}', false, 'render', 'Managed app platform that runs web services, workers, cron and managed databases from your repository. Choose as the Heroku-successor lane: boring deploys for a conventional web app + worker + Postgres stack, with preview environments.', NULL, 'host', 'service');
INSERT INTO public.node_roles VALUES ('fly-io', 'Fly.io', 'App platform that runs Docker images as Fly Machines (micro-VMs) in regions close to users: global app placement, volumes, private networking (WireGuard), managed Postgres.', 'Cloud', '#7B3BE2', 'container', 'Platform', true, 'infrastructure', '{"natures": ["build", "call"], "roleIds": [], "providers": ["fly-io"], "interfaceKinds": ["data", "queue", "service", "telemetry"]}', '{"environment": {"type": "enum", "label": "Environment", "default": "production", "options": ["production", "staging"]}, "primaryRegion": {"type": "string", "label": "Primary region", "default": "iad", "description": "Fly region code (iad, fra, syd…) — placement IS the product; contained nodes inherit it"}}', '[]', '[]', 11, '2026-08-30 12:07:22.195594+00', '2026-08-30 12:07:22.439057+00', 'hosting', '{platform,hosting,paas,fly,machines,micro-vms,regions,docker}', false, 'fly-io', 'App platform that runs your Docker images as micro-VMs placed in regions near your users. Choose when latency/geography is part of the product (multi-region apps, per-region state) or when you want VM-level control with PaaS-level ergonomics — fly.toml is the deployment contract.', NULL, 'host', 'service');
INSERT INTO public.node_roles VALUES ('gcp', 'Google Cloud', 'Google Cloud Platform providing compute, storage, messaging, and database services', 'cloud', '#4285F4', 'container', 'Platform', true, 'infrastructure', '{"natures": ["build", "call", "engine", "integrate"], "roleIds": [], "providers": ["gcp", "firebase"], "interfaceKinds": ["auth", "data", "event_bus", "object_store", "queue", "service", "telemetry"]}', '{"folder": {"type": "string", "label": "Folder / org path", "description": "Where the project sits in the resource hierarchy — org policies inherit down from it"}, "iacTool": {"type": "enum", "label": "IaC tool", "options": ["terraform", "opentofu", "pulumi", "provider-native", "cdk"], "description": "The infrastructure-as-code tool EVERY declarative node in this platform is provisioned with — inherited by contained nodes and named verbatim in their task packets. Terraform is the ecosystem default (BSL-licensed since 2023; OpenTofu is the Linux Foundation fork under MPL); provider-native = CloudFormation/Bicep/Config-Connector. Leave unset only if undecided — packets will then instruct the AI to confirm rather than assume"}, "projectId": {"type": "string", "label": "Project ID", "description": "The GCP project children are created in (e.g. myapp-prod-1234). In GCP the PROJECT is the primary isolation and billing boundary, not the account"}, "environment": {"type": "enum", "label": "Environment", "default": "production", "options": ["dev", "staging", "production"], "description": "Drives sizing/HA defaults children inherit"}, "labelPolicy": {"type": "boolean", "label": "Enforce resource labels", "default": true, "description": "project/env/owner LABELS (GCP calls them labels, not tags) on every child — reads in billing export"}, "orgPolicies": {"type": "boolean", "label": "Org policy constraints", "default": true, "description": "Constraints like domain-restricted sharing and no-external-IP inherit to every child — IaC must satisfy them or provisioning fails"}, "budgetAlerts": {"type": "boolean", "label": "Budget alerts", "default": true, "description": "Billing budget + Pub/Sub notification wiring (IaC); enabling the billing export is a console step"}, "primaryRegion": {"type": "string", "label": "Primary region", "default": "us-central1", "description": "Default region children deploy into unless they say otherwise — Terraform reads this"}, "identityBaseline": {"type": "enum", "label": "Identity baseline", "default": "workload-identity-federation", "options": ["workload-identity-federation", "per-service-service-accounts", "default-compute-sa"], "description": "Workload Identity Federation avoids downloaded service-account keys entirely. The default compute SA is over-privileged and should never be the answer for production"}}', '[]', '[]', 6, '2026-05-13 02:08:25.219645+00', '2026-08-30 12:07:22.439057+00', 'hosting', '{cloud,platform,gcp,cloud-functions,cloud-sql,cloud-storage,pub-sub,cloud-run,google}', false, 'gcp', 'Choose when your architecture is built on Google Cloud Platform and you want to represent the platform container with its managed capabilities (Cloud Functions, Cloud SQL, Cloud Storage, Pub/Sub, Cloud Run). Drag this onto the canvas to set up a GCP-centric deployment context.', NULL, 'host', 'service');
INSERT INTO public.node_roles VALUES ('service-mesh', 'Service Mesh', 'Service-to-service traffic infrastructure (mTLS, retries, traffic splitting, telemetry) installed into a cluster and configured declaratively. Model it as a node placed inside the cluster it is installed into; services keep their normal edges — mesh policies are this node''s own deliverable.', 'network', '#6366f1', 'service', 'Networking', false, NULL, '[]', '{"mtls": {"type": "boolean", "label": "mTLS", "default": true, "description": "Mutual TLS between services"}, "tracing": {"type": "boolean", "label": "Distributed Tracing", "default": true, "description": "Jaeger/Zipkin integration"}, "loadBalancing": {"type": "string", "label": "Load Balancing", "default": "round-robin", "description": "round-robin, least-conn, random"}, "circuitBreaker": {"type": "boolean", "label": "Circuit Breaker", "default": true, "description": "Fault tolerance pattern"}, "implementation": {"type": "string", "label": "Implementation", "default": "istio", "description": "istio, linkerd, consul"}}', '[{"name": "Sidecar In", "direction": "in"}, {"name": "Sidecar Out", "direction": "out"}]', '["request_response"]', 26, '2026-02-06 23:27:08.605764+00', '2026-08-30 12:07:22.533535+00', NULL, '{logical-boundary}', false, NULL, 'Choose for service-to-service communication infrastructure that handles mTLS, observability, and traffic management. Examples: Istio for microservice security, Linkerd for lightweight service mesh, Kong Mesh for API traffic. Unlike a Load Balancer (L4/L7 routing), a Service Mesh manages inter-service communication policies.', NULL, 'build', 'service');

