INSERT INTO public.deployment_targets VALUES ('kubernetes-pod', 'Kubernetes Pod', 'Kubernetes pod execution', 'box', '["backend-service", "worker", "database", "cache", "message-broker"]', '{}', 12, '2026-02-06 23:50:51.037528+00');
INSERT INTO public.deployment_targets VALUES ('static-hosting', 'Static Hosting', 'Static file hosting (S3, Netlify, Vercel)', 'upload-cloud', '["static-site", "frontend-app", "cdn"]', '{}', 13, '2026-02-06 23:50:51.037528+00');
