INSERT INTO public.technology_catalog VALUES ('pusher', 'Pusher', NULL, '#6b7280', '["realtime-service"]', '{"purpose": "Managed realtime messaging (Channels) with a famously simple API: public/private/presence channels, client events, broad SDK coverage. STATUS NOTE: operating but stagnant — no significant new functionality since the 2020 Bird/MessageBird acquisition. Fine for modest-volume realtime (notifications, live dashboards, light chat); for delivery guarantees, history or large scale prefer Ably, or soketi for a self-hosted Pusher-protocol server (drop-in SDK compatibility).", "configMode": "external", "provenance": {"notes": "Phase B9 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["pusher-js", "server SDK trigger()", "channel auth endpoint", "presence channels", "soketi (self-hosted compatible)"], "antiPatterns": ["Treating Channels as a source of truth — no persistence, no replay; state lives in your database", "Public channels carrying private data because auth setup was skipped", "Choosing Pusher for a NEW build that already needs history, guaranteed delivery or exactly-once — that is the Ably/soketi fork in the road"], "apiReference": {"areas": {"webhooks": {"endpoints": ["Channel existence / presence webhooks (channel_occupied/vacated, member_added/removed) — verify the X-Pusher-Signature HMAC", "Use occupancy webhooks to start/stop upstream work so you do not publish into empty rooms"]}, "channel-auth": {"endpoints": ["`POST /pusher/auth` (your endpoint) — signs private-/presence-channel subscriptions with the app secret; wire pusher-js authEndpoint to it", "Presence auth returns channel_data (user_id + user_info) — this is where identity enters the channel"]}, "server-publish": {"endpoints": ["Server SDK: pusher.trigger(channel, event, data) — the whole publish surface; batch trigger for multi-channel fan-out", "Payload limit ~10KB — send references (ids), have clients fetch the data from your API"]}}, "docsUrl": "https://pusher.com/docs/channels"}, "bestPractices": ["Private channels for anything user-specific — the auth endpoint signs channel subscriptions per user", "Presence channels for member lists; keep presence payloads tiny (id + name, not profiles)", "Publish from the server (trigger) — client events only for ephemeral peer signals (typing indicators)", "Design channels so a missed message is recoverable from your API — Channels has no history/replay"], "sdkInitPattern": "import Pusher from ''pusher'';\n\nconst pusher = new Pusher({\n  appId: process.env.PUSHER_APP_ID,\n  key: process.env.PUSHER_KEY,        // client-visible\n  secret: process.env.PUSHER_SECRET,  // server-only\n  cluster: process.env.PUSHER_CLUSTER,\n  useTLS: true,\n});\nawait pusher.trigger(`private-user-${userId}`, ''order-updated'', { orderId });", "securityGuidance": "The app key is client-visible; the secret signs everything and never leaves the server. Use private- or presence- channels for anything user-specific — your channel-auth endpoint decides who may subscribe, so authorize against the authenticated session there (naming a channel is not a capability). Validate webhook signatures from Pusher before trusting channel-vacated/occupied events, and keep payloads reference-not-secret: every subscriber of a channel sees every event on it.", "setupInstructions": [{"url": "https://dashboard.pusher.com/", "type": "dashboard_config", "title": "Create Pusher App", "required": true, "instructions": "In the Pusher dashboard, create a new Channels app. Select your preferred cluster (closest to your users). Note the App ID, Key, Secret, and Cluster."}, {"type": "dashboard_config", "title": "Configure Allowed Origins", "required": false, "instructions": "Under App Settings, configure allowed origins for CORS. Add your development and production domains."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export PUSHER_APP_ID=<from-dashboard>", "export PUSHER_KEY=<from-dashboard>", "export PUSHER_SECRET=<from-dashboard>", "export PUSHER_CLUSTER=<e.g.-us2>"], "required": true, "instructions": "Add Pusher credentials to your application environment."}]}', '[]', '{"apiAreas": {"type": "multiselect", "label": "Pusher API areas used", "options": ["server-publish", "channel-auth", "webhooks"], "description": "Which parts of the Pusher Channels API this component calls — selected areas'' endpoint reference is embedded in the build instructions"}, "features": {"type": "multiselect", "label": "Features used", "options": ["public-channels", "private-channels", "presence-channels", "client-events"], "description": "Private/presence channels require the auth endpoint; client events require private/presence"}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''/occupied'':183C ''2020'':30B ''abli'':52B ''acquisit'':32B ''anyth'':146C ''api'':11B ''app'':95C,125C ''appid'':93C ''auth'':76C,153C ''authent'':163C ''author'':160C ''await'':114C ''bird/messagebird'':31B ''broad'':16B ''capabl'':172C ''channel'':6B,13B,75C,79C,144C,152C,168C,181C,196C ''channel-auth'':151C ''channel-vac'':180C ''chat'':43B ''client'':14B,101C,129C ''client-vis'':100C,128C ''cluster'':109C,111C ''compat'':68B,84C ''const'':89C ''coverag'':18B ''dashboard'':41B ''decid'':155C ''deliveri'':45B ''drop'':65B ''drop-in'':64B ''endpoint'':77C,154C ''event'':15B,184C,199C ''everi'':192C,198C ''everyth'':134C ''famous'':9B ''fine'':33B ''function'':27B ''guarante'':46B ''histori'':47B ''host'':59B,83C ''id'':96C ''import'':85C ''js'':71C ''keep'':186C ''key'':97C,99C,126C ''larg'':49B ''leav'':137C ''light'':42B ''live'':40B ''manag'':3B ''may'':157C ''messag'':5B ''modest'':36B ''modest-volum'':35B ''name'':166C ''never'':136C ''new'':26B,91C ''note'':20B ''notif'':39B ''oper'':21B ''order'':121C ''order-upd'':120C ''orderid'':123C ''payload'':187C ''prefer'':51B ''presenc'':78C,143C ''privat'':117C,141C ''private-us'':116C ''process.env.pusher'':94C,98C,104C,110C ''protocol'':62B ''public/private/presence'':12B ''pusher'':1A,2A,61B,70C,86C,88C,90C,92C,177C ''pusher-j'':69C ''pusher-protocol'':60B ''pusher.trigger'':115C ''realtim'':4B,38B ''refer'':189C ''reference-not-secret'':188C ''scale'':50B ''sdk'':17B,67B,73C ''secret'':103C,105C,132C,191C ''see'':197C ''self'':58B,82C ''self-host'':57B,81C ''server'':63B,72C,107C,139C ''server-on'':106C ''session'':164C ''sign'':133C ''signatur'':175C ''signific'':25B ''simpl'':10B ''sinc'':28B ''soketi'':54B,80C ''specif'':149C ''stagnant'':23B ''status'':19B ''subscrib'':158C,193C ''trigger'':74C ''true'':113C ''trust'':179C ''updat'':122C ''use'':140C ''user'':118C,148C ''user-specif'':147C ''userid'':119C ''usetl'':112C ''vacat'':182C ''valid'':173C ''visibl'':102C,130C ''volum'':37B ''webhook'':174C');
INSERT INTO public.technology_catalog VALUES ('vercel-edge', 'Vercel Edge Functions', NULL, '#6b7280', '["serverless-function"]', '{"purpose": "Vercel''s legacy edge runtime (V8 isolates, web-standard APIs, fast cold starts). DEPRECATED: Vercel replaced Edge Functions with Vercel Functions on the Node.js runtime under Fluid Compute — same regions and pricing, full Node standard library; Edge Middleware also runs on Vercel Functions now. This node exists for EXISTING deployments; new builds use Vercel Functions.", "configMode": "code", "provenance": {"notes": "Dialect-B row converted WITH the vendor deprecation: Edge Functions deprecated, Vercel Functions/Fluid Compute the successor. The vercel PLATFORM row is absent — the entire PaaS/hosting family (vercel, netlify, railway, render, fly-io) is missing from the catalog; banked as chunk 4g-2.", "method": "live-docs", "sources": ["https://vercel.com/docs/functions/runtimes/edge/edge-functions.rsc", "https://vercel.com/changelog/edge-middleware-and-edge-functions-are-now-powered-by-vercel-functions"], "verifiedAt": "2026-07-27"}, "typicalTech": ["Vercel Functions (successor)", "Fluid Compute", "middleware", "legacy edge runtime"], "antiPatterns": ["Starting NEW functions on the deprecated edge runtime", "Keeping edge-runtime API workarounds (web-crypto shims, fetch-only DB drivers chosen for compatibility) after migrating"], "bestPractices": ["New work: Vercel Functions (Node runtime, Fluid Compute) — full Node APIs (database clients, crypto, fs) without the edge-runtime restrictions", "Migrating: remove runtime = ''edge'' config and re-test any code that worked around missing Node APIs — the workarounds are now unnecessary", "Middleware: plain middleware on Vercel Functions — no special runtime handling"], "migrationTarget": "vercel"}', '[]', '{"migrationTarget": {"type": "enum", "label": "Migration target", "default": "vercel-functions-fluid", "options": ["vercel-functions-fluid", "keep-legacy-edge"], "description": "Edge Functions are deprecated — Vercel Functions (Node runtime, Fluid Compute) is the successor; keep-legacy only while a migration is scheduled"}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''also'':45B ''api'':16B ''build'':58B ''cold'':18B ''comput'':34B,66C ''deploy'':56B ''deprec'':20B ''edg'':2A,5A,9B,23B,43B,69C ''exist'':53B,55B ''fast'':17B ''fluid'':33B,65C ''full'':39B ''function'':3A,24B,27B,49B,61B,63C ''isol'':12B ''legaci'':8B,68C ''librari'':42B ''middlewar'':44B,67C ''new'':57B ''node'':40B,52B ''node.js'':30B ''price'':38B ''region'':36B ''replac'':22B ''run'':46B ''runtim'':10B,31B,70C ''standard'':15B,41B ''start'':19B ''successor'':64C ''use'':59B ''v8'':11B ''vercel'':1A,4A,6B,21B,26B,48B,60B,62C ''web'':14B ''web-standard'':13B');
INSERT INTO public.technology_catalog VALUES ('aws-ecs', 'AWS ECS', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-ecs.png', '#FF9900', '["ecs-cluster", "docker-container"]', '{"purpose": "AWS-native container orchestration service for running Docker containers at scale. ECS Fargate provides serverless container execution without managing EC2 instances; ECS on EC2 gives full control over underlying compute. Best for teams already on AWS who want simpler container orchestration than Kubernetes. Use ECS Fargate for most containerized workloads; use ECS on EC2 for GPU workloads, specific instance types, or cost optimization with Spot/Reserved instances. Choose EKS over ECS when you need Kubernetes ecosystem compatibility.", "configMode": "declarative", "provenance": {"notes": "Phase B4 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using EC2 launch type when Fargate suffices (unnecessary operational overhead)", "Running sidecar containers without proper health checks", "Not using task definitions versioning for rollback capability", "Hardcoding secrets in task definitions instead of using Secrets Manager references", "Ignoring Fargate platform version updates"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/ecs/"}, "bestPractices": ["Use Fargate launch type unless you need specific EC2 instance control", "Use ECS Service Connect or Cloud Map for service discovery", "Configure task-level IAM roles (not instance roles) for least privilege", "Enable Container Insights for monitoring and logging", "Use capacity providers for mixed Fargate/EC2/Spot strategies", "Store secrets in Secrets Manager or Parameter Store, not environment variables"], "securityGuidance": "Two roles, two jobs: the EXECUTION role pulls images and writes logs; the TASK role is what your code runs as — scope it per service, least privilege. Inject secrets via the secrets/valueFrom binding to Secrets Manager or SSM, never plaintext environment. Use awsvpc networking with a security group per service, keep privileged mode off, and gate deploys on ECR image scanning.", "configurationTemplate": "{\r\n  \"family\": \"api\",\r\n  \"networkMode\": \"awsvpc\",\r\n  \"requiresCompatibilities\": [\"FARGATE\"],\r\n  \"cpu\": \"256\", \"memory\": \"512\",\r\n  \"taskRoleArn\": \"arn:aws:iam::ACCOUNT:role/api-task-role\",\r\n  \"executionRoleArn\": \"arn:aws:iam::ACCOUNT:role/api-execution-role\",\r\n  \"containerDefinitions\": [{\r\n    \"name\": \"api\", \"image\": \"ACCOUNT.dkr.ecr.REGION.amazonaws.com/api:TAG\",\r\n    \"portMappings\": [{ \"containerPort\": 3000 }],\r\n    \"secrets\": [{ \"name\": \"DB_PASSWORD\", \"valueFrom\": \"arn:aws:secretsmanager:...:secret:db-password\" }]\r\n  }]\r\n}"}', '[{"kind": "build", "path": "Dockerfile", "priority": "essential", "description": "Container image definition"}, {"kind": "config", "path": "ecs-task-definition.json", "priority": "essential", "description": "ECS task definition"}, {"kind": "config", "path": "terraform/ecs.tf", "priority": "recommended", "description": "ECS cluster and service infrastructure"}, {"kind": "config", "path": "docker-compose.yml", "priority": "recommended", "description": "Local development Docker Compose"}]', '{"cpu": {"type": "string", "label": "CPU (vCPU units)", "default": "256"}, "memory": {"type": "string", "label": "Memory (MB)", "default": "512"}, "launchType": {"enum": ["FARGATE", "EC2"], "type": "string", "label": "Launch Type", "default": "FARGATE"}, "desiredCount": {"type": "number", "label": "Desired Task Count", "default": 2}, "serviceConnect": {"type": "boolean", "label": "Service Connect", "default": true}}', '["load-balancer", "database", "cache", "message-broker"]', false, NULL, NULL, '2026-03-04 00:48:04.051147+00', '2026-08-30 12:07:23.877005+00', NULL, '#CC7A00', '''alreadi'':39B ''aw'':1A,3A,6B,41B ''aws-nat'':5B ''awsvpc'':124C ''best'':36B ''bind'':114C ''choos'':72B ''code'':100C ''compat'':81B ''comput'':35B ''contain'':8B,14B,21B,45B ''container'':54B ''control'':32B ''cost'':67B ''deploy'':138C ''docker'':13B ''ec'':2A,4A,17B,27B,50B,57B,75B ''ec2'':25B,29B,59B ''ecosystem'':80B ''ecr'':140C ''ek'':73B ''environ'':122C ''execut'':22B,87C ''fargat'':18B,51B ''full'':31B ''gate'':137C ''give'':30B ''gpu'':61B ''group'':129C ''imag'':90C,141C ''inject'':109C ''instanc'':26B,64B,71B ''job'':85C ''keep'':132C ''kubernet'':48B,79B ''least'':107C ''log'':93C ''manag'':24B,117C ''mode'':134C ''nativ'':7B ''need'':78B ''network'':125C ''never'':120C ''optim'':68B ''orchestr'':9B,46B ''per'':105C,130C ''plaintext'':121C ''privileg'':108C,133C ''provid'':19B ''pull'':89C ''role'':83C,88C,96C ''run'':12B,101C ''scale'':16B ''scan'':142C ''scope'':103C ''secret'':110C,116C ''secrets/valuefrom'':113C ''secur'':128C ''serverless'':20B ''servic'':10B,106C,131C ''simpler'':44B ''specif'':63B ''spot/reserved'':70B ''ssm'':119C ''task'':95C ''team'':38B ''two'':82C,84C ''type'':65B ''under'':34B ''use'':49B,56B,123C ''via'':111C ''want'':43B ''without'':23B ''workload'':55B,62B ''write'':92C');
INSERT INTO public.technology_catalog VALUES ('memcached', 'Memcached', NULL, '#00835a', '["cache"]', '{"purpose": "High-performance distributed memory caching system designed for simplicity and speed. Use when you need a straightforward, multi-threaded caching layer for reducing database load on read-heavy workloads. Memcached excels at caching database query results, session data, rendered page fragments, and API responses with simple key-value access patterns. Its multi-threaded architecture can better utilize multi-core machines compared to Redis''s single-threaded model for pure caching workloads. Don''t use when you need advanced data structures (sorted sets, streams, pub/sub) -- Redis is better suited. Don''t use when you need data persistence or durability -- Memcached is purely ephemeral. Avoid when you need key enumeration, pattern matching, or any operation beyond get/set/delete. For most new projects, Redis offers a superset of Memcached functionality, so prefer Redis unless you specifically need multi-threaded simple caching.", "configMode": "declarative", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Memcached", "memcached-client", "AWS ElastiCache (Memcached)", "libmemcached", "mcrouter", "pymemcache", "memjs", "php-memcached"], "antiPatterns": ["Using Memcached for data that requires persistence or durability", "Storing values larger than 1MB (default max value size)", "Not handling cache misses gracefully causing thundering herd on cache expiry", "Using Memcached when you need data structures beyond simple key-value", "Running without monitoring hit/miss ratios making it impossible to tune", "Treating Memcached as a database instead of a performance optimization layer"], "apiReference": {"docsUrl": "https://github.com/memcached/memcached/wiki"}, "bestPractices": ["Set appropriate TTL values for all cached items based on data freshness requirements", "Use consistent hashing for distributing keys across multiple nodes", "Size your cache based on working set, not total dataset size", "Use multi-get for fetching multiple keys in a single round trip", "Implement cache warming strategies for cold starts", "Monitor hit/miss ratios to evaluate cache effectiveness", "Use namespaced keys with version prefixes for cache invalidation"], "freshnessNote": "Self-hosted memcached remains alive and fine at what it does; note the managed-service world is retiring it (GCP Memorystore for Memcached EOL path, per the 4c-2 finding) — for NEW builds valkey/redis covers this use case plus everything adjacent.", "sdkInitPattern": "// Node.js with memjs\\nimport memjs from \"memjs\";\\nconst mc = memjs.Client.create(process.env.MEMCACHED_SERVERS!, { retries: 2, expires: 300 });\\n// [Tailor to project language: Python=pymemcache, Go=bradfitz/gomemcache, PHP=ext-memcached, Java=spymemcached]", "securityGuidance": "Never expose Memcached to the internet -- it has no built-in authentication by default. Place behind a firewall in a private network. Use SASL authentication when available (ElastiCache supports it). Encrypt data in transit using a sidecar proxy or stunnel if TLS is not natively supported. Never store sensitive data (passwords, tokens) in cache without encryption.", "commonApiPatterns": [{"name": "Get/Set", "description": "Basic get and set with TTL", "codeTemplate": "await mc.set(\"user:123\", JSON.stringify(userData), { expires: 600 });\\nconst { value } = await mc.get(\"user:123\");\\nif (value) { const user = JSON.parse(value.toString()); }"}, {"name": "Cache-Aside", "description": "Cache-aside pattern with fallback to data source", "codeTemplate": "async function getCached(key: string, fetcher: () => Promise<any>, ttl = 300) {\\n  const { value } = await mc.get(key);\\n  if (value) return JSON.parse(value.toString());\\n  const data = await fetcher();\\n  await mc.set(key, JSON.stringify(data), { expires: ttl });\\n  return data;\\n}"}, {"name": "Delete / Invalidate", "description": "Cache invalidation with versioned keys", "codeTemplate": "await mc.delete(\"user:123\");\\n// Version-based invalidation:\\nconst version = await mc.increment(\"user:version:123\", 1);\\n// Key becomes: `user:123:v${version}`"}], "integrationPatterns": ["Application cache layer for database query results and rendered fragments", "AWS ElastiCache or mcrouter for managed/scaled Memcached deployments", "Session store for stateless web application servers"], "configurationTemplate": "# memcached startup flags\\nmemcached -m 512 -c 1024 -t 4 -l 127.0.0.1 -p 11211\\n# -m: memory in MB\\n# -c: max connections\\n# -t: threads (use number of CPU cores)\\n# -l: listen address\\n# -p: port"}', '[{"kind": "config", "path": "memcached.conf", "language": "text", "description": "Bind to internal interface, disable UDP, memory cap"}]', '{"useCase": {"type": "enum", "label": "Use case", "default": "simple-object-cache", "options": ["simple-object-cache", "session-cache"], "description": "Memcached does one thing (volatile key-value caching) — anything needing structures, persistence or pub/sub is the redis/valkey node"}}', '["backend-service"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#006B4A', '''2'':175C ''300'':177C ''access'':55B ''advanc'':87B ''api'':48B ''architectur'':61B ''authent'':205C,218C ''avail'':220C ''avoid'':112B ''aw'':152C ''behind'':209C ''better'':63B,96B ''beyond'':123B ''bradfitz/gomemcache'':186C ''built'':203C ''built-in'':202C ''cach'':8B,24B,38B,79B,147B,247C ''client'':151C ''compar'':69B ''core'':67B ''data'':43B,88B,104B,225C,243C ''databas'':28B,39B ''default'':207C ''design'':10B ''distribut'':6B ''durabl'':107B ''elasticach'':153C,221C ''encrypt'':224C,249C ''enumer'':117B ''ephemer'':111B ''excel'':36B ''expir'':176C ''expos'':194C ''ext'':189C ''ext-memcach'':188C ''firewal'':211C ''fragment'':46B ''function'':135B ''get/set/delete'':124B ''go'':185C ''heavi'':33B ''high'':4B ''high-perform'':3B ''internet'':198C ''java'':191C ''key'':53B,116B ''key-valu'':52B ''languag'':182C ''layer'':25B ''libmemcach'':155C ''load'':29B ''machin'':68B ''match'':119B ''mc'':170C ''mcrouter'':156C ''memcach'':1A,2A,35B,108B,134B,148C,150C,154C,161C,190C,195C ''memcached-cli'':149C ''memj'':158C,164C,166C,168C ''memjs.client.create'':171C ''memori'':7B ''model'':76B ''multi'':22B,59B,66B,144B ''multi-cor'':65B ''multi-thread'':21B,58B,143B ''n'':178C ''nativ'':238C ''nconst'':169C ''need'':18B,86B,103B,115B,142B ''network'':215C ''never'':193C,240C ''new'':127B ''nimport'':165C ''node.js'':162C ''offer'':130B ''oper'':122B ''page'':45B ''password'':244C ''pattern'':56B,118B ''perform'':5B ''persist'':105B ''php'':160C,187C ''php-memcach'':159C ''place'':208C ''prefer'':137B ''privat'':214C ''process.env.memcached'':172C ''project'':128B,181C ''proxi'':231C ''pub/sub'':93B ''pure'':78B,110B ''pymemcach'':157C,184C ''python'':183C ''queri'':40B ''read'':32B ''read-heavi'':31B ''redi'':71B,94B,129B,138B ''reduc'':27B ''render'':44B ''respons'':49B ''result'':41B ''retri'':174C ''sasl'':217C ''sensit'':242C ''server'':173C ''session'':42B ''set'':91B ''sidecar'':230C ''simpl'':51B,146B ''simplic'':12B ''singl'':74B ''single-thread'':73B ''sort'':90B ''specif'':141B ''speed'':14B ''spymemcach'':192C ''store'':241C ''straightforward'':20B ''stream'':92B ''structur'':89B ''stunnel'':233C ''suit'':97B ''superset'':132B ''support'':222C,239C ''system'':9B ''tailor'':179C ''thread'':23B,60B,75B,145B ''tls'':235C ''token'':245C ''transit'':227C ''unless'':139B ''use'':15B,83B,100B,216C,228C ''util'':64B ''valu'':54B ''without'':248C ''workload'':34B,80B');
INSERT INTO public.technology_catalog VALUES ('solid', 'SolidJS', NULL, '#2c4f7c', '["frontend-app"]', '{"purpose": "Reactive JavaScript UI framework with fine-grained reactivity and no virtual DOM. SolidJS compiles components to direct DOM operations, delivering performance that rivals vanilla JavaScript while maintaining a developer experience similar to React. Use when you need the highest possible runtime performance for interactive web applications, when you want React-like JSX syntax without the VDOM overhead, or when you''re building performance-critical dashboards, visualizations, or real-time interfaces. Solid''s reactivity model (signals, memos, effects) updates only the exact DOM nodes that changed. Don''t use when your team is heavily invested in React ecosystem libraries that don''t have Solid equivalents. Don''t use for content-heavy sites where Astro or Next.js SSG would be simpler. Avoid if your project needs a mature, battle-tested ecosystem with extensive third-party component libraries -- React and Vue have larger ecosystems.", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["SolidJS", "SolidStart", "Solid Router", "Vite", "Tailwind CSS", "solid-primitives", "Kobalte UI", "Vitest"], "antiPatterns": ["Destructuring signal accessors (props.count) in component body breaking reactivity tracking", "Using React mental model with re-renders -- Solid components run once, only signals update", "Creating unnecessary effects when derived state (createMemo) is sufficient", "Not using For component for lists causing unnecessary DOM recreation", "Importing React-specific libraries that depend on virtual DOM reconciliation", "Using createEffect for synchronous derived values instead of createMemo"], "apiReference": {"docsUrl": "https://docs.solidjs.com"}, "bestPractices": ["Use createSignal for reactive state and createMemo for derived computations", "Use createResource for async data fetching with built-in loading/error states", "Destructure props carefully -- use mergeProps or splitProps to maintain reactivity", "Use SolidStart for full-stack applications with SSR and file-based routing", "Leverage Solid''s fine-grained reactivity instead of React patterns like useMemo", "Use Show, For, Switch/Match control flow components instead of ternary expressions"], "sdkInitPattern": "npx degit solidjs/templates/ts my-app && cd my-app && npm install\\n// src/App.tsx\\nimport { createSignal } from \"solid-js\";\\nexport default function App() {\\n  const [count, setCount] = createSignal(0);\\n  return <button onClick={() => setCount(c => c + 1)}>Count: {count()}</button>;\\n}", "securityGuidance": "Solid auto-escapes JSX text content preventing XSS. Never use innerHTML prop with unsanitized user input. Validate and sanitize URLs passed to href or src attributes. Use Content Security Policy headers in production. Avoid storing sensitive tokens in signals that might be exposed via devtools -- use httpOnly cookies for auth.", "commonApiPatterns": [{"name": "Reactive Signal", "description": "Signal with derived memo for reactive state", "codeTemplate": "const [name, setName] = createSignal(\"\");\\nconst greeting = createMemo(() => `Hello, ${name() || \"World\"}!`);\\nreturn <div>\\n  <input value={name()} onInput={(e) => setName(e.target.value)} />\\n  <p>{greeting()}</p>\\n</div>;"}, {"name": "Async Resource", "description": "createResource for async data with Show/For control flow", "codeTemplate": "const [users] = createResource(async () => {\\n  const res = await fetch(\"/api/users\");\\n  return res.json() as Promise<User[]>;\\n});\\nreturn <Show when={!users.loading} fallback={<p>Loading...</p>}>\\n  <For each={users()}>{(user) => <div>{user.name}</div>}</For>\\n</Show>;"}, {"name": "Store for Complex State", "description": "Solid store with produce for nested immutable-style updates", "codeTemplate": "import { createStore, produce } from \"solid-js/store\";\\nconst [state, setState] = createStore({ todos: [] as Todo[] });\\nconst addTodo = (text: string) => setState(produce((s) => { s.todos.push({ id: Date.now(), text, done: false }); }));\\nconst toggle = (id: number) => setState(\"todos\", (t) => t.id === id, \"done\", (d) => !d);"}], "integrationPatterns": ["SolidStart for full-stack SSR/SSG with file-based routing and server functions", "Tailwind CSS for utility-first styling with Solid components", "Vitest + Solid Testing Library for component testing"], "configurationTemplate": "// vite.config.ts\\nimport { defineConfig } from \"vite\";\\nimport solid from \"vite-plugin-solid\";\\nexport default defineConfig({\\n  plugins: [solid()],\\n  server: { port: 3000 },\\n  build: { target: \"esnext\" }\\n});"}', '[{"kind": "source", "path": "src/App.tsx", "language": "typescript", "description": "Root component"}, {"kind": "config", "path": "vite.config.ts", "language": "typescript", "description": "Vite configuration"}]', '{"framework": {"type": "enum", "label": "Framework", "default": "solidstart", "options": ["solidstart", "spa-vite"]}, "rendering": {"type": "enum", "label": "Rendering", "default": "ssr", "options": ["ssr", "csr", "static"]}, "typescript": {"type": "boolean", "label": "TypeScript", "default": true}}', '["rest-api", "graphql-api"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-30 12:07:23.877005+00', NULL, '#234A6E', '''0'':193C ''1'':201C ''app'':169C,173C,187C ''applic'':49B ''astro'':120B ''attribut'':231C ''auth'':255C ''auto'':207C ''auto-escap'':206C ''avoid'':127B,239C ''battl'':135B ''battle-test'':134B ''build'':66B ''button'':196C ''c'':199C,200C ''cd'':170C ''chang'':91B ''compil'':17B ''compon'':18B,143B ''const'':189C ''content'':116B,211C,233C ''content-heavi'':115B ''cooki'':253C ''count'':190C,202C,203C ''createsign'':179C,192C ''critic'':69B ''css'':157C ''dashboard'':70B ''default'':185C ''degit'':165C ''deliv'':23B ''develop'':32B ''devtool'':250C ''direct'':20B ''dom'':15B,21B,88B ''ecosystem'':103B,137B,150B ''effect'':83B ''equival'':110B ''escap'':208C ''exact'':87B ''experi'':33B ''expos'':248C ''extens'':139B ''fine'':9B ''fine-grain'':8B ''framework'':6B ''function'':186C ''grain'':10B ''header'':236C ''heavi'':117B ''heavili'':99B ''highest'':42B ''href'':228C ''httpon'':252C ''innerhtml'':216C ''input'':221C ''instal'':175C ''interact'':47B ''interfac'':76B ''invest'':100B ''javascript'':4B,28B ''js'':183C ''jsx'':56B,209C ''kobalt'':161C ''larger'':149B ''librari'':104B,144B ''like'':55B ''maintain'':30B ''matur'':133B ''memo'':82B ''might'':246C ''model'':80B ''my-app'':167C,171C ''n'':176C,188C,194C,204C ''need'':40B,131B ''never'':214C ''nexport'':184C ''next.js'':122B ''nimport'':178C ''node'':89B ''npm'':174C ''npx'':164C ''onclick'':197C ''oper'':22B ''overhead'':61B ''parti'':142B ''pass'':226C ''perform'':24B,45B,68B ''performance-crit'':67B ''polici'':235C ''possibl'':43B ''prevent'':212C ''primit'':160C ''product'':238C ''project'':130B ''prop'':217C ''re'':65B ''react'':36B,54B,102B,145B ''react-lik'':53B ''reactiv'':3B,11B,79B ''real'':74B ''real-tim'':73B ''return'':195C ''rival'':26B ''router'':154C ''runtim'':44B ''sanit'':224C ''secur'':234C ''sensit'':241C ''setcount'':191C,198C ''signal'':81B,244C ''similar'':34B ''simpler'':126B ''site'':118B ''solid'':2A,77B,109B,153C,159C,182C,205C ''solid-j'':181C ''solid-primit'':158C ''solidj'':1A,16B,151C ''solidjs/templates/ts'':166C ''solidstart'':152C ''src'':230C ''src/app.tsx'':177C ''ssg'':123B ''store'':240C ''syntax'':57B ''tailwind'':156C ''team'':97B ''test'':136B ''text'':210C ''third'':141B ''third-parti'':140B ''time'':75B ''token'':242C ''ui'':5B,162C ''unsanit'':219C ''updat'':84B ''url'':225C ''use'':37B,94B,113B,215C,232C,251C ''user'':220C ''valid'':222C ''vanilla'':27B ''vdom'':60B ''via'':249C ''virtual'':14B ''visual'':71B ''vite'':155C ''vitest'':163C ''vue'':147B ''want'':52B ''web'':48B ''without'':58B ''would'':124B ''xss'':213C');
INSERT INTO public.technology_catalog VALUES ('mysql', 'MySQL', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/mysql.png', '#4479a1', '["database"]', '{"purpose": "Widely adopted open-source relational database, dominant in web applications and CMS platforms. Use when your application stack is built around the MySQL ecosystem (WordPress, Drupal, Laravel, Rails), when you need mature replication with read replicas, or when the team has deep MySQL expertise. MySQL excels at high-throughput read-heavy workloads with InnoDB. Don''t use when you need advanced SQL features like array types, JSONB indexing, recursive CTEs with complex operations, or row-level security -- PostgreSQL is stronger there. Don''t use MySQL for analytical workloads requiring window functions on very large datasets without an OLAP layer. Avoid if you need native support for geospatial beyond basic functions or vector embeddings. For new greenfield projects without ecosystem constraints, PostgreSQL is generally the more capable default choice.", "configMode": "declarative", "provenance": {"notes": "docsUrl is the vendor''s canonical documentation root, stamped from model knowledge and checked by scripts/n10-verify-docs-urls.ts; pre-existing body content not yet live-docs verified — upgrade at this row''s enrichment chunk.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["MySQL 8+", "AWS RDS MySQL", "Azure Database for MySQL", "PlanetScale", "Vitess", "ProxySQL", "MySQL Workbench", "Percona"], "antiPatterns": ["Using MyISAM engine instead of InnoDB for transactional tables", "Not indexing columns used in WHERE, JOIN, and ORDER BY clauses", "Using SELECT * in production queries pulling unnecessary data", "Storing large BLOBs in the database instead of object storage", "Running ALTER TABLE on large production tables without pt-online-schema-change", "Using utf8 instead of utf8mb4 silently truncating 4-byte Unicode characters"], "apiReference": {"docsUrl": "https://dev.mysql.com/doc/"}, "bestPractices": ["Use InnoDB engine for all tables (ACID compliance, row-level locking)", "Create composite indexes matching your most frequent WHERE/ORDER BY patterns", "Use connection pooling to manage connection overhead", "Set innodb_buffer_pool_size to 70-80% of available RAM", "Enable slow query log and use EXPLAIN ANALYZE for query optimization", "Use utf8mb4 character set for full Unicode support including emoji", "Implement read replicas for scaling read-heavy workloads"], "sdkInitPattern": "// Node.js with mysql2\\nimport mysql from \"mysql2/promise\";\\nconst pool = mysql.createPool({ uri: process.env.DATABASE_URL, waitForConnections: true, connectionLimit: 20 });\\n// [Tailor to project language: Python=mysql-connector-python, Go=go-sql-driver/mysql, PHP=PDO]", "securityGuidance": "Always use prepared statements with parameterized queries to prevent SQL injection. Require TLS for all client connections (require_secure_transport=ON). Create separate database users with minimal privileges for each application. Disable remote root login and use strong authentication plugins. Store credentials in a secrets manager, never in application code.", "commonApiPatterns": [{"name": "Parameterized Query", "description": "Prepared statement with positional parameters", "codeTemplate": "const [rows] = await pool.execute(\"SELECT id, name, email FROM users WHERE id = ?\", [userId]);"}, {"name": "Transaction", "description": "Transaction with rollback and connection release", "codeTemplate": "const conn = await pool.getConnection();\\ntry {\\n  await conn.beginTransaction();\\n  await conn.execute(\"INSERT INTO orders (user_id, total) VALUES (?, ?)\", [userId, total]);\\n  await conn.execute(\"UPDATE inventory SET stock = stock - ? WHERE product_id = ?\", [qty, productId]);\\n  await conn.commit();\\n} catch (e) {\\n  await conn.rollback();\\n  throw e;\\n} finally {\\n  conn.release();\\n}"}, {"name": "Upsert", "description": "Insert or update on duplicate key", "codeTemplate": "await pool.execute(\\n  \"INSERT INTO users (email, name) VALUES (?, ?) ON DUPLICATE KEY UPDATE name = VALUES(name), updated_at = NOW()\",\\n  [email, name]\\n);"}], "integrationPatterns": ["ProxySQL or MySQL Router for connection pooling and read/write splitting", "AWS RDS or PlanetScale for managed hosting with automatic scaling", "Vitess for horizontal sharding of large MySQL deployments"], "configurationTemplate": "# my.cnf key tuning\\n[mysqld]\\ninnodb_buffer_pool_size = 1G    # 70-80% of RAM\\ninnodb_log_file_size = 256M\\nmax_connections = 150\\nslow_query_log = 1\\nlong_query_time = 0.5\\ncharacter-set-server = utf8mb4\\ncollation-server = utf8mb4_unicode_ci"}', '[{"kind": "schema", "path": "schema.sql", "language": "sql", "description": "Database schema"}]', '{"edition": {"type": "enum", "label": "Track", "default": "mysql-8.4-lts", "options": ["mysql-8.4-lts", "innovation-track"], "description": "8.4 LTS is the boring production pick; innovation releases churn quarterly"}, "replication": {"type": "enum", "label": "Replication", "default": "single-primary", "options": ["single-primary", "primary-replica", "group-replication"]}, "backupStrategy": {"type": "enum", "label": "Backups", "default": "binlog-pitr", "options": ["binlog-pitr", "mysqldump-scheduled", "snapshot-only"]}}', '["backend-service", "rest-api"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#376181', '''/mysql'':182C ''20'':166C ''8'':136C ''adopt'':4B ''advanc'':66B ''alway'':185C ''analyt'':93B ''applic'':13B,20B,215C,233C ''around'':24B ''array'':70B ''authent'':223C ''avoid'':106B ''aw'':137C ''azur'':140C ''basic'':115B ''beyond'':114B ''built'':23B ''capabl'':132B ''choic'':134B ''client'':200C ''cms'':15B ''code'':234C ''complex'':77B ''connect'':201C ''connectionlimit'':165C ''connector'':175C ''constraint'':126B ''creat'':206C ''credenti'':226C ''ctes'':75B ''databas'':9B,141C,208C ''dataset'':101B ''deep'':45B ''default'':133B ''disabl'':216C ''domin'':10B ''driver'':181C ''drupal'':29B ''ecosystem'':27B,125B ''embed'':119B ''excel'':49B ''expertis'':47B ''featur'':68B ''function'':97B,116B ''general'':129B ''geospati'':113B ''go'':177C,179C ''go-sql-driv'':178C ''greenfield'':122B ''heavi'':56B ''high'':52B ''high-throughput'':51B ''index'':73B ''inject'':195C ''innodb'':59B ''jsonb'':72B ''languag'':171C ''laravel'':30B ''larg'':100B ''layer'':105B ''level'':82B ''like'':69B ''login'':219C ''manag'':230C ''matur'':35B ''minim'':211C ''mysql'':1A,2A,26B,46B,48B,91B,135C,139C,143C,147C,154C,174C ''mysql-connector-python'':173C ''mysql.createpool'':159C ''mysql2'':152C ''mysql2/promise'':156C ''n'':167C ''nativ'':110B ''nconst'':157C ''need'':34B,65B,109B ''never'':231C ''new'':121B ''nimport'':153C ''node.js'':150C ''olap'':104B ''open'':6B ''open-sourc'':5B ''oper'':78B ''parameter'':190C ''pdo'':184C ''percona'':149C ''php'':183C ''planetscal'':144C ''platform'':16B ''plugin'':224C ''pool'':158C ''postgresql'':84B,127B ''prepar'':187C ''prevent'':193C ''privileg'':212C ''process.env.database'':161C ''project'':123B,170C ''proxysql'':146C ''python'':172C,176C ''queri'':191C ''rail'':31B ''rds'':138C ''read'':38B,55B ''read-heavi'':54B ''recurs'':74B ''relat'':8B ''remot'':217C ''replic'':36B ''replica'':39B ''requir'':95B,196C,202C ''root'':218C ''row'':81B ''row-level'':80B ''secret'':229C ''secur'':83B,203C ''separ'':207C ''sourc'':7B ''sql'':67B,180C,194C ''stack'':21B ''statement'':188C ''store'':225C ''strong'':222C ''stronger'':86B ''support'':111B ''tailor'':168C ''team'':43B ''throughput'':53B ''tls'':197C ''transport'':204C ''true'':164C ''type'':71B ''uri'':160C ''url'':162C ''use'':17B,62B,90B,186C,221C ''user'':209C ''vector'':118B ''vitess'':145C ''waitforconnect'':163C ''web'':12B ''wide'':3B ''window'':96B ''without'':102B,124B ''wordpress'':28B ''workbench'':148C ''workload'':57B,94B');
INSERT INTO public.technology_catalog VALUES ('socket-io', 'Socket.io', NULL, '#6b7280', '["realtime-service"]', '{"purpose": "The long-standing Node.js realtime library: event-based bidirectional messaging with rooms/namespaces, automatic reconnection and polling fallback. Self-hosted realtime inside YOUR Node service — the DIY lane vs managed (Ably/Pusher) or platform primitives (Durable Objects). Overhead above raw WebSockets and a Node-only server are the trade.", "configMode": "code", "provenance": {"notes": "Phase B8c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-28. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["rooms + namespaces", "Redis adapter", "handshake auth middleware", "reconnection handling"], "antiPatterns": ["Scaling to multiple nodes without the adapter — silent partial delivery", "Treating socket delivery as guaranteed — it is at-most-once transport; the source of truth is your API/DB", "Broadcasting large payloads to big rooms instead of references"], "apiReference": {"docsUrl": "https://socket.io/docs/v4/"}, "bestPractices": ["Rooms for fan-out scoping; namespaces for auth boundaries", "Multi-node = Redis adapter + sticky sessions, configured together", "Reconnect handling: emit missed-state on reconnection — the library reconnects sockets, YOUR app reconciles state", "Auth in the handshake middleware, not per-event checks scattered through handlers"], "sdkInitPattern": "import { Server } from ''socket.io'';\n\nconst io = new Server(httpServer, { cors: { origin: process.env.APP_ORIGIN } });\n\nio.use(async (socket, next) => {\n  const user = await verifyToken(socket.handshake.auth.token);\n  if (!user) return next(new Error(''unauthorized''));\n  socket.data.user = user;\n  next();\n});\n\nio.on(''connection'', (socket) => {\n  socket.join(`user:${socket.data.user.id}`);\n});", "securityGuidance": "Authenticate in middleware at handshake time and re-authorize on every room join — a connection is not a capability, and room names derived from raw client input let one user subscribe to another''s stream. Pin CORS origins (never *), validate every event payload server-side like any HTTP input, emit to specific rooms rather than broadcasting, and remember disconnect/reconnect gets a fresh handshake: expired tokens must fail there too. Scale-out adapters (Redis) inherit the broker''s security posture."}', '[{"kind": "code", "path": "src/realtime/server.ts", "language": "typescript", "description": "Server init: handshake auth middleware, pinned CORS, room authorization"}]', '{"scaleOut": {"type": "enum", "label": "Scale-out", "default": "single-node", "options": ["single-node", "redis-adapter-multi-node"], "description": "Multi-node needs the Redis adapter AND sticky sessions — the two-part answer people learn in production"}, "transports": {"type": "enum", "label": "Transports", "default": "websocket-with-polling-fallback", "options": ["websocket-with-polling-fallback", "websocket-only"]}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''ably/pusher'':36B ''adapt'':58C,176C ''anoth'':135C ''async'':78C ''auth'':60C ''authent'':102C ''author'':111C ''automat'':18B ''await'':83C ''base'':13B ''bidirect'':14B ''broadcast'':159C ''broker'':180C ''capabl'':121C ''client'':128C ''connect'':97C,117C ''const'':68C,81C ''cor'':73C,139C ''deriv'':125C ''disconnect/reconnect'':162C ''diy'':32B ''durabl'':40B ''emit'':153C ''error'':91C ''event'':12B,144C ''event-bas'':11B ''everi'':113C,143C ''expir'':167C ''fail'':170C ''fallback'':22B ''fresh'':165C ''get'':163C ''handl'':63C ''handshak'':59C,106C,166C ''host'':25B ''http'':151C ''httpserver'':72C ''import'':64C ''inherit'':178C ''input'':129C,152C ''insid'':27B ''io'':3A,69C ''io.on'':96C ''io.use'':77C ''join'':115C ''lane'':33B ''let'':130C ''librari'':10B ''like'':149C ''long'':6B ''long-stand'':5B ''manag'':35B ''messag'':15B ''middlewar'':61C,104C ''must'':169C ''name'':124C ''namespac'':56C ''never'':141C ''new'':70C,90C ''next'':80C,89C,95C ''node'':29B,49B ''node-on'':48B ''node.js'':8B ''object'':41B ''one'':131C ''origin'':74C,76C,140C ''overhead'':42B ''payload'':145C ''pin'':138C ''platform'':38B ''poll'':21B ''postur'':183C ''primit'':39B ''process.env.app'':75C ''rather'':157C ''raw'':44B,127C ''re'':110C ''re-author'':109C ''realtim'':9B,26B ''reconnect'':19B,62C ''redi'':57C,177C ''rememb'':161C ''return'':88C ''room'':55C,114C,123C,156C ''rooms/namespaces'':17B ''scale'':174C ''scale-out'':173C ''secur'':182C ''self'':24B ''self-host'':23B ''server'':51B,65C,71C,147C ''server-sid'':146C ''servic'':30B ''side'':148C ''socket'':2A,79C,98C ''socket.data.user'':93C ''socket.data.user.id'':101C ''socket.handshake.auth.token'':85C ''socket.io'':1A,67C ''socket.join'':99C ''specif'':155C ''stand'':7B ''stream'':137C ''subscrib'':133C ''time'':107C ''token'':168C ''trade'':54B ''unauthor'':92C ''user'':82C,87C,94C,100C,132C ''valid'':142C ''verifytoken'':84C ''vs'':34B ''websocket'':45B');
INSERT INTO public.technology_catalog VALUES ('nginx', 'NGINX', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/nginx.png', '#009639', '["load-balancer", "api-gateway"]', '{"purpose": "High-performance web server, reverse proxy, and load balancer. NGINX is not a CDN itself, but can be deployed at edge locations as a building block for custom CDN infrastructure when paired with caching and distribution layers.", "configMode": "definition-as-code", "provenance": {"notes": "docsUrl is the vendor''s canonical documentation root, stamped from model knowledge and checked by scripts/n10-verify-docs-urls.ts; pre-existing body content not yet live-docs verified — upgrade at this row''s enrichment chunk.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["NGINX", "NGINX Plus", "OpenResty", "Lua modules", "Reverse Proxy"], "antiPatterns": ["Using if statements in location blocks (NGINX if is evil for rewrites)", "Not forwarding X-Forwarded-For and X-Real-IP headers to backends", "Leaving default server configuration active in production", "Not setting proxy_read_timeout for long-running API requests", "Serving static files without caching headers or gzip compression"], "apiReference": {"docsUrl": "https://nginx.org/en/docs/"}, "bestPractices": ["Use upstream blocks for load balancing", "Implement proper health checks", "Configure appropriate worker processes", "Use HTTPS with proper TLS configuration", "Implement rate limiting", "Use caching for static content", "Configure proper logging"], "sdkInitPattern": "# /etc/nginx/nginx.conf\\nworker_processes auto;\\nevents { worker_connections 1024; }\\nhttp {\\n  include mime.types;\\n  sendfile on;\\n  server {\\n    listen 80;\\n    server_name example.com;\\n    location / { root /var/www/html; index index.html; }\\n  }\\n}", "securityGuidance": "Disable server_tokens to hide NGINX version. Use TLS 1.2+ only with strong cipher suites. Set security headers (X-Frame-Options, X-Content-Type-Options, CSP). Limit request body size with client_max_body_size. Use rate limiting to prevent abuse. Restrict access to admin paths with allow/deny directives. Run NGINX worker processes as a non-root user.", "commonApiPatterns": [{"name": "Reverse Proxy", "description": "Load-balanced reverse proxy with proper header forwarding", "codeTemplate": "upstream backend {\\n  server app1:3000;\\n  server app2:3000;\\n}\\nserver {\\n  listen 80;\\n  location /api/ {\\n    proxy_pass http://backend;\\n    proxy_set_header Host $host;\\n    proxy_set_header X-Real-IP $remote_addr;\\n    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\\n    proxy_set_header X-Forwarded-Proto $scheme;\\n  }\\n}"}, {"name": "TLS Termination", "description": "HTTPS with modern TLS configuration and HSTS", "codeTemplate": "server {\\n  listen 443 ssl http2;\\n  server_name example.com;\\n  ssl_certificate /etc/letsencrypt/live/example.com/fullchain.pem;\\n  ssl_certificate_key /etc/letsencrypt/live/example.com/privkey.pem;\\n  ssl_protocols TLSv1.2 TLSv1.3;\\n  ssl_ciphers HIGH:!aNULL:!MD5;\\n  add_header Strict-Transport-Security \"max-age=31536000; includeSubDomains\" always;\\n}"}, {"name": "Rate Limiting", "description": "Per-IP rate limiting with burst allowance", "codeTemplate": "http {\\n  limit_req_zone $binary_remote_addr zone=api:10m rate=10r/s;\\n  server {\\n    location /api/ {\\n      limit_req zone=api burst=20 nodelay;\\n      proxy_pass http://backend;\\n    }\\n  }\\n}"}], "setupInstructions": [{"type": "toolchain_install", "title": "Install NGINX", "commands": ["# Debian/Ubuntu:", "sudo apt-get install nginx", "# macOS:", "brew install nginx", "# Verify:", "nginx -v"], "required": true, "instructions": "Install via system package manager. Use the official NGINX repository for the latest stable version."}, {"type": "dashboard_config", "title": "Configure Server Blocks", "commands": ["sudo nano /etc/nginx/sites-available/myapp", "sudo ln -s /etc/nginx/sites-available/myapp /etc/nginx/sites-enabled/", "sudo nginx -t && sudo systemctl reload nginx"], "required": true, "instructions": "Create a server block (virtual host) configuration in /etc/nginx/sites-available/. Link it to sites-enabled. Configure the server_name, root directory, and location blocks."}, {"url": "https://certbot.eff.org/", "type": "certificate", "title": "Obtain TLS Certificate", "commands": ["sudo apt-get install certbot python3-certbot-nginx", "sudo certbot --nginx -d example.com -d www.example.com"], "required": false, "instructions": "Use Certbot (Let''s Encrypt) to obtain a free TLS certificate. Certbot can automatically configure NGINX for HTTPS."}, {"type": "dashboard_config", "title": "Configure Reverse Proxy", "required": true, "instructions": "In the location block, configure proxy_pass to forward requests to your application server. Set proxy headers for proper client IP forwarding."}], "integrationPatterns": ["Certbot/Let''s Encrypt for automated TLS certificate renewal", "Docker or Kubernetes for containerized deployment", "Upstream blocks for load balancing across application servers", "Lua modules (OpenResty) for dynamic request processing", "Prometheus exporter for metrics collection"], "configurationTemplate": "# /etc/nginx/conf.d/default.conf\\nserver {\\n  listen 80;\\n  server_name _;\\n  return 301 https://$host$request_uri;\\n}\\nserver {\\n  listen 443 ssl http2;\\n  server_name example.com;\\n  ssl_certificate /etc/ssl/certs/cert.pem;\\n  ssl_certificate_key /etc/ssl/private/key.pem;\\n\\n  location / {\\n    root /var/www/html;\\n    try_files $uri $uri/ /index.html;\\n  }\\n  location /api/ {\\n    proxy_pass http://backend:3000/;\\n    proxy_http_version 1.1;\\n    proxy_set_header Upgrade $http_upgrade;\\n    proxy_set_header Connection \"upgrade\";\\n  }\\n}"}', '[{"kind": "config", "path": "nginx.conf", "language": "nginx", "description": "NGINX configuration"}]', '{"tls": {"type": "enum", "label": "TLS", "default": "certbot-lets-encrypt", "options": ["certbot-lets-encrypt", "manual-certs", "terminated-upstream"]}, "usage": {"type": "enum", "label": "Usage", "default": "reverse-proxy", "options": ["reverse-proxy", "static-file-server", "load-balancer"]}, "configStyle": {"type": "enum", "label": "Config management", "default": "versioned-in-repo", "options": ["versioned-in-repo", "hand-edited-on-server"], "description": "nginx.conf belongs in the repo and deploys like code — hand-edited server config is the drift generator"}}', '["backend-service", "frontend-app"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#007A2E', '''/etc/nginx/nginx.conf'':49C ''/var/www/html'':76C ''1.2'':90C ''1024'':56C ''80'':68C ''abus'':123C ''access'':125C ''admin'':127C ''allow/deny'':130C ''auto'':52C ''balanc'':12B ''block'':29B ''bodi'':111C,116C ''build'':28B ''cach'':37B ''cdn'':17B,32B ''cipher'':94C ''client'':114C ''connect'':55C ''content'':105C ''csp'':108C ''custom'':31B ''deploy'':22B ''direct'':131C ''disabl'':81C ''distribut'':39B ''edg'':24B ''example.com'':72C ''frame'':101C ''header'':98C ''hide'':85C ''high'':4B ''high-perform'':3B ''includ'':59C ''index'':77C ''index.html'':78C ''infrastructur'':33B ''layer'':40B ''limit'':109C,120C ''listen'':67C ''load'':11B ''locat'':25B,74C ''lua'':45C ''max'':115C ''mime.types'':60C ''modul'':46C ''n'':58C,61C,64C,66C,69C,73C,79C,80C ''name'':71C ''nevent'':53C ''nginx'':1A,2A,13B,41C,42C,86C,133C ''nhttp'':57C ''non'':139C ''non-root'':138C ''nworker'':50C ''openresti'':44C ''option'':102C,107C ''pair'':35B ''path'':128C ''perform'':5B ''plus'':43C ''prevent'':122C ''process'':51C,135C ''proxi'':9B,48C ''rate'':119C ''request'':110C ''restrict'':124C ''revers'':8B,47C ''root'':75C,140C ''run'':132C ''secur'':97C ''sendfil'':62C ''server'':7B,65C,70C,82C ''set'':96C ''size'':112C,117C ''strong'':93C ''suit'':95C ''tls'':89C ''token'':83C ''type'':106C ''use'':88C,118C ''user'':141C ''version'':87C ''web'':6B ''worker'':54C,134C ''x'':100C,104C ''x-content-type-opt'':103C ''x-frame-opt'':99C');
INSERT INTO public.technology_catalog VALUES ('chromadb', 'ChromaDB', NULL, '#7C3AED', '["vector-database"]', '{"purpose": "ChromaDB is an open-source embedding database designed for storing documents, metadata, and vectors for retrieval-augmented generation and semantic search workflows. Use it when you want a developer-friendly vector store for local development, lightweight production systems, or agent pipelines that benefit from simple collection-based retrieval APIs. Choose ChromaDB over embedding tables in a relational database when you want a purpose-built retrieval interface and over heavier distributed vector systems when the workload is modest and operational simplicity matters. Do not use it when you need highly distributed multi-tenant scale, advanced enterprise controls, or extreme retrieval throughput that calls for a more specialized production vector platform.", "configMode": "declarative", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["LangChain", "LlamaIndex", "OpenAI", "SentenceTransformers", "FastAPI", "Docker", "PostgreSQL", "LiteLLM"], "antiPatterns": ["Treating ChromaDB as a drop-in replacement for transactional relational storage", "Mixing many unrelated corpora and embedding models into one collection without boundaries", "Skipping persistence and backup planning for production retrieval workloads", "Assuming default chunking and retrieval settings are good enough without evaluation", "Exposing ChromaDB directly to untrusted clients instead of mediating access through an application layer", "Choosing ChromaDB for large-scale distributed retrieval requirements it was not designed to handle alone"], "apiReference": {"docsUrl": "https://docs.trychroma.com/"}, "bestPractices": ["Version collections and embedding models explicitly so retrieval behavior remains reproducible over time", "Store meaningful document metadata and IDs so semantic search can be narrowed by tenant, source, or content type", "Use ChromaDB behind a retrieval service boundary instead of coupling every application directly to the database", "Evaluate chunking strategy, top-k settings, and reranking quality using real documents and user queries", "Persist data deliberately and back up collections if the store is part of a production RAG path", "Separate local experimentation collections from production collections to avoid contamination and drift", "Monitor ingestion latency, collection size, and retrieval accuracy as embeddings and corpora evolve"], "sdkInitPattern": "import { ChromaClient } from ''chromadb'';\n\nconst chroma = new ChromaClient({ path: process.env.CHROMA_URL });\nconst collection = await chroma.getOrCreateCollection({ name: ''docs'' });\nconst results = await collection.query({\n  queryEmbeddings: [embedding],\n  nResults: 5,\n  where: { tenantId },  // the ownership filter rides EVERY query\n});", "securityGuidance": "A self-hosted Chroma server ships without meaningful auth by default — enable the auth provider (token/basic) and TLS before it crosses a network boundary, or anyone who can reach the port owns every collection. Embeddings inherit the source content''s sensitivity, and multi-tenant isolation is a where-filter you must apply on every query (or collection-per-tenant): a missing filter is cross-tenant retrieval. The persistence directory is the full data copy — back it up and permission it like a database volume."}', '[{"kind": "source", "path": "src/retrieval/chroma-client.py", "priority": "essential", "description": "Application client for creating collections, upserting embeddings, and querying ChromaDB"}, {"kind": "config", "path": "config/chromadb-settings.yaml", "priority": "recommended", "description": "Collection persistence, embedding model, and runtime configuration for ChromaDB deployments"}, {"kind": "schema", "path": "src/retrieval/document-schema.json", "priority": "recommended", "description": "Document metadata and collection schema conventions used for ChromaDB ingestion"}, {"kind": "build", "path": "docker/chromadb-compose.yaml", "priority": "recommended", "description": "Containerized deployment definition for local or self-hosted ChromaDB environments"}]', '{"persistenceMode": {"type": "string", "label": "Persistence Mode", "default": "disk", "options": ["disk", "ephemeral"], "description": "Primary storage mode for ChromaDB collections"}, "embeddingProvider": {"type": "string", "label": "Embedding Provider", "default": "openai", "options": ["openai", "sentence-transformers", "custom"], "description": "Default embedding provider paired with ChromaDB collections"}, "multiTenantIsolation": {"type": "boolean", "label": "Multi-Tenant Isolation", "default": false, "description": "Partition collections or namespaces by tenant for retrieval isolation"}}', '["ai-service", "llm-gateway", "backend-service", "ml-pipeline", "object-storage"]', false, NULL, NULL, '2026-03-17 03:20:36.070813+00', '2026-08-30 12:07:23.877005+00', NULL, '#632FBE', '''5'':150C ''advanc'':102B ''agent'':45B ''anyon'':185C ''api'':55B ''appli'':213C ''augment'':21B ''auth'':168C,173C ''await'':139C,145C ''back'':238C ''base'':53B ''benefit'':48B ''boundari'':183C ''built'':71B ''call'':110B ''choos'':56B ''chroma'':131C,163C ''chroma.getorcreatecollection'':140C ''chromacli'':127C,133C ''chromadb'':1A,2A,3B,57B,129C ''collect'':52B,138C,193C,219C ''collection-bas'':51B ''collection-per-ten'':218C ''collection.query'':146C ''const'':130C,137C,143C ''content'':198C ''control'':104B ''copi'':237C ''cross'':180C,227C ''cross-ten'':226C ''data'':236C ''databas'':10B,64B,246C ''default'':170C ''design'':11B ''develop'':34B,40B ''developer-friend'':33B ''directori'':232C ''distribut'':77B,97B ''doc'':142C ''docker'':123C ''document'':14B ''embed'':9B,59B,148C,194C ''enabl'':171C ''enterpris'':103B ''everi'':157C,192C,215C ''extrem'':106B ''fastapi'':122C ''filter'':155C,210C,224C ''friend'':35B ''full'':235C ''generat'':22B ''heavier'':76B ''high'':96B ''host'':162C ''import'':126C ''inherit'':195C ''interfac'':73B ''isol'':205C ''langchain'':118C ''lightweight'':41B ''like'':244C ''litellm'':125C ''llamaindex'':119C ''local'':39B ''matter'':88B ''meaning'':167C ''metadata'':15B ''miss'':223C ''modest'':84B ''multi'':99B,203C ''multi-ten'':98B,202C ''must'':212C ''name'':141C ''need'':95B ''network'':182C ''new'':132C ''nresult'':149C ''open'':7B ''open-sourc'':6B ''openai'':120C ''oper'':86B ''own'':191C ''ownership'':154C ''path'':134C ''per'':220C ''permiss'':242C ''persist'':231C ''pipelin'':46B ''platform'':117B ''port'':190C ''postgresql'':124C ''process.env.chroma'':135C ''product'':42B,115B ''provid'':174C ''purpos'':70B ''purpose-built'':69B ''queri'':158C,216C ''queryembed'':147C ''reach'':188C ''relat'':63B ''result'':144C ''retriev'':20B,54B,72B,107B,229C ''retrieval-aug'':19B ''ride'':156C ''scale'':101B ''search'':25B ''self'':161C ''self-host'':160C ''semant'':24B ''sensit'':200C ''sentencetransform'':121C ''server'':164C ''ship'':165C ''simpl'':50B ''simplic'':87B ''sourc'':8B,197C ''special'':114B ''store'':13B,37B ''system'':43B,79B ''tabl'':60B ''tenant'':100B,204C,221C,228C ''tenantid'':152C ''throughput'':108B ''tls'':177C ''token/basic'':175C ''url'':136C ''use'':27B,91B ''vector'':17B,36B,78B,116B ''volum'':247C ''want'':31B,67B ''where-filt'':208C ''without'':166C ''workflow'':26B ''workload'':82B');
INSERT INTO public.technology_catalog VALUES ('pgvector', 'pgvector', NULL, '#336791', '["vector-database"]', '{"purpose": "pgvector is a PostgreSQL extension that adds vector similarity search and indexing directly inside a relational database, letting teams keep embeddings close to transactional data and metadata. Use it when your application already depends on PostgreSQL and you want semantic search, retrieval, or hybrid filtering without introducing a separate vector database too early. Choose pgvector over a standalone vector store when operational simplicity, SQL joins, and transactional proximity matter more than extreme-scale ANN specialization. Do not use it when the workload demands billion-scale vector search, highly specialized retrieval infrastructure, or independent horizontal scaling beyond what your PostgreSQL architecture can support comfortably.", "configMode": "declarative", "provenance": {"notes": "Phase B8c additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["PostgreSQL", "SQLAlchemy", "psycopg", "LangChain", "LlamaIndex", "OpenAI", "FastAPI", "Redis"], "antiPatterns": ["Mixing embeddings from incompatible models in the same collection without versioning or migration strategy", "Using pgvector as a substitute for a full-text search engine when lexical ranking is the real need", "Assuming approximate vector indexes require no benchmarking or quality evaluation", "Pushing high-churn large-scale vector workloads into a single PostgreSQL instance without capacity planning", "Treating embeddings as opaque blobs with no metadata, lineage, or model provenance", "Choosing pgvector when a dedicated vector service is clearly required for scale or isolation"], "apiReference": {"docsUrl": "https://github.com/pgvector/pgvector"}, "bestPractices": ["Store embeddings alongside rich relational metadata so similarity search can be combined with SQL filtering and joins", "Choose index strategy and distance metric intentionally based on retrieval quality, latency, and update patterns", "Keep embedding model versions explicit so vectors can be re-embedded safely during migrations", "Use PostgreSQL for source-of-truth metadata and pgvector for retrieval rather than duplicating metadata into many parallel stores", "Benchmark exact and approximate search behavior on real query distributions before production rollout", "Partition or namespace data logically by tenant, corpus, or environment to keep retrieval predictable", "Track embedding generation, index rebuilds, and query latency as part of normal database observability"], "securityGuidance": "Embeddings are derived from source content and inherit its sensitivity — similarity search without an ownership predicate is cross-tenant retrieval, so every query carries the owner/tenant filter (and RLS enforces it even when application code forgets). Parameterize the vector literal like any input, remember HNSW/IVFFlat indexes are approximate (a recall miss is a correctness bug, not a security control), and dumps of the table carry the embeddings: back up under the same policy as the source text.", "configurationTemplate": "CREATE EXTENSION IF NOT EXISTS vector;\nCREATE TABLE documents (\n  id bigserial PRIMARY KEY,\n  owner_id uuid NOT NULL,\n  content text,\n  embedding vector(1536)\n);\nCREATE INDEX ON documents USING hnsw (embedding vector_cosine_ops);\n-- query: ORDER BY embedding <=> $1 LIMIT 5, always with the owner filter\nSELECT id, content FROM documents WHERE owner_id = $2 ORDER BY embedding <=> $1 LIMIT 5;"}', '[{"kind": "schema", "path": "db/extensions/pgvector.sql", "priority": "essential", "description": "PostgreSQL extension enablement and vector column definitions for pgvector-backed retrieval"}, {"kind": "schema", "path": "db/migrations/embedding-indexes.sql", "priority": "recommended", "description": "Migration scripts for vector indexes, distance operators, and tenant-aware retrieval structures"}, {"kind": "source", "path": "src/retrieval/pgvector-store.ts", "priority": "essential", "description": "Application retrieval adapter for upserting embeddings and executing similarity search against pgvector"}, {"kind": "config", "path": "src/retrieval/embedding-config.json", "priority": "recommended", "description": "Embedding model, dimension, distance metric, and namespace configuration for pgvector usage"}]', '{"indexType": {"type": "string", "label": "Index Type", "default": "hnsw", "options": ["hnsw", "ivfflat", "exact"], "description": "Primary ANN or exact search strategy for pgvector collections"}, "distanceMetric": {"type": "string", "label": "Distance Metric", "default": "cosine", "options": ["cosine", "l2", "inner-product"], "description": "Primary similarity metric used for vector search"}, "embeddingDimensions": {"type": "number", "label": "Embedding Dimensions", "default": 1536, "description": "Expected vector dimensionality for stored embeddings"}}', '["database", "ai-service", "llm-gateway", "backend-service", "ml-pipeline"]', false, NULL, NULL, '2026-03-17 03:20:36.070813+00', '2026-08-30 12:07:23.877005+00', NULL, '#295372', '''add'':9B ''alreadi'':35B ''ann'':77B ''applic'':34B,150C ''approxim'':164C ''architectur'':104B ''back'':184C ''beyond'':100B ''billion'':88B ''billion-scal'':87B ''bug'':171C ''carri'':140C,181C ''choos'':56B ''close'':24B ''code'':151C ''comfort'':107B ''content'':121C ''control'':175C ''correct'':170C ''cross'':134C ''cross-ten'':133C ''data'':27B ''databas'':19B,53B ''demand'':86B ''depend'':36B ''deriv'':118C ''direct'':15B ''dump'':177C ''earli'':55B ''embed'':23B,116C,183C ''enforc'':146C ''even'':148C ''everi'':138C ''extens'':7B ''extrem'':75B ''extreme-scal'':74B ''fastapi'':114C ''filter'':47B,143C ''forget'':152C ''high'':92B ''hnsw/ivfflat'':161C ''horizont'':98B ''hybrid'':46B ''independ'':97B ''index'':14B,162C ''infrastructur'':95B ''inherit'':123C ''input'':159C ''insid'':16B ''introduc'':49B ''join'':67B ''keep'':22B ''langchain'':111C ''let'':20B ''like'':157C ''liter'':156C ''llamaindex'':112C ''matter'':71B ''metadata'':29B ''miss'':167C ''openai'':113C ''oper'':64B ''owner/tenant'':142C ''ownership'':130C ''parameter'':153C ''pgvector'':1A,2A,3B,57B ''polici'':189C ''postgresql'':6B,38B,103B,108C ''predic'':131C ''proxim'':70B ''psycopg'':110C ''queri'':139C ''recal'':166C ''redi'':115C ''relat'':18B ''rememb'':160C ''retriev'':44B,94B,136C ''rls'':145C ''scale'':76B,89B,99B ''search'':12B,43B,91B,127C ''secur'':174C ''semant'':42B ''sensit'':125C ''separ'':51B ''similar'':11B,126C ''simplic'':65B ''sourc'':120C,192C ''special'':78B,93B ''sql'':66B ''sqlalchemi'':109C ''standalon'':60B ''store'':62B ''support'':106B ''tabl'':180C ''team'':21B ''tenant'':135C ''text'':193C ''transact'':26B,69B ''use'':30B,81B ''vector'':10B,52B,61B,90B,155C ''want'':41B ''without'':48B,128C ''workload'':85B');
INSERT INTO public.technology_catalog VALUES ('nextjs', 'Next.js', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/nextjs.png', '#000000', '["frontend-app", "backend-service"]', '{"purpose": "Full-stack React framework with server-side rendering, static generation, API routes, and edge middleware", "configMode": "code", "provenance": {"notes": "Turbopack is stable and the DEFAULT bundler for dev and build since Next.js 16; App Router is the default template. Model knowledge would have shipped webpack-default.", "method": "live-docs", "sources": ["https://nextjs.org/blog/next-16", "https://nextjs.org/docs/app/api-reference/turbopack"], "verifiedAt": "2026-07-27"}, "typicalTech": ["Next.js 14+", "React 18+", "TypeScript", "App Router", "Server Components", "Server Actions", "Prisma/Drizzle"], "antiPatterns": ["Adding \"use client\" to every component instead of keeping components server-rendered by default", "Fetching data in Client Components when Server Components can access the DB directly", "Not using loading.tsx and error.tsx for streaming and error boundaries", "Importing server-only code in Client Components leaking secrets", "Using getServerSideProps/getStaticProps patterns from Pages Router in App Router"], "apiReference": {"docsUrl": "https://nextjs.org/docs"}, "bestPractices": ["Use App Router with server components by default", "Implement proper loading.tsx and error.tsx boundaries", "Use server actions for form mutations", "Leverage ISR for content that changes occasionally", "Use Route Handlers for API endpoints", "Implement middleware for auth and redirects", "Use next/image for automatic image optimization", "Implement proper metadata for SEO"], "sdkInitPattern": "npx create-next-app@latest my-app --typescript --tailwind --eslint --app --src-dir && cd my-app\\n// src/app/page.tsx\\nexport default function Home() {\\n  return <main><h1>Hello Next.js</h1></main>;\\n}", "securityGuidance": "Server Components run on the server only -- never expose secrets in Client Components. Use environment variables with NEXT_PUBLIC_ prefix only for truly public values. Validate all Server Action inputs. Use next/headers for reading cookies server-side. Set security headers in next.config.js or middleware. Use middleware.ts for route-level authentication checks before rendering.", "commonApiPatterns": [{"name": "Server Component with Data", "description": "React Server Component with direct database access (no API needed)", "codeTemplate": "// src/app/users/page.tsx\\nexport default async function UsersPage() {\\n  const users = await db.user.findMany();\\n  return (\\n    <ul>\\n      {users.map(u => <li key={u.id}>{u.name}</li>)}\\n    </ul>\\n  );\\n}"}, {"name": "Server Action", "description": "Server Action for form mutation with cache revalidation", "codeTemplate": "\"use server\";\\nexport async function createUser(formData: FormData) {\\n  const name = formData.get(\"name\") as string;\\n  const user = await db.user.create({ data: { name } });\\n  revalidatePath(\"/users\");\\n  return user;\\n}"}, {"name": "Route Handler", "description": "API Route Handler with GET and POST methods", "codeTemplate": "// src/app/api/users/route.ts\\nexport async function GET() {\\n  const users = await db.user.findMany();\\n  return Response.json(users);\\n}\\nexport async function POST(request: Request) {\\n  const body = await request.json();\\n  const user = await db.user.create({ data: body });\\n  return Response.json(user, { status: 201 });\\n}"}], "integrationPatterns": ["App Router with Server Components for zero-JS server rendering", "Prisma or Drizzle for type-safe database access from Server Components", "NextAuth.js (Auth.js) for authentication with session management", "Vercel or self-hosted Node.js for deployment", "Playwright or Cypress for end-to-end testing"], "configurationTemplate": "// next.config.ts\\nimport type { NextConfig } from \"next\";\\nconst config: NextConfig = {\\n  experimental: {\\n    typedRoutes: true,\\n  },\\n  images: {\\n    remotePatterns: [{ hostname: \"images.example.com\" }],\\n  },\\n};\\nexport default config;"}', '[{"kind": "source", "path": "src/app/layout.tsx", "language": "typescript", "description": "Root layout"}, {"kind": "source", "path": "src/app/page.tsx", "language": "typescript", "description": "Home page"}, {"kind": "config", "path": "next.config.js", "language": "javascript", "description": "Next.js configuration"}]', '{"router": {"type": "enum", "label": "Router", "default": "app-router", "options": ["app-router", "pages-router-legacy"], "description": "App Router (server components) is the default; Pages Router is maintained for existing apps"}, "bundler": {"type": "enum", "label": "Bundler", "default": "turbopack-default", "options": ["turbopack-default", "webpack-legacy"], "description": "Turbopack is stable and the default for dev AND build since Next.js 16"}, "apiSurface": {"type": "enum", "label": "API surface", "default": "both", "options": ["route-handlers", "server-actions", "both", "none-external-api"]}, "deployment": {"type": "enum", "label": "Deployment", "default": "vercel", "options": ["vercel", "self-hosted-node", "docker", "static-export"], "description": "static-export disables server features (RSC payloads still prerender, but no server actions/ISR)"}, "renderingPosture": {"type": "enum", "label": "Rendering posture", "default": "server-first", "options": ["server-first", "static-heavy", "client-heavy"], "description": "Server-first = RSC by default with client islands; static-heavy leans on prerendering; client-heavy marks most of the tree use-client"}}', '["database", "cache", "auth-provider", "external-service"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-30 12:07:23.877005+00', NULL, '#333333', '''14'':21C ''18'':23C ''action'':30C,91C ''api'':15B ''app'':25C,36C,40C,44C,51C ''authent'':114C ''cd'':48C ''check'':115C ''client'':74C ''compon'':28C,64C,75C ''cooki'':97C ''creat'':34C ''create-next-app'':33C ''default'':55C ''dir'':47C ''edg'':18B ''environ'':77C ''eslint'':43C ''expos'':71C ''framework'':7B ''full'':4B ''full-stack'':3B ''function'':56C ''generat'':14B ''header'':103C ''hello'':60C ''home'':57C ''input'':92C ''latest'':37C ''level'':113C ''middlewar'':19B,107C ''middleware.ts'':109C ''my-app'':38C,49C ''n'':52C,58C,62C ''never'':70C ''nexport'':54C ''next'':35C,80C ''next.config.js'':105C ''next.js'':1A,20C,61C ''next/headers'':94C ''nextj'':2A ''npx'':32C ''prefix'':82C ''prisma/drizzle'':31C ''public'':81C,86C ''react'':6B,22C ''read'':96C ''render'':12B,117C ''return'':59C ''rout'':16B,112C ''route-level'':111C ''router'':26C ''run'':65C ''secret'':72C ''secur'':102C ''server'':10B,27C,29C,63C,68C,90C,99C ''server-sid'':9B,98C ''set'':101C ''side'':11B,100C ''src'':46C ''src-dir'':45C ''src/app/page.tsx'':53C ''stack'':5B ''static'':13B ''tailwind'':42C ''truli'':85C ''typescript'':24C,41C ''use'':76C,93C,108C ''valid'':88C ''valu'':87C ''variabl'':78C');
INSERT INTO public.technology_catalog VALUES ('cloudflare-workers', 'Cloudflare Workers', NULL, '#6b7280', '["serverless-function"]', '{"purpose": "Serverless JavaScript/TypeScript execution at the edge on Cloudflare global network with V8 isolates. Zero cold starts, global deployment, and integrated storage (KV, R2, D1, Durable Objects). Ideal for request routing, API proxies, A/B testing, auth middleware, and lightweight compute.", "configMode": "code", "provenance": {"notes": "Phase B1 additions authored from model knowledge — this row had no prior provenance. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Wrangler CLI", "TypeScript", "Workers KV", "Durable Objects", "R2", "D1"], "antiPatterns": ["Heavy compute exceeding CPU time limits (10ms free / 30s paid)", "Buffering large response bodies in memory (128MB limit)", "Using Workers as a traditional long-running application server", "Storing secrets in source code or wrangler.toml", "Assuming Node.js API availability without compatibility flags", "Cross-origin requests without proper CORS headers"], "apiReference": {"docsUrl": "https://developers.cloudflare.com/workers/"}, "bestPractices": ["Use Wrangler CLI for local dev and deployment", "Leverage KV for read-heavy global state with eventual consistency", "Use Durable Objects when strong consistency or coordination is needed", "Keep worker code small for instant cold starts", "Use wrangler secret for sensitive values instead of environment variables", "Stream large responses instead of buffering", "Use cron triggers for scheduled tasks"], "freshnessNote": "Cloudflare''s direction is Workers-FIRST: static assets deploy on Workers directly (the Pages successor path — a separate Pages node was deliberately not added). Bindings in wrangler.toml are the platform contract; local dev via wrangler/workerd matches production semantics.", "sdkInitPattern": "// src/index.ts — Workers module syntax\r\nexport default {\r\n  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {\r\n    return new Response(''ok'');\r\n  },\r\n};", "securityGuidance": "Secrets go in via wrangler secret put (encrypted bindings) — never committed to wrangler.toml or source. Scope Cloudflare API tokens to the single zone/account an integration needs. Treat every route as public internet: validate input and deny by default. Reach data through bindings (KV, D1, R2, Durable Objects, service bindings) rather than embedding credentials for external calls, and remember Workers are stateless edge isolates — no long-lived in-memory secrets or sessions.", "setupInstructions": [{"url": "https://dash.cloudflare.com/sign-up", "type": "account_setup", "title": "Create Cloudflare Account", "required": true, "instructions": "Sign up for a Cloudflare account. Workers are available on all plans including Free."}, {"type": "toolchain_install", "title": "Install Wrangler CLI", "commands": ["npm install -g wrangler", "wrangler login"], "required": true, "instructions": "Install the Wrangler CLI for local development and deployment."}, {"type": "environment_variable", "title": "Configure wrangler.toml", "required": true, "instructions": "Create a wrangler.toml configuration file with your account ID and worker name."}, {"type": "environment_variable", "title": "Set Worker Secrets", "commands": ["wrangler secret put API_KEY"], "required": false, "instructions": "Add any API keys or secrets your worker needs using wrangler secret."}]}', '[{"kind": "config", "path": "wrangler.toml", "language": "toml", "description": "Worker configuration: name, routes, bindings (secrets set via wrangler secret put, never here)"}, {"kind": "source", "path": "src/index.ts", "language": "typescript", "description": "Worker entry — module-syntax fetch handler"}]', '{"bindings": {"type": "multiselect", "label": "Bindings", "options": ["kv", "r2", "d1", "durable-objects", "queues", "workers-ai", "hyperdrive", "static-assets"], "description": "Platform resources wired into the Worker via wrangler.toml bindings — each is config + a typed env accessor, not an SDK client"}, "triggers": {"type": "multiselect", "label": "Triggers", "options": ["http-fetch", "cron-scheduled", "queue-consumer"], "description": "What invokes this Worker"}, "framework": {"type": "enum", "label": "Framework", "default": "hono", "options": ["hono", "plain-fetch-handler", "full-stack-framework-adapter"], "description": "Hono is the standing Workers framework; framework adapters (Next/Remix/Astro on Workers) for full apps"}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''a/b'':37B ''api'':35B,89C ''async'':59C ''auth'':39B ''bind'':80C,113C,120C ''call'':127C ''cli'':45C ''cloudflar'':1A,3A,12B,88C ''cold'':19B ''commit'':82C ''comput'':43B ''credenti'':124C ''ctx'':65C ''d1'':28B,52C,115C ''data'':111C ''default'':58C,109C ''deni'':107C ''deploy'':22B ''durabl'':29B,49C,117C ''edg'':10B,133C ''embed'':123C ''encrypt'':79C ''env'':63C,64C ''everi'':99C ''execut'':7B ''executioncontext'':66C ''export'':57C ''extern'':126C ''fetch'':60C ''global'':13B,21B ''go'':73C ''ideal'':31B ''in-memori'':139C ''input'':105C ''integr'':24B,96C ''internet'':103C ''isol'':17B,134C ''javascript/typescript'':6B ''kv'':26B,48C,114C ''lightweight'':42B ''live'':138C ''long'':137C ''long-liv'':136C ''memori'':141C ''middlewar'':40B ''modul'':55C ''need'':97C ''network'':14B ''never'':81C ''new'':69C ''object'':30B,50C,118C ''ok'':71C ''promis'':67C ''proxi'':36B ''public'':102C ''put'':78C ''r2'':27B,51C,116C ''rather'':121C ''reach'':110C ''rememb'':129C ''request'':33B,61C,62C ''respons'':70C ''return'':68C ''rout'':34B,100C ''scope'':87C ''secret'':72C,77C,142C ''serverless'':5B ''servic'':119C ''session'':144C ''singl'':93C ''sourc'':86C ''src/index.ts'':53C ''start'':20B ''stateless'':132C ''storag'':25B ''syntax'':56C ''test'':38B ''token'':90C ''treat'':98C ''type