INSERT INTO public.technology_catalog VALUES ('supabase-storage', 'Supabase Storage', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_managed.png', '#3ECF8E', '["object-storage"]', '{"purpose": "S3-compatible object storage integrated with Supabase Auth and RLS. Provides buckets for file uploads (images, documents, media) with access control via RLS policies on storage.objects. Supports signed URLs for temporary access, image transformations, resumable uploads, and CDN-backed delivery. Ideal when your project already uses Supabase and you want unified auth-based file access without managing a separate S3 setup.", "configMode": "declarative", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["@supabase/supabase-js", "Supabase Storage API", "PostgreSQL RLS", "S3-compatible API", "Image Transformations", "Resumable Uploads (TUS protocol)"], "antiPatterns": ["Creating public buckets for user-uploaded content without size/type restrictions", "Not setting RLS policies on storage.objects table (defaults to no access)", "Storing files larger than 5GB without resumable uploads", "Using storage for structured data that belongs in the database", "Hardcoding bucket names instead of using environment configuration", "Not validating file MIME types server-side before accepting uploads"], "apiReference": {"docsUrl": "https://supabase.com/docs/guides/storage"}, "bestPractices": ["Use RLS policies on storage.objects to restrict file access by auth.uid()", "Create separate buckets for different access patterns (public assets vs private uploads)", "Use signed URLs for private file downloads with short expiry (1 hour max)", "Validate file size and MIME type before accepting uploads", "Use image transformations for responsive image delivery instead of storing multiple sizes", "Organize files by user: {bucket}/{user_id}/{filename} for simple RLS policies", "Use resumable uploads (TUS) for files larger than 6MB", "Set appropriate cache-control headers for CDN optimization"], "freshnessNote": "Placement decides the lane: managed includes image transformations; self-hosted this is the open-source storage-api container, and transforms require running imgproxy beside it.", "sdkInitPattern": "import { createClient } from \"@supabase/supabase-js\";\nconst supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);\n\n// Upload file\nconst { data, error } = await supabase.storage\n  .from(\"avatars\")\n  .upload(`${userId}/${filename}`, file, {\n    contentType: file.type,\n    upsert: true\n  });\n\n// Get public URL\nconst { data: { publicUrl } } = supabase.storage\n  .from(\"avatars\")\n  .getPublicUrl(`${userId}/${filename}`);", "securityGuidance": "Enable RLS on storage.objects and storage.buckets tables. Create policies scoped to auth.uid() for user-owned files. Use signed URLs for private content delivery. Restrict allowed MIME types and file sizes in bucket configuration. Never expose service_role key to client code.", "commonApiPatterns": [{"name": "Upload File", "description": "Upload a file to a private bucket with user scoping", "codeTemplate": "const { data, error } = await supabase.storage\n  .from(\"uploads\")\n  .upload(`${userId}/${filename}`, file, {\n    contentType: file.type,\n    cacheControl: \"3600\",\n    upsert: false\n  });"}, {"name": "Download with Signed URL", "description": "Generate a time-limited download URL for private files", "codeTemplate": "const { data, error } = await supabase.storage\n  .from(\"uploads\")\n  .createSignedUrl(`${userId}/${filename}`, 3600);\n// data.signedUrl is valid for 1 hour"}, {"name": "List Files", "description": "List files in a user-scoped folder", "codeTemplate": "const { data, error } = await supabase.storage\n  .from(\"uploads\")\n  .list(userId, {\n    limit: 100,\n    offset: 0,\n    sortBy: { column: \"created_at\", order: \"desc\" }\n  });"}, {"name": "Delete File", "description": "Remove a file from storage", "codeTemplate": "const { error } = await supabase.storage\n  .from(\"uploads\")\n  .remove([`${userId}/${filename}`]);"}], "setupInstructions": [{"url": "https://supabase.com/dashboard/project/_/storage/buckets", "type": "dashboard_config", "title": "Create Storage Bucket", "required": true, "instructions": "In Supabase Dashboard > Storage > New Bucket. Choose public (for assets like avatars) or private (for user files). Name it descriptively (e.g., avatars, documents)."}, {"type": "permissions", "title": "Write RLS Policies on storage.objects", "required": true, "instructions": "Storage uses RLS on the storage.objects table. Write policies that check auth.uid() and bucket_id to control who can upload, download, and delete files."}, {"type": "dashboard_config", "title": "Configure Image Transformations", "required": false, "instructions": "For image buckets, enable image transformations in bucket settings. This allows on-the-fly resizing via URL parameters (width, height, quality)."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export SUPABASE_URL=https://your-project.supabase.co", "export SUPABASE_SERVICE_ROLE_KEY=<from-project-settings>"], "required": true, "instructions": "Use your existing Supabase project credentials. The service role key bypasses RLS for server-side operations."}], "integrationPatterns": ["RLS policies on storage.objects for auth-scoped file access", "Image transformations for responsive delivery (width, height, quality params)", "Database trigger to clean up storage objects when parent record is deleted", "Edge Function for post-upload processing (virus scan, image optimization)"], "configurationTemplate": "-- Create a private bucket\nINSERT INTO storage.buckets (id, name, public)\nVALUES (''uploads'', ''uploads'', false);\n\n-- RLS: Users can upload to their own folder\nCREATE POLICY \"Users can upload own files\"\nON storage.objects FOR INSERT TO authenticated\nWITH CHECK (bucket_id = ''uploads'' AND (storage.foldername(name))[1] = auth.uid()::text);\n\n-- RLS: Users can view own files\nCREATE POLICY \"Users can view own files\"\nON storage.objects FOR SELECT TO authenticated\nUSING (bucket_id = ''uploads'' AND (storage.foldername(name))[1] = auth.uid()::text);\n\n-- RLS: Users can delete own files\nCREATE POLICY \"Users can delete own files\"\nON storage.objects FOR DELETE TO authenticated\nUSING (bucket_id = ''uploads'' AND (storage.foldername(name))[1] = auth.uid()::text);"}', '[{"kind": "config", "path": "supabase/migrations/storage-buckets.sql", "language": "sql", "priority": "essential", "description": "Storage bucket creation and RLS policies"}, {"kind": "source", "path": "src/lib/storage.ts", "language": "typescript", "priority": "essential", "description": "Storage helper functions for upload, download, and signed URLs"}, {"kind": "source", "path": "src/components/FileUpload.tsx", "language": "typescript", "priority": "recommended", "description": "Reusable file upload component with progress and validation"}]', '{"uploads": {"type": "enum", "label": "Upload path", "default": "client-direct", "options": ["client-direct", "server-mediated", "resumable-tus"], "description": "Resumable (TUS) for large files; client-direct with RLS is the default lane"}, "bucketPolicy": {"type": "enum", "label": "Bucket policy", "default": "private-rls", "options": ["private-rls", "public-read", "mixed"], "description": "Access control is Postgres RLS on storage.objects — the policy IS the security model"}, "imageTransforms": {"type": "boolean", "label": "Image transformations", "default": false, "description": "On-the-fly resize/format. Managed: built in. Self-hosted OSS: requires running the imgproxy container"}}', '[]', false, NULL, NULL, '2026-05-16 17:56:17.93653+00', '2026-08-30 12:07:35.06843+00', 'Supabase Storage', NULL, '''access'':25B,37B,62B ''allow'':151C ''alreadi'':51B ''anon'':95C ''api'':72C,78C ''auth'':13B,59B ''auth-bas'':58B ''auth.uid'':137C ''avatar'':105C,122C ''await'':102C ''back'':45B ''base'':60B ''bucket'':17B,158C ''cdn'':44B ''cdn-back'':43B ''client'':166C ''code'':167C ''compat'':7B,77C ''configur'':159C ''const'':89C,99C,117C ''content'':148C ''contenttyp'':110C ''control'':26B ''creat'':133C ''createcli'':86C,91C ''data'':100C,118C ''deliveri'':46B,149C ''document'':22B ''enabl'':126C ''error'':101C ''expos'':161C ''file'':19B,61B,98C,109C,142C,155C ''file.type'':111C ''filenam'':108C,125C ''get'':114C ''getpublicurl'':123C ''ideal'':47B ''imag'':21B,38B,79C ''import'':85C ''integr'':10B ''key'':96C,164C ''manag'':64B ''media'':23B ''mime'':152C ''never'':160C ''object'':8B ''own'':141C ''polici'':29B,134C ''postgresql'':73C ''privat'':147C ''project'':50B ''protocol'':84C ''provid'':16B ''public'':115C ''publicurl'':119C ''restrict'':150C ''resum'':40B,81C ''rls'':15B,28B,74C,127C ''role'':163C ''s3'':6B,67B,76C ''s3-compatible'':5B,75C ''scope'':135C ''separ'':66B ''servic'':162C ''setup'':68B ''sign'':33B,144C ''size'':156C ''storag'':2A,4A,9B,71C ''storage.buckets'':131C ''storage.objects'':31B,129C ''supabas'':1A,3A,12B,53B,70C,90C,92C,94C ''supabase.storage'':103C,120C ''supabase/supabase-js'':69C,88C ''support'':32B ''tabl'':132C ''temporari'':36B ''transform'':39B,80C ''true'':113C ''tus'':83C ''type'':153C ''unifi'':57B ''upload'':20B,41B,82C,97C,106C ''upsert'':112C ''url'':34B,93C,116C,145C ''use'':52B,143C ''user'':140C ''user-own'':139C ''userid'':107C,124C ''via'':27B ''want'':56B ''without'':63B');
INSERT INTO public.technology_catalog VALUES ('cloudflare-r2', 'Cloudflare R2', NULL, '#6b7280', '["object-storage"]', '{"purpose": "S3-compatible object storage with zero egress fees. Ideal for storing user uploads, static assets, backups, and large files with global low-latency access via Cloudflare network.", "configMode": "declarative", "provenance": {"notes": "Phase B7b additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Cloudflare Workers", "S3 SDK", "presigned URLs"], "antiPatterns": ["Using R2 as a database replacement", "Storing secrets or credentials in buckets", "Exposing bucket without access controls"], "apiReference": {"docsUrl": "https://developers.cloudflare.com/r2/"}, "bestPractices": ["Use presigned URLs for direct browser uploads", "Leverage Workers for access control logic", "Use custom domains for public bucket access", "Enable lifecycle rules for cost management"], "freshnessNote": "Zero egress fees is the differentiator vs S3-class storage. With MinIO community edition dead (archived 2026-02), R2''s S3-compatible API is also the low-ops managed lane for S3-tooling workloads.", "sdkInitPattern": "// Worker binding (no keys) — or S3-compatible API with scoped R2 tokens\r\nexport default {\r\n  async fetch(request: Request, env: Env) {\r\n    const obj = await env.ASSETS.get(''report.pdf'');\r\n    return new Response(obj?.body, { headers: { ''content-type'': ''application/pdf'' } });\r\n  },\r\n};", "securityGuidance": "Prefer Worker bindings (no credentials at all) over the S3-compatible API; where S3 clients are required, mint R2 API tokens scoped to the single bucket and permission set, never account-level keys. Buckets are private by default — public access is an explicit decision via custom domains or r2.dev, and presigned URLs with short expiries are the sharing mechanism for private objects.", "setupInstructions": [{"url": "https://dash.cloudflare.com/?to=/:account/r2/new", "type": "dashboard_config", "title": "Create R2 Bucket", "required": true, "instructions": "In Cloudflare Dashboard > R2 > Create Bucket. Choose a bucket name unique within your account. Select the location hint closest to your users."}, {"type": "permissions", "title": "Create API Token", "required": true, "instructions": "Go to R2 > Manage R2 API Tokens > Create API Token. Select the permissions needed (Object Read, Object Write). Restrict to specific buckets if possible."}, {"type": "dashboard_config", "title": "Configure CORS", "required": false, "instructions": "In bucket settings, configure CORS rules to allow your application origin to perform uploads and downloads directly from the browser."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export CLOUDFLARE_ACCOUNT_ID=<from-dashboard>", "export CLOUDFLARE_R2_ACCESS_KEY_ID=<from-api-token>", "export CLOUDFLARE_R2_SECRET_ACCESS_KEY=<from-api-token>", "export CLOUDFLARE_R2_BUCKET_NAME=my-bucket", "export CLOUDFLARE_R2_ENDPOINT=https://<account-id>.r2.cloudflarestorage.com"], "required": true, "instructions": "Add R2 credentials to your application environment. R2 uses S3-compatible API with a Cloudflare-specific endpoint."}]}', '[{"kind": "config", "path": "wrangler.toml", "language": "toml", "description": "R2 bucket bindings for the Worker; tokens only for external S3-compatible clients"}]', '{"access": {"type": "enum", "label": "Access path", "default": "workers-binding", "options": ["workers-binding", "s3-compatible-api", "public-bucket-custom-domain"], "description": "Bindings from Workers; the S3-compatible API for existing S3 tooling; public buckets behind a custom domain for assets"}, "lifecycle": {"type": "boolean", "label": "Lifecycle rules", "default": false, "description": "Expiry/transition rules — unbounded object growth is the default failure"}}', '[]', false, NULL, NULL, '2026-05-18 02:34:18.400748+00', '2026-08-30 12:07:23.877005+00', 'Cloudflare R2', NULL, '''access'':30B,117C ''account'':108C ''account-level'':107C ''api'':48C,88C,96C ''application/pdf'':75C ''asset'':20B ''async'':55C ''await'':63C ''backup'':21B ''bind'':41C,78C ''bodi'':70C ''bucket'':102C,111C ''client'':91C ''cloudflar'':1A,3A,32B,34C ''compat'':7B,47C,87C ''const'':61C ''content'':73C ''content-typ'':72C ''credenti'':80C ''custom'':123C ''decis'':121C ''default'':54C,115C ''domain'':124C ''egress'':12B ''env'':59C,60C ''env.assets.get'':64C ''expiri'':132C ''explicit'':120C ''export'':53C ''fee'':13B ''fetch'':56C ''file'':24B ''global'':26B ''header'':71C ''ideal'':14B ''key'':43C,110C ''larg'':23B ''latenc'':29B ''level'':109C ''low'':28B ''low-lat'':27B ''mechan'':136C ''mint'':94C ''network'':33B ''never'':106C ''new'':67C ''obj'':62C,69C ''object'':8B,139C ''permiss'':104C ''prefer'':76C ''presign'':38C,128C ''privat'':113C,138C ''public'':116C ''r2'':2A,4A,51C,95C ''r2.dev'':126C ''report.pdf'':65C ''request'':57C,58C ''requir'':93C ''respons'':68C ''return'':66C ''s3'':6B,36C,46C,86C,90C ''s3-compatible'':5B,45C,85C ''scope'':50C,98C ''sdk'':37C ''set'':105C ''share'':135C ''short'':131C ''singl'':101C ''static'':19B ''storag'':9B ''store'':16B ''token'':52C,97C ''type'':74C ''upload'':18B ''url'':39C,129C ''user'':17B ''via'':31B,122C ''worker'':35C,40C,77C ''zero'':11B');
INSERT INTO public.technology_catalog VALUES ('aws-s3', 'AWS S3', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-s3.png', '#FF9900', '["object-storage"]', '{"purpose": "AWS''s object storage service providing virtually unlimited, highly durable (99.999999999%) storage for any type of data. Use for static asset hosting, file uploads, data lake storage, backups, log archival, and as an origin for CloudFront CDN. S3 supports storage classes (Standard, Intelligent-Tiering, Glacier) for cost optimization across access patterns. Its event notification system integrates with Lambda, SQS, and SNS for event-driven processing. S3 is the default choice for storing files, media, and unstructured data in AWS architectures. Don''t use for data requiring POSIX filesystem semantics (use EFS instead). Don''t use for structured data that needs querying -- use a database. Avoid S3 Standard for archival data accessed less than once per year -- use S3 Glacier Deep Archive for massive cost savings.", "configMode": "declarative", "provenance": {"notes": "Storage classes incl. EXPRESS_ONEZONE + the July 2026 IA-transition change verified live.", "method": "live-docs", "sources": ["https://docs.aws.amazon.com/AmazonS3/latest/userguide/storage-class-intro.html", "https://aws.amazon.com/s3/storage-classes/", "https://aws.amazon.com/about-aws/whats-new/2026/07/s3-removes-30-day-transitions-standard-ia-one-zone-ia/"], "verifiedAt": "2026-07-27"}, "typicalTech": ["Amazon S3", "AWS SDK", "S3 Transfer Acceleration", "CloudFront", "S3 Event Notifications", "S3 Glacier", "S3 Intelligent-Tiering", "Terraform aws_s3_bucket"], "antiPatterns": ["Leaving buckets publicly accessible without a clear, justified reason", "Not enabling versioning for buckets storing user-uploaded content", "Storing all data in S3 Standard when lifecycle policies could save costs", "Using S3 for real-time database operations requiring low-latency queries", "Not encrypting buckets containing any form of user or business data", "Uploading large files without multipart upload causing timeout failures"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/s3/"}, "bestPractices": ["Block all public access by default and use presigned URLs for temporary access", "Enable versioning for buckets storing important data to protect against accidental deletion", "Use S3 Lifecycle rules to transition objects to cheaper storage classes automatically", "Use server-side encryption (SSE-S3 or SSE-KMS) for all buckets", "Use multipart upload for files larger than 100MB", "Enable S3 access logging or CloudTrail for audit trails", "Use intelligent-tiering for unpredictable access patterns to optimize costs automatically"], "sdkInitPattern": "// Node.js with @aws-sdk/client-s3\\nimport { S3Client, PutObjectCommand, GetObjectCommand } from \"@aws-sdk/client-s3\";\\nimport { getSignedUrl } from \"@aws-sdk/s3-request-presigner\";\\nconst s3 = new S3Client({ region: process.env.AWS_REGION });\\n// [Tailor to project language: Python=boto3.client(\"s3\"), Go=s3.NewFromConfig, Java=S3Client.builder()]", "securityGuidance": "Enable S3 Block Public Access at the account level as a guardrail. Use bucket policies with least-privilege IAM principals. Enable server-side encryption on all buckets. Use VPC endpoints for S3 access from private subnets. Use presigned URLs for temporary access instead of making objects public. Enable MFA Delete for versioned buckets containing critical data.", "commonApiPatterns": [{"name": "Upload Object", "description": "Upload file with server-side encryption", "codeTemplate": "await s3.send(new PutObjectCommand({\\n  Bucket: \"my-bucket\",\\n  Key: `uploads/${userId}/${filename}`,\\n  Body: fileBuffer,\\n  ContentType: contentType,\\n  ServerSideEncryption: \"AES256\"\\n}));"}, {"name": "Presigned URL", "description": "Generate time-limited presigned URL for secure download", "codeTemplate": "const url = await getSignedUrl(s3, new GetObjectCommand({\\n  Bucket: \"my-bucket\",\\n  Key: `uploads/${userId}/${filename}`\\n}), { expiresIn: 3600 });\\n// Return url to client for temporary download access"}, {"name": "List Objects", "description": "List objects by prefix with pagination", "codeTemplate": "import { ListObjectsV2Command } from \"@aws-sdk/client-s3\";\\nconst { Contents = [] } = await s3.send(new ListObjectsV2Command({\\n  Bucket: \"my-bucket\",\\n  Prefix: `uploads/${userId}/`,\\n  MaxKeys: 100\\n}));"}, {"name": "Delete Object", "description": "Delete a single object", "codeTemplate": "import { DeleteObjectCommand } from \"@aws-sdk/client-s3\";\\nawait s3.send(new DeleteObjectCommand({ Bucket: \"my-bucket\", Key: objectKey }));"}], "setupInstructions": [{"url": "https://console.aws.amazon.com/s3/", "type": "dashboard_config", "title": "Create S3 Bucket", "required": true, "instructions": "In AWS Console > S3 > Create Bucket. Choose a globally unique name and region. Enable or disable versioning based on your needs."}, {"type": "permissions", "title": "Configure Bucket Access", "required": true, "instructions": "Set the bucket to private by default. Configure a bucket policy for least-privilege access. For public assets, use CloudFront distribution instead of making the bucket public."}, {"type": "dashboard_config", "title": "Configure CORS for Browser Uploads", "required": false, "instructions": "Under Permissions > CORS, add a CORS configuration allowing your application origin to perform PUT/POST for direct uploads from the browser."}, {"type": "permissions", "title": "Create IAM User or Role", "required": true, "instructions": "Create an IAM user (for server-side) or IAM role (for AWS services) with minimum S3 permissions: s3:GetObject, s3:PutObject, s3:DeleteObject on the specific bucket ARN."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export AWS_ACCESS_KEY_ID=<from-iam-user>", "export AWS_SECRET_ACCESS_KEY=<from-iam-user>", "export AWS_S3_BUCKET_NAME=my-app-uploads", "export AWS_REGION=us-east-1"], "required": true, "instructions": "Add AWS credentials and bucket info to your application environment."}], "integrationPatterns": ["CloudFront as CDN origin for global static asset delivery", "S3 Event Notifications + Lambda for serverless file processing pipelines", "S3 Lifecycle rules for automated archival to Glacier for long-term storage"], "configurationTemplate": "resource \"aws_s3_bucket\" \"assets\" {\\n  bucket = \"${var.project}-assets\"\\n}\\nresource \"aws_s3_bucket_versioning\" \"assets\" {\\n  bucket = aws_s3_bucket.assets.id\\n  versioning_configuration { status = \"Enabled\" }\\n}\\nresource \"aws_s3_bucket_server_side_encryption_configuration\" \"assets\" {\\n  bucket = aws_s3_bucket.assets.id\\n  rule { apply_server_side_encryption_by_default { sse_algorithm = \"AES256\" } }\\n}\\nresource \"aws_s3_bucket_public_access_block\" \"assets\" {\\n  bucket                  = aws_s3_bucket.assets.id\\n  block_public_acls       = true\\n  block_public_policy     = true\\n  ignore_public_acls      = true\\n  restrict_public_buckets = true\\n}"}', '[{"kind": "config", "path": "infra/aws/s3.tf"}]', '{"encryption": {"type": "enum", "label": "Encryption", "default": "SSE-S3", "options": ["SSE-S3", "SSE-KMS", "DSSE-KMS"], "description": "Server-side encryption mode"}, "versioning": {"type": "boolean", "label": "Versioning", "default": true, "description": "Protects user-uploaded content against accidental deletion/overwrite"}, "storageClass": {"type": "enum", "label": "Default storage class", "default": "STANDARD", "options": ["STANDARD", "INTELLIGENT_TIERING", "EXPRESS_ONEZONE", "STANDARD_IA", "ONEZONE_IA", "GLACIER_IR", "GLACIER", "DEEP_ARCHIVE"], "description": "Per-object default; lifecycle rules can transition later (the 30-day minimum for IA transitions was removed July 2026)"}, "blockPublicAccess": {"type": "boolean", "label": "Block public access", "default": true, "description": "Keep ON; use presigned URLs for temporary access"}, "staticWebsiteHosting": {"type": "boolean", "label": "Static website hosting", "default": false, "description": "Serve as a website origin (usually behind CloudFront)"}}', '["backend-service", "serverless-function", "frontend-app", "cdn"]', false, NULL, NULL, '2026-02-20 14:51:11.165373+00', '2026-08-30 12:07:23.877005+00', NULL, '#CC7A00', '''/client-s3'':158C,167C ''/s3-request-presigner'':174C ''99.999999999'':15B ''acceler'':138C ''access'':55B,117B,198C,228C,237C ''account'':201C ''across'':54B ''amazon'':132C ''architectur'':86B ''archiv'':34B,115B,127B ''asset'':25B ''avoid'':111B ''aw'':1A,3A,5B,85B,134C,150C,156C,165C,172C ''aws-sdk'':155C,164C,171C ''backup'':32B ''block'':196C ''boto3.client'':188C ''bucket'':152C,207C,222C,248C ''cdn'':41B ''choic'':76B ''class'':45B ''cloudfront'':40B,139C ''contain'':249C ''cost'':52B,130B ''critic'':250C ''data'':21B,29B,83B,91B,104B,116B,251C ''databas'':110B ''deep'':126B ''default'':75B ''delet'':245C ''driven'':70B ''durabl'':14B ''ef'':97B ''enabl'':194C,215C,243C ''encrypt'':219C ''endpoint'':225C ''event'':58B,69B,141C ''event-driven'':68B ''file'':27B,79B ''filesystem'':94B ''getobjectcommand'':162C ''getsignedurl'':169C ''glacier'':50B,125B,144C ''go'':190C ''guardrail'':205C ''high'':13B ''host'':26B ''iam'':213C ''instead'':98B,238C ''integr'':61B ''intellig'':48B,147C ''intelligent-ti'':47B,146C ''java'':192C ''lake'':30B ''lambda'':63B ''languag'':186C ''least'':211C ''least-privileg'':210C ''less'':118B ''level'':202C ''log'':33B ''make'':240C ''massiv'':129B ''media'':80B ''mfa'':244C ''n'':182C ''nconst'':175C ''need'':106B ''new'':177C ''nimport'':159C,168C ''node.js'':153C ''notif'':59B,142C ''object'':7B,241C ''optim'':53B ''origin'':38B ''pattern'':56B ''per'':121B ''polici'':208C ''posix'':93B ''presign'':233C ''princip'':214C ''privat'':230C ''privileg'':212C ''process'':71B ''process.env.aws'':180C ''project'':185C ''provid'':10B ''public'':197C,242C ''putobjectcommand'':161