INSERT INTO public.technology_catalog VALUES ('litellm', 'LiteLLM', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/litellm.png', '#7C3AED', '["inference-service"]', '{"purpose": "Provides a unified OpenAI-compatible gateway for routing, securing, observing, and managing access to multiple LLM providers and models.", "configMode": "declarative", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["OpenAI", "Claude", "Gemini", "Vertex AI", "SageMaker", "LangChain", "LangGraph", "Redis", "PostgreSQL", "OpenTelemetry"], "antiPatterns": ["Calling every upstream model provider directly from app code while also adding LiteLLM, which defeats the gateway abstraction.", "Treating LiteLLM as an orchestration framework for agent state or business workflows instead of as the model access control plane.", "Embedding provider-specific prompts, auth rules, or retry logic in multiple services rather than centralizing them behind the gateway.", "Running production traffic through a gateway without explicit model aliasing, quotas, or fallback rules."], "apiReference": {"docsUrl": "https://docs.litellm.ai/"}, "bestPractices": ["Place LiteLLM between application services or agents and upstream model providers to centralize routing, authentication, budgets, and failover.", "Configure provider credentials and model aliases through environment variables or config files rather than hardcoding them in application code.", "Use model routing, fallback policies, and spend limits to separate cost control concerns from business logic.", "Pair the gateway with observability and logging systems so token usage, latency, and failures can be traced across agent workflows."], "securityGuidance": "The proxy concentrates every provider key you own — config references them via os.environ, never literals in config.yaml, and the master key is admin power (it mints virtual keys): rotate it like a root credential. Issue per-team/per-app virtual keys with budgets, rate limits, and model allow-lists so one leaked consumer key cannot drain every provider account, keep the admin UI and /key endpoints off the public internet, and audit spend per key — the gateway is exactly where runaway-cost detection belongs.", "configurationTemplate": "# litellm/config.yaml — one gateway, many providers\nmodel_list:\n  - model_name: gpt-4o\n    litellm_params:\n      model: azure/gpt-4o\n      api_base: os.environ/AZURE_API_BASE\n      api_key: os.environ/AZURE_API_KEY\n  - model_name: claude\n    litellm_params:\n      model: anthropic/claude-sonnet-5\n      api_key: os.environ/ANTHROPIC_API_KEY\ngeneral_settings:\n  master_key: os.environ/LITELLM_MASTER_KEY"}', '[{"kind": "config", "path": "litellm.config.yaml", "language": "yaml", "description": "Primary LiteLLM gateway configuration defining models, routing, fallbacks, budgets, and provider settings."}, {"kind": "build", "path": "docker-compose.yml", "language": "yaml", "description": "Container orchestration file for running the LiteLLM gateway alongside supporting services in local or shared environments."}, {"kind": "doc", "path": "docs/ai-gateway.md", "language": "markdown", "description": "Architecture documentation describing gateway responsibilities, allowed upstream providers, and model routing policies."}, {"kind": "source", "path": "src/lib/ai/client.ts", "language": "typescript", "description": "Application client wrapper that sends model requests to LiteLLM instead of directly to upstream providers."}]', '{"type": "object", "properties": {"baseUrl": {"type": "string", "title": "Gateway Base URL", "description": "Base URL used by clients and agents to call the LiteLLM gateway."}, "authMode": {"enum": ["api-key", "service-token", "oidc", "internal-network"], "type": "string", "title": "Gateway Auth Mode", "description": "How clients authenticate to the gateway."}, "budgetScope": {"enum": ["user", "project", "team", "organization"], "type": "string", "title": "Budget Scope", "description": "Primary unit for spend controls and rate limits."}, "primaryModels": {"type": "array", "items": {"type": "string"}, "title": "Primary Model Aliases", "description": "Logical model names exposed through the gateway for default usage."}, "fallbackModels": {"type": "array", "items": {"type": "string"}, "title": "Fallback Model Aliases", "description": "Models used when the preferred route fails, is throttled, or exceeds policy."}}, "additionalProperties": false}', '["ai-service", "rest-api", "monitoring", "logging", "tracing"]', false, NULL, NULL, '2026-03-09 03:59:27.499903+00', '2026-08-30 12:07:23.877005+00', NULL, '#1F2937', '''/key'':99C ''/per-app'':72C ''access'':16B ''account'':93C ''admin'':56C,96C ''ai'':27C ''allow'':82C ''allow-list'':81C ''audit'':106C ''belong'':119C ''budget'':76C ''cannot'':89C ''claud'':24C ''compat'':8B ''concentr'':36C ''config'':42C ''config.yaml'':50C ''consum'':87C ''cost'':117C ''credenti'':67C ''detect'':118C ''drain'':90C ''endpoint'':100C ''everi'':37C,91C ''exact'':113C ''gateway'':9B,111C ''gemini'':25C ''internet'':104C ''issu'':68C ''keep'':94C ''key'':39C,54C,61C,74C,88C,109C ''langchain'':29C ''langgraph'':30C ''leak'':86C ''like'':64C ''limit'':78C ''list'':83C ''litellm'':1A,2A ''liter'':48C ''llm'':19B ''manag'':15B ''master'':53C ''mint'':59C ''model'':22B,80C ''multipl'':18B ''never'':47C ''observ'':13B ''one'':85C ''openai'':7B,23C ''openai-compat'':6B ''opentelemetri'':33C ''os.environ'':46C ''per'':70C,108C ''per-team'':69C ''postgresql'':32C ''power'':57C ''provid'':3B,20B,38C,92C ''proxi'':35C ''public'':103C ''rate'':77C ''redi'':31C ''refer'':43C ''root'':66C ''rotat'':62C ''rout'':11B ''runaway'':116C ''runaway-cost'':115C ''sagemak'':28C ''secur'':12B ''spend'':107C ''team'':71C ''ui'':97C ''unifi'':5B ''vertex'':26C ''via'':45C ''virtual'':60C,73C');
INSERT INTO public.technology_catalog VALUES ('gitlab-ci', 'GitLab CI', NULL, '#6b7280', '["ci-cd-pipeline"]', '{"purpose": "Built-in CI/CD for GitLab with Auto DevOps, container registry, and integrated deployment environments. Pipelines defined in .gitlab-ci.yml with stages, jobs, and rules.", "configMode": "definition-as-code", "provenance": {"notes": "Phase B8c additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["YAML", "Docker", "Kubernetes", "bash"], "antiPatterns": ["Storing secrets in .gitlab-ci.yml", "Running all jobs in a single stage", "Not using cache between pipeline runs", "Over-using allow_failure without investigation"], "apiReference": {"docsUrl": "https://docs.gitlab.com/ci/"}, "bestPractices": ["Use stages to organize pipeline flow", "Leverage includes for DRY pipeline config", "Use rules instead of only/except for job conditions", "Cache and artifacts for build optimization", "Use protected variables for sensitive environments"], "securityGuidance": "Mark CI/CD variables protected + masked and scope them to protected branches/environments — an unprotected secret is readable by any branch pipeline, including one opened from a fork or by any developer. Prefer OIDC (id_tokens) federation to cloud providers over long-lived keys stored as variables, pin job images by digest, review changes to .gitlab-ci.yml like deploy-pipeline changes (they are), and give environment-gated jobs required approvals so a merge alone cannot reach production.", "setupInstructions": [{"type": "manual_workflow", "title": "Create Pipeline Configuration", "commands": ["touch .gitlab-ci.yml"], "required": true, "instructions": "Create .gitlab-ci.yml in your repository root. Define stages (build, test, deploy) and jobs. GitLab automatically detects and runs pipelines on push."}, {"url": "https://docs.gitlab.com/ee/ci/variables/", "type": "environment_variable", "title": "Configure CI/CD Variables", "required": true, "instructions": "In your project Settings > CI/CD > Variables, add variables for API keys, deployment credentials, and tokens. Mark sensitive values as Masked and Protected."}, {"type": "permissions", "title": "Set Up Protected Environments", "required": false, "instructions": "In Settings > CI/CD > Protected environments, configure environments that require approval before deployment. Set allowed deployers and approvers."}, {"type": "toolchain_install", "title": "Register GitLab Runner", "commands": ["# Install runner:", "curl -L https://packages.gitlab.com/install/repositories/runner/gitlab-runner/script.deb.sh | sudo bash", "sudo apt-get install gitlab-runner", "# Register:", "sudo gitlab-runner register"], "required": false, "instructions": "For self-hosted runners, install and register a GitLab Runner. Configure executor type (Docker, shell, Kubernetes). Shared runners on gitlab.com are available by default."}], "configurationTemplate": "# .gitlab-ci.yml\nstages: [test, build, deploy]\ntest:\n  stage: test\n  image: node:20\n  script: [npm ci, npm test]\ndeploy:\n  stage: deploy\n  environment: production\n  rules:\n    - if: $CI_COMMIT_BRANCH == $CI_DEFAULT_BRANCH\n  script: [./deploy.sh]"}', '[{"kind": "config", "path": ".gitlab-ci.yml", "language": "yaml", "description": "Pipeline stages; protected+masked variables, OIDC to cloud providers"}]', '{"runners": {"type": "enum", "label": "Runners", "default": "gitlab-hosted", "options": ["gitlab-hosted", "self-hosted"]}, "pipelineStyle": {"type": "enum", "label": "Pipeline style", "default": "includes-and-templates", "options": ["single-gitlab-ci-yml", "includes-and-templates"], "description": "Shared includes/templates once more than one repo pipelines — copy-pasted YAML is the drift generator"}, "supplyChainSecurity": {"type": "multiselect", "label": "Supply-chain security steps", "options": ["vulnerability-scan-trivy-grype", "sbom-generation-syft", "artifact-signing-cosign", "iac-scanning", "none-yet"], "description": "Security steps IN this pipeline (the 4i-1 ruling: scanners/signers are pipeline configuration, not nodes)"}}', '[]', false, NULL, NULL, '2026-05-18 02:39:19.313183+00', '2026-08-30 12:07:23.877005+00', 'GitLab CI', NULL, '''alon'':106C ''approv'':102C ''auto'':12B ''bash'':32C ''branch'':51C ''branches/environments'':43C ''built'':6B ''built-in'':5B ''cannot'':107C ''chang'':85C,92C ''ci'':2A,4A ''ci/cd'':8B,34C ''cloud'':69C ''contain'':14B ''defin'':21B ''deploy'':18B,90C ''deploy-pipelin'':89C ''develop'':62C ''devop'':13B ''digest'':83C ''docker'':30C ''environ'':19B,98C ''environment-g'':97C ''feder'':67C ''fork'':58C ''gate'':99C ''gitlab'':1A,3A,10B ''gitlab-ci.yml'':23B,87C ''give'':96C ''id'':65C ''imag'':81C ''includ'':53C ''integr'':17B ''job'':26B,80C,100C ''key'':75C ''kubernet'':31C ''like'':88C ''live'':74C ''long'':73C ''long-liv'':72C ''mark'':33C ''mask'':37C ''merg'':105C ''oidc'':64C ''one'':54C ''open'':55C ''pin'':79C ''pipelin'':20B,52C,91C ''prefer'':63C ''product'':109C ''protect'':36C,42C ''provid'':70C ''reach'':108C ''readabl'':48C ''registri'':15B ''requir'':101C ''review'':84C ''rule'':28B ''scope'':39C ''secret'':46C ''stage'':25B ''store'':76C ''token'':66C ''unprotect'':45C ''variabl'':35C,78C ''yaml'':29C');
INSERT INTO public.technology_catalog VALUES ('azure-app-service', 'Azure App Service', NULL, '#0078D4', '["backend-service"]', '{"purpose": "Azure App Service is a managed PaaS for hosting web applications, APIs, and background jobs without operating virtual machines or Kubernetes clusters. Use it for standard backend services that need autoscaling, deployment slots, managed TLS, and streamlined CI/CD with low platform overhead. Choose App Service over Azure Functions when the workload is an always-on application process and over AKS when you do not need Kubernetes primitives, sidecars, or cluster-level platform control. Do not use it for highly customized container platforms, advanced service-mesh patterns, or workloads that require deep orchestration and node-level tuning.", "configMode": "declarative", "provenance": {"notes": "Phase B1 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Azure App Service", "Azure SQL Database", "Azure Functions", "Azure Application Insights", "Azure Key Vault", "Azure Front Door", "Azure Container Registry"], "antiPatterns": ["Using App Service when Kubernetes operators, sidecars, or custom networking are core requirements", "Treating deployment slots as permanent unmanaged environments with configuration drift", "Embedding secrets directly in application code, container images, or repository files", "Assuming local disk is durable for stateful business data", "Ignoring scaling behavior and regional quota constraints during production planning", "Consolidating unrelated noisy-neighbor workloads into a single shared App Service plan"], "apiReference": {"docsUrl": "https://learn.microsoft.com/azure/app-service/"}, "bestPractices": ["Use deployment slots for staged rollouts, smoke tests, and fast rollback", "Store secrets in Key Vault and reference them through application settings", "Enable autoscaling rules aligned to CPU, memory, and request-driven metrics", "Use managed identities for secure access to databases, storage, and Azure APIs", "Configure health checks and always-on behavior for production backend services", "Keep environment-specific configuration isolated to avoid drift between stages", "Instrument the service with Application Insights and structured logging from the start"], "securityGuidance": "Use the app''s managed identity for databases, storage, and Key Vault — never embed connection strings with credentials. Reference secrets as Key Vault app settings. Enforce HTTPS-only with minimum TLS 1.2, disable FTP/FTPS deployment, and put internal APIs behind VNet integration + private endpoints. Use Easy Auth (App Service Authentication) rather than hand-rolled login for user-facing apps.", "configurationTemplate": "# Create the app on an existing plan, then bind settings to Key Vault\r\naz webapp create --resource-group my-rg --plan my-plan --name my-app --runtime \"NODE:20-lts\"\r\naz webapp config appsettings set --resource-group my-rg --name my-app \\\r\n  --settings DB_PASSWORD=''@Microsoft.KeyVault(SecretUri=https://my-kv.vault.azure.net/secrets/db-password/)''"}', '[{"kind": "source", "path": "src/server/app.ts", "priority": "essential", "description": "Primary web application or API entrypoint for App Service"}, {"kind": "config", "path": "azure/webapp-config.json", "priority": "recommended", "description": "App Service site configuration and deployment settings"}, {"kind": "config", "path": ".github/workflows/deploy-app-service.yml", "priority": "recommended", "description": "CI/CD workflow for App Service deployments"}]', '{"os": {"type": "enum", "label": "Operating System", "default": "linux", "options": ["linux", "windows"], "description": "Underlying App Service runtime OS"}, "alwaysOn": {"type": "boolean", "label": "Always On", "default": true, "description": "Keep the app warm for production workloads"}, "deploymentSlot": {"type": "boolean", "label": "Deployment Slot", "default": true, "description": "Enable deployment slot support for staged releases"}}', '["database", "cache", "auth-provider", "monitoring", "load-balancer"]', false, NULL, NULL, '2026-03-14 15:29:57.538666+00', '2026-08-30 12:07:23.877005+00', NULL, '#005FAA', '''1.2'':159C ''advanc'':91B ''ak'':67B ''alway'':61B ''always-on'':60B ''api'':18B,166C ''app'':2A,5A,8B,50B,108C,129C,150C,175C,188C ''applic'':17B,63B,116C ''auth'':174C ''authent'':177C ''autosc'':37B ''azur'':1A,4A,7B,53B,107C,110C,113C,115C,118C,121C,124C ''backend'':33B ''background'':20B ''behind'':167C ''choos'':49B ''ci/cd'':44B ''cluster'':28B,78B ''cluster-level'':77B ''connect'':141C ''contain'':89B,125C ''control'':81B ''credenti'':144C ''custom'':88B ''databas'':112C,134C ''deep'':100B ''deploy'':38B,162C ''disabl'':160C ''door'':123C ''easi'':173C ''emb'':140C ''endpoint'':171C ''enforc'':152C ''face'':187C ''front'':122C ''ftp/ftps'':161C ''function'':54B,114C ''hand'':181C ''hand-rol'':180C ''high'':87B ''host'':15B ''https'':154C ''https-on'':153C ''ident'':132C ''insight'':117C ''integr'':169C ''intern'':165C ''job'':21B ''key'':119C,137C,148C ''kubernet'':27B,73B ''level'':79B,105B ''login'':183C ''low'':46B ''machin'':25B ''manag'':12B,40B,131C ''mesh'':94B ''minimum'':157C ''need'':36B,72B ''never'':139C ''node'':104B ''node-level'':103B ''oper'':23B ''orchestr'':101B ''overhead'':48B ''paa'':13B ''pattern'':95B ''platform'':47B,80B,90B ''primit'':74B ''privat'':170C ''process'':64B ''put'':164C ''rather'':178C ''refer'':145C ''registri'':126C ''requir'':99B ''roll'':182C ''secret'':146C ''servic'':3A,6A,9B,34B,51B,93B,109C,176C ''service-mesh'':92B ''set'':151C ''sidecar'':75B ''slot'':39B ''sql'':111C ''standard'':32B ''storag'':135C ''streamlin'':43B ''string'':142C ''tls'':41B,158C ''tune'':106B ''use'':29B,84B,127C,172C ''user'':186C ''user-fac'':185C ''vault'':120C,138C,149C ''virtual'':24B ''vnet'':168C ''web'':16B ''without'':22B ''worklo