INSERT INTO public.technology_catalog VALUES ('influxdb', 'InfluxDB', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/influxdb.png', '#22adf6', '["time-series-db"]', '{"purpose": "Purpose-built time-series database optimized for high-throughput ingestion, compression, and real-time querying of timestamped data. Use for IoT sensor data, application metrics and monitoring, infrastructure observability, financial tick data, and any workload where data points are primarily appended with a timestamp. InfluxDB excels at downsampling, retention policies, and continuous queries over time-ordered data. Don''t use as a general-purpose database for relational or document data -- it lacks joins, transactions, and flexible querying beyond time-series patterns. Don''t use for workloads where you need complex ad-hoc queries across non-time dimensions. Avoid for small datasets where PostgreSQL with time-based indexes would suffice. Consider TimescaleDB if you need time-series features within a PostgreSQL-compatible engine.", "configMode": "declarative", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["InfluxDB 3+", "Telegraf", "Grafana", "InfluxDB Cloud", "Flux query language", "InfluxDB line protocol", "Chronograf", "Kapacitor"], "antiPatterns": ["Using high-cardinality values (UUIDs, email addresses) as tags causing series explosion", "Writing individual data points instead of batching causing high overhead", "Not setting retention policies letting data grow unbounded", "Querying unbounded time ranges without LIMIT causing memory exhaustion", "Storing non-time-series relational data in InfluxDB", "Ignoring series cardinality limits until the database becomes unresponsive"], "apiReference": {"docsUrl": "https://docs.influxdata.com/"}, "bestPractices": ["Design measurement names and tag sets around your query patterns", "Use tags for indexed metadata (low cardinality) and fields for values (high cardinality)", "Set retention policies to automatically expire old data and save storage", "Use batch writes to maximize ingestion throughput", "Create continuous queries or tasks for pre-aggregated dashboards", "Monitor series cardinality -- high cardinality tags degrade performance", "Use InfluxDB 3.0 (Flux or SQL) for more expressive queries"], "freshnessNote": "InfluxDB 3 is the current line (SQL-native); the v2-era Flux query language is DEPRECATED — an AI generating Flux for a new build is writing against a dead language.", "sdkInitPattern": "// Node.js with @influxdata/influxdb-client\\nimport { InfluxDB, Point } from \"@influxdata/influxdb-client\";\\nconst influx = new InfluxDB({ url: process.env.INFLUX_URL!, token: process.env.INFLUX_TOKEN! });\\nconst writeApi = influx.getWriteApi(\"my-org\", \"my-bucket\", \"s\");\\n// [Tailor to project language: Python=influxdb-client-python, Go=influxdb-client-go, Java=influxdb-client-java]", "securityGuidance": "Use API tokens with scoped read/write permissions per bucket. Enable TLS for all client connections. Restrict network access to InfluxDB ports. Use separate tokens for ingestion agents (write-only) and dashboards (read-only). Rotate API tokens periodically and store them in a secrets manager.", "commonApiPatterns": [{"name": "Write Points", "description": "Write a metric point with tags and fields", "codeTemplate": "const point = new Point(\"cpu\")\\n  .tag(\"host\", \"server01\")\\n  .tag(\"region\", \"us-east\")\\n  .floatField(\"usage_percent\", 73.5)\\n  .timestamp(new Date());\\nwriteApi.writePoint(point);\\nawait writeApi.flush();"}, {"name": "Flux Query", "description": "Query recent data with Flux language", "codeTemplate": "const queryApi = influx.getQueryApi(\"my-org\");\\nconst query = ''from(bucket: \"my-bucket\") |> range(start: -1h) |> filter(fn: (r) => r._measurement == \"cpu\" and r.host == \"server01\") |> mean()'';\\nconst rows = await queryApi.collectRows(query);"}, {"name": "Batch Write", "description": "Batch write multiple points for efficient ingestion", "codeTemplate": "const points = metrics.map(m =>\\n  new Point(m.measurement)\\n    .tag(\"host\", m.host)\\n    .floatField(\"value\", m.value)\\n    .timestamp(m.timestamp)\\n);\\npoints.forEach(p => writeApi.writePoint(p));\\nawait writeApi.flush();"}], "integrationPatterns": ["Telegraf for collecting metrics from servers, containers, databases, and applications", "Grafana for time-series visualization and alerting dashboards", "Kapacitor or InfluxDB tasks for stream processing and alerting"], "configurationTemplate": "# influxdb.conf / environment\\nINFLUXDB_HTTP_BIND_ADDRESS=:8086\\nINFLUXDB_STORAGE_WAL_FSYNC_DELAY=100ms\\nINFLUXDB_STORAGE_CACHE_MAX_MEMORY_SIZE=1073741824\\nINFLUXDB_REPORTING_DISABLED=true\\n# Retention policy: keep 30 days of raw data\\n# Downsampling task: aggregate to 1h intervals after 7 days"}', '[{"kind": "config", "path": "config.yml", "language": "yaml", "description": "InfluxDB server config: TLS, storage paths"}]', '{"majorLine": {"type": "enum", "label": "Line", "default": "influxdb-3", "options": ["influxdb-3", "influxdb-2-legacy"], "description": "InfluxDB 3 (SQL-native, object-storage-backed) is the current line; v2 (Flux language) is legacy — Flux is deprecated, do not write new Flux"}, "retention": {"type": "string", "label": "Retention window", "default": "30d", "description": "Time-series without retention policy fills disks — declare the window"}}', '["backend-service", "monitoring", "iot-device"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#1B8DC6', '''3'':138C ''access'':216C ''across'':104B ''ad'':101B ''ad-hoc'':100B ''agent'':225C ''api'':200C,235C ''append'':47B ''applic'':30B ''avoid'':109B ''base'':118B ''beyond'':86B ''bucket'':177C,207C ''built'':5B ''chronograf'':149C ''client'':187C,192C,197C,212C ''cloud'':