oken'':166C,168C,201C,222C,236C ''transact'':82B ''url'':163C,165C ''use'':25B,67B,93B,199C,220C ''within'':131B ''workload'':41B,95B ''would'':120B ''write'':227C ''write-on'':226C ''writeapi'':170C');
INSERT INTO public.technology_catalog VALUES ('java-backend', 'Java', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/java.png', '#E76F00', '["backend-service", "worker", "webhook-handler", "shared-library", "realtime-service"]', '{"purpose": "Enterprise-grade, cross-platform programming language for building scalable backend services, microservices, and data processing systems on the JVM", "configMode": "code", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Java 21+", "Spring Boot 3", "Quarkus", "Micronaut", "Maven/Gradle", "Hibernate/JPA", "JUnit 5", "Lombok", "MapStruct"], "antiPatterns": ["God classes with too many responsibilities", "Not closing database connections or using try-with-resources", "Catching generic Exception instead of specific types", "Using field injection making classes hard to test", "Exposing JPA entities directly in REST responses", "N+1 query problems from lazy loading without fetch joins", "Not using connection pooling (HikariCP)", "Mutable shared state without proper synchronization"], "apiReference": {"docsUrl": "https://docs.oracle.com/en/java/"}, "bestPractices": ["Use Spring Boot for rapid application development with convention over configuration", "Implement proper layered architecture (Controller, Service, Repository)", "Use Spring Data JPA or Hibernate for ORM with proper entity lifecycle management", "Leverage constructor injection over field injection", "Use records for DTOs and immutable data transfer objects", "Implement proper exception handling with @ControllerAdvice", "Use virtual threads (Project Loom) for I/O-bound workloads on Java 21+", "Write tests with JUnit 5 and Mockito", "Use Spring Actuator for health checks and metrics"], "sdkInitPattern": "@SpringBootApplication\npublic class Application {\n    public static void main(String[] args) {\n        SpringApplication.run(Application.class, args);\n    }\n}\n\n@RestController\n@RequestMapping(\"/api/orders\")\nclass OrderController {\n    @GetMapping\n    List<Order> list(@AuthenticationPrincipal AppUser user) {\n        return orders.findByOwnerId(user.getId());\n    }\n}", "securityGuidance": "Parameterized queries everywhere (JPA/JDBC PreparedStatement — string-concatenated JPQL is injection), bean validation on request DTOs at the boundary, and explicit DTOs rather than entity exposure so mass assignment and lazy-loading leaks cannot happen. Never deserialize untrusted data with Java native serialization — it is the classic RCE class; keep Jackson polymorphic typing off. Secrets come from environment/vault config, dependencies ride a scanned BOM (the ecosystem''s CVE surface is the supply chain), and pin JVM/base images by digest."}', '[{"kind": "source", "path": "src/main/java/com/example/Application.java", "language": "java", "description": "Spring Boot application entry point"}, {"kind": "source", "path": "src/main/java/com/example/controller/", "language": "java", "description": "REST controller definitions"}, {"kind": "source", "path": "src/main/java/com/example/service/", "language": "java", "description": "Business logic services"}, {"kind": "config", "path": "pom.xml", "language": "xml", "description": "Maven project definition"}, {"kind": "config", "path": "src/main/resources/application.yml", "language": "yaml", "description": "Spring Boot configuration"}]', '{"buildTool": {"type": "enum", "label": "Build tool", "default": "maven", "options": ["maven", "gradle"]}, "framework": {"type": "enum", "label": "Framework", "default": "spring-boot", "options": ["spring-boot", "quarkus", "micronaut", "plain-jvm"], "description": "Spring Boot 4.x is the ecosystem default (JDK 17+ baseline, Java 25 LTS current); Quarkus/Micronaut where startup time and footprint drive the design"}}', '["database", "cache", "message-broker", "auth-provider"]', false, NULL, NULL, '2026-03-31 13:54:56.372888+00', '2026-08-30 12:07:23.877005+00', 'Java', NULL, '''/api/orders'':53C ''21'':26C ''3'':29C ''5'':35C ''applic'':41C ''application.class'':49C ''appus'':60C ''arg'':47C,50C ''assign'':93C ''authenticationprincip'':59C ''backend'':3A,15B ''bean'':76C ''bom'':129C ''boot'':28C ''boundari'':83C ''build'':13B ''cannot'':99C ''chain'':138C ''class'':40C,54C,114C ''classic'':112C ''come'':121C ''concaten'':72C ''config'':124C ''cross'':8B ''cross-platform'':7B ''cve'':133C ''data'':19B,104C ''depend'':125C ''deseri'':102C ''digest'':144C ''dtos'':80C,86C ''ecosystem'':131C ''enterpris'':5B ''enterprise-grad'':4B ''entiti'':89C ''environment/vault'':123C ''everywher'':67C ''explicit'':85C ''exposur'':90C ''getmap'':56C ''grade'':6B ''happen'':100C ''hibernate/jpa'':33C ''imag'':142C ''inject'':75C ''jackson'':116C ''java'':1A,2A,25C,106C ''jpa/jdbc'':68C ''jpql'':73C ''junit'':34C ''jvm'':24B ''jvm/base'':141C ''keep'':115C ''languag'':11B ''lazi'':96C ''lazy-load'':95C ''leak'':98C ''list'':57C,58C ''load'':97C ''lombok'':36C ''main'':45C ''mapstruct'':37C ''mass'':92C ''maven/gradle'':32C ''micronaut'':31C ''microservic'':17B ''nativ'':107C ''never'':101C ''ordercontrol'':55C ''orders.findbyownerid'':63C ''parameter'':65C ''pin'':140C ''platform'':9B ''polymorph'':117C ''preparedstat'':69C ''process'':20B ''program'':10B ''public'':39C,42C ''quarkus'':30C ''queri'':66C ''rather'':87C ''rce'':113C ''request'':79C ''requestmap'':52C ''restcontrol'':51C ''return'':62C ''ride'':126C ''scalabl'':14B ''scan'':128C ''secret'':120C ''serial'':108C ''servic'':16B ''spring'':27C ''springapplication.run'':48C ''springbootappl'':38C ''static'':43C ''string'':46C,71C ''string-concaten'':70C ''suppli'':137C ''surfac'':134C ''system'':21B ''type'':118C ''untrust'':103C ''user'':61C ''user.getid'':64C ''valid'':77C ''void'':44C');
INSERT INTO public.technology_catalog VALUES ('vllm', 'vLLM', NULL, '#0f172a', '["inference-service"]', '{"purpose": "High-throughput, memory-efficient inference engine for serving large language models (LLMs) in production. vLLM uses PagedAttention to manage KV cache memory efficiently, enabling significantly higher throughput than naive inference serving. Use when you need to self-host LLMs (Llama, Mistral, Qwen, etc.) with production-grade performance, when you need OpenAI-compatible API endpoints for drop-in replacement of commercial APIs, or when you require batched inference for cost-efficient GPU utilization. vLLM supports continuous batching, tensor parallelism across GPUs, and quantized model serving. Don''t use when you can use a managed API (OpenAI, Anthropic, Google) that meets your latency and cost requirements. Don''t use without GPUs -- vLLM requires CUDA-capable hardware. Avoid for small models that can run efficiently on CPU with simpler frameworks like llama.cpp or Ollama.", "configMode": "declarative", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["vLLM", "CUDA", "Hugging Face Hub", "OpenAI API format", "AWQ/GPTQ quantization", "Ray Serve", "NVIDIA A100/H100", "Docker NVIDIA runtime"], "antiPatterns": ["Running without GPU causing extremely slow inference", "Setting max_model_len too high consuming GPU memory unnecessarily", "Not implementing request timeouts allowing long-running generations to block capacity", "Exposing vLLM directly to the internet without an API gateway and authentication", "Ignoring quantization when GPU memory is constrained", "Not monitoring GPU utilization and queue depth leading to undetected performance degradation"], "apiReference": {"docsUrl": "https://docs.vllm.ai/"}, "bestPractices": ["Use quantized models (AWQ, GPTQ) to reduce memory footprint and increase throughput", "Set appropriate max_model_len based on your use case to optimize KV cache allocation", "Use tensor parallelism across multiple GPUs for large models that exceed single GPU memory", "Enable continuous batching (default) and tune max_num_batched_tokens for your workload", "Monitor GPU memory usage and request queue depth for capacity planning", "Use the OpenAI-compatible API for easy integration with existing LLM tooling", "Implement request timeouts and rate limiting in front of vLLM"], "sdkInitPattern": "# Launch vLLM server\\npython -m vllm.entrypoints.openai.api_server --model meta-llama/Llama-3-8B-Instruct --port 8000 --max-model-len 4096\\n# Or with Docker:\\ndocker run --gpus all -p 8000:8000 vllm/vllm-openai --model meta-llama/Llama-3-8B-Instruct", "securityGuidance": "Never expose vLLM directly to the internet -- place behind a reverse proxy with authentication. Store Hugging Face tokens in environment variables or secrets, never in code. Implement rate limiting and request size limits to prevent abuse. Monitor for prompt injection attempts in user-provided inputs. Use network isolation to restrict which services can access the inference endpoint.", "commonApiPatterns": [{"name": "Chat Completion", "description": "OpenAI-compatible chat completion endpoint", "codeTemplate": "const response = await fetch(\"http://localhost:8000/v1/chat/completions\", {\\n  method: \"POST\",\\n  headers: { \"Content-Type\": \"application/json\" },\\n  body: JSON.stringify({\\n    model: \"meta-llama/Llama-3-8B-Instruct\",\\n    messages: [{ role: \"user\", content: \"Explain quantum computing\" }],\\n    max_tokens: 512,\\n    temperature: 0.7\\n  })\\n});\\nconst data = await response.json();"}, {"name": "Streaming", "description": "Streaming chat completion with server-sent events", "codeTemplate": "const response = await fetch(\"http://localhost:8000/v1/chat/completions\", {\\n  method: \"POST\",\\n  headers: { \"Content-Type\": \"application/json\" },\\n  body: JSON.stringify({ model: \"meta-llama/Llama-3-8B-Instruct\", messages: [{ role: \"user\", content: prompt }], stream: true })\\n});\\nconst reader = response.body!.getReader();\\nconst decoder = new TextDecoder();\\nwhile (true) {\\n  const { done, value } = await reader.read();\\n  if (done) break;\\n  const chunk = decoder.decode(value);\\n  // Parse SSE data lines\\n}"}, {"name": "Embeddings", "description": "Generate embeddings using OpenAI-compatible endpoint", "codeTemplate": "const response = await fetch(\"http://localhost:8000/v1/embeddings\", {\\n  method: \"POST\",\\n  headers: { \"Content-Type\": \"application/json\" },\\n  body: JSON.stringify({ model: \"BAAI/bge-large-en-v1.5\", input: [\"text to embed\"] })\\n});\\nconst { data } = await response.json();\\nconst embedding = data[0].embedding;"}], "integrationPatterns": ["API Gateway (NGINX, Kong) for authentication, rate limiting, and TLS termination", "LangChain or LlamaIndex for RAG pipelines with vLLM as the inference backend", "Prometheus + Grafana for monitoring GPU utilization, request latency, and queue depth"], "configurationTemplate": "# Docker Compose for vLLM\\nservices:\\n  vllm:\\n    image: vllm/vllm-openai:latest\\n    runtime: nvidia\\n    ports: [\"8000:8000\"]\\n    volumes:\\n      - huggingface_cache:/root/.cache/huggingface\\n    environment:\\n      - HUGGING_FACE_HUB_TOKEN=${HF_TOKEN}\\n    command: >\\n      --model meta-llama/Llama-3-8B-Instruct\\n      --max-model-len 4096\\n      --gpu-memory-utilization 0.9\\n      --tensor-parallel-size 1\\nvolumes:\\n  huggingface_cache:"}', '[{"kind": "build", "path": "docker-compose.yml", "language": "yaml", "description": "Docker Compose configuration for vLLM server with GPU passthrough and HuggingFace model cache volume"}, {"kind": "config", "path": "scripts/start-vllm.sh", "language": "bash", "description": "Startup script: python -m vllm.entrypoints.openai.api_server --model <model> --tensor-parallel-size <n>"}, {"kind": "config", "path": ".env", "language": "dotenv", "description": "Environment variables: VLLM_MODEL, VLLM_TENSOR_PARALLEL_SIZE, HF_TOKEN, VLLM_API_KEY"}]', '{"quantization": {"type": "enum", "label": "Quantization", "default": "none", "options": ["none", "awq", "gptq", "fp8", "bitsandbytes"], "description": "Weight quantization method to reduce VRAM usage"}, "tensorParallelSize": {"max": 8, "min": 1, "type": "number", "label": "Tensor Parallel Size", "default": 1, "description": "Number of GPUs to use for tensor parallelism (1 = single GPU)"}}', '["open-source-llm", "ai-service", "llm-gateway", "backend-service"]', false, NULL, NULL, '2026-03-13 01:22:40.314709+00', '2026-08-30 12:07:23.877005+00', 'vLLM', '#f0fdf4', '''/llama-3-8b-instruct'':170C,194C ''4096'':177C ''8000'':172C,187C,188C ''a100/h100'':155C ''abus'':230C ''access'':249C ''across'':88B ''anthrop'':105B ''api'':60B,69B,103B,148C ''attempt'':235C ''authent'':208C ''avoid'':125B ''awq/gptq'':150C ''batch'':74B,85B ''behind'':203C ''cach'':25B ''capabl'':123B ''code'':220C ''commerci'':68B ''compat'':59B ''continu'':84B ''cost'':78B,112B ''cost-effici'':77B ''cpu'':134B ''cuda'':122B,143C ''cuda-cap'':121B ''direct'':198C ''docker'':156C,181C ''drop'':64B ''drop-in'':63B ''effici'':8B,27B,79B,132B ''enabl'':28B ''endpoint'':61B,252C ''engin'':10B ''environ'':214C ''etc'':48B ''expos'':196C ''face'':145C,211C ''format'':149C ''framework'':137B ''googl'':106B ''gpu'':80B ''gpus'':89B,118B,184C ''grade'':52B ''hardwar'':124B ''high'':4B ''high-throughput'':3B ''higher'':30B ''host'':43B ''hub'':146C ''hug'':144C,210C ''implement'':221C ''infer'':9B,34B,75B,251C ''inject'':234C ''input'':240C ''internet'':201C ''isol'':243C ''kv'':24B ''languag'':14B ''larg'':13B ''latenc'':110B ''launch'':159C ''len'':176C ''like'':138B ''limit'':223C,227C ''llama'':45B,169C,193C ''llama.cpp'':139B ''llms'':16B,44B ''m'':163C ''manag'':23B,102B ''max'':174C ''max-model-len'':173C ''meet'':108B ''memori'':7B,26B ''memory-ef