INSERT INTO public.technology_catalog VALUES ('aws-lambda', 'AWS Lambda', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-lambda.png', '#6b7280', '["serverless-function"]', '{"purpose": "Serverless compute service that runs code in response to events and automatically manages the underlying compute resources. Supports Node.js, Python, Java, Go, .NET, Ruby, and custom runtimes.", "configMode": "code", "provenance": {"notes": "Phase B1 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Lambda Functions", "API Gateway", "EventBridge", "SQS", "SNS", "DynamoDB Streams", "S3 Events", "Lambda Layers", "Step Functions"], "antiPatterns": ["Monolithic Lambda functions doing too many things", "Not setting appropriate memory and timeout limits", "Storing state inside the function", "Not handling cold starts", "Synchronous invocation chains across multiple Lambdas", "Ignoring concurrency limits"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/lambda/"}, "bestPractices": ["Keep functions small and single-purpose", "Use environment variables for configuration", "Implement proper error handling and dead letter queues", "Use Lambda Layers for shared dependencies", "Set appropriate memory allocation for cost/performance balance", "Use provisioned concurrency for latency-sensitive workloads", "Use Step Functions for orchestrating multiple Lambda invocations", "Monitor with CloudWatch and X-Ray tracing"], "sdkInitPattern": "// handler.mjs — Node.js Lambda handler (ES module)\r\nexport const handler = async (event) => {\r\n  return { statusCode: 200, body: JSON.stringify({ ok: true }) };\r\n};", "securityGuidance": "One execution role per function with least-privilege IAM — never share a broad role across functions. Pull secrets from Secrets Manager or SSM Parameter Store at runtime instead of plaintext environment variables. If you expose a Function URL or API Gateway route, require auth (IAM or an authorizer) — no wildcard resource policies. Attach to a VPC only when the function truly needs private resources; it adds cold-start and egress complexity."}', '[{"kind": "source", "path": "src/handlers/index.ts"}, {"kind": "config", "path": "infra/aws/lambda.tf"}]', '{"runtime": {"type": "enum", "label": "Runtime", "default": "nodejs22.x", "options": ["nodejs24.x", "nodejs22.x", "nodejs20.x", "python3.14", "python3.13", "python3.12", "java25", "java21", "dotnet10", "dotnet8", "ruby3.4", "provided.al2023"], "description": "Lambda execution runtime"}, "memoryMb": {"type": "number", "label": "Memory (MB)", "default": 256, "description": "128-10240; CPU scales with memory"}, "triggerType": {"type": "enum", "label": "Primary trigger", "options": ["api-gateway", "sqs", "eventbridge", "s3", "schedule", "dynamodb-stream", "direct-invoke"], "description": "What invokes this function"}, "architecture": {"type": "enum", "label": "Architecture", "default": "arm64", "options": ["arm64", "x86_64"], "description": "arm64 (Graviton) is cheaper for most workloads"}, "timeoutSeconds": {"type": "number", "label": "Timeout (seconds)", "default": 30, "description": "Maximum 900 (15 minutes)"}}', '["api-gateway", "queue", "database", "object-storage", "event-stream"]', false, NULL, NULL, '2026-02-21 04:24:52.574678+00', '2026-08-30 12:07:23.877005+00', NULL, '#CC7A00', '''200'':60C ''across'':80C ''add'':131C ''api'':34C,105C ''async'':56C ''attach'':118C ''auth'':109C ''author'':113C ''automat'':16B ''aw'':1A,3A ''bodi'':61C ''broad'':78C ''code'':10B ''cold'':133C ''cold-start'':132C ''complex'':137C ''comput'':6B,20B ''const'':54C ''custom'':30B ''dynamodb'':39C ''egress'':136C ''environ'':96C ''es'':51C ''event'':14B,42C,57C ''eventbridg'':36C ''execut'':66C ''export'':53C ''expos'':100C ''function'':33C,46C,69C,81C,102C,125C ''gateway'':35C,106C ''go'':26B ''handler'':50C,55C ''handler.mjs'':47C ''iam'':74C,110C ''instead'':93C ''java'':25B ''json.stringify'':62C ''lambda'':2A,4A,32C,43C,49C ''layer'':44C ''least'':72C ''least-privileg'':71C ''manag'':17B,86C ''modul'':52C ''need'':127C ''net'':27B ''never'':75C ''node.js'':23B,48C ''ok'':63C ''one'':65C ''paramet'':89C ''per'':68C ''plaintext'':95C ''polici'':117C ''privat'':128C ''privileg'':73C ''pull'':82C ''python'':24B ''requir'':108C ''resourc'':21B,116C,129C ''respons'':12B ''return'':58C ''role'':67C,79C ''rout'':107C ''rubi'':28B ''run'':9B ''runtim'':31B,92C ''s3'':41C ''secret'':83C,85C ''serverless'':5B ''servic'':7B ''share'':76C ''sns'':38C ''sqs'':37C ''ssm'':88C ''start'':134C ''statuscod'':59C ''step'':45C ''store'':90C ''stream'':40C ''support'':22B ''true'':64C ''truli'':126C ''under'':19B ''url'':103C ''variabl'':97C ''vpc'':121C ''wildcard'':115C');
INSERT INTO public.technology_catalog VALUES ('valkey', 'Valkey', NULL, '#3b82f6', '["cache", "database"]', '{"purpose": "Open-source, community-driven fork of Redis maintained by the Linux Foundation. Valkey provides the same in-memory data structure store capabilities as Redis with a commitment to remaining fully open-source under the BSD license. Use as a drop-in replacement for Redis when you want to avoid Redis''s dual licensing (RSALv2/SSPLv1) introduced in 2024. Valkey supports all core Redis data structures, commands, and protocols. It is ideal for caching, session storage, rate limiting, pub/sub, and any workload previously served by Redis. AWS ElastiCache and other managed services now offer Valkey as an engine option. Don''t use if you specifically need Redis Stack modules (RedisJSON, RediSearch, RedisGraph) that are not yet available in Valkey. Don''t use if your team and tooling are tightly coupled to Redis Enterprise features. For new projects without Redis licensing concerns, either Redis or Valkey works -- the protocol and API are identical.", "configMode": "declarative", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Valkey 7+", "ioredis", "redis-py", "AWS ElastiCache (Valkey)", "Valkey CLI", "Valkey Cluster", "Valkey Sentinel", "Terraform"], "antiPatterns": ["Assuming Redis Stack modules (RedisJSON, RediSearch) are available in Valkey", "Using as primary database without a persistent backing store for critical data", "Storing large objects (>1MB) as single keys consuming excessive memory", "Using KEYS command in production causing blocking scans (use SCAN instead)", "Not setting TTL on cache entries causing memory to grow indefinitely", "Running without authentication in any environment beyond local development"], "apiReference": {"docsUrl": "https://valkey.io/docs/"}, "bestPractices": ["Use the same data structure selection guidance as Redis (hashes, sets, sorted sets, streams)", "Set TTL on all cache keys to prevent unbounded memory growth", "Use pipelining for batch operations to reduce round-trip latency", "Configure persistence (RDB + AOF) when data durability matters", "Monitor memory usage and configure maxmemory-policy for eviction behavior", "Test compatibility with existing Redis client libraries (ioredis, redis-py, etc.)", "Use Valkey Cluster for horizontal scaling across multiple nodes"], "freshnessNote": "Relationship to the redis row: protocol-compatible siblings. This row = an explicitly-Valkey deployment (BSD, Linux Foundation, v9 era); the redis row''s engine field covers Redis-branded workloads where valkey is the compatible default. Same client libraries either way — pick ONE row per node, do not model both.", "sdkInitPattern": "// Node.js -- uses standard Redis clients (protocol-compatible)\\nimport Redis from \"ioredis\";\\nconst valkey = new Redis(process.env.VALKEY_URL || \"redis://localhost:6379\");\\n// [Tailor to project language: Python=redis-py, Go=go-redis, Rust=fred, Java=Lettuce]", "securityGuidance": "All Redis security practices apply -- set strong authentication, enable TLS, bind to specific interfaces. Use ACLs to create users with minimal command and key permissions. Place Valkey in a private subnet accessible only to application servers. Disable dangerous commands (FLUSHALL, KEYS, CONFIG) for application users.", "commonApiPatterns": [{"name": "Cache Pattern", "description": "Cache-aside pattern identical to Redis usage", "codeTemplate": "async function getCached<T>(key: string, fetcher: () => Promise<T>, ttl = 300): Promise<T> {\\n  const cached = await valkey.get(key);\\n  if (cached) return JSON.parse(cached);\\n  const data = await fetcher();\\n  await valkey.setex(key, ttl, JSON.stringify(data));\\n  return data;\\n}"}, {"name": "Data Structures", "description": "Hash, set, and sorted set operations", "codeTemplate": "await valkey.hset(\"user:123\", { name: \"Alice\", email: \"alice@example.com\" });\\nawait valkey.sadd(\"online-users\", \"123\", \"456\");\\nawait valkey.zadd(\"leaderboard\", 1500, \"player1\", 2200, \"player2\");\\nconst topPlayers = await valkey.zrevrange(\"leaderboard\", 0, 9, \"WITHSCORES\");"}, {"name": "Streams", "description": "Stream append and blocking read for event processing", "codeTemplate": "await valkey.xadd(\"events\", \"*\", \"type\", \"order_created\", \"data\", JSON.stringify({ orderId }));\\nconst entries = await valkey.xread(\"COUNT\", 10, \"BLOCK\", 5000, \"STREAMS\", \"events\", \"$\");"}], "integrationPatterns": ["Drop-in replacement for Redis in any existing architecture using standard Redis client libraries", "AWS ElastiCache with Valkey engine for managed deployment", "Application cache, session store, and job queue using identical Redis patterns"], "configurationTemplate": "# valkey.conf (same format as redis.conf)\\nmaxmemory 256mb\\nmaxmemory-policy allkeys-lru\\nsave 900 1\\nsave 300 10\\nappendonly yes\\nappendfsync everysec\\nrequirepass ${VALKEY_PASSWORD}\\nbind 127.0.0.1\\ntls-port 6380\\ntls-cert-file /etc/valkey/tls/valkey.crt\\ntls-key-file /etc/valkey/tls/valkey.key"}', '[{"kind": "config", "path": "valkey.conf", "language": "text", "description": "Bind address, requirepass/ACLs, renamed dangerous commands, TLS"}]', '{"eviction": {"type": "enum", "label": "Eviction policy", "default": "noeviction", "options": ["noeviction", "allkeys-lru", "volatile-ttl"]}, "topology": {"type": "enum", "label": "Topology", "default": "standalone", "options": ["standalone", "sentinel-ha", "cluster"]}, "persistence": {"type": "enum", "label": "Persistence", "default": "aof-everysec", "options": ["aof-everysec", "rdb-snapshots", "none-pure-cache"]}}', '["backend-service", "worker"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#3070D6', '''2024'':64B ''6379'':193C ''7'':159C ''access'':242C ''acl'':226C ''api'':155B ''appli'':215C ''applic'':245C,254C ''authent'':218C ''avail'':122B ''avoid'':56B ''aw'':92B,164C ''bind'':221C ''bsd'':41B ''cach'':79B ''capabl'':27B ''cli'':168C ''client'':178C ''cluster'':170C ''command'':72B,232C,249C ''commit'':32B ''communiti'':7B ''community-driven'':6B ''compat'':181C ''concern'':146B ''config'':252C ''core'':68B ''coupl'':135B ''creat'':228C ''danger'':248C ''data'':24B,70B ''disabl'':247C ''driven'':8B ''drop'':47B ''drop-in'':46B ''dual'':59B ''either'':147B ''elasticach'':93B,165C ''enabl'':219C ''engin'':103B ''enterpris'':138B ''featur'':139B ''flushal'':250C ''fork'':9B ''foundat'':16B ''fred'':208C ''fulli'':35B ''go'':203C,205C ''go-redi'':204C ''ideal'':77B ''ident'':157B ''in-memori'':21B ''interfac'':224C ''introduc'':62B ''ioredi'':160C,185C ''java'':209C ''key'':234C,251C ''languag'':198C ''lettuc'':210C ''licens'':42B,60B,145B ''limit'':83B ''linux'':15B ''localhost'':192C ''maintain'':12B ''manag'':96B ''memori'':23B ''minim'':231C ''modul'':114B ''n'':194C ''nconst'':186C ''need'':111B ''new'':141B,188C ''nimport'':182C ''node.js'':174C ''offer'':99B ''open'':4B,37B ''open-sourc'':3B,36B ''option'':104B ''permiss'':235C ''place'':236C ''practic'':214C ''previous'':88B ''privat'':240C ''process.env.valkey'':190C ''project'':142B,197C ''protocol'':74B,153B,180C ''protocol-compat'':179C ''provid'':18B ''pub/sub'':84B ''py'':163C,202C ''python'':199C ''rate'':82B ''redi'':11B,29B,51B,57B,69B,91B,112B,137B,144B,148B,162C,177C,183C,189C,201C,206C,212C ''redis-pi'':161C,200C ''redisearch'':116B ''redisgraph'':117B ''redisjson'':115B ''remain'':34B ''replac'':49B ''rsalv2/ssplv1'':61B ''rust'':207C ''secur'':213C ''sentinel'':172C ''serv'':89B ''server'':246C ''servic'':97B ''session'':80B ''set'':216C ''sourc'':5B,38B ''specif'':110B,223C ''stack'':113B ''standard'':176C ''storag'':81B ''store'':26B ''strong'':217C ''structur'':25B,71B ''subnet'':241C ''support'':66B ''tailor'':195C ''team'':130B ''terraform'':173C ''tight'':134B ''tls'':220C ''tool'':132B ''url'':191C ''use'':43B,107B,127B,175C,225C ''user'':229C,255C ''valkey'':1A,2A,17B,65B,100B,124B,150B,158C,166C,167C,169C,171C,187C,237C ''want'':54B ''without'':143B ''work'':151B ''workload'':87B ''yet'':121B');
INSERT INTO public.technology_catalog VALUES ('gcp-cloud-functions', 'Google Cloud Run functions', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/gcp-cloud-functions.png', '#4285F4', '["serverless-function"]', '{"purpose": "Google Cloud Functions is Google Cloud''s lightweight serverless functions platform for event-driven code that responds to HTTP requests and cloud events without managing servers. Use it for single-purpose handlers, webhooks, background automation, and integrations triggered by storage, messaging, or platform events. Choose Google Cloud Functions over Cloud Run when the unit of deployment is a small event-driven function rather than a full containerized service. Do not use it for complex multi-service applications, long-running container platforms, or workloads that need fine-grained container control where Cloud Run or GKE are better fits.", "configMode": "code", "provenance": {"notes": "Phase B3 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Google Cloud Functions", "Cloud Run", "Pub/Sub", "Eventarc", "Cloud Storage", "Secret Manager", "Cloud Logging"], "antiPatterns": ["Using Cloud Functions as a long-running application server with multiple unrelated endpoints", "Embedding credentials or secrets directly in code or deployment scripts", "Packing very large dependencies into every function deployment without considering cold-start impact", "Assuming exactly-once delivery semantics for event-driven workflows", "Using functions for workloads that require custom sidecars, advanced networking, or container-level control", "Treating a single function as the orchestration layer for an entire platform"], "apiReference": {"docsUrl": "https://cloud.google.com/functions/docs"}, "bestPractices": ["Keep each function focused on one trigger type and a clearly bounded responsibility", "Design handlers to be idempotent because events and retries can be delivered more than once", "Store configuration and secrets outside source code using environment configuration and secret management", "Use event payloads as lightweight triggers and fetch large documents from external storage when needed", "Set timeouts, memory, and concurrency deliberately to match the real runtime profile", "Use structured logging and tracing so invocations can be correlated across downstream services", "Split latency-sensitive HTTP functions from asynchronous background handlers into separate deployments"], "sdkInitPattern": "// index.js — Functions Framework (2nd gen)\r\nconst functions = require(''@google-cloud/functions-framework'');\r\n\r\nfunctions.http(''hello'', (req, res) => {\r\n  res.json({ ok: true });\r\n});", "securityGuidance": "Deploy with --no-allow-unauthenticated and grant roles/cloudfunctions.invoker (or run.invoker for 2nd gen) explicitly. Give each function its own least-privilege service account — never the default compute account. Reach secrets through Secret Manager bindings, not plaintext env vars, and keep ingress internal-only where callers are inside the project."}', '[{"kind": "source", "path": "src/functions/index.ts", "priority": "essential", "description": "Primary Google Cloud Functions entrypoint for HTTP or event-driven handlers"}, {"kind": "config", "path": "functions/package.json", "priority": "recommended", "description": "Runtime dependencies and build configuration for the function deployment"}, {"kind": "config", "path": "infra/cloud-functions.yaml", "priority": "recommended", "description": "Infrastructure and trigger configuration for deploying Google Cloud Functions"}]', '{"ingress": {"type": "string", "label": "Ingress", "default": "all", "options": ["all", "internal-only", "internal-and-gclb"], "description": "Network exposure policy for the function"}, "runtime": {"type": "string", "label": "Runtime", "default": "nodejs22", "options": ["nodejs22", "python312", "go122", "java21"], "description": "Language runtime for the function deployment"}, "memoryMb": {"type": "number", "label": "Memory (MB)", "default": 256, "description": "CPU scales with memory — a slow function is often an under-memoried one"}, "generation": {"type": "enum", "label": "Generation", "default": "cloud-run-functions", "options": ["cloud-run-functions", "1st-gen"], "description": "What was Cloud Functions (2nd gen) is now Cloud Run functions, built on Cloud Run — longer timeouts, concurrency > 1, larger instances. 1st gen only for existing deployments"}, "concurrency": {"type": "number", "label": "Concurrent requests per instance", "default": 1, "description": "Only Cloud Run functions can exceed 1; raising it is the main cost lever"}, "triggerType": {"type": "string", "label": "Trigger Type", "default": "http", "options": ["http", "pubsub", "storage", "eventarc"], "description": "Primary event source for the function"}, "timeoutSeconds": {"type": "number", "label": "Timeout (s)", "default": 60}}', '["message-broker", "event-stream", "object-storage", "monitoring", "auth-provider"]', false, NULL, NULL, '2026-03-14 20:08:37.431602+00', '2026-08-30 12:07:23.877005+00', NULL, '#2F6AD8', '''/functions-framework'':135C ''2nd'':127C,155C ''account'':167C,172C ''allow'':147C ''applic'':88B ''autom'':44B ''background'':43B ''better'':109B ''bind'':178C ''caller'':190C ''choos'':54B ''cloud'':2A,6A,9B,13B,30B,56B,59B,104B,112C,114C,118C,122C,134C ''code'':23B ''complex'':84B ''comput'':171C ''const'':129C ''contain'':92B,101B ''container'':77B ''control'':102B ''default'':170C ''deploy'':65B,143C ''driven'':22B,71B ''env'':181C ''event'':21B,31B,53B,70B ''event-driven'':20B,69B ''eventarc'':117C ''explicit'':157C ''fine'':99B ''fine-grain'':98B ''fit'':110B ''framework'':126C ''full'':76B ''function'':4A,7A,10B,17B,57B,72B,113C,125C,130C,160C ''functions.http'':136C ''gcp'':5A ''gen'':128C,156C ''give'':158C ''gke'':107B ''googl'':1A,8B,12B,55B,111C,133C ''google-cloud'':132C ''grain'':100B ''grant'':150C ''handler'':41B ''hello'':137C ''http'':27B ''index.js'':124C ''ingress'':185C ''insid'':192C ''integr'':46B ''intern'':187C ''internal-on'':186C ''keep'':184C ''least'':164C ''least-privileg'':163C ''lightweight'':15B ''log'':123C ''long'':90B ''long-run'':89B ''manag'':33B,121C,177C ''messag'':50B ''multi'':86B ''multi-servic'':85B ''need'':97B ''never'':168C ''no-allow-unauthent'':145C ''ok'':141C ''plaintext'':180C ''platform'':18B,52B,93B ''privileg'':165C ''project'':194C ''pub/sub'':116C ''purpos'':40B ''rather'':73B ''reach'':173C ''req'':138C ''request'':28B ''requir'':131C ''res'':139C ''res.json'':140C ''respond'':25B ''roles/cloudfunctions.invoker'':151C ''run'':3A,60B,91B,105B,115C ''run.invoker'':153C ''secret'':120C,174C,176C ''server'':34B ''serverless'':16B ''servic'':78B,87B,166C ''singl'':39B ''single-purpos'':38B ''small'':68B ''storag'':49B,119C ''trigger'':47B ''true'':142C ''unauthent'':148C ''unit'':63B ''use'':35B,81B ''var'':182C ''webhook'':42B ''without'':32B ''workload'':95B');
INSERT INTO public.technology_catalog VALUES ('postgresql', 'PostgreSQL', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/postgresql.png', '#336791', '["database"]', '{"purpose": "Best general-purpose relational database for most application workloads. Ideal for ACID transactions, complex joins, JSONB semi-structured data, full-text search, geospatial queries (PostGIS), and vector embeddings (pgvector). Use when you need strong consistency guarantees, complex relational modeling, or advanced SQL features like CTEs, window functions, and materialized views. Default choice for Supabase-backed applications. Don''t use when your workload is purely key-value lookups at extreme throughput (use Redis), append-only time-series without relational joins (use InfluxDB/TimescaleDB), or when you need automatic global distribution without manual sharding (consider CockroachDB or Spanner). PostgreSQL handles semi-structured data well via JSONB, so don''t default to MongoDB just because you have some schema flexibility needs.", "configMode": "declarative", "provenance": {"notes": "docsUrl is the vendor''s canonical documentation root, stamped from model knowledge and checked by scripts/n10-verify-docs-urls.ts; pre-existing body content not yet live-docs verified — upgrade at this row''s enrichment chunk.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["PostgreSQL 16+", "pgBouncer", "Supabase", "Neon", "AWS RDS PostgreSQL", "pgvector", "PostGIS", "pgAdmin"], "antiPatterns": ["Missing indexes on foreign key columns causing slow joins", "Not using connection pooling causing \"too many connections\" under load", "Storing large binary files directly in the database instead of object storage", "Using SELECT * in queries pulling unnecessary columns across the wire", "Running schema migrations without testing on a staging replica first", "Choosing PostgreSQL when workload is purely key-value or time-series"], "apiReference": {"docsUrl": "https://www.postgresql.org/docs/current/"}, "bestPractices": ["Use connection pooling (pgBouncer or Supabase built-in pooler) for high-concurrency apps", "Create B-tree indexes on frequently queried and foreign key columns", "Use JSONB for semi-structured data alongside relational columns", "Implement row-level security (RLS) for multi-tenant applications", "Enable pg_stat_statements for query performance analysis", "Use logical replication or streaming replication for high availability", "Run ANALYZE after bulk data loads to update query planner statistics"], "freshnessNote": "PostgreSQL 18 is current (async I/O, native UUIDv7 generation) — prefer UUIDv7 over v4 for new primary keys (index locality).", "sdkInitPattern": "// Node.js with pg\\nimport { Pool } from \"pg\";\\nconst pool = new Pool({ connectionString: process.env.DATABASE_URL, max: 20 });\\n// [Tailor to project language: Python=psycopg, Go=pgx, Rust=sqlx, .NET=Npgsql]", "securityGuidance": "Always use parameterized queries -- never concatenate user input into SQL strings. Enable SSL/TLS for all connections (sslmode=require or verify-full). Use row-level security (RLS) policies for multi-tenant data isolation. Grant least-privilege roles: separate read-only and read-write database users. Rotate database credentials regularly and store them in a secrets manager.", "commonApiPatterns": [{"name": "Parameterized Query", "description": "Safe parameterized query preventing SQL injection", "codeTemplate": "const { rows } = await pool.query(\"SELECT id, name, email FROM users WHERE id = $1\", [userId]);"}, {"name": "Transaction", "description": "Multi-statement transaction with proper rollback and connection release", "codeTemplate": "const client = await pool.connect();\\ntry {\\n  await client.query(\"BEGIN\");\\n  await client.query(\"INSERT INTO orders (user_id, total) VALUES ($1, $2)\", [userId, total]);\\n  await client.query(\"UPDATE inventory SET stock = stock - $1 WHERE product_id = $2\", [qty, productId]);\\n  await client.query(\"COMMIT\");\\n} catch (e) {\\n  await client.query(\"ROLLBACK\");\\n  throw e;\\n} finally {\\n  client.release();\\n}"}, {"name": "Upsert", "description": "Insert or update on conflict using ON CONFLICT clause", "codeTemplate": "await pool.query(\\n  \"INSERT INTO users (email, name) VALUES ($1, $2) ON CONFLICT (email) DO UPDATE SET name = EXCLUDED.name, updated_at = NOW()\",\\n  [email, name]\\n);"}, {"name": "Full-Text Search", "description": "Full-text search with ranking using tsvector", "codeTemplate": "SELECT id, title, ts_rank(search_vector, query) AS rank\\nFROM articles, plainto_tsquery(''english'', $1) query\\nWHERE search_vector @@ query\\nORDER BY rank DESC LIMIT 20;"}], "setupInstructions": [{"type": "manual_workflow", "title": "Provision PostgreSQL Instance", "commands": ["docker run -d -p 5432:5432 -e POSTGRES_PASSWORD=postgres postgres:16"], "required": true, "instructions": "Set up PostgreSQL via a managed service (Supabase, RDS, Cloud SQL, Neon) or install locally for development."}, {"type": "environment_variable", "title": "Set Database URL", "commands": ["export DATABASE_URL=postgresql://user:password@host:5432/dbname"], "required": true, "instructions": "Configure the PostgreSQL connection URL in your environment variables."}], "integrationPatterns": ["Supabase or Neon for managed PostgreSQL with built-in connection pooling and APIs", "pgBouncer for connection pooling in self-managed deployments", "pgvector for AI/ML vector similarity search alongside relational data", "PostGIS for geospatial queries and location-based features", "Logical replication to read replicas for scaling read-heavy workloads"], "configurationTemplate": "# postgresql.conf (key tuning)\\nshared_buffers = ''256MB''            # 25% of RAM\\neffective_cache_size = ''768MB''      # 75% of RAM\\nwork_mem = ''4MB''\\nmaintenance_work_mem = ''64MB''\\nmax_connections = 100\\nlog_min_duration_statement = 200   # Log slow queries > 200ms\\nshared_preload_libraries = ''pg_stat_statements''"}', '[{"kind": "schema", "path": "schema.sql", "language": "sql", "description": "Database schema definition"}, {"kind": "schema", "path": "migrations/", "language": "sql", "description": "Migration files directory"}]', '{"extensions": {"type": "multiselect", "label": "Extensions", "options": ["pgvector", "postgis", "pg_cron", "timescaledb", "none"], "description": "The extension story is why Postgres wins — vector search (see the pgvector node), geospatial, scheduling and time-series without leaving the database"}, "backupStrategy": {"type": "enum", "label": "Backups", "default": "pgbackrest-pitr", "options": ["pgbackrest-pitr", "pg_dump-scheduled", "snapshot-only"], "description": "Point-in-time recovery vs logical dumps vs volume snapshots — an explicit decision, not a default you discover during an incident"}, "connectionPooling": {"type": "enum", "label": "Connection pooling", "default": "pgbouncer", "options": ["pgbouncer", "built-in-pool-only", "none"], "description": "Serverless/edge callers exhaust raw connections fast — a pooler is the default posture, not an optimization"}}', '["backend-service", "rest-api", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#2A5275', '''16'':129C ''20'':154C ''acid'':15B ''advanc'':46B ''alway'':168C ''append'':81B ''append-on'':80B ''applic'':11B,62B ''automat'':95B ''aw'':133C ''back'':61B ''best'':3B ''choic'':57B ''cockroachdb'':102B ''complex'':17B,42B ''concaten'':173C ''connect'':183C ''connectionstr'':150C ''consid'':101B ''consist'':40B ''credenti'':220C ''ctes'':50B ''data'':23B,110B,201C ''databas'':8B,216C,219C ''default'':56B,117B ''distribut'':97B ''embed'':33B ''enabl'':179C ''extrem'':76B ''featur'':48B ''flexibl'':126B ''full'':25B,189C ''full-text'':24B ''function'':52B ''general'':5B ''general-purpos'':4B ''geospati'':28B ''global'':96B ''go'':162C ''grant'':203C ''guarante'':41B ''handl'':106B ''ideal'':13B ''influxdb/timescaledb'':90B ''input'':175C ''isol'':202C ''join'':18B,88B ''jsonb'':19B,113B ''key'':72B ''key-valu'':71B ''languag'':159C ''least'':205C ''least-privileg'':204C ''level'':193C ''like'':49B ''lookup'':74B ''manag'':228C ''manual'':99B ''materi'':54B ''max'':153C ''model'':44B ''mongodb'':119B ''multi'':199C ''multi-ten'':198C ''n'':155C ''nconst'':146C ''need'':38B,94B,127B ''neon'':132C ''net'':166C ''never'':172C ''new'':148C ''nimport'':142C ''node.js'':139C ''npgsql'':167C ''parameter'':170C ''pg'':141C,145C ''pgadmin'':138C ''pgbouncer'':130C ''pgvector'':34B,136C ''pgx'':163C ''polici'':196C ''pool'':143C,147C,149C ''postgi'':30B,137C ''postgresql'':1A,2A,105B,128C,135C ''privileg'':206C ''process.env.database'':151C ''project'':158C ''psycopg'':161C ''pure'':70B ''purpos'':6B ''python'':160C ''queri'':29B,171C ''rds'':134C ''read'':210C,214C ''read-on'':209C ''read-writ'':213C ''redi'':79B ''regular'':221C ''relat'':7B,43B,87B ''requir'':185C ''rls'':195C ''role'':207C ''rotat'':218C ''row'':192C ''row-level'':191C ''rust'':164C ''schema'':125B ''search'':27B ''secret'':227C ''secur'':194C ''semi'':21B,108B ''semi-structur'':20B,107B ''separ'':208C ''seri'':85B ''shard'':100B ''spanner'':104B ''sql'':47B,177C ''sqlx'':165C ''ssl/tls'':180C ''sslmode'':184C ''store'':223C ''string'':178C ''strong'':39B ''structur'':22B,109B ''supabas'':60B,131C ''supabase-back'':59B ''tailor'':156C ''tenant'':200C ''text'':26B ''throughput'':77B ''time'':84B ''time-seri'':83B ''transact'':16B ''url'':152C ''use'':35B,65B,78B,89B,169C,190C ''user'':174C,217C ''valu'':73B ''vector'':32B ''verifi'':188C ''verify-ful'':187C ''via'':112B ''view'':55B ''well'':111B ''window'':51B ''without'':86B,98B ''workload'':12B,68B ''write'':215C');
INSERT INTO public.technology_catalog VALUES ('neo4j', 'Neo4j', NULL, '#008cc1', '["graph-db"]', '{"purpose": "Native graph database storing data as nodes, relationships, and properties, optimized for traversing connected data. Use when your core queries involve exploring relationships -- social networks, recommendation engines, fraud detection, knowledge graphs, access control hierarchies, and dependency analysis. Neo4j''s Cypher query language makes complex path traversals, shortest-path calculations, and pattern matching intuitive. Don''t use for tabular data with simple CRUD operations -- a relational database is simpler and more efficient. Don''t use for high-throughput write-heavy workloads without relationship queries. Avoid when your \"graph\" is really just a few foreign key joins that PostgreSQL handles natively. Consider starting with PostgreSQL recursive CTEs for simple hierarchy queries before adopting a dedicated graph database.", "configMode": "declarative", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Neo4j 5+", "Cypher Query Language", "Neo4j Browser", "Neo4j Bloom", "Neo4j Aura", "APOC Library", "Graph Data Science Library", "neo4j-driver"], "antiPatterns": ["Modeling tabular data as a graph when it has few meaningful relationships", "Creating property-rich nodes without indexes on queried properties", "Using unbounded variable-length path traversals without limits", "Storing time-series or log data in Neo4j instead of a purpose-built database", "Not using parameters in Cypher queries defeating query plan caching", "Creating \"supernodes\" with millions of relationships without relationship type filtering"], "apiReference": {"docsUrl": "https://neo4j.com/docs/"}, "bestPractices": ["Model relationships as first-class citizens with meaningful types and properties", "Create indexes on node properties used in MATCH and WHERE clauses", "Use parameterized Cypher queries to prevent injection and enable plan caching", "Use MERGE instead of CREATE to prevent duplicate nodes and relationships", "Batch large data imports with UNWIND or LOAD CSV with periodic commits", "Profile queries with EXPLAIN and PROFILE to identify expensive operations", "Use relationship direction consistently and avoid bidirectional relationships"], "sdkInitPattern": "// Node.js with neo4j-driver\\nimport neo4j from \"neo4j-driver\";\\nconst driver = neo4j.driver(process.env.NEO4J_URI!, neo4j.auth.basic(process.env.NEO4J_USER!, process.env.NEO4J_PASSWORD!));\\n// [Tailor to project language: Python=neo4j, Go=neo4j-go-driver, Java=neo4j-java-driver, .NET=Neo4j.Driver]", "securityGuidance": "Always enable authentication and use strong passwords. Use parameterized Cypher queries to prevent injection attacks. Restrict APOC and GDS procedure access to authorized users. Enable TLS for Bolt and HTTP connections. Use role-based access control to separate read and write access across databases.", "commonApiPatterns": [{"name": "Create Node", "description": "Create or merge a node with properties using parameterized Cypher", "codeTemplate": "const session = driver.session();\\ntry {\\n  await session.run(\"MERGE (u:User {id: $id}) SET u.name = $name, u.email = $email\", { id, name, email });\\n} finally {\\n  await session.close();\\n}"}, {"name": "Create Relationship", "description": "Create a typed relationship between two nodes", "codeTemplate": "await session.run(\\n  \"MATCH (a:User {id: $fromId}), (b:User {id: $toId}) MERGE (a)-[:FOLLOWS {since: datetime()}]->(b)\",\\n  { fromId, toId }\\n);"}, {"name": "Traverse Graph", "description": "Friend-of-friend recommendation query", "codeTemplate": "const result = await session.run(\\n  \"MATCH (u:User {id: $userId})-[:FOLLOWS]->(friend)-[:FOLLOWS]->(fof) WHERE NOT (u)-[:FOLLOWS]->(fof) AND fof <> u RETURN DISTINCT fof.name AS suggestion, count(*) AS mutualFriends ORDER BY mutualFriends DESC LIMIT 10\",\\n  { userId }\\n);"}, {"name": "Shortest Path", "description": "Find shortest path between two nodes", "codeTemplate": "const result = await session.run(\\n  \"MATCH path = shortestPath((a:User {id: $startId})-[:KNOWS*..6]-(b:User {id: $endId})) RETURN path\",\\n  { startId, endId }\\n);"}], "integrationPatterns": ["APOC library for advanced procedures (import, export, graph algorithms)", "Graph Data Science library for centrality, community detection, and ML pipelines", "Application layer: use as a specialized query engine alongside a primary relational database"], "configurationTemplate": "# neo4j.conf key settings\\nserver.default_listen_address=0.0.0.0\\nserver.bolt.listen_address=:7687\\nserver.http.listen_address=:7474\\ndbms.memory.heap.initial_size=512m\\ndbms.memory.heap.max_size=1G\\ndbms.memory.pagecache.size=512m\\ndbms.security.auth_enabled=true\\ndbms.security.procedures.unrestricted=apoc.*"}', '[{"kind": "config", "path": "neo4j.conf", "language": "text", "description": "Listen addresses, TLS policies, auth enabled"}]', '{"edition": {"type": "enum", "label": "Edition", "default": "community", "options": ["community", "enterprise", "aura-managed"], "description": "Clustering and RBAC are enterprise features; Aura is the managed lane"}, "accessPattern": {"type": "enum", "label": "Access pattern", "default": "cypher-driver", "options": ["cypher-driver", "graphql-library", "both"]}}', '["backend-service", "ai-service"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#0070A1', '''5'':122C ''access'':34B,204C,219C,226C ''across'':227C ''adopt'':116B ''alway'':184C ''analysi'':39B ''apoc'':132C,200C ''attack'':198C ''aura'':131C ''authent'':186C ''author'':206C ''avoid'':89B ''base'':218C ''bloom'':129C ''bolt'':211C ''browser'':127C ''calcul'':52B ''complex'':46B ''connect'':16B,214C ''consid'':105B ''control'':35B,220C ''core'':21B ''crud'':65B ''ctes'':110B ''cypher'':42B,123C,193C ''data'':7B,17B,62B,135C ''databas'':5B,69B,120B,228C ''dedic'':118B ''depend'':38B ''detect'':31B ''driver'':140C,145C,151C,153C,176C,181C ''effici'':74B ''enabl'':185C,208C ''engin'':29B ''explor'':24B ''foreign'':98B ''fraud'':30B ''gds'':202C ''go'':172C,175C ''graph'':4B,33B,92B,119B,134C ''handl'':103B ''heavi'':84B ''hierarchi'':36B,113B ''high'':80B ''high-throughput'':79B ''http'':213C ''inject'':197C ''intuit'':56B ''involv'':23B ''java'':177C,180C ''join'':100B ''key'':99B ''knowledg'':32B ''languag'':44B,125C,169C ''librari'':133C,137C ''make'':45B ''match'':55B ''n'':165C ''nativ'':3B,104B ''nconst'':152C ''neo4j'':1A,2A,40B,121C,126C,128C,130C,139C,144C,147C,150C,156C,160C,163C,171C,174C,179C ''neo4j-driver'':138C,143C,149C ''neo4j-go-driver'':173C ''neo4j-java-driver'':178C ''neo4j.auth.basic'':158C ''neo4j.driver'':154C,183C ''net'':182C ''network'':27B ''nimport'':146C ''node'':9B ''node.js'':141C ''oper'':66B ''optim'':13B ''parameter'':192C ''password'':164C,190C ''path'':47B,51B ''pattern'':54B ''postgresql'':102B,108B ''prevent'':196C ''procedur'':203C ''process.env'':155C,159C,162C ''project'':168C ''properti'':12B ''python'':170C ''queri'':22B,43B,88B,114B,124C,194C ''read'':223C ''realli'':94B ''recommend'':28B ''recurs'':109B ''relat'':68B ''relationship'':10B,25B,87B ''restrict'':199C ''role'':217C ''role-bas'':216C ''scienc'':136C ''separ'':222C ''shortest'':50B ''shortest-path'':49B ''simpl'':64B,112B ''simpler'':71B ''social'':26B ''start'':106B ''store'':6B ''strong'':189C ''tabular'':61B ''tailor'':166C ''throughput'':81B ''tls'':209C ''travers'':15B,48B ''uri'':157C ''use'':18B,59B,77B,188C,191C,215C ''user'':161C,207C ''without'':86B ''workload'':85B ''write'':83B,225C ''write-heavi'':82B');
INSERT INTO public.technology_catalog VALUES ('openai', 'OpenAI', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/openai.png', '#412991', '["inference-service"]', '{"purpose": "LLM provider — GPT-5.6 model family via the Responses API (the primary surface: reasoning controls, function calling, built-in web/file search, computer use), plus embeddings, image generation, audio, and 50%-discount batch processing. Consider Anthropic Claude as the alternative frontier provider; the two are commonly abstracted behind one gateway interface.", "configMode": "external", "provenance": {"notes": "Phase B3 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Responses API", "GPT-5.6 (sol/terra/luna)", "function calling", "structured outputs", "text-embedding-3", "Batch API", "official openai SDK"], "antiPatterns": ["Building new agentic features on the Assistants API — DEPRECATED, sunset announced for 2026-08 (the former openai-assistants catalog row was retired into this one); the Responses API is its successor", "Hardcoding a model ID everywhere instead of one config point — model families turn over every few months", "Exposing API keys in frontend code", "Using sol-tier for classification/extraction work luna handles", "Ignoring token budgets on long-context calls — 1.05M context is a capacity, not a target"], "apiReference": {"areas": {"audio": {"endpoints": ["`POST /v1/audio/transcriptions` — speech-to-text (model=gpt-4o-transcribe; file upload)", "`POST /v1/audio/speech` — text-to-speech (voice, format)", "Realtime lane: gpt-realtime-2 for speech-to-speech agents (configurable reasoning), gpt-realtime-translate for streaming translation — the Realtime beta shape was removed 2026-05-12"]}, "images": {"endpoints": ["`POST /v1/images/generations` — model=gpt-image-2 (state of the art) | gpt-image-1 | gpt-image-1-mini; prompt, size, quality, n", "Image editing/variations on the same endpoint family; gpt-image models accept high-fidelity image inputs", "dall-e-2 / dall-e-3 were REMOVED from the API 2026-05-12 — do not generate code against them"]}, "models": {"docsUrl": "https://developers.openai.com/api/docs/models", "endpoints": ["`gpt-5.6-sol` — flagship (GA 2026-07-09; alias gpt-5.6 routes here). 1.05M ctx / 128K out; text+image in; reasoning controls, function calling, built-in web search / file search / computer use. $5/$30 per MTok. For frontier reasoning and specialist domains", "`gpt-5.6-terra` — the production default: same capability surface as sol, matches GPT-5.5 quality at roughly half the cost. 1.05M ctx / 128K out. $2.50/$15 per MTok", "`gpt-5.6-luna` — high-volume/cost-sensitive tier, same capability surface. 1.05M ctx / 128K out. $1/$7 per MTok. Classification, extraction, routing", "`gpt-5.5` — previous frontier default (2026-04-23; first OpenAI 1M-ctx model). Strong agentic coding (Terminal-Bench 2.0 82.7%); since 5.5 the mainline models power Codex directly — no separate codex model. $5/$30 per MTok", "`gpt-5.5-pro` — deep multi-step reasoning, Responses API only (multi-turn model interaction before answering); Batch-capable. 1.05M ctx / 128K out. $30/$180 per MTok — reserve for problems that pay for it", "`gpt-5.2-pro` — previous pro tier, Responses-only; OpenAI recommends gpt-5.5-pro for new work", "`text-embedding-3-small` / `text-embedding-3-large` — the two embedding models (large = highest quality incl. non-English; both support the dimensions parameter)", "`gpt-image-2` (state of the art) / `gpt-image-1` / `gpt-image-1-mini` — image generation+editing; dall-e-2/3 were REMOVED from the API 2026-05-12", "`gpt-realtime-2` — speech-to-speech realtime agents with configurable reasoning; `gpt-realtime-translate` — streaming speech translation (the Realtime beta was removed 2026-05-12); `gpt-4o-transcribe` — speech-to-text", "`GET /v1/models` — live listing; pin model IDs in ONE config point and verify at boot — this family turns over every few months"]}, "batches": {"endpoints": ["`POST /v1/batches` — async batch of requests at 50% discount (24h window); input via uploaded JSONL file", "`GET /v1/batches/{id}` — poll status; retrieve output file when complete"]}, "responses": {"endpoints": ["`POST /v1/responses` — primary generation surface (model, input, tools, stream); supports reasoning controls, function calling, built-in web search / file search / computer use", "Multi-turn state: pass previous_response_id to continue a conversation server-side", "`GET /v1/responses/{id}` — retrieve a stored response", "Structured output: json_schema response format for typed extraction"]}, "embeddings": {"endpoints": ["`POST /v1/embeddings` — model=text-embedding-3-small|large, input (string or array), optional dimensions to truncate", "Batch inputs in one call; store vectors with the content hash they were computed from"]}, "chat-completions": {"endpoints": ["`POST /v1/chat/completions` — the long-standing compatibility surface (messages[], tools, stream)", "Use for ecosystem tooling that expects this shape; new OpenAI features land on Responses first"]}}, "docsUrl": "https://developers.openai.com/api"}, "bestPractices": ["Use the Responses API for new work — it is the primary surface; Chat Completions remains the compatibility surface", "Pick the model tier per workload: terra for the product default, luna for high-volume paths, sol only where frontier reasoning pays for itself", "Stream responses for anything user-facing; buffer server-side only for pipelines", "Batch API for anything tolerant of async turnaround — 50% cost reduction", "Cache embeddings keyed by content hash; never recompute unchanged inputs", "Keep API keys server-side; the browser never calls OpenAI directly", "Handle 429/5xx with exponential backoff and a circuit breaker — provider incidents are a WHEN, not an IF"], "sdkInitPattern": "import OpenAI from ''openai'';\r\n\r\nconst client = new OpenAI({ apiKey: process.env.OPENAI_API_KEY }); // server-side only", "securityGuidance": "API keys are server-side secrets — never ship them to browsers or mobile apps; proxy model calls through your backend. Scope keys per project and set usage limits so a leaked key is a bounded incident. Do not send credentials, tokens, or unnecessary personal data in prompts, and treat model output as untrusted input: validate it before executing, rendering, or persisting it.", "setupInstructions": [{"url": "https://platform.openai.com", "type": "account_setup", "title": "Create an API key", "required": true, "instructions": "In the OpenAI platform dashboard, create a project and generate an API key scoped to it."}, {"type": "environment_variable", "title": "Provide the key as configuration", "required": true, "instructions": "Set OPENAI_API_KEY in server-side environment configuration only — the SDK reads it by default."}, {"type": "billing", "title": "Set usage limits", "required": false, "instructions": "Configure monthly usage limits in the platform billing settings so a leaked key or runaway loop is a bounded incident."}]}', '[{"kind": "source", "path": "src/ai/openai-client.ts", "priority": "essential", "description": "OpenAI client setup and configuration"}, {"kind": "source", "path": "src/ai/prompts/", "priority": "essential", "description": "System prompts and templates"}, {"kind": "source", "path": "src/ai/tools.ts", "priority": "recommended", "description": "Function calling / tool definitions"}]', '{"model": {"type": "enum", "label": "Model", "default": "gpt-5.6-terra", "options": ["gpt-5.6-sol", "gpt-5.6-terra", "gpt-5.6-luna", "gpt-5.5", "gpt-5.5-pro", "gpt-5.2-pro"], "required": true, "description": "Current family: GPT-5.6 (2026-07) — sol = flagship, terra = intelligence/cost balance (the production default; matches GPT-5.5 at ~half cost), luna = high-volume. gpt-5.5 remains strong for agentic coding; the -pro models are Responses-only deep reasoning. Per-model capabilities: select the models area in API areas"}, "apiAreas": {"type": "multiselect", "label": "OpenAI API areas used", "options": ["responses", "chat-completions", "embeddings", "images", "audio", "batches", "models"], "description": "Which parts of the OpenAI API this component calls — selected areas'' endpoint reference is embedded in the build instructions (the models area = the per-model capability matrix)"}, "streaming": {"type": "boolean", "label": "Streaming responses", "default": true, "description": "SSE streaming to the client — an architecture choice (affects your API route + UI), not a per-request knob"}, "embeddingsModel": {"type": "enum", "label": "Embeddings model", "default": "text-embedding-3-small", "options": ["text-embedding-3-small", "text-embedding-3-large"], "description": "Only relevant when the embeddings area is used"}}', '["backend-service", "worker", "database"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#0D8566', '''-5.6'':6B,57C ''3'':66C ''50'':33B ''abstract'':49B ''altern'':42B ''anthrop'':38B ''api'':12B,55C,68C,82C,87C ''apikey'':80C ''app'':101C ''audio'':31B ''backend'':107C ''batch'':35B,67C ''behind'':50B ''bound'':122C ''browser'':98C ''built'':21B ''built-in'':20B ''call'':19B,60C,104C ''claud'':39B ''client'':77C ''common'':48B ''comput'':25B ''consid'':37B ''const'':76C ''control'':17B ''credenti'':127C ''data'':132C ''discount'':34B ''embed'':28B,65C ''execut'':145C ''famili'':8B ''frontier'':43B ''function'':18B,59C ''gateway'':52B ''generat'':30B ''gpt'':5B,56C ''imag'':29B ''import'':72C ''incid'':123C ''input'':141C ''interfac'':53B ''key'':83C,88C,109C,119C ''leak'':118C ''limit'':115C ''llm'':3B ''mobil'':100C ''model'':7B,103C,137C ''never'':94C ''new'':78C ''offici'':69C ''one'':51B ''openai'':1A,2A,70C,73C,75C,79C ''output'':62C,138C ''per'':110C ''persist'':148C ''person'':131C ''plus'':27B ''primari'':14B ''process'':36B ''process.env.openai'':81C ''project'':111C ''prompt'':134C ''provid'':4B,44B ''proxi'':102C ''reason'':16B ''render'':146C ''respons'':11B,54C ''scope'':108C ''sdk'':71C ''search'':24B ''secret'':93C ''send'':126C ''server'':85C,91C ''server-sid'':84C,90C ''set'':113C ''ship'':95C ''side'':86C,92C ''sol/terra/luna'':58C ''structur'':61C ''surfac'':15B ''text'':64C ''text-embed'':63C ''token'':128C ''treat'':136C ''two'':46B ''unnecessari'':130C ''untrust'':140C ''usag'':114C ''use'':26B ''valid'':142C ''via'':9B ''web/file'':23B');
INSERT INTO public.technology_catalog VALUES ('flutter', 'Flutter', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/flutter.png', '#02569B', '["mobile-app"]', '{"purpose": "Google''s cross-platform UI toolkit for building natively compiled applications for mobile, web, and desktop from a single Dart codebase. Flutter uses its own rendering engine (Skia/Impeller) rather than platform widgets, giving pixel-perfect control across platforms. Use when building mobile apps that need to run on both iOS and Android with a single codebase and a highly custom UI. Flutter excels at apps with rich animations, custom designs, and when team velocity across platforms matters more than native look-and-feel. Don''t use when you need deeply integrated platform-native UI that must look exactly like stock iOS/Android controls -- native SwiftUI/Jetpack Compose will feel more natural. Don''t use for simple content apps where React Native or a PWA would suffice with less toolchain complexity. Avoid if your team has no Dart experience and the project timeline is tight.", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (UI model, concurrency model, persistence, distribution); live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Flutter", "Dart", "Riverpod", "Bloc", "go_router", "freezed", "Hive/Drift", "Flutter DevTools"], "antiPatterns": ["Deeply nested widget trees making code unreadable (extract into separate widgets)", "Using setState everywhere instead of structured state management", "Not separating business logic from UI widgets", "Ignoring platform-specific adaptations (navigation patterns, keyboard behavior)", "Not using const constructors causing unnecessary widget rebuilds", "Building one massive widget instead of composing smaller specialized widgets"], "apiReference": {"docsUrl": "https://docs.flutter.dev"}, "bestPractices": ["Use Riverpod or Bloc for state management with clear separation from UI", "Follow widget composition over inheritance -- break UI into small, reusable widgets", "Implement go_router for declarative, deep-link-capable routing", "Use freezed for immutable data classes with union types", "Follow platform design guidelines (Material on Android, Cupertino on iOS)", "Write widget tests and golden tests for UI regression detection", "Use const constructors aggressively to optimize widget rebuild performance"], "sdkInitPattern": "flutter create my_app && cd my_app && flutter run\\n// lib/main.dart\\nimport ''package:flutter/material.dart'';\\nvoid main() => runApp(const MyApp());\\nclass MyApp extends StatelessWidget {\\n  const MyApp({super.key});\\n  @override\\n  Widget build(BuildContext context) {\\n    return MaterialApp(home: Scaffold(body: Center(child: Text(''Hello Flutter''))));\\n  }\\n}", "securityGuidance": "Never embed API keys or secrets in Dart code -- they are extractable from compiled binaries. Use platform-specific secure storage (flutter_secure_storage) for tokens. Implement certificate pinning for sensitive API connections. Validate and sanitize all user inputs. Use ProGuard/R8 on Android and bitcode on iOS to obfuscate release builds.", "commonApiPatterns": [{"name": "Stateful Widget", "description": "Stateful widget with setState for local state", "codeTemplate": "class Counter extends StatefulWidget {\\n  const Counter({super.key});\\n  @override\\n  State<Counter> createState() => _CounterState();\\n}\\nclass _CounterState extends State<Counter> {\\n  int _count = 0;\\n  @override\\n  Widget build(BuildContext context) {\\n    return ElevatedButton(\\n      onPressed: () => setState(() => _count++),\\n      child: Text(''Count: $_count''),\\n    );\\n  }\\n}"}, {"name": "Riverpod Provider", "description": "Riverpod async data fetching with loading/error states", "codeTemplate": "final usersProvider = FutureProvider<List<User>>((ref) async {\\n  final response = await http.get(Uri.parse(''$baseUrl/api/users''));\\n  return (jsonDecode(response.body) as List).map((j) => User.fromJson(j)).toList();\\n});\\n// In widget:\\nfinal users = ref.watch(usersProvider);\\nreturn users.when(\\n  data: (list) => ListView.builder(itemCount: list.length, itemBuilder: (_, i) => Text(list[i].name)),\\n  loading: () => const CircularProgressIndicator(),\\n  error: (e, _) => Text(''Error: $e''),\\n);"}, {"name": "Navigation", "description": "Declarative routing with go_router and path parameters", "codeTemplate": "final router = GoRouter(routes: [\\n  GoRoute(path: ''/'', builder: (_, __) => const HomeScreen()),\\n  GoRoute(path: ''/user/:id'', builder: (_, state) => UserScreen(id: state.pathParameters[''id'']!)),\\n]);"}], "setupInstructions": [{"url": "https://docs.flutter.dev/get-started/install", "type": "toolchain_install", "title": "Install Flutter SDK", "commands": ["git clone https://github.com/flutter/flutter.git -b stable", "export PATH=\"$PATH:$(pwd)/flutter/bin\"", "flutter doctor"], "required": true, "instructions": "Download and install the Flutter SDK. Add flutter/bin to your PATH."}, {"type": "toolchain_install", "title": "Configure Android SDK", "commands": ["flutter doctor --android-licenses"], "required": true, "instructions": "Install Android Studio and configure the Android SDK for Android builds. Accept Android licenses."}, {"type": "toolchain_install", "title": "Configure iOS Development (macOS only)", "commands": ["sudo xcode-select --switch /Applications/Xcode.app/Contents/Developer", "sudo xcodebuild -license accept"], "required": false, "instructions": "Install Xcode from the Mac App Store. Configure Xcode command line tools and accept the license."}, {"type": "dashboard_config", "title": "Configure App Signing", "required": false, "instructions": "Set up signing configurations for release builds. Android: generate a keystore. iOS: configure provisioning profiles in Apple Developer portal."}], "integrationPatterns": ["Firebase or Supabase for backend services (auth, database, storage)", "Platform channels for accessing native iOS/Android APIs not available in Dart", "CI/CD with Codemagic or GitHub Actions for automated builds and store deployment"], "configurationTemplate": "# pubspec.yaml\\nname: my_app\\ndescription: My Flutter application\\npublish_to: none\\nversion: 1.0.0+1\\n\\nenvironment:\\n  sdk: \">=3.2.0 <4.0.0\"\\n\\ndependencies:\\n  flutter:\\n    sdk: flutter\\n  flutter_riverpod: ^2.4.0\\n  go_router: ^13.0.0\\n  freezed_annotation: ^2.4.0\\n  json_annotation: ^4.8.0\\n\\ndev_dependencies:\\n  flutter_test:\\n    sdk: flutter\\n  build_runner: ^2.4.0\\n  freezed: ^2.4.0\\n  json_serializable: ^6.7.0"}', '[{"kind": "config", "path": "pubspec.yaml", "language": "yaml", "description": "Flutter project dependencies and configuration"}, {"kind": "source", "path": "lib/main.dart", "language": "dart", "description": "Application entry point"}, {"kind": "source", "path": "lib/app.dart", "language": "dart", "description": "Root application widget"}, {"kind": "source", "path": "lib/screens/home_screen.dart", "language": "dart", "description": "Home screen widget"}, {"kind": "source", "path": "test/widget_test.dart", "language": "dart", "description": "Widget test suite"}, {"kind": "config", "path": "analysis_options.yaml", "language": "yaml", "description": "Dart analyzer configuration"}]', '{"codegen": {"type": "enum", "label": "Serialization", "default": "freezed-json-serializable", "options": ["freezed-json-serializable", "manual"]}, "flavors": {"type": "boolean", "label": "Build flavors", "default": true, "description": "dev/staging/prod app ids and configs — retrofitting flavors later is painful"}, "targets": {"type": "multiselect", "label": "Targets", "options": ["ios", "android", "web", "windows", "macos", "linux"], "description": "One codebase, one node — say where it actually ships; each desktop target adds CI and signing work"}, "stateManagement": {"type": "enum", "label": "State management", "default": "riverpod", "options": ["riverpod", "bloc", "provider", "setState-only"]}, "platformChannels": {"type": "boolean", "label": "Native platform channels", "default": false, "description": "The Dart↔native boundary — every channel is code written twice, plan them"}}', '["web.rest-api", "auth.supabase-auth", "auth.firebase-auth"]', false, NULL, NULL, '2026-02-16 02:23:50.361867+00', '2026-08-30 12:07:23.877005+00', NULL, '#01467D', '''across'':41B,79B ''android'':56B,248C ''anim'':72B ''api'':208C,237C ''app'':47B,69B,122B,162C,165C ''applic'':14B ''avoid'':135B ''binari'':220C ''bitcod'':250C ''bloc'':152C ''bodi'':198C ''build'':11B,45B,190C,256C ''buildcontext'':191C ''cd'':163C ''center'':199C ''certif'':233C ''child'':200C ''code'':214C ''codebas'':24B,60B ''compil'':13B,219C ''complex'':134B ''compos'':111B ''connect'':238C ''const'':176C,183C ''content'':121B ''context'':192C ''control'':40B,108B ''creat'':160C ''cross'':6B ''cross-platform'':5B ''custom'':64B,73B ''dart'':23B,141B,150C,213C ''deepli'':95B ''design'':74B ''desktop'':19B ''devtool'':158C ''emb'':207C ''engin'':30B ''exact'':104B ''excel'':67B ''experi'':142B ''extend'':180C ''extract'':217C ''feel'':88B,113B ''flutter'':1A,2A,25B,66B,149C,157C,159C,166C,203C,227C ''flutter/material.dart'':172C ''freez'':155C ''give'':36B ''go'':153C ''googl'':3B ''hello'':202C ''high'':63B ''hive/drift'':156C ''home'':196C ''implement'':232C ''input'':244C ''integr'':96B ''io'':54B,252C ''ios/android'':107B ''key'':209C ''less'':132B ''lib/main.dart'':169C ''like'':105B ''look'':86B,103B ''look-and-feel'':85B ''main'':174C ''materialapp'':195C ''matter'':81B ''mobil'':16B,46B ''must'':102B ''myapp'':177C,179C,184C ''n'':168C,182C,186C,188C,193C,204C,205C ''nativ'':12B,84B,99B,109B,125B ''natur'':115B ''nclass'':178C ''need'':49B,94B ''never'':206C ''nimport'':170C ''nvoid'':173C ''obfusc'':254C ''overrid'':187C ''packag'':171C ''perfect'':39B ''pin'':234C ''pixel'':38B ''pixel-perfect'':37B