INSERT INTO public.technology_catalog VALUES ('cassandra', 'Cassandra', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/cassandra.png', '#1287b1', '["database"]', '{"purpose": "Distributed wide-column store designed for massive write throughput and linear horizontal scalability across data centers. Best for write-heavy workloads like event logging, IoT ingestion, messaging at petabyte scale. Requires careful data modeling around query patterns. Not suited for complex queries, transactions, or frequent schema changes.", "configMode": "declarative", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Apache Cassandra 4+", "DataStax Astra", "AWS Keyspaces", "CQL", "ScyllaDB (compatible)"], "antiPatterns": ["Using secondary indexes on high-cardinality columns", "Not denormalizing data (relational thinking)", "Using consistency level ALL in production", "Choosing Cassandra for small datasets or simple CRUD apps"], "apiReference": {"docsUrl": "https://cassandra.apache.org/doc/latest/"}, "bestPractices": ["Design tables around specific query patterns", "Choose partition keys for even data distribution", "Use appropriate consistency levels per query", "Keep partition sizes under 100MB", "Implement proper compaction strategy (STCS, LCS, or TWCS)", "Run regular repairs and monitor tombstones"], "sdkInitPattern": "import { Client } from ''cassandra-driver'';\n\nconst cassandra = new Client({\n  contactPoints: process.env.CASSANDRA_HOSTS.split('',''),\n  localDataCenter: ''dc1'',\n  keyspace: ''app'',\n  credentials: { username: process.env.CASSANDRA_USER, password: process.env.CASSANDRA_PASS },\n});\nconst rs = await cassandra.execute(''SELECT * FROM orders WHERE owner_id = ?'', [userId], { prepare: true });", "securityGuidance": "Switch authenticator/authorizer from AllowAll to password-based before any real data lands, change the default cassandra/cassandra superuser, and create per-application roles with keyspace-scoped grants. Enable client and internode encryption (cluster gossip crosses racks), keep JMX bound to localhost or authenticated, and always prepared statements — CQL injection is real. Partition keys shape isolation: owner-prefixed keys plus per-role keyspaces keep tenants apart."}', '[{"kind": "config", "path": "cassandra.yaml", "language": "yaml", "description": "Authenticator/authorizer (password-based), encryption options, seeds"}]', '{"compaction": {"type": "enum", "label": "Compaction", "default": "stcs-default", "options": ["stcs-default", "lcs-read-heavy", "twcs-time-series"]}, "consistencyDefault": {"type": "enum", "label": "Consistency default", "default": "local-quorum", "options": ["local-quorum", "one", "quorum"], "description": "The read/write consistency stance is the architecture — declare it once, deviate per-query deliberately"}}', '["backend-service", "event-stream"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#0E6B8E', '''4'':54C ''across'':17B ''allowal'':101C ''alway'':144C ''apach'':52C ''apart'':166C ''app'':77C ''applic'':120C ''around'':39B ''astra'':56C ''authent'':142C ''authenticator/authorizer'':99C ''aw'':57C ''await'':87C ''base'':105C ''best'':20B ''bound'':138C ''care'':36B ''cassandra'':1A,2A,53C,66C,69C ''cassandra-driv'':65C ''cassandra.execute'':88C ''cassandra/cassandra'':114C ''center'':19B ''chang'':51B,111C ''client'':63C,71C,128C ''cluster'':132C ''column'':6B ''compat'':61C ''complex'':45B ''const'':68C,85C ''contactpoint'':72C ''cql'':59C,147C ''creat'':117C ''credenti'':78C ''cross'':134C ''data'':18B,37B,109C ''datastax'':55C ''dc1'':75C ''default'':113C ''design'':8B ''distribut'':3B ''driver'':67C ''enabl'':127C ''encrypt'':131C ''event'':27B ''frequent'':49B ''gossip'':133C ''grant'':126C ''heavi'':24B ''horizont'':15B ''id'':94C ''import'':62C ''ingest'':30B ''inject'':148C ''internod'':130C ''iot'':29B ''isol'':154C ''jmx'':137C ''keep'':136C,164C ''key'':152C,158C ''keyspac'':58C,76C,124C,163C ''keyspace-scop'':123C ''land'':110C ''like'':26B ''linear'':14B ''localdatacent'':74C ''localhost'':140C ''log'':28B ''massiv'':10B ''messag'':31B ''model'':38B ''new'':70C ''order'':91C ''owner'':93C,156C ''owner-prefix'':155C ''partit'':151C ''pass'':84C ''password'':82C,104C ''password-bas'':103C ''pattern'':41B ''per'':119C,161C ''per-appl'':118C ''per-rol'':160C ''petabyt'':33B ''plus'':159C ''prefix'':157C ''prepar'':96C,145C ''process.env.cassandra'':80C,83C ''process.env.cassandra_hosts.split'':73C ''queri'':40B,46B ''rack'':135C ''real'':108C,150C ''requir'':35B ''role'':121C,162C ''rs'':86C ''scalabl'':16B ''scale'':34B ''schema'':50B ''scope'':125C ''scylladb'':60C ''select'':89C ''shape'':153C ''statement'':146C ''store'':7B ''suit'':43B ''superus'':115C ''switch'':98C ''tenant'':165C ''throughput'':12B ''transact'':47B ''true'':97C ''user'':81C ''userid'':95C ''usernam'':79C ''wide'':5B ''wide-column'':4B ''workload'':25B ''write'':11B,23B ''write-heavi'':22B');
INSERT INTO public.technology_catalog VALUES ('aws-rds', 'AWS RDS', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-rds.png', '#3B48CC', '["database"]', '{"purpose": "AWS managed relational database service supporting PostgreSQL, MySQL, MariaDB, Oracle, and SQL Server engines with automated backups, patching, and Multi-AZ failover. Best for traditional relational workloads on AWS where you want managed infrastructure without the enhanced performance of Aurora. Use RDS when you need a specific engine version, Oracle/SQL Server compatibility, or lower cost than Aurora for smaller workloads. Choose Aurora over RDS when you need higher throughput, auto-scaling storage, or global databases.", "configMode": "declarative", "provenance": {"notes": "Phase B5 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Placing RDS in public subnets", "Not enabling Multi-AZ for production", "Using RDS when Aurora Serverless v2 would be more cost-effective for variable workloads", "Hardcoding database credentials instead of using Secrets Manager", "Not setting up CloudWatch alarms for critical metrics"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/rds/"}, "bestPractices": ["Enable Multi-AZ for production workloads", "Use read replicas for read-heavy applications", "Enable automated backups with appropriate retention period", "Use IAM database authentication where possible", "Place RDS in private subnets with security groups", "Enable Performance Insights for query analysis"], "securityGuidance": "No public accessibility; the security group admits only the application tier. Let RDS manage the master password in Secrets Manager (--manage-master-user-password) and use IAM database authentication for application access where the engine supports it. Encrypt storage with KMS and require TLS in transit. Keep automated backups + deletion protection on for production — an unprotected prod instance is one API call from gone.", "configurationTemplate": "# Private Postgres instance, encrypted, no public access\r\naws rds create-db-instance --db-instance-identifier app-db \\\r\n  --engine postgres --db-instance-class db.t4g.medium --allocated-storage 50 \\\r\n  --master-username appadmin --manage-master-user-password \\\r\n  --no-publicly-accessible --storage-encrypted \\\r\n  --vpc-security-group-ids sg-app-tier --deletion-protection"}', '[{"kind": "schema", "path": "database/schema.sql", "priority": "essential", "description": "Database schema definitions"}, {"kind": "schema", "path": "database/migrations/", "priority": "essential", "description": "Database migration files"}, {"kind": "config", "path": "terraform/rds.tf", "priority": "recommended", "description": "RDS instance infrastructure definition"}, {"kind": "source", "path": "src/database/db-client.ts", "priority": "essential", "description": "Database connection client"}]', '{"engine": {"enum": ["postgresql", "mysql", "mariadb", "oracle", "sqlserver"], "type": "string", "label": "Engine", "default": "postgresql"}, "multiAz": {"type": "boolean", "label": "Multi-AZ", "default": true}, "storageType": {"enum": ["gp3", "io1", "io2"], "type": "string", "label": "Storage Type", "default": "gp3"}, "readReplicas": {"type": "number", "label": "Read Replicas", "default": 0}, "engineVersion": {"type": "string", "label": "Engine Version"}, "instanceClass": {"type": "string", "label": "Instance Class", "default": "db.t3.medium"}}', '["rest-api", "worker", "serverless-function"]', false, NULL, NULL, '2026-03-04 00:48:04.051147+00', '2026-08-30 12:07:23.877005+00', 'AWS RDS', '#2F3AA3', '''access'':84C,114C ''admit'':88C ''api'':143C ''applic'':91C,113C ''aurora'':45B,62B,67B ''authent'':111C ''auto'':76B ''auto-sc'':75B ''autom'':20B,130C ''aw'':1A,3A,5B,34B ''az'':26B ''backup'':21B,131C ''best'':28B ''call'':144C ''choos'':66B ''compat'':57B ''cost'':60B ''databas'':8B,81B,110C ''delet'':132C ''encrypt'':120C ''engin'':18B,53B,117C ''enhanc'':42B ''failov'':27B ''global'':80B ''gone'':146C ''group'':87C ''higher'':73B ''iam'':109C ''infrastructur'':39B ''instanc'':140C ''keep'':129C ''kms'':123C ''let'':93C ''lower'':59B ''manag'':6B,38B,95C,101C,103C ''manage-master-user-password'':102C ''mariadb'':13B ''master'':97C,104C ''multi'':25B ''multi-az'':24B ''mysql'':12B ''need'':50B,72B ''one'':142C ''oracl'':14B ''oracle/sql'':55B ''password'':98C,106C ''patch'':22B ''perform'':43B ''postgresql'':11B ''prod'':139C ''product'':136C ''protect'':133C ''public'':83C ''rds'':2A,4A,47B,69B,94C ''relat'':7B,31B ''requir'':125C ''scale'':77B ''secret'':100C ''secur'':86C ''server'':17B,56B ''servic'':9B ''smaller'':64B ''specif'':52B ''sql'':16B ''storag'':78B,121C ''support'':10B,118C ''throughput'':74B ''tier'':92C ''tls'':126C ''tradit'':30B ''transit'':128C ''unprotect'':138C ''use'':46B,108C ''user'':105C ''version'':54B ''want'':37B ''without'':40B ''workload'':32B,65B');
INSERT INTO public.technology_catalog VALUES ('haproxy', 'HAProxy', NULL, '#003366', '["load-balancer"]', '{"purpose": "Reliable, high-performance TCP/HTTP load balancer with advanced health checking and SSL termination", "configMode": "definition-as-code", "provenance": {"notes": "docsUrl stamped from model knowledge, checked by n10:verify-urls; body content predates provenance tracking. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["HAProxy", "HAProxy Enterprise", "DataPlane API"], "antiPatterns": ["Using TCP mode when HTTP mode provides better health checking and routing", "Not setting timeouts leading to connection leaks under load", "Exposing stats endpoint publicly without authentication", "Hardcoding backend server IPs instead of using DNS resolution", "Not configuring retries for transient backend failures"], "apiReference": {"docsUrl": "https://docs.haproxy.org/"}, "bestPractices": ["Use proper health check configuration", "Implement stick tables for session persistence", "Configure proper timeouts", "Use ACLs for routing rules", "Monitor with stats page", "Implement proper SSL termination"], "sdkInitPattern": "# /etc/haproxy/haproxy.cfg\\nglobal\\n  maxconn 50000\\n  log stdout format raw local0\\n\\ndefaults\\n  mode http\\n  timeout connect 5s\\n  timeout client 30s\\n  timeout server 30s\\n  option httplog\\n\\nfrontend http_front\\n  bind *:80\\n  default_backend app_servers\\n\\nbackend app_servers\\n  balance roundrobin\\n  server app1 10.0.1.10:3000 check\\n  server app2 10.0.1.11:3000 check", "securityGuidance": "Use TLS 1.2+ with strong cipher suites. Protect the stats endpoint with authentication and restrict to internal networks. Set connection and request timeouts to prevent slowloris attacks. Use stick tables for rate limiting and abuse detection. Disable unnecessary HTTP methods. Add security headers (HSTS, X-Frame-Options) via http-response set-header directives.", "commonApiPatterns": [{"name": "HTTPS Frontend", "description": "TLS termination with path-based backend routing", "codeTemplate": "frontend https_front\\n  bind *:443 ssl crt /etc/ssl/certs/combined.pem alpn h2,http/1.1\\n  http-request redirect scheme https unless { ssl_fc }\\n  use_backend api_servers if { path_beg /api }\\n  default_backend web_servers"}, {"name": "Health Checks", "description": "HTTP health checks with failure thresholds", "codeTemplate": "backend app_servers\\n  option httpchk GET /health\\n  http-check expect status 200\\n  server app1 10.0.1.10:3000 check inter 5s fall 3 rise 2\\n  server app2 10.0.1.11:3000 check inter 5s fall 3 rise 2"}, {"name": "Rate Limiting", "description": "IP-based rate limiting using stick tables", "codeTemplate": "frontend http_front\\n  stick-table type ip size 100k expire 30s store http_req_rate(10s)\\n  http-request track-sc0 src\\n  http-request deny deny_status 429 if { sc_http_req_rate(0) gt 100 }"}], "integrationPatterns": ["DNS or Consul for dynamic backend service discovery", "Let''s Encrypt with ACME for automated certificate management", "Prometheus via stats endpoint for metrics scraping", "Keepalived or VRRP for high-availability HAProxy pairs", "Kubernetes Ingress Controller (haproxy-ingress) for K8s integration"], "configurationTemplate": "global\\n  maxconn 50000\\n  log stdout format raw local0\\n  ssl-default-bind-ciphers TLS13-AES-256-GCM-SHA384:TLS13-AES-128-GCM-SHA256\\n  ssl-default-bind-options ssl-min-ver TLSv1.2\\n\\ndefaults\\n  mode http\\n  timeout connect 5s\\n  timeout client 30s\\n  timeout server 30s\\n  option httplog\\n  option forwardfor\\n  option http-server-close\\n  retry-on all-retryable-errors\\n  retries 3\\n\\nlisten stats\\n  bind *:8404\\n  stats enable\\n  stats uri /stats\\n  stats auth admin:${STATS_PASSWORD}"}', '[{"kind": "config", "path": "haproxy.cfg", "language": "haproxy", "description": "HAProxy configuration"}]', '{"mode": {"type": "enum", "label": "Mode", "default": "http-l7", "options": ["http-l7", "tcp-l4"]}, "highAvailability": {"type": "enum", "label": "HA", "default": "single-node", "options": ["single-node", "keepalived-vrrp-pair"], "description": "A single load balancer is a single point of failure — the VRRP pair is the classic answer when it matters"}}', '["backend-service"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#002B55', '''/etc/haproxy/haproxy.cfg'':22C ''1.2'':86C ''10.0.1.10'':75C ''10.0.1.11'':81C ''3000'':76C,82C ''30s'':45C,49C ''50000'':26C ''5s'':41C ''80'':59C ''abus'':118C ''add'':124C ''advanc'':11B ''api'':21C ''app'':63C,67C ''app1'':74C ''app2'':80C ''attack'':110C ''authent'':96C ''backend'':62C ''balanc'':9B,70C ''bind'':58C ''check'':13B,77C,83C ''cipher'':89C ''client'':44C ''connect'':40C,103C ''dataplan'':20C ''default'':61C ''detect'':119C ''direct'':139C ''disabl'':120C ''endpoint'':94C ''enterpris'':19C ''format'':30C ''frame'':130C ''front'':56C ''haproxi'':1A,2A,17C,18C ''header'':126C,138C ''health'':12B ''high'':5B ''high-perform'':4B ''hsts'':127C ''http'':37C,55C,122C,134C ''http-respons'':133C ''httplog'':52C ''intern'':100C ''limit'':116C ''load'':8B ''local0'':32C ''log'':28C ''maxconn'':25C ''method'':123C ''mode'':36C ''n'':24C,27C,33C,35C,38C,42C,46C,50C,53C,57C,60C,65C,69C,72C,78C ''nbackend'':66C ''ndefault'':34C ''network'':101C ''nfrontend'':54C ''nglobal'':23C ''option'':51C,131C ''perform'':6B ''prevent'':108C ''protect'':91C ''rate'':115C ''raw'':31C ''reliabl'':3B ''request'':105C ''respons'':135C ''restrict'':98C ''roundrobin'':71C ''secur'':125C ''server'':48C,64C,68C,73C,79C ''set'':102C,137C ''set-head'':136C ''slowlori'':109C ''ssl'':15B ''stat'':93C ''stdout'':29C ''stick'':112C ''strong'':88C ''suit'':90C ''tabl'':113C ''tcp/http'':7B ''termin'':16B ''timeout'':39C,43C,47C,106C ''tls'':85C ''unnecessari'':121C ''use'':84C,111C ''via'':132C ''x'':129C ''x-frame-opt'':128C');
INSERT INTO public.technology_catalog VALUES ('aws-cognito', 'AWS Cognito', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-cognito.png', '#dd344c', '["auth-provider"]', '{"purpose": "AWS managed identity service providing User Pools for user directory and authentication, Identity Pools for AWS credential federation, Lambda triggers for custom workflows, and deep integration with API Gateway, ALB, and other AWS services", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Amazon Cognito", "Amplify Auth", "aws-amplify", "@aws-sdk/client-cognito-identity-provider", "Cognito User Pools", "Cognito Identity Pools", "AWS CDK", "Terraform AWS Provider"], "antiPatterns": ["Using Identity Pools when User Pools alone suffice", "Not implementing MFA for production applications", "Complex Lambda trigger chains that create brittle auth flows", "Not configuring account recovery options", "Hardcoding User Pool IDs in application code", "Not handling token refresh properly", "Using admin-level SDK calls from client-side code"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/cognito/"}, "bestPractices": ["Use User Pools for user directory management and authentication", "Use Identity Pools only when AWS credential federation is needed", "Configure proper password policies and account recovery", "Use Lambda triggers (pre-signup, post-confirmation, custom-message) for custom workflows", "Implement MFA for sensitive applications", "Use Cognito Groups for role-based access with IAM role mapping", "Deploy infrastructure as code with CDK or Terraform", "Use Advanced Security Features for adaptive authentication", "Configure proper app client settings (token validity, OAuth scopes)", "Implement proper token refresh handling in the client"], "sdkInitPattern": "import { CognitoIdentityProviderClient, InitiateAuthCommand } from ''@aws-sdk/client-cognito-identity-provider'';\n\nconst cognito = new CognitoIdentityProviderClient({});\nconst res = await cognito.send(new InitiateAuthCommand({\n  AuthFlow: ''USER_PASSWORD_AUTH'',\n  ClientId: process.env.COGNITO_CLIENT_ID,\n  AuthParameters: { USERNAME: email, PASSWORD: password },\n}));\n// verify res.AuthenticationResult.IdToken server-side (issuer, audience, expiry) on every request", "securityGuidance": "Verify JWTs server-side on every request — signature against the pool''s JWKS, issuer, audience (client id), expiry, and token_use; client-asserted identity is not identity. Public app clients get no secret (use SRP/authorization-code + PKCE flows), enable advanced security features (adaptive auth, compromised-credential checks) and MFA, and scope any identity-pool role mappings least-privilege — the credentials they vend are real AWS access.", "setupInstructions": [{"url": "https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-user-pools.html", "type": "dashboard_config", "title": "Create User Pool", "required": true, "instructions": "Create a Cognito User Pool in the AWS Console. Configure sign-in options (email, phone, username) and password policies."}, {"type": "dashboard_config", "title": "Create App Client", "required": true, "instructions": "Create an App Client in the User Pool settings. Configure OAuth 2.0 grant types and callback URLs."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export COGNITO_USER_POOL_ID=us-east-1_xxxxx", "export COGNITO_CLIENT_ID=your-client-id", "export COGNITO_REGION=us-east-1"], "required": true, "instructions": "Configure your Cognito User Pool ID, Client ID, and region in environment variables."}, {"type": "dashboard_config", "title": "Configure Identity Pool (Optional)", "required": false, "instructions": "If you need AWS service access from the client, create an Identity Pool linked to the User Pool for temporary AWS credentials."}]}', '[{"kind": "config", "path": "infra/cognito/user-pool.tf", "language": "hcl", "priority": "essential", "description": "Terraform configuration for Cognito User Pool"}, {"kind": "config", "path": "infra/cognito/identity-pool.tf", "language": "hcl", "priority": "recommended", "description": "Terraform configuration for Cognito Identity Pool"}, {"kind": "config", "path": "infra/cognito/triggers.tf", "language": "hcl", "priority": "recommended", "description": "Lambda trigger definitions for Cognito events"}, {"kind": "config", "path": "src/auth/cognito-config.ts", "language": "typescript", "priority": "essential", "description": "Amplify Auth or Cognito client configuration"}, {"kind": "source", "path": "src/auth/cognito-provider.tsx", "language": "typescript", "priority": "essential", "description": "React authentication provider using Amplify"}, {"kind": "source", "path": "lambdas/pre-signup/index.ts", "language": "typescript", "priority": "recommended", "description": "Pre Sign-Up Lambda trigger for validation"}, {"kind": "source", "path": "lambdas/post-confirmation/index.ts", "language": "typescript", "priority": "recommended", "description": "Post Confirmation Lambda trigger for provisioning"}, {"kind": "source", "path": "lambdas/custom-message/index.ts", "language": "typescript", "priority": "recommended", "description": "Custom Message Lambda trigger for email/SMS customization"}]', '{"mfa": {"type": "boolean", "label": "MFA Enabled", "default": false, "description": "Require multi-factor authentication"}, "region": {"type": "string", "label": "AWS Region", "default": "us-east-1", "description": "AWS region for Cognito resources"}, "hostedUI": {"type": "boolean", "label": "Hosted UI", "default": false, "description": "Use Cognito Hosted UI for authentication"}, "selfSignUp": {"type": "boolean", "label": "Self Sign-Up", "default": true, "description": "Allow users to register themselves"}, "userPoolId": {"type": "string", "label": "User Pool ID", "description": "Cognito User Pool identifier"}, "identityPoolId": {"type": "string", "label": "Identity Pool ID", "description": "Cognito Identity Pool identifier for AWS credential federation"}}', '["backend-service", "serverless-function", "frontend-app", "api-gateway", "rest-api"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#B82A3E', '''/client-cognito-identity-provider'':49C,68C ''access'':172C ''adapt'':146C ''advanc'':143C ''alb'':34B ''amazon'':39C ''amplifi'':41C,45C ''api'':32B ''app'':133C ''assert'':127C ''audienc'':98C,118C ''auth'':42C,82C,147C ''authent'':16B ''authflow'':79C ''authparamet'':87C ''aw'':1A,3A,5B,20B,37B,44C,47C,56C,59C,66C,171C ''await'':75C ''aws-amplifi'':43C ''aws-sdk'':46C,65C ''cdk'':57C ''check'':151C ''client'':85C,119C,126C,134C ''client-assert'':125C ''clientid'':83C ''cognito'':2A,4A,40C,50C,53C,70C ''cognito.send'':76C ''cognitoidentityprovidercli'':62C,72C ''compromis'':149C ''compromised-credenti'':148C ''const'':69C,73C ''credenti'':21B,150C,166C ''custom'':26B ''deep'':29B ''directori'':14B ''email'':89C ''enabl'':142C ''everi'':101C,109C ''expiri'':99C,121C ''featur'':145C ''feder'':22B ''flow'':141C ''gateway'':33B ''get'':135C ''id'':86C,120C ''ident'':7B,17B,54C,128C,131C,158C ''identity-pool'':157C ''import'':61C ''initiateauthcommand'':63C,78C ''integr'':30B ''issuer'':97C,117C ''jwks'':116C ''jwts'':104C ''lambda'':23B ''least'':163C ''least-privileg'':162C ''manag'':6B ''map'':161C ''mfa'':153C ''new'':71C,77C ''password'':81C,90C,91C ''pkce'':140C ''pool'':11B,18B,52C,55C,114C,159C ''privileg'':164C ''process.env.cognito'':84C ''provid'':9B,60C ''public'':132C ''real'':170C ''request'':102C,110C ''res'':74C ''res.authenticationresult.idtoken'':93C ''role'':160C ''scope'':155C ''sdk'':48C,67C ''secret'':137C ''secur'':144C ''server'':95C,106C ''server-sid'':94C,105C ''servic'':8B,38B ''side'':96C,107C ''signatur'':111C ''s