INSERT INTO public.technology_catalog VALUES ('kafka', 'Apache Kafka', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/kafka.png', '#231f20', '["event-stream", "message-broker"]', '{"purpose": "Distributed event streaming platform designed for high-throughput, fault-tolerant, real-time data pipelines and event-driven architectures. Kafka persists events as an immutable, ordered, replayable log partitioned across brokers. Use when you need durable event sourcing, stream processing, change data capture (CDC), or when multiple consumers need to independently process the same events at their own pace. Kafka excels at high-volume log aggregation, real-time analytics pipelines, and connecting disparate systems with a central event backbone. Don''t use for simple task queues where SQS or RabbitMQ is simpler to operate. Don''t use for low-volume messaging where the operational overhead of Kafka clusters is not justified. Avoid when you need request/reply patterns -- Kafka is designed for asynchronous fire-and-forget streaming, not synchronous communication.", "configMode": "declarative", "provenance": {"notes": "docsUrl is the vendor''s canonical documentation root, stamped from model knowledge and checked by scripts/n10-verify-docs-urls.ts; pre-existing body content not yet live-docs verified — upgrade at this row''s enrichment chunk.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Apache Kafka", "Confluent Cloud", "Amazon MSK", "KRaft", "Schema Registry", "Kafka Connect", "kafkajs", "Kafka Streams"], "antiPatterns": ["Using Kafka for simple request/reply or RPC-style communication", "Creating too many topics with few partitions instead of fewer well-partitioned topics", "Not monitoring consumer group lag causing undetected processing delays", "Using Kafka without a schema registry allowing breaking schema changes", "Setting replication factor to 1 in production risking data loss on broker failure", "Processing messages without idempotency causing duplicate side effects on redelivery"], "apiReference": {"docsUrl": "https://kafka.apache.org/documentation/"}, "bestPractices": ["Choose partition keys that distribute load evenly and maintain ordering within a logical entity", "Use consumer groups with multiple partitions for parallel, scalable consumption", "Set appropriate retention policies based on replay requirements (time or size based)", "Use idempotent producers (enable.idempotence=true) to prevent duplicate messages", "Schema Registry (Avro/Protobuf) for contract enforcement between producers and consumers", "Monitor consumer lag to detect slow consumers before they fall too far behind", "Use compacted topics for changelog/state-store patterns"], "freshnessNote": "Kafka 4.x is KRaft-ONLY — ZooKeeper was removed entirely in 4.0 (deprecated since 3.3); do not generate zookeeper.connect configuration, it is a dead architecture. 4.2 made Share Groups (native queue semantics) production-ready; brokers require Java 17. Previous inspector schema was connection-string fields (brokers/host arrays) — replaced with architecture decisions; wiring lives in env vars.", "sdkInitPattern": "// Node.js with kafkajs\\nimport { Kafka } from \"kafkajs\";\\nconst kafka = new Kafka({ clientId: \"my-app\", brokers: (process.env.KAFKA_BROKERS || \"localhost:9092\").split(\",\") });\\n// [Tailor to project language: Python=confluent-kafka-python, Go=confluent-kafka-go, Java=kafka-clients, Rust=rdkafka]", "securityGuidance": "Enable SASL/SCRAM or mTLS authentication for all client connections. Use ACLs to restrict which users/services can produce or consume from specific topics. Enable encryption in transit with TLS. Disable auto.create.topics.enable to prevent unauthorized topic creation. Use Schema Registry to enforce data contracts between producers and consumers.", "commonApiPatterns": [{"name": "Producer", "description": "Idempotent producer with keyed messages and headers", "codeTemplate": "const producer = kafka.producer({ idempotent: true });\\nawait producer.connect();\\nawait producer.send({\\n  topic: \"orders\",\\n  messages: [{ key: orderId, value: JSON.stringify({ orderId, total, items }), headers: { source: \"order-service\" } }]\\n});"}, {"name": "Consumer Group", "description": "Consumer group with auto-offset management", "codeTemplate": "const consumer = kafka.consumer({ groupId: \"order-processor\" });\\nawait consumer.connect();\\nawait consumer.subscribe({ topic: \"orders\", fromBeginning: false });\\nawait consumer.run({\\n  eachMessage: async ({ topic, partition, message }) => {\\n    const order = JSON.parse(message.value!.toString());\\n    await processOrder(order);\\n  }\\n});"}, {"name": "Batch Consumer", "description": "Batch consumer with manual offset control and heartbeats", "codeTemplate": "await consumer.run({\\n  eachBatch: async ({ batch, resolveOffset, heartbeat }) => {\\n    for (const message of batch.messages) {\\n      await processMessage(message);\\n      resolveOffset(message.offset);\\n      await heartbeat();\\n    }\\n  }\\n});"}], "integrationPatterns": ["Kafka Connect for CDC from databases (Debezium) and sink to data warehouses", "Schema Registry (Avro/Protobuf/JSON Schema) for producer-consumer contract management", "Stream processing with Kafka Streams, Flink, or ksqlDB for real-time transformations"], "configurationTemplate": "# server.properties key settings\\nnum.partitions=12\\ndefault.replication.factor=3\\nmin.insync.replicas=2\\nlog.retention.hours=168\\nlog.segment.bytes=1073741824\\nauto.create.topics.enable=false\\ncompression.type=lz4"}', '[{"kind": "source", "path": "src/kafka/producer.ts", "priority": "essential", "description": "Kafka producer configuration"}, {"kind": "source", "path": "src/kafka/consumer.ts", "priority": "essential", "description": "Kafka consumer configuration"}, {"kind": "source", "path": "src/kafka/topics.ts", "priority": "recommended", "description": "Topic definitions"}, {"kind": "schema", "path": "avro/schemas/", "priority": "recommended", "description": "Avro schema definitions"}]', '{"messagingModel": {"type": "enum", "label": "Messaging model", "default": "consumer-groups-streaming", "options": ["consumer-groups-streaming", "share-groups-queue-semantics"], "description": "Classic partition-ordered streaming vs Share Groups (production-ready in 4.2): per-message ack, unordered — Kafka''s native queue story"}, "schemaRegistry": {"type": "enum", "label": "Schema registry", "default": "none-json", "options": ["none-json", "confluent-schema-registry", "apicurio"], "description": "Typed topics (Avro/Protobuf) need a registry; JSON-without-registry is fine until the first breaking producer change"}, "topicManagement": {"type": "enum", "label": "Topic management", "default": "declarative-iac", "options": ["declarative-iac", "application-created"], "description": "Topics, partitions and retention declared in IaC vs auto-created by apps — auto-creation in production is the classic footgun"}}', '["backend-service", "worker", "database"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#1A1718', '''9092'':173C ''acl'':206C ''across'':36B ''aggreg'':73B ''amazon'':144C ''analyt'':77B ''apach'':1A,140C ''app'':168C ''architectur'':25B ''asynchron'':131B ''authent'':200C ''auto.create.topics.enable'':225C ''avoid'':121B ''backbon'':87B ''broker'':37B,169C,171C ''captur'':49B ''cdc'':50B ''central'':85B ''chang'':47B ''client'':193C,203C ''clientid'':165C ''cloud'':143C ''cluster'':117B ''communic'':139B ''confluent'':142C,182C,187C ''confluent-kafka-go'':186C ''confluent-kafka-python'':181C ''connect'':80B,150C,204C ''consum'':54B,214C,241C ''contract'':237C ''creation'':230C ''data'':19B,48B,236C ''design'':8B,129B ''disabl'':224C ''dispar'':81B ''distribut'':4B ''driven'':24B ''durabl'':42B ''enabl'':196C,218C ''encrypt'':219C ''enforc'':235C ''event'':5B,23B,28B,43B,61B,86B ''event-driven'':22B ''excel'':67B ''fault'':14B ''fault-toler'':13B ''fire'':133B ''fire-and-forget'':132B ''forget'':135B ''go'':185C,189C ''high'':11B,70B ''high-throughput'':10B ''high-volum'':69B ''immut'':31B ''independ'':57B ''java'':190C ''justifi'':120B ''kafka'':2A,3A,26B,66B,116B,127B,141C,149C,152C,158C,162C,164C,183C,188C,192C ''kafka-cli'':191C ''kafkaj'':151C,156C,160C ''kraft'':146C ''languag'':179C ''localhost'':172C ''log'':34B,72B ''low'':108B ''low-volum'':107B ''messag'':110B ''msk'':145C ''mtls'':199C ''multipl'':53B ''my-app'':166C ''n'':175C ''nconst'':161C ''need'':41B,55B,124B ''new'':163C ''nimport'':157C ''node.js'':154C ''oper'':102B,113B ''order'':32B ''overhead'':114B ''pace'':65B ''partit'':35B ''pattern'':126B ''persist'':27B ''pipelin'':20B,78B ''platform'':7B ''prevent'':227C ''process'':46B,58B ''process.env.kafka'':170C ''produc'':212C,239C ''project'':178C ''python'':180C,184C ''queue'':94B ''rabbitmq'':98B ''rdkafka'':195C ''real'':17B,75B ''real-tim'':16B,74B ''registri'':148C,233C ''replay'':33B ''request/reply'':125B ''restrict'':208C ''rust'':194C ''sasl/scram'':197C ''schema'':147C,232C ''simpl'':92B ''simpler'':100B ''sourc'':44B ''specif'':216C ''split'':174C ''sqs'':96B ''stream'':6B,45B,136B,153C ''synchron'':138B ''system'':82B ''tailor'':176C ''task'':93B ''throughput'':12B ''time'':18B,76B ''tls'':223C ''toler'':15B ''topic'':217C,229C ''transit'':221C ''unauthor'':228C ''use'':38B,90B,105B,205C,231C ''users/services'':210C ''volum'':71B,109B');
INSERT INTO public.technology_catalog VALUES ('gcp', 'Google Cloud Platform', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/gcp.png', '#4285F4', '["gcp"]', '{"purpose": "GCP cloud provider identifier for infrastructure container nodes. Use this as the technology for cloud-project, vpc, and subnet roles when the deployment target is GCP. Individual GCP services have their own technology entries and should be assigned to their respective leaf-role nodes, NOT to infrastructure containers.", "lifecycle": "platform-umbrella", "provenance": {"notes": "B10 lifecycle stamp; body content predates provenance tracking. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Google Cloud Deployment Manager", "Terraform", "gcloud CLI", "Cloud Asset Inventory"], "antiPatterns": ["Using a single project for all environments", "Exporting service account keys instead of using workload identity", "Running resources without organization policies or folder hierarchy", "Leaving default compute service account with Editor role", "Ignoring VPC Service Controls for projects handling sensitive data"], "bestPractices": ["Use Shared VPCs for multi-project networking", "Enable Cloud Audit Logs", "Use projects for resource isolation", "Implement organization policies"], "sdkInitPattern": "gcloud init && gcloud config set project my-project-id && gcloud auth application-default login", "securityGuidance": "Enable Cloud Audit Logs for all projects. Use Organization Policies to enforce constraints (e.g., restrict public IP creation). Implement VPC Service Controls for sensitive data perimeters. Use Workload Identity Federation instead of exported service account keys. Enable Security Command Center for threat detection. Use hierarchical firewall policies at the organization level.", "commonApiPatterns": [{"name": "Create Project", "description": "Create a GCP project under an organization folder with billing", "codeTemplate": "gcloud projects create my-project-prod --name=\"My Project Prod\" --folder=123456 && gcloud billing projects link my-project-prod --billing-account=BILLING_ID"}, {"name": "Enable APIs", "description": "Enable required APIs for a project", "codeTemplate": "gcloud services enable compute.googleapis.com container.googleapis.com cloudsql.googleapis.com --project=my-project-prod"}, {"name": "Set IAM Policy", "description": "Grant IAM role to a service account", "codeTemplate": "gcloud projects add-iam-policy-binding my-project-prod --member=\"serviceAccount:sa@project.iam.gserviceaccount.com\" --role=\"roles/compute.admin\""}], "integrationPatterns": ["Cloud Identity + IAM for organization-wide access management", "Cloud Logging + Cloud Monitoring for centralized observability", "Organization Policies for governance at scale", "Cloud Build or GitHub Actions for CI/CD pipelines", "Cloud Billing + Budgets for cost governance"], "configurationTemplate": "# GCP Organization pattern (Terraform)\\nprovider \"google\" {\\n  project = var.project_id\\n  region  = var.region\\n}\\nresource \"google_project\" \"main\" {\\n  name       = var.project_name\\n  project_id = var.project_id\\n  org_id     = var.org_id\\n  billing_account = var.billing_account\\n  labels = {\\n    environment = var.environment\\n    managed_by  = \"terraform\"\\n  }\\n}"}', '[]', '{}', '[]', false, NULL, NULL, '2026-02-20 14:25:20.585755+00', '2026-08-30 12:07:23.877005+00', NULL, '#3367C2', '''account'':115C ''applic'':78C ''application-default'':77C ''asset'':63C ''assign'':43B ''audit'':83C ''auth'':76C ''center'':120C ''cli'':61C ''cloud'':2A,6B,20B,56C,62C,82C ''cloud-project'':19B ''command'':119C ''config'':68C ''constraint'':93C ''contain'':11B,54B ''control'':102C ''creation'':98C ''data'':105C ''default'':79C ''deploy'':28B,57C ''detect'':123C ''e.g'':94C ''enabl'':81C,117C ''enforc'':92C ''entri'':39B ''export'':113C ''feder'':110C ''firewal'':126C ''gcloud'':60C,65C,67C,75C ''gcp'':4A,5B,31B,33B ''googl'':1A,55C ''hierarch'':125C ''id'':74C ''ident'':109C ''identifi'':8B ''implement'':99C ''individu'':32B ''infrastructur'':10B,53B ''init'':66C ''instead'':111C ''inventori'':64C ''ip'':97C ''key'':116C ''leaf'':48B ''leaf-rol'':47B ''level'':131C ''log'':84C ''login'':80C ''manag'':58C ''my-project-id'':71C ''node'':12B,50B ''organ'':89C,130C ''perimet'':106C ''platform'':3A ''polici'':90C,127C ''project'':21B,70C,73C,87C ''provid'':7B ''public'':96C ''respect'':46B ''restrict'':95C ''role'':25B,49B ''secur'':118C ''sensit'':104C ''servic'':34B,101C,114C ''set'':69C ''subnet'':24B ''target'':29B ''technolog'':17B,38B ''terraform'':59C ''threat'':122C ''use'':13B,88C,107C,124C ''vpc'':22B,100C ''workload'':108C');
INSERT INTO public.technology_catalog VALUES ('nats', 'NATS', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/nats.png', '#27aae1', '["event-stream", "message-broker"]', '{"purpose": "Lightweight, high-performance messaging system designed for cloud-native applications, microservices, and IoT. NATS provides pub/sub, request/reply, and queue groups out of the box with extremely low latency. JetStream adds persistence, exactly-once delivery, and stream processing. Use when you need simple, fast service-to-service communication with minimal operational overhead, when you want a single messaging system that handles pub/sub, queues, and key-value without separate infrastructure. NATS is ideal for command-and-control patterns, service discovery, and ephemeral event routing. Don''t use when you need durable, replayed event streams with long retention -- Kafka is better for event sourcing. Don''t use for guaranteed delivery without JetStream enabled. Avoid when your team already has deep Kafka or RabbitMQ expertise and those systems meet your needs.", "configMode": "declarative", "provenance": {"notes": "docsUrl is the vendor''s canonical documentation root, stamped from model knowledge and checked by scripts/n10-verify-docs-urls.ts; pre-existing body content not yet live-docs verified — upgrade at this row''s enrichment chunk.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["NATS Server", "JetStream", "NATS CLI (nats)", "nats.js", "nats.go", "nats.py", "NATS Helm Chart", "Synadia Cloud"], "antiPatterns": ["Using core NATS (without JetStream) for messages that must not be lost", "Not implementing reconnection logic causing silent message loss during network issues", "Creating overly broad subject subscriptions processing irrelevant messages", "Using NATS for large binary file transfer instead of object storage with notifications", "Running a single NATS server in production without clustering", "Not setting stream limits causing unbounded disk usage with JetStream"], "apiReference": {"docsUrl": "https://docs.nats.io/"}, "bestPractices": ["Use JetStream for any workload requiring message persistence or exactly-once delivery", "Use queue groups for load-balanced message consumption across service instances", "Use subject hierarchies (e.g., orders.us.created) for flexible subscription filtering with wildcards", "Implement connection event handlers for reconnection and error logging", "Set appropriate message TTLs and stream limits to prevent unbounded storage growth", "Use request/reply pattern for synchronous service-to-service calls with timeouts", "Deploy a NATS cluster (3+ nodes) for production high availability"], "freshnessNote": "Previous inspector schema was host/port connection fields — replaced with architecture decisions (persistence stance, topology, subject design); wiring lives in env vars.", "sdkInitPattern": "// Node.js with nats\\nimport { connect, StringCodec } from \"nats\";\\nconst nc = await connect({ servers: process.env.NATS_URL || \"nats://localhost:4222\" });\\nconst sc = StringCodec();\\n// [Tailor to project language: Go=nats.Connect, Python=nats.connect, Rust=async-nats, Java=io.nats.client]", "securityGuidance": "Enable TLS for all client and cluster connections. Use NKey or JWT-based authentication instead of plain passwords. Configure per-user/per-account publish and subscribe permissions to enforce topic isolation. Use NATS accounts for multi-tenant isolation. Never expose NATS ports directly to the internet without authentication.", "commonApiPatterns": [{"name": "Publish/Subscribe", "description": "Pub/sub with wildcard subject subscription", "codeTemplate": "nc.publish(\"orders.created\", sc.encode(JSON.stringify({ orderId, total })));\\nconst sub = nc.subscribe(\"orders.>\");\\nfor await (const msg of sub) {\\n  const order = JSON.parse(sc.decode(msg.data));\\n  console.log(`Received on ${msg.subject}:`, order);\\n}"}, {"name": "Request/Reply", "description": "Synchronous request/reply with timeout", "codeTemplate": "const response = await nc.request(\"users.lookup\", sc.encode(JSON.stringify({ email })), { timeout: 5000 });\\nconst user = JSON.parse(sc.decode(response.data));"}, {"name": "JetStream Consumer", "description": "Durable JetStream consumer with explicit acknowledgment", "codeTemplate": "const js = nc.jetstream();\\nconst consumer = await js.consumers.get(\"ORDERS\", \"order-processor\");\\nfor await (const msg of await consumer.consume()) {\\n  const order = JSON.parse(sc.decode(msg.data));\\n  await processOrder(order);\\n  msg.ack();\\n}"}, {"name": "Queue Group", "description": "Queue group for load-balanced consumption across instances", "codeTemplate": "const sub = nc.subscribe(\"tasks.process\", { queue: \"workers\" });\\nfor await (const msg of sub) {\\n  await handleTask(JSON.parse(sc.decode(msg.data)));\\n}"}], "integrationPatterns": ["Microservice event bus for loosely-coupled service communication", "JetStream KV store for lightweight distributed configuration", "Kubernetes-native deployment via NATS Helm chart with leaf node federation"], "configurationTemplate": "# nats-server.conf\\nport: 4222\\nhttp_port: 8222\\njetstream {\\n  store_dir: /data/jetstream\\n  max_mem: 1G\\n  max_file: 10G\\n}\\ncluster {\\n  name: my-cluster\\n  listen: 0.0.0.0:6222\\n  routes: [\\n    nats-route://nats-1:6222\\n    nats-route://nats-2:6222\\n  ]\\n}\\nauthorization {\\n  users: [\\n    { user: app, password: $APP_PASS, permissions: { publish: [\">\"], subscribe: [\">\"] } }\\n  ]\\n}"}', '[{"kind": "source", "path": "src/messaging/nats-client.ts", "priority": "essential", "description": "NATS connection and subscription management"}, {"kind": "source", "path": "src/messaging/subscribers/", "priority": "essential", "description": "Subject subscriber handlers"}]', '{"subjects": {"type": "enum", "label": "Subject design", "default": "hierarchical-wildcards", "options": ["hierarchical-wildcards", "flat"], "description": "orders.eu.created-style hierarchies with wildcard consumers are the NATS idiom"}, "deployment": {"type": "enum", "label": "Deployment", "default": "single-server", "options": ["single-server", "three-node-cluster", "leafnode-edge"]}, "persistence": {"type": "enum", "label": "Persistence", "default": "jetstream", "options": ["jetstream", "core-nats-ephemeral"], "description": "JetStream = durable streams/consumers + KV/object store; core NATS is fire-and-forget pub/sub — declaring which you depend on IS the durability contract"}}', '["backend-service", "worker"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#1F88B4', '''/per-account'':208C ''4222'':166C ''account'':219C ''add'':34B ''alreadi'':123B ''applic'':14B ''async'':181C ''async-nat'':180C ''authent'':199C,234C ''avoid'':119B ''await'':160C ''base'':198C ''better'':106B ''box'':28B ''chart'':147C ''cli'':140C ''client'':189C ''cloud'':12B,149C ''cloud-nat'':11B ''cluster'':191C ''command'':81B ''command-and-control'':80B ''communic'':53B ''configur'':204C ''connect'':154C,161C,192C ''control'':83B ''deep'':125B ''deliveri'':39B,115B ''design'':9B ''direct'':229C ''discoveri'':86B ''durabl'':97B ''enabl'':118B,185C ''enforc'':214C ''ephemer'':88B ''event'':89B,99B,108B ''exact'':37B ''exactly-onc'':36B ''expertis'':129B ''expos'':226C ''extrem'':30B ''fast'':48B ''go'':175C ''group'':24B ''guarante'':114B ''handl'':66B ''helm'':146C ''high'':5B ''high-perform'':4B ''ideal'':78B ''infrastructur'':75B ''instead'':200C ''internet'':232C ''io.nats.client'':184C ''iot'':17B ''isol'':216C,224C ''java'':183C ''jetstream'':33B,117B,138C ''jwt'':197C ''jwt-base'':196C ''kafka'':104B,126B ''key'':71B ''key-valu'':70B ''languag'':174C ''latenc'':32B ''lightweight'':3B ''localhost'':165C ''long'':102B ''low'':31B ''meet'':133B ''messag'':7B,63B ''microservic'':15B ''minim'':55B ''multi'':222C ''multi-ten'':221C ''n'':170C ''nat'':1A,2A,18B,76B,136C,139C,141C,145C,152C,157C,182C,218C,227C ''nativ'':13B ''nats.connect'':176C,178C ''nats.go'':143C ''nats.js'':142C ''nats.py'':144C ''nc'':159C ''nconst'':158C,167C ''need'':46B,96B,135B ''never'':225C ''nimport'':153C ''nkey'':194C ''node.js'':150C ''oper'':56B ''overhead'':57B ''password'':203C ''pattern'':84B ''per'':206C ''per-us'':205C ''perform'':6B ''permiss'':212C ''persist'':35B ''plain'':202C ''port'':228C ''process'':42B ''process.env.nats'':163C ''project'':173C ''provid'':19B ''pub/sub'':20B,67B ''publish'':209C ''python'':177C ''queue'':23B,68B ''rabbitmq'':128B ''replay'':98B ''request/reply'':21B ''retent'':103B ''rout'':90B ''rust'':179C ''sc'':168C ''separ'':74B ''server'':137C,162C ''servic'':50B,52B,85B ''service-to-servic'':49B ''simpl'':47B ''singl'':62B ''sourc'':109B ''stream'':41B,100B ''stringcodec'':155C,169C ''subscrib'':211C ''synadia'':148C ''system'':8B,64B,132B ''tailor'':171C ''team'':122B ''tenant'':223C ''tls'':186C ''topic'':215C ''url'':164C ''use'':43B,93B,112B,193C,217C ''user'':207C ''valu'':72B ''want'':60B ''without'':73B,116B,233C');
INSERT INTO public.technology_catalog VALUES ('langchain', 'LangChain', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/langchain.png', '#1c3c3c', '["inference-service", "ml-pipeline"]', '{"purpose": "LLM orchestration framework for composing chains, agents, RAG pipelines, and tool-calling workflows. Supports LangChain Expression Language (LCEL) for declarative chain composition and LangSmith for observability. Best for multi-step LLM workflows, agentic systems, and retrieval-augmented generation. Not a direct LLM provider — requires an underlying model (OpenAI, Anthropic, etc.).", "configMode": "code", "provenance": {"notes": "Phase B8c additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["LangChain", "LangSmith", "LCEL", "LangGraph", "LangServe", "Python", "TypeScript", "Vector Stores", "Agents", "Tool Calling"], "antiPatterns": ["Overly complex chains when a single LLM call suffices", "Not implementing streaming for user-facing applications", "Missing error handling in agent tool execution", "Not using LangSmith for debugging and monitoring", "Ignoring token costs across chained calls", "Using LangChain abstractions for trivial single-call patterns"], "apiReference": {"docsUrl": "https://js.langchain.com/docs/"}, "bestPractices": ["Use LCEL for declarative chain composition", "Implement LangSmith tracing for observability", "Use structured output parsers for reliable data extraction", "Implement memory for conversational context", "Use LangGraph for complex stateful agent workflows", "Cache expensive LLM calls with caching layer", "Implement proper error handling and fallback chains", "Version prompts and chain configurations"], "sdkInitPattern": "import { ChatAnthropic } from ''@langchain/anthropic'';\nimport { ChatPromptTemplate } from ''@langchain/core/prompts'';\n\nconst model = new ChatAnthropic({ model: ''claude-sonnet-5'' }); // ANTHROPIC_API_KEY from env\nconst prompt = ChatPromptTemplate.fromMessages([\n  [''system'', ''Answer using ONLY the provided context.''],\n  [''human'', ''Context: {context}\\n\\nQuestion: {question}''],\n]);\nconst answer = await prompt.pipe(model).invoke({ context, question });", "securityGuidance": "Provider keys stay server-side in environment config — chains never run in the browser with real credentials. Retrieved documents and user input entering prompts are untrusted: prompt injection via retrieved content is the standard attack, so treat model output as untrusted too — never eval it, never pass it unvalidated to tools that mutate state. Scope every tool given to an agent to least privilege (a SQL tool gets a read-only connection), and callbacks/tracing (LangSmith) capture full prompts and completions: decide deliberately what leaves your boundary."}', '[{"kind": "source", "path": "src/ai/chains/", "priority": "essential", "description": "LangChain chain definitions"}, {"kind": "source", "path": "src/ai/agents/", "priority": "essential", "description": "Agent configurations and tool definitions"}, {"kind": "source", "path": "src/ai/prompts/", "priority": "recommended", "description": "Prompt templates and few-shot examples"}]', '{"agentType": {"type": "enum", "label": "Agent Type", "default": "none", "options": ["none", "tool-calling", "react", "langgraph", "plan-and-execute"], "description": "Agent architecture pattern"}, "framework": {"type": "enum", "label": "Framework", "default": "langchain-python", "options": ["langchain-python", "langchain-js"], "required": true, "description": "LangChain runtime language"}, "llmProvider": {"type": "enum", "label": "LLM Provider", "default": "openai", "options": ["openai", "anthropic", "aws-bedrock", "google-vertex", "open-source-llm", "custom"], "description": "Underlying LLM provider"}}', '["database", "ai-service", "backend-service"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#162F2F', '''5'':84C ''agent'':9B,37B,65C,175C ''answer'':94C,107C ''anthrop'':54B,85C ''api'':86C ''attack'':149C ''augment'':42B ''await'':108C ''best'':30B ''boundari'':201C ''browser'':128C ''call'':15B,67C ''callbacks/tracing'':189C ''captur'':191C ''chain'':8B,24B,123C ''chatanthrop'':69C,79C ''chatprompttempl'':73C ''chatprompttemplate.frommessages'':92C ''claud'':82C ''claude-sonnet'':81C ''complet'':195C ''compos'':7B ''composit'':25B ''config'':122C ''connect'':187C ''const'':76C,90C,106C ''content'':145C ''context'':99C,101C,102C,112C ''credenti'':131C ''decid'':196C ''declar'':23B ''deliber'':197C ''direct'':46B ''document'':133C ''enter'':137C ''env'':89C ''environ'':121C ''etc'':55B ''eval'':158C ''everi'':170C ''express'':19B ''framework'':5B ''full'':192C ''generat'':43B ''get'':182C ''given'':172C ''human'':100C ''import'':68C,72C ''inject'':142C ''input'':136C ''invok'':111C ''key'':87C,115C ''langchain'':1A,2A,18B,56C ''langchain/anthropic'':71C ''langchain/core/prompts'':75C ''langgraph'':59C ''langserv'':60C ''langsmith'':27B,57C,190C ''languag'':20B ''lcel'':21B,58C ''least'':177C ''leav'':199C ''llm'':3B,35B,47B ''model'':52B,77C,80C,110C,152C ''multi'':33B ''multi-step'':32B ''mutat'':167C ''n'':103C ''never'':124C,157C,160C ''new'':78C ''nquestion'':104C ''observ'':29B ''openai'':53B ''orchestr'':4B ''output'':153C ''pass'':161C ''pipelin'':11B ''privileg'':178C ''prompt'':91C,138C,141C,193C ''prompt.pipe'':109C ''provid'':48B,98C,114C ''python'':61C ''question'':105C,113C ''rag'':10B ''read'':185C ''read-on'':184C ''real'':130C ''requir'':49B ''retriev'':41B,132C,144C ''retrieval-aug'':40B ''run'':125C ''scope'':169C ''server'':118C ''server-sid'':117C ''side'':119C ''sonnet'':83C ''sql'':180C ''standard'':148C ''state'':168C ''stay'':116C ''step'':34B ''store'':64C ''support'':17B ''system'':38B,93C ''tool'':14B,66C,165C,171C,181C ''tool-cal'':13B ''treat'':151C ''typescript'':62C ''under'':51B ''untrust'':140C,155C ''unvalid'':163C ''use'':95C ''user'':135C ''vector'':63C ''via'':143C ''workflow'':16B,36B');
INSERT INTO public.technology_catalog VALUES ('ruby-backend', 'Ruby', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/ruby.png', '#CC342D', '["backend-service", "worker", "webhook-handler"]', '{"purpose": "Dynamic, expressive programming language optimized for developer productivity, powering web applications and background processing with Rails and its ecosystem", "configMode": "code", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Ruby 3.3+", "Ruby on Rails 7+", "Sinatra", "Sidekiq", "ActiveRecord", "RSpec", "Puma", "Bundler", "Devise"], "antiPatterns": ["Fat controllers with business logic", "N+1 queries from not using includes/eager_load", "Monkey-patching core classes in production code", "Not using database indexes for frequently queried columns", "Skipping database migrations and modifying schema directly", "Using callbacks for complex business logic instead of service objects", "Not implementing proper error handling in background jobs"], "apiReference": {"docsUrl": "https://docs.ruby-lang.org/en/"}, "bestPractices": ["Follow Rails conventions (MVC, RESTful routes, ActiveRecord patterns)", "Use Sidekiq or GoodJob for background job processing", "Implement proper database migrations with reversible changes", "Use RSpec with FactoryBot for comprehensive testing", "Leverage concerns and service objects to keep controllers thin", "Use strong parameters for mass assignment protection", "Implement proper caching strategies (fragment, Russian doll, low-level)", "Use Bundler for dependency management with Gemfile.lock"], "sdkInitPattern": "# Rails controller — scope every query by the authenticated user\nclass OrdersController < ApplicationController\n  before_action :authenticate_user!\n\n  def index\n    render json: current_user.orders\n  end\n\n  def create\n    order = current_user.orders.create!(order_params)\n    render json: order, status: :created\n  end\n\n  private\n\n  def order_params\n    params.require(:order).permit(:product_id, :quantity)\n  end\nend", "securityGuidance": "Strong parameters on every write path — params.permit is the mass-assignment defense, and current_user-scoped queries (never Model.find on a client-supplied id without an ownership check) are the authorization floor. ActiveRecord parameterization protects you until someone string-interpolates into where/order — never do it. Never Marshal.load or YAML.unsafe_load untrusted data (both are RCE), keep secrets in credentials/environment not the repo, html_escape by default stays on, and bundle-audit the gemfile in CI."}', '[{"kind": "source", "path": "app/controllers/application_controller.rb", "language": "ruby", "description": "Base controller"}, {"kind": "source", "path": "config/routes.rb", "language": "ruby", "description": "Route definitions"}, {"kind": "source", "path": "app/models/", "language": "ruby", "description": "ActiveRecord models"}, {"kind": "config", "path": "Gemfile", "language": "ruby", "description": "Ruby dependency manifest"}, {"kind": "config", "path": "config/database.yml", "language": "yaml", "description": "Database configuration"}]', '{"framework": {"type": "enum", "label": "Framework", "default": "rails", "options": ["rails", "sinatra", "plain-ruby"], "description": "Rails (8.x era) is the reason to be in Ruby — full-stack conventions; Sinatra for tiny services"}, "backgroundJobs": {"type": "enum", "label": "Background jobs", "default": "solid-queue", "options": ["solid-queue", "sidekiq", "none"], "description": "Solid Queue is the Rails-8-era database-backed default; Sidekiq where Redis-backed throughput is needed"}}', '["database", "cache", "message-broker"]', false, NULL, NULL, '2026-03-31 13:54:56.372888+00', '2026-08-30 12:07:23.877005+00', 'Ruby', NULL, '''3.3'':24C ''7'':28C ''action'':49C ''activerecord'':31C,117C ''applic'':14B ''applicationcontrol'':47C ''assign'':93C ''audit'':157C ''authent'':43C,50C ''author'':115C ''backend'':3A ''background'':16B ''bundl'':156C ''bundle-audit'':155C ''bundler'':34C ''check'':112C ''ci'':161C ''class'':45C ''client'':106C ''client-suppli'':105C ''control'':37C ''creat'':59C,68C ''credentials/environment'':144C ''current'':96C ''current_user.orders'':56C ''current_user.orders.create'':61C ''data'':137C ''def'':52C,58C,71C ''default'':151C ''defens'':94C ''develop'':10B ''devis'':35C ''dynam'':4B ''ecosystem'':22B ''end'':57C,69C,80C,81C ''escap'':149C ''everi'':39C,85C ''express'':5B ''floor'':116C ''gemfil'':159C ''html'':148C ''id'':78C,108C ''index'':53C ''interpol'':125C ''json'':55C,65C ''keep'':141C ''languag'':7B ''load'':135C ''marshal.load'':132C ''mass'':92C ''mass-assign'':91C ''model.find'':102C ''never'':101C,128C,131C ''optim'':8B ''order'':60C,62C,66C,72C,75C ''orderscontrol'':46C ''ownership'':111C ''param'':63C,73C ''paramet'':83C ''parameter'':118C ''params.permit'':88C ''params.require'':74C ''path'':87C ''permit'':76C ''power'':12B ''privat'':70C ''process'':17B ''product'':11B,77C ''program'':6B ''protect'':119C ''puma'':33C ''quantiti'':79C ''queri'':40C,100C ''rail'':19B,27C,36C ''rce'':140C ''render'':54C,64C ''repo'':147C ''rspec'':32C ''rubi'':1A,2A,23C,25C ''scope'':38C,99C ''secret'':142C ''sidekiq'':30C ''sinatra'':29C ''someon'':122C ''status'':67C ''stay'':152C ''string'':124C ''string-interpol'':123C ''strong'':82C ''suppli'':107C ''untrust'':136C ''user'':44C,51C,98C ''user-scop'':97C ''web'':13B ''where/order'':127C ''without'':109C ''write'':86C ''yaml.unsafe'':134C');
INSERT INTO public.technology_catalog VALUES ('rust-backend', 'Rust', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/rust-backend.png', '#dea584', '["backend-service", "worker", "cli-tool", "shared-library"]', '{"purpose": "Memory-safe systems language for services where performance and correctness both matter: high-throughput APIs, proxies, parsers, CLIs and shared native libraries other stacks bind to. Costs more engineering time per feature than Go/TS — the right node when that trade is deliberate.", "configMode": "code", "provenance": {"notes": "Stable stack (axum/tokio/sqlx/serde standard for years); live-docs upgrade rides N10(b). Row previously had EMPTY ai_context.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["axum + tokio + tower", "sqlx", "serde", "thiserror/anyhow", "clippy", "cargo workspaces"], "antiPatterns": ["unwrap()/expect() on I/O paths — every one is a latent panic", "Cloning to satisfy the borrow checker instead of restructuring ownership — a smell the compiler is pointing at real design debt", "Async trait gymnastics where a simple sync design would do", "Choosing Rust for a CRUD API where iteration speed matters more than the performance envelope"], "apiReference": {"docsUrl": "https://doc.rust-lang.org/"}, "bestPractices": ["axum + tokio + tower is the service stack; reach for it whole, not piecemeal", "sqlx with compile-time-checked queries (offline mode in CI so builds do not need a database)", "thiserror in libraries, anyhow in binaries; ? everywhere — no unwrap() on fallible paths in production code", "Clippy pedantic in CI from day one — retrofitting lints onto a Rust codebase is misery", "Keep async boundaries clean: spawn_blocking for CPU/sync work, never block the executor"], "sdkInitPattern": "cargo init myapp\\ncargo add axum tokio --features tokio/full serde --features serde/derive sqlx --features sqlx/postgres,sqlx/runtime-tokio\\n// src/main.rs\\nuse axum::{Router, routing::get};\\n#[tokio::main]\\nasync fn main() {\\n    let app = Router::new().route(\"/health\", get(|| async { \"ok\" }));\\n    let listener = tokio::net::TcpListener::bind(\"0.0.0.0:3000\").await.unwrap();\\n    axum::serve(listener, app).await.unwrap();\\n}", "securityGuidance": "Leverage the type system and ownership model for memory safety. Use sqlx compile-time checked queries to prevent SQL injection. Validate input using serde and custom deserialization. Set timeouts on all async operations. Use secrecy crate for sensitive values to prevent accidental logging. Audit dependencies with cargo-audit in CI.", "commonApiPatterns": [{"name": "Axum Handler", "description": "Axum handler with state extraction, path params, and typed errors", "codeTemplate": "async fn get_user(\\n    State(pool): State<PgPool>,\\n    Path(id): Path<i64>,\\n) -> Result<Json<User>, AppError> {\\n    let user = sqlx::query_as!(User, \"SELECT id, name FROM users WHERE id = $1\", id)\\n        .fetch_optional(&pool).await?\\n        .ok_or(AppError::NotFound)?;\\n    Ok(Json(user))\\n}"}, {"name": "Error Handling", "description": "Custom error type implementing IntoResponse for consistent API errors", "codeTemplate": "enum AppError { NotFound, Internal(anyhow::Error) }\\nimpl IntoResponse for AppError {\\n    fn into_response(self) -> Response {\\n        match self {\\n            Self::NotFound => (StatusCode::NOT_FOUND, \"not found\").into_response(),\\n            Self::Internal(e) => {\\n                tracing::error!(\"Internal error: {e:?}\");\\n                (StatusCode::INTERNAL_SERVER_ERROR, \"internal error\").into_response()\\n            }\\n        }\\n    }\\n}"}, {"name": "Middleware Layer", "description": "Tower middleware for tracing and CORS", "codeTemplate": "use tower_http::{cors::CorsLayer, trace::TraceLayer};\\nlet app = Router::new()\\n    .route(\"/api/users\", get(list_users))\\n    .layer(TraceLayer::new_for_http())\\n    .layer(CorsLayer::permissive());"}], "integrationPatterns": ["Axum or Actix-web for HTTP framework", "SQLx with compile-time query checking for database access", "tonic for gRPC services with protobuf", "tracing + tracing-subscriber for structured observability", "cargo-nextest for faster parallel test execution"], "configurationTemplate": "# Cargo.toml\\n[package]\\nname = \"myapp\"\\nversion = \"0.1.0\"\\nedition = \"2021\"\\n\\n[dependencies]\\naxum = \"0.7\"\\ntokio = { version = \"1\", features = [\"full\"] }\\nserde = { version = \"1\", features = [\"derive\"] }\\nsqlx = { version = \"0.7\", features = [\"postgres\", \"runtime-tokio\", \"macros\"] }\\ntower-http = { version = \"0.5\", features = [\"cors\", \"trace\"] }\\ntracing = \"0.1\"\\ntracing-subscriber = \"0.3\"\\nanyhow = \"1\"\\n\\n[profile.release]\\nlto = true\\nstrip = true"}', '[{"kind": "source", "path": "src/main.rs", "language": "rust", "description": "Application entry point"}, {"kind": "source", "path": "src/routes/mod.rs", "language": "rust", "description": "Route handlers"}, {"kind": "config", "path": "Cargo.toml", "language": "toml", "description": "Rust project manifest"}]', '{"dataAccess": {"type": "enum", "label": "Data access", "default": "sqlx", "options": ["sqlx", "diesel", "none"], "description": "sqlx = async, compile-time-checked SQL; diesel = sync ORM"}, "webFramework": {"type": "enum", "label": "Web framework", "default": "axum", "options": ["axum", "actix-web", "none-lib-or-cli"], "description": "axum (tokio-native, tower middleware) is the standing default for services; none for library/CLI deliverables"}, "errorStrategy": {"type": "enum", "label": "Error handling", "default": "thiserror-anyhow", "options": ["thiserror-anyhow", "custom-enums-only"], "description": "thiserror for library errors, anyhow at the application edge — the community-standard split"}}', '["database", "cache", "message-broker"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', 'Rust', '#B5876D', '''/health'':92C ''0.0.0.0'':103C ''3000'':104C ''accident'':155C ''add'':61C ''api'':20B ''app'':88C,110C ''async'':94C,145C ''audit'':157C,162C ''await.unwrap'':105C,111C ''axum'':48C,62C,76C,107C ''backend'':3A ''bind'':30B,102C ''cargo'':55C,57C,161C ''cargo-audit'':160C ''check'':128C ''ci'':164C ''clippi'':54C ''clis'':23B ''compil'':126C ''compile-tim'':125C ''correct'':14B ''cost'':32B ''crate'':149C ''custom'':139C ''deliber'':47B ''depend'':158C ''deseri'':140C ''engin'':34B ''featur'':37B,64C,67C,70C ''fn'':84C ''get'':79C,93C ''go/ts'':39B ''high'':18B ''high-throughput'':17B ''init'':58C ''inject'':133C ''input'':135C ''languag'':8B ''let'':87C,97C ''leverag'':113C ''librari'':27B ''listen'':98C,109C ''log'':156C ''main'':82C,85C ''matter'':16B ''memori'':5B,121C ''memory-saf'':4B ''model'':119C ''myapp'':59C ''n'':73C,80C,86C,96C,106C,112C ''nasync'':83C ''nativ'':26B ''ncargo'':60C ''net'':100C ''new'':90C ''node'':42B ''nuse'':75C ''ok'':95C ''oper'':146C ''ownership'':118C ''parser'':22B ''per'':36B ''perform'':12B ''prevent'':131C,154C ''proxi'':21B ''queri'':129C ''right'':41B ''rout'':78C,91C ''router'':77C,89C ''rust'':1A,2A ''safe'':6B ''safeti'':122C ''secreci'':148C ''sensit'':151C ''serd'':52C,66C,137C ''serde/derive'':68C ''serv'':108C ''servic'':10B ''set'':141C ''share'':25B ''sql'':132C ''sqlx'':51C,69C,124C ''sqlx/postgres'':71C ''sqlx/runtime-tokio'':72C ''src/main.rs'':74C ''stack'':29B ''system'':7B,116C ''tcplisten'':101C ''thiserror/anyhow'':53C ''throughput'':19B ''time'':35B,127C ''timeout'':142C ''tokio'':49C,63C,81C,99C ''tokio/full'':65C ''tower'':50C ''trade'':45B ''type'':115C ''use'':123C,136C,147C ''valid'':134C ''valu'':152C ''workspac'':56C');
INSERT INTO public.technology_catalog VALUES ('firebase-auth', 'Firebase Auth', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/firebase-auth.png', '#ffca28', '["auth-provider"]', '{"purpose": "Firebase''s authentication service providing drop-in identity management for web and mobile applications. Supports email/password, phone number, and social providers (Google, Apple, Facebook, GitHub, etc.) with minimal configuration. Use when you need rapid authentication setup without building a custom auth backend, when your app uses other Firebase services (Firestore, Storage), or when you need social login across multiple providers with a unified API. Firebase Auth handles token management, session persistence, and account linking automatically. Don''t use when you need fine-grained server-side session management with custom claims beyond what Firebase supports. Don''t use when you need SAML or enterprise SSO without Firebase Identity Platform (paid upgrade). Avoid if you''re already using Supabase Auth, Auth0, or Clerk and don''t want multiple auth providers. Consider Supabase Auth for PostgreSQL-backed applications needing tighter database integration.", "configMode": "declarative", "provenance": {"notes": "docsUrl is the vendor''s canonical documentation root, stamped from model knowledge and checked by scripts/n10-verify-docs-urls.ts; pre-existing body content not yet live-docs verified — upgrade at this row''s enrichment chunk.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Firebase Auth", "Firebase SDK", "Firebase Admin SDK", "Firebase Identity Platform", "Firebase App Check", "FirebaseUI", "Firebase Emulator Suite", "Firebase Console"], "antiPatterns": ["Trusting client-side authentication state without server-side token verification", "Not implementing Firestore Security Rules to complement Firebase Auth", "Using Firebase Auth custom claims for data that changes frequently (claims require token refresh)", "Storing sensitive user data in Firebase Auth profile instead of a secured database", "Not handling auth state changes causing stale UI after session expiry", "Exposing Firebase config keys and treating them as secrets (they are public by design)"], "apiReference": {"docsUrl": "https://firebase.google.com/docs/auth"}, "bestPractices": ["Use Firebase ID tokens for server-side verification, never trust client-side auth state alone", "Set custom claims for role-based access control (admin, editor, viewer)", "Enable email enumeration protection to prevent account discovery attacks", "Implement proper error handling for all auth operations with user-friendly messages", "Use App Check to verify that requests come from your genuine app, not spoofed clients", "Configure authorized domains to prevent phishing redirects", "Use multi-factor authentication for sensitive applications"], "freshnessNote": "Firebase is part of Google Cloud (owner ruling; palette + provider inference unified since N4.7/4c-1) — this node nests in a Google Cloud project. gcp-identity-platform IS Firebase Auth''s enterprise tier (SAML/OIDC, multi-tenancy, SLA): pick Identity Platform when those requirements exist, Firebase Auth for the standard consumer-app lane.", "sdkInitPattern": "// Web (JavaScript)\\nimport { initializeApp } from \"firebase/app\";\\nimport { getAuth, signInWithEmailAndPassword, createUserWithEmailAndPassword, onAuthStateChanged } from \"firebase/auth\";\\nconst app = initializeApp({ apiKey: \"...\", authDomain: \"my-app.firebaseapp.com\", projectId: \"my-app\" });\\nconst auth = getAuth(app);\\n// [Tailor to project language: Flutter=firebase_auth, iOS=FirebaseAuth, Android=firebase-auth-ktx, Node.js=firebase-admin/auth]", "securityGuidance": "Always verify Firebase ID tokens server-side with the Admin SDK before granting access. Enable App Check to prevent unauthorized API usage from spoofed clients. Configure authorized domains to prevent phishing redirects. Enable email enumeration protection. Use custom claims for role-based access and enforce them in Firestore Security Rules and server-side middleware.", "commonApiPatterns": [{"name": "Email Sign-Up / Sign-In", "description": "Email/password registration and login", "codeTemplate": "import { createUserWithEmailAndPassword, signInWithEmailAndPassword } from \"firebase/auth\";\\nconst { user } = await createUserWithEmailAndPassword(auth, email, password);\\n// Sign in:\\nconst { user: existing } = await signInWithEmailAndPassword(auth, email, password);"}, {"name": "Social Login", "description": "Google OAuth sign-in with popup", "codeTemplate": "import { GoogleAuthProvider, signInWithPopup } from \"firebase/auth\";\\nconst provider = new GoogleAuthProvider();\\nconst { user } = await signInWithPopup(auth, provider);\\nconsole.log(user.displayName, user.email, user.photoURL);"}, {"name": "Auth State Listener", "description": "Listen for auth state changes for reactive UI updates", "codeTemplate": "onAuthStateChanged(auth, (user) => {\\n  if (user) {\\n    console.log(\"Signed in:\", user.uid, user.email);\\n  } else {\\n    console.log(\"Signed out\");\\n  }\\n});"}, {"name": "Server-Side Verification", "description": "Verify Firebase ID token on the server", "codeTemplate": "// Node.js with firebase-admin\\nimport { getAuth } from \"firebase-admin/auth\";\\nconst decoded = await getAuth().verifyIdToken(idToken);\\nconsole.log(\"Verified user:\", decoded.uid, decoded.email);"}], "setupInstructions": [{"url": "https://console.firebase.google.com", "type": "account_setup", "title": "Create Firebase Project", "required": true, "instructions": "Create a Firebase project in the Firebase Console. Enable Authentication in the Build section."}, {"type": "dashboard_config", "title": "Enable Sign-in Providers", "required": true, "instructions": "In Firebase Console > Authentication > Sign-in method, enable the providers you need (Email/Password, Google, Apple, etc.)."}, {"type": "environment_variable", "title": "Add Firebase Config", "commands": ["export FIREBASE_API_KEY=your-api-key", "export FIREBASE_AUTH_DOMAIN=your-project.firebaseapp.com", "export FIREBASE_PROJECT_ID=your-project-id"], "required": true, "instructions": "Copy the Firebase config object from Project Settings > General > Your apps and add it to your environment variables."}, {"type": "sdk_install", "title": "Install Firebase SDK", "commands": ["npm install firebase"], "required": true, "instructions": "Install the Firebase JS SDK in your project."}], "integrationPatterns": ["Firestore Security Rules using request.auth for document-level access control", "Cloud Functions triggered on user creation/deletion for backend provisioning", "Firebase App Check for verifying request authenticity from legitimate apps"], "configurationTemplate": "// Firebase console config (public, safe to embed)\\nconst firebaseConfig = {\\n  apiKey: \"AIza...\",\\n  authDomain: \"my-app.firebaseapp.com\",\\n  projectId: \"my-app\",\\n  storageBucket: \"my-app.appspot.com\",\\n  messagingSenderId: \"123456\",\\n  appId: \"1:123456:web:abc123\"\\n};\\n// Enable providers in Firebase Console > Authentication > Sign-in method\\n// Configure authorized domains in Firebase Console > Authentication > Settings"}', '[{"kind": "config", "path": "firebase/firebase.json", "language": "json", "priority": "essential", "description": "Firebase project configuration"}, {"kind": "config", "path": "firebase/firestore.rules", "language": "text", "priority": "recommended", "description": "Firestore security rules with auth.uid checks"}, {"kind": "config", "path": "src/auth/firebase-config.ts", "language": "typescript", "priority": "essential", "description": "Firebase app initialization and auth configuration"}, {"kind": "source", "path": "src/auth/firebase-provider.tsx", "language": "typescript", "priority": "essential", "description": "React auth context provider with Firebase Auth"}, {"kind": "source", "path": "src/auth/firebase-admin.ts", "language": "typescript", "priority": "recommended", "description": "Firebase Admin SDK initialization for server-side"}, {"kind": "config", "path": "firebase/.firebaserc", "language": "json", "priority": "recommended", "description": "Firebase project aliases for multi-environment"}]', '{"emailAuth": {"type": "boolean", "label": "Email/Password Auth", "default": true, "description": "Enable email and password authentication"}, "phoneAuth": {"type": "boolean", "label": "Phone Auth", "default": false, "description": "Enable phone number authentication"}, "projectId": {"type": "string", "label": "Firebase Project ID", "description": "Firebase project identifier"}, "anonymousAuth": {"type": "boolean", "label": "Anonymous Auth", "default": false, "description": "Enable anonymous guest authentication"}, "socialProviders": {"type": "array", "label": "Social Providers", "description": "Enabled OAuth providers (Google, GitHub, etc.)"}}', '["frontend-app", "backend-service", "database"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#E0B020', '''/auth'':213C ''access'':228C,258C ''account'':78B ''across'':63B ''admin'':153C,212C,224C ''alreadi'':122B ''alway'':214C ''android'':204C ''api'':69B,235C ''apikey'':183C ''app'':50B,159C,181C,189C,193C,230C ''appl'':28B ''applic'':19B,143B ''auth'':2A,4A,46B,71B,125B,134B,138B,149C,191C,201C,207C ''auth0'':126B ''authdomain'':184C ''authent'':7B,40B ''author'':241C ''automat'':80B ''avoid'':118B ''back'':142B ''backend'':47B ''base'':257C ''beyond'':98B ''build'':43B ''check'':160C,231C ''claim'':97B,253C ''clerk'':128B ''client'':239C ''configur'':34B,240C ''consid'':136B ''consol'':166C ''createuserwithemailandpassword'':176C ''custom'':45B,96B,252C ''databas'':146B ''domain'':242C ''drop'':11B ''drop-in'':10B ''email'':248C ''email/password'':21B ''emul'':163C ''enabl'':229C,247C ''enforc'':260C ''enterpris'':110B ''enumer'':249C ''etc'':31B ''facebook'':29B ''fine'':88B ''fine-g