INSERT INTO public.technology_catalog VALUES ('azure', 'Microsoft Azure', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/azure.png', '#0078D4', '["azure"]', '{"purpose": "Azure cloud provider identifier for infrastructure container nodes. Use this as the technology for cloud-project, vpc, and subnet roles when the deployment target is Azure. Individual Azure services have their own technology entries and should be assigned to their respective leaf-role nodes, NOT to infrastructure containers.", "lifecycle": "platform-umbrella", "provenance": {"notes": "B10 lifecycle stamp; body content predates provenance tracking. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Azure Resource Manager", "Bicep", "Terraform", "Azure Management Groups", "Azure Policy"], "antiPatterns": ["Using a single subscription for all environments and teams", "Creating resources without resource groups or tagging conventions", "Using classic (ASM) resources instead of ARM-based resources", "Storing secrets in app settings instead of Azure Key Vault", "Ignoring Azure Advisor recommendations for security and cost"], "bestPractices": ["Use Virtual Networks with NSGs", "Enable Azure Monitor and Defender", "Use resource groups for logical organization", "Implement Azure Landing Zones"], "sdkInitPattern": "az login && az account set --subscription my-sub-id && az account show", "securityGuidance": "Enable Microsoft Defender for Cloud across all subscriptions. Use Azure AD with Conditional Access policies. Implement management groups with Azure Policy for governance. Enable diagnostic logging for all resources. Use managed identities instead of service principals with secrets. Enable Azure Key Vault for secrets management.", "commonApiPatterns": [{"name": "Create Resource Group", "description": "Create a resource group with tags for logical organization", "codeTemplate": "az group create --name rg-myapp-prod --location eastus --tags Environment=Production ManagedBy=Terraform"}, {"name": "Deploy ARM/Bicep Template", "description": "Deploy infrastructure via Bicep template", "codeTemplate": "az deployment group create --resource-group rg-myapp-prod --template-file main.bicep --parameters env=prod"}, {"name": "List Resources", "description": "List all resources in a resource group", "codeTemplate": "az resource list --resource-group rg-myapp-prod --output table"}], "integrationPatterns": ["Azure AD + Conditional Access for identity and access management", "Azure Monitor + Log Analytics for centralized observability", "Azure Policy + Blueprints for governance at scale", "Azure DevOps or GitHub Actions for CI/CD pipelines", "Azure Cost Management for budget tracking and optimization"], "configurationTemplate": "# Azure Landing Zone pattern (Terraform)\\nprovider \"azurerm\" {\\n  features {}\\n  subscription_id = var.subscription_id\\n}\\nresource \"azurerm_resource_group\" \"main\" {\\n  name     = \"rg-${var.project}-${var.environment}\"\\n  location = var.location\\n  tags = {\\n    Environment = var.environment\\n    ManagedBy   = \"terraform\"\\n  }\\n}"}', '[]', '{}', '[]', false, NULL, NULL, '2026-02-20 14:25:20.585755+00', '2026-08-30 12:07:23.877005+00', NULL, '#005EA2', '''access'':90C ''account'':67C,75C ''across'':82C ''ad'':87C ''assign'':42B ''az'':64C,66C,74C ''azur'':2A,3A,4B,30B,32B,54C,59C,62C,86C,96C,116C ''bicep'':57C ''cloud'':5B,19B,81C ''cloud-project'':18B ''condit'':89C ''contain'':10B,53B ''defend'':79C ''deploy'':27B ''diagnost'':101C ''enabl'':77C,100C,115C ''entri'':38B ''govern'':99C ''group'':61C,94C ''id'':73C ''ident'':108C ''identifi'':7B ''implement'':92C ''individu'':31B ''infrastructur'':9B,52B ''instead'':109C ''key'':117C ''leaf'':47B ''leaf-rol'':46B ''log'':102C ''login'':65C ''manag'':56C,60C,93C,107C,121C ''microsoft'':1A,78C ''my-sub-id'':70C ''node'':11B,49B ''polici'':63C,91C,97C ''princip'':112C ''project'':20B ''provid'':6B ''resourc'':55C,105C ''respect'':45B ''role'':24B,48B ''secret'':114C,120C ''servic'':33B,111C ''set'':68C ''show'':76C ''sub'':72C ''subnet'':23B ''subscript'':69C,84C ''target'':28B ''technolog'':16B,37B ''terraform'':58C ''use'':12B,85C,106C ''vault'':118C ''vpc'':21B');
INSERT INTO public.technology_catalog VALUES ('elasticsearch', 'Elasticsearch', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/elasticsearch.png', '#fed10a', '["search-engine", "database"]', '{"purpose": "Distributed search and analytics engine built on Apache Lucene, optimized for full-text search, log analytics, and real-time data exploration. Use when you need advanced full-text search with relevance scoring, fuzzy matching, faceted navigation, and autocomplete. Elasticsearch excels at log aggregation and observability (ELK stack), e-commerce product search, and any application where users search across large volumes of semi-structured text. Don''t use as a primary database -- Elasticsearch is not ACID-compliant and can lose acknowledged writes during node failures. Don''t use for simple key-value lookups or small datasets where PostgreSQL full-text search suffices. Avoid when you need strong consistency guarantees for financial transactions. Consider OpenSearch as an open-source alternative with compatible APIs.", "configMode": "declarative", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Elasticsearch 8+", "Kibana", "Logstash", "Elastic Agent", "OpenSearch", "elastic/elasticsearch-js", "Elastic Cloud", "AWS OpenSearch"], "antiPatterns": ["Using Elasticsearch as the primary source of truth without a backing database", "Creating too many shards (over-sharding) on small clusters", "Not defining explicit mappings and relying on dynamic mapping for everything", "Running search-heavy and indexing-heavy workloads on the same nodes", "Using deeply nested documents causing expensive nested queries", "Not setting index refresh intervals for write-heavy workloads"], "apiReference": {"docsUrl": "https://www.elastic.co/guide/en/elasticsearch/reference/current/index.html"}, "bestPractices": ["Design index mappings upfront with appropriate field types and analyzers", "Use bulk API for indexing large volumes of data instead of individual requests", "Set proper shard count based on data volume (aim for 10-50GB per shard)", "Use index aliases for zero-downtime reindexing and index rotation", "Implement index lifecycle management (ILM) for time-series data", "Use search templates for reusable parameterized queries", "Monitor cluster health and set up alerts for yellow/red status"], "freshnessNote": "Licensing state 2026: Elasticsearch carries an AGPLv3 option since 8.16 (open source again); OpenSearch (Apache 2.0) is the fork. Interop trap: Elastic official clients reject OpenSearch clusters — changing distribution means changing the client dependency, not a config value.", "sdkInitPattern": "// Node.js with @elastic/elasticsearch\\nimport { Client } from \"@elastic/elasticsearch\";\\nconst client = new Client({ node: process.env.ELASTICSEARCH_URL!, auth: { apiKey: process.env.ES_API_KEY! } });\\n// [Tailor to project language: Python=elasticsearch-py, Go=go-elasticsearch, Java=elasticsearch-java, .NET=Elastic.Clients.Elasticsearch]", "securityGuidance": "Enable X-Pack security with TLS for transport and HTTP layers. Use API keys or native realm authentication instead of embedding credentials. Never expose Elasticsearch directly to the internet -- place behind an API gateway or reverse proxy. Restrict index-level access with role-based access control. Sanitize user search input to prevent query injection in query_string queries.", "commonApiPatterns": [{"name": "Index Document", "description": "Index a single document by ID", "codeTemplate": "await client.index({\\n  index: \"products\",\\n  id: productId,\\n  document: { name, description, category, price, createdAt: new Date() }\\n});"}, {"name": "Full-Text Search", "description": "Multi-field search with boosting, filters, and highlighting", "codeTemplate": "const result = await client.search({\\n  index: \"products\",\\n  query: {\\n    bool: {\\n      must: [{ multi_match: { query: searchTerm, fields: [\"name^3\", \"description\"] } }],\\n      filter: [{ term: { category: \"electronics\" } }, { range: { price: { lte: 500 } } }]\\n    }\\n  },\\n  highlight: { fields: { name: {}, description: {} } },\\n  size: 20\\n});"}, {"name": "Bulk Index", "description": "Bulk indexing for batch data ingestion", "codeTemplate": "const body = products.flatMap(p => [{ index: { _index: \"products\", _id: p.id } }, p]);\\nawait client.bulk({ body, refresh: true });"}, {"name": "Aggregation", "description": "Aggregations for analytics and faceted navigation", "codeTemplate": "const result = await client.search({\\n  index: \"products\",\\n  size: 0,\\n  aggs: {\\n    by_category: { terms: { field: \"category.keyword\" } },\\n    avg_price: { avg: { field: \"price\" } }\\n  }\\n});"}], "integrationPatterns": ["Logstash or Beats for data ingestion pipelines from various sources", "Kibana for visualization, dashboards, and cluster management", "Application search layer: index from primary database, search via Elasticsearch"], "configurationTemplate": "# elasticsearch.yml\\ncluster.name: my-cluster\\nnode.name: node-1\\npath.data: /var/lib/elasticsearch\\nnetwork.host: 0.0.0.0\\ndiscovery.seed_hosts: [\"es-node-1\", \"es-node-2\"]\\ncluster.initial_master_nodes: [\"node-1\", \"node-2\"]\\nxpack.security.enabled: true\\nxpack.security.transport.ssl.enabled: true"}', '[{"kind": "config", "path": "elasticsearch.yml", "language": "yaml", "description": "Node/cluster settings; xpack.security stays enabled"}]', '{"primaryUse": {"type": "enum", "label": "Primary use", "default": "app-search", "options": ["app-search", "logs-observability", "vector-hybrid-search"]}, "distribution": {"type": "enum", "label": "Distribution", "default": "elasticsearch-agpl", "options": ["elasticsearch-agpl", "opensearch-apache2"], "description": "Elasticsearch is open source again (AGPLv3 option since 8.16); OpenSearch is the Apache-2.0 fork. NOT interchangeable at the client: Elastic clients reject OpenSearch clusters — the distribution decides which client library the app imports"}, "indexLifecycle": {"type": "boolean", "label": "ILM/ISM policies", "default": true, "description": "Time-based indices without lifecycle policies fill disks — the logs-cluster classic"}}', '["backend-service", "logging", "monitoring"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#D6B008', '''8'':134C ''access'':225C,230C ''acid'':83B ''acid-compli'':82B ''acknowledg'':88B ''across'':64B ''advanc'':30B ''agent'':138C ''aggreg'':48B ''altern'':129B ''analyt'':6B,19B ''apach'':10B ''api'':132B,162C,196C,216C ''apikey'':160C ''applic'':60B ''auth'':159C ''authent'':201C ''autocomplet'':43B ''avoid'':112B ''aw'':143C ''base'':229C ''behind'':214C ''built'':8B ''client'':149C,153C,155C ''cloud'':142C ''commerc'':55B ''compat'':131B ''compliant'':84B ''consid'':122B ''consist'':117B ''control'':231C ''credenti'':205C ''data'':24B ''databas'':78B ''dataset'':104B ''direct'':209C ''distribut'':3B ''e'':54B ''e-commerc'':53B ''elast'':137C,141C ''elastic.clients.elasticsearch'':182C ''elastic/elasticsearch'':147C,151C ''elastic/elasticsearch-js'':140C ''elasticsearch'':1A,2A,44B,79B,133C,171C,176C,179C,208C ''elasticsearch-java'':178C ''elasticsearch-pi'':170C ''elk'':51B ''embed'':204C ''enabl'':183C ''engin'':7B ''excel'':45B ''explor'':25B ''expos'':207C ''facet'':40B ''failur'':92B ''financi'':120B ''full'':15B,32B,108B ''full-text'':14B,31B,107B ''fuzzi'':38B ''gateway'':217C ''go'':173C,175C ''go-elasticsearch'':174C ''guarante'':118B ''http'':193C ''index'':223C ''index-level'':222C ''inject'':239C ''input'':235C ''instead'':202C ''internet'':212C ''java'':177C,180C ''key'':99B,163C,197C ''key-valu'':98B ''kibana'':135C ''languag'':168C ''larg'':65B ''layer'':194C ''level'':224C ''log'':18B,47B ''logstash'':136C ''lookup'':101B ''lose'':87B ''lucen'':11B ''match'':39B ''n'':164C ''nativ'':199C ''navig'':41B ''nconst'':152C ''need'':29B,115B ''net'':181C ''never'':206C ''new'':154C ''nimport'':148C ''node'':91B,156C ''node.js'':145C ''observ'':50B ''open'':127B ''open-sourc'':126B ''opensearch'':123B,139C,144C ''optim'':12B ''pack'':186C ''place'':213C ''postgresql'':106B ''prevent'':237C ''primari'':77B ''process.env.elasticsearch'':157C ''process.env.es'':161C ''product'':56B ''project'':167C ''proxi'':220C ''py'':172C ''python'':169C ''queri'':238C,241C,243C ''real'':22B ''real-tim'':21B ''realm'':200C ''relev'':36B ''restrict'':221C ''revers'':219C ''role'':228C ''role-bas'':227C ''sanit'':232C ''score'':37B ''search'':4B,17B,34B,57B,63B,110B,234C ''secur'':187C ''semi'':69B ''semi-structur'':68B ''simpl'':97B ''small'':103B ''sourc'':128B ''stack'':52B ''string'':242C ''strong'':116B ''structur'':70B ''suffic'':111B ''tailor'':165C ''text'':16B,33B,71B,109B ''time'':23B ''tls'':189C ''transact'':121B ''transport'':191C ''url'':158C ''use'':26B,74B,95B,195C ''user'':62B,233C ''valu'':100B ''volum'':66B ''write'':89B ''x'':185C ''x-pack'':184C');
INSERT INTO public.technology_catalog VALUES ('phoenix-elixir', 'Phoenix (Elixir)', NULL, '#6b7280', '["realtime-service", "backend-service"]', '{"purpose": "Elixir web framework on the BEAM VM — the realtime specialist: Channels/PubSub/Presence handle millions of concurrent connections per node with supervision-tree fault tolerance, and LiveView builds interactive UIs server-side without a JS framework. Costs: the Elixir learning curve and a smaller ecosystem than Node — the right node when realtime/concurrency IS the product.", "configMode": "code", "provenance": {"notes": "Phase B8c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Phoenix LiveView", "Channels/PubSub/Presence", "Ecto + Postgres", "Oban", "OTP releases", "BEAM VM"], "antiPatterns": ["Treating processes like threads — GenServers hold state and serialize access; a GenServer as a shared bottleneck is the classic scaling bug", "Ecto queries in LiveView mount without preloads — N+1s surface as latency on every socket join", "Ignoring the supervision tree design — a flat tree under one supervisor loses the fault-isolation the BEAM is for"], "apiReference": {"docsUrl": "https://hexdocs.pm/phoenix/"}, "bestPractices": ["LiveView first for interactive UI — reach for a JS frontend only when offline/native interactions demand it", "Lean on OTP: supervisors restart crashed processes — let it crash beats defensive rescue everywhere", "PubSub + Presence are built in — do not bolt on an external realtime service beside Phoenix", "Oban for durable background jobs (database-backed, observable)", "Deploy as OTP releases (mix release) in containers"], "sdkInitPattern": "# router.ex\npipeline :api do\n  plug :accepts, [\"json\"]\n  plug AppWeb.Plugs.RequireAuth\nend\n\nscope \"/api\", AppWeb do\n  pipe_through :api\n  resources \"/orders\", OrderController, only: [:index, :show, :create]\nend", "securityGuidance": "Secrets (SECRET_KEY_BASE, signing salts, DB URLs) resolve in config/runtime.exs from the environment — never compiled into releases or committed in config/*.exs. Authorize in context functions, not just router pipelines (scope every Repo query by the authenticated actor), verify channel/LiveView socket auth on connect AND on every topic join, and keep force_ssl + secure cookie flags on in prod. Ecto changesets with explicit cast lists are your mass-assignment defense — never cast params wholesale."}', '[{"kind": "config", "path": "config/runtime.exs", "language": "elixir", "description": "Runtime config resolving secrets from the environment"}, {"kind": "code", "path": "lib/app_web/router.ex", "language": "elixir", "description": "Pipelines with auth plugs, scoped routes"}]', '{"liveView": {"type": "boolean", "label": "LiveView UI", "default": true, "description": "Server-rendered interactive UI — the reason to pick Phoenix; a separate JS frontend is the exception, not the default"}, "deployment": {"type": "enum", "label": "Deployment", "default": "otp-releases-docker", "options": ["otp-releases-docker", "fly-io-optimized"]}, "backgroundJobs": {"type": "enum", "label": "Background jobs", "default": "oban", "options": ["oban", "none"]}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''/api'':81C ''/orders'':88C ''accept'':75C ''actor'':133C ''api'':72C,86C ''appweb'':82C ''appweb.plugs.requireauth'':78C ''assign'':165C ''auth'':137C ''authent'':132C ''author'':118C ''base'':98C ''beam'':10B,68C ''build'':31B ''cast'':159C,168C ''changeset'':156C ''channel/liveview'':135C ''channels/pubsub/presence'':15B,62C ''commit'':114C ''compil'':110C ''concurr'':19B ''config'':116C ''config/runtime.exs'':105C ''connect'':20B,139C ''context'':120C ''cooki'':150C ''cost'':41B ''creat'':93C ''curv'':45B ''db'':101C ''defens'':166C ''ecosystem'':49B ''ecto'':63C,155C ''elixir'':2A,4A,5B,43B ''end'':79C,94C ''environ'':108C ''everi'':127C,142C ''ex'':117C ''explicit'':158C ''fault'':27B ''flag'':151C ''forc'':147C ''framework'':7B,40B ''function'':121C ''handl'':16B ''index'':91C ''interact'':32B ''join'':144C ''js'':39B ''json'':76C ''keep'':146C ''key'':97C ''learn'':44B ''list'':160C ''liveview'':30B,61C ''mass'':164C ''mass-assign'':163C ''million'':17B ''never'':109C,167C ''node'':22B,51B,54B ''oban'':65C ''ordercontrol'':89C ''otp'':66C ''param'':169C ''per'':21B ''phoenix'':1A,3A,60C ''pipe'':84C ''pipelin'':71C,125C ''plug'':74C,77C ''postgr'':64C ''prod'':154C ''product'':59B ''queri'':129C ''realtim'':13B ''realtime/concurrency'':56B ''releas'':67C,112C ''repo'':128C ''resolv'':103C ''resourc'':87C ''right'':53B ''router'':124C ''router.ex'':70C ''salt'':100C ''scope'':80C,126C ''secret'':95C,96C ''secur'':149C ''server'':35B ''server-sid'':34B ''show'':92C ''side'':36B ''sign'':99C ''smaller'':48B ''socket'':136C ''specialist'':14B ''ssl'':148C ''supervis'':25B ''supervision-tre'':24B ''toler'':28B ''topic'':143C ''tree'':26B ''ui'':33B ''url'':102C ''verifi'':134C ''vm'':11B,69C ''web'':6B ''wholesal'':170C ''without'':37B');
INSERT INTO public.technology_catalog VALUES ('aspnet-core', 'ASP.NET Core (C#)', NULL, '#512BD4', '["backend-service", "worker", "realtime-service"]', '{"purpose": "Cross-platform, high-performance .NET framework for building modern web APIs, real-time services, and cloud-native backend applications", "configMode": "code", "provenance": {"notes": "Phase B3 additions authored from model knowledge — no prior provenance. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": [".NET 8+", "C#", "Entity Framework Core", "MediatR", "FluentValidation", "Serilog", "xUnit", "Swashbuckle/NSwag"], "antiPatterns": ["Using the Service Locator pattern instead of constructor injection", "Fat controllers with business logic instead of using services/handlers", "Not using async/await for I/O-bound operations", "Exposing Entity Framework entities directly in API responses", "Not validating input models", "Catching and swallowing exceptions without logging", "Not implementing proper CORS configuration", "Using synchronous database calls in request handlers"], "apiReference": {"docsUrl": "https://learn.microsoft.com/aspnet/core/"}, "bestPractices": ["Use built-in dependency injection for all services", "Implement the middleware pipeline for cross-cutting concerns", "Use Minimal APIs for lightweight endpoints or Controllers for complex domains", "Implement health checks with Microsoft.Extensions.Diagnostics.HealthChecks", "Use Options pattern for strongly-typed configuration", "Implement proper exception handling middleware", "Use async/await throughout the request pipeline", "Leverage IHttpClientFactory for outbound HTTP calls", "Use response caching and output caching where appropriate"], "sdkInitPattern": "// Program.cs — minimal API\r\nvar builder = WebApplication.CreateBuilder(args);\r\nbuilder.Services.AddAuthentication();\r\nbuilder.Services.AddAuthorization();\r\n\r\nvar app = builder.Build();\r\napp.UseHttpsRedirection();\r\napp.UseAuthentication();\r\napp.UseAuthorization();\r\napp.MapGet(\"/health\", () => Results.Ok(new { ok = true }));\r\napp.Run();", "securityGuidance": "Middleware ORDER is security: UseAuthentication before UseAuthorization, and both before the endpoints they protect. Keep secrets out of appsettings.json — user-secrets in development, a vault (Key Vault, etc.) in production. Enforce HTTPS redirection + HSTS, use the antiforgery services for cookie-authenticated form posts, and lean on the framework''s model binding + validation instead of reading raw request bodies."}', '[{"kind": "source", "path": "Program.cs", "language": "csharp", "description": "Application entry point and service configuration"}, {"kind": "source", "path": "Controllers/ApiController.cs", "language": "csharp", "description": "API controller definitions"}, {"kind": "source", "path": "Services/", "language": "csharp", "description": "Business logic services"}, {"kind": "config", "path": "App.csproj", "language": "xml", "description": ".NET project file with NuGet dependencies"}, {"kind": "config", "path": "appsettings.json", "language": "json", "description": "Application configuration"}, {"kind": "config", "path": "appsettings.Development.json", "language": "json", "description": "Development environment overrides"}]', '{"openApi": {"type": "boolean", "label": "OpenAPI generation", "default": true}, "apiStyle": {"type": "enum", "label": "API style", "default": "minimal-apis", "options": ["minimal-apis", "controllers"], "description": "Minimal APIs are the current-.NET default for services; controllers for large conventional codebases"}, "dataAccess": {"type": "enum", "label": "Data access", "default": "ef-core", "options": ["ef-core", "dapper"]}}', '["database", "cache", "message-broker", "auth-provider"]', false, NULL, NULL, '2026-03-31 13:54:56.372888+00', '2026-08-30 12:07:23.877005+00', 'ASP.NET Core', NULL, '''/health'':56C ''8'':30C ''antiforgeri'':99C ''api'':18B,42C ''app'':50C ''app.mapget'':55C ''app.run'':61C ''app.useauthentication'':53C ''app.useauthorization'':54C ''app.usehttpsredirection'':52C ''applic'':28B ''appsettings.json'':80C ''arg'':46C ''asp.net'':1A ''aspnet'':4A ''authent'':104C ''backend'':27B ''bind'':114C ''bodi'':121C ''build'':15B ''builder'':44C ''builder.build'':51C ''builder.services.addauthentication'':47C ''builder.services.addauthorization'':48C ''c'':3A,31C ''cloud'':25B ''cloud-nat'':24B ''cooki'':103C ''cookie-authent'':102C ''core'':2A,5A,34C ''cross'':7B ''cross-platform'':6B ''develop'':85C ''endpoint'':73C ''enforc'':93C ''entiti'':32C ''etc'':90C ''fluentvalid'':36C ''form'':105C ''framework'':13B,33C,111C ''high'':10B ''high-perform'':9B ''hsts'':96C ''https'':94C ''instead'':116C ''keep'':76C ''key'':88C ''lean'':108C ''mediatr'':35C ''middlewar'':62C ''minim'':41C ''model'':113C ''modern'':16B ''nativ'':26B ''net'':12B,29C ''new'':58C ''ok'':59C ''order'':63C ''perform'':11B ''platform'':8B ''post'':106C ''product'':92C ''program.cs'':40C ''protect'':75C ''raw'':119C ''read'':118C ''real'':20B ''real-tim'':19B ''redirect'':95C ''request'':120C ''results.ok'':57C ''secret'':77C,83C ''secur'':65C ''serilog'':37C ''servic'':22B,100C ''swashbuckle/nswag'':39C ''time'':21B ''true'':60C ''use'':97C ''useauthent'':66C ''useauthor'':68C ''user'':82C ''user-secret'':81C ''valid'':115C ''var'':43C,49C ''vault'':87C,89C ''web'':17B ''webapplication.createbuilder'':45C ''xunit'':38C');
INSERT INTO public.technology_catalog VALUES ('azure-functions', 'Azure Functions', NULL, '#0078D4', '["serverless-function"]', '{"purpose": "Azure Functions is Azure''s event-driven serverless compute platform for running short-lived code without managing servers. Use it for HTTP endpoints, queue consumers, timer jobs, webhook receivers, and integration logic that scales per invocation with minimal operational overhead. Choose Azure Functions over App Service when workloads are bursty, trigger-driven, or highly asynchronous and you want consumption-based or event-aligned scaling. Do not use it for long-running stateful application servers, tightly coupled monoliths, or platforms that require deep container orchestration control where App Service or AKS is a better fit.", "configMode": "code", "provenance": {"notes": "Phase B1 additions (securityGuidance, sdkInitPattern, docsUrl) authored from model knowledge — no egress in the authoring environment. Prior stamp: live-docs 2026-07-27. Upgrade the whole row at its live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Azure Functions", "Azure Storage", "Azure Service Bus", "Azure Event Grid", "Azure Application Insights", "Azure API Management", "Azure Key Vault"], "antiPatterns": ["Using Azure Functions as a long-running monolithic application host", "Storing secrets directly in source code or local settings files", "Packing large dependencies into every function deployment and increasing cold start latency", "Performing heavy synchronous fan-out work inside a single invocation without queue decoupling", "Ignoring retry semantics and idempotency for event-driven handlers", "Using Functions where a stable always-on backend service or Kubernetes platform is the actual requirement"], "apiReference": {"docsUrl": "https://learn.microsoft.com/azure/azure-functions/"}, "bestPractices": ["Keep each function focused on a single trigger and bounded responsibility", "Use managed identities instead of embedding credentials in configuration", "Design queue and event handlers to be idempotent under retries and duplicate delivery", "Externalize secrets and environment configuration through app settings and Key Vault references", "Use Durable Functions only when explicit orchestration state or fan-out workflows are required", "Monitor cold starts and select Premium plans for latency-sensitive or VNet-integrated workloads", "Move shared business logic into reusable libraries instead of duplicating code across functions"], "sdkInitPattern": "// Azure Functions v4 programming model (Node.js)\r\nconst { app } = require(''@azure/functions'');\r\n\r\napp.http(''hello'', {\r\n  methods: [''GET''],\r\n  authLevel: ''function'',\r\n  handler: async (request, context) => {\r\n    return { jsonBody: { ok: true } };\r\n  },\r\n});", "securityGuidance": "Function keys are routing convenience, not production auth — front user-facing endpoints with Azure AD (Easy Auth) or API Management. Store secrets as Key Vault references, never plaintext app settings. Use the function app''s managed identity to reach other Azure services instead of connection strings. Enforce HTTPS-only and restrict CORS to known origins."}', '[{"kind": "source", "path": "src/functions/http-handler.ts", "priority": "essential", "description": "Primary Azure Functions HTTP trigger handler"}, {"kind": "config", "path": "host.json", "priority": "essential", "description": "Azure Functions host runtime configuration"}, {"kind": "config", "path": "local.settings.json", "priority": "recommended", "description": "Local development settings and connection configuration"}]', '{"runtime": {"type": "enum", "label": "Runtime", "default": "node", "options": ["node", "python", "dotnet", "java", "powershell"], "description": "Primary language runtime"}, "hostingPlan": {"type": "enum", "label": "Hosting plan", "default": "flex-consumption", "options": ["flex-consumption", "premium", "dedicated", "consumption-legacy"], "description": "Flex Consumption is the recommended serverless plan (Linux; VNet integration, 512/2048/4096 MB instances, always-ready to cut cold starts). Premium for prewarmed capacity; Dedicated to share an App Service plan. consumption-legacy only for existing Windows apps — Linux Consumption retires 2028-09-30."}, "vnetIntegration": {"type": "boolean", "label": "VNet Integration", "default": false, "description": "Enable private network integration for outbound access"}}', '["rest-api", "message-broker", "event-stream", "scheduler", "monitoring"]', false, NULL, NULL, '2026-03-14 15:29:57.538666+00', '2026-08-30 12:07:23.877005+00', NULL, '#005FAA', '''ad'':163C ''ak'':100B ''align'':72B ''api'':119C,167C ''app'':51B,97B,131C,177C,182C ''app.http'':134C ''applic'':83B,116C ''async'':141C ''asynchron'':62B ''auth'':155C,165C ''authlevel'':138C ''azur'':1A,3A,5B,8B,48B,105C,107C,109C,112C,115C,118C,121C,124C,162C,189C ''azure/functions'':133C ''base'':68B ''better'':103B ''bursti'':56B ''bus'':111C ''choos'':47B ''code'':21B ''comput'':14B ''connect'':193C ''const'':130C ''consum'':31B ''consumpt'':67B ''consumption-bas'':66B ''contain'':93B ''context'':143C ''control'':95B ''conveni'':152C ''cor'':201C ''coupl'':86B ''deep'':92B ''driven'':12B,59B ''easi'':164C ''endpoint'':29B,160C ''enforc'':195C ''event'':11B,71B,113C ''event-align'':70B ''event-driven'':10B ''face'':159C ''fit'':104B ''front'':156C ''function'':2A,4A,6B,49B,106C,125C,139C,148C,181C ''get'':137C ''grid'':114C ''handler'':140C ''hello'':135C ''high'':61B ''http'':28B ''https'':197C ''https-on'':196C ''ident'':185C ''insight'':117C ''instead'':191C ''integr'':37B ''invoc'':42B ''job'':33B ''jsonbodi'':145C ''key'':122C,149C,172C ''known'':203C ''live'':20B ''logic'':38B ''long'':80B ''long-run'':79B ''manag'':23B,120C,168C,184C ''method'':136C ''minim'':44B ''model'':128C ''monolith'':87B ''never'':175C ''node.js'':129C ''ok'':146C ''oper'':45B ''orchestr'':94B ''origin'':204C ''overhead'':