INSERT INTO public.technology_catalog VALUES ('electron', 'Electron', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/electron.png', '#47848f', '["desktop-app"]', '{"purpose": "Framework for building cross-platform desktop applications using web technologies (HTML, CSS, JavaScript/TypeScript) with full Node.js access and native OS integration", "configMode": "code", "provenance": {"notes": "Phase B8e additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Electron", "Node.js", "Chromium", "electron-builder", "electron-forge", "electron-vite", "electron-updater", "electron-store"], "antiPatterns": ["Disabling web security or context isolation for convenience", "Running Node.js APIs directly in the renderer process", "Not implementing IPC validation allowing renderer-to-main injection", "Large application bundles from including unneeded Chromium features", "Memory leaks from unclosed BrowserWindow instances", "Shipping without code signing causing OS security warnings"], "apiReference": {"docsUrl": "https://www.electronjs.org/docs/latest/"}, "bestPractices": ["Enable context isolation and sandbox for all renderer processes", "Use preload scripts for IPC instead of exposing Node.js to renderers", "Implement auto-updates with electron-updater and code signing", "Minimize main process work to keep the app responsive", "Use electron-builder for cross-platform packaging (MSI, DMG, AppImage, DEB)", "Implement proper Content Security Policy (CSP) headers", "Sign and notarize macOS builds for Gatekeeper approval", "Use session partition for multi-window isolation", "Store user preferences with electron-store in AppData/Library"], "sdkInitPattern": "// main.js — secure defaults\nconst { app, BrowserWindow, ipcMain } = require(''electron'');\n\napp.whenReady().then(() => {\n  const win = new BrowserWindow({\n    webPreferences: {\n      contextIsolation: true,\n      nodeIntegration: false,\n      sandbox: true,\n      preload: path.join(__dirname, ''preload.js''),\n    },\n  });\n  win.loadFile(''index.html'');\n});\n\nipcMain.handle(''orders:list'', async (event) => {\n  return await listOrdersForCurrentUser();  // validate sender + args on every handler\n});", "securityGuidance": "contextIsolation on, nodeIntegration off, sandbox on — the renderer is a browser tab and must stay one; capabilities cross only through a minimal preload contextBridge API, and every ipcMain handler validates the sender frame and its arguments (a compromised renderer will call anything you expose). Never load remote URLs into a privileged window, deny-by-default in setWindowOpenHandler and will-navigate, keep webSecurity on, ship through the signed auto-updater (electron-updater with a pinned feed), and remember asar is not protection — bundled secrets are extractable by anyone with the binary.", "setupInstructions": [{"type": "toolchain_install", "title": "Install Build Tools", "commands": ["xcode-select --install", "sudo apt-get install build-essential libnss3-dev libatk-bridge2.0-0"], "required": true, "instructions": "Install platform-specific build tools. On macOS: Xcode Command Line Tools. On Windows: Visual Studio Build Tools. On Linux: build-essential and related packages."}, {"url": "https://www.electronjs.org/docs/latest/tutorial/code-signing", "type": "dashboard_config", "title": "Configure Code Signing (Production)", "required": false, "instructions": "For production distribution, configure code signing certificates. macOS requires an Apple Developer account; Windows requires an EV code signing certificate."}, {"type": "manual_workflow", "title": "Configure Auto-Update Server", "required": false, "instructions": "Set up an update server (e.g., electron-updater with GitHub Releases, S3, or a custom server) for distributing application updates."}]}', '[{"kind": "source", "path": "src/main/index.ts", "language": "typescript", "description": "Electron main process entry point"}, {"kind": "source", "path": "src/preload/index.ts", "language": "typescript", "description": "Preload script for secure IPC bridge"}, {"kind": "source", "path": "src/main/ipc-handlers.ts", "language": "typescript", "description": "IPC message handlers for main process APIs"}, {"kind": "source", "path": "src/main/updater.ts", "language": "typescript", "description": "Auto-update logic using electron-updater"}, {"kind": "config", "path": "electron-builder.json", "language": "json", "description": "electron-builder configuration for all platform targets"}, {"kind": "config", "path": "electron.vite.config.ts", "language": "typescript", "description": "Electron Vite build configuration"}, {"kind": "config", "path": "build/entitlements.mac.plist", "language": "xml", "description": "macOS entitlements for hardened runtime and notarization"}, {"kind": "config", "path": "build/installer.nsh", "description": "NSIS custom installer script for Windows"}]', '{"targets": {"type": "multiselect", "label": "Build targets", "options": ["windows", "macos", "linux"], "description": "Signing and notarization are per-OS MANUAL setup, not code"}, "packager": {"type": "enum", "label": "Packager", "default": "electron-builder", "options": ["electron-builder", "electron-forge"]}, "autoUpdate": {"type": "boolean", "label": "Auto-update", "default": true}, "uiFramework": {"type": "enum", "label": "UI framework", "default": "react", "options": ["react", "vue", "svelte", "angular", "solid", "vanilla"], "description": "The web framework rendering inside Electron — this node IS the desktop app; do not model a second frontend node for the same UI"}, "contextIsolation": {"type": "boolean", "label": "Context isolation", "default": true, "description": "The security baseline — renderer never gets Node APIs directly; expose narrow bridges via preload"}}', '["rest-api", "database", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#3D7078', '''access'':20B ''anyon'':175C ''anyth'':126C ''api'':109C ''app'':47C ''app.whenready'':52C ''applic'':10B ''arg'':81C ''argument'':120C ''asar'':166C ''async'':74C ''auto'':155C ''auto-updat'':154C ''await'':77C ''binari'':178C ''browser'':95C ''browserwindow'':48C,57C ''build'':5B ''builder'':30C ''bundl'':170C ''call'':125C ''capabl'':101C ''chromium'':27C ''compromis'':122C ''const'':46C,54C ''contextbridg'':108C ''contextisol'':59C,85C ''cross'':7B,102C ''cross-platform'':6B ''css'':15B ''default'':45C,140C ''deni'':138C ''deny-by-default'':137C ''desktop'':9B ''dirnam'':67C ''electron'':1A,2A,25C,29C,32C,35C,38C,41C,51C,158C ''electron-build'':28C ''electron-forg'':31C ''electron-stor'':40C ''electron-updat'':37C,157C ''electron-vit'':34C ''event'':75C ''everi'':83C,111C ''expos'':128C ''extract'':173C ''fals'':62C ''feed'':163C ''forg'':33C ''frame'':117C ''framework'':3B ''full'':18B ''handler'':84C,113C ''html'':14B ''index.html'':70C ''integr'':24B ''ipcmain'':49C,112C ''ipcmain.handle'':71C ''javascript/typescript'':16B ''keep'':147C ''list'':73C ''listordersforcurrentus'':78C ''load'':130C ''main.js'':43C ''minim'':106C ''must'':98C ''nativ'':22B ''navig'':146C ''never'':129C ''new'':56C ''node.js'':19B,26C ''nodeintegr'':61C,87C ''one'':100C ''order'':72C ''os'':23B ''path.join'':66C ''pin'':162C ''platform'':8B ''preload'':65C,107C ''preload.js'':68C ''privileg'':135C ''protect'':169C ''rememb'':165C ''remot'':131C ''render'':92C,123C ''requir'':50C ''return'':76C ''sandbox'':63C,89C ''secret'':171C ''secur'':44C ''sender'':80C,116C ''setwindowopenhandl'':142C ''ship'':150C ''sign'':153C ''stay'':99C ''store'':42C ''tab'':96C ''technolog'':13B ''true'':60C,64C ''updat'':39C,156C,159C ''url'':132C ''use'':11B ''valid'':79C,114C ''vite'':36C ''web'':12B ''webprefer'':58C ''websecur'':148C ''will-navig'':144C ''win'':55C ''win.loadfile'':69C ''window'':136C');
INSERT INTO public.technology_catalog VALUES ('twilio', 'Twilio', NULL, '#6b7280', '["external-service"]', '{"purpose": "Cloud communications platform for sending SMS, making voice calls, and handling real-time messaging via programmable APIs.", "configMode": "external", "provenance": {"notes": "Phase B9 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Node.js", "Python", "webhooks", "TwiML"], "antiPatterns": ["Sending SMS without opt-in consent", "Ignoring delivery status webhooks", "Hardcoding phone numbers in source code", "Not handling Twilio error codes gracefully"], "apiReference": {"areas": {"lookup": {"docsUrl": "https://www.twilio.com/docs/lookup/v2-api", "endpoints": ["`GET https://lookups.twilio.com/v2/PhoneNumbers/{number}` — E.164 validation + carrier/line-type intelligence", "Use line_type_intelligence before SMS to avoid burning sends on landlines/VoIP"]}, "verify": {"docsUrl": "https://www.twilio.com/docs/verify/api", "endpoints": ["`POST https://verify.twilio.com/v2/Services/{ServiceSid}/Verifications` — start OTP (To, Channel=sms|call|whatsapp|email)", "`POST .../VerificationCheck` — check the submitted code (To, Code) → status=approved", "A Verification Service holds the common config (code length, friendly name) — one per product surface"]}, "webhooks": {"endpoints": ["Validate X-Twilio-Signature (HMAC-SHA1 of URL + sorted params with the auth token) on every inbound webhook", "Inbound messages/calls hit your webhook expecting TwiML (or empty 204 for messages handled async)", "Respond within 15s; long work goes async"]}, "messaging": {"docsUrl": "https://www.twilio.com/docs/messaging/api/message-resource", "endpoints": ["`POST https://api.twilio.com/2010-04-01/Accounts/{AccountSid}/Messages.json` — send (To, From or MessagingServiceSid, Body/MediaUrl); auth = AccountSid:AuthToken basic or API key", "StatusCallback URL per message — delivery receipts (queued → sent → delivered/failed) arrive as webhooks", "Messaging Services: `https://messaging.twilio.com/v1/Services` — sender pools, sticky sender, opt-out handling", "Channel fallback: RCS/MMS fall back to SMS automatically when undeliverable"]}}, "docsUrl": "https://www.twilio.com/docs/messaging/api"}, "bestPractices": ["Validate webhook signatures with X-Twilio-Signature", "Use messaging services for production SMS", "Handle delivery status callbacks", "Implement rate limiting for outbound messages"], "sdkInitPattern": "import twilio from ''twilio'';\n\nconst client = twilio(process.env.TWILIO_ACCOUNT_SID, process.env.TWILIO_AUTH_TOKEN);\nawait client.messages.create({\n  from: process.env.TWILIO_FROM_NUMBER,\n  to: userPhone,\n  body: ''Your verification code is 123456'',\n});", "securityGuidance": "The Account SID + Auth Token pair is full account control — server-side only, and prefer scoped API keys (revocable per service) over the master auth token for applications. Validate X-Twilio-Signature on every inbound webhook or anyone can forge SMS/call events at your endpoints. Phone numbers are PII: log message SIDs, not bodies or numbers, and use subaccounts to isolate environments and bound the blast radius of a leaked credential.", "setupInstructions": [{"url": "https://www.twilio.com/try-twilio", "type": "account_setup", "title": "Create Twilio Account", "required": true, "instructions": "Sign up at twilio.com. Verify your personal phone number during registration. Note your Account SID and Auth Token from the Console dashboard."}, {"type": "dashboard_config", "title": "Buy a Phone Number", "required": true, "instructions": "In Console > Phone Numbers > Buy a Number. Select a number with SMS and/or Voice capabilities based on your needs. This becomes your sender number."}, {"type": "webhook_config", "title": "Configure Webhook URL", "required": false, "instructions": "Under the phone number settings, set the webhook URL for incoming messages (A Message Comes In) and status callbacks. Use ngrok or similar for local testing."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export TWILIO_ACCOUNT_SID=AC...", "export TWILIO_AUTH_TOKEN=<from-console-dashboard>", "export TWILIO_PHONE_NUMBER=+1234567890"], "required": true, "instructions": "Add Twilio credentials to your application environment."}]}', '[]', '{"sender": {"type": "enum", "label": "Sender", "default": "messaging-service", "options": ["messaging-service", "single-phone-number"], "description": "Messaging Services (sender pools, sticky sender, compliance routing) are the production default; a bare phone number is fine for prototypes"}, "apiAreas": {"type": "multiselect", "label": "Twilio API areas used", "options": ["messaging", "verify", "lookup", "webhooks"], "description": "Which parts of the Twilio API this component calls — selected areas'' endpoint reference is embedded in the build instructions"}, "channels": {"type": "multiselect", "label": "Channels", "options": ["sms", "mms", "whatsapp", "rcs", "voice", "verify-otp"], "description": "Which communication channels this component sends through — drives sender setup and compliance work"}, "dataResidency": {"type": "enum", "label": "Data residency", "default": "us1-default", "options": ["us1-default", "ie1-eu", "au1"], "description": "Regional base URLs (e.g. api.dublin.ie1.twilio.com) for EU/AU data residency"}}', '[]', false, NULL, NULL, '2026-05-18 02:35:27.802569+00', '2026-08-30 12:07:23.877005+00', 'Twilio', NULL, '''123456'':51C ''account'':33C,53C,60C ''anyon'':91C ''api'':20B,69C ''applic'':80C ''auth'':36C,55C,77C ''await'':38C ''blast'':119C ''bodi'':46C,107C ''bound'':117C ''call'':11B ''client'':30C ''client.messages.create'':39C ''cloud'':3B ''code'':49C ''communic'':4B ''const'':29C ''control'':61C ''credenti'':124C ''endpoint'':98C ''environ'':115C ''event'':95C ''everi'':87C ''forg'':93C ''full'':59C ''handl'':13B ''import'':25C ''inbound'':88C ''isol'':114C ''key'':70C ''leak'':123C ''log'':103C ''make'':9B ''master'':76C ''messag'':17B,104C ''node.js'':21C ''number'':43C,100C,109C ''pair'':57C ''per'':72C ''phone'':99C ''pii'':102C ''platform'':5B ''prefer'':67C ''process.env.twilio'':32C,35C,41C ''programm'':19B ''python'':22C ''radius'':120C ''real'':15B ''real-tim'':14B ''revoc'':71C ''scope'':68C ''send'':7B ''server'':63C ''server-sid'':62C ''servic'':73C ''sid'':34C,54C,105C ''side'':64C ''signatur'':85C ''sms'':8B ''sms/call'':94C ''subaccount'':112C ''time'':16B ''token'':37C,56C,78C ''twilio'':1A,2A,26C,28C,31C,84C ''twiml'':24C ''use'':111C ''userphon'':45C ''valid'':81C ''verif'':48C ''via'':18B ''voic'':10B ''webhook'':23C,89C ''x'':83C ''x-twilio-signatur'':82C');
INSERT INTO public.technology_catalog VALUES ('supabase-edge-functions', 'Supabase Edge Functions', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_managed.png', '#6b7280', '["serverless-function"]', '{"purpose": "Server-side TypeScript functions deployed to Deno runtime at the edge. Use for webhooks, third-party API integrations, and custom server logic within the Supabase ecosystem.", "configMode": "code", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Deno", "TypeScript", "Supabase CLI"], "antiPatterns": ["Importing from deno.land/x or esm.sh CDNs", "Not handling OPTIONS preflight requests", "Using bare specifiers without npm: or jsr: prefix", "Sharing code between functions via relative imports"], "apiReference": {"docsUrl": "https://supabase.com/docs/guides/functions"}, "bestPractices": ["Use Deno.serve() for request handling", "Import npm packages with npm: prefix", "Handle CORS with Access-Control headers", "Use Supabase client with service role key for admin operations", "Keep functions focused on a single responsibility"], "freshnessNote": "Placement decides the lane: managed deploys via supabase functions deploy; self-hosted this is the open-source edge-runtime container — functions arrive by folder mount + restart. Runtime details (Deno, npm: specifiers, execution limits) live on the deno-edge technology row.", "sdkInitPattern": "// supabase/functions/orders/index.ts\nimport { createClient } from ''npm:@supabase/supabase-js@2'';\n\nDeno.serve(async (req: Request) => {\n  const authHeader = req.headers.get(''Authorization'')!;\n  const supabase = createClient(\n    Deno.env.get(''SUPABASE_URL'')!,\n    Deno.env.get(''SUPABASE_ANON_KEY'')!,\n    { global: { headers: { Authorization: authHeader } } },\n  );\n  const { data, error } = await supabase.from(''orders'').select(''*''); // RLS applies as the CALLER\n  if (error) return new Response(error.message, { status: 400 });\n  return Response.json(data);\n});", "securityGuidance": "Forward the caller''s JWT into the client so Row Level Security evaluates as the USER — constructing the client with the service-role key bypasses RLS entirely and must be a deliberate, endpoint-by-endpoint decision, never the default. Secrets come from function env (supabase secrets set), verify_jwt stays on unless the endpoint is intentionally public (webhooks verify their own signatures instead), and validate all input server-side — the function is your trust boundary, not the browser that called it.", "setupInstructions": [{"url": "https://supabase.com/docs/guides/cli", "type": "toolchain_install", "title": "Install Supabase CLI", "commands": ["npm install -g supabase", "supabase login"], "required": true, "instructions": "Install the Supabase CLI for local development and deployment of Edge Functions."}, {"type": "toolchain_install", "title": "Create a New Function", "commands": ["supabase functions new my-function"], "required": true, "instructions": "Use the CLI to scaffold a new Edge Function. This creates the function directory and index.ts file."}, {"type": "manual_workflow", "title": "Deploy Function", "commands": ["supabase functions deploy my-function"], "required": true, "instructions": "Deploy to your Supabase project. The function will be available at your project URL under /functions/v1/function-name."}, {"type": "environment_variable", "title": "Manage Secrets", "commands": ["supabase secrets set MY_API_KEY=value", "supabase secrets list"], "required": false, "instructions": "Set environment variables (secrets) for your Edge Functions. These are available via Deno.env.get() at runtime."}]}', '[{"kind": "code", "path": "supabase/functions/orders/index.ts", "language": "typescript", "description": "Edge function forwarding the caller JWT so RLS applies as the user"}]', '{"verifyJwt": {"type": "boolean", "label": "Verify JWT", "default": true, "description": "Default-on gateway check; turn off ONLY for public webhooks that verify their own signatures (Stripe, GitHub)"}, "secretsSource": {"type": "enum", "label": "Secrets", "default": "supabase-secrets-cli", "options": ["supabase-secrets-cli", "env-file-self-hosted"]}, "boundResources": {"type": "multiselect", "label": "Talks to", "options": ["supabase-db", "supabase-storage", "external-apis"], "description": "What the function reaches — drives the env/secret checklist in the packet"}}', '[]', false, NULL, NULL, '2026-05-18 02:38:14.715381+00', '2026-08-30 12:07:35.06843+00', 'Supabase Edge Functions', NULL, '''2'':45C ''400'':87C ''anon'':62C ''api'':25B ''appli'':76C ''async'':47C ''authhead'':51C,67C ''author'':53C,66C ''await'':71C ''boundari'':168C ''browser'':171C ''bypass'':116C ''call'':173C ''caller'':79C,93C ''cli'':38C ''client'':98C,109C ''come'':133C ''const'':50C,54C,68C ''construct'':107C ''createcli'':41C,56C ''custom'':28B ''data'':69C,90C ''decis'':128C ''default'':131C ''deliber'':123C ''deno'':14B,35C ''deno.env.get'':57C,60C ''deno.serve'':46C ''deploy'':12B ''ecosystem'':34B ''edg'':2A,5A,18B ''endpoint'':125C,127C,146C ''endpoint-by-endpoint'':124C ''entir'':118C ''env'':136C ''error'':70C,81C ''error.message'':85C ''evalu'':103C ''forward'':91C ''function'':3A,6A,11B,135C,164C ''global'':64C ''header'':65C ''import'':40C ''input'':159C ''instead'':155C ''integr'':26B ''intent'':148C ''jwt'':95C,141C ''key'':63C,115C ''level'':101C ''logic'':30B ''must'':120C ''never'':129C ''new'':83C ''npm'':43C ''order'':73C ''parti'':24B ''public'':149C ''req'':48C ''req.headers.get'':52C ''request'':49C ''respons'':84C ''response.json'':89C ''return'':82C,88C ''rls'':75C,117C ''role'':114C ''row'':100C ''runtim'':15B ''secret'':132C,138C ''secur'':102C ''select'':74C ''server'':8B,29B,161C ''server-sid'':7B,160C ''servic'':113C ''service-rol'':112C ''set'':139C ''side'':9B,162C ''signatur'':154C ''status'':86C ''stay'':142C ''supabas'':1A,4A,33B,37C,55C,58C,61C,137C ''supabase.from'':72C ''supabase/functions/orders/index.ts'':39C ''supabase/supabase-js'':44C ''third'':23B ''third-parti'':22B ''trust'':167C ''typescript'':10B,36C ''unless'':144C ''url'':59C ''use'':19B ''user'':106C ''valid'':157C ''verifi'':140C,151C ''webhook'':21B,150C ''within'':31B');
INSERT INTO public.technology_catalog VALUES ('supabase-auth', 'Supabase Auth', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_managed.png', '#3ecf8e', '["auth-provider"]', '{"purpose": "Managed authentication service built on GoTrue, deeply integrated with PostgreSQL Row Level Security. Provides email/password, magic links, phone auth, OAuth social providers, and SAML SSO. Auth state is stored in the auth schema and accessible via auth.uid() and auth.jwt() in RLS policies and database functions.", "configMode": "external", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["GoTrue", "@supabase/supabase-js", "@supabase/auth-helpers-nextjs", "@supabase/auth-helpers-react", "@supabase/ssr", "PostgreSQL RLS", "JWT", "PKCE"], "antiPatterns": ["Using service_role key in client-side code (exposes full database access)", "Storing authorization data in raw_user_meta_data (user can modify it)", "Not enabling RLS on tables that store user data", "Creating RLS policies with USING (true) which allows unrestricted access", "Using async callbacks directly with onAuthStateChange (causes deadlocks)", "Not handling token refresh or session expiration", "Directly querying auth.users or auth schema tables from client code", "Exposing JWT secrets or service_role key in frontend bundles", "Relying solely on client-side auth checks without server-side RLS enforcement", "Not using email confirmation in production (allows unverified signups)"], "apiReference": {"docsUrl": "https://supabase.com/docs/guides/auth"}, "bestPractices": ["Use Row Level Security (RLS) policies with auth.uid() as the primary authorization mechanism", "Use onAuthStateChange listener for reactive session management", "Wrap async logic inside onAuthStateChange in an IIFE to avoid deadlocks", "Use @supabase/ssr for server-side rendering frameworks (Next.js, SvelteKit, Remix)", "Enable email confirmation for production deployments", "Use PKCE flow for mobile and SPA applications", "Store custom user data in a public.profiles table with RLS, not in auth.users metadata", "Use auth.jwt() -> app_metadata for authorization claims (cannot be modified by user)", "Use Supabase Edge Functions with service_role key for admin auth operations", "Implement proper error handling for signUp, signIn, and signOut flows", "Use auth.admin for server-side privileged operations like user management", "Add auth hooks (database webhooks) for post-signup provisioning", "Use custom claims via database functions for role-based access control"], "freshnessNote": "Placement decides the lane: inside Supabase (Managed), auth is the managed service (dashboard provider toggles, SMS/SSO config). Self-hosted, this node is the open-source GoTrue container — OAuth providers, SMTP and redirect URLs are environment configuration, and phone auth needs your own provider wiring.", "sdkInitPattern": "import { createClient } from ''@supabase/supabase-js'';\n\nconst supabase = createClient(process.env.SUPABASE_URL!, process.env.SUPABASE_ANON_KEY!);\nconst { data, error } = await supabase.auth.signInWithOAuth({\n  provider: ''github'',\n  options: { redirectTo: `${origin}/auth/callback` },\n});\n// server-side: verify the session JWT on every request via supabase.auth.getUser()", "securityGuidance": "The anon key is public by design — security comes from RLS plus auth server settings, not key secrecy; the service-role key bypasses everything and never leaves the server. Verify sessions server-side with getUser() (which validates against the auth server) rather than trusting a decoded JWT alone, keep redirect URLs exact (a wildcard redirect is token exfiltration), enable email confirmation and sensible OTP expiries, and require MFA for admin-tier users. Auth hooks/triggers that mint claims are access-policy code — review them like RLS.", "setupInstructions": [{"url": "https://supabase.com/docs/guides/auth", "type": "dashboard_config", "title": "Enable Auth in Supabase Dashboard", "required": true, "instructions": "Navigate to Authentication > Providers in your Supabase dashboard to enable email/password and any social providers."}, {"type": "dashboard_config", "title": "Configure Redirect URLs", "required": true, "instructions": "Add your application URLs to Authentication > URL Configuration > Redirect URLs in the Supabase dashboard."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export VITE_SUPABASE_URL=https://your-project.supabase.co", "export VITE_SUPABASE_ANON_KEY=your-anon-key"], "required": true, "instructions": "Ensure SUPABASE_URL and SUPABASE_ANON_KEY are set in your application environment."}]}', '[{"kind": "config", "path": "src/lib/supabase.ts", "language": "typescript", "priority": "essential", "description": "Supabase client singleton with auth configuration"}, {"kind": "source", "path": "src/auth/AuthProvider.tsx", "language": "typescript", "priority": "essential", "description": "React auth context provider using onAuthStateChange"}, {"kind": "source", "path": "src/auth/ProtectedRoute.tsx", "language": "typescript", "priority": "essential", "description": "Route guard component checking auth session state"}, {"kind": "source", "path": "src/auth/useAuth.ts", "language": "typescript", "priority": "essential", "description": "Auth hook for accessing session, user, signIn, signOut"}, {"kind": "schema", "path": "supabase/migrations/create_profiles.sql", "language": "sql", "priority": "essential", "description": "Public profiles table with RLS policies linked to auth.uid()"}, {"kind": "schema", "path": "supabase/migrations/rls-policies.sql", "language": "sql", "priority": "essential", "description": "Row Level Security policies using auth.uid() for data access control"}, {"kind": "source", "path": "supabase/functions/auth-webhook/index.ts", "language": "typescript", "priority": "recommended", "description": "Edge Function for post-signup provisioning webhook"}, {"kind": "config", "path": "supabase/config.toml", "language": "toml", "priority": "recommended", "description": "Local Supabase config with auth settings (email confirmation, providers)"}, {"kind": "source", "path": "src/middleware/auth.ts", "language": "typescript", "priority": "recommended", "description": "Server middleware for SSR auth with @supabase/ssr"}]', '{"pkceFlow": {"type": "boolean", "label": "PKCE Flow", "default": true, "description": "Use PKCE auth flow for SPAs and mobile apps (recommended)"}, "emailAuth": {"type": "boolean", "label": "Email/Password Auth", "default": true, "description": "Enable email and password authentication"}, "phoneAuth": {"type": "boolean", "label": "Phone Auth", "default": false, "description": "Enable phone number (SMS) authentication"}, "magicLinks": {"type": "boolean", "label": "Magic Links", "default": false, "description": "Enable passwordless magic link authentication"}, "mfaEnabled": {"type": "boolean", "label": "MFA", "default": false, "description": "Enable multi-factor authentication with TOTP"}, "projectUrl": {"type": "string", "label": "Supabase Project URL", "description": "Supabase project API URL"}, "customClaims": {"type": "boolean", "label": "Custom Claims", "default": false, "description": "Use app_metadata custom claims for role-based access control"}, "sessionTimeout": {"type": "number", "label": "Session Timeout (seconds)", "default": 3600, "description": "JWT token expiration time in seconds"}, "socialProviders": {"type": "array", "label": "OAuth Providers", "description": "Enabled social login providers (Google, GitHub, Discord, etc.)"}, "emailConfirmation": {"type": "boolean", "label": "Email Confirmation", "default": false, "description": "Require email confirmation before allowing sign-in"}}', '["database", "backend-service", "frontend-app", "edge-function"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:35.06843+00', NULL, '#32A872', '''/auth/callback'':81C ''access'':39B,176C ''access-polici'':175C ''admin'':166C ''admin-ti'':165C ''alon'':143C ''anon'':69C,95C ''auth'':2A,4A,23B,30B,36B,106C,135C,169C ''auth.jwt'':43B ''auth.uid'':41B ''authent'':6B ''await'':74C ''built'':8B ''bypass'':117C ''claim'':173C ''code'':178C ''come'':102C ''confirm'':156C ''const'':63C,71C ''createcli'':60C,65C ''data'':72C ''databas'':48B ''decod'':141C ''deepli'':11B ''design'':100C ''email'':155C ''email/password'':19B ''enabl'':154C ''error'':73C ''everi'':90C ''everyth'':118C ''exact'':147C ''exfiltr'':153C ''expiri'':160C ''function'':49B ''getus'':130C ''github'':77C ''gotru'':10B,50C ''hooks/triggers'':170C ''import'':59C ''integr'':12B ''jwt'':57C,88C,142C ''keep'':144C ''key'':70C,96C,110C,116C ''leav'':121C ''level'':16B ''like'':181C ''link'':21B ''magic'':20B ''manag'':5B ''mfa'':163C ''mint'':172C ''never'':120C ''oauth'':24B ''option'':78C ''origin'':80C ''otp'':159C ''phone'':22B ''pkce'':58C ''plus'':105C ''polici'':46B,177C ''postgresql'':14B,55C ''process.env.supabase'':66C,68C ''provid'':18B,26B,76C ''public'':98C ''rather'':137C ''redirect'':145C,150C ''redirectto'':79C ''request'':91C ''requir'':162C ''review'':179C ''rls'':45B,56C,104C,182C ''role'':115C ''row'':15B ''saml'':28B ''schema'':37B ''secreci'':111C ''secur'':17B,101C ''sensibl'':158C ''server'':83C,107C,123C,127C,136C ''server-sid'':82C,126C ''servic'':7B,114C ''service-rol'':113C ''session'':87C,125C ''set'':108C ''side'':84C,128C ''social'':25B ''sso'':29B ''state'':31B ''store'':33B ''supabas'':1A,3A,64C ''supabase.auth.getuser'':93C ''supabase.auth.signinwithoauth'':75C ''supabase/auth-helpers-nextjs'':52C ''supabase/auth-helpers-react'':53C ''supabase/ssr'':54C ''supabase/supabase-js'':51C,62C ''tier'':167C ''token'':152C ''trust'':139C ''url'':67C,146C ''user'':168C ''valid'':132C ''verifi'':85C,124C ''via'':40B,92C ''wildcard'':149C');
INSERT INTO public.technology_catalog VALUES ('auth0', 'Auth0', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/auth0.png', '#eb5424', '["auth-provider"]', '{"purpose": "Identity platform providing Universal Login, MFA, social connections, enterprise federation (SAML/OIDC), Organizations for B2B multi-tenancy, and Auth0 Actions for extensible login pipelines", "configMode": "external", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: model-knowledge 2026-08-10. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Auth0", "auth0-react", "auth0-nextjs", "express-oauth2-jwt-bearer", "Auth0 Actions", "Auth0 Organizations", "Auth0 Deploy CLI", "Auth0 Management API"], "antiPatterns": ["Implementing custom login pages when Universal Login works", "Not validating tokens on the backend", "Storing sensitive data in user metadata (limited to 16 KB)", "Not implementing proper logout flow (both local and Auth0 session)", "Ignoring rate limits on Management API calls", "Using deprecated Rules instead of Actions", "Hardcoding client secrets in frontend code"], "apiReference": {"docsUrl": "https://auth0.com/docs"}, "bestPractices": ["Use Universal Login for consistent, secure authentication UX", "Implement Auth0 Actions (post-login, pre-registration) for custom logic", "Use Auth0 Organizations for B2B multi-tenant SaaS", "Configure proper token lifetimes and rotation policies", "Implement RBAC with Auth0 permissions and roles", "Use Auth0 Deploy CLI or Terraform provider for environment promotion", "Store tenant configuration as code in auth0/ directory", "Validate JWTs on backend using express-oauth2-jwt-bearer or equivalent", "Use refresh token rotation for enhanced security", "Configure brute-force protection and anomaly detection"], "sdkInitPattern": "import { auth } from ''express-oauth2-jwt-bearer'';\n\n// verify Auth0-issued JWTs on every API request\napp.use(auth({\n  audience: process.env.AUTH0_AUDIENCE,\n  issuerBaseURL: `https://${process.env.AUTH0_DOMAIN}/`,\n}));\n\napp.get(''/api/orders'', (req, res) => {\n  const userId = req.auth.payload.sub;  // identity comes from the VERIFIED token\n  res.json(listOrders(userId));\n});", "securityGuidance": "Verify tokens server-side on every request — audience and issuer pinned, identity read from the verified payload, never from client-supplied fields. Client secrets and Management API tokens are server-side only (SPAs use authorization-code + PKCE with rotating refresh tokens); callback/logout URLs are exact, never wildcarded. Actions run inside your login flow — review them like auth code and keep their secrets in Action config. Scope Management API tokens to the fewest grants and mind its rate limits: syncing user data on every request is both a perf and an availability bug.", "setupInstructions": [{"url": "https://auth0.com/signup", "type": "account_setup", "title": "Create Auth0 Tenant", "required": true, "instructions": "Create an Auth0 account and tenant at the Auth0 dashboard. Choose your tenant region based on user proximity."}, {"url": "https://auth0.com/docs/get-started/applications", "type": "dashboard_config", "title": "Configure Application", "required": true, "instructions": "Create a new Application in Auth0 dashboard. Set allowed callback URLs, logout URLs, and web origins for your deployment domain."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export AUTH0_DOMAIN=your-tenant.auth0.com", "export AUTH0_CLIENT_ID=your-client-id", "export AUTH0_CLIENT_SECRET=your-client-secret"], "required": true, "instructions": "Add AUTH0_DOMAIN, AUTH0_CLIENT_ID, and AUTH0_CLIENT_SECRET to your environment."}, {"type": "dashboard_config", "title": "Configure OAuth Connections", "required": false, "instructions": "Enable social connections (Google, GitHub, etc.) or enterprise connections (SAML, OIDC) in the Auth0 dashboard under Authentication > Social/Enterprise."}]}', '[{"kind": "config", "path": "auth0/tenant.yaml", "language": "yaml", "priority": "essential", "description": "Auth0 tenant configuration for environment promotion"}, {"kind": "source", "path": "auth0/rules/assign-roles.js", "language": "javascript", "priority": "recommended", "description": "Auth0 Rule or Action for role assignment on login"}, {"kind": "source", "path": "auth0/actions/post-login.js", "language": "javascript", "priority": "recommended", "description": "Auth0 Action triggered after successful login"}, {"kind": "source", "path": "src/auth/auth0-provider.tsx", "language": "typescript", "priority": "essential", "description": "Auth0 React provider wrapper with Auth0Provider"}, {"kind": "config", "path": "src/auth/auth0-config.ts", "language": "typescript", "priority": "essential", "description": "Auth0 client configuration with domain and clientId"}, {"kind": "source", "path": "src/middleware/auth0-verify.ts", "language": "typescript", "priority": "essential", "description": "Backend middleware to verify Auth0 JWT tokens"}, {"kind": "config", "path": "auth0/connections/database.json", "language": "json", "priority": "recommended", "description": "Custom database connection configuration"}, {"kind": "doc", "path": "auth0/email-templates/welcome.html", "language": "html", "priority": "recommended", "description": "Customized welcome email template"}]', '{"mfa": {"type": "boolean", "label": "MFA Enabled", "default": false, "description": "Enable multi-factor authentication"}, "domain": {"type": "string", "label": "Auth0 Domain", "description": "Your Auth0 tenant domain (e.g., myapp.auth0.com)"}, "audience": {"type": "string", "label": "API Audience", "description": "Auth0 API audience identifier for token validation"}, "clientId": {"type": "string", "label": "Client ID", "description": "Auth0 application client ID"}, "universalLogin": {"type": "boolean", "label": "Universal Login", "default": true, "description": "Use Auth0 Universal Login (recommended)"}, "socialConnections": {"type": "array", "label": "Social Connections", "description": "Enabled social identity providers (Google, GitHub, etc.)"}}', '["backend-service", "frontend-app", "api-gateway", "rest-api", "serverless-function"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#C9461E', '''/api/orders'':77C ''action'':22B,40C,143C,159C ''api'':48C,64C,120C,163C ''app.get'':76C ''app.use'':66C ''audienc'':68C,71C,100C ''auth'':50C,67C,152C ''auth0'':1A,2A,21B,27C,29C,32C,39C,41C,43C,46C,59C,70C,74C ''auth0-issued'':58C ''auth0-nextjs'':31C ''auth0-react'':28C ''author'':130C ''authorization-cod'':129C ''avail'':186C ''b2b'':16B ''bearer'':38C,56C ''bug'':187C ''callback/logout'':137C ''cli'':45C ''client'':113C,116C ''client-suppli'':112C ''code'':131C,153C ''come'':84C ''config'':160C ''connect'':10B ''const'':80C ''data'':176C ''deploy'':44C ''domain'':75C ''enterpris'':11B ''everi'':63C,98C,178C ''exact'':140C ''express'':35C,53C ''express-oauth2-jwt-bearer'':34C,52C ''extens'':24B ''feder'':12B ''fewest'':167C ''field'':115C ''flow'':148C ''grant'':168C ''ident'':3B,83C,104C ''import'':49C ''insid'':145C ''issu'':60C ''issuer'':102C ''issuerbaseurl'':72C ''jwt'':37C,55C ''jwts'':61C ''keep'':155C ''like'':151C ''limit'':173C ''listord'':90C ''login'':7B,25B,147C ''manag'':47C,119C,162C ''mfa'':8B ''mind'':170C ''multi'':18B ''multi-ten'':17B ''never'':110C,141C ''nextj'':33C ''oauth2'':36C,54C ''organ'':14B,42C ''payload'':109C ''perf'':183C ''pin'':103C ''pipelin'':26B ''pkce'':132C ''platform'':4B ''process.env'':69C,73C ''provid'':5B ''rate'':172C ''react'':30C ''read'':105C ''refresh'':135C ''req'':78C ''req.auth.payload.sub'':82C ''request'':65C,99C,179C ''res'':79C ''res.json'':89C ''review'':149C ''rotat'':134C ''run'':144C ''saml/oidc'':13B ''scope'':161C ''secret'':117C,157C ''server'':95C,124C ''server-sid'':94C,123C ''side'':96C,125C ''social'':9B ''spas'':127C ''suppli'':114C ''sync'':174C ''tenanc'':19B ''token'':88C,93C,121C,136C,164C ''univers'':6B ''url'':138C ''use'':128C ''user'':175C ''userid'':81C,91C ''verifi'':57C,87C,92C,108C ''wildcard'':142C');
INSERT INTO public.technology_catalog VALUES ('mongodb', 'MongoDB', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/mongodb.png', '#47a248', '["database"]', '{"purpose": "Document-oriented NoSQL database storing data as flexible JSON-like (BSON) documents. Use when your data model is hierarchical or deeply nested, when schema evolves frequently across iterations, or when you need to store heterogeneous document structures in the same collection. MongoDB excels at rapid prototyping, content management systems, product catalogs with varying attributes, and real-time analytics via the aggregation framework. Don''t use when your data is highly relational with many join-heavy queries -- MongoDB lacks native joins and $lookup is expensive at scale. Don''t use for strict transactional workloads requiring complex multi-collection ACID (though multi-document transactions exist, they add overhead). Avoid if PostgreSQL JSONB can handle your semi-structured needs within a relational model, as it offers both flexibility and relational querying.", "configMode": "declarative", "provenance": {"notes": "docsUrl is the vendor''s canonical documentation root, stamped from model knowledge and checked by scripts/n10-verify-docs-urls.ts; pre-existing body content not yet live-docs verified — upgrade at this row''s enrichment chunk.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["MongoDB 7+", "MongoDB Atlas", "Mongoose", "MongoDB Compass", "Mongosh", "MongoDB Change Streams", "Atlas Search", "Atlas Vector Search"], "antiPatterns": ["Treating MongoDB like a relational database with normalized tables and excessive $lookups", "Not creating indexes on fields used in queries causing full collection scans", "Storing unbounded arrays that grow indefinitely within documents", "Using MongoDB as a queue when dedicated message brokers are more appropriate", "Ignoring schema validation allowing inconsistent document shapes", "Running without authentication in any environment beyond local development"], "apiReference": {"docsUrl": "https://www.mongodb.com/docs/"}, "bestPractices": ["Design schemas around query access patterns, not entity relationships", "Embed related data in documents when read together, reference when independently accessed", "Create compound indexes matching your most common query filters and sort orders", "Use the aggregation framework for analytics instead of pulling data to the app", "Set appropriate write concern and read concern for your consistency needs", "Use MongoDB Atlas for managed hosting with automated backups and scaling", "Use change streams for real-time event-driven architectures"], "sdkInitPattern": "// Node.js with mongodb driver\\nimport { MongoClient } from \"mongodb\";\\nconst client = new MongoClient(process.env.MONGODB_URI!);\\nconst db = client.db(\"myapp\");\\n// [Tailor to project language: Python=pymongo, Go=mongo-driver, Rust=mongodb, .NET=MongoDB.Driver]", "securityGuidance": "Always enable authentication and authorization -- never run without auth outside local dev. Use TLS/SSL for all connections. Create database users with the minimum required roles (readWrite, read, etc.) per application. Enable audit logging for compliance. Use field-level encryption for sensitive data like PII. Restrict network access with IP allowlists or VPC peering.", "commonApiPatterns": [{"name": "CRUD Operations", "description": "Basic insert, find, update, delete operations", "codeTemplate": "const users = db.collection<User>(\"users\");\\nawait users.insertOne({ name, email, createdAt: new Date() });\\nconst user = await users.findOne({ email });\\nawait users.updateOne({ _id: userId }, { $set: { name: newName } });\\nawait users.deleteOne({ _id: userId });"}, {"name": "Aggregation Pipeline", "description": "Aggregation pipeline for analytics queries", "codeTemplate": "const result = await db.collection(\"orders\").aggregate([\\n  { $match: { status: \"completed\", createdAt: { $gte: startDate } } },\\n  { $group: { _id: \"$customerId\", totalSpent: { $sum: \"$total\" }, count: { $sum: 1 } } },\\n  { $sort: { totalSpent: -1 } },\\n  { $limit: 10 }\\n]).toArray();"}, {"name": "Change Stream", "description": "Real-time change notification via change streams", "codeTemplate": "const changeStream = db.collection(\"orders\").watch([{ $match: { operationType: \"insert\" } }]);\\nchangeStream.on(\"change\", (change) => {\\n  console.log(\"New order:\", change.fullDocument);\\n});"}, {"name": "Text Search", "description": "Full-text search with relevance scoring", "codeTemplate": "await db.collection(\"articles\").createIndex({ title: \"text\", body: \"text\" });\\nconst results = await db.collection(\"articles\").find({ $text: { $search: \"machine learning\" } }).sort({ score: { $meta: \"textScore\" } }).toArray();"}], "setupInstructions": [{"url": "https://www.mongodb.com/atlas/database", "type": "manual_workflow", "title": "Provision MongoDB Instance", "required": true, "instructions": "Set up MongoDB via MongoDB Atlas (managed) or self-hosted. Atlas offers a free tier for development."}, {"type": "dashboard_config", "title": "Configure Network Access", "required": true, "instructions": "In MongoDB Atlas, add your application server IP addresses to the Network Access list. For development, you can allow access from anywhere (0.0.0.0/0)."}, {"type": "environment_variable", "title": "Set Connection String", "commands": ["export MONGODB_URI=mongodb+srv://user:password@cluster.mongodb.net/dbname"], "required": true, "instructions": "Get the connection string from your MongoDB provider and configure it in your environment."}], "integrationPatterns": ["MongoDB Atlas for managed hosting with built-in search and vector capabilities", "Mongoose for schema validation and middleware in Node.js applications", "Change Streams for event-driven microservice communication", "Atlas Search (Lucene-based) for full-text and faceted search"], "configurationTemplate": "# mongod.conf key settings\\nstorage:\\n  dbPath: /data/db\\n  wiredTiger:\\n    engineConfig:\\n      cacheSizeGB: 2\\nnet:\\n  bindIp: 127.0.0.1\\n  tls:\\n    mode: requireTLS\\n    certificateKeyFile: /etc/ssl/mongo.pem\\nsecurity:\\n  authorization: enabled\\nreplication:\\n  replSetName: rs0"}', '[{"kind": "schema", "path": "models/", "language": "typescript", "description": "Mongoose/schema models directory"}]', '{"topology": {"type": "enum", "label": "Topology", "default": "replica-set", "options": ["replica-set", "standalone-dev-only", "sharded"], "description": "Replica set is the production baseline (transactions and change streams require it); standalone is a dev convenience, not a deployment"}, "changeStreams": {"type": "boolean", "label": "Change streams used", "default": false, "description": "Downstream consumers of data changes — an architecture fact worth declaring"}, "schemaDiscipline": {"type": "enum", "label": "Schema discipline", "default": "validator-enforced", "options": ["validator-enforced", "app-enforced-only"], "description": "JSON Schema validators on collections — schemaless storage does not mean schemaless data"}}', '["backend-service", "rest-api"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#3D8B40', '''7'':139C ''access'':234C ''acid'':105B ''across'':31B ''add'':113B ''aggreg'':66B ''allowlist'':237C ''alway'':187C ''analyt'':63B ''applic'':216C ''atlas'':141C,149C,151C ''attribut'':58B ''audit'':218C ''auth'':195C ''authent'':189C ''author'':191C ''avoid'':115B ''bson'':15B ''catalog'':55B ''chang'':147C ''client'':163C ''client.db'':170C ''collect'':45B,104B ''compass'':144C ''complex'':101B ''complianc'':221C ''connect'':203C ''content'':51B ''creat'':204C ''data'':9B,20B,73B,229C ''databas'':7B,205C ''db'':169C ''deepli'':25B ''dev'':198C ''document'':4B,16B,40B,109B ''document-ori'':3B ''driver'':157C,182C ''enabl'':188C,217C ''encrypt'':226C ''etc'':214C ''evolv'':29B ''excel'':47B ''exist'':111B ''expens'':90B ''field'':224C ''field-level'':223C ''flexibl'':11B,134B ''framework'':67B ''frequent'':30B ''go'':179C ''handl'':120B ''heavi'':81B ''heterogen'':39B ''hierarch'':23B ''high'':75B ''ip'':236C ''iter'':32B ''join'':80B,86B ''join-heavi'':79B ''json'':13B ''json-lik'':12B ''jsonb'':118B ''lack'':84B ''languag'':176C ''level'':225C ''like'':14B,230C ''local'':197C ''log'':219C ''lookup'':88B ''manag'':52B ''mani'':78B ''minimum'':209C ''model'':21B,129B ''mongo'':181C ''mongo-driv'':180C ''mongocli'':159C,165C ''mongodb'':1A,2A,46B,83B,138C,140C,143C,146C,156C,161C,184C ''mongodb.driver'':186C ''mongoos'':142C ''mongosh'':145C ''multi'':103B,108B ''multi-collect'':102B ''multi-docu'':107B ''myapp'':171C ''n'':172C ''nativ'':85B ''nconst'':162C,168C ''need'':36B,125B ''nest'':26B ''net'':185C ''network'':233C ''never'':192C ''new'':164C ''nimport'':158C ''node.js'':154C ''nosql'':6B ''offer'':132B ''orient'':5B ''outsid'':196C ''overhead'':114B ''peer'':240C ''per'':215C ''pii'':231C ''postgresql'':117B ''process.env.mongodb'':166C ''product'':54B ''project'':175C ''prototyp'':50B ''pymongo'':178C ''python'':177C ''queri'':82B,137B ''rapid'':49B ''read'':213C ''readwrit'':212C ''real'':61B ''real-tim'':60B ''relat'':76B,128B,136B ''requir'':100B,210C ''restrict'':232C ''role'':211C ''run'':193C ''rust'':183C ''scale'':92B ''schema'':28B ''search'':150C,153C ''semi'':123B ''semi-structur'':122B ''sensit'':228C ''store'':8B,38B ''stream'':148C ''strict'':97B ''structur'':41B,124B ''system'':53B ''tailor'':173C ''though'':106B ''time'':62B ''tls/ssl'':200C ''transact'':98B,110B ''uri'':167C ''use'':17B,70B,95B,199C,222C ''user'':206C ''vari'':57B ''vector'':152C ''via'':64B ''vpc'':239C ''within'':126B ''without'':194C ''workload'':99B');
INSERT INTO public.technology_catalog VALUES ('posthog', 'PostHog', NULL, '#F54E00', '["external-service", "monitoring"]', '{"purpose": "All-in-one product analytics with feature flags, session replay, and experiments", "configMode": "external", "provenance": {"notes": "Phase B2 setupInstructions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["posthog-js", "posthog-node", "Feature flags", "Session replay", "Self-hosted or cloud"], "antiPatterns": ["Capturing autocapture noise without a curated event taxonomy", "Sending PII in event properties instead of person properties", "Checking feature flags only client-side for security-relevant gates"], "apiReference": {"areas": {"query": {"endpoints": ["`POST /api/projects/{id}/query/` — HogQL (SQL dialect) over your events for product dashboards and exports", "Personal API key auth; paginate and cache — analytical queries are not a hot path"]}, "capture": {"endpoints": ["`POST /i/v0/e/` (or SDK capture) — events with distinct_id + properties; batch endpoint for server-side volume", "identify to merge anonymous → known users; group() for B2B account-level analytics", "Use the project API key client-side (write-only); the personal API key is server-side ONLY", "Proxy the JS snippet through your domain (managed reverse proxy) so ad-blockers do not blind analytics"]}, "feature-flags": {"endpoints": ["`POST /decide` — flag evaluation for a distinct_id (the SDK calls this); returns variants + payloads", "Server-side LOCAL evaluation with a personal API key polls flag definitions — zero-latency checks, no per-request network call", "Bootstrap flags into the frontend on first paint to avoid flicker", "Experiments ride feature flags — the flag variant IS the experiment arm"]}}, "docsUrl": "https://posthog.com/docs/api"}, "bestPractices": ["Initialize once in a client provider and identify users after auth", "Define a tracking plan; name events object_action (project_created)", "Use feature flags for gradual rollouts and kill switches", "Evaluate flags server-side with posthog-node for gated backend logic", "Use group analytics for B2B account-level metrics"], "sdkInitPattern": "import posthog from ''posthog-js'';\nposthog.init(process.env.NEXT_PUBLIC_POSTHOG_KEY, { api_host: ''https://us.i.posthog.com'' });\nposthog.identify(user.id, { plan: user.plan });", "securityGuidance": "Use a reverse proxy for ingestion to avoid ad blockers; scrub PII from replays", "setupInstructions": [{"url": "https://posthog.com", "type": "account_setup", "title": "Create a PostHog project and copy its API key", "required": true, "instructions": "In the PostHog app (cloud or self-hosted instance), create a project and copy the Project API key from Settings — this is the client-safe key used by the SDKs."}, {"type": "sdk_install", "title": "Install the SDK", "commands": ["npm install posthog-js"], "required": true, "instructions": "Frontend: posthog-js. Server: posthog-node. Initialize with the Project API key and your instance host."}, {"type": "environment_variable", "title": "Configure key and host", "required": true, "instructions": "Set the Project API key and API host (cloud region or your self-hosted URL) as environment configuration rather than hardcoding them."}]}', '[{"kind": "source", "path": "src/lib/posthog.ts", "priority": "essential"}, {"kind": "config", "path": "instrumentation-client.ts", "priority": "recommended"}]', '{"hosting": {"type": "enum", "label": "Hosting", "default": "posthog-cloud-us", "options": ["posthog-cloud-us", "posthog-cloud-eu", "self-hosted"], "description": "EU cloud for GDPR data residency; self-hosted only with real ops capacity"}, "apiAreas": {"type": "multiselect", "label": "PostHog API areas used", "options": ["capture", "feature-flags", "query"], "description": "Which parts of the PostHog API this component calls — selected areas'' endpoint reference is embedded in the build instructions"}, "products": {"type": "multiselect", "label": "PostHog products used", "options": ["product-analytics", "session-replay", "feature-flags", "experiments", "error-tracking", "surveys"], "description": "PostHog is a suite — declaring which products this app actually uses scopes the integration work"}}', '[{"id": "react", "reason": "Client SDK integration"}, {"id": "nodejs", "reason": "Server-side flag evaluation"}]', false, NULL, NULL, '2026-08-30 12:07:21.442329+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''ad'':57C ''all-in-on'':3B ''analyt'':8B ''api'':42C ''avoid'':56C ''blocker'':58C ''cloud'':30C ''experi'':15B ''featur'':10B,22C ''flag'':11B,23C ''host'':28C,43C ''import'':31C ''ingest'':54C ''js'':18C,36C ''key'':41C ''node'':21C ''one'':6B ''pii'':60C ''plan'':47C ''posthog'':1A,2A,17C,20C,32C,35C,40C ''posthog-j'':16C,34C ''posthog-nod'':19C ''posthog.identify'':45C ''posthog.init'':37C ''process.env.next'':38C ''product'':7B ''proxi'':52C ''public'':39C ''replay'':13B,25C,62C ''revers'':51C ''scrub'':59C ''self'':27C ''self-host'':26C ''session'':12B,24C ''us.i.posthog.com'':44C ''use'':49C ''user.id'':46C ''user.plan'':48C');
INSERT INTO public.technology_catalog VALUES ('ollama', 'Ollama', NULL, '#1a1a2e', '["inference-service"]', '{"purpose": "Native macOS, Linux, and Windows application that downloads and serves open-source language models locally via an OpenAI-compatible REST API. Primary deployment story is OS-native install, with Docker support for containerized environments.", "configMode": "declarative", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Docker", "GPU drivers (CUDA/Metal/ROCm)", "LiteLLM", "OpenWebUI", "LangChain"], "antiPatterns": ["Exposing the Ollama port (11434) directly to the internet without authentication", "Pulling models at container startup rather than baking them into a volume or image layer", "Running production inference on CPU-only hardware"], "apiReference": {"docsUrl": "https://github.com/ollama/ollama/tree/main/docs"}, "bestPractices": ["Install natively on macOS (dmg), Linux (install.sh), or Windows (exe) for best GPU utilization", "Use docker-compose with GPU passthrough only when native install is not feasible", "Set OLLAMA_KEEP_ALIVE to balance VRAM retention vs cold-start latency", "Pin model versions (e.g., llama3.2:3b-instruct-q4_K_M) for production reproducibility", "Front with LiteLLM or a gateway when serving multiple upstream consumers"], "securityGuidance": "The API has no authentication — binding 11434 beyond localhost/an internal network is an open inference endpoint (and open model management: anyone who can reach it can pull or delete models). Front it with an authenticating reverse proxy for anything multi-user, set OLLAMA_ORIGINS deliberately (browser pages on allowed origins can call the API), treat downloaded model files as supply-chain artifacts (pin tags/digests you have vetted), and remember prompts and outputs stay on the box — that locality is the privacy win, so do not undo it by logging full prompts to a shared sink.", "configurationTemplate": "# docker-compose.yml\nservices:\n  ollama:\n    image: ollama/ollama\n    volumes: [ollama:/root/.ollama]\n    ports: [''127.0.0.1:11434:11434'']\nvolumes:\n  ollama: {}\n# then: docker exec ollama ollama pull llama3.2\n# app calls http://ollama:11434/api/chat"}', '[{"kind": "config", "path": "scripts/install-ollama.sh", "language": "bash", "description": "Linux/macOS install script: curl https://ollama.com/install.sh | sh — sets up Ollama as a system service"}, {"kind": "config", "path": "docker-compose.yml", "language": "yaml", "description": "Optional Docker Compose configuration with GPU passthrough and persistent model volume for containerized environments"}, {"kind": "config", "path": "llm/Modelfile", "language": "dockerfile", "description": "Modelfile to define system prompt, parameters, and base model for a custom Ollama model variant"}, {"kind": "config", "path": ".env", "language": "dotenv", "description": "Environment variables: OLLAMA_HOST, OLLAMA_KEEP_ALIVE, OLLAMA_NUM_GPU"}]', '{"keepAlive": {"type": "enum", "label": "Keep Alive", "default": "5m", "options": ["0s", "1m", "5m", "15m", "1h", "-1"], "description": "How long to keep a loaded model in VRAM after the last request"}}', '["open-source-llm", "ai-service", "llm-gateway", "backend-service"]', false, NULL, NULL, '2026-08-30 12:07:18.752409+00', '2026-08-30 12:07:23.877005+00', 'Ollama', '#e8e8e8', '''11434'':53C ''allow'':96C ''anyon'':67C ''anyth'':85C ''api'':25B,48C,101C ''applic'':8B ''artifact'':110C ''authent'':51C,81C ''beyond'':54C ''bind'':52C ''box'':124C ''browser'':93C ''call'':99C ''chain'':109C ''compat'':23B ''container'':38B ''cuda/metal/rocm'':43C ''delet'':75C ''deliber'':92C ''deploy'':27B ''docker'':35B,40C ''download'':10B,103C ''driver'':42C ''endpoint'':62C ''environ'':39B ''file'':105C ''front'':77C ''full'':138C ''gpu'':41C ''infer'':61C ''instal'':33B ''intern'':56C ''langchain'':46C ''languag'':16B ''linux'':5B ''litellm'':44C ''local'':18B,126C ''localhost/an'':55C ''log'':137C ''maco'':4B ''manag'':66C ''model'':17B,65C,76C,104C ''multi'':87C ''multi-us'':86C ''nativ'':3B,32B ''network'':57C ''ollama'':1A,2A,90C ''open'':14B,60C,64C ''open-sourc'':13B ''openai'':22B ''openai-compat'':21B ''openwebui'':45C ''origin'':91C,97C ''os'':31B ''os-nat'':30B ''output'':120C ''page'':94C ''pin'':111C ''primari'':26B ''privaci'':129C ''prompt'':118C,139C ''proxi'':83C ''pull'':73C ''reach'':70C ''rememb'':117C ''rest'':24B ''revers'':82C ''serv'':12B ''set'':89C ''share'':142C ''sink'':143C ''sourc'':15B ''stay'':121C ''stori'':28B ''suppli'':108C ''supply-chain'':107C ''support'':36B ''tags/digests'':112C ''treat'':102C ''undo'':134C ''user'':88C ''vet'':115C ''via'':19B ''win'':130C ''window'':7B');
INSERT INTO public.technology_catalog VALUES ('sentry', 'Sentry', NULL, '#362D59', '["monitoring", "external-service"]', '{"purpose": "Error tracking and performance monitoring with releases, tracing, and alerts", "configMode": "external", "provenance": {"notes": "Phase B9 setupInstructions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["@sentry/nextjs", "@sentry/node", "Source maps", "Releases", "Tracing"], "antiPatterns": ["Wrapping everything in try/catch and swallowing errors Sentry would surface", "Running production without release tagging, making regressions untraceable", "Sending PII in breadcrumbs and event extras"], "apiReference": {"areas": {"sdk-setup": {"endpoints": ["Sentry.init({dsn, environment, release, tracesSampleRate}) — the DSN is per-project; environment + release make issues diffable", "Sample deliberately: tracesSampleRate/profilesSampleRate/replaysSessionSampleRate are COST dials, not booleans", "Scrub PII at the SDK (beforeSend / sendDefaultPii=false) — the event leaves your infrastructure", "Capture handled errors with context (Sentry.captureException + setContext/tags) — unhandled-only leaves the interesting failures dark"]}, "alerts-webhooks": {"endpoints": ["Issue alert rules (new issue, regression, frequency spike) → Slack/PagerDuty/webhook targets", "Internal integrations expose a webhook + API token for custom routing; verify the sentry-hook-signature header", "Alert on RATE CHANGES not raw counts — noisy alerts get muted, muted Sentry is no Sentry"]}, "releases-sourcemaps": {"endpoints": ["Create a release per deploy (sentry-cli releases new / the Vite-Next-webpack plugins) and upload source maps bound to release + dist", "Un-symbolicated stack traces are the top wasted-Sentry failure — wire the build plugin, not manual uploads", "Associate commits so suspect-commit + ownership rules route issues to the right humans"]}}, "docsUrl": "https://docs.sentry.io"}, "bestPractices": ["Upload source maps per release so stack traces resolve to source", "Tag events with user id, plan, and feature flags for triage context", "Sample traces in production instead of capturing 100 percent", "Alert on new-issue and regression conditions, not raw event volume", "Scrub sensitive data with beforeSend before events leave the app"], "sdkInitPattern": "import * as Sentry from ''@sentry/node'';\nSentry.init({ dsn: process.env.SENTRY_DSN, tracesSampleRate: 0.1, environment: process.env.NODE_ENV });", "securityGuidance": "Treat DSNs as public but scrub payloads; restrict auth tokens used for source map upload", "setupInstructions": [{"type": "account_setup", "title": "Create a Sentry project and copy its DSN", "required": true, "instructions": "Create a project for the platform in use and copy the DSN from Project Settings → Client Keys. The DSN identifies where events go; treat it as configuration."}, {"type": "environment_variable", "title": "Configure DSN and environment", "required": true, "instructions": "Provide SENTRY_DSN plus environment/release tags via configuration; scrub PII with beforeSend and enable server-side data scrubbing."}, {"type": "environment_variable", "title": "Add a CI auth token for source maps/releases", "required": false, "instructions": "Create an org auth token scoped to release management for CI source-map upload; store it in the CI secret store."}]}', '[{"kind": "config", "path": "sentry.client.config.ts", "priority": "essential"}, {"kind": "config", "path": "sentry.server.config.ts", "priority": "essential"}]', '{"apiAreas": {"type": "multiselect", "label": "Sentry integration areas", "options": ["sdk-setup", "releases-sourcemaps", "alerts-webhooks"], "description": "Which parts of the Sentry integration this component owns — selected areas'' reference is embedded in the build instructions"}, "products": {"type": "multiselect", "label": "Sentry products used", "options": ["error-monitoring", "tracing-performance", "session-replay", "profiling", "cron-monitoring"], "description": "Error monitoring is the core; the rest are opt-in SDK features with their own sample rates and cost"}}', '[{"id": "posthog", "reason": "Error-to-session correlation"}, {"id": "nodejs", "reason": "Server instrumentation"}]', false, NULL, NULL, '2026-08-30 12:07:21.442329+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''0.1'':29C ''alert'':12B ''auth'':41C ''dsn'':25C,27C ''dsns'':34C ''env'':32C ''environ'':30C ''error'':3B ''import'':19C ''map'':16C,46C ''monitor'':7B ''payload'':39C ''perform'':6B ''process.env.node'':31C ''process.env.sentry'':26C ''public'':36C ''releas'':9B,17C ''restrict'':40C ''scrub'':38C ''sentri'':1A,2A,21C ''sentry.init'':24C ''sentry/nextjs'':13C ''sentry/node'':14C,23C ''sourc'':15C,45C ''token'':42C ''trace'':10B,18C ''tracessampler'':28C ''track'':4B ''treat'':33C ''upload'':47C ''use'':43C');
INSERT INTO public.technology_catalog VALUES ('stripe', 'Stripe', NULL, '#6b7280', '["external-service"]', '{"purpose": "Payment processing platform for accepting one-time and recurring payments, managing subscriptions, invoicing, and handling payouts.", "configMode": "external", "provenance": {"notes": "Phase B1 additions (securityGuidance, sdkInitPattern) authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Node.js", "Python", "React", "webhooks"], "antiPatterns": ["Trusting client-side payment confirmation without server verification", "Hardcoding API keys in source", "Ignoring webhook event ordering", "Not implementing retry logic for failed webhooks"], "apiReference": {"areas": {"connect": {"docsUrl": "https://docs.stripe.com/api/accounts", "endpoints": ["`POST /v1/accounts` — create a connected account (type=express)", "`POST /v1/account_links` — onboarding link (refresh_url, return_url)", "Destination charges: create PaymentIntent with transfer_data[destination]=acct_…", "`POST /v1/transfers` — move funds to a connected account (separate charges & transfers)"]}, "checkout": {"docsUrl": "https://docs.stripe.com/api/checkout/sessions", "endpoints": ["`POST /v1/checkout/sessions` — create a hosted session (mode=payment|subscription, line_items, success_url, cancel_url)", "`GET /v1/checkout/sessions/{id}` — retrieve (payment_status, customer)", "`GET /v1/checkout/sessions/{id}/line_items` — purchased items", "`POST /v1/checkout/sessions/{id}/expire` — invalidate an open session"]}, "payments": {"docsUrl": "https://docs.stripe.com/api/payment_intents", "endpoints": ["`POST /v1/payment_intents` — create a PaymentIntent (amount, currency; automatic_payment_methods is ON by default — configure methods in the Dashboard)", "`GET /v1/payment_intents/{id}` — retrieve status (requires_action, processing, succeeded)", "`POST /v1/payment_intents/{id}/confirm` — confirm with a payment method (or confirm=true at creation)", "`POST /v1/payment_intents/{id}/capture` — capture a manual-capture intent", "`POST /v1/refunds` — refund (payment_intent, optional amount for partial)"]}, "webhooks": {"docsUrl": "https://docs.stripe.com/webhooks", "endpoints": ["`POST /v1/webhook_endpoints` — register endpoint (url, enabled_events[])", "Verify signatures: Stripe-Signature header + webhooks.constructEvent(payload, sig, secret) — raw body required", "Key events: checkout.session.completed, payment_intent.succeeded, invoice.paid, invoice.payment_failed, customer.subscription.updated, customer.subscription.deleted", "Return 2xx fast; process async — Stripe retries non-2xx with backoff"]}, "customers": {"docsUrl": "https://docs.stripe.com/api/customers", "endpoints": ["`POST /v1/customers` — create (email, metadata: map to your user id)", "`GET /v1/customers/{id}` — retrieve", "`POST /v1/customers/{id}` — update (default payment method, address)", "`GET /v1/customers/search` — query syntax, e.g. metadata[''userId'']:''…''"]}, "invoicing": {"docsUrl": "https://docs.stripe.com/api/invoices", "endpoints": ["`POST /v1/invoices` — create a draft invoice for a customer", "`POST /v1/invoiceitems` — add line items to the next/target invoice", "`POST /v1/invoices/{id}/finalize` — finalize a draft for payment", "`POST /v1/invoices/{id}/send` — email the invoice", "`GET /v1/invoices/upcoming` — preview the next invoice (proration checks)"]}, "subscriptions": {"docsUrl": "https://docs.stripe.com/api/subscriptions", "endpoints": ["`POST /v1/subscriptions` — create (customer, items[0][price]; payment_behavior=default_incomplete for SCA)", "`GET /v1/subscriptions/{id}` — retrieve (status, current_period_end)", "`POST /v1/subscriptions/{id}` — update plan/quantity (proration_behavior)", "`DELETE /v1/subscriptions/{id}` — cancel (or cancel_at_period_end=true via update)", "`POST /v1/billing_portal/sessions` — customer self-service portal link", "billing_mode=flexible on new subscriptions/Checkout Sessions for predictable proration/invoicing behavior — requires API version 2025-06-30.basil or later", "Entitlements API — define features once, read a customer''s active entitlements instead of hand-mapping prices to feature flags"]}}, "docsUrl": "https://docs.stripe.com/api"}, "bestPractices": ["Always verify webhook signatures", "Use idempotency keys for API calls", "Handle async payment confirmations via webhooks", "Use Stripe CLI for local webhook testing", "Store only Stripe customer/subscription IDs, never card details"], "sdkInitPattern": "import Stripe from ''stripe'';\r\n\r\n// Secret key lives server-side ONLY; the publishable key is the only client-safe key.\r\nconst stripe = new Stripe(process.env.STRIPE_SECRET_KEY);", "securityGuidance": "Secret and restricted keys never reach the client — the publishable key is the only browser-safe credential. Verify every webhook with stripe.webhooks.constructEvent and the endpoint''s signing secret before trusting its payload. Use idempotency keys on all mutating requests so retries never double-charge. Keep card data out of your systems entirely: Stripe-hosted Checkout or Elements keeps you in SAQ-A scope — never log or store PANs. Prefer restricted keys scoped to exactly the resources an integration touches.", "setupInstructions": [{"url": "https://dashboard.stripe.com/register", "type": "account_setup", "title": "Create Stripe Account", "required": true, "instructions": "Sign up at stripe.com. Complete account activation by providing business details and a bank account for payouts. Use test mode for development."}, {"url": "https://dashboard.stripe.com/apikeys", "type": "environment_variable", "title": "Get API Keys", "required": true, "instructions": "In Dashboard > Developers > API Keys, copy the Publishable Key (client-side) and Secret Key (server-side). Use test keys (prefixed with pk_test_ and sk_test_) during development."}, {"type": "webhook_config", "title": "Register Webhook Endpoint", "required": true, "instructions": "In Dashboard > Developers > Webhooks > Add Endpoint. Enter your server URL and select events to listen for (checkout.session.completed, invoice.paid, customer.subscription.updated, etc.). Note the webhook signing secret."}, {"type": "toolchain_install", "title": "Test with Stripe CLI", "commands": ["brew install stripe/stripe-cli/stripe", "stripe login", "stripe listen --forward-to localhost:3000/api/webhooks/stripe"], "required": false, "instructions": "Install the Stripe CLI for local webhook testing. Forward events to your local server during development."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export STRIPE_PUBLISHABLE_KEY=pk_test_...", "export STRIPE_SECRET_KEY=sk_test_...", "export STRIPE_WEBHOOK_SECRET=whsec_..."], "required": true, "instructions": "Add Stripe credentials to your application environment."}]}', '[]', '{"mode": {"type": "enum", "label": "API mode", "default": "test", "options": ["test", "live"], "description": "Key mode this environment targets (sk_test_* / sk_live_*)"}, "apiAreas": {"type": "multiselect", "label": "Stripe API areas used", "options": ["payments", "checkout", "subscriptions", "invoicing", "customers", "webhooks", "connect"], "description": "Which parts of the Stripe API this component calls — selected areas'' endpoint reference is embedded in the build instructions"}}', '[]', false, NULL, NULL, '2026-05-18 02:35:27.802569+00', '2026-08-30 12:07:23.877005+00', 'Stripe', NULL, '''accept'':7B ''browser'':67C ''browser-saf'':66C ''card'':99C ''charg'':97C ''checkout'':109C ''client'':42C,59C ''client-saf'':41C ''const'':45C ''credenti'':69C ''data'':100C ''doubl'':96C ''double-charg'':95C ''element'':111C ''endpoint'':77C ''entir'':105C ''everi'':71C ''exact'':129C ''handl'':18B ''host'':108C ''idempot'':86C ''import'':24C ''integr'':133C ''invoic'':16B ''keep'':98C,112C ''key'':29C,37C,44C,51C,55C,62C,87C,126C ''live'':30C ''log'':120C ''manag'':14B ''mutat'':90C ''never'':56C,94C,119C ''new'':47C ''node.js'':20C ''one'':9B ''one-tim'':8B ''pan'':123C ''payload'':84C ''payment'':3B,13B ''payout'':19B ''platform'':5B ''prefer'':124C ''process'':4B ''process.env.stripe'':49C ''publish'':36C,61C ''python'':21C ''reach'':57C ''react'':22C ''recur'':12B ''request'':91C ''resourc'':131C ''restrict'':54C,125C ''retri'':93C ''safe'':43C,68C ''saq'':116C ''saq-a'':115C ''scope'':118C,127C ''secret'':28C,50C,52C,80C ''server'':32C ''server-sid'':31C ''side'':33C ''sign'':79C ''store'':122C ''stripe'':1A,2A,25C,27C,46C,48C,107C ''stripe-host'':106C ''stripe.webhooks.constructevent'':74C ''subscript'':15B ''system'':104C ''time'':10B ''touch'':134C ''trust'':82C ''use'':85C ''verifi'':70C ''webhook'':23C,72C');
INSERT INTO public.technology_catalog VALUES ('aws-sns', 'AWS SNS', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-sns.png', '#FF4F8B', '["event-stream", "message-broker"]', '{"purpose": "AWS-native pub/sub messaging service for fan-out notifications, A2A and A2P messaging. Best for decoupling microservices via topic-based fan-out, sending push notifications, and triggering multiple SQS queues or Lambda functions from a single event. Use SNS+SQS fan-out pattern for reliable multi-subscriber delivery. Not suited for ordered message processing (use SQS FIFO) or event replay (use Kinesis).", "configMode": "declarative", "provenance": {"notes": "Phase B4 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using SNS for ordered processing without FIFO topics", "Relying on SNS for durable event replay (use Kinesis or EventBridge)", "Sending large payloads directly (use S3 references for >256KB)", "Not setting up DLQs on subscriptions", "Using SNS when simple point-to-point queuing suffices (use SQS directly)"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/sns/"}, "bestPractices": ["Use SNS+SQS fan-out pattern for reliable multi-subscriber delivery", "Enable message filtering policies to reduce unnecessary processing", "Use FIFO topics when message ordering and deduplication matter", "Set up dead-letter queues on subscriptions for failed deliveries", "Use message attributes for metadata instead of embedding in body"], "sdkInitPattern": "import { SNSClient, PublishCommand } from ''@aws-sdk/client-sns'';\r\n\r\nconst sns = new SNSClient({});\r\nawait sns.send(new PublishCommand({\r\n  TopicArn: process.env.ORDERS_TOPIC_ARN,\r\n  Message: JSON.stringify({ orderId }),\r\n}));", "securityGuidance": "Topic access policies name specific principals — a \"*\" principal on a topic is an open publish/subscribe door. HTTPS subscribers must VERIFY the message signature (the signing certificate flow) before trusting a delivery; confirmation and notification requests are forgeable otherwise. Encrypt topics with KMS where payloads are sensitive, and give every delivery path a dead-letter queue so failures are visible instead of silent."}', '[{"kind": "source", "path": "src/messaging/sns-client.ts", "priority": "essential", "description": "SNS publish and topic management client"}, {"kind": "config", "path": "src/messaging/sns-topics.ts", "priority": "recommended", "description": "Topic ARN definitions and subscription config"}, {"kind": "config", "path": "terraform/sns.tf", "priority": "recommended", "description": "SNS topic and subscription infrastructure"}]', '{"topicType": {"enum": ["standard", "fifo"], "type": "string", "label": "Topic Type", "default": "standard"}, "encryption": {"type": "boolean", "label": "Server-Side Encryption", "default": true}, "messageFiltering": {"type": "boolean", "label": "Message Filtering", "default": false}}', '["message-broker", "serverless-function", "worker"]', false, NULL, NULL, '2026-03-04 00:48:04.051147+00', '2026-08-30 12:07:23.877005+00', NULL, '#C0125F', '''/client-sns'':80C ''a2a'':16B ''a2p'':18B ''access'':97C ''arn'':92C ''aw'':1A,3A,6B,78C ''await'':85C ''aws-nat'':5B ''aws-sdk'':77C ''base'':27B ''best'':20B ''certif'':121C ''confirm'':127C ''const'':81C ''dead'':149C ''dead-lett'':148C ''decoupl'':22B ''deliveri'':58B,126C,145C ''door'':111C ''encrypt'':134C ''event'':45B,69B ''everi'':144C ''failur'':153C ''fan'':13B,29B,50B ''fan-out'':12B,28B,49B ''fifo'':67B ''flow'':122C ''forgeabl'':132C ''function'':41B ''give'':143C ''https'':112C ''import'':73C ''instead'':156C ''json.stringify'':94C ''kinesi'':72B ''kms'':137C ''lambda'':40B ''letter'':150C ''messag'':9B,19B,63B,93C,117C ''microservic'':23B ''multi'':56B ''multi-subscrib'':55B ''multipl'':36B ''must'':114C ''name'':99C ''nativ'':7B ''new'':83C,87C ''notif'':15B,33B,129C ''open'':109C ''order'':62B ''orderid'':95C ''otherwis'':133C ''path'':146C ''pattern'':52B ''payload'':139C ''polici'':98C ''princip'':101C,103C ''process'':64B ''process.env.orders'':90C ''pub/sub'':8B ''publish/subscribe'':110C ''publishcommand'':75C,88C ''push'':32B ''queue'':38B,151C ''reliabl'':54B ''replay'':70B ''request'':130C ''sdk'':79C ''send'':31B ''sensit'':141C ''servic'':10B ''sign'':120C ''signatur'':118C ''silent'':158C ''singl'':44B ''sns'':2A,4A,47B,82C ''sns.send'':86C ''snsclient'':74C,84C ''specif'':100C ''sqs'':37B,48B,66B ''subscrib'':57B,113C ''suit'':60B ''topic'':26B,91C,96C,106C,135C ''topic-bas'':25B ''topicarn'':89C ''trigger'':35B ''trust'':124C ''use'':46B,65B,71B ''verifi'':115C ''via'':24B ''visibl'':155C');
INSERT INTO public.technology_catalog VALUES ('sqlite', 'SQLite', NULL, '#003B57', '["database"]', '{"purpose": "Embedded, zero-ops SQL database — a file, not a server. The honest default for single-node apps, desktop/mobile local storage, CLIs and edge deployments; in WAL mode it carries substantial production write loads (the 2020s server-side-SQLite wave: Litestream replication, LiteFS, libSQL/Turso). The boundary is real: one writer node — when the architecture needs multiple app servers writing, that is the Postgres fork in the road.", "configMode": "declarative", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["WAL mode", "Litestream", "better-sqlite3 / rusqlite / sqlite3 stdlib", "libSQL/Turso (managed lane)", "PRAGMA tuning"], "antiPatterns": ["Multiple processes/containers writing the same database file over a network filesystem — the classic corruption story", "Treating it as a toy: modern SQLite in WAL mode outperforms a mis-tuned Postgres for single-node read-heavy loads", "Storing the file on ephemeral container storage with no replication — the deploy wipes the database", "Choosing it for multi-writer, multi-node architectures — that is the boundary, respect it"], "apiReference": {"docsUrl": "https://sqlite.org/docs.html"}, "bestPractices": ["WAL mode + busy_timeout on every connection — the two pragmas that make SQLite production-grade", "One write connection, many read connections — serialize writes in the app instead of colliding on locks", "Litestream (or LiteFS) for continuous replication to object storage — backup is a stream, not a cron job", "Foreign keys are OFF by default — PRAGMA foreign_keys=ON at connection open", "Migrations are still migrations — version the schema even though it is a file"], "sdkInitPattern": "import Database from ''better-sqlite3'';\n\nconst db = new Database(''app.db'');\ndb.pragma(''journal_mode = WAL'');\nconst orders = db.prepare(''SELECT * FROM orders WHERE owner_id = ?'').all(userId);", "securityGuidance": "The database is a file — filesystem permissions ARE the access control: owned by the service user, mode 600, outside any web-served directory (a downloadable .db is total disclosure). Always prepared statements; SQLite is just as injectable as any SQL engine. One writer at a time is the concurrency model (WAL helps readers), backups are file copies taken via the backup API not cp-under-write, and encrypt at the filesystem/volume layer if the data warrants it — stock SQLite files are plaintext."}', '[{"kind": "config", "path": "data/app.db"}, {"kind": "source", "path": "migrations/"}]', '{"consumer": {"type": "enum", "label": "Used as", "default": "app-primary-db", "options": ["app-primary-db", "local-cache-or-state", "desktop-mobile-storage"]}, "journalMode": {"type": "enum", "label": "Journal mode", "default": "wal", "options": ["wal", "rollback-legacy"], "description": "WAL is the production answer — concurrent readers during writes"}, "replication": {"type": "enum", "label": "Replication/backup", "default": "litestream", "options": ["litestream", "litefs", "file-copy-only"]}}', '[]', false, NULL, NULL, '2026-08-30 12:07:22.147795+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''2020s'':39B ''600'':129C ''access'':121C ''alway'':142C ''api'':174C ''app'':21B,61B ''app.db'':96C ''architectur'':58B ''backup'':166C,173C ''better'':76C,90C ''better-sqlite3'':75C,89C ''boundari'':50B ''carri'':33B ''clis'':25B ''concurr'':161C ''const'':92C,101C ''control'':122C ''copi'':169C ''cp'':177C ''cp-under-writ'':176C ''data'':188C ''databas'':8B,87C,95C,113C ''db'':93C,138C ''db.pragma'':97C ''db.prepare'':103C ''default'':16B ''deploy'':28B ''desktop/mobile'':22B ''directori'':135C ''disclosur'':141C ''download'':137C ''edg'':27B ''embed'':3B ''encrypt'':181C ''engin'':153C ''file'':10B,116C,168C,193C ''filesystem'':117C ''filesystem/volume'':184C ''fork'':68B ''help'':164C ''honest'':15B ''id'':109C ''import'':86C ''inject'':149C ''journal'':98C ''lane'':83C ''layer'':185C ''libsql/turso'':48B,81C ''litef'':47B ''litestream'':45B,74C ''load'':37B ''local'':23B ''manag'':82C ''mode'':31B,73C,99C,128C ''model'':162C ''multipl'':60B ''need'':59B ''new'':94C ''node'':20B,55B ''one'':53B,154C ''op'':6B ''order'':102C,106C ''outsid'':130C ''own'':123C ''owner'':108C ''permiss'':118C ''plaintext'':195C ''postgr'':67B ''pragma'':84C ''prepar'':143C ''product'':35B ''reader'':165C ''real'':52B ''replic'':46B ''road'':71B ''rusqlit'':78C ''select'':104C ''serv'':134C ''server'':13B,41B,62B ''server-side-sqlit'':40B ''servic'':126C ''side'':42B ''singl'':19B ''single-nod'':18B ''sql'':7B,152C ''sqlite'':1A,2A,43B,145C,192C ''sqlite3'':77C,79C,91C ''statement'':144C ''stdlib'':80C ''stock'':191C ''storag'':24B ''substanti'':34B ''taken'':170C ''time'':158C ''total'':140C ''tune'':85C ''user'':127C ''userid'':111C ''via'':171C ''wal'':30B,72C,100C,163C ''warrant'':189C ''wave'':44B ''web'':133C ''web-serv'':132C ''write'':36B,63B,179C ''writer'':54B,155C ''zero'':5B ''zero-op'':4B');
INSERT INTO public.technology_catalog VALUES ('azure-kubernetes-service', 'Azure Kubernetes Service', NULL, '#0078D4', '["k8s-cluster"]', '{"purpose": "Azure Kubernetes Service is Azure''s managed Kubernetes platform for running containerized applications with cluster orchestration, autoscaling, rolling deployments, and ecosystem tooling around standard Kubernetes APIs. Use AKS for microservices platforms, internal developer platforms, multi-service environments, and workloads that need operators, ingress control, service meshes, or custom runtime composition. Choose AKS over App Service when you need container orchestration flexibility and over Azure Functions when services are long-running or require pod-level control. Do not use AKS for simple single-service applications where App Service or Functions provide a lower-ops and faster path to production.", "configMode": "declarative", "provenance": {"notes": "Phase B5 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Azure Kubernetes Service", "Azure Container Registry", "Azure Monitor", "Azure Application Gateway", "Azure Key Vault", "Helm", "KEDA", "Azure CNI"], "antiPatterns": ["Running AKS for a single simple web app that could use App Service", "Deploying workloads without requests and limits and causing unstable scheduling", "Using the default node pool for every workload class, environment, and system component", "Granting overly broad cluster-admin permissions to application teams", "Ignoring Kubernetes version upgrades and node image maintenance", "Treating AKS as a lift-and-shift VM replacement without platform standards or guardrails"], "apiReference": {"docsUrl": "https://learn.microsoft.com/azure/aks/"}, "bestPractices": ["Use separate node pools for system components and application workloads", "Integrate with Azure Container Registry using managed identities and least-privilege pulls", "Define resource requests and limits for every deployment to improve scheduling stability", "Use Helm, GitOps, or other declarative delivery patterns for repeatable releases", "Enable autoscaling at both cluster and workload layers and monitor node pool cost", "Restrict exposure with ingress controls, network policies, and namespace isolation", "Store secrets outside the cluster and inject them through secure secret management patterns"], "securityGuidance": "Workload identity (OIDC federation) is how pods reach Azure services — never mount service-principal secrets into pods. Use Entra-integrated RBAC for the control plane, disable local accounts, and restrict API-server access (private cluster or authorized IP ranges) for production. Pull images from a private ACR via the cluster''s managed identity, and apply Kubernetes RBAC least-privilege per namespace on top of the Azure layer.", "configurationTemplate": "az aks create --resource-group my-rg --name my-cluster \\\r\n  --enable-managed-identity --enable-oidc-issuer --enable-workload-identity \\\r\n  --enable-aad --enable-azure-rbac --node-count 3\r\naz aks get-credentials --resource-group my-rg --name my-cluster"}', '[{"kind": "config", "path": "k8s/cluster-values.yaml", "priority": "essential", "description": "Cluster-wide AKS configuration values and deployment parameters"}, {"kind": "schema", "path": "k8s/deployments/", "priority": "essential", "description": "Kubernetes deployment manifests for workloads targeting AKS"}, {"kind": "config", "path": "helm/Chart.yaml", "priority": "recommended", "description": "Helm chart metadata for AKS application packaging"}, {"kind": "config", "path": "infra/aks.bicep", "priority": "recommended", "description": "Infrastructure-as-code definition for AKS cluster provisioning"}]', '{"networkPlugin": {"type": "enum", "label": "Network Plugin", "default": "azure-cni", "options": ["azure-cni", "kubenet"], "description": "Cluster networking mode"}, "privateCluster": {"type": "boolean", "label": "Private Cluster", "default": false, "description": "Restrict Kubernetes API access to private networking"}, "ingressController": {"type": "enum", "label": "Ingress Controller", "default": "application-gateway", "options": ["application-gateway", "nginx", "none"], "description": "Primary ingress strategy for the cluster"}}', '["docker-container", "load-balancer", "monitoring", "object-storage", "database"]', false, NULL, NULL, '2026-03-14 15:29:57.538666+00', '2026-08-30 12:07:23.877005+00', 'AKS', '#005FAA', '''access'':163C ''account'':157C ''acr'':177C ''ak'':34B,59B,88B ''api'':32B,161C ''api-serv'':160C ''app'':61B,96B ''appli'':185C ''applic'':19B,94B,119C ''around'':29B ''author'':167C ''autosc'':23B ''azur'':1A,4A,7B,11B,71B,110C,113C,116C,118C,121C,126C,136C,197C ''choos'':58B ''cluster'':21B,165C,180C ''cni'':127C ''composit'':57B ''contain'':66B,114C ''container'':18B ''control'':51B,84B,153C ''custom'':55B ''deploy'':25B ''develop'':39B ''disabl'':155C ''ecosystem'':27B ''entra'':148C ''entra-integr'':147C ''environ'':44B ''faster'':106B ''feder'':131C ''flexibl'':68B ''function'':72B,99B ''gateway'':120C ''helm'':124C ''ident'':129C,183C ''imag'':173C ''ingress'':50B ''integr'':149C ''intern'':38B ''ip'':168C ''keda'':125C ''key'':122C ''kubernet'':2A,5A,8B,14B,31B,111C,186C ''layer'':198C ''least'':189C ''least-privileg'':188C ''level'':83B ''local'':156C ''long'':77B ''long-run'':76B ''lower'':103B ''lower-op'':102B ''manag'':13B,182C ''mesh'':53B ''microservic'':36B ''monitor'':117C ''mount'':139C ''multi'':42B ''multi-servic'':41B ''namespac'':192C ''need'':48B,65B ''never'':138C ''oidc'':130C ''op'':104B ''oper'':49B ''orchestr'':22B,67B ''path'':107B ''per'':191C ''plane'':154C ''platform'':15B,37B,40B ''pod'':82B,134C,145C ''pod-level'':81B ''princip'':142C ''privat'':164C,176C ''privileg'':190C ''product'':109B,171C ''provid'':100B ''pull'':172C ''rang'':169C ''rbac'':150C,187C ''reach'':135C ''registri'':115C ''requir'':80B ''restrict'':159C ''roll'':24B ''run'':17B,78B ''runtim'':56B ''secret'':143C ''server'':162C ''servic'':3A,6A,9B,43B,52B,62B,74B,93B,97B,112C,137C,141C ''service-princip'':140C ''simpl'':90B ''singl'':92B ''single-servic'':91B ''standard'':30B ''tool'':28B ''top'':194C ''use'':33B,87B,146C ''vault'':123C ''via'':178C ''workload'':46B,128C');
INSERT INTO public.technology_catalog VALUES ('aws-dynamodb', 'AWS DynamoDB', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/dynamodb.png', '#4053d6', '["database"]', '{"purpose": "AWS-native serverless NoSQL database delivering single-digit millisecond latency at any scale. Best for AWS-centric architectures with predictable access patterns, serverless billing, and tight Lambda/EventBridge integration. Ideal for session stores, shopping carts, IoT telemetry, and gaming leaderboards. Not suited for complex relational queries or ad-hoc analytics.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS DynamoDB", "DynamoDB Streams", "DAX", "PartiQL", "AWS SDK", "Single-Table Design"], "antiPatterns": ["Hot partition keys causing throttling", "Scanning instead of querying", "Creating a table per entity (relational thinking)", "Choosing DynamoDB when complex joins or ad-hoc queries are required"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/dynamodb/"}, "bestPractices": ["Design partition keys for even data distribution", "Use single-table design patterns for related entities", "Implement GSIs strategically (max 20 per table)", "Use DynamoDB Streams for change data capture", "Enable point-in-time recovery", "Use on-demand billing for unpredictable workloads"], "sdkInitPattern": "import { DynamoDBClient } from ''@aws-sdk/client-dynamodb'';\nimport { DynamoDBDocumentClient, QueryCommand } from ''@aws-sdk/lib-dynamodb'';\n\nconst doc = DynamoDBDocumentClient.from(new DynamoDBClient({}));\nconst { Items } = await doc.send(new QueryCommand({\n  TableName: ''orders'',\n  KeyConditionExpression: ''pk = :pk'',\n  ExpressionAttributeValues: { '':pk'': `USER#${userId}` },\n}));", "securityGuidance": "Key design is access control''s substrate: prefix partition keys by owner (USER#id) and Query, never Scan, in request paths — a Scan bug on a multi-tenant table is a cross-tenant read. IAM can enforce it: dynamodb:LeadingKeys conditions bind a role to its own partitions. Always ExpressionAttributeValues (no string-built expressions), enable PITR on tables you cannot lose, and deletion protection on production tables."}', '[{"kind": "config", "path": "infra/aws/dynamodb.tf"}]', '{"streams": {"type": "boolean", "label": "DynamoDB Streams", "default": false, "description": "Change events for Lambda/Kinesis consumers"}, "tableClass": {"type": "enum", "label": "Table class", "default": "STANDARD", "options": ["STANDARD", "STANDARD_INFREQUENT_ACCESS"], "description": "IA trades storage cost for higher request cost"}, "ttlEnabled": {"type": "boolean", "label": "TTL", "default": false, "description": "Auto-expire items via a timestamp attribute"}, "billingMode": {"type": "enum", "label": "Billing mode", "default": "PAY_PER_REQUEST", "options": ["PAY_PER_REQUEST", "PROVISIONED"], "description": "On-demand per-request pricing vs provisioned capacity units"}, "pointInTimeRecovery": {"type": "boolean", "label": "Point-in-time recovery", "default": true, "description": "Continuous backup (35-day window)"}}', '["backend-service", "serverless-function"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#3344B5', '''/client-dynamodb'':76C ''/lib-dynamodb'':84C ''access'':28B,108C ''ad'':55B ''ad-hoc'':54B ''alway'':155C ''analyt'':57B ''architectur'':25B ''aw'':1A,3A,6B,23B,58C,64C,74C,82C ''await'':92C ''aws-centr'':22B ''aws-nat'':5B ''aws-sdk'':73C,81C ''best'':20B ''bill'':31B ''bind'':148C ''bug'':128C ''built'':160C ''cannot'':167C ''cart'':41B ''centric'':24B ''complex'':50B ''condit'':147C ''const'':85C,90C ''control'':109C ''cross'':138C ''cross-ten'':137C ''databas'':10B ''dax'':62C ''delet'':170C ''deliv'':11B ''design'':69C,106C ''digit'':14B ''doc'':86C ''doc.send'':93C ''dynamodb'':2A,4A,59C,60C,145C ''dynamodbcli'':71C,89C ''dynamodbdocumentcli'':78C ''dynamodbdocumentclient.from'':87C ''enabl'':162C ''enforc'':143C ''express'':161C ''expressionattributevalu'':101C,156C ''game'':45B ''hoc'':56B ''iam'':141C ''id'':118C ''ideal'':36B ''import'':70C,77C ''integr'':35B ''iot'':42B ''item'':91C ''key'':105C,114C ''keyconditionexpress'':98C ''lambda/eventbridge'':34B ''latenc'':16B ''leaderboard'':46B ''leadingkey'':146C ''lose'':168C ''millisecond'':15B ''multi'':132C ''multi-ten'':131C ''nativ'':7B ''never'':121C ''new'':88C,94C ''nosql'':9B ''order'':97C ''owner'':116C ''partiql'':63C ''partit'':113C,154C ''path'':125C ''pattern'':29B ''pitr'':163C ''pk'':99C,100C,102C ''predict'':27B ''prefix'':112C ''product'':173C ''protect'':171C ''queri'':52B,120C ''querycommand'':79C,95C ''read'':140C ''relat'':51B ''request'':124C ''role'':150C ''scale'':19B ''scan'':122C,127C ''sdk'':65C,75C,83C ''serverless'':8B,30B ''session'':38B ''shop'':40B ''singl'':13B,67C ''single-digit'':12B ''single-t'':66C ''store'':39B ''stream'':61C ''string'':159C ''string-built'':158C ''substrat'':111C ''suit'':48B ''tabl'':68C,134C,165C,174C ''tablenam'':96C ''telemetri'':43B ''tenant'':133C,139C ''tight'':33B ''user'':103C,117C ''userid'':104C');
INSERT INTO public.technology_catalog VALUES ('aws-ec2', 'AWS EC2', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/ec2.png', '#ff9900', '["virtual-machine"]', '{"purpose": "AWS Elastic Compute Cloud (EC2) instance providing resizable compute capacity. Use when the architecture requires explicit VM-level visibility for workloads that need full OS control, GPU access, or specific instance types.", "configMode": "declarative", "provenance": {"notes": "Schema kept to stable API surface (instance families, AMI families); full live verify rides 4a-3. Stray id kept; N9b owns the aws-ec2 rename.", "method": "model-knowledge", "sources": ["https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-types.html"], "verifiedAt": "2026-07-27"}, "typicalTech": ["Amazon Linux 2", "Ubuntu", "Docker on EC2", "EBS volumes", "Elastic IP", "Auto Scaling Groups", "Application Load Balancer"], "antiPatterns": ["SSH-ing into production instances instead of using immutable AMI deployments", "Using access keys on instances instead of IAM instance profiles", "Running a single instance without auto-scaling or health checks", "Using IMDSv1 which is vulnerable to SSRF credential theft", "Not encrypting EBS volumes containing sensitive data"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/ec2/"}, "bestPractices": ["Use Auto Scaling Groups for high availability", "Place instances in private subnets behind ALB", "Use IAM instance profiles instead of access keys", "Enable detailed monitoring", "Use EBS-optimized instance types", "Tag all resources for cost allocation"], "sdkInitPattern": "aws ec2 run-instances --image-id ami-0abcdef1234567890 --instance-type t3.medium --key-name my-key --subnet-id subnet-xxx --security-group-ids sg-xxx --iam-instance-profile Name=my-profile", "securityGuidance": "Never use access keys on instances -- always use IAM instance profiles. Place instances in private subnets and use SSM Session Manager instead of SSH bastion hosts. Apply security groups with least-privilege inbound rules. Enable IMDSv2 (require token-based metadata) to prevent SSRF attacks. Use encrypted EBS volumes. Patch instances via AWS Systems Manager Patch Manager. Disable password-based SSH login.", "commonApiPatterns": [{"name": "Auto Scaling Group", "description": "Create ASG with launch template across multiple AZs behind a target group", "codeTemplate": "aws autoscaling create-auto-scaling-group --auto-scaling-group-name my-asg --launch-template LaunchTemplateId=lt-xxx,Version=$Latest --min-size 2 --max-size 10 --desired-capacity 2 --vpc-zone-identifier \"subnet-a,subnet-b\" --target-group-arns arn:aws:elasticloadbalancing:..."}, {"name": "Launch Template", "description": "Define reusable instance configuration with launch template", "codeTemplate": "aws ec2 create-launch-template --launch-template-name my-lt --launch-template-data ''{\"ImageId\":\"ami-xxx\",\"InstanceType\":\"t3.medium\",\"IamInstanceProfile\":{\"Name\":\"my-profile\"},\"SecurityGroupIds\":[\"sg-xxx\"],\"UserData\":\"...\"}''"}, {"name": "SSM Session", "description": "Connect to instance via Session Manager without SSH keys", "codeTemplate": "aws ssm start-session --target i-xxx"}], "integrationPatterns": ["Application Load Balancer for HTTP/HTTPS traffic distribution", "Auto Scaling Groups for elasticity and high availability", "Systems Manager for patching, session management, and automation", "CloudWatch agent for custom metrics and log collection", "EBS snapshots and AMI pipeline for backup and recovery"], "configurationTemplate": "resource \"aws_launch_template\" \"app\" {\\n  name_prefix   = \"app-\"\\n  image_id      = data.aws_ami.latest.id\\n  instance_type = var.instance_type\\n  iam_instance_profile {\\n    name = aws_iam_instance_profile.app.name\\n  }\\n  vpc_security_group_ids = [aws_security_group.app.id]\\n  user_data = base64encode(templatefile(\"userdata.sh\", {}))\\n}\\nresource \"aws_autoscaling_group\" \"app\" {\\n  min_size         = 2\\n  max_size         = 10\\n  desired_capacity = 2\\n  launch_template {\\n    id      = aws_launch_template.app.id\\n    version = \"$Latest\"\\n  }\\n  vpc_zone_identifier = module.vpc.private_subnets\\n  target_group_arns   = [aws_lb_target_group.app.arn]\\n}"}', '[{"kind": "config", "path": "infra/aws/ec2.tf"}, {"kind": "source", "path": "scripts/user-data.sh"}]', '{"os": {"type": "enum", "label": "Operating system", "default": "amazon-linux-2023", "options": ["amazon-linux-2023", "ubuntu-24.04", "ubuntu-22.04", "debian-12", "windows-server-2022"], "description": "AMI family"}, "spot": {"type": "boolean", "label": "Spot instances", "default": false, "description": "Deeply discounted but interruptible — fault-tolerant workloads only"}, "ebsGb": {"type": "number", "label": "Root EBS volume (GB)", "default": 30}, "publicIp": {"type": "boolean", "label": "Public IP", "default": false, "description": "Prefer private subnets + load balancer / SSM Session Manager access"}, "autoScaling": {"type": "boolean", "label": "Auto Scaling group", "default": false, "description": "Instances managed by an ASG (launch template + scaling policies) rather than standing alone"}, "instanceType": {"type": "string", "label": "Instance type", "default": "t4g.small", "description": "e.g. t4g.small, m7g.large — Graviton (…g) families are cheaper for most workloads"}}', '["load-balancer", "database", "cache", "message-broker", "backend-service"]', false, NULL, NULL, '2026-02-10 22:05:39.905006+00', '2026-08-30 12:07:24.229622+00', NULL, '#CC7A00', '''0abcdef1234567890'':65C ''2'':40C ''access'':33B,99C ''alway'':103C ''amazon'':38C ''ami'':64C ''ami-0abcdef1234567890'':63C ''appli'':123C ''applic'':52C ''architectur'':18B ''attack'':142C ''auto'':49C ''aw'':1A,3A,5B,55C,150C ''balanc'':54C ''base'':137C,158C ''bastion'':121C ''capac'':14B ''cloud'':8B ''comput'':7B,13B ''control'':31B ''disabl'':155C ''docker'':42C ''eb'':45C,145C ''ec2'':2A,4A,9B,44C,56C ''elast'':6B,47C ''enabl'':132C ''encrypt'':144C ''explicit'':20B ''full'':29B ''gpu'':32B ''group'':51C,84C,125C ''host'':122C ''iam'':90C,105C ''iam-instance-profil'':89C ''id'':62C,78C,85C ''imag'':61C ''image-id'':60C ''imdsv2'':133C ''inbound'':130C ''instanc'':10B,36B,59C,67C,91C,102C,106C,109C,148C ''instance-typ'':66C ''instead'':118C ''ip'':48C ''key'':71C,75C,100C ''key-nam'':70C ''least'':128C ''least-privileg'':127C ''level'':23B ''linux'':39C ''load'':53C ''login'':160C ''manag'':117C,152C,154C ''metadata'':138C ''my-key'':73C ''my-profil'':94C ''name'':72C,93C ''need'':28B ''never'':97C ''os'':30B ''password'':157C ''password-bas'':156C ''patch'':147C,153C ''place'':108C ''prevent'':140C ''privat'':111C ''privileg'':129C ''profil'':92C,96C,107C ''provid'':11B ''requir'':19B,134C ''resiz'':12B ''rule'':131C ''run'':58C ''run-inst'':57C ''scale'':50C ''secur'':83C,124C ''security-group-id'':82C ''session'':116C ''sg'':87C ''sg-xxx'':86C ''specif'':35B ''ssh'':120C,159C ''ssm'':115C ''ssrf'':141C ''subnet'':77C,80C,112C ''subnet-id'':76C ''subnet-xxx'':79C ''system'':151C ''t3.medium'':69C ''token'':136C ''token-bas'':135C ''type'':37B,68C ''ubuntu'':41C ''use'':15B,98C,104C,114C,143C ''via'':149C ''visibl'':24B ''vm'':22B ''vm-level'':21B ''volum'':46C,146C ''workload'':26B ''xxx'':81C,88C');
INSERT INTO public.technology_catalog VALUES ('aws-sqs', 'AWS SQS', NULL, '#6b7280', '["queue"]', '{"purpose": "Fully managed message queuing service for decoupling distributed systems. Supports standard (best-effort ordering) and FIFO (exactly-once processing) queue types.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS SDK", "Node.js", "Python", "Lambda triggers"], "antiPatterns": ["Using SQS for real-time communication", "Setting visibility timeout shorter than processing time", "Not handling duplicate messages in standard queues", "Ignoring dead-letter queue messages"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/sqs/"}, "bestPractices": ["Use FIFO queues when message ordering matters", "Configure dead-letter queues for failed messages", "Set appropriate visibility timeout based on processing time", "Use long polling to reduce empty receives and cost", "Batch send/receive/delete operations for throughput"], "sdkInitPattern": "import { SQSClient, SendMessageCommand, ReceiveMessageCommand } from ''@aws-sdk/client-sqs'';\n\nconst sqs = new SQSClient({});\nawait sqs.send(new SendMessageCommand({ QueueUrl: queueUrl, MessageBody: JSON.stringify({ orderId }) }));\nconst { Messages } = await sqs.send(new ReceiveMessageCommand({ QueueUrl: queueUrl, WaitTimeSeconds: 20 }));", "securityGuidance": "Split send from receive in IAM — producers get sqs:SendMessage on their one queue, consumers get Receive/Delete, nobody gets sqs:*. Configure a dead-letter queue with a bounded maxReceiveCount so poison messages surface instead of looping, enable SSE (KMS for cross-service reads), and keep queue policies free of Principal:* — an open queue policy is an open write path into your workers.", "setupInstructions": [{"url": "https://console.aws.amazon.com/sqs/", "type": "dashboard_config", "title": "Create SQS Queue", "required": true, "instructions": "In AWS Console > SQS > Create Queue. Choose Standard (high throughput, at-least-once) or FIFO (exactly-once, ordered). Set visibility timeout to match your expected processing time."}, {"type": "dashboard_config", "title": "Configure Dead-Letter Queue", "required": true, "instructions": "Create a separate DLQ and configure the main queue to send failed messages (after N receive attempts) to the DLQ. Monitor the DLQ for stuck messages."}, {"type": "permissions", "title": "Set IAM Permissions", "required": true, "instructions": "Create an IAM policy granting sqs:SendMessage, sqs:ReceiveMessage, sqs:DeleteMessage, and sqs:GetQueueAttributes on the specific queue ARN. Attach to your application role or user."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export AWS_SQS_QUEUE_URL=https://sqs.us-east-1.amazonaws.com/123456789/my-queue", "export AWS_REGION=us-east-1", "export AWS_ACCESS_KEY_ID=<from-iam>", "export AWS_SECRET_ACCESS_KEY=<from-iam>"], "required": true, "instructions": "Add SQS queue URL and AWS credentials to your application environment."}]}', '[{"kind": "config", "path": "infra/aws/sqs.tf"}]', '{"queueType": {"type": "enum", "label": "Queue type", "default": "standard", "options": ["standard", "fifo"], "description": "Standard: at-least-once, unlimited throughput; FIFO: exactly-once, ordered"}, "retentionDays": {"type": "number", "label": "Retention (days)", "default": 4, "description": "1-14 days"}, "deadLetterQueue": {"type": "boolean", "label": "Dead-letter queue", "default": true, "description": "Route poison messages after maxReceiveCount"}, "maxReceiveCount": {"type": "number", "label": "Max receives before DLQ", "default": 5}, "visibilityTimeoutSeconds": {"type": "number", "label": "Visibility timeout (s)", "default": 30, "description": "Set >= your consumer''s processing time"}}', '["serverless-function", "worker", "backend-service"]', false, NULL, NULL, '2026-05-18 02:38:14.715381+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''/client-sqs'':42C ''20'':65C ''aw'':1A,3A,28C,40C ''await'':47C,58C ''aws-sdk'':39C ''best'':17B ''best-effort'':16B ''bound'':94C ''configur'':86C ''const'':43C,56C ''consum'':80C ''cross'':108C ''cross-servic'':107C ''dead'':89C ''dead-lett'':88C ''decoupl'':11B ''distribut'':12B ''effort'':18B ''enabl'':103C ''exact'':23B ''exactly-onc'':22B ''fifo'':21B ''free'':115C ''fulli'':5B ''get'':73C,81C,84C ''iam'':71C ''import'':34C ''instead'':100C ''json.stringify'':54C ''keep'':112C ''kms'':105C ''lambda'':32C ''letter'':90C ''loop'':102C ''manag'':6B ''maxreceivecount'':95C ''messag'':7B,57C,98C ''messagebodi'':53C ''new'':45C,49C,60C ''nobodi'':83C ''node.js'':30C ''one'':78C ''open'':119C,124C ''order'':19B ''orderid'':55C ''path'':126C ''poison'':97C ''polici'':114C,121C ''princip'':117C ''process'':25B ''produc'':72C ''python'':31C ''queu'':8B ''queue'':26B,79C,91C,113C,120C ''queueurl'':51C,52C,62C,63C ''read'':110C ''receiv'':69C ''receive/delete'':82C ''receivemessagecommand'':37C,61C ''sdk'':29C,41C ''send'':67C ''sendmessag'':75C ''sendmessagecommand'':36C,50C ''servic'':9B,109C ''split'':66C ''sqs'':2A,4A,44C,74C,85C ''sqs.send'':48C,59C ''sqsclient'':35C,46C ''sse'':104C ''standard'':15B ''support'':14B ''surfac'':99C ''system'':13B ''trigger'':33C ''type'':27B ''waittimesecond'':64C ''worker'':129C ''write'':125C');
INSERT INTO public.technology_catalog VALUES ('azure-cosmos-db', 'Azure Cosmos DB', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/cosmosdb.png', '#6b7280', '["database"]', '{"purpose": "Globally distributed, multi-model database service with guaranteed single-digit millisecond latency. Supports document, key-value, graph, and column-family data models.", "configMode": "declarative", "provenance": {"notes": "Phase B2 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Azure SDK", "Node.js", "Python", ".NET", "SQL API"], "antiPatterns": ["Using cross-partition queries for hot paths", "Choosing a partition key that creates hot partitions", "Not indexing fields used in WHERE clauses", "Over-provisioning throughput in manual mode"], "apiReference": {"docsUrl": "https://learn.microsoft.com/azure/cosmos-db/"}, "bestPractices": ["Choose the right partition key for even data distribution", "Use the SQL API for most workloads (most mature)", "Set appropriate consistency level per operation", "Use change feed for event-driven architectures", "Configure autoscale throughput for variable workloads"], "sdkInitPattern": "import { CosmosClient } from ''@azure/cosmos'';\r\nimport { DefaultAzureCredential } from ''@azure/identity'';\r\n\r\n// Managed identity / AAD — no account keys in app config.\r\nconst client = new CosmosClient({\r\n  endpoint: process.env.COSMOS_ENDPOINT,\r\n  aadCredentials: new DefaultAzureCredential(),\r\n});\r\nconst container = client.database(''app'').container(''items'');", "securityGuidance": "Authenticate with Microsoft Entra ID + managed identity and Cosmos DB RBAC data-plane roles — avoid distributing account keys, and disable key-based auth where the workload allows. Restrict network access with private endpoints or account-level firewall rules rather than public reach. Scope RBAC to the database/container the workload touches. Choose partition keys deliberately — a hot partition is an availability incident, not just a cost one.", "setupInstructions": [{"url": "https://portal.azure.com/#create/Microsoft.DocumentDB", "type": "dashboard_config", "title": "Create Cosmos DB Account", "required": true, "instructions": "In Azure Portal > Azure Cosmos DB > Create. Choose the API type (NoSQL/SQL API recommended for most cases). Select the capacity mode (serverless for dev, provisioned for production)."}, {"type": "dashboard_config", "title": "Create Database and Container", "required": true, "instructions": "Within the account, create a database and container. Choose a partition key that distributes data evenly (e.g., /tenantId, /userId). This cannot be changed after creation."}, {"type": "environment_variable", "title": "Note Connection String", "required": true, "instructions": "In the account Settings > Keys, copy the Primary Connection String or the URI + Primary Key pair."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export COSMOS_DB_ENDPOINT=https://my-account.documents.azure.com:443/", "export COSMOS_DB_KEY=<primary-key>", "export COSMOS_DB_DATABASE=my-database", "export COSMOS_DB_CONTAINER=my-container"], "required": true, "instructions": "Add Cosmos DB connection details to your application environment."}]}', '[{"kind": "config", "path": "infra/azure/cosmos.bicep"}]', '{"api": {"type": "enum", "label": "API", "default": "nosql", "options": ["nosql", "mongodb", "cassandra", "gremlin", "table"], "description": "NoSQL is the native API with the fullest feature set; others are wire-compatibility layers for migrations"}, "capacityMode": {"type": "enum", "label": "Capacity mode", "default": "autoscale-ru", "options": ["serverless", "provisioned-ru", "autoscale-ru"], "description": "Serverless for spiky/dev; autoscale RU/s for production with variable load"}, "partitionKey": {"type": "string", "label": "Partition key", "description": "High-cardinality key — the single biggest performance decision"}, "consistencyLevel": {"type": "enum", "label": "Consistency", "default": "session", "options": ["session", "bounded-staleness", "strong", "consistent-prefix", "eventual"], "description": "Session is the default trade-off; strong costs RU and limits multi-region writes"}, "multiRegionWrites": {"type": "boolean", "label": "Multi-region writes", "default": false, "description": "Active-active across regions; raises cost and conflict-handling burden"}}', '["backend-service", "serverless-function", "worker"]', false, NULL, NULL, '2026-05-18 02:38:14.715381+00', '2026-08-30 12:07:23.877005+00', 'Azure Cosmos DB', NULL, '''aad'':50C ''aadcredenti'':64C ''access'':104C ''account'':52C,90C,110C ''account-level'':109C ''allow'':101C ''api'':39C ''app'':55C,70C ''auth'':97C ''authent'':73C ''avail'':135C ''avoid'':88C ''azur'':1A,4A,33C ''azure/cosmos'':43C ''azure/identity'':47C ''base'':96C ''choos'':126C ''client'':58C ''client.database'':69C ''column'':29B ''column-famili'':28B ''config'':56C ''const'':57C,67C ''contain'':68C,71C ''cosmos'':2A,5A,81C ''cosmoscli'':41C,60C ''cost'':140C ''data'':31B,85C ''data-plan'':84C ''databas'':12B ''database/container'':122C ''db'':3A,6A,82C ''defaultazurecredenti'':45C,66C ''deliber'':129C ''digit'':18B ''disabl'':93C ''distribut'':8B,89C ''document'':22B ''endpoint'':61C,63C,107C ''entra'':76C ''famili'':30B ''firewal'':112C ''global'':7B ''graph'':26B ''guarante'':15B ''hot'':131C ''id'':77C ''ident'':49C,79C ''import'':40C,44C ''incid'':136C ''item'':72C ''key'':24B,53C,91C,95C,128C ''key-bas'':94C ''key-valu'':23B ''latenc'':20B ''level'':111C ''manag'':48C,78C ''microsoft'':75C ''millisecond'':19B ''model'':11B,32B ''multi'':10B ''multi-model'':9B ''net'':37C ''network'':103C ''new'':59C,65C ''node.js'':35C ''one'':141C ''partit'':127C,132C ''plane'':86C ''privat'':106C ''process.env.cosmos'':62C ''public'':116C ''python'':36C ''rather'':114C ''rbac'':83C,119C ''reach'':117C ''restrict'':102C ''role'':87C ''rule'':113C ''scope'':118C ''sdk'':34C ''servic'':13B ''singl'':17B ''single-digit'':16B ''sql'':38C ''support'':21B ''touch'':125C ''valu'':25B ''workload'':100C,124C');
INSERT INTO public.technology_catalog VALUES ('azure-entra-id', 'Microsoft Entra ID', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/azure-ad-b2c.png', '#0078D4', '["auth-provider"]', '{"purpose": "Microsoft identity platform for workforce SSO, app registrations, and OAuth flows", "configMode": "declarative", "provenance": {"notes": "Phase B6 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["MSAL", "OAuth 2.0 / OIDC", "Managed Identities", "Conditional Access", "Microsoft Graph"], "antiPatterns": ["Storing client secrets in code instead of Key Vault", "Using one app registration across all environments", "Requesting broad Graph permissions upfront", "Building custom token validation instead of using MSAL"], "apiReference": {"docsUrl": "https://learn.microsoft.com/entra/"}, "bestPractices": ["Use managed identities for service-to-service authentication", "Use MSAL libraries instead of hand-rolling token flows", "Enforce Conditional Access policies and MFA", "Create separate app registrations per environment", "Request least-privilege Microsoft Graph scopes", "Prefer workload identity federation over client secrets in CI"], "sdkInitPattern": "import { ConfidentialClientApplication } from \"@azure/msal-node\";\nconst cca = new ConfidentialClientApplication({ auth: { clientId: process.env.AZURE_CLIENT_ID, authority: `https://login.microsoftonline.com/${process.env.AZURE_TENANT_ID}`, clientSecret: process.env.AZURE_CLIENT_SECRET } });", "securityGuidance": "App registrations hold the keys: prefer certificates or federated credentials (workload identity) over client secrets, expire and rotate what secrets remain, and grant API permissions least-privilege with admin consent reviewed. Enforce Conditional Access + MFA for users, and monitor sign-in and audit logs — identity is the perimeter.", "setupInstructions": [{"url": "https://learn.microsoft.com/en-us/azure/active-directory-b2c/tutorial-create-tenant", "type": "account_setup", "title": "Create Azure AD B2C Tenant", "required": true, "instructions": "Create an Azure AD B2C tenant in the Azure portal. This is separate from your main Azure AD directory."}, {"type": "dashboard_config", "title": "Register Application", "required": true, "instructions": "Register your application in the B2C tenant under App registrations. Configure redirect URIs and platform settings."}, {"type": "dashboard_config", "title": "Create User Flows", "required": true, "instructions": "Create sign-up/sign-in, password reset, and profile editing user flows (or custom policies) in the Azure portal."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export AZURE_AD_B2C_TENANT=your-tenant.onmicrosoft.com", "export AZURE_AD_B2C_CLIENT_ID=your-client-id", "export AZURE_AD_B2C_POLICY=B2C_1_signupsignin"], "required": true, "instructions": "Configure your B2C tenant name, client ID, and policy names in environment variables."}]}', '[{"kind": "config", "path": "infra/azure/entra.bicep"}]', '{"mfa": {"type": "boolean", "label": "MFA Enabled", "default": false, "description": "Require multi-factor authentication"}, "clientId": {"type": "string", "label": "Application (Client) ID", "description": "Entra ID app registration client ID"}, "tenantId": {"type": "string", "label": "Tenant ID", "description": "Microsoft Entra ID tenant identifier"}, "authFlows": {"type": "multiselect", "label": "Auth flows", "options": ["authorization-code-pkce", "client-credentials", "device-code", "on-behalf-of"], "description": "PKCE for SPAs/mobile; client-credentials for service-to-service"}, "authority": {"type": "string", "label": "Authority URL", "description": "Entra ID authority endpoint"}, "userFlows": {"type": "boolean", "label": "User Flows", "default": true, "description": "Use built-in user flows (simpler)"}, "tenantType": {"type": "enum", "label": "Tenant type", "default": "workforce", "options": ["workforce", "external"], "description": "External ID replaces Azure AD B2C for customer-facing sign-in"}, "mfaRequired": {"type": "boolean", "label": "MFA required", "default": true}, "customPolicies": {"type": "boolean", "label": "Custom Policies", "default": false, "description": "Use custom policies (Identity Experience Framework)"}, "conditionalAccess": {"type": "boolean", "label": "Conditional access policies", "default": true}}', '[{"id": "azure-app-service", "reason": "App authentication integration"}, {"id": "azure-functions", "reason": "Managed identity consumer"}, {"id": "azure-key-vault", "reason": "Secret storage for credentials"}]', false, NULL, NULL, '2026-08-30 12:07:21.475149+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''/$'':44C ''2.0'':20C ''access'':25C,86C ''admin'':81C ''api'':75C ''app'':13B,52C ''audit'':96C ''auth'':36C ''author'':41C ''azur'':4A ''azure/msal-node'':31C ''cca'':33C ''certif'':58C ''client'':39C,50C,65C ''clientid'':37C ''clientsecret'':48C ''condit'':24C,85C ''confidentialclientappl'':29C,35C ''consent'':82C ''const'':32C ''credenti'':61C ''enforc'':84C ''entra'':2A,5A ''expir'':67C ''feder'':60C ''flow'':17B ''grant'':74C ''graph'':27C ''hold'':54C ''id'':3A,6A,40C,47C ''ident'':8B,23C,63C,98C ''import'':28C ''key'':56C ''least'':78C ''least-privileg'':77C ''log'':97C ''login.microsoftonline.com'':43C ''login.microsoftonline.com/$'':42C ''manag'':22C ''mfa'':87C ''microsoft'':1A,7B,26C ''monitor'':91C ''msal'':18C ''new'':34C ''oauth'':16B,19C ''oidc'':21C ''perimet'':101C ''permiss'':76C ''platform'':9B ''prefer'':57C ''privileg'':79C ''process.env.azure'':38C,45C,49C ''registr'':14B,53C ''remain'':72C ''review'':83C ''rotat'':69C ''secret'':51C,66C,71C ''sign'':93C ''sign-in'':92C ''sso'':12B ''tenant'':46C ''user'':89C ''workforc'':11B ''workload'':62C');
INSERT INTO public.technology_catalog VALUES ('gcp-cloud-run', 'Google Cloud Run', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/gcp-cloud-run.png', '#4285F4', '["docker-container"]', '{"purpose": "Google Cloud Run is Google Cloud''s fully managed serverless platform for running stateless containers and function-style workloads on demand with HTTP and event-driven invocation models. Use it for containerized web services, APIs, background jobs, and function deployments that need autoscaling, revision management, and managed infrastructure. Choose Cloud Run over Cloud Functions when you want container packaging, broader runtime control, or service-style deployments, and over GKE when you do not need cluster-level Kubernetes management. Do not use it for stateful services that depend on local persistence or for platforms that require custom Kubernetes primitives, operators, or daemon workloads.", "configMode": "code", "provenance": {"notes": "Phase B1 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Cloud Run", "Artifact Registry", "Pub/Sub", "Eventarc", "Cloud Build", "Secret Manager", "Cloud Logging"], "antiPatterns": ["Treating Cloud Run as a stateful container host with reliance on local disk persistence", "Bundling many unrelated services into one container just to avoid multiple deployments", "Ignoring concurrency settings and then misreading scaling, memory, or latency behavior", "Using Cloud Run where Kubernetes-specific networking, sidecars, or operators are required", "Embedding secrets into container images instead of using managed configuration or secret injection", "Deploying mutable latest-tag images to production without versioning or provenance controls"], "apiReference": {"docsUrl": "https://cloud.google.com/run/docs"}, "bestPractices": ["Build services as stateless containers and externalize durable state to managed backing services", "Use revisions and traffic splitting for safe rollouts and controlled production changes", "Tune concurrency, CPU, and memory settings based on actual request patterns and latency goals", "Protect service access with identity-aware ingress rules and least-privilege service accounts", "Separate synchronous HTTP services from asynchronous jobs and event consumers into distinct deployments", "Use structured logs, traces, and request correlation IDs for observability across revisions", "Pin production images by digest and source them from trusted registries and CI pipelines"], "securityGuidance": "Deploy --no-allow-unauthenticated by default and grant roles/run.invoker explicitly; public endpoints are an opt-in decision. Run each service under its own least-privilege service account — never the default compute service account. Mount secrets from Secret Manager instead of plaintext env vars, and set ingress to internal (or internal + load balancer) for service-to-service traffic.", "configurationTemplate": "# Deploy from source; private by default — grant invoker explicitly\r\ngcloud run deploy my-service --source . --region us-central1 --no-allow-unauthenticated\r\ngcloud run services add-iam-policy-binding my-service --region us-central1 \\\r\n  --member=\"serviceAccount:caller@my-project.iam.gserviceaccount.com\" --role=\"roles/run.invoker\""}', '[{"kind": "source", "path": "src/cloud-run/server.ts", "priority": "essential", "description": "Primary HTTP or event-driven service entrypoint for Cloud Run"}, {"kind": "config", "path": "cloudrun/service.yaml", "priority": "essential", "description": "Cloud Run service definition including scaling, ingress, and runtime settings"}, {"kind": "config", "path": "Dockerfile", "priority": "recommended", "description": "Container build definition for the Cloud Run service"}, {"kind": "config", "path": "infra/cloud-run.yaml", "priority": "recommended", "description": "Infrastructure definition for deploying Google Cloud Run services"}]', '{"ingress": {"type": "string", "label": "Ingress", "default": "all", "options": ["all", "internal", "internal-and-gclb"], "description": "Network exposure policy for the Cloud Run service"}, "concurrency": {"type": "number", "label": "Concurrency", "default": 80, "description": "Maximum number of concurrent requests per instance"}, "maxInstances": {"type": "number", "label": "Max instances", "default": 100, "description": "The blast-radius cap on a traffic spike and on a downstream database"}, "minInstances": {"type": "number", "label": "Min instances", "default": 0, "description": "Above 0 removes cold starts and adds always-on cost"}, "resourceKind": {"type": "enum", "label": "Cloud Run resource", "default": "service", "options": ["service", "job", "worker-pool"], "description": "A service serves requests; a job runs to completion; a worker pool pulls from a queue. These are different resources with different deploy commands — `function` is NOT one of them, it is the separate Cloud Run functions product"}, "cpuAllocation": {"type": "enum", "label": "CPU allocation", "default": "request-based", "options": ["request-based", "instance-based"], "description": "Request-based bills only while handling requests but freezes CPU in between — background work and connection pools need instance-based"}, "serviceAccount": {"type": "string", "label": "Runtime service account", "description": "Give each service its own — the default compute SA is over-privileged"}}', '["api-gateway", "object-storage", "message-broker", "monitoring", "auth-provider"]', false, NULL, NULL, '2026-03-14 20:08:37.431602+00', '2026-08-30 12:07:23.877005+00', NULL, '#2F6AD8', '''account'':154C,160C ''allow'':128C ''api'':43B ''artifact'':115C ''autosc'':51B ''background'':44B ''balanc'':179C ''broader'':68B ''build'':120C ''choos'':57B ''cloud'':2A,5A,8B,12B,58B,61B,113C,119C,123C ''cluster'':85B ''cluster-level'':84B ''comput'':158C ''contain'':21B,66B ''container'':40B ''control'':70B ''custom'':106B ''daemon'':111B ''decis'':143C ''default'':131C,157C ''demand'':28B ''depend'':97B ''deploy'':48B,75B,125C ''driven'':34B ''endpoint'':137C ''env'':169C ''event'':33B ''event-driven'':32B ''eventarc'':118C ''explicit'':135C ''fulli'':14B ''function'':24B,47B,62B ''function-styl'':23B ''gcp'':4A ''gke'':78B ''googl'':1A,7B,11B ''grant'':133C ''http'':30B ''infrastructur'':56B ''ingress'':173C ''instead'':166C ''intern'':175C,177C ''invoc'':35B ''job'':45B ''kubernet'':87B,107B ''least'':151C ''least-privileg'':150C ''level'':86B ''load'':178C ''local'':99B ''log'':124C ''manag'':15B,53B,55B,88B,122C,165C ''model'':36B ''mount'':161C ''need'':50B,83B ''never'':155C ''no-allow-unauthent'':126C ''oper'':109B ''opt'':141C ''opt-in'':140C ''packag'':67B ''persist'':100B ''plaintext'':168C ''platform'':17B,103B ''primit'':108B ''privileg'':152C ''pub/sub'':117C ''public'':136C ''registri'':116C ''requir'':105B ''revis'':52B ''roles/run.invoker'':134C ''run'':3A,6A,9B,19B,59B,114C,144C ''runtim'':69B ''secret'':121C,162C,164C ''serverless'':16B ''servic'':42B,73B,95B,146C,153C,159C,182C,184C ''service-styl'':72B ''service-to-servic'':181C ''set'':172C ''state'':94B ''stateless'':20B ''style'':25B,74B ''traffic'':185C ''unauthent'':129C ''use'':37B,91B ''var'':170C ''want'':65B ''web'':41B ''workload'':26B,112B');
INSERT INTO public.technology_catalog VALUES ('gcp-cloud-pub-sub', 'Google Cloud Pub/Sub', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/gcp-cloud-pub-sub.png', '#4285F4', '["event-stream", "message-broker"]', '{"purpose": "Cloud Pub/Sub is Google Cloud''s fully managed asynchronous messaging and event ingestion service for decoupling producers and consumers at scale. Use it for service integration, event-driven architectures, real-time pipelines, and fan-out delivery where publishers should not depend on subscriber availability. Choose Pub/Sub over Cloud Tasks when multiple independent consumers or streaming-style delivery patterns are needed, and over direct HTTP integration when resilience and asynchronous decoupling matter. Do not use it for tightly controlled per-task scheduling, long-running workflow orchestration, or durable relational storage.", "configMode": "declarative", "provenance": {"notes": "Phase B2 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Cloud Pub/Sub", "Dataflow", "Cloud Run", "Cloud Functions", "Eventarc", "Cloud Monitoring", "BigQuery"], "antiPatterns": ["Using Pub/Sub as a relational datastore or long-term system of record", "Assuming exactly-once business processing without designing idempotent consumers", "Packing large documents or binaries directly into messages instead of object storage references", "Using one shared topic for unrelated domains with no ownership or contract boundaries", "Replacing scheduled task execution with Pub/Sub when Cloud Tasks is the better fit", "Treating Pub/Sub as a service mesh or synchronous request-response transport"], "apiReference": {"docsUrl": "https://cloud.google.com/pubsub/docs"}, "bestPractices": ["Design topics and subscriptions around domain boundaries and consumer ownership", "Use dead-letter topics, retry policies, and acknowledgment deadlines deliberately", "Keep messages compact and place large payloads in external storage with references", "Make subscribers idempotent because redelivery and at-least-once semantics are normal", "Separate push and pull subscription patterns based on consumer scaling and control needs", "Monitor backlog, unacked messages, publish latency, and subscriber error rates continuously", "Use schemas or explicit message contracts when multiple teams depend on the same events"], "sdkInitPattern": "import { PubSub } from ''@google-cloud/pubsub'';\r\n\r\nconst pubsub = new PubSub(); // ADC: workload identity in GCP\r\nawait pubsub.topic(''orders'').publishMessage({ json: { orderId } });\r\n\r\npubsub.subscription(''orders-worker'').on(''message'', (msg) => {\r\n  handle(JSON.parse(msg.data.toString()));\r\n  msg.ack();\r\n});", "securityGuidance": "Grant per-topic publisher and per-subscription subscriber roles — never project-wide Pub/Sub admin to workloads. Authenticate with workload identity / ADC, not exported keys. Push subscriptions must deliver to authenticated endpoints (OIDC token on the push config); an unauthenticated push endpoint is an open ingestion door. Configure dead-letter topics and sane retry policies so poison messages cannot wedge a subscription, and use CMEK where compliance requires it."}', '[{"kind": "source", "path": "src/pubsub/publisher.ts", "priority": "essential", "description": "Client for publishing messages to Cloud Pub/Sub topics"}, {"kind": "source", "path": "src/pubsub/subscriber.ts", "priority": "recommended", "description": "Subscriber handler with ack, retry, and dead-letter behavior"}, {"kind": "config", "path": "infra/pubsub.yaml", "priority": "recommended", "description": "Infrastructure-as-code definition for topics, subscriptions, and dead-letter policies"}]', '{"deliveryMode": {"type": "string", "label": "Delivery Mode", "default": "pull", "options": ["pull", "push"], "description": "Primary subscription delivery pattern"}, "deadLettering": {"type": "boolean", "label": "Dead Lettering", "default": true, "description": "Route repeatedly failing messages to a dead-letter topic"}, "retentionDays": {"type": "number", "label": "Message retention (days)", "default": 7, "description": "Also the replay window — how far back a subscription can be seeked"}, "deadLetterTopic": {"type": "boolean", "label": "Dead-letter topic", "default": true, "description": "Without one, a poison message is redelivered until it expires"}, "messageOrdering": {"type": "boolean", "label": "Ordered delivery", "default": false, "description": "Ordering keys serialize per key and cap throughput for that key"}, "orderingEnabled": {"type": "boolean", "label": "Ordering Enabled", "default": false, "description": "Preserve ordered delivery for messages with ordering keys"}, "subscriptionType": {"type": "enum", "label": "Subscription type", "default": "pull", "options": ["pull", "push", "bigquery", "cloud-storage"], "description": "BigQuery and Cloud Storage subscriptions write directly with no subscriber code at all — the cheapest pipeline is often no pipeline"}, "deliveryGuarantee": {"type": "enum", "label": "Delivery", "default": "at-least-once", "options": ["at-least-once", "exactly-once"], "description": "At-least-once is the default and requires idempotent handlers; exactly-once is regional and costs latency"}}', '["worker", "serverless-function", "backend-service", "monitoring", "ml-pipeline"]', false, NULL, NULL, '2026-03-14 21:24:46.083759+00', '2026-08-30 12:07:23.877005+00', NULL, '#2F6AD8', '''/pubsub'':120C ''adc'':125C,170C ''admin'':163C ''architectur'':37B ''asynchron'':16B,80B ''authent'':166C,179C ''avail'':54B ''await'':130C ''bigqueri'':113C ''cannot'':208C ''choos'':55B ''cloud'':2A,5A,8B,12B,58B,103C,106C,108C,111C,119C ''cmek'':214C ''complianc'':216C ''config'':186C ''configur'':196C ''const'':121C ''consum'':26B,63B ''control'':89B ''dataflow'':105C ''dead'':198C ''dead-lett'':197C ''decoupl'':23B,81B ''deliv'':177C ''deliveri'':46B,68B ''depend'':51B ''direct'':74B ''door'':195C ''driven'':36B ''durabl'':100B ''endpoint'':180C,190C ''event'':19B,35B ''event-driven'':34B ''eventarc'':110C ''export'':172C ''fan'':44B ''fan-out'':43B ''fulli'':14B ''function'':109C ''gcp'':4A,129C ''googl'':1A,11B,118C ''google-cloud'':117C ''grant'':147C ''handl'':143C ''http'':75B ''ident'':127C,169C ''import'':114C ''independ'':62B ''ingest'':20B,194C ''integr'':33B,76B ''json'':134C ''json.parse'':144C ''key'':173C ''letter'':199C ''long'':95B ''long-run'':94B ''manag'':15B ''matter'':82B ''messag'':17B,141C,207C ''monitor'':112C ''msg'':142C ''msg.ack'':146C ''msg.data.tostring'':145C ''multipl'':61B ''must'':176C ''need'':71B ''never'':158C ''new'':123C ''oidc'':181C ''open'':193C ''orchestr'':98B ''order'':132C,138C ''orderid'':135C ''orders-work'':137C ''pattern'':69B ''per'':91B,149C,154C ''per-subscript'':153C ''per-task'':90B ''per-top'':148C ''pipelin'':41B ''poison'':206C ''polici'':204C ''produc'':24B ''project'':160C ''project-wid'':159C ''pub'':6A ''pub/sub'':3A,9B,56B,104C,162C ''publish'':48B,151C ''publishmessag'':133C ''pubsub'':115C,122C,124C ''pubsub.subscription'':136C ''pubsub.topic'':131C ''push'':174C,185C,189C ''real'':39B ''real-tim'':38B ''relat'':101B ''requir'':217C ''resili'':78B ''retri'':203C ''role'':157C ''run'':96B,107C ''sane'':202C ''scale'':28B ''schedul'':93B ''servic'':21B,32B ''storag'':102B ''stream'':66B ''streaming-styl'':65B ''style'':67B ''sub'':7A ''subscrib'':53B,156C ''subscript'':155C,175C,211C ''task'':59B,92B ''tight'':88B ''time'':40B ''token'':182C ''topic'':150C,200C ''unauthent'':188C ''use'':29B,85B,213C ''wedg'':209C ''wide'':161C ''worker'':139C ''workflow'':97B ''workload'':126C,165C,168C');
INSERT INTO public.technology_catalog VALUES ('react-native', 'React Native', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/react.png', '#61DAFB', '["mobile-app"]', '{"purpose": "JavaScript/TypeScript framework for building native mobile applications using React paradigms. React Native renders actual native UI components (not WebView), giving near-native performance while sharing business logic across iOS and Android. Use when your team has strong React/JavaScript expertise and wants to share code between mobile and web platforms. React Native is ideal when you want native performance with web development velocity, when your app uses standard platform UI components, and when you want access to the enormous npm ecosystem. Don''t use when you need pixel-perfect custom rendering or heavy animations -- Flutter''s Skia engine has an edge there. Don''t use for performance-critical apps like games or video editors where native is mandatory. Avoid if your app is heavily platform-specific with little shared business logic between iOS and Android.", "configMode": "code", "provenance": {"notes": "New Architecture is MANDATORY since RN 0.82 (legacy frozen June 2025, config option removed in Expo SDK 55) — deliberately NO architecture field, the decision no longer exists. Expo is the recommended toolchain.", "method": "live-docs", "sources": ["https://reactnative.dev/blog/2025/10/08/react-native-0.82", "https://docs.expo.dev/guides/new-architecture/"], "verifiedAt": "2026-07-27"}, "typicalTech": ["React Native", "Expo", "React Navigation", "TypeScript", "Hermes", "FlashList", "Reanimated", "React Native Testing Library"], "antiPatterns": ["Using FlatList for large lists without virtualization optimization", "Passing inline functions and objects as props causing unnecessary re-renders", "Overusing bridge calls (old architecture) causing performance bottlenecks", "Not handling keyboard interactions and safe areas properly across platforms", "Using WebView for screens that should be native components", "Ignoring native module linking and Hermes engine configuration"], "apiReference": {"docsUrl": "https://reactnative.dev/docs/getting-started"}, "bestPractices": ["Use TypeScript for type safety across the entire codebase", "Use React Navigation for routing with native navigation gestures", "Implement state management with Zustand, Jotai, or TanStack Query", "Use the New Architecture (Fabric + TurboModules) for better native interop", "Test with Detox for end-to-end and React Native Testing Library for components", "Use Expo for managed workflow when possible to simplify build and deploy", "Optimize lists with FlashList instead of FlatList for large datasets"], "sdkInitPattern": "npx create-expo-app my-app --template blank-typescript && cd my-app && npx expo start\\n// App.tsx\\nimport { Text, View } from \"react-native\";\\nexport default function App() {\\n  return <View style={{ flex: 1, justifyContent: \"center\", alignItems: \"center\" }}><Text>Hello React Native</Text></View>;\\n}", "securityGuidance": "Never embed API keys or secrets in JavaScript bundles -- they are extractable. Use expo-secure-store or react-native-keychain for secure token storage. Enable Hermes engine for improved security (bytecode rather than plain JS). Implement certificate pinning for sensitive API connections. Use App Transport Security (iOS) and Network Security Config (Android) to enforce HTTPS.", "commonApiPatterns": [{"name": "Screen Component", "description": "Screen with route params and TanStack Query data fetching", "codeTemplate": "function UserScreen({ route }: { route: RouteProp<RootStack, \"User\"> }) {\\n  const { id } = route.params;\\n  const { data: user, isLoading } = useQuery({ queryKey: [\"user\", id], queryFn: () => fetchUser(id) });\\n  if (isLoading) return <ActivityIndicator />;\\n  return <View><Text style={styles.name}>{user?.name}</Text></View>;\\n}"}, {"name": "Navigation Stack", "description": "Native stack navigator with typed routes", "codeTemplate": "const Stack = createNativeStackNavigator<RootStack>();\\nfunction AppNavigator() {\\n  return (\\n    <Stack.Navigator>\\n      <Stack.Screen name=\"Home\" component={HomeScreen} />\\n      <Stack.Screen name=\"User\" component={UserScreen} />\\n    </Stack.Navigator>\\n  );\\n}"}, {"name": "Animated Component", "description": "Reanimated 3 animation running on the UI thread", "codeTemplate": "import Animated, { useSharedValue, useAnimatedStyle, withSpring } from \"react-native-reanimated\";\\nfunction AnimatedBox() {\\n  const offset = useSharedValue(0);\\n  const style = useAnimatedStyle(() => ({ transform: [{ translateX: withSpring(offset.value) }] }));\\n  return <Animated.View style={[styles.box, style]} onTouchStart={() => { offset.value = offset.value === 0 ? 200 : 0; }} />;\\n}"}], "setupInstructions": [{"url": "https://reactnative.dev/docs/environment-setup", "type": "toolchain_install", "title": "Install Development Environment", "commands": ["npm install -g react-native-cli", "brew install watchman"], "required": true, "instructions": "Install Node.js, Watchman (macOS), and the React Native CLI or use Expo."}, {"type": "toolchain_install", "title": "Configure Android Environment", "commands": ["export ANDROID_HOME=$HOME/Android/Sdk", "export PATH=$PATH:$ANDROID_HOME/emulator:$ANDROID_HOME/platform-tools"], "required": true, "instructions": "Install Android Studio, configure ANDROID_HOME, and set up an emulator or connect a physical device."}, {"type": "toolchain_install", "title": "Configure iOS Environment (macOS only)", "commands": ["sudo gem install cocoapods", "cd ios && pod install"], "required": false, "instructions": "Install Xcode and CocoaPods for iOS development."}], "integrationPatterns": ["Expo for simplified build, OTA updates, and managed native module configuration", "Firebase or Supabase for backend services (auth, database, push notifications)", "EAS Build + EAS Submit for CI/CD pipeline to App Store and Google Play"], "configurationTemplate": "// app.json (Expo)\\n{\\n  \"expo\": {\\n    \"name\": \"my-app\",\\n    \"slug\": \"my-app\",\\n    \"version\": \"1.0.0\",\\n    \"platforms\": [\"ios\", \"android\"],\\n    \"newArchEnabled\": true,\\n    \"plugins\": [\\n      \"expo-router\",\\n      \"expo-secure-store\"\\n    ]\\n  }\\n}"}', '[{"kind": "config", "path": "app.json", "language": "json", "description": "Expo/React Native app configuration"}, {"kind": "source", "path": "App.tsx", "language": "typescript", "description": "Root application component"}, {"kind": "source", "path": "src/navigation/index.tsx", "language": "typescript", "description": "Navigation configuration"}, {"kind": "config", "path": "package.json", "language": "json", "description": "NPM dependencies and scripts"}, {"kind": "config", "path": "metro.config.js", "language": "javascript", "description": "Metro bundler configuration"}, {"kind": "source", "path": "src/screens/HomeScreen.tsx", "language": "typescript", "description": "Home screen component"}]', '{"targets": {"type": "multiselect", "label": "Targets", "options": ["ios", "android", "web"], "description": "One codebase, one node — targets are configuration, not extra nodes"}, "toolchain": {"type": "enum", "label": "Toolchain", "default": "expo", "options": ["expo", "bare-react-native"], "description": "Expo is the recommended framework (EAS builds, expo-router, OTA updates); bare RN only when a native requirement rules Expo out — and check that it actually does, most no longer do"}, "navigation": {"type": "enum", "label": "Navigation", "default": "expo-router", "options": ["expo-router", "react-navigation"]}, "otaUpdates": {"type": "boolean", "label": "OTA updates (EAS Update)", "default": true, "description": "Ship JS-level fixes without a store review — within store policy limits"}, "stateManagement": {"type": "enum", "label": "State", "default": "zustand", "options": ["zustand", "redux-toolkit", "tanstack-query-plus-store", "context-only"]}}', '["web.rest-api", "auth.supabase-auth", "backend.nodejs"]', false, NULL, NULL, '2026-02-16 02:23:50.361867+00', '2026-08-30 12:07:23.877005+00', NULL, '#4DC0E8', '''1'':193C ''access'':80B ''across'':33B ''actual'':18B ''alignitem'':196C ''android'':36B,142B,255C ''anim'':99B ''api'':204C,244C ''app'':70B,115B,128B,160C,163C,171C,187C,247C ''app.tsx'':176C ''applic'':11B ''avoid'':125B ''blank'':166C ''blank-typescript'':165C ''build'':8B ''bundl'':210C ''busi'':31B,137B ''bytecod'':234C ''cd'':168C ''center'':195C,197C ''certif'':240C ''code'':49B ''compon'':21B,75B ''config'':254C ''connect'':245C ''creat'':158C ''create-expo-app'':157C ''critic'':114B ''custom'':95B ''default'':185C ''develop'':66B ''ecosystem'':85B ''edg'':106B ''editor'':120B ''emb'':203C ''enabl'':228C ''enforc'':257C ''engin'':103B,230C ''enorm'':83B ''expertis'':44B ''expo'':145C,159C,173C,216C ''expo-secure-stor'':215C ''extract'':213C ''flashlist'':150C ''flex'':192C ''flutter'':100B ''framework'':6B ''function'':186C ''game'':117B ''give'':24B ''heavi'':98B ''heavili'':130B ''hello'':198C ''herm'':149C,229C ''https'':258C ''ideal'':58B ''implement'':239C ''improv'':232C ''io'':34B,140B,250C ''javascript'':209C ''javascript/typescript'':5B ''js'':238C ''justifycont'':194C ''key'':205C ''keychain'':223C ''librari'':155C ''like'':116B ''littl'':135B ''logic'':32B,138B ''mandatori'':124B ''mobil'':10B,51B ''my-app'':161C,169C ''n'':175C,188C,201C ''nativ'':2A,4A,9B,16B,19B,27B,56B,62B,122B,144C,153C,183C,200C,222C ''navig'':147C ''near'':26B ''near-nat'':25B ''need'':91B ''network'':252C ''never'':202C ''nexport'':184C ''nimport'':177C ''npm'':84B ''npx'':156C,172C ''paradigm'':14B ''perfect'':94B ''perform'':28B,63B,113B ''performance-crit'':112B ''pin'':241C ''pixel'':93B ''pixel-perfect'':92B ''plain'':237C ''platform'':54B,73B,132B ''platform-specif'':131B ''rather'':235C ''react'':1A,3A,13B,15B,55B,143C,146C,152C,182C,199C,221C ''react-nat'':181C ''react-native-keychain'':220C ''react/javascript'':43B ''reanim'':151C ''render'':17B,96B ''return'':189C ''secret'':207C ''secur'':217C,225C,233C,249C,253C ''sensit'':243C ''share'':30B,48B,136B ''skia'':102B ''specif'':133B ''standard'':72B ''start'':174C ''storag'':227C ''store'':218C ''strong'':42B ''style'':191C ''team'':40B ''templat'':164C ''test'':154C ''text'':178C ''token'':226C ''transport'':248C ''typescript'':148C,167C ''ui'':20B,74B ''use'':12B,37B,71B,88B,110B,214C,246C ''veloc'':67B ''video'':119B ''view'':179C,190C ''want'':46B,61B,79B ''web'':53B,65B ''webview'':23B');
INSERT INTO public.technology_catalog VALUES ('angular', 'Angular', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/angular.png', '#dd0031', '["frontend-app"]', '{"purpose": "Full-featured TypeScript framework for building enterprise-scale web applications with dependency injection and RxJS", "configMode": "code", "provenance": {"notes": "Zoneless change detection is the DEFAULT since v21 and Zone.js is no longer included by default; signals fundamentals stable since v20. Model knowledge would have shipped zoneless as experimental.", "method": "live-docs", "sources": ["https://angular.dev/guide/zoneless", "https://blog.angular.dev/announcing-angular-v21-57946c34f14b"], "verifiedAt": "2026-07-27"}, "typicalTech": ["Angular 17+", "TypeScript", "RxJS", "NgRx", "Angular CLI", "Angular Material"], "antiPatterns": ["Using NgModules for new components when standalone components are preferred", "Not unsubscribing from Observables causing memory leaks (use takeUntilDestroyed or async pipe)", "Putting logic in component templates instead of the component class", "Not using OnPush change detection for performance-critical components", "Creating barrel files that re-export everything causing larger bundles"], "apiReference": {"docsUrl": "https://angular.dev/overview"}, "bestPractices": ["Use standalone components", "Follow the Angular style guide", "Use OnPush change detection strategy", "Implement lazy loading for feature modules", "Use NgRx for complex state management", "Use Angular signals for reactive state", "Implement proper error handling with interceptors", "Use trackBy with ngFor"], "sdkInitPattern": "npx @angular/cli new my-app --routing --style=scss --ssr=false && cd my-app\\n// src/app/app.component.ts\\n@Component({\\n  selector: \"app-root\",\\n  standalone: true,\\n  template: `<h1>Hello Angular</h1>`,\\n})\\nexport class AppComponent {}", "securityGuidance": "Angular sanitizes template bindings by default. Never bypass sanitization with bypassSecurityTrust* unless absolutely necessary and input is verified. Use HttpInterceptors for centralized auth token injection. Enable strict CSP. Use Angular built-in XSRF protection with HttpClient. Avoid using ElementRef.nativeElement for direct DOM manipulation.", "commonApiPatterns": [{"name": "Standalone Component", "description": "Standalone component with signal-based input and control flow", "codeTemplate": "@Component({\\n  selector: \"app-user-list\",\\n  standalone: true,\\n  imports: [CommonModule, RouterLink],\\n  template: `\\n    @for (user of users(); track user.id) {\\n      <div><a [routerLink]=\"[''/user'', user.id]\">{{ user.name }}</a></div>\\n    }\\n  `,\\n})\\nexport class UserListComponent {\\n  users = input.required<User[]>();\\n}"}, {"name": "Injectable Service", "description": "Root-provided service with HttpClient for API calls", "codeTemplate": "@Injectable({ providedIn: \"root\" })\\nexport class UserService {\\n  private http = inject(HttpClient);\\n  getUsers() {\\n    return this.http.get<User[]>(\"/api/users\");\\n  }\\n  getUser(id: string) {\\n    return this.http.get<User>(`/api/users/${id}`);\\n  }\\n}"}, {"name": "Route Guard", "description": "Functional route guard with redirect to login", "codeTemplate": "export const authGuard: CanActivateFn = (route, state) => {\\n  const auth = inject(AuthService);\\n  const router = inject(Router);\\n  if (auth.isAuthenticated()) return true;\\n  return router.createUrlTree([\"/login\"], { queryParams: { returnUrl: state.url } });\\n};"}], "integrationPatterns": ["Angular Router for routing with lazy-loaded feature modules", "RxJS for reactive data streams and state management", "NgRx or Angular Signals for complex state management", "Angular Material or PrimeNG for UI component libraries", "Karma/Jasmine or Jest with Angular Testing Library for testing"], "configurationTemplate": "// angular.json (key sections)\\n{\\n  \"projects\": {\\n    \"my-app\": {\\n      \"architect\": {\\n        \"build\": {\\n          \"options\": {\\n            \"outputPath\": \"dist/my-app\",\\n            \"budgets\": [\\n              { \"type\": \"initial\", \"maximumWarning\": \"500kB\", \"maximumError\": \"1MB\" }\\n            ]\\n          }\\n        }\\n      }\\n    }\\n  }\\n}"}', '[{"kind": "source", "path": "src/app/app.component.ts", "language": "typescript", "description": "Root component"}, {"kind": "source", "path": "src/main.ts", "language": "typescript", "description": "Application bootstrap"}, {"kind": "config", "path": "angular.json", "language": "json", "description": "Angular workspace configuration"}]', '{"ssr": {"type": "boolean", "label": "SSR / hydration", "default": false}, "reactivity": {"type": "enum", "label": "Reactivity", "default": "signals-first", "options": ["signals-first", "rxjs-heavy", "mixed"], "description": "signal/effect/linkedSignal are stable — new state should be signals; RxJS stays for genuine streams"}, "componentModel": {"type": "enum", "label": "Component model", "default": "standalone-default", "options": ["standalone-default", "ngmodules-legacy"]}, "changeDetection": {"type": "enum", "label": "Change detection", "default": "zoneless-default", "options": ["zoneless-default", "zone-based-legacy"], "description": "Zoneless is the default since v21 (Zone.js is no longer included); zone-based only for apps that have not migrated"}}', '["rest-api", "graphql-api", "auth-provider", "websocket-server"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-30 12:07:23.877005+00', NULL, '#B00028', '''17'':21C ''absolut'':76C ''angular'':1A,2A,20C,25C,27C,59C,64C,93C ''angular/cli'':30C ''app'':34C,43C,51C ''app-root'':50C ''appcompon'':63C ''applic'':14B ''auth'':86C ''avoid'':101C ''bind'':67C ''build'':9B ''built'':95C ''built-in'':94C ''bypass'':71C ''bypasssecuritytrust'':74C ''cd'':40C ''central'':85C ''class'':62C ''cli'':26C ''compon'':47C ''csp'':91C ''default'':69C ''depend'':16B ''direct'':105C ''dom'':106C ''elementref.nativeelement'':103C ''enabl'':89C ''enterpris'':11B ''enterprise-scal'':10B ''fals'':39C ''featur'':5B ''framework'':7B ''full'':4B ''full-featur'':3B ''hello'':58C ''httpclient'':100C ''httpinterceptor'':83C ''inject'':17B,88C ''input'':79C ''manipul'':107C ''materi'':28C ''my-app'':32C,41C ''n'':44C,46C,48C,53C,56C,60C ''necessari'':77C ''never'':70C ''new'':31C ''nexport'':61C ''ngrx'':24C ''npx'':29C ''protect'':98C ''root'':52C ''rout'':35C ''rxjs'':19B,23C ''sanit'':65C,72C ''scale'':12B ''scss'':37C ''selector'':49C ''src/app/app.component.ts'':45C ''ssr'':38C ''standalon'':54C ''strict'':90C ''style'':36C ''templat'':57C,66C ''token'':87C ''true'':55C ''typescript'':6B,22C ''unless'':75C ''use'':82C,92C,102C ''verifi'':81C ''web'':13B ''xsrf'':97C');
INSERT INTO public.technology_catalog VALUES ('vue', 'Vue', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/vue.png', '#42b883', '["frontend-app"]', '{"purpose": "Progressive JavaScript framework for building user interfaces with an approachable, performant, and versatile design", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Vue 3", "TypeScript", "Vite", "Vue Router", "Pinia", "VueUse"], "antiPatterns": ["Using Options API in new projects when Composition API offers better TypeScript support", "Mutating props directly instead of emitting events to parent", "Deeply nested v-if/v-else chains instead of computed properties or component composition", "Using Vuex in new projects instead of Pinia", "Not using script setup syntax which provides better type inference and less boilerplate"], "apiReference": {"docsUrl": "https://vuejs.org/guide/"}, "bestPractices": ["Use Composition API with script setup", "Use Pinia for state management", "Implement proper prop validation", "Use computed properties instead of methods for derived state", "Leverage Vue devtools for debugging", "Use provide/inject sparingly", "Implement lazy loading for routes"], "sdkInitPattern": "npm create vite@latest my-app -- --template vue-ts && cd my-app && npm install\\n<!-- src/App.vue -->\\n<script setup lang=\"ts\">\\nimport { ref } from \"vue\";\\nconst msg = ref(\"Hello Vue\");\\n</script>\\n<template><h1>{{ msg }}</h1></template>", "securityGuidance": "Vue auto-escapes template interpolation preventing XSS. Never use v-html with unsanitized content. Validate dynamic :href and :src bindings to block javascript: URIs. Use CSP headers in production. Avoid storing auth tokens in reactive state exposed to devtools -- use httpOnly cookies. Sanitize input before passing to third-party DOM manipulation libraries.", "commonApiPatterns": [{"name": "Composition API Component", "description": "Component with reactive state, computed properties, and lifecycle hooks", "codeTemplate": "<script setup lang=\"ts\">\\nimport { ref, computed, onMounted } from \"vue\";\\nconst count = ref(0);\\nconst doubled = computed(() => count.value * 2);\\nconst increment = () => count.value++;\\nonMounted(() => console.log(\"mounted\"));\\n</script>\\n<template>\\n  <button @click=\"increment\">{{ count }} ({{ doubled }})</button>\\n</template>"}, {"name": "Composable", "description": "Reusable composable function for data fetching", "codeTemplate": "export function useUsers() {\\n  const users = ref<User[]>([]);\\n  const loading = ref(true);\\n  onMounted(async () => {\\n    users.value = await fetch(\"/api/users\").then(r => r.json());\\n    loading.value = false;\\n  });\\n  return { users, loading };\\n}"}, {"name": "Pinia Store", "description": "Pinia store with Composition API setup syntax", "codeTemplate": "export const useAuthStore = defineStore(\"auth\", () => {\\n  const user = ref<User | null>(null);\\n  const isAuthenticated = computed(() => !!user.value);\\n  async function login(credentials: Credentials) {\\n    user.value = await authApi.login(credentials);\\n  }\\n  return { user, isAuthenticated, login };\\n});"}], "integrationPatterns": ["Vue Router for SPA routing with navigation guards", "Pinia for type-safe state management with devtools support", "VueUse for collection of essential composition utilities", "Tailwind CSS or UnoCSS for utility-first styling", "Vitest + Vue Test Utils for component testing"], "configurationTemplate": "// vite.config.ts\\nimport { defineConfig } from \"vite\";\\nimport vue from \"@vitejs/plugin-vue\";\\nexport default defineConfig({\\n  plugins: [vue()],\\n  server: { port: 3000 },\\n  resolve: {\\n    alias: { \"@\": \"/src\" }\\n  }\\n});\\n\\n// tsconfig.json\\n{\\n  \"compilerOptions\": {\\n    \"target\": \"ES2020\",\\n    \"module\": \"ESNext\",\\n    \"jsx\": \"preserve\",\\n    \"strict\": true,\\n    \"moduleResolution\": \"bundler\",\\n    \"paths\": { \"@/*\": [\"./src/*\"] }\\n  }\\n}"}', '[{"kind": "source", "path": "src/App.vue", "language": "vue", "description": "Root Vue component"}, {"kind": "source", "path": "src/main.ts", "language": "typescript", "description": "Application entry point"}, {"kind": "config", "path": "vite.config.ts", "language": "typescript", "description": "Vite configuration"}]', '{"state": {"type": "enum", "label": "State", "default": "pinia", "options": ["pinia", "composables-only", "none"]}, "styling": {"type": "enum", "label": "Styling", "default": "scoped-sfc-css", "options": ["tailwind", "scoped-sfc-css", "css-modules"]}, "apiStyle": {"type": "enum", "label": "API style", "default": "composition-script-setup", "options": ["composition-script-setup", "options-legacy"], "description": "Composition API with <script setup> is the standing default; Options API is maintained for existing code"}, "typescript": {"type": "boolean", "label": "TypeScript", "default": true}}', '["rest-api", "graphql-api", "auth-provider", "websocket-server"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-30 12:07:23.877005+00', NULL, '#35946D', '''3'':18C ''app'':31C,39C ''approach'':12B ''auth'':79C ''auto'':48C ''auto-escap'':47C ''avoid'':77C ''bind'':67C ''block'':69C ''build'':7B ''cd'':36C ''content'':61C ''cooki'':89C ''creat'':26C ''csp'':73C ''design'':16B ''devtool'':86C ''dom'':98C ''dynam'':63C ''escap'':49C ''expos'':84C ''framework'':5B ''header'':74C ''href'':64C ''html'':58C ''httpon'':88C ''input'':91C ''instal'':41C ''interfac'':9B ''interpol'':51C ''javascript'':4B,70C ''latest'':28C ''librari'':100C ''manipul'':99C ''msg'':45C ''my-app'':29C,37C ''n'':42C,43C,44C ''never'':54C ''npm'':25C,40C ''parti'':97C ''pass'':93C ''perform'':13B ''pinia'':23C ''prevent'':52C ''product'':76C ''progress'':3B ''reactiv'':82C ''router'':22C ''sanit'':90C ''src'':66C ''state'':83C ''store'':78C ''templat'':32C,50C ''third'':96C ''third-parti'':95C ''token'':80C ''ts'':35C ''typescript'':19C ''unsanit'':60C ''uri'':71C ''use'':55C,72C,87C ''user'':8B ''v'':57C ''v-html'':56C ''valid'':62C ''versatil'':15B ''vite'':20C,27C ''vue'':1A,2A,17C,21C,34C,46C ''vue-t'':33C ''vueus'':24C ''xss'':53C');
INSERT INTO public.technology_catalog VALUES ('github', 'GitHub', NULL, '#181717', '["external-service"]', '{"purpose": "The GitHub platform API — integrate repositories, issues/PRs, Actions and webhooks into the product itself (dashboards, bots, automation, GitHub Apps). This node is for CALLING GitHub''s API from your application; CI/CD that merely runs on GitHub is the github-actions node instead.", "configMode": "external", "provenance": {"notes": "Phase B9 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Octokit SDK", "GitHub Apps", "fine-grained PATs", "webhooks (X-Hub-Signature-256)", "GraphQL v4", "REST v3"], "antiPatterns": ["Classic PATs with repo-wide scope where a fine-grained token or App installation would do", "Polling the API for changes that webhooks already push to you", "Trusting webhook payloads without signature verification", "One user''s OAuth token powering an org-wide integration — that is what GitHub Apps are for"], "apiReference": {"areas": {"repos": {"docsUrl": "https://docs.github.com/en/rest/repos", "endpoints": ["`GET /repos/{owner}/{repo}` — repository metadata (default_branch, permissions)", "`GET /repos/{owner}/{repo}/contents/{path}` — read a file (base64) or directory listing", "`PUT /repos/{owner}/{repo}/contents/{path}` — create/update a file (message, content, sha for updates)", "`GET /repos/{owner}/{repo}/commits` — commit history (sha, path, since filters)", "`GET /repos/{owner}/{repo}/branches` · `POST /repos/{owner}/{repo}/git/refs` — list branches / create a ref"]}, "actions": {"docsUrl": "https://docs.github.com/en/rest/actions", "endpoints": ["`POST /repos/{owner}/{repo}/actions/workflows/{id}/dispatches` — trigger a workflow_dispatch run (ref, inputs)", "`GET /repos/{owner}/{repo}/actions/runs` — run status/conclusion (filter by branch, event, status)", "`GET /repos/{owner}/{repo}/actions/runs/{run_id}/artifacts` — list artifacts; download via archive_download_url", "`POST /repos/{owner}/{repo}/actions/runs/{run_id}/rerun` — re-run a workflow"]}, "webhooks": {"docsUrl": "https://docs.github.com/en/webhooks", "endpoints": ["`POST /repos/{owner}/{repo}/hooks` — register endpoint (config.url, secret, events[])", "Verify X-Hub-Signature-256: HMAC-SHA256 of the RAW body with the webhook secret — reject mismatches", "Key events: push, pull_request, issues, issue_comment, workflow_run, release", "Return 2xx within 10s; process async — GitHub marks slow endpoints as failing"]}, "apps-auth": {"docsUrl": "https://docs.github.com/en/rest/authentication", "endpoints": ["GitHub App lane: sign a JWT with the app private key → `POST /app/installations/{id}/access_tokens` → short-lived installation token", "Fine-grained PAT lane: per-repo, per-permission tokens for single-owner automation", "Send `X-GitHub-Api-Version: 2026-03-10` — unversioned requests get the oldest supported behavior", "Rate limits: per-authentication primary limits + secondary abuse limits; check X-RateLimit-Remaining, honor Retry-After", "GraphQL alternative: `POST /graphql` with the same tokens — one query for nested resource views"]}, "issues-prs": {"docsUrl": "https://docs.github.com/en/rest/issues", "endpoints": ["`GET|POST /repos/{owner}/{repo}/issues` — list/create issues (labels, assignees)", "`POST /repos/{owner}/{repo}/issues/{number}/comments` — comment on an issue or PR", "`GET|POST /repos/{owner}/{repo}/pulls` — list/create PRs (head, base, draft)", "`PUT /repos/{owner}/{repo}/pulls/{number}/merge` — merge (merge_method: merge|squash|rebase)", "`GET /repos/{owner}/{repo}/pulls/{number}/files` — changed files with patch hunks"]}}, "docsUrl": "https://docs.github.com/en/rest"}, "bestPractices": ["Authenticate as a GitHub App with short-lived installation tokens for anything multi-user or org-installed; fine-grained PATs only for single-owner scripts", "Send X-GitHub-Api-Version (current: 2026-03-10) and Accept: application/vnd.github+json on every request", "Verify webhook payloads with the X-Hub-Signature-256 HMAC before trusting them", "Respect both primary rate limits and secondary (abuse) limits — honor Retry-After and retry-with-backoff on 403/429", "Use conditional requests (ETag / If-None-Match) — 304 responses do not count against the rate limit", "Reach for the GraphQL API (POST /graphql) when a view needs many nested resources in one round trip"], "sdkInitPattern": "import { Octokit } from ''octokit'';\n\n// GitHub App installation auth — short-lived tokens, scoped to the installation\nimport { createAppAuth } from ''@octokit/auth-app'';\nconst octokit = new Octokit({\n  authStrategy: createAppAuth,\n  auth: {\n    appId: process.env.GH_APP_ID,\n    privateKey: process.env.GH_APP_PRIVATE_KEY,\n    installationId,\n  },\n});\nconst { data: pr } = await octokit.rest.pulls.get({ owner, repo, pull_number });", "securityGuidance": "Prefer a GitHub App over personal access tokens for integrations — installation tokens are short-lived, repo-scoped, and revocable per installation; where PATs are unavoidable use fine-grained tokens with minimum repository and permission scope. The App''s private key is the crown jewel: secret store only, rotate on any doubt. Verify X-Hub-Signature-256 on every webhook with the shared secret, request the fewest webhook events you consume, and remember repo contents fetched via the API are third-party input — do not execute or eval them.", "setupInstructions": [{"type": "account_setup", "title": "Create a GitHub App (or fine-grained PAT)", "required": true, "instructions": "Register a GitHub App with the minimum repository permissions and webhook events the integration needs, generate its private key, and install it on the target repos."}, {"type": "environment_variable", "title": "Store credentials as configuration", "required": true, "instructions": "Provide the App id + private key (or the fine-grained token) via server-side secret configuration."}, {"type": "webhook_config", "title": "Configure the webhook secret", "required": false, "instructions": "Set a webhook secret on the App and verify X-Hub-Signature-256 on every delivery."}]}', '[{"kind": "source", "path": "src/lib/github.ts"}, {"kind": "source", "path": "src/app/api/webhooks/github/route.ts"}]', '{"apiAreas": {"type": "multiselect", "label": "GitHub API areas used", "options": ["repos", "issues-prs", "actions", "webhooks", "apps-auth"], "description": "Which parts of the GitHub API this component calls — selected areas'' endpoint reference is embedded in the build instructions"}, "authMode": {"type": "enum", "label": "Authentication", "default": "github-app", "options": ["github-app", "fine-grained-pat", "oauth-app"], "description": "GitHub App = short-lived installation tokens, org-installable (the integration default); fine-grained PAT = single-owner automation; OAuth app = acting as end users"}, "apiFlavor": {"type": "enum", "label": "API flavor", "default": "rest", "options": ["rest", "graphql", "both"]}}', '[{"id": "github-actions", "reason": "CI/CD product on the same platform — workflow runs this node can trigger and inspect via the actions area"}]', false, NULL, NULL, '2026-08-30 12:07:22.078198+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''256'':59C,169C ''access'':116C ''action'':10B,43B ''api'':6B,29B,191C ''app'':21B,49C,69C,93C,97C,113C,149C ''appid'':91C ''applic'':32B ''auth'':71C,90C ''authstrategi'':88C ''autom'':19B ''await'':104C ''bot'':18B ''call'':26B ''ci/cd'':33B ''const'':84C,101C ''consum'':183C ''content'':187C ''createappauth'':81C,89C ''crown'':155C ''dashboard'':17B ''data'':102C ''doubt'':163C ''eval'':201C ''event'':181C ''everi'':171C ''execut'':199C ''fetch'':188C ''fewest'':179C ''fine'':51C,139C ''fine-grain'':50C,138C ''github'':1A,2A,4B,20B,27B,38B,42B,48C,68C,112C ''github-act'':41B ''grain'':52C,140C ''graphql'':60C ''hub'':57C,167C ''id'':94C ''import'':64C,80C ''input'':196C ''instal'':70C,79C,120C,132C ''installationid'':100C ''instead'':45B ''integr'':7B,119C ''issues/prs'':9B ''jewel'':156C ''key'':99C,152C ''live'':74C,125C ''mere'':35B ''minimum'':143C ''new'':86C ''node'':23B,44B ''number'':109C ''octokit'':46C,65C,67C,85C,87C ''octokit.rest.pulls.get'':105C ''octokit/auth-app'':83C ''owner'':106C ''parti'':195C ''pat'':53C,134C ''per'':131C ''permiss'':146C ''person'':115C ''platform'':5B ''pr'':103C ''prefer'':110C ''privat'':98C,151C ''privatekey'':95C ''process.env.gh'':92C,96C ''product'':15B ''pull'':108C ''rememb'':185C ''repo'':107C,127C,186C ''repo-scop'':126C ''repositori'':8B,144C ''request'':177C ''rest'':62C ''revoc'':130C ''rotat'':160C ''run'':36B ''scope'':76C,128C,147C ''sdk'':47C ''secret'':157C,176C ''share'':175C ''short'':73C,124C ''short-liv'':72C,123C ''signatur'':58C,168C ''store'':158C ''third'':194C ''third-parti'':193C ''token'':75C,117C,121C,141C ''unavoid'':136C ''use'':137C ''v3'':63C ''v4'':61C ''verifi'':164C ''via'':189C ''webhook'':12B,54C,172C,180C ''x'':56C,166C ''x-hub-signatur'':55C,165C');
INSERT INTO public.technology_catalog VALUES ('anthropic', 'Anthropic Claude', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/anthropic.png', '#D97757', '["inference-service"]', '{"purpose": "LLM provider — the Claude 5 family via the Messages API: adaptive extended thinking, tool use with server-side web search/fetch, structured outputs, prompt caching, 1M-token context, and 50%-discount batch processing. Strong at long-document analysis, agentic tool orchestration and code generation. Consider OpenAI as the alternative frontier provider; the two are commonly abstracted behind one gateway interface.", "configMode": "external", "provenance": {"notes": "Phase B9 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Messages API", "claude-opus-5", "claude-sonnet-5", "adaptive thinking", "tool use", "prompt caching", "structured outputs", "Batches API", "official anthropic SDK"], "antiPatterns": ["Recalling pre-2026 API shapes from training data — thinking budgets and old tool-type versions have churned; verify against current docs", "Rebuilding what server tools provide (web search/fetch) as hand-rolled client tools", "Sending unchanging long context uncached on every request", "One mega-prompt where tool use + structured outputs would give a checkable pipeline", "Exposing API keys in frontend code"], "apiReference": {"areas": {"files": {"endpoints": ["`POST /v1/files` — upload once, reference by file_id in messages (documents, images)", "`GET /v1/files` · `DELETE /v1/files/{id}` — list and lifecycle"]}, "models": {"docsUrl": "https://platform.claude.com/docs/en/about-claude/models/overview", "endpoints": ["`claude-opus-5` — most capable (released 2026-07-24). 1M ctx; adaptive thinking; vision; full tool use incl. server-side web search/fetch; prompt caching; batches. $5/$25 per MTok. Long multi-step agentic work, deep research, hard reasoning", "`claude-sonnet-5` — production default (2026-06-30). 1M ctx; adaptive thinking; vision; server tools; $3/$15 per MTok (intro $2/$10 through 2026-08-31). Coding, review, extraction, tool orchestration — the right default for most production work", "`claude-haiku-4-5` — speed/cost tier. 200K ctx / 64K out; vision; tool use; $1/$5 per MTok. Extended thinking uses the pre-4.6 budget_tokens shape (NOT adaptive). Classification, routing, high-volume paths", "`claude-opus-4-8` — prior Opus flagship, still offered. 1M ctx / 128K out; adaptive thinking; $5/$25 per MTok", "`claude-opus-4-7` / `claude-opus-4-6` — earlier Opus 4.x, still offered (1M ctx; adaptive thinking; $5/$25). Note: Opus 4.7+ use a newer tokenizer producing ~30% more tokens for the same text — factor into cost estimates when migrating from 4.6", "`claude-sonnet-4-6` — prior Sonnet (1M ctx / 64K out; adaptive + extended thinking; $3/$15). Superseded by claude-sonnet-5 as the default", "Capability rules across the lineup: adaptive thinking on 4.6+ models (budget_tokens REJECTED there); server-side web search/fetch (the 20260209 tool versions) on Opus 4.6+ / Sonnet 4.6+; every listed model accepts text+image input; all support prompt caching, batches (50% discount) and structured outputs on current API revisions", "`GET /v1/models` — live listing; pin model IDs in ONE config point and verify at boot — this lineup turns over every few months"]}, "batches": {"endpoints": ["`POST /v1/messages/batches` — up to 100k requests, 50% discount, results within 24h", "`GET /v1/messages/batches/{id}` — poll processing_status; fetch results_url when ended"]}, "messages": {"endpoints": ["`POST /v1/messages` — the single generation endpoint (model, max_tokens, messages[], system); multimodal content blocks (text, image, document)", "Streaming: stream=true → SSE events (message_start, content_block_delta, message_stop)", "Prompt caching: cache_control {\"type\": \"ephemeral\"} on stable prefix blocks — cache-read tokens are ~10x cheaper", "1M-token context on Opus 5 / Sonnet 5; plan budgets, not maximums"]}, "tool-use": {"endpoints": ["tools[] with JSON-schema input_schema; loop on stop_reason=tool_use → execute → return tool_result blocks", "strict: true on a tool schema for validated parameters", "Server tools (run on provider infrastructure): web search + web fetch — declare in tools[], no execution loop on your side", "SDK tool runners automate the request→execute→loop cycle; hooks give approval gates and logging"]}, "utilities": {"endpoints": ["`POST /v1/messages/count_tokens` — pre-flight token counting for budget checks (free)", "`GET /v1/models` — live model listing/capability discovery; pin IDs in config, verify at boot"]}, "thinking-and-outputs": {"endpoints": ["Adaptive thinking: thinking {\"type\": \"adaptive\"} — the model decides when/how much to reason; budget_tokens is deprecated/rejected on Claude 5 models", "Effort control: output_config {\"effort\": \"low|medium|high|max\"} tunes depth vs cost", "Structured outputs: output_config {\"format\": {json_schema}} — validated typed responses", "Thinking blocks arrive as separate content blocks; render or drop deliberately"]}}, "docsUrl": "https://platform.claude.com/docs/en/api"}, "bestPractices": ["Everything goes through POST /v1/messages — tools, thinking and output constraints are features of this one endpoint, not separate APIs", "Use adaptive thinking ({\"type\": \"adaptive\"}) for anything non-trivial; do not carry budget_tokens forward — Claude 5 models reject it", "Prompt caching (cache_control on stable prefix blocks) for repeated system prompts and long shared context — order content stable-first so the prefix hits", "Stream by default; use the SDK final-message helper when you only need the complete response", "Structured outputs (output_config.format) for typed extraction instead of parse-and-pray", "Batches API for async workloads — 50% cost reduction", "Keep API keys server-side; handle 429/529 with exponential backoff"], "sdkInitPattern": "import Anthropic from ''@anthropic-ai/sdk'';\n\nconst anthropic = new Anthropic(); // ANTHROPIC_API_KEY from env\nconst message = await anthropic.messages.create({\n  model: ''claude-sonnet-5'',\n  max_tokens: 1024,\n  messages: [{ role: ''user'', content: prompt }],\n});", "securityGuidance": "API keys are server-side only — a key in client code is an open meter and an open data channel; proxy all model calls through your backend with per-user rate limits and cost ceilings. User input and any retrieved/tool content entering prompts is untrusted (prompt injection is the standard attack), so treat model output as untrusted too: never eval it, and validate tool-use arguments before executing them against real systems. Log usage metadata, not full prompts, unless your data policy explicitly covers conversation retention.", "setupInstructions": [{"url": "https://console.anthropic.com", "type": "account_setup", "title": "Create an API key", "required": true, "instructions": "In the Claude Console, create an API key under the appropriate workspace so usage and spend are attributable."}, {"type": "environment_variable", "title": "Store the key as configuration", "required": true, "instructions": "Provide ANTHROPIC_API_KEY via server-side environment configuration; set spend limits in the console."}]}', '[{"kind": "source", "path": "src/ai/anthropic-client.ts", "priority": "essential", "description": "Anthropic client setup and configuration"}, {"kind": "source", "path": "src/ai/prompts/", "priority": "essential", "description": "System prompts and templates"}, {"kind": "source", "path": "src/ai/tools.ts", "priority": "recommended", "description": "Tool use definitions and handlers"}]', '{"model": {"type": "enum", "label": "Model", "default": "claude-opus-5", "options": ["claude-opus-5", "claude-sonnet-5", "claude-haiku-4-5", "claude-opus-4-8", "claude-opus-4-7", "claude-opus-4-6", "claude-sonnet-4-6"], "required": true, "description": "Current lineup (2026-07): claude-opus-5 = most capable (2026-07-24); claude-sonnet-5 = production default balancing intelligence and cost; claude-haiku-4-5 = high-volume tier. Prior Opus 4.x / Sonnet 4.6 remain offered for pinned workloads. Per-model capabilities: select the models area in API areas"}, "apiAreas": {"type": "multiselect", "label": "Anthropic API areas used", "options": ["messages", "thinking-and-outputs", "tool-use", "batches", "files", "utilities", "models"], "description": "Which parts of the Anthropic API this component calls — selected areas'' endpoint reference is embedded in the build instructions (the models area = the per-model capability matrix)"}, "thinking": {"type": "enum", "label": "Extended thinking", "default": "adaptive", "options": ["adaptive", "off"], "description": "adaptive lets the model decide when/how much to reason — the current API shape on Claude 5 models (budget_tokens is rejected there)"}, "streaming": {"type": "boolean", "label": "Streaming responses", "default": true, "description": "SSE streaming — an architecture choice (API route + UI), and the way to avoid timeouts on long generations"}}', '["backend-service", "worker"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', 'Anthropic', '#B86245', '''/sdk'':95C ''1024'':116C ''1m'':30B ''1m-token'':29B ''5'':8B,71C,75C,113C ''50'':34B ''abstract'':61B ''adapt'':14B,76C ''agent'':44B ''ai'':94C ''altern'':54B ''analysi'':43B ''anthrop'':1A,3A,87C,90C,93C,97C,99C,100C ''anthropic-ai'':92C ''anthropic.messages.create'':108C ''api'':13B,67C,85C,101C,122C ''argument'':190C ''attack'':174C ''await'':107C ''backend'':149C ''batch'':36B,84C ''behind'':62B ''cach'':28B,81C ''call'':146C ''ceil'':158C ''channel'':142C ''claud'':2A,7B,69C,73C,111C ''claude-opus'':68C ''claude-sonnet'':72C,110C ''client'':132C ''code'':48B,133C ''common'':60B ''consid'':50B ''const'':96C,105C ''content'':120C,164C ''context'':32B ''convers'':209C ''cost'':157C ''cover'':208C ''data'':141C,205C ''discount'':35B ''document'':42B ''enter'':165C ''env'':104C ''eval'':183C ''execut'':192C ''explicit'':207C ''extend'':15B ''famili'':9B ''frontier'':55B ''full'':201C ''gateway'':64B ''generat'':49B ''import'':89C ''inject'':170C ''input'':160C ''interfac'':65B ''key'':102C,123C,130C ''limit'':155C ''llm'':4B ''log'':197C ''long'':41B ''long-docu'':40B ''max'':114C ''messag'':12B,66C,106C,117C ''metadata'':199C ''meter'':137C ''model'':109C,145C,177C ''never'':182C ''new'':98C ''offici'':86C ''one'':63B ''open'':136C,140C ''openai'':51B ''opus'':70C ''orchestr'':46B ''output'':26B,83C,178C ''per'':152C ''per-us'':151C ''polici'':206C ''process'':37B ''prompt'':27B,80C,121C,166C,169C,202C ''provid'':5B,56B ''proxi'':143C ''rate'':154C ''real'':195C ''retent'':210C ''retrieved/tool'':163C ''role'':118C ''sdk'':88C ''search/fetch'':24B ''server'':21B,126C ''server-sid'':20B,125C ''side'':22B,127C ''sonnet'':74C,112C ''standard'':173C ''strong'':38B ''structur'':25B,82C ''system'':196C ''think'':16B,77C ''token'':31B,115C ''tool'':17B,45B,78C,188C ''tool-us'':187C ''treat'':176C ''two'':58B ''unless'':203C ''untrust'':168C,180C ''usag'':198C ''use'':18B,79C,189C ''user'':119C,153C,159C ''valid'':186C ''via'':10B ''web'':23B');
INSERT INTO public.technology_catalog VALUES ('sendgrid', 'Twilio SendGrid', NULL, '#6b7280', '["external-service"]', '{"purpose": "Email delivery service (Twilio SendGrid) for transactional and marketing email at volume — v3 Mail Send, dynamic Handlebars templates, marketing lists and the signed Event Webhook. NOTE: no free tier since May 2025 (entry is the paid Essentials plan) — for low-volume transactional email on a budget, Resend is the common alternative; SendGrid''s strengths are volume, marketing tooling and deliverability tooling at scale.", "configMode": "external", "provenance": {"notes": "Phase B9 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Node.js", "Python", "SMTP", "REST API"], "antiPatterns": ["Sending from unverified domains", "Ignoring bounce notifications", "Using a single API key for all environments", "Not setting up domain authentication before production"], "apiReference": {"areas": {"mail-send": {"docsUrl": "https://www.twilio.com/docs/sendgrid/api-reference/mail-send/mail-send", "endpoints": ["`POST https://api.sendgrid.com/v3/mail/send` — bearer API-key auth; personalizations[] (per-recipient to/substitutions), from (authenticated domain), content or template_id", "202 = accepted for delivery (not delivered) — actual outcomes arrive via the Event Webhook", "Sandbox mode (mail_settings.sandbox_mode) for tests — validates without sending"]}, "event-webhook": {"endpoints": ["Signed Event Webhook posts delivery events: processed, delivered, bounce, dropped, spamreport, open, click", "Verify the signature (ECDSA public key from settings) before trusting events", "Feed bounce/spamreport into suppression handling; SendGrid also maintains its own suppression lists (/v3/suppression/*)"]}, "inbound-parse": {"endpoints": ["Inbound Parse posts inbound email (MX → parse webhook) to your endpoint as multipart form data", "Use for reply-by-email features; validate the destination domain setup in DNS"]}, "dynamic-templates": {"endpoints": ["Template IDs starting d- are dynamic templates; pass per-recipient data as personalizations[].dynamic_template_data", "Handlebars syntax in templates ({{name}}, conditionals, iterations); manage versions in the UI, reference by ID in code", "Keep template data flat and typed — deep nesting is where template bugs live"]}, "marketing-contacts": {"endpoints": ["`PUT /v3/marketing/contacts` — upsert contacts (async job); lists via /v3/marketing/lists", "`POST /v3/marketing/singlesends` — campaign sends against lists/segments", "Marketing sends have separate unsubscribe handling from transactional — do not mix pipelines"]}}, "docsUrl": "https://www.twilio.com/docs/sendgrid/api-reference"}, "bestPractices": ["Authenticate your sending domain with SPF and DKIM", "Use dynamic templates for consistent emails", "Monitor bounce and complaint rates", "Implement unsubscribe handling for marketing emails"], "sdkInitPattern": "import sgMail from ''@sendgrid/mail'';\n\nsgMail.setApiKey(process.env.SENDGRID_API_KEY);\nawait sgMail.send({\n  from: ''no-reply@example.com'', // an authenticated sender domain\n  to: userEmail,\n  subject: ''Welcome'',\n  html: welcomeHtml,\n});", "securityGuidance": "Create API keys with the narrowest permission set (Mail Send only for the app) — a full-access key can read suppression lists and rewrite account settings. Authenticate your sending domain (SPF + DKIM + DMARC) or deliverability and spoofing-resistance both suffer. Verify the signed Event Webhook signature before trusting delivery/bounce events, process bounces and spam reports (sender reputation is an asset), and never interpolate unsanitized user content into HTML mail.", "setupInstructions": [{"url": "https://signup.sendgrid.com/", "type": "account_setup", "title": "Create SendGrid Account", "required": true, "instructions": "Sign up at sendgrid.com. The free tier includes 100 emails/day. Upgrade for higher volume."}, {"type": "dashboard_config", "title": "Verify Sender Identity", "required": true, "instructions": "Under Settings > Sender Authentication, either verify a single sender email or authenticate your entire domain (recommended for production). Domain authentication adds SPF and DKIM records."}, {"type": "permissions", "title": "Create API Key", "required": true, "instructions": "In Settings > API Keys > Create API Key. Select Restricted Access and grant only Mail Send permission. Name it descriptively (e.g., production-transactional)."}, {"type": "dns_config", "title": "Set Up Domain Authentication", "required": false, "instructions": "Under Sender Authentication > Domain Authentication, add CNAME records to your DNS. This improves deliverability and prevents emails landing in spam."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export SENDGRID_API_KEY=SG...", "export SENDGRID_FROM_EMAIL=noreply@yourdomain.com"], "required": true, "instructions": "Add SendGrid credentials to your application environment."}]}', '[]', '{"apiAreas": {"type": "multiselect", "label": "SendGrid API areas used", "options": ["mail-send", "dynamic-templates", "marketing-contacts", "event-webhook", "inbound-parse"], "description": "Which parts of the SendGrid API this component calls — selected areas'' endpoint reference is embedded in the build instructions"}, "emailKinds": {"type": "multiselect", "label": "Email kinds", "options": ["transactional", "marketing"], "description": "Different suppression rules and sender reputation handling per kind"}, "domainAuthenticated": {"type": "boolean", "label": "Domain authentication done", "default": false, "description": "SPF + DKIM domain authentication is a hard prerequisite for production deliverability — a console task, not code"}}', '[]', false, NULL, NULL, '2026-05-18 02:35:27.802569+00', '2026-08-30 12:07:23.877005+00', 'SendGrid', NULL, '''2025'':35B ''access'':112C ''account'':120C ''altern'':55B ''api'':72C,79C,96C ''app'':108C ''asset'':156C ''authent'':86C,122C ''await'':81C ''bounc'':148C ''budget'':50B ''common'':54B ''content'':162C ''creat'':95C ''deliver'':64B,130C ''deliveri'':5B ''delivery/bounce'':145C ''dkim'':127C ''dmarc'':128C ''domain'':88C,125C ''dynam'':19B ''email'':4B,13B,47B ''entri'':36B ''essenti'':40B ''event'':27B,140C,146C ''free'':31B ''full'':111C ''full-access'':110C ''handlebar'':20B ''html'':93C,164C ''import'':73C ''interpol'':159C ''key'':80C,97C,113C ''list'':23B,117C ''low'':44B ''low-volum'':43B ''mail'':17B,103C,165C ''market'':12B,22B,61B ''may'':34B ''narrowest'':100C ''never'':158C ''no-reply@example.com'':84C ''node.js'':68C ''note'':29B ''paid'':39B ''permiss'':101C ''plan'':41B ''process'':147C ''process.env.sendgrid'':78C ''python'':69C ''read'':115C ''report'':151C ''reput'':153C ''resend'':51B ''resist'':134C ''rest'':71C ''rewrit'':119C ''scale'':67B ''send'':18B,104C,124C ''sender'':87C,152C ''sendgrid'':2A,3A,8B,56B ''sendgrid/mail'':76C ''servic'':6B ''set'':102C,121C ''sgmail'':74C ''sgmail.send'':82C ''sgmail.setapikey'':77C ''sign'':26B,139C ''signatur'':142C ''sinc'':33B ''smtp'':70C ''spam'':150C ''spf'':126C ''spoof'':133C ''spoofing-resist'':132C ''strength'':58B ''subject'':91C ''suffer'':136C ''suppress'':116C ''templat'':21B ''tier'':32B ''tool'':62B,65B ''transact'':10B,46B ''trust'':144C ''twilio'':1A,7B ''unsanit'':160C ''user'':161C ''useremail'':90C ''v3'':16B ''verifi'':137C ''volum'':15B,45B,60B ''webhook'':28B,141C ''welcom'':92C ''welcomehtml'':94C');
INSERT INTO public.technology_catalog VALUES ('kotlin-backend', 'Kotlin (Backend)', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/kotlin-android.png', '#7F52FF', '["backend-service", "worker", "webhook-handler"]', '{"purpose": "Modern JVM language combining conciseness and safety for building backend services with coroutines-first concurrency and full Java interoperability", "configMode": "code", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Kotlin 2.0+", "Ktor", "Spring Boot", "Exposed/Ktorm", "Coroutines", "Koin/Hilt", "Gradle Kotlin DSL", "kotest"], "antiPatterns": ["Using GlobalScope for coroutine launches", "Not using structured concurrency", "Overusing nullable types when non-null is appropriate", "Ignoring Kotlin idioms and writing Java-style code", "Not cancelling coroutine scopes properly", "Using mutable collections when immutable ones suffice"], "apiReference": {"docsUrl": "https://kotlinlang.org/docs/"}, "bestPractices": ["Use Kotlin coroutines for async and concurrent programming", "Leverage data classes for DTOs and domain models", "Use sealed classes for exhaustive state modeling", "Implement dependency injection with Koin or Spring", "Use Ktor for lightweight, coroutine-native HTTP services", "Leverage extension functions for clean API design", "Use Flow for reactive streams", "Write tests with kotest and MockK"], "sdkInitPattern": "fun main() {\n    embeddedServer(Netty, port = 8080) {\n        install(ContentNegotiation) { json() }\n        install(Authentication) { jwt { /* verifier + validate */ } }\n        routing {\n            authenticate {\n                get(\"/api/orders\") {\n                    val userId = call.principal<JWTPrincipal>()!!.subject\n                    call.respond(orderService.listFor(userId))\n                }\n            }\n        }\n    }.start(wait = true)\n}", "securityGuidance": "Type safety is not input safety: validate and bound request payloads at the boundary (kotlinx.serialization with explicit models), scope every data access by the authenticated principal, and use parameterized queries through Exposed/JDBC — string templates into SQL are injection with nicer syntax. Coroutine contexts must not smuggle authority across requests (never cache a principal in a shared scope), secrets resolve from environment config, and the JVM supply-chain discipline applies: scanned, pinned dependencies."}', '[{"kind": "source", "path": "src/main/kotlin/Application.kt", "language": "kotlin", "description": "Application entry point"}, {"kind": "source", "path": "src/main/kotlin/routes/Routes.kt", "language": "kotlin", "description": "Route definitions"}, {"kind": "config", "path": "build.gradle.kts", "language": "kotlin", "description": "Gradle Kotlin DSL build file"}, {"kind": "config", "path": "src/main/resources/application.conf", "language": "hocon", "description": "Ktor/application configuration"}]', '{"buildTool": {"type": "enum", "label": "Build tool", "default": "gradle-kotlin-dsl", "options": ["gradle-kotlin-dsl", "maven"]}, "framework": {"type": "enum", "label": "Framework", "default": "spring-boot", "options": ["spring-boot", "ktor"], "description": "Spring Boot for teams on the Spring ecosystem; Ktor for Kotlin-native coroutine-first services"}}', '["database", "cache", "message-broker"]', false, NULL, NULL, '2026-03-31 14:00:38.405595+00', '2026-08-30 12:07:23.877005+00', 'Kotlin', NULL, '''/api/orders'':54C ''2.0'':26C ''8080'':42C ''access'':86C ''across'':112C ''appli'':134C ''authent'':47C,52C,89C ''author'':111C ''backend'':2A,4A,14B ''boot'':29C ''bound'':73C ''boundari'':78C ''build'':13B ''cach'':115C ''call.principal'':57C ''call.respond'':59C ''chain'':132C ''combin'':8B ''concis'':9B ''concurr'':20B ''config'':126C ''contentnegoti'':44C ''context'':107C ''coroutin'':18B,31C,106C ''coroutines-first'':17B ''data'':85C ''depend'':137C ''disciplin'':133C ''dsl'':35C ''embeddedserv'':39C ''environ'':125C ''everi'':84C ''explicit'':81C ''exposed/jdbc'':96C ''exposed/ktorm'':30C ''first'':19B ''full'':22B ''fun'':37C ''get'':53C ''gradl'':33C ''inject'':102C ''input'':69C ''instal'':43C,46C ''interoper'':24B ''java'':23B ''json'':45C ''jvm'':6B,129C ''jwt'':48C ''koin/hilt'':32C ''kotest'':36C ''kotlin'':1A,3A,25C,34C ''kotlinx.serialization'':79C ''ktor'':27C ''languag'':7B ''main'':38C ''model'':82C ''modern'':5B ''must'':108C ''netti'':40C ''never'':114C ''nicer'':104C ''orderservice.listfor'':60C ''parameter'':93C ''payload'':75C ''pin'':136C ''port'':41C ''princip'':90C,117C ''queri'':94C ''request'':74C,113C ''resolv'':123C ''rout'':51C ''safeti'':11B,66C,70C ''scan'':135C ''scope'':83C,121C ''secret'':122C ''servic'':15B ''share'':120C ''smuggl'':110C ''spring'':28C ''sql'':100C ''start'':62C ''string'':97C ''subject'':58C ''suppli'':131C ''supply-chain'':130C ''syntax'':105C ''templat'':98C ''true'':64C ''type'':65C ''use'':92C ''userid'':56C,61C ''val'':55C ''valid'':50C,71C ''verifi'':49C ''wait'':63C');
INSERT INTO public.technology_catalog VALUES ('php-backend', 'PHP', NULL, '#777BB4', '["backend-service", "webhook-handler", "cli-tool"]', '{"purpose": "Server-side language powering a huge share of the production web. Modern PHP (8.4/8.5 era) is typed, fast and framework-driven: Laravel (current major: 13, 2026-02) is the default choice for product work — full-stack conventions, Eloquent ORM, queues, scheduling; Symfony for component-driven architectures. Serve via php-fpm (the boring default) or FrankenPHP + Octane where high concurrency pays.", "configMode": "code", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Laravel 13", "Composer", "Eloquent ORM", "PHPStan", "Pest/PHPUnit", "php-fpm", "FrankenPHP + Octane", "Horizon queues"], "antiPatterns": ["Writing 2010-era PHP (no types, raw superglobals, include-based routing) — an AI generating legacy-style PHP is producing liability", "Composer dependencies without a committed lock file", "Long-running state in Octane/FrankenPHP workers without resetting per-request state — the classic share-nothing assumption no longer holds there", "Hand-rolled auth/password handling when the framework ships hardened primitives"], "apiReference": {"docsUrl": "https://www.php.net/docs.php"}, "bestPractices": ["Laravel unless there is a reason not to — conventions, first-party packages (queues, auth, billing) and the largest hiring pool", "composer.lock committed; declare the PHP version in composer.json require.php and pin the runtime image to it", "Static analysis from day one (PHPStan or Psalm at a meaningful level) — modern PHP is typed, use it", "Queues for anything slow (Laravel queues + Horizon); HTTP requests do not send emails or call slow third parties inline", "FrankenPHP + Octane for high-concurrency deployments — but the octane:install static binary is PHP-8.4-locked; match the binary to the app''s PHP version deliberately"], "sdkInitPattern": "<?php\ndeclare(strict_types=1);\n\n$pdo = new PDO($_ENV[''DATABASE_DSN''], $_ENV[''DB_USER''], $_ENV[''DB_PASS''], [\n    PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,\n    PDO::ATTR_EMULATE_PREPARES => false,\n]);\n\n$stmt = $pdo->prepare(''SELECT * FROM orders WHERE owner_id = :owner'');\n$stmt->execute([''owner'' => $userId]);\n$orders = $stmt->fetchAll(PDO::FETCH_ASSOC);", "securityGuidance": "PDO prepared statements with emulation off — string-built SQL is the canonical PHP breach. Never unserialize() untrusted input (object injection is RCE; use JSON), never pass user input to include/require paths or shell functions (escapeshellarg if unavoidable), and htmlspecialchars on output unless a template engine escapes by default. password_hash/password_verify for credentials, session cookies HttpOnly+Secure+SameSite with session_regenerate_id on login, uploads validated by content and stored outside the web root, and display_errors off in production."}', '[{"kind": "config", "path": "composer.json"}, {"kind": "source", "path": "app/Http/Controllers/"}, {"kind": "source", "path": "routes/web.php"}, {"kind": "config", "path": "phpstan.neon"}]', '{"serving": {"type": "enum", "label": "Serving model", "default": "php-fpm", "options": ["php-fpm", "frankenphp-octane"], "description": "php-fpm = the boring share-nothing default; FrankenPHP+Octane = persistent workers for high concurrency (state-reset discipline required)"}, "framework": {"type": "enum", "label": "Framework", "default": "laravel", "options": ["laravel", "symfony", "plain-php"], "description": "Laravel is the product-work default; Symfony for component-driven builds; plain PHP only for tiny scripts"}, "staticAnalysis": {"type": "enum", "label": "Static analysis", "default": "phpstan", "options": ["phpstan", "psalm", "none"]}}', '[{"id": "postgresql", "reason": "Primary relational store via Eloquent/Doctrine"}, {"id": "redis", "reason": "Queues, cache and session store"}, {"id": "stripe", "reason": "Laravel Cashier is the standing billing integration"}]', false, NULL, NULL, '2026-08-30 12:07:22.11799+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''-02'':33B ''/8.5'':19B ''1'':88C ''13'':31B,71C ''2026'':32B ''8.4'':18B ''architectur'':54B ''assoc'':131C ''attr'':102C,108C ''backend'':3A ''bore'':61B ''breach'':146C ''built'':140C ''canon'':144C ''choic'':37B ''compon'':52B ''component-driven'':51B ''compos'':72C ''concurr'':68B ''content'':199C ''convent'':44B ''cooki'':186C ''credenti'':184C ''current'':29B ''databas'':93C ''db'':96C,99C ''declar'':85C ''default'':36B,62B,180C ''display'':207C ''driven'':27B,53B ''dsn'':94C ''eloqu'':45B,73C ''emul'':109C,136C ''engin'':177C ''env'':92C,95C,98C ''era'':20B ''errmod'':103C,105C ''error'':208C ''escap'':178C ''escapeshellarg'':167C ''except'':106C ''execut'':123C ''fals'':111C ''fast'':23B ''fetch'':130C ''fetchal'':128C ''fpm'':59B,79C ''framework'':26B ''framework-driven'':25B ''frankenphp'':64B,80C ''full'':42B ''full-stack'':41B ''function'':166C ''hash/password_verify'':182C ''high'':67B ''horizon'':82C ''htmlspecialchar'':171C ''httpon'':187C ''huge'':10B ''id'':120C,193C ''include/require'':162C ''inject'':152C ''input'':150C,160C ''json'':156C ''languag'':7B ''laravel'':28B,70C ''login'':195C ''major'':30B ''modern'':16B ''never'':147C,157C ''new'':90C ''object'':151C ''octan'':65B,81C ''order'':117C,126C ''orm'':46B,74C ''output'':173C ''outsid'':202C ''owner'':119C,121C,124C ''pass'':100C,158C ''password'':181C ''path'':163C ''pay'':69B ''pdo'':89C,91C,101C,104C,107C,113C,129C,132C ''pest/phpunit'':76C ''php'':1A,2A,17B,58B,78C,84C,145C ''php-fpm'':57B,77C ''phpstan'':75C ''power'':8B ''prepar'':110C,114C,133C ''product'':14B,39B,211C ''queue'':47B,83C ''rce'':154C ''regener'':192C ''root'':205C ''samesit'':189C ''schedul'':48B ''secur'':188C ''select'':115C ''serv'':55B ''server'':5B ''server-sid'':4B ''session'':185C,191C ''share'':11B ''shell'':165C ''side'':6B ''sql'':141C ''stack'':43B ''statement'':134C ''stmt'':112C,122C,127C ''store'':201C ''strict'':86C ''string'':139C ''string-built'':138C ''symfoni'':49B ''templat'':176C ''type'':22B,87C ''unavoid'':169C ''unless'':174C ''unseri'':148C ''untrust'':149C ''upload'':196C ''use'':155C ''user'':97C,159C ''userid'':125C ''valid'':197C ''via'':56B ''web'':15B,204C ''work'':40B');
INSERT INTO public.technology_catalog VALUES ('python-backend', 'Python', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/python-backend.png', '#3776ab', '["backend-service", "worker", "ml-pipeline", "inference-service", "webhook-handler", "cli-tool", "shared-library"]', '{"purpose": "The default language for data/ML-adjacent backends and a first-class choice for typed API services (FastAPI + Pydantic). Spans API services, workers, ML pipelines, inference services, webhook handlers and CLIs — when the component touches the data/ML ecosystem, Python is usually the honest pick.", "configMode": "code", "provenance": {"notes": "Stable stack facts (uv consolidation, FastAPI/Pydantic defaults); live-docs upgrade rides N10(b). Row previously had EMPTY ai_context.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["FastAPI + Pydantic", "uv", "ruff", "pyright", "pytest", "SQLAlchemy/SQLModel", "Celery/arq", "httpx"], "antiPatterns": ["Blocking I/O inside async routes (sync DB drivers, requests) — kills the event loop invisibly", "requirements.txt without pins in a production service", "Django for a pure JSON API where FastAPI is lighter — Django earns its weight only when the admin/ORM/auth batteries are used", "Global mutable module state as a cache — breaks under multiple workers"], "apiReference": {"docsUrl": "https://docs.python.org/3/"}, "bestPractices": ["Type hints everywhere + Pydantic models at every boundary — FastAPI turns them into validation and OpenAPI for free", "uv for env + deps (committed lockfile, pinned python version); one venv per service", "Async where the framework is async — mixing blocking calls (requests, raw psycopg) into async handlers is the classic FastAPI foot-gun; use httpx/asyncpg", "Workers: Celery or arq with explicit idempotency — Python queue consumers WILL be redelivered", "ruff for lint+format (one tool), pytest with fixtures over unittest classes"], "sdkInitPattern": "pip install fastapi uvicorn sqlalchemy pydantic-settings\\n# main.py\\nfrom fastapi import FastAPI\\napp = FastAPI()\\n\\n@app.get(\"/health\")\\ndef health(): return {\"status\": \"ok\"}\\n\\n# uvicorn main:app --reload", "securityGuidance": "Use Pydantic models for automatic input validation on all endpoints. Use parameterized queries via SQLAlchemy ORM, never raw string interpolation. Set CORS middleware with explicit allowed origins. Use python-jose or PyJWT for JWT validation. Pin dependencies and use pip-audit for vulnerability scanning. Never run uvicorn with --reload in production.", "commonApiPatterns": [{"name": "REST Endpoint", "description": "FastAPI endpoint with dependency injection and response model", "codeTemplate": "@app.get(\"/api/users/{user_id}\", response_model=UserResponse)\\nasync def get_user(user_id: int, db: AsyncSession = Depends(get_db)):\\n    user = await db.get(User, user_id)\\n    if not user:\\n        raise HTTPException(status_code=404, detail=\"User not found\")\\n    return user"}, {"name": "Dependency Injection", "description": "Composable dependency chain for DB sessions and auth", "codeTemplate": "async def get_db() -> AsyncGenerator[AsyncSession, None]:\\n    async with async_session() as session:\\n        yield session\\n\\nasync def get_current_user(token: str = Depends(oauth2_scheme), db: AsyncSession = Depends(get_db)) -> User:\\n    payload = verify_token(token)\\n    return await db.get(User, payload[\"sub\"])"}, {"name": "Background Task", "description": "Celery task for async background processing", "codeTemplate": "from celery import Celery\\ncelery_app = Celery(\"tasks\", broker=\"redis://localhost:6379\")\\n\\n@celery_app.task\\ndef send_email(to: str, subject: str, body: str):\\n    smtp_client.send(to=to, subject=subject, body=body)"}], "integrationPatterns": ["FastAPI or Flask for HTTP framework with automatic OpenAPI docs", "SQLAlchemy 2.0 with asyncio for async database access", "Celery or ARQ for distributed task queues", "Pydantic for data validation and settings management", "pytest with httpx.AsyncClient for async API testing"], "configurationTemplate": "# pyproject.toml\\n[project]\\nname = \"myapp\"\\nversion = \"1.0.0\"\\nrequires-python = \">=3.11\"\\ndependencies = [\\n    \"fastapi>=0.110.0\",\\n    \"uvicorn[standard]>=0.27.0\",\\n    \"sqlalchemy[asyncio]>=2.0.0\",\\n    \"pydantic-settings>=2.0.0\",\\n]\\n\\n[tool.ruff]\\ntarget-version = \"py311\"\\nselect = [\"E\", \"F\", \"I\", \"UP\"]\\n\\n[tool.mypy]\\nstrict = true\\nplugins = [\"pydantic.mypy\"]"}', '[{"kind": "source", "path": "src/main.py", "language": "python", "description": "Application entry point"}, {"kind": "source", "path": "src/routes/__init__.py", "language": "python", "description": "Route definitions"}, {"kind": "config", "path": "pyproject.toml", "language": "toml", "description": "Python project manifest"}]', '{"framework": {"type": "enum", "label": "Framework", "default": "fastapi", "options": ["fastapi", "django", "flask", "none-script"], "description": "FastAPI = typed async APIs (the default for services); Django = batteries-included product apps with admin; Flask = small and legacy codebases"}, "packaging": {"type": "enum", "label": "Packaging / env", "default": "uv", "options": ["uv", "poetry", "pip-requirements"], "description": "uv is the 2026 default (fast, lockfile, python-version management in one tool); poetry legacy-fine; bare requirements.txt only for throwaway scripts"}, "typeChecking": {"type": "enum", "label": "Type checking", "default": "pyright", "options": ["pyright", "mypy", "none"]}}', '["database", "cache", "message-broker", "ai-service"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', 'Python', '#2D5F89', '''/health'':74C ''allow'':111C ''api'':18B,23B ''app'':84C ''audit'':128C ''automat'':90C ''backend'':3A,9B ''celery/arq'':54C ''choic'':15B ''class'':14B ''clis'':33B ''compon'':36B ''cor'':107C ''data/ml'':39B ''data/ml-adjacent'':8B ''default'':5B ''depend'':123C ''ecosystem'':40B ''endpoint'':95C ''explicit'':110C ''fastapi'':20B,47C,58C,67C,69C,71C ''first'':13B ''first-class'':12B ''handler'':31B ''health'':76C ''honest'':45B ''httpx'':55C ''import'':68C ''infer'':28B ''input'':91C ''instal'':57C ''interpol'':105C ''jose'':116C ''jwt'':120C ''languag'':6B ''main'':83C ''main.py'':65C ''middlewar'':108C ''ml'':26B ''model'':88C ''n'':64C,72C,80C,81C ''n@app.get'':73C ''napp'':70C ''ndef'':75C ''never'':102C,132C ''nfrom'':66C ''ok'':79C ''origin'':112C ''orm'':101C ''parameter'':97C ''pick'':46B ''pin'':122C ''pip'':56C,127C ''pip-audit'':126C ''pipelin'':27B ''product'':138C ''pydant'':21B,48C,62C,87C ''pydantic-set'':61C ''pyjwt'':118C ''pyright'':51C ''pytest'':52C ''python'':1A,2A,41B,115C ''python-jos'':114C ''queri'':98C ''raw'':103C ''reload'':85C,136C ''return'':77C ''ruff'':50C ''run'':133C ''scan'':131C ''servic'':19B,24B,29B ''set'':63C,106C ''span'':22B ''sqlalchemi'':60C,100C ''sqlalchemy/sqlmodel'':53C ''status'':78C ''string'':104C ''touch'':37B ''type'':17B ''use'':86C,96C,113C,125C ''usual'':43B ''uv'':49C ''uvicorn'':59C,82C,134C ''valid'':92C,121C ''via'':99C ''vulner'':130C ''webhook'':30B ''worker'':25B');
INSERT INTO public.technology_catalog VALUES ('docker', 'Docker', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/docker.png', '#2496ed', '["docker-container", "docker-compose"]', '{"purpose": "Container platform for building, shipping, and running applications in isolated environments with consistent deployment", "configMode": "definition-as-code", "provenance": {"notes": "docsUrl is the vendor''s canonical documentation root, stamped from model knowledge and checked by scripts/n10-verify-docs-urls.ts; pre-existing body content not yet live-docs verified — upgrade at this row''s enrichment chunk.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Docker Engine", "Docker Compose", "Dockerfile", "Docker Hub", "BuildKit"], "antiPatterns": ["Using latest tag in production causing unpredictable deployments", "Running containers as root without security justification", "Copying entire build context by skipping .dockerignore", "Installing dev dependencies in production images", "Storing secrets or credentials in image layers or ENV instructions"], "apiReference": {"docsUrl": "https://docs.docker.com/"}, "bestPractices": ["Use multi-stage builds to reduce image size", "Use specific base image tags (not latest)", "Implement proper health checks", "Use .dockerignore to exclude unnecessary files", "Run as non-root user", "Use COPY instead of ADD", "Implement proper layer caching", "Use docker compose for local development"], "sdkInitPattern": "# Dockerfile\\nFROM node:20-alpine AS builder\\nWORKDIR /app\\nCOPY package*.json ./\\nRUN npm ci\\nCOPY . .\\nRUN npm run build\\n\\nFROM node:20-alpine\\nWORKDIR /app\\nCOPY --from=builder /app/dist ./dist\\nCOPY --from=builder /app/node_modules ./node_modules\\nUSER node\\nEXPOSE 3000\\nCMD [\"node\", \"dist/index.js\"]", "securityGuidance": "Always run containers as a non-root user (USER directive). Use minimal base images (alpine, distroless). Never store secrets in images or environment variables in Dockerfiles -- use runtime secret injection. Scan images for vulnerabilities with Trivy or Snyk. Pin base image versions by digest for reproducibility. Set read-only root filesystem where possible. Do not install unnecessary packages in production images.", "commonApiPatterns": [{"name": "Build Image", "description": "Build a production image using a multi-stage Dockerfile", "codeTemplate": "docker build -t myapp:latest --target production -f Dockerfile ."}, {"name": "Docker Compose", "description": "Local development stack with app and database", "codeTemplate": "services:\\n  app:\\n    build: .\\n    ports: [\"3000:3000\"]\\n    environment:\\n      - DATABASE_URL=postgres://user:pass@db:5432/mydb\\n    depends_on:\\n      db: { condition: service_healthy }\\n  db:\\n    image: postgres:16-alpine\\n    volumes: [\"pgdata:/var/lib/postgresql/data\"]\\n    healthcheck:\\n      test: [\"CMD-SHELL\", \"pg_isready\"]\\nvolumes:\\n  pgdata:"}, {"name": "Push to Registry", "description": "Tag and push image to a container registry", "codeTemplate": "docker tag myapp:latest registry.example.com/myapp:v1.0.0 && docker push registry.example.com/myapp:v1.0.0"}], "setupInstructions": [{"url": "https://docs.docker.com/engine/install/", "type": "toolchain_install", "title": "Install Docker Engine", "commands": ["curl -fsSL https://get.docker.com | sh", "sudo usermod -aG docker $USER"], "required": true, "instructions": "Install Docker Engine on your development machine and any deployment targets."}, {"type": "dashboard_config", "title": "Configure Docker Registry", "commands": ["docker login"], "required": true, "instructions": "Set up access to a container registry (Docker Hub, ECR, GCR, or self-hosted) for pushing and pulling images."}], "integrationPatterns": ["Container registries (Docker Hub, ECR, ACR, GAR) for image distribution", "Docker Compose for local multi-service development environments", "CI/CD pipelines for automated image building and scanning", "Kubernetes or ECS for production container orchestration", "BuildKit for advanced build features (caching, secrets, SSH forwarding)"], "configurationTemplate": "# .dockerignore\\nnode_modules\\n.git\\n.env\\ndist\\n*.md\\n\\n# Multi-stage Dockerfile\\nFROM node:20-alpine AS deps\\nWORKDIR /app\\nCOPY package*.json ./\\nRUN npm ci --omit=dev\\n\\nFROM node:20-alpine AS builder\\nWORKDIR /app\\nCOPY package*.json ./\\nRUN npm ci\\nCOPY . .\\nRUN npm run build\\n\\nFROM node:20-alpine AS production\\nWORKDIR /app\\nCOPY --from=deps /app/node_modules ./node_modules\\nCOPY --from=builder /app/dist ./dist\\nUSER node\\nEXPOSE 3000\\nHEALTHCHECK CMD wget -q --spider http://localhost:3000/health || exit 1\\nCMD [\"node\", \"dist/index.js\"]"}', '[{"kind": "config", "path": "Dockerfile", "language": "dockerfile", "description": "Container build definition"}, {"kind": "config", "path": "docker-compose.yml", "language": "yaml", "description": "Multi-container orchestration"}, {"kind": "config", "path": ".dockerignore", "language": "text", "description": "Build exclusion patterns"}]', '{"usage": {"type": "enum", "label": "Usage", "default": "compose-stack", "options": ["compose-stack", "single-service"], "description": "Compose file orchestrating the local/prod stack vs one containerized service"}, "registry": {"type": "enum", "label": "Image registry", "default": "ghcr", "options": ["ghcr", "docker-hub", "private-registry"]}, "multiStageBuilds": {"type": "boolean", "label": "Multi-stage builds", "default": true, "description": "Build stage + slim runtime stage — the image-size and attack-surface discipline"}}', '["backend-service", "database", "cache", "message-broker"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#1D7AC2', '''/app'':33C,51C ''/app/dist'':55C ''/app/node_modules'':60C ''/dist'':56C ''/node_modules'':61C ''20'':28C,48C ''3000'':65C ''alpin'':29C,49C,84C ''alway'':69C ''applic'':10B ''base'':82C,109C ''build'':6B,44C ''builder'':31C,54C,59C ''buildkit'':24C ''ci'':39C ''compos'':20C ''consist'':15B ''contain'':3B,71C ''deploy'':16B ''digest'':113C ''direct'':79C ''dist/index.js'':68C ''distroless'':85C ''docker'':1A,2A,17C,19C,22C ''dockerfil'':21C,25C,95C ''engin'':18C ''environ'':13B,92C ''filesystem'':121C ''hub'':23C ''imag'':83C,90C,101C,110C,131C ''inject'':99C ''instal'':126C ''isol'':12B ''json'':36C ''minim'':81C ''n'':45C ''ncmd'':66C ''ncopi'':34C,40C,52C,57C ''never'':86C ''nexpos'':64C ''nfrom'':26C,46C ''node'':27C,47C,63C,67C ''non'':75C ''non-root'':74C ''npm'':38C,42C ''nrun'':37C,41C ''nuser'':62C ''nworkdir'':32C,50C ''packag'':35C,128C ''pin'':108C ''platform'':4B ''possibl'':123C ''product'':130C ''read'':118C ''read-on'':117C ''reproduc'':115C ''root'':76C,120C ''run'':9B,43C,70C ''runtim'':97C ''scan'':100C ''secret'':88C,98C ''set'':116C ''ship'':7B ''snyk'':107C ''store'':87C ''trivi'':105C ''unnecessari'':127C ''use'':80C,96C ''user'':77C,78C ''variabl'':93C ''version'':111C ''vulner'':103C');
INSERT INTO public.technology_catalog VALUES ('qdrant', 'Qdrant', NULL, '#DC244C', '["vector-database"]', '{"purpose": "Open-source vector database (Rust) built around filtered vector search: payload-based filtering evaluated WITH the ANN search rather than pre/post-filtering, plus quantization for memory control. One of the standing self-hosted vector answers alongside pgvector — pgvector when the vectors live beside relational data in Postgres, Qdrant when vector search IS the workload and needs its own scaling.", "configMode": "declarative", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["qdrant client SDKs", "payload indexes", "named vectors", "quantization", "snapshots", "docker/helm deploy"], "antiPatterns": ["Post-filtering search results in app code — Qdrant''s filtered search exists precisely to avoid the recall hole", "One giant unfiltered collection for multi-tenant data — payload-filter or per-collection isolation, decided up front", "Skipping pgvector evaluation when the app is already on Postgres and vectors are small-scale — a second database is real ops cost"], "apiReference": {"docsUrl": "https://qdrant.tech/documentation/"}, "bestPractices": ["Model collections around filtered search: payload indexes on every field used in filters", "Named vectors per collection for multi-embedding-model setups (dense + sparse for hybrid)", "Scalar/product quantization when memory is the constraint — measure recall before and after", "Snapshots for backup; the API covers snapshot create/restore", "Keep embedding generation in YOUR pipeline — the database stores and searches vectors, it does not own the model choice"], "sdkInitPattern": "import { QdrantClient } from ''@qdrant/js-client-rest'';\n\nconst qdrant = new QdrantClient({ url: process.env.QDRANT_URL, apiKey: process.env.QDRANT_API_KEY });\nawait qdrant.search(''docs'', {\n  vector: embedding,\n  limit: 5,\n  filter: { must: [{ key: ''tenantId'', match: { value: tenantId } }] },\n});", "securityGuidance": "Enable API-key auth (it is OFF by default self-hosted) and TLS before anything crosses a network boundary — an open 6333 is full read/write of every collection. Multi-tenant isolation is a payload filter you must apply on EVERY search (tenant key in the filter), or use collection-per-tenant; embeddings are derived from source content and inherit its sensitivity. Read-only API keys for search-only services, and snapshot files are full data copies."}', '[{"kind": "config", "path": "docker-compose.yml"}]', '{"deployment": {"type": "enum", "label": "Deployment", "default": "single-node-docker", "options": ["single-node-docker", "distributed-cluster", "qdrant-cloud"]}, "vectorSetup": {"type": "enum", "label": "Vector setup", "default": "dense-plus-sparse-hybrid", "options": ["dense-only", "dense-plus-sparse-hybrid"], "description": "Hybrid (dense + sparse) is the honest RAG default"}, "quantization": {"type": "enum", "label": "Quantization", "default": "none", "options": ["none", "scalar", "product"], "description": "Turn on when memory forces it — measure recall impact"}}', '[{"id": "pgvector", "reason": "The evaluate-first alternative when the app already runs Postgres"}]', false, NULL, NULL, '2026-08-30 12:07:22.147795+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''5'':96C ''6333'':127C ''alongsid'':40B ''ann'':21B ''answer'':39B ''anyth'':120C ''api'':88C,106C,172C ''api-key'':105C ''apikey'':86C ''appli'':144C ''around'':10B ''auth'':108C ''await'':90C ''base'':16B ''besid'':47B ''boundari'':124C ''built'':9B ''client'':65C ''collect'':133C,156C ''collection-per-ten'':155C ''const'':79C ''content'':164C ''control'':30B ''copi'':185C ''cross'':121C ''data'':49B,184C ''databas'':7B ''default'':113C ''deploy'':74C ''deriv'':161C ''doc'':92C ''docker/helm'':73C ''embed'':94C,159C ''enabl'':104C ''evalu'':18B ''everi'':132C,146C ''file'':181C ''filter'':11B,17B,97C,141C,152C ''full'':129C,183C ''host'':37B,116C ''import'':75C ''index'':68C ''inherit'':166C ''isol'':137C ''key'':89C,99C,107C,149C,173C ''limit'':95C ''live'':46B ''match'':101C ''memori'':29B ''multi'':135C ''multi-ten'':134C ''must'':98C,143C ''name'':69C ''need'':60B ''network'':123C ''new'':81C ''one'':31B ''open'':4B,126C ''open-sourc'':3B ''payload'':15B,67C,140C ''payload-bas'':14B ''per'':157C ''pgvector'':41B,42B ''plus'':26B ''postgr'':51B ''pre/post-filtering'':25B ''process.env.qdrant'':84C,87C ''qdrant'':1A,2A,52B,64C,80C ''qdrant.search'':91C ''qdrant/js-client-rest'':78C ''qdrantclient'':76C,82C ''quantiz'':27B,71C ''rather'':23B ''read'':170C ''read-on'':169C ''read/write'':130C ''relat'':48B ''rust'':8B ''scale'':63B ''sdks'':66C ''search'':13B,22B,55B,147C,176C ''search-on'':175C ''self'':36B,115C ''self-host'':35B,114C ''sensit'':168C ''servic'':178C ''snapshot'':72C,180C ''sourc'':5B,163C ''stand'':34B ''tenant'':136C,148C,158C ''tenantid'':100C,103C ''tls'':118C ''url'':83C,85C ''use'':154C ''valu'':102C ''vector'':6B,12B,38B,45B,54B,70C,93C ''workload'':58B');
INSERT INTO public.technology_catalog VALUES ('grafana', 'Grafana', NULL, '#F46800', '["monitoring"]', '{"purpose": "The standing open-source dashboard and visualization layer — one pane over Prometheus metrics, logs (Loki), traces (Tempo), SQL stores and more, with unified alerting. Grafana 13 is current. The node earns its place when dashboards/alerts are part of the delivered system, not a personal tool.", "configMode": "definition-as-code", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["provisioning-as-code", "Prometheus datasource", "Loki/Tempo (LGTM stack)", "unified alerting", "dashboards JSON in repo"], "antiPatterns": ["UI-only dashboards with no provisioning export — unrecoverable after the volume dies", "A wall of auto-generated panels as the ''observability strategy''", "Embedding Grafana as the product analytics UI for end users — that is an app feature, not an ops dashboard"], "apiReference": {"docsUrl": "https://grafana.com/docs/grafana/latest/"}, "bestPractices": ["Provision EVERYTHING as code (datasources + dashboards via provisioning files or Terraform) — clicked-together dashboards nobody can restore is the Grafana failure mode", "Dashboards answer questions (is checkout healthy?) — start from the user-facing symptom, not from every metric you have", "Use unified alerting OR Alertmanager, not both — two alerting systems means two half-watched ones", "Folder + team permissions from day one on shared instances"], "securityGuidance": "Change the default admin credential before first boot and wire SSO (OAuth/OIDC) with role mapping — viewer by default, editor/admin by team. Datasource credentials live in provisioning secrets or the encrypted store, not dashboard JSON. Disable anonymous access on anything internet-reachable, scope service accounts + API tokens per automation with expiry, and remember dashboards leak by design: a viewer sees whatever the datasource proxy can query.", "configurationTemplate": "# provisioning/datasources/prometheus.yml\napiVersion: 1\ndatasources:\n  - name: Prometheus\n    type: prometheus\n    access: proxy\n    url: http://prometheus:9090\n    isDefault: true"}', '[{"kind": "config", "path": "grafana/provisioning/datasources/"}, {"kind": "config", "path": "grafana/provisioning/dashboards/"}, {"kind": "source", "path": "grafana/dashboards/"}]', '{"alerting": {"type": "enum", "label": "Alerting", "default": "alertmanager-owns-it", "options": ["alertmanager-owns-it", "grafana-unified-alerting"]}, "datasources": {"type": "multiselect", "label": "Datasources", "options": ["prometheus", "loki-logs", "tempo-traces", "postgres", "clickhouse"], "description": "What this instance visualizes — each datasource is wiring + permissions work"}, "provisioning": {"type": "enum", "label": "Dashboard management", "default": "as-code-provisioned", "options": ["as-code-provisioned", "ui-managed"]}}', '[{"id": "prometheus", "reason": "Primary metrics datasource"}]', false, NULL, NULL, '2026-08-30 12:07:22.167076+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''13'':29B ''access'':100C ''account'':108C ''admin'':67C ''alert'':27B,59C ''anonym'':99C ''anyth'':102C ''api'':109C ''autom'':112C ''boot'':71C ''chang'':64C ''code'':52C ''credenti'':68C,86C ''current'':31B ''dashboard'':8B,60C,96C,117C ''dashboards/alerts'':38B ''datasourc'':54C,85C,126C ''default'':66C,81C ''deliv'':43B ''design'':120C ''disabl'':98C ''earn'':34B ''editor/admin'':82C ''encrypt'':93C ''expiri'':114C ''first'':70C ''grafana'':1A,2A,28B ''internet'':104C ''internet-reach'':103C ''json'':61C,97C ''layer'':11B ''leak'':118C ''lgtm'':56C ''live'':87C ''log'':17B ''loki'':18B ''loki/tempo'':55C ''map'':78C ''metric'':16B ''node'':33B ''oauth/oidc'':75C ''one'':12B ''open'':6B ''open-sourc'':5B ''pane'':13B ''part'':40B ''per'':111C ''person'':47B ''place'':36B ''prometheus'':15B,53C ''provis'':50C,89C ''provisioning-as-cod'':49C ''proxi'':127C ''queri'':129C ''reachabl'':105C ''rememb'':116C ''repo'':63C ''role'':77C ''scope'':106C ''secret'':90C ''see'':123C ''servic'':107C ''sourc'':7B ''sql'':21B ''sso'':74C ''stack'':57C ''stand'':4B ''store'':22B,94C ''system'':44B ''team'':84C ''tempo'':20B ''token'':110C ''tool'':48B ''trace'':19B ''unifi'':26B,58C ''viewer'':79C,122C ''visual'':10B ''whatev'':124C ''wire'':73C');
INSERT INTO public.technology_catalog VALUES ('kong', 'Kong Gateway', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/kong.svg', '#003459', '["api-gateway", "service-mesh"]', '{"purpose": "Cloud-native API gateway and service connectivity platform with a plugin-based architecture for managing, securing, and observing API traffic. Use when you need centralized API management across multiple backend services -- authentication, rate limiting, request transformation, and observability in a single layer. Kong supports both traditional (VM/Docker) and Kubernetes-native (Kong Ingress Controller) deployments. It is ideal for microservice architectures where cross-cutting concerns should not be duplicated in each service. Don''t use for simple single-service deployments where a reverse proxy (NGINX) suffices. Don''t use when your API management needs are minimal and cloud-native solutions (AWS API Gateway, Azure APIM) integrate better with your cloud provider. Avoid Kong when you specifically need a service mesh -- use Istio or Linkerd instead, though Kong Mesh exists for that use case.", "configMode": "definition-as-code", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Kong Gateway", "Kong Ingress Controller", "decK", "Kong Manager", "Kong Plugins", "Konnect (cloud)", "Prometheus Plugin", "Helm Chart"], "antiPatterns": ["Putting business logic in Kong plugins instead of keeping the gateway for cross-cutting concerns", "Not implementing rate limiting on public endpoints", "Ignoring plugin execution order causing unexpected behavior", "Running Kong without health checks on upstream services", "Over-configuring plugins per route when global plugins apply to most routes", "Not using declarative configuration (decK) causing configuration drift"], "apiReference": {"docsUrl": "https://docs.konghq.com/"}, "bestPractices": ["Use declarative configuration with decK for version-controlled, reproducible setups", "Implement rate limiting on all public-facing APIs to prevent abuse", "Use JWT or OAuth2 plugins for token-based authentication", "Configure health checks on upstream services for automatic failover", "Use the Prometheus plugin for metrics and Grafana for visualization", "Separate API gateway concerns (auth, rate limiting) from business logic in services", "Use Kong Ingress Controller in Kubernetes for native integration"], "sdkInitPattern": "# Docker Compose for Kong with DB-less mode\\nservices:\\n  kong:\\n    image: kong:3.6\\n    environment:\\n      KONG_DATABASE: \"off\"\\n      KONG_DECLARATIVE_CONFIG: /etc/kong/kong.yml\\n      KONG_PROXY_LISTEN: 0.0.0.0:8000, 0.0.0.0:8443 ssl\\n      KONG_ADMIN_LISTEN: 0.0.0.0:8001\\n    ports: [\"8000:8000\", \"8443:8443\", \"8001:8001\"]\\n    volumes: [\"./kong.yml:/etc/kong/kong.yml\"]", "securityGuidance": "Always require authentication on public-facing routes (JWT, OAuth2, or API key plugins). Enable HTTPS and configure SSL certificates for all proxy listeners. Restrict Admin API access to internal networks only. Implement rate limiting on all routes to prevent abuse and DDoS. Use RBAC (Kong Enterprise) or network-level controls to manage who can configure the gateway.", "commonApiPatterns": [{"name": "Service + Route", "description": "Declarative service and route configuration", "codeTemplate": "# kong.yml (declarative)\\n_format_version: \"3.0\"\\nservices:\\n  - name: user-service\\n    url: http://user-api:3000\\n    routes:\\n      - name: user-routes\\n        paths: [\"/api/users\"]\\n        strip_path: false"}, {"name": "Authentication Plugin", "description": "JWT authentication plugin on a service", "codeTemplate": "plugins:\\n  - name: jwt\\n    service: user-service\\n    config:\\n      claims_to_verify: [\"exp\"]\\n      header_names: [\"Authorization\"]"}, {"name": "Rate Limiting Plugin", "description": "Per-minute rate limiting with local counter", "codeTemplate": "plugins:\\n  - name: rate-limiting\\n    service: user-service\\n    config:\\n      minute: 60\\n      policy: local\\n      fault_tolerant: true\\n      hide_client_headers: false"}, {"name": "Request Transformation", "description": "Add and remove headers before forwarding to upstream", "codeTemplate": "plugins:\\n  - name: request-transformer\\n    service: user-service\\n    config:\\n      add:\\n        headers: [\"X-Request-Source:kong-gateway\"]\\n      remove:\\n        headers: [\"X-Internal-Only\"]"}], "integrationPatterns": ["Kubernetes Ingress Controller for native K8s service discovery and routing", "Prometheus + Grafana for API traffic metrics, latency, and error rate dashboards", "decK CLI for GitOps-style declarative configuration management"], "configurationTemplate": "# Full kong.yml declarative config\\n_format_version: \"3.0\"\\nservices:\\n  - name: api-service\\n    url: http://api-backend:3000\\n    connect_timeout: 5000\\n    read_timeout: 60000\\n    routes:\\n      - name: api-routes\\n        paths: [\"/api\"]\\n        strip_path: false\\n    plugins:\\n      - name: rate-limiting\\n        config: { minute: 100, policy: local }\\n      - name: jwt\\n        config: { claims_to_verify: [\"exp\"] }\\n      - name: cors\\n        config: { origins: [\"*\"], methods: [\"GET\",\"POST\",\"PUT\",\"DELETE\"], headers: [\"Authorization\",\"Content-Type\"] }\\n      - name: prometheus"}', '[{"kind": "config", "path": "kong.yml", "language": "yaml", "description": "Declarative gateway config — services, routes, auth + rate-limit plugins"}]', '{"plugins": {"type": "multiselect", "label": "Plugins used", "options": ["auth-key-jwt-oauth", "rate-limiting", "transformations", "observability"], "description": "Which gateway concerns Kong owns for the services behind it"}, "deployment": {"type": "enum", "label": "Deployment", "default": "oss-gateway", "options": ["oss-gateway", "konnect-managed"]}, "configuration": {"type": "enum", "label": "Configuration", "default": "declarative-deck-yaml", "options": ["declarative-deck-yaml", "db-backed-admin-api"], "description": "decK YAML in the repo is the drift-free lane; DB-backed for runtime-mutable setups"}}', '["backend-service", "k8s-cluster", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#002A47', '''/etc/kong/kong.yml'':184C,211C ''/kong.yml'':210C ''0.0.0.0'':189C,191C,198C ''3.6'':173C ''8000'':190C,202C,203C ''8001'':199C,206C,207C ''8443'':192C,204C,205C ''abus'':252C ''access'':239C ''across'':33B ''admin'':196C,237C ''alway'':212C ''api'':7B,24B,31B,99B,110B,223C,238C ''apim'':113B ''architectur'':18B,66B ''authent'':37B,214C ''avoid'':120B ''aw'':109B ''azur'':112B ''backend'':35B ''base'':17B ''better'':115B ''case'':141B ''central'':30B ''certif'':231C ''chart'':157C ''cloud'':5B,106B,118B,153C ''cloud-nat'':4B,105B ''compos'':159C ''concern'':71B ''config'':183C ''configur'':229C,268C ''connect'':11B ''control'':59B,146C,263C ''cross'':69B ''cross-cut'':68B ''cut'':70B ''databas'':178C ''db'':164C ''db-less'':163C ''ddos'':254C ''deck'':147C ''declar'':182C ''deploy'':60B,87B ''docker'':158C ''duplic'':75B ''enabl'':226C ''enterpris'':258C ''environ'':175C ''exist'':137B ''face'':218C ''gateway'':2A,8B,111B,143C,270C ''helm'':156C ''https'':227C ''ideal'':63B ''imag'':171C ''implement'':244C ''ingress'':58B,145C ''instead'':133B ''integr'':114B ''intern'':241C ''istio'':130B ''jwt'':220C ''key'':224C ''kong'':1A,3A,48B,57B,121B,135B,142C,144C,148C,150C,161C,169C,172C,177C,181C,186C,195C,257C ''konnect'':152C ''kubernet'':55B ''kubernetes-n'':54B ''layer'':47B ''less'':165C ''level'':262C ''limit'':39B,246C ''linkerd'':132B ''listen'':188C,197C,235C ''manag'':20B,32B,100B,149C,265C ''mesh'':128B,136B ''microservic'':65B ''minim'':103B ''mode'':166C ''multipl'':34B ''n'':168C,170C,174C,176C,180C,185C,194C,200C,208C ''nativ'':6B,56B,107B ''need'':29B,101B,125B ''network'':242C,261C ''network-level'':260C ''nginx'':92B ''nservic'':167C ''oauth2'':221C ''observ'':23B,43B ''platform'':12B ''plugin'':16B,151C,155C,225C ''plugin-bas'':15B ''port'':201C ''prevent'':251C ''prometheus'':154C ''provid'':119B ''proxi'':91B,187C,234C ''public'':217C ''public-fac'':216C ''rate'':38B,245C ''rbac'':256C ''request'':40B ''requir'':213C ''restrict'':236C ''revers'':90B ''rout'':219C,249C ''secur'':21B ''servic'':10B,36B,78B,86B,127B ''simpl'':83B ''singl'':46B,85B ''single-servic'':84B ''solut'':108B ''specif'':124B ''ssl'':193C,230C ''suffic'':93B ''support'':49B ''though'':134B ''tradit'':51B ''traffic'':25B ''transform'':41B ''use'':26B,81B,96B,129B,140B,255C ''vm/docker'':52B ''volum'':209C');
INSERT INTO public.technology_catalog VALUES ('pinecone', 'Pinecone', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/pinecone.png', '#0ECF83', '["vector-database"]', '{"purpose": "Stores and queries vector embeddings for semantic search, retrieval-augmented generation, long-term memory, and similarity-based AI workflows.", "configMode": "external", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: model-knowledge 2026-08-10. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["OpenAI", "Claude", "Gemini", "LangChain", "LangGraph", "LiteLLM", "Redis", "PostgreSQL", "S3", "FastAPI"], "antiPatterns": ["Using Pinecone as a replacement for primary relational storage, transactional workflows, or strongly consistent business records.", "Mixing embeddings from incompatible models into the same index without an explicit migration or compatibility plan.", "Building retrieval pipelines without metadata filters, namespace boundaries, or lifecycle rules for stale vectors.", "Assuming vector similarity alone is enough for quality retrieval without chunking, ranking, and evaluation discipline."], "apiReference": {"docsUrl": "https://docs.pinecone.io/"}, "bestPractices": ["Use Pinecone as the retrieval and similarity search layer behind AI services or agents rather than as a source-of-truth transactional database.", "Store rich metadata with vectors so queries can combine similarity search with filters for tenant, document type, or access scope.", "Separate embedding generation pipelines from query-time retrieval paths to keep ingestion scalable and runtime latency predictable.", "Document index purpose, namespace strategy, and embedding model compatibility so retrieval behavior stays understandable as systems evolve."], "sdkInitPattern": "import { Pinecone } from ''@pinecone-database/pinecone'';\n\nconst pc = new Pinecone({ apiKey: process.env.PINECONE_API_KEY });\nconst index = pc.index(''docs'');\nconst results = await index.namespace(`tenant-${tenantId}`).query({\n  vector: embedding,\n  topK: 5,\n  includeMetadata: true,\n  filter: { ownerId: { $eq: userId } },\n});", "securityGuidance": "API keys are server-side only and scoped per project/environment — a key in client code is read/write on every index it can reach. Namespace-per-tenant is the isolation floor (queries only search within a namespace) with metadata filters as the per-user layer INSIDE a namespace; a query without the tenant namespace is cross-tenant retrieval. Embeddings and their metadata inherit the source content''s sensitivity — index what retrieval needs, keep raw PII out of metadata, and remember deletes are per-namespace operations: build account-teardown to actually remove the vectors.", "setupInstructions": [{"url": "https://app.pinecone.io/", "type": "account_setup", "title": "Create Pinecone Account", "required": true, "instructions": "Sign up for Pinecone and create a project. Select the appropriate cloud provider and region for your index."}, {"type": "dashboard_config", "title": "Create Index", "required": true, "instructions": "Create a vector index with the correct dimension matching your embedding model (e.g., 1536 for OpenAI text-embedding-ada-002, 768 for all-MiniLM-L6-v2)."}, {"type": "environment_variable", "title": "Set API Key", "commands": ["export PINECONE_API_KEY=your-api-key", "export PINECONE_ENVIRONMENT=your-environment"], "required": true, "instructions": "Get your API key from the Pinecone console and add it to your environment."}]}', '[{"kind": "config", "path": "config/pinecone-index.json", "language": "json", "description": "Configuration for Pinecone index naming, dimensions, metric type, namespaces, and environment-specific settings."}, {"kind": "source", "path": "src/lib/retrieval/pinecone-client.ts", "language": "typescript", "description": "Application client wrapper for connecting to Pinecone and performing upsert, query, and namespace operations."}, {"kind": "source", "path": "src/workers/embed-and-upsert.py", "language": "python", "description": "Background ingestion worker that generates embeddings and upserts them into Pinecone with metadata."}, {"kind": "doc", "path": "docs/retrieval-architecture.md", "language": "markdown", "description": "Architecture notes for retrieval flow, embedding model choice, chunking strategy, metadata filters, and evaluation considerations."}]', '{"type": "object", "properties": {"indexName": {"type": "string", "title": "Index Name", "description": "Primary Pinecone index used by the application."}, "topKDefault": {"type": "number", "title": "Default Top K", "description": "Default number of results to retrieve for similarity queries."}, "distanceMetric": {"enum": ["cosine", "dotproduct", "euclidean"], "type": "string", "title": "Distance Metric", "description": "Similarity metric used by the index."}, "embeddingModel": {"type": "string", "title": "Embedding Model", "description": "Embedding model expected to produce vectors compatible with this index."}, "namespaceStrategy": {"enum": ["none", "per-user", "per-tenant", "per-project", "per-environment"], "type": "string", "title": "Namespace Strategy", "description": "How vectors are partitioned logically within Pinecone."}}, "additionalProperties": false}', '["ai-service", "ml-pipeline", "worker", "rest-api", "backend-service", "database"]', false, NULL, NULL, '2026-02-16 23:46:48.04289+00', '2026-08-30 12:07:23.877005+00', NULL, '#1F2937', '''/pinecone'':41C ''5'':64C ''account'':162C ''account-teardown'':161C ''actual'':165C ''ai'':23B ''api'':48C,71C ''apikey'':46C ''augment'':13B ''await'':56C ''base'':22B ''build'':160C ''claud'':26C ''client'':85C ''code'':86C ''const'':42C,50C,54C ''content'':139C ''cross'':129C ''cross-ten'':128C ''databas'':40C ''delet'':154C ''doc'':53C ''embed'':7B,62C,132C ''eq'':69C ''everi'':90C ''fastapi'':34C ''filter'':67C,111C ''floor'':102C ''gemini'':27C ''generat'':14B ''import'':35C ''includemetadata'':65C ''index'':51C,91C,142C ''index.namespace'':57C ''inherit'':136C ''insid'':118C ''isol'':101C ''keep'':146C ''key'':49C,72C,83C ''langchain'':28C ''langgraph'':29C ''layer'':117C ''litellm'':30C ''long'':16B ''long-term'':15B ''memori'':18B ''metadata'':110C,135C,151C ''namespac'':96C,108C,120C,126C,158C ''namespace-per-ten'':95C ''need'':145C ''new'':44C ''openai'':25C ''oper'':159C ''ownerid'':68C ''pc'':43C ''pc.index'':52C ''per'':80C,97C,115C,157C ''per-namespac'':156C ''per-us'':114C ''pii'':148C ''pinecon'':1A,2A,36C,39C,45C ''pinecone-databas'':38C ''postgresql'':32C ''process.env.pinecone'':47C ''project/environment'':81C ''queri'':5B,60C,103C,122C ''raw'':147C ''reach'':94C ''read/write'':88C ''redi'':31C ''rememb'':153C ''remov'':166C ''result'':55C ''retriev'':12B,131C,144C ''retrieval-aug'':11B ''s3'':33C ''scope'':79C ''search'':10B,105C ''semant'':9B ''sensit'':141C ''server'':75C ''server-sid'':74C ''side'':76C ''similar'':21B ''similarity-bas'':20B ''sourc'':138C ''store'':3B ''teardown'':163C ''tenant'':58C,98C,125C,130C ''tenantid'':59C ''term'':17B ''topk'':63C ''true'':66C ''user'':116C ''userid'':70C ''vector'':6B,61C,168C ''within'':106C ''without'':123C ''workflow'':24B');
INSERT INTO public.technology_catalog VALUES ('temporal', 'Temporal', NULL, '#6b7280', '["worker"]', '{"purpose": "Durable execution platform for long-running, reliable workflows: code that survives crashes and redeploys mid-execution, with built-in retries, timeouts, versioning and multi-language SDKs. The costs are real — a server cluster (plus database) to operate when self-hosted, and a genuine learning curve (deterministic workflow code, activity boundaries). The right node when a business process spans minutes-to-months and MUST complete.", "configMode": "declarative", "provenance": {"notes": "Phase B8b additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Temporal server", "TypeScript/Go/Java/Python SDKs", "task queues", "signals/queries", "schedules", "Temporal Cloud"], "antiPatterns": ["I/O or non-deterministic calls inside workflow code — breaks replay, the #1 Temporal bug class", "Gigantic payloads through workflow history — pass references, keep events small", "Using Temporal as a message bus — it orchestrates work, brokers move messages", "Self-hosting casually — the server cluster + persistence + upgrades is a platform-team commitment"], "apiReference": {"docsUrl": "https://docs.temporal.io/"}, "bestPractices": ["Workflow code must be DETERMINISTIC — all I/O, randomness and clock reads live in activities; the workflow replays from history", "Activities are idempotent with explicit retry policies — Temporal WILL re-run them", "Version workflows (patched/versioning APIs) before changing in-flight logic — running executions replay old code paths", "Use signals/queries for external interaction with running workflows instead of polling database flags", "One task queue per worker deployment; scale workers horizontally"], "sdkInitPattern": "import { Client, Connection } from ''@temporalio/client'';\n\nconst connection = await Connection.connect({ address: process.env.TEMPORAL_ADDRESS });\nconst client = new Client({ connection, namespace: ''app'' });\nawait client.workflow.start(processOrder, {\n  taskQueue: ''orders'',\n  workflowId: `order-${orderId}`,\n  args: [{ orderId }],\n});", "securityGuidance": "Namespaces are the isolation boundary — one per team/environment with per-namespace authorization, and workers connect over mTLS (or API keys on Temporal Cloud) with identities scoped to their task queues. Workflow histories persist every input and activity result: payloads carry references, not secrets or raw PII, or use a payload codec to encrypt what must pass through. The Web UI is a full execution-history reader — gate it behind SSO."}', '[{"kind": "code", "path": "src/workflows/index.ts", "language": "typescript", "description": "Workflow definitions — deterministic, payloads reference-not-secret"}, {"kind": "code", "path": "src/worker.ts", "language": "typescript", "description": "Worker: mTLS connection, task-queue scoped identity"}]', '{"sdk": {"type": "enum", "label": "Worker SDK", "default": "typescript", "options": ["typescript", "go", "java", "python", "dotnet"], "description": "Workflow/activity code lives in WORKER nodes in this language — the Temporal node is the orchestration server"}, "deployment": {"type": "enum", "label": "Deployment", "default": "temporal-cloud", "options": ["temporal-cloud", "self-hosted-cluster"], "description": "Self-hosting the server cluster (plus its database) is real ops — Temporal Cloud unless data residency or cost at scale forces otherwise"}, "primaryUse": {"type": "enum", "label": "Primary use", "default": "durable-workflows", "options": ["durable-workflows", "saga-orchestration", "scheduled-jobs"]}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''activ'':56B,149C ''address'':92C,94C ''api'':131C ''app'':101C ''arg'':110C ''author'':124C ''await'':90C,102C ''behind'':182C ''boundari'':57B,116C ''built'':23B ''built-in'':22B ''busi'':63B ''carri'':152C ''client'':84C,96C,98C ''client.workflow.start'':103C ''cloud'':82C,135C ''cluster'':39B ''code'':12B,55B ''codec'':163C ''complet'':72B ''connect'':85C,89C,99C,127C ''connection.connect'':91C ''const'':88C,95C ''cost'':34B ''crash'':15B ''curv'':52B ''databas'':41B ''determinist'':53B ''durabl'':3B ''encrypt'':165C ''everi'':146C ''execut'':4B,20B,177C ''execution-histori'':176C ''full'':175C ''gate'':180C ''genuin'':50B ''histori'':144C,178C ''host'':47B ''ident'':137C ''import'':83C ''input'':147C ''isol'':115C ''key'':132C ''languag'':31B ''learn'':51B ''long'':8B ''long-run'':7B ''mid'':19B ''mid-execut'':18B ''minut'':67B ''minutes-to-month'':66B ''month'':69B ''mtls'':129C ''multi'':30B ''multi-languag'':29B ''must'':71B,167C ''namespac'':100C,112C,123C ''new'':97C ''node'':60B ''one'':117C ''oper'':43B ''order'':106C,108C ''orderid'':109C,111C ''pass'':168C ''payload'':151C,162C ''per'':118C,122C ''per-namespac'':121C ''persist'':145C ''pii'':158C ''platform'':5B ''plus'':40B ''process'':64B ''process.env.temporal'':93C ''processord'':104C ''queue'':78C,142C ''raw'':157C ''reader'':179C ''real'':36B ''redeploy'':17B ''refer'':153C ''reliabl'':10B ''result'':150C ''retri'':25B ''right'':59B ''run'':9B ''schedul'':80C ''scope'':138C ''sdks'':32B,76C ''secret'':155C ''self'':46B ''self-host'':45B ''server'':38B,74C ''signals/queries'':79C ''span'':65B ''sso'':183C ''surviv'':14B ''task'':77C,141C ''taskqueu'':105C ''team/environment'':119C ''tempor'':1A,2A,73C,81C,134C ''temporalio/client'':87C ''timeout'':26B ''typescript/go/java/python'':75C ''ui'':172C ''use'':160C ''version'':27B ''web'':171C ''worker'':126C ''workflow'':11B,54B,143C ''workflowid'':107C');
INSERT INTO public.technology_catalog VALUES ('azure-sql-database', 'Azure SQL Database', NULL, '#0078D4', '["database"]', '{"purpose": "Azure SQL Database is Azure''s managed relational database service based on Microsoft SQL Server for transactional applications, reporting workloads, and operational data stores. Use it when you need managed backups, patching, scaling options, high availability, and SQL compatibility without operating database servers. Choose Azure SQL Database over Cosmos DB when your workload is strongly relational and over self-managed SQL Server when you want platform-managed operations. Do not use it as a cache, event stream, or globally distributed document store where Redis, messaging platforms, or NoSQL databases are a better fit.", "configMode": "declarative", "provenance": {"notes": "Phase B7a additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Azure SQL Database", "Azure App Service", "Azure Functions", "Azure Data Factory", "Azure Key Vault", "Azure Monitor", "SQL Server Management Studio"], "antiPatterns": ["Using Azure SQL Database as a distributed cache or message queue", "Letting application code rely on excessive chatty queries or unbounded ORM patterns", "Opening broad public network access without IP restrictions or private endpoints", "Skipping index maintenance and performance tuning as workload volume grows", "Mixing unrelated applications into one schema without ownership or isolation boundaries", "Treating the database as the integration layer for every asynchronous workflow in the system"], "apiReference": {"docsUrl": "https://learn.microsoft.com/azure/azure-sql/"}, "bestPractices": ["Use private endpoints or strict firewall rules to limit database exposure", "Design schemas, indexes, and query patterns around transactional workload needs", "Use managed identities, Azure AD authentication, and secret rotation for database access", "Monitor performance metrics, query plans, and DTU or vCore utilization continuously", "Separate read-heavy, reporting, and operational concerns when workload patterns diverge", "Use automated backups, point-in-time restore, and geo-redundancy based on recovery targets", "Apply migrations through repeatable versioned deployment workflows instead of manual edits"], "securityGuidance": "Entra-only authentication where the estate allows it — SQL logins are legacy surface. No public network access for production: private endpoints and a closed server firewall. TDE stays on, auditing on, application users least-privilege (never the server admin), and every query built from user input is parameterized.", "configurationTemplate": "az sql server create --resource-group my-rg --name my-sql --enable-ad-only-auth \\\n  --external-admin-principal-type User --external-admin-name admin@contoso.com --external-admin-sid <OBJECT_ID>\naz sql db create --resource-group my-rg --server my-sql --name appdb --service-objective S1"}', '[{"kind": "schema", "path": "db/schema.sql", "priority": "essential", "description": "Core Azure SQL Database schema definition"}, {"kind": "schema", "path": "db/migrations/", "priority": "essential", "description": "Versioned migration scripts for database evolution"}, {"kind": "config", "path": "infra/sql-database.bicep", "priority": "recommended", "description": "Infrastructure-as-code definition for Azure SQL Database"}]', '{"serviceTier": {"type": "enum", "label": "Service Tier", "default": "general-purpose", "options": ["general-purpose", "business-critical", "hyperscale"], "description": "Compute and storage performance tier"}, "zoneRedundant": {"type": "boolean", "label": "Zone Redundant", "default": false, "description": "Enable zone-redundant high availability where supported"}, "deploymentModel": {"type": "enum", "label": "Deployment Model", "default": "vcore", "options": ["vcore", "dtu"], "description": "Azure SQL purchasing model"}}', '["backend-service", "worker", "monitoring", "auth-provider", "api-gateway"]', false, NULL, NULL, '2026-03-14 15:40:50.204814+00', '2026-08-30 12:07:23.877005+00', NULL, '#005FAA', '''access'':139C ''admin'':162C ''allow'':129C ''app'':106C ''applic'':24B,154C ''audit'':152C ''authent'':125C ''avail'':42B ''azur'':1A,4A,7B,11B,51B,102C,105C,108C,110C,113C,116C ''backup'':37B ''base'':17B ''better'':100B ''built'':166C ''cach'':83B ''choos'':50B ''close'':146C ''compat'':45B ''cosmos'':55B ''data'':29B,111C ''databas'':3A,6A,9B,15B,48B,53B,97B,104C ''db'':56B ''distribut'':88B ''document'':89B ''endpoint'':143C ''entra'':123C ''entra-on'':122C ''estat'':128C ''event'':84B ''everi'':164C ''factori'':112C ''firewal'':148C ''fit'':101B ''function'':109C ''global'':87B ''high'':41B ''input'':169C ''key'':114C ''least'':157C ''least-privileg'':156C ''legaci'':134C ''login'':132C ''manag'':13B,36B,67B,75B,120C ''messag'':93B ''microsoft'':19B ''monitor'':117C ''need'':35B ''network'':138C ''never'':159C ''nosql'':96B ''oper'':28B,47B,76B ''option'':40B ''parameter'':171C ''patch'':38B ''platform'':74B,94B ''platform-manag'':73B ''privat'':142C ''privileg'':158C ''product'':141C ''public'':137C ''queri'':165C ''redi'':92B ''relat'':14B,62B ''report'':25B ''scale'':39B ''self'':66B ''self-manag'':65B ''server'':21B,49B,69B,119C,147C,161C ''servic'':16B,107C ''sql'':2A,5A,8B,20B,44B,52B,68B,103C,118C,131C ''stay'':150C ''store'':30B,90B ''stream'':85B ''strong'':61B ''studio'':121C ''surfac'':135C ''tde'':149C ''transact'':23B ''use'':31B,79B ''user'':155C,168C ''vault'':115C ''want'':72B ''without'':46B ''workload'':26B,59B');
INSERT INTO public.technology_catalog VALUES ('azure-blob-storage', 'Azure Blob Storage', NULL, '#0078D4', '["object-storage"]', '{"purpose": "Azure''s massively scalable object storage for unstructured data including documents, images, videos, backups, and data lake content. Use for storing user-uploaded files, serving static web content, data lake analytics input, and backup/archival. Blob Storage supports three access tiers (Hot, Cool, Archive) for cost optimization and lifecycle management policies for automatic tier transitions. It integrates natively with Azure CDN, Azure Functions, and Azure Data Factory. Don''t use for structured data requiring queries -- use a database. Don''t use Hot tier for archival data accessed rarely -- Archive tier is 10-20x cheaper. Avoid for workloads requiring POSIX filesystem semantics -- use Azure Files or Azure Data Lake Storage Gen2 (which is built on Blob Storage with hierarchical namespace enabled).", "configMode": "declarative", "provenance": {"notes": "Schemas kept to stable API surface (tiers, redundancy modes, consistency levels, availability options); live-docs upgrades ride the 4b close-out.", "method": "model-knowledge", "sources": ["https://learn.microsoft.com/en-us/azure/"], "verifiedAt": "2026-07-27"}, "typicalTech": ["Azure Blob Storage", "@azure/storage-blob", "Azure Storage Explorer", "Azure CDN", "AzCopy", "Azure Data Lake Gen2", "Azure Functions Blob Trigger", "Terraform azurerm_storage_account"], "antiPatterns": ["Using storage account keys in application code instead of managed identity or SAS tokens", "Leaving containers with public access when private with SAS is appropriate", "Storing all data in Hot tier when lifecycle policies could reduce costs significantly", "Not enabling soft delete for containers with user-uploaded content", "Using Blob Storage for structured data that needs indexing and querying", "Not configuring CORS rules for web applications accessing blobs directly"], "apiReference": {"docsUrl": "https://learn.microsoft.com/azure/storage/blobs/"}, "bestPractices": ["Use managed identity for authentication instead of storage account keys", "Enable soft delete for blobs and containers to protect against accidental deletion", "Use lifecycle management policies to automatically transition blobs to cooler tiers", "Enable blob versioning for buckets storing important content", "Use Azure CDN or Front Door for global distribution of static content", "Use SAS tokens with short expiry for temporary client-side access", "Enable storage analytics logging for audit and troubleshooting"], "sdkInitPattern": "// Node.js with @azure/storage-blob\\nimport { BlobServiceClient } from \"@azure/storage-blob\";\\nconst blobService = BlobServiceClient.fromConnectionString(process.env.AZURE_STORAGE_CONNECTION!);\\nconst container = blobService.getContainerClient(\"uploads\");\\n// [Tailor to project language: Python=azure-storage-blob, .NET=Azure.Storage.Blobs, Java=azure-storage-blob]", "securityGuidance": "Use managed identity authentication instead of storage account keys. Set minimum TLS version to 1.2. Use Private Endpoints to restrict access to private networks. Generate SAS tokens with minimal permissions and short expiry. Enable soft delete and versioning to protect against accidental data loss. Use Azure Defender for Storage for threat detection.", "commonApiPatterns": [{"name": "Upload Blob", "description": "Upload a blob with content type", "codeTemplate": "const blockBlob = container.getBlockBlobClient(`${userId}/${filename}`);\\nawait blockBlob.upload(buffer, buffer.length, {\\n  blobHTTPHeaders: { blobContentType: contentType }\\n});"}, {"name": "Generate SAS URL", "description": "Generate time-limited SAS URL for secure download", "codeTemplate": "import { generateBlobSASQueryParameters, BlobSASPermissions, StorageSharedKeyCredential } from \"@azure/storage-blob\";\\nconst sas = generateBlobSASQueryParameters({\\n  containerName: \"uploads\", blobName: blobPath,\\n  permissions: BlobSASPermissions.parse(\"r\"),\\n  expiresOn: new Date(Date.now() + 3600000)\\n}, sharedKeyCredential);\\nconst url = `${blockBlob.url}?${sas.toString()}`;"}, {"name": "List Blobs", "description": "List blobs by prefix with async iteration", "codeTemplate": "const blobs = [];\\nfor await (const blob of container.listBlobsFlat({ prefix: `${userId}/` })) {\\n  blobs.push({ name: blob.name, size: blob.properties.contentLength, lastModified: blob.properties.lastModified });\\n}"}], "setupInstructions": [{"url": "https://learn.microsoft.com/en-us/azure/storage/blobs/storage-quickstart-blobs-portal", "type": "dashboard_config", "title": "Create Storage Account", "required": true, "instructions": "Create an Azure Storage Account in the Azure portal. Choose performance tier (Standard/Premium) and redundancy (LRS/GRS/ZRS)."}, {"type": "dashboard_config", "title": "Create Container", "required": true, "instructions": "Create a blob container with the appropriate access level (Private, Blob, or Container)."}, {"type": "environment_variable", "title": "Set Connection String", "commands": ["export AZURE_STORAGE_CONNECTION_STRING=DefaultEndpointsProtocol=https;AccountName=..."], "required": true, "instructions": "Get the connection string from Access Keys in the storage account settings."}, {"type": "dashboard_config", "title": "Configure CORS Rules", "required": false, "instructions": "If using client-side uploads, configure CORS rules under Settings > Resource sharing (CORS) in the storage account."}], "integrationPatterns": ["Azure CDN or Front Door for global static content delivery", "Azure Functions with Blob Trigger for event-driven file processing", "Azure Data Factory for ETL pipelines reading from Blob Storage"], "configurationTemplate": "resource \"azurerm_storage_account\" \"main\" {\\n  name                     = \"${var.project}storage\"\\n  resource_group_name      = azurerm_resource_group.main.name\\n  location                 = azurerm_resource_group.main.location\\n  account_tier             = \"Standard\"\\n  account_replication_type = \"LRS\"\\n  min_tls_version          = \"TLS1_2\"\\n  blob_properties {\\n    delete_retention_policy { days = 30 }\\n    container_delete_retention_policy { days = 30 }\\n    versioning_enabled = true\\n  }\\n}\\nresource \"azurerm_storage_container\" \"uploads\" {\\n  name                  = \"uploads\"\\n  storage_account_name  = azurerm_storage_account.main.name\\n  container_access_type = \"private\"\\n}"}', '[{"kind": "config", "path": "infra/azure/storage.bicep"}]', '{"accessTier": {"type": "enum", "label": "Access tier", "default": "hot", "options": ["hot", "cool", "cold", "archive"], "description": "Cheaper storage costs more per read — match the access pattern"}, "redundancy": {"type": "enum", "label": "Redundancy", "default": "ZRS", "options": ["LRS", "ZRS", "GRS", "GZRS"], "description": "LRS single datacenter; ZRS across zones; G* adds geo-replication"}, "publicAccess": {"type": "boolean", "label": "Allow public blob access", "default": false, "description": "Keep OFF; use SAS tokens or private endpoints"}, "softDeleteDays": {"type": "number", "label": "Soft delete (days)", "default": 7}, "hierarchicalNamespace": {"type": "boolean", "label": "Hierarchical namespace (Data Lake Gen2)", "default": false, "description": "Enables true directories + POSIX ACLs for analytics workloads"}}', '["backend-service", "serverless-function", "frontend-app"]', false, NULL, NULL, '2026-02-20 14:51:11.165373+00', '2026-08-30 12:07:23.877005+00', NULL, '#005EA2', '''-20'':99B ''1.2'':198C ''10'':98B ''access'':46B,93B,204C ''accident'':225C ''account'':149C,191C ''analyt'':38B ''archiv'':50B,91B,95B ''authent'':187C ''automat'':59B ''avoid'':102B ''azcopi'':137C ''azur'':1A,4A,7B,66B,68B,71B,110B,113B,128C,132C,135C,138C,142C,174C,181C,229C ''azure-storage-blob'':173C,180C ''azure.storage.blobs'':178C ''azure/storage-blob'':131C,152C,156C ''azurerm'':147C ''backup'':20B ''backu