INSERT INTO public.technology_catalog VALUES ('bullmq', 'BullMQ', NULL, '#6b7280', '["queue", "worker"]', '{"purpose": "The standing Node.js job queue on Redis/Valkey: delayed and repeatable (cron) jobs, rate limiting, priorities, parent-child flows, and Bull Board for visibility. The default background-work answer inside a Node stack; the Redis dependency is the operational surface.", "configMode": "code", "provenance": {"notes": "Phase B8c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-28. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["queues + workers", "repeatable jobs", "flows", "rate limiting", "Bull Board", "Redis/Valkey backing"], "antiPatterns": ["Workers inside the API process in production — one slow job class starves request handling", "Job payloads carrying whole documents — pass ids, fetch in the worker", "Ignoring the Redis persistence/eviction config under the queue (noeviction is mandatory — see the redis row)"], "apiReference": {"docsUrl": "https://docs.bullmq.io/"}, "bestPractices": ["Idempotent processors with explicit jobId where dedup matters — retries and redeliveries are the design", "Dedicated worker processes; concurrency tuned per queue, not global", "Configure attempts + backoff + a failed-job policy per queue; Bull Board (or equivalent) from day one", "Repeatable jobs replace cron containers — one scheduling system, not two"], "sdkInitPattern": "import { Queue, Worker } from ''bullmq'';\n\nconst connection = { url: process.env.REDIS_URL }; // rediss:// with auth\nconst queue = new Queue(''emails'', { connection });\nawait queue.add(''welcome'', { userId }, { attempts: 3, backoff: { type: ''exponential'', delay: 1000 } });\n\nnew Worker(''emails'', async (job) => { await sendWelcome(job.data.userId); }, { connection });", "securityGuidance": "Queue security IS Redis security — anyone who can reach the Redis instance can enqueue arbitrary jobs into your workers and read every payload, so authenticated TLS connections and network isolation are non-negotiable. Job data persists in Redis until removal: references, not secrets or raw PII, and set removeOnComplete/removeOnFail so processed payloads do not accumulate. Bound attempts with backoff so poison jobs surface in the failed set instead of looping, and make processors idempotent — at-least-once is the contract."}', '[{"kind": "code", "path": "src/queues/index.ts", "language": "typescript", "description": "Queue definitions with bounded attempts + removeOnComplete"}, {"kind": "code", "path": "src/workers/index.ts", "language": "typescript", "description": "Idempotent worker processors"}]', '{"workers": {"type": "enum", "label": "Worker placement", "default": "dedicated-worker-nodes", "options": ["dedicated-worker-nodes", "same-process-dev-only"], "description": "Production workers are their own processes/nodes — in-API workers are a dev convenience"}, "features": {"type": "multiselect", "label": "Features used", "options": ["delayed-scheduled-jobs", "rate-limiting", "priorities", "flows-parent-child", "repeatable-cron"], "description": "Which BullMQ capabilities this component relies on"}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''1000'':83C ''3'':78C ''accumul'':148C ''answer'':32B ''anyon'':98C ''arbitrari'':107C ''async'':87C ''at-least-onc'':168C ''attempt'':77C,150C ''auth'':66C ''authent'':117C ''await'':73C,89C ''back'':54C ''background'':30B ''background-work'':29B ''backoff'':79C,152C ''board'':24B,52C ''bound'':149C ''bull'':23B,51C ''bullmq'':1A,2A,59C ''child'':20B ''connect'':61C,72C,92C,119C ''const'':60C,67C ''contract'':174C ''cron'':13B ''data'':128C ''default'':28B ''delay'':10B,82C ''depend'':39B ''email'':71C,86C ''enqueu'':106C ''everi'':114C ''exponenti'':81C ''fail'':159C ''flow'':21B,48C ''idempot'':167C ''import'':55C ''insid'':33B ''instanc'':104C ''instead'':161C ''isol'':122C ''job'':6B,14B,47C,88C,108C,127C,155C ''job.data.userid'':91C ''least'':170C ''limit'':16B,50C ''loop'':163C ''make'':165C ''negoti'':126C ''network'':121C ''new'':69C,84C ''node'':35B ''node.js'':5B ''non'':125C ''non-negoti'':124C ''oper'':42B ''parent'':19B ''parent-child'':18B ''payload'':115C,145C ''persist'':129C ''pii'':139C ''poison'':154C ''prioriti'':17B ''process'':144C ''process.env.redis'':63C ''processor'':166C ''queue'':7B,44C,56C,68C,70C,93C ''queue.add'':74C ''rate'':15B,49C ''raw'':138C ''reach'':101C ''read'':113C ''redi'':38B,96C,103C,131C ''redis/valkey'':9B,53C ''refer'':134C ''remov'':133C ''removeoncomplete/removeonfail'':142C ''repeat'':12B,46C ''secret'':136C ''secur'':94C,97C ''sendwelcom'':90C ''set'':141C,160C ''stack'':36B ''stand'':4B ''surfac'':43B,156C ''tls'':118C ''type'':80C ''url'':62C,64C ''userid'':76C ''visibl'':26B ''welcom'':75C ''work'':31B ''worker'':45C,57C,85C,111C');
INSERT INTO public.technology_catalog VALUES ('kotlin-android', 'Kotlin (Android)', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/kotlin-android.png', '#7F52FF', '["mobile-app"]', '{"purpose": "JetBrains'' modern language for native Android development, now Google''s preferred language for Android. Kotlin with Jetpack Compose provides a declarative, type-safe UI framework for building Android applications. Use when building Android-specific apps that need deep platform integration -- Google Play services, Android widgets, Wear OS, Android Auto, or advanced camera and sensor APIs. Native Kotlin apps deliver the best performance and most complete access to Android platform capabilities. Don''t use when you need cross-platform iOS support from the same codebase -- use Flutter, React Native, or Kotlin Multiplatform instead. Don''t use for simple content apps where a cross-platform solution reduces development cost. Consider Kotlin Multiplatform for sharing business logic with iOS while keeping native UI on each platform.", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (UI model, concurrency model, persistence, distribution); live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Kotlin", "Jetpack Compose", "Android Studio", "Hilt", "Room", "Retrofit/Ktor", "Kotlin Coroutines", "Gradle Version Catalog"], "antiPatterns": ["Using Java patterns in Kotlin (verbose builders instead of DSLs, nullable types everywhere)", "Not using coroutines and falling back to callbacks or RxJava for simple async", "Putting business logic in Activities/Fragments instead of ViewModels", "Using GlobalScope for coroutines instead of lifecycle-aware scopes", "Not handling configuration changes (rotation) causing state loss", "Ignoring ProGuard/R8 configuration causing runtime crashes in release builds"], "apiReference": {"docsUrl": "https://developer.android.com/docs"}, "bestPractices": ["Use Jetpack Compose for new UI development instead of XML layouts", "Follow MVVM with ViewModel and StateFlow for reactive state management", "Use Kotlin coroutines and Flow for asynchronous operations", "Implement Hilt for dependency injection", "Use Room or SQLDelight for local database persistence", "Write unit tests with JUnit5 and UI tests with Compose Testing", "Use Version Catalog (libs.versions.toml) for centralized dependency management"], "sdkInitPattern": "// Android Studio: New Project > Empty Activity (Compose)\\n// MainActivity.kt\\nclass MainActivity : ComponentActivity() {\\n    override fun onCreate(savedInstanceState: Bundle?) {\\n        super.onCreate(savedInstanceState)\\n        setContent {\\n            MyAppTheme {\\n                Text(\"Hello Kotlin\")\\n            }\\n        }\\n    }\\n}", "securityGuidance": "Use EncryptedSharedPreferences or Android Keystore for storing credentials. Enable network security config to enforce HTTPS. Use certificate pinning for sensitive API connections. Enable ProGuard/R8 for release builds to obfuscate code. Never embed API keys in Java/Kotlin source -- use BuildConfig fields from local.properties or CI secrets. Use biometric authentication via BiometricPrompt for sensitive operations.", "commonApiPatterns": [{"name": "Compose UI with State", "description": "Composable function with remember state", "codeTemplate": "@Composable\\nfun Counter() {\\n    var count by remember { mutableIntStateOf(0) }\\n    Column(horizontalAlignment = Alignment.CenterHorizontally) {\\n        Text(\"Count: $count\", style = MaterialTheme.typography.headlineMedium)\\n        Button(onClick = { count++ }) { Text(\"Increment\") }\\n    }\\n}"}, {"name": "ViewModel with StateFlow", "description": "Hilt-injected ViewModel with sealed UiState and coroutines", "codeTemplate": "@HiltViewModel\\nclass UserViewModel @Inject constructor(private val repo: UserRepository) : ViewModel() {\\n    private val _uiState = MutableStateFlow<UiState>(UiState.Loading)\\n    val uiState = _uiState.asStateFlow()\\n    init {\\n        viewModelScope.launch {\\n            _uiState.value = try { UiState.Success(repo.getUsers()) } catch (e: Exception) { UiState.Error(e.message ?: \"Unknown error\") }\\n        }\\n    }\\n}"}, {"name": "Navigation", "description": "Jetpack Navigation Compose with arguments", "codeTemplate": "NavHost(navController = navController, startDestination = \"home\") {\\n    composable(\"home\") { HomeScreen(onUserClick = { navController.navigate(\"user/$it\") }) }\\n    composable(\"user/{id}\") { backStackEntry ->\\n        UserScreen(userId = backStackEntry.arguments?.getString(\"id\")!!)\\n    }\\n}"}], "setupInstructions": [{"url": "https://play.google.com/console", "type": "console", "title": "Create the Play Console developer account", "required": true, "instructions": "One-time $25 registration; identity verification can take days. Organization accounts need a D-U-N-S number."}, {"type": "console", "title": "Create the app + store listing", "required": true, "instructions": "Application ID (package name) is permanent once published. Listing needs the data-safety form, content rating questionnaire and privacy policy URL before ANY track can publish."}, {"type": "console", "title": "Signing: upload key + Play App Signing", "required": true, "instructions": "Generate an upload keystore and enroll in Play App Signing (Google holds the release key, you hold the upload key). Losing a legacy self-managed release key is unrecoverable — always enroll."}, {"type": "console", "title": "Internal testing track first", "required": false, "instructions": "Internal track publishes in minutes with no review — wire CI to it before touching production. New personal accounts also need a closed-testing period before production access."}, {"type": "manual", "title": "Production release + review", "required": true, "instructions": "Staged rollout by percentage is the default safety net — start at a low percentage and watch vitals before 100%."}], "integrationPatterns": ["Firebase or Supabase Kotlin SDK for backend services (auth, database, messaging)", "Retrofit or Ktor Client for type-safe HTTP API communication", "GitHub Actions or Gradle Play Publisher for CI/CD to Google Play"], "configurationTemplate": "// build.gradle.kts (app module)\\nplugins {\\n    alias(libs.plugins.android.application)\\n    alias(libs.plugins.kotlin.android)\\n    alias(libs.plugins.kotlin.compose)\\n    alias(libs.plugins.hilt.android)\\n    alias(libs.plugins.ksp)\\n}\\nandroid {\\n    namespace = \"com.example.myapp\"\\n    compileSdk = 34\\n    defaultConfig {\\n        minSdk = 26\\n        targetSdk = 34\\n    }\\n    buildFeatures { compose = true }\\n}"}', '[{"kind": "config", "path": "build.gradle.kts", "language": "kotlin", "description": "Gradle build configuration"}, {"kind": "source", "path": "app/src/main/java/MainActivity.kt", "language": "kotlin", "description": "Main Activity with Compose UI"}, {"kind": "config", "path": "app/src/main/AndroidManifest.xml", "language": "xml", "description": "Android application manifest"}, {"kind": "source", "path": "app/src/main/java/ui/theme/Theme.kt", "language": "kotlin", "description": "Compose theme configuration"}, {"kind": "source", "path": "app/src/test/ExampleUnitTest.kt", "language": "kotlin", "description": "Unit test suite"}]', '{"di": {"type": "enum", "label": "Dependency injection", "default": "hilt", "options": ["hilt", "koin", "manual"]}, "ui": {"type": "enum", "label": "UI", "default": "jetpack-compose", "options": ["jetpack-compose", "xml-views-legacy", "mixed"], "description": "Compose is the standing default for new apps"}, "async": {"type": "enum", "label": "Async model", "default": "coroutines-flow", "options": ["coroutines-flow", "rxjava-legacy"]}, "persistence": {"type": "enum", "label": "Persistence", "default": "room", "options": ["room", "datastore-only", "none-api-only"]}, "distribution": {"type": "enum", "label": "Distribution", "default": "play-store", "options": ["play-store", "internal-testing", "enterprise-sideload"], "description": "Play Console setup, signing keys and review are MANUAL steps, not code"}}', '["web.rest-api", "auth.supabase-auth", "database.firebase"]', false, NULL, NULL, '2026-02-16 02:23:50.361867+00', '2026-08-30 12:07:23.877005+00', NULL, '#6B3FE6', '''access'':72B ''activ'':150C ''advanc'':57B ''android'':2A,4A,10B,18B,33B,39B,50B,54B,74B,135C,145C,181C ''android-specif'':38B ''api'':61B,198C,210C ''app'':41B,64B,106B ''applic'':34B ''authent'':225C ''auto'':55B ''best'':67B ''biometr'':224C ''biometricprompt'':227C ''build'':32B,37B,204C ''buildconfig'':216C ''bundl'':162C ''busi'':121B ''camera'':58B ''capabl'':76B ''catalog'':144C ''certif'':194C ''ci'':221C ''code'':207C ''codebas'':91B ''complet'':71B ''componentact'':156C ''compos'':22B,134C,151C ''config'':189C ''connect'':199C ''consid'':116B ''content'':105B ''coroutin'':141C ''cost'':115B ''credenti'':185C ''cross'':84B,110B ''cross-platform'':83B,109B ''declar'':25B ''deep'':44B ''deliv'':65B ''develop'':11B,114B ''emb'':209C ''empti'':149C ''enabl'':186C,200C ''encryptedsharedprefer'':179C ''enforc'':191C ''field'':217C ''flutter'':93B ''framework'':30B ''fun'':159C ''googl'':13B,47B ''gradl'':142C ''hello'':172C ''hilt'':137C ''https'':192C ''instead'':99B ''integr'':46B ''io'':86B,124B ''java/kotlin'':213C ''jetbrain'':5B ''jetpack'':21B,133C ''keep'':126B ''key'':211C ''keystor'':182C ''kotlin'':1A,3A,19B,63B,97B,117B,132C,140C,173C ''languag'':7B,16B ''local.properties'':219C ''logic'':122B ''mainact'':155C ''mainactivity.kt'':153C ''modern'':6B ''multiplatform'':98B,118B ''myappthem'':169C ''n'':152C,157C,163C,166C,168C,170C,174C,175C,176C,177C ''nativ'':9B,62B,95B,127B ''nclass'':154C ''need'':43B,82B ''network'':187C ''never'':208C ''new'':147C ''obfusc'':206C ''oncreat'':160C ''oper'':230C ''os'':53B ''overrid'':158C ''perform'':68B ''pin'':195C ''platform'':45B,75B,85B,111B,131B ''play'':48B ''prefer'':15B ''proguard/r8'':201C ''project'':148C ''provid'':23B ''react'':94B ''reduc'':113B ''releas'':203C ''retrofit/ktor'':139C ''room'':138C ''safe'':28B ''savedinstancest'':161C,165C ''secret'':222C ''secur'':188C ''sensit'':197C,229C ''sensor'':60B ''servic'':49B ''setcont'':167C ''share'':120B ''simpl'':104B ''solut'':112B ''sourc'':214C ''specif'':40B ''store'':184C ''studio'':136C,146C ''super.oncreate'':164C ''support'':87B ''text'':171C ''type'':27B ''type-saf'':26B ''ui'':29B,128B ''use'':35B,79B,92B,102B,178C,193C,215C,223C ''version'':143C ''via'':226C ''wear'':52B ''widget'':51B');
INSERT INTO public.technology_catalog VALUES ('tauri', 'Tauri', NULL, '#FFC131', '["desktop-app"]', '{"purpose": "Framework for building lightweight cross-platform desktop applications with a Rust backend and any web frontend, using the OS native webview instead of bundled Chromium", "configMode": "code", "provenance": {"notes": "Phase B8e additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Tauri", "Rust", "WebView2", "WKWebView", "tauri-bundler", "tauri-plugin-updater", "serde", "tokio"], "antiPatterns": ["Using allowlist: all instead of scoping permissions per capability", "Blocking the main thread with synchronous Rust commands", "Not validating IPC payloads from the frontend in command handlers", "Skipping code signing which prevents auto-update and triggers OS warnings", "Bundling native Node.js modules (Tauri does not ship Node.js)"], "apiReference": {"docsUrl": "https://tauri.app/start/"}, "bestPractices": ["Use Tauri commands (invoke) for frontend-to-Rust IPC instead of raw events", "Define granular capability permissions in src-tauri/capabilities/", "Keep the Rust backend thin; delegate heavy logic to async tasks with tokio", "Use tauri-plugin-store for persistent key-value storage", "Enable the updater plugin with code signing for automatic updates", "Build universal binaries for macOS (aarch64 + x86_64)", "Use the Tauri CLI (cargo tauri build) for reproducible cross-platform builds", "Leverage sidecar binaries for shipping CLI tools alongside the app"], "securityGuidance": "The capability system is the security model — grant the webview only the specific commands and scoped paths/urls it needs (a broad fs or shell scope hands web content the machine), and keep the CSP strict: the webview renders your UI but any injected script speaks to your Rust commands with the app''s privileges. Validate every command''s arguments in Rust as untrusted input, never build shell invocations from webview strings, ship updates only through the signed updater (the signing key lives in CI secrets, not the repo), and pin remote content out — loading arbitrary remote pages into a privileged webview recreates Electron''s classic mistake.", "setupInstructions": [{"url": "https://www.rust-lang.org/tools/install", "type": "toolchain_install", "title": "Install Rust Toolchain", "commands": ["curl --proto =https --tlsv1.2 -sSf https://sh.rustup.rs | sh", "rustup update stable"], "required": true, "instructions": "Install Rust via rustup. Tauri requires a stable Rust compiler."}, {"type": "toolchain_install", "title": "Install OS Dependencies", "commands": ["# Linux (Debian/Ubuntu):", "sudo apt-get install libwebkit2gtk-4.1-dev build-essential curl wget file libxdo-dev libssl-dev libayatana-appindicator3-dev librsvg2-dev", "# macOS:", "xcode-select --install"], "required": true, "instructions": "Install platform-specific webview and build dependencies: Windows needs WebView2 (pre-installed on Win11), Linux needs webkit2gtk and related libs, macOS needs Xcode Command Line Tools."}, {"type": "dashboard_config", "title": "Configure tauri.conf.json", "required": true, "instructions": "Edit src-tauri/tauri.conf.json to set your app identifier (reverse domain), window title, size, and permissions. The identifier cannot change after distribution."}, {"type": "certificate", "title": "Set Up Code Signing", "commands": ["# macOS env vars:", "export APPLE_CERTIFICATE=<base64-p12>", "export APPLE_CERTIFICATE_PASSWORD=<password>", "export APPLE_ID=<apple-id>", "export APPLE_PASSWORD=<app-specific-password>"], "required": false, "instructions": "For macOS: configure Apple Developer certificate and notarization credentials. For Windows: set up Authenticode certificate. Tauri CLI handles signing during build if credentials are provided via env vars."}], "configurationTemplate": "// src-tauri/tauri.conf.json\n{\n  \"productName\": \"app\",\n  \"identifier\": \"com.example.app\",\n  \"app\": {\n    \"security\": {\n      \"csp\": \"default-src ''self''; connect-src ''self'' https://api.example.com\"\n    }\n  },\n  \"bundle\": { \"targets\": \"all\" }\n}\n// capabilities/main.json grants the webview ONLY the commands + scopes it needs"}', '[{"kind": "config", "path": "src-tauri/tauri.conf.json", "language": "json", "description": "Tauri application configuration (windows, security, bundler)"}, {"kind": "source", "path": "src-tauri/src/main.rs", "language": "rust", "description": "Tauri Rust backend entry point"}, {"kind": "source", "path": "src-tauri/src/commands.rs", "language": "rust", "description": "Tauri command handlers invoked from frontend"}, {"kind": "config", "path": "src-tauri/Cargo.toml", "language": "toml", "description": "Rust dependencies for the Tauri sidecar"}, {"kind": "config", "path": "src-tauri/capabilities/default.json", "language": "json", "description": "Tauri v2 capability permissions for IPC and system access"}, {"kind": "config", "path": "src-tauri/build.rs", "language": "rust", "description": "Tauri build script for compile-time setup"}, {"kind": "config", "path": "src-tauri/icons/icon.png", "description": "Application icon source for all platform targets"}]', '{"targets": {"type": "multiselect", "label": "Build targets", "options": ["windows", "macos", "linux"], "description": "Signing/notarization are per-OS manual setup"}, "updater": {"type": "boolean", "label": "Built-in updater", "default": true}, "ipcSurface": {"type": "enum", "label": "Backend surface", "default": "commands-rust", "options": ["commands-rust", "sidecar-binary", "minimal-shell"], "description": "Tauri commands are Rust functions the UI invokes — the real app logic boundary"}, "uiFramework": {"type": "enum", "label": "UI framework", "default": "react", "options": ["react", "vue", "svelte", "solid", "vanilla"], "description": "The web framework rendering inside Tauri — this node IS the desktop app; the backend is Rust commands"}, "capabilities": {"type": "boolean", "label": "Capability-scoped permissions", "default": true, "description": "Tauri v2 permissions: each window gets only the APIs its capability file grants"}}', '["frontend-app", "rest-api", "database"]', false, NULL, NULL, '2026-03-16 02:23:33.717373+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''app'':93C ''applic'':11B ''arbitrari'':136C ''argument'':100C ''backend'':15B ''broad'':62C ''build'':5B,107C ''bundl'':27B ''bundler'':35C ''capabl'':43C ''chromium'':28B ''ci'':125C ''classic'':146C ''command'':55C,90C,98C ''content'':69C,133C ''cross'':8B ''cross-platform'':7B ''csp'':75C ''desktop'':10B ''electron'':144C ''everi'':97C ''framework'':3B ''frontend'':19B ''fs'':63C ''grant'':49C ''hand'':67C ''inject'':84C ''input'':105C ''instead'':25B ''invoc'':109C ''keep'':73C ''key'':122C ''lightweight'':6B ''live'':123C ''load'':135C ''machin'':71C ''mistak'':147C ''model'':48C ''nativ'':23B ''need'':60C ''never'':106C ''os'':22B ''page'':138C ''paths/urls'':58C ''pin'':131C ''platform'':9B ''plugin'':38C ''privileg'':95C,141C ''recreat'':143C ''remot'':132C,137C ''render'':79C ''repo'':129C ''rust'':14B,30C,89C,102C ''scope'':57C,66C ''script'':85C ''secret'':126C ''secur'':47C ''serd'':40C ''shell'':65C,108C ''ship'':113C ''sign'':118C,121C ''speak'':86C ''specif'':54C ''strict'':76C ''string'':112C ''system'':44C ''tauri'':1A,2A,29C,34C,37C ''tauri-bundl'':33C ''tauri-plugin-updat'':36C ''tokio'':41C ''ui'':81C ''untrust'':104C ''updat'':39C,114C,119C ''use'':20B ''valid'':96C ''web'':18B,68C ''webview'':24B,51C,78C,111C,142C ''webview2'':31C ''wkwebview'':32C');
INSERT INTO public.technology_catalog VALUES ('resend', 'Resend', NULL, '#18181B', '["external-service"]', '{"purpose": "Developer-first transactional email API with React Email template support", "configMode": "external", "provenance": {"notes": "Verified via web search over resend.com docs (network policy blocks direct fetch): idempotency keys, scheduled sends, batch (100/call), Broadcast API and CSV contact import (200MB) all current.", "method": "live-docs", "sources": ["https://resend.com/docs/api-reference", "https://resend.com/blog/broadcast-api"], "verifiedAt": "2026-07-27"}, "typicalTech": ["resend", "react-email", "@react-email/components", "Webhooks"], "antiPatterns": ["Sending marketing broadcasts through the transactional pipeline", "Hardcoding HTML strings instead of using React Email templates", "Ignoring bounce events and repeatedly mailing dead addresses"], "apiReference": {"areas": {"batch": {"endpoints": ["`POST /emails/batch` — up to 100 emails in one call (array of email objects)", "Batch is for distinct transactional emails — audience blasts belong to broadcasts instead"]}, "emails": {"endpoints": ["`POST /emails` — send (from: verified-domain sender, to, subject, react|html|text); bearer auth with the API key", "Idempotency-Key header on sends that may retry — same key = processed once", "scheduled_at for delayed sends; attachments supported (incl. inline CID images)", "`GET /emails/{id}` — delivery status of a sent email"]}, "domains": {"endpoints": ["`POST /domains` — register a sending domain; returns the SPF/DKIM records to publish", "`GET /domains/{id}` — poll verification status; sending from unverified domains fails", "One domain per environment (mail.staging.example.com) keeps reputation isolated"]}, "webhooks": {"endpoints": ["Events: email.sent, email.delivered, email.bounced, email.complained, email.opened, email.clicked", "Verify webhook signatures (svix headers) before trusting payloads", "Feed bounces/complaints into a suppression list — repeatedly mailing dead addresses burns domain reputation"]}, "broadcasts": {"endpoints": ["`POST /broadcasts` — create a campaign against an audience (from, subject, react|html)", "`POST /broadcasts/{id}/send` — send or schedule; broadcasts honor per-audience unsubscribe automatically"]}, "audiences-contacts": {"endpoints": ["`POST /audiences` · `GET /audiences` — contact lists for marketing sends", "`POST /audiences/{id}/contacts` — add/update contacts (email, unsubscribed flag)", "Bulk import via the Contacts Import API/dashboard (CSV up to 200MB)"]}}, "docsUrl": "https://resend.com/docs/api-reference"}, "bestPractices": ["Build templates as React Email components for type-safe, previewable emails", "Configure SPF, DKIM, and a dedicated sending domain before production", "Use idempotency keys when retrying sends", "Consume delivery and bounce webhooks to maintain suppression lists", "Batch API calls when sending to multiple recipients"], "sdkInitPattern": "import { Resend } from ''resend'';\nconst resend = new Resend(process.env.RESEND_API_KEY);\nawait resend.emails.send({ from: ''app@example.com'', to: user.email, subject: ''Welcome'', react: WelcomeEmail({ name }) });", "securityGuidance": "Keep API keys server-side only; verify webhook signing secrets", "setupInstructions": [{"url": "https://resend.com/domains", "type": "console", "title": "Verify the sending domain", "required": true, "instructions": "Add the domain in the Resend dashboard, publish the returned SPF + DKIM DNS records, and wait for verified status — production sends from unverified domains fail."}, {"type": "console", "title": "Create a scoped API key", "required": true, "instructions": "One key per environment (sending-only scope for the app; full-access only for admin tooling). Store server-side as RESEND_API_KEY."}]}', '[{"kind": "source", "path": "src/lib/resend.ts", "priority": "essential"}, {"kind": "source", "path": "emails/**/*.tsx", "priority": "recommended", "description": "React Email templates"}]', '{"apiAreas": {"type": "multiselect", "label": "Resend API areas used", "options": ["emails", "batch", "domains", "audiences-contacts", "broadcasts", "webhooks"], "description": "Which parts of the Resend API this component calls — selected areas'' endpoint reference is embedded in the build instructions"}, "emailKinds": {"type": "multiselect", "label": "Email kinds", "options": ["transactional", "marketing-broadcasts"], "description": "Transactional goes through /emails; marketing goes through audiences + broadcasts — different suppression and compliance rules"}, "templateEngine": {"type": "enum", "label": "Templates", "default": "react-email", "options": ["react-email", "plain-html"], "description": "React Email components (type-safe, previewable) are the reason teams pick Resend; raw HTML strings are the fallback"}}', '[{"id": "react", "reason": "React Email templates"}, {"id": "nodejs", "reason": "Server-side sending"}]', false, NULL, NULL, '2026-08-30 12:07:21.442329+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''/components'':21C ''api'':8B,32C,46C ''app@example.com'':37C ''await'':34C ''const'':27C ''develop'':4B ''developer-first'':3B ''email'':7B,11B,17C,20C ''first'':5B ''import'':23C ''keep'':45C ''key'':33C,47C ''name'':44C ''new'':29C ''process.env.resend'':31C ''react'':10B,16C,19C,42C ''react-email'':15C,18C ''resend'':1A,2A,14C,24C,26C,28C,30C ''resend.emails.send'':35C ''secret'':55C ''server'':49C ''server-sid'':48C ''side'':50C ''sign'':54C ''subject'':40C ''support'':13B ''templat'':12B ''transact'':6B ''user.email'':39C ''verifi'':52C ''webhook'':22C,53C ''welcom'':41C ''welcomeemail'':43C');
INSERT INTO public.technology_catalog VALUES ('algolia', 'Algolia', NULL, '#6b7280', '["external-service", "search-engine"]', '{"purpose": "Hosted search-as-a-service providing fast full-text search, faceting, filtering, and AI-powered relevance for applications.", "configMode": "external", "provenance": {"notes": "Phase B9 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["React InstantSearch", "JavaScript", "REST API"], "antiPatterns": ["Exposing the Admin API key in client code", "Indexing all fields without selecting searchable attributes", "Not configuring relevance ranking", "Syncing data without handling deletions"], "apiReference": {"areas": {"search": {"endpoints": ["client.search / searchSingleIndex — query + facetFilters + page/hitsPerPage; typo tolerance and synonyms are index settings", "Facets: declare attributesForFaceting up front; faceting on undeclared attributes silently returns nothing", "Use secured API keys (generated server-side with filters baked in) for per-user visibility restrictions"]}, "indexing": {"endpoints": ["v5 clients (current — v4 superseded): client.saveObjects({indexName, objects}) with your stable objectID; partialUpdateObjects for field changes", "Replica indices carry alternative sort orders (price asc/desc) — sorting is an index property, not a query parameter", "Batch writes (1k-10k records per call); index settings (searchableAttributes, customRanking) live in code/config, not clicked in the dashboard", "Admin API key SERVER-SIDE ONLY"]}, "frontend-ui": {"endpoints": ["InstantSearch (react-instantsearch et al.) renders search UI against the search-only key — do not proxy searches through your backend, latency is the product", "Send click/conversion events (Insights API) — they feed AI re-ranking and analytics"]}}, "docsUrl": "https://www.algolia.com/doc"}, "bestPractices": ["Use the Search-Only API key on the client, Admin key on server only", "Configure searchable attributes and custom ranking", "Use facets for filtering UX", "Implement query suggestions for better UX"], "sdkInitPattern": "import { algoliasearch } from ''algoliasearch'';\n\nconst client = algoliasearch(process.env.ALGOLIA_APP_ID, process.env.ALGOLIA_ADMIN_KEY); // server-only\nawait client.saveObject({ indexName: ''products'', body: { objectID: id, name, price } });\n\n// browser gets the Search-Only key — or a secured key with enforced filters:\n// client.generateSecuredApiKey({ parentApiKey: searchKey, restrictions: { filters: `tenant:${tenantId}` } })", "securityGuidance": "Three key tiers, three jobs: the Admin key never leaves the server, the Search-Only key is what browsers get, and secured API keys (generated server-side with embedded filters and expiry) are how multi-tenant indices stay partitioned — a plain search key on a shared index searches EVERYONE''s records. Records are readable by any holder of a search key for the index: index what search needs, not whole documents with sensitive fields, and set unretrievableAttributes for fields that rank but must not return.", "setupInstructions": [{"url": "https://www.algolia.com/users/sign_up", "type": "account_setup", "title": "Create Algolia Application", "required": true, "instructions": "Sign up at algolia.com. Create a new application. Note the Application ID from the dashboard."}, {"type": "dashboard_config", "title": "Create and Configure Index", "required": true, "instructions": "In the Algolia dashboard, create an index. Configure searchable attributes (which fields to search), custom ranking (business metrics for relevance), and facets (filterable attributes)."}, {"type": "permissions", "title": "Get API Keys", "required": true, "instructions": "Under API Keys, note: Application ID, Search-Only API Key (safe for client), and Admin API Key (server-only, for indexing). Optionally create scoped API keys for specific indices."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export ALGOLIA_APP_ID=<application-id>", "export ALGOLIA_SEARCH_KEY=<search-only-key>", "export ALGOLIA_ADMIN_KEY=<admin-api-key>", "export ALGOLIA_INDEX_NAME=my_index"], "required": true, "instructions": "Add Algolia credentials to your application environment."}]}', '[]', '{"apiAreas": {"type": "multiselect", "label": "Algolia API areas used", "options": ["indexing", "search", "frontend-ui"], "description": "Which parts of the Algolia API this component calls — selected areas'' endpoint reference is embedded in the build instructions"}, "indexingModel": {"type": "enum", "label": "Indexing model", "default": "event-driven-sync", "options": ["event-driven-sync", "batch-rebuild"], "description": "Event-driven = update records on data change (webhooks/DB triggers); batch = periodic full rebuilds — pick one, mixing them creates drift"}}', '[]', false, NULL, NULL, '2026-05-18 02:35:27.802569+00', '2026-08-30 12:07:23.877005+00', 'Algolia', NULL, '''admin'':40C,81C ''ai'':19B ''ai-pow'':18B ''algolia'':1A,2A ''algoliasearch'':30C,32C,35C ''api'':28C,98C ''app'':37C ''applic'':23B ''await'':45C ''bodi'':49C ''browser'':54C,94C ''client'':34C ''client.generatesecuredapikey'':68C ''client.saveobject'':46C ''const'':33C ''document'':148C ''embed'':105C ''enforc'':66C ''everyon'':126C ''expiri'':108C ''facet'':15B ''fast'':10B ''field'':151C,156C ''filter'':16B,67C,72C,106C ''full'':12B ''full-text'':11B ''generat'':100C ''get'':55C,95C ''holder'':134C ''host'':3B ''id'':38C,51C ''import'':29C ''index'':124C,141C,142C ''indexnam'':47C ''indic'':114C ''instantsearch'':25C ''javascript'':26C ''job'':79C ''key'':41C,60C,64C,76C,82C,91C,99C,120C,138C ''leav'':84C ''multi'':112C ''multi-ten'':111C ''must'':160C ''name'':52C ''need'':145C ''never'':83C ''objectid'':50C ''parentapikey'':69C ''partit'':116C ''plain'':118C ''power'':20B ''price'':53C ''process.env.algolia'':36C,39C ''product'':48C ''provid'':9B ''rank'':158C ''react'':24C ''readabl'':131C ''record'':128C,129C ''relev'':21B ''rest'':27C ''restrict'':71C ''return'':162C ''search'':5B,14B,58C,89C,119C,125C,137C,144C ''search-as-a-servic'':4B ''search-on'':57C,88C ''searchkey'':70C ''secur'':63C,97C ''sensit'':150C ''server'':43C,86C,102C ''server-on'':42C ''server-sid'':101C ''servic'':8B ''set'':153C ''share'':123C ''side'':103C ''stay'':115C ''tenant'':73C,113C ''tenantid'':74C ''text'':13B ''three'':75C,78C ''tier'':77C ''unretrievableattribut'':154C ''whole'':147C');
INSERT INTO public.technology_catalog VALUES ('go-backend', 'Go', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/go-backend.png', '#00add8', '["backend-service", "worker", "webhook-handler", "cli-tool", "shared-library"]', '{"purpose": "The infrastructure-and-services language: single static binary, first-class concurrency, boring deployments. Default choice for network services, CLIs and anything that ships as one binary into a container. Its standard library carries more of the app than in any other mainstream stack.", "configMode": "code", "provenance": {"notes": "Stable idioms (stdlib-first, sqlc, race detector); live-docs upgrade rides N10(b). Row previously had EMPTY ai_context.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["net/http (1.22+ routing)", "sqlc", "pgx", "golangci-lint", "go test -race", "single-binary Docker images"], "antiPatterns": ["Goroutine leaks — every `go` needs an exit story (context cancellation or channel close)", "interface{} / any where a concrete type or small interface would do", "Framework-first architectures imported from other ecosystems (heavy DI containers, fat middleware stacks)", "Ignoring the error return — the linter catches it, wire the linter (golangci-lint)"], "apiReference": {"docsUrl": "https://go.dev/doc/"}, "bestPractices": ["Start with the stdlib (net/http with 1.22+ routing, database/sql) — add frameworks only when a concrete need appears", "Errors are values: wrap with %w, check with errors.Is/As; no panic in library/service code", "Context on every request path — cancellation and deadlines through every layer", "sqlc for data access: write SQL, generate typed Go — reviewable queries beat ORM magic", "Table-driven tests + the race detector in CI (go test -race)"], "sdkInitPattern": "go mod init myapp\\n// main.go\\npackage main\\n\\nimport (\\n  \"log\"\\n  \"net/http\"\\n)\\n\\nfunc main() {\\n  mux := http.NewServeMux()\\n  mux.HandleFunc(\"GET /health\", healthHandler)\\n  log.Fatal(http.ListenAndServe(\":8080\", mux))\\n}", "securityGuidance": "Use context.Context for request-scoped values and cancellation propagation. Use parameterized SQL queries via database/sql to prevent injection. Validate input with a struct validation library. Set timeouts on HTTP server, client, and database connections. Use crypto/rand for random values, never math/rand. Run go vet and staticcheck in CI. Use Go modules with go.sum for dependency integrity.", "commonApiPatterns": [{"name": "HTTP Handler", "description": "Handler function with DB query and error handling using closures for dependency injection", "codeTemplate": "func getUserHandler(db *sql.DB) http.HandlerFunc {\\n  return func(w http.ResponseWriter, r *http.Request) {\\n    id := r.PathValue(\"id\")\\n    var user User\\n    err := db.QueryRowContext(r.Context(), \"SELECT id, name FROM users WHERE id = $1\", id).Scan(&user.ID, &user.Name)\\n    if err == sql.ErrNoRows {\\n      http.Error(w, \"not found\", http.StatusNotFound)\\n      return\\n    }\\n    json.NewEncoder(w).Encode(user)\\n  }\\n}"}, {"name": "Middleware", "description": "Middleware pattern using handler wrapping and context for auth propagation", "codeTemplate": "func authMiddleware(next http.Handler) http.Handler {\\n  return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\\n    token := r.Header.Get(\"Authorization\")\\n    claims, err := validateToken(strings.TrimPrefix(token, \"Bearer \"))\\n    if err != nil {\\n      http.Error(w, \"unauthorized\", http.StatusUnauthorized)\\n      return\\n    }\\n    ctx := context.WithValue(r.Context(), userKey, claims)\\n    next.ServeHTTP(w, r.WithContext(ctx))\\n  })\\n}"}, {"name": "Graceful Shutdown", "description": "Graceful shutdown with signal handling and context timeout", "codeTemplate": "srv := &http.Server{Addr: \":8080\", Handler: mux}\\ngo func() { log.Fatal(srv.ListenAndServe()) }()\\nquit := make(chan os.Signal, 1)\\nsignal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)\\n<-quit\\nctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)\\ndefer cancel()\\nsrv.Shutdown(ctx)"}], "integrationPatterns": ["net/http (stdlib) or Chi/Echo for HTTP routing", "database/sql with pgx or sqlc for type-safe database access", "gRPC with protobuf for service-to-service communication", "slog (stdlib) for structured logging", "testing package with testcontainers for integration tests"], "configurationTemplate": "// go.mod\\nmodule myapp\\ngo 1.22\\n\\n// Makefile\\n.PHONY: build run test\\nbuild:\\n\\tCGO_ENABLED=0 go build -ldflags=\"-s -w\" -o bin/server ./cmd/server\\nrun:\\n\\tgo run ./cmd/server\\ntest:\\n\\tgo test -race -cover ./..."}', '[{"kind": "source", "path": "cmd/server/main.go", "language": "go", "description": "Server entry point"}, {"kind": "source", "path": "internal/handlers/handlers.go", "language": "go", "description": "HTTP handlers"}, {"kind": "config", "path": "go.mod", "language": "go", "description": "Go module definition"}]', '{"config": {"type": "enum", "label": "Config style", "default": "env-only", "options": ["env-only", "env-plus-flags"]}, "httpStack": {"type": "enum", "label": "HTTP stack", "default": "stdlib-net-http", "options": ["stdlib-net-http", "gin", "echo", "fiber"], "description": "Since Go 1.22 the stdlib router handles methods + path params — the honest default; frameworks earn their place only for middleware ecosystems"}, "dataAccess": {"type": "enum", "label": "Data access", "default": "sqlc", "options": ["sqlc", "gorm", "database-sql"], "description": "sqlc = SQL-first codegen (the Go-idiomatic pick); gorm = ORM convenience with its own cost"}}', '["database", "cache", "message-broker", "grpc-service"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', 'Go', '#00889B', '''/health'':89C ''1.22'':50C ''8080'':94C ''anyth'':26B ''app'':42B ''backend'':3A ''binari'':12B,31B,62C ''bore'':17B ''cancel'':105C ''carri'':38B ''choic'':20B ''ci'':145C ''class'':15B ''client'':128C ''clis'':24B ''concurr'':16B ''connect'':131C ''contain'':34B ''context.context'':98C ''crypto/rand'':133C ''databas'':130C ''database/sql'':112C ''default'':19B ''depend'':152C ''deploy'':18B ''docker'':63C ''first'':14B ''first-class'':13B ''get'':88C ''go'':1A,2A,57C,65C,140C,147C ''go.sum'':150C ''golangci'':55C ''golangci-lint'':54C ''healthhandl'':90C ''http'':126C ''http.listenandserve'':93C ''http.newservemux'':85C ''imag'':64C ''infrastructur'':6B ''infrastructure-and-servic'':5B ''init'':67C ''inject'':115C ''input'':117C ''integr'':153C ''languag'':9B ''librari'':37B,122C ''lint'':56C ''log'':76C ''log.fatal'':92C ''main'':72C,82C ''main.go'':70C ''mainstream'':47B ''math/rand'':138C ''mod'':66C ''modul'':148C ''mux'':84C,95C ''mux.handlefunc'':87C ''myapp'':68C ''n'':69C,73C,75C,77C,79C,80C,83C,86C,91C,96C ''net/http'':49C,78C ''network'':22B ''never'':137C ''nfunc'':81C ''nimport'':74C ''npackag'':71C ''one'':30B ''parameter'':108C ''pgx'':53C ''prevent'':114C ''propag'':106C ''queri'':110C ''race'':59C ''random'':135C ''request'':101C ''request-scop'':100C ''rout'':51C ''run'':139C ''scope'':102C ''server'':127C ''servic'':8B,23B ''set'':123C ''ship'':28B ''singl'':10B,61C ''single-binari'':60C ''sql'':109C ''sqlc'':52C ''stack'':48B ''standard'':36B ''static'':11B ''staticcheck'':143C ''struct'':120C ''test'':58C ''timeout'':124C ''use'':97C,107C,132C,146C ''valid'':116C,121C ''valu'':103C,136C ''vet'':141C ''via'':111C');
INSERT INTO public.technology_catalog VALUES ('gcp-firestore', 'Google Cloud Firestore', NULL, '#ffca28', '["database"]', '{"purpose": "Serverless document database from Firebase/Google Cloud with real-time synchronization and offline support built in. Use when building mobile or web applications that need real-time data sync across clients, offline-first capabilities, or when you want zero server management with automatic scaling. Firestore excels at chat applications, collaborative tools, live dashboards, and any app where users see changes instantly without polling. It handles user-facing read-heavy workloads well with its hierarchical document/collection model. Don''t use when you need complex relational queries with joins -- Firestore has no join support. Don''t use for analytics or aggregation-heavy workloads. Avoid when your query patterns require composite inequality filters across many fields. Avoid for write-heavy workloads exceeding 10,000 writes/second per collection group without careful sharding. Consider Supabase/PostgreSQL if you need relational modeling with real-time features.", "configMode": "declarative", "provenance": {"notes": "Schemas held to the stable API surface (release channels, machine families, storage types, database modes, processing units); live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Cloud Firestore", "Firebase SDK", "Firebase Console", "Firestore Security Rules", "Firebase Emulator Suite", "Firebase Extensions", "Firestore Bundles", "Firebase Admin SDK"], "antiPatterns": ["Deeply nesting subcollections creating complex query limitations", "Not setting up Firestore Security Rules leaving data publicly accessible", "Storing arrays that need to be queried by index position", "Using Firestore for complex analytics that require SQL-like aggregation", "Reading entire collections when you only need a subset of documents", "Creating hot-spot document counters without distributed counters pattern"], "apiReference": {"docsUrl": "https://firebase.google.com/docs/firestore"}, "bestPractices": ["Structure data as flat collections rather than deeply nested subcollections", "Denormalize data to match your read patterns and reduce the number of reads", "Use composite indexes for queries with multiple filters or ordering", "Use batched writes for atomic multi-document operations", "Implement Firestore Security Rules as your primary access control layer", "Use collection group queries for querying across subcollections", "Cache frequently read documents on the client to reduce billing costs"], "sdkInitPattern": "// Web (JavaScript)\\nimport { initializeApp } from \"firebase/app\";\\nimport { getFirestore, collection, doc, getDocs } from \"firebase/firestore\";\\nconst app = initializeApp({ projectId: \"my-project\", apiKey: \"...\" });\\nconst db = getFirestore(app);\\n// [Tailor to project language: Python=firebase-admin, Flutter=cloud_firestore, iOS=FirebaseFirestore, Android=firebase-firestore-ktx]", "securityGuidance": "Always deploy Firestore Security Rules -- the default open rules should never reach production. Validate data shape and field types in security rules using request.resource.data. Use Firebase App Check to prevent unauthorized API access from spoofed clients. Never trust client-provided timestamps -- use server timestamps (serverTimestamp()). Restrict Admin SDK usage to server-side code only.", "commonApiPatterns": [{"name": "CRUD Operations", "description": "Basic document CRUD with typed references", "codeTemplate": "import { doc, setDoc, getDoc, updateDoc, deleteDoc } from \"firebase/firestore\";\\nawait setDoc(doc(db, \"users\", userId), { name, email, createdAt: new Date() });\\nconst snap = await getDoc(doc(db, \"users\", userId));\\nif (snap.exists()) console.log(snap.data());\\nawait updateDoc(doc(db, \"users\", userId), { name: newName });\\nawait deleteDoc(doc(db, \"users\", userId));"}, {"name": "Real-Time Listener", "description": "Real-time query listener with change type detection", "codeTemplate": "import { collection, query, where, onSnapshot } from \"firebase/firestore\";\\nconst q = query(collection(db, \"messages\"), where(\"roomId\", \"==\", roomId));\\nconst unsub = onSnapshot(q, (snapshot) => {\\n  snapshot.docChanges().forEach((change) => {\\n    if (change.type === \"added\") handleNewMessage(change.doc.data());\\n  });\\n});\\n// Call unsub() to detach listener"}, {"name": "Batched Write", "description": "Atomic batch write for multiple document updates (max 500 per batch)", "codeTemplate": "import { writeBatch, doc } from \"firebase/firestore\";\\nconst batch = writeBatch(db);\\nfor (const item of items) {\\n  batch.set(doc(db, \"items\", item.id), item);\\n}\\nawait batch.commit();"}], "setupInstructions": [{"url": "https://console.firebase.google.com/", "type": "dashboard_config", "title": "Enable Firestore in Firebase Console", "required": true, "instructions": "In Firebase Console > Build > Firestore Database > Create Database. Choose production mode (locked by default) or test mode (open for 30 days). Select the closest region."}, {"type": "permissions", "title": "Configure Security Rules", "required": true, "instructions": "In Firestore > Rules, write security rules that validate authentication and data access patterns. Rules use a match/allow syntax. Test rules in the Rules Playground."}, {"type": "dashboard_config", "title": "Create Indexes", "required": false, "instructions": "Firestore automatically creates single-field indexes. For compound queries, create composite indexes in Firestore > Indexes, or let the SDK error message guide you to the auto-generation link."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export FIREBASE_API_KEY=<from-project-settings>", "export FIREBASE_PROJECT_ID=my-project", "export GOOGLE_APPLICATION_CREDENTIALS=/path/to/service-account.json"], "required": true, "instructions": "Use your Firebase project configuration for client-side apps. For server-side, use a service account."}], "integrationPatterns": ["Firebase Authentication for user identity integrated with security rules", "Cloud Functions for Firestore triggers (onCreate, onUpdate, onDelete)", "Firebase Hosting for deploying web apps with Firestore backend"], "configurationTemplate": "// firestore.rules\\nrules_version = ''2'';\\nservice cloud.firestore {\\n  match /databases/{database}/documents {\\n    match /users/{userId} {\\n      allow read: if request.auth != null && request.auth.uid == userId;\\n      allow create: if request.auth != null && request.auth.uid == userId;\\n      allow update: if request.auth != null && request.auth.uid == userId;\\n    }\\n    match /posts/{postId} {\\n      allow read: if true;\\n      allow write: if request.auth != null && request.auth.uid == resource.data.authorId;\\n    }\\n  }\\n}"}', '[{"kind": "config", "path": "firestore.rules"}, {"kind": "config", "path": "firestore.indexes.json"}]', '{"location": {"type": "enum", "label": "Location type", "default": "regional", "options": ["regional", "multi-region"], "description": "Set at creation and never changeable"}, "databaseMode": {"type": "enum", "label": "Database mode", "default": "native", "options": ["native", "datastore"], "description": "Native mode for new work — real-time listeners, offline persistence and the mobile/web SDKs. Datastore mode exists for App Engine-era compatibility and is chosen at creation, permanently"}, "securityRules": {"type": "boolean", "label": "Security Rules enforced", "default": true, "description": "Client SDKs talk to Firestore DIRECTLY — Security Rules are the entire authorization layer, not a backup for one"}, "compositeIndexes": {"type": "boolean", "label": "Composite indexes planned", "default": true, "description": "Any query with multiple filters or an order-by needs one; they are declared, not inferred"}, "offlinePersistence": {"type": "boolean", "label": "Offline persistence", "default": true}}', '["frontend-app", "backend-service", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#E0B020', '''000'':132B ''10'':131B ''access'':247C ''across'':36B,121B ''admin'':169C,204C,262C ''aggreg'':109B ''aggregation-heavi'':108B ''alway'':215C ''analyt'':106B ''android'':210C ''api'':246C ''apikey'':191C ''app'':63B,185C,195C,241C ''applic'':28B,56B ''automat'':50B ''avoid'':112B,124B ''build'':24B ''built'':20B ''bundl'':167C ''capabl'':41B ''care'':138B ''chang'':67B ''chat'':55B ''check'':242C ''client'':37B,250C,254C ''client-provid'':253C ''cloud'':2A,11B,152C,206C ''code'':269C ''collabor'':57B ''collect'':135B,179C ''complex'':92B ''composit'':118B ''consid'':140B ''consol'':157C ''dashboard'':60B ''data'':34B,229C ''databas'':8B ''db'':193C ''default'':221C ''deploy'':216C ''doc'':180C ''document'':7B ''document/collection'':84B ''emul'':162C ''exceed'':130B ''excel'':53B ''extens'':165C ''face'':75B ''featur'':151B ''field'':123B,232C ''filter'':120B ''firebas'':154C,156C,161C,164C,168C,203C,212C,240C ''firebase-admin'':202C ''firebase-firestore-ktx'':211C ''firebase/app'':176C ''firebase/firestore'':183C ''firebase/google'':10B ''firebasefirestor'':209C ''firestor'':3A,5A,52B,97B,153C,158C,166C,207C,213C,217C ''first'':40B ''flutter'':205C ''gcp'':4A ''getdoc'':181C ''getfirestor'':178C,194C ''googl'':1A ''group'':136B ''handl'':72B ''heavi'':78B,110B,128B ''hierarch'':83B ''inequ'':119B ''initializeapp'':174C,186C ''instant'':68B ''io'':208C ''javascript'':172C ''join'':96B,100B ''ktx'':214C ''languag'':200C ''live'':59B ''manag'':48B ''mani'':122B ''mobil'':25B ''model'':85B,146B ''my-project'':188C ''n'':196C ''nconst'':184C,192C ''need'':30B,91B,144B ''never'':225C,251C ''nimport'':173C,177C ''offlin'':18B,39B ''offline-first'':38B ''open'':222C ''pattern'':116B ''per'':134B ''poll'':70B ''prevent'':244C ''product'':227C ''project'':190C,199C ''projectid'':187C ''provid'':255C ''python'':201C ''queri'':94B,115B ''reach'':226C ''read'':77B ''read-heavi'':76B ''real'':14B,32B,149B ''real-tim'':13B,31B,148B ''relat'':93B,145B ''request.resource.data'':238C ''requir'':117B ''restrict'':261C ''rule'':160C,219C,223C,236C ''scale'':51B ''sdk'':155C,170C,263C ''secur'':159C,218C,235C ''see'':66B ''server'':47B,258C,267C ''server-sid'':266C ''serverless'':6B ''servertimestamp'':260C ''shape'':230C ''shard'':139B ''side'':268C ''spoof'':249C ''suit'':163C ''supabase/postgresql'':141B ''support'':19B,101B ''sync'':35B ''synchron'':16B ''tailor'':197C ''time'':15B,33B,150B ''timestamp'':256C,259C ''tool'':58B ''trust'':252C ''type'':233C ''unauthor'':245C ''usag'':264C ''use'':22B,88B,104B,237C,239C,257C ''user'':65B,74B ''user-fac'':73B ''valid'':228C ''want'':45B ''web'':27B,171C ''well'':80B ''without'':69B,137B ''workload'':79B,111B,129B ''write'':127B ''write-heavi'':126B ''writes/second'':133B ''zero'':46B');
INSERT INTO public.technology_catalog VALUES ('plausible', 'Plausible', NULL, '#5850EC', '["external-service", "monitoring"]', '{"purpose": "Privacy-first, cookieless web analytics that is lightweight and GDPR-friendly", "configMode": "external", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: model-knowledge 2026-08-10. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Plausible script", "Custom events", "Stats API", "Self-hosted or cloud"], "antiPatterns": ["Expecting user-level funnels or identity tracking from aggregate analytics", "Adding both Plausible and heavyweight analytics scripts to the same page", "Tracking every click as a custom event and drowning goal reports"], "apiReference": {"areas": {"stats": {"endpoints": ["`POST /api/v2/query` — the Stats API: metrics (visitors, pageviews, conversion), date ranges, filters, breakdowns in one JSON query", "Bearer auth with an API key scoped to the site; embed key metrics in your own admin instead of iframing dashboards"]}, "events": {"endpoints": ["`POST /api/event` — server-side/custom event capture (name, url, domain; props for goal breakdowns)", "The script tag covers pageviews; this endpoint is for custom goals and script-blocked contexts", "Proxy the script through your domain — the standing ad-blocker mitigation"]}}, "docsUrl": "https://plausible.io/docs"}, "bestPractices": ["Load the script with defer and serve via proxy to reduce blocking", "Track conversions as custom events with props, not pageviews", "Use the Stats API to embed key metrics in internal dashboards", "Prefer Plausible when cookie banners must be avoided"], "sdkInitPattern": "<script defer data-domain=\"example.com\" src=\"https://plausible.io/js/script.js\"></script>", "securityGuidance": "The tracking script is public by design — the sensitive surface is the Stats API key (server-side only) and the dashboard: shared-link URLs are bearer capabilities, so treat them like tokens and set passwords on shared dashboards for anything non-public. Do not smuggle user identifiers into custom event props — the product''s value is that it holds no PII; keep it that way. Self-hosted instances need TLS, a locked admin account, and SMTP credentials handled like any secret.", "setupInstructions": [{"type": "account_setup", "title": "Add the site in Plausible", "required": true, "instructions": "Add the site (or self-hosted instance) and embed the lightweight script tag with your domain — no cookies, no consent banner needed for the default script."}, {"type": "environment_variable", "title": "Create an API key for the Stats API (if reading analytics)", "required": false, "instructions": "Generate a Stats API key in account settings and provide it server-side; aggregate stats are still business data."}]}', '[{"kind": "source", "path": "src/components/PlausibleScript.tsx", "priority": "recommended"}]', '{"hosting": {"type": "enum", "label": "Hosting", "default": "plausible-cloud", "options": ["plausible-cloud", "self-hosted"]}, "apiAreas": {"type": "multiselect", "label": "Plausible API areas used", "options": ["events", "stats"], "description": "Which parts of the Plausible API this component calls — selected areas'' endpoint reference is embedded in the build instructions"}}', '[{"id": "posthog", "reason": "Product analytics complement"}]', false, NULL, NULL, '2026-08-30 12:07:21.442329+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''account'':104C ''admin'':103C ''analyt'':8B ''anyth'':68C ''api'':21C,40C ''bearer'':54C ''capabl'':55C ''cloud'':26C ''cookieless'':6B ''credenti'':107C ''custom'':18C,78C ''dashboard'':48C,66C ''design'':33C ''event'':19C,79C ''first'':5B ''friend'':15B ''gdpr'':14B ''gdpr-friend'':13B ''handl'':108C ''hold'':88C ''host'':24C,97C ''identifi'':76C ''instanc'':98C ''keep'':91C ''key'':41C ''lightweight'':11B ''like'':59C,109C ''link'':51C ''lock'':102C ''need'':99C ''non'':70C ''non-publ'':69C ''password'':63C ''pii'':90C ''plausibl'':1A,2A,16C ''privaci'':4B ''privacy-first'':3B ''product'':82C ''prop'':80C ''public'':31C,71C ''script'':17C,29C ''secret'':111C ''self'':23C,96C ''self-host'':22C,95C ''sensit'':35C ''server'':43C ''server-sid'':42C ''set'':62C ''share'':50C,65C ''shared-link'':49C ''side'':44C ''smtp'':106C ''smuggl'':74C ''stat'':20C,39C ''surfac'':36C ''tls'':100C ''token'':60C ''track'':28C ''treat'':57C ''url'':52C ''user'':75C ''valu'':84C ''way'':94C ''web'':7B');
INSERT INTO public.technology_catalog VALUES ('deno-edge', 'Deno (Supabase Edge)', NULL, '#6b7280', '["serverless-function"]', '{"purpose": "Deno-based edge runtime for Supabase Edge Functions — TypeScript-first, web-standard APIs, sub-50ms cold starts, Supabase client built in. Constraints are the design: limited execution time and no persistent connections — long work belongs on a worker node, and database access goes through the pooler or PostgREST, not held connections.", "configMode": "code", "provenance": {"notes": "Phase B8c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Deno runtime", "supabase-js", "npm: specifiers", "Web Crypto", "supabase functions deploy"], "antiPatterns": ["Holding database connections open — use the connection pooler or supabase-js, connections do not survive the isolate", "Long-running work against the execution-time limit — queue it instead", "Porting Node-specific APIs (fs, net) into edge code"], "apiReference": {"docsUrl": "https://docs.deno.com/deploy/"}, "bestPractices": ["Web-standard APIs (fetch, Request/Response, crypto) — code written this way ports across edge runtimes", "npm: specifiers for npm packages (no bare npm by default); jsr for Deno-native", "Secrets via supabase secrets set, read from Deno.env — never bundled", "Verify webhooks/JWTs IN the function — the edge is the trust boundary", "Keep functions single-purpose and fast; anything long-running is a worker node, not an edge function"], "sdkInitPattern": "Deno.serve(async (req: Request) => {\n  const url = new URL(req.url);\n  if (url.pathname === ''/api/orders'') {\n    const user = await verifyJwt(req.headers.get(''authorization''));\n    if (!user) return new Response(''unauthorized'', { status: 401 });\n    return Response.json(await listOrders(user.id));\n  }\n  return new Response(''not found'', { status: 404 });\n});", "securityGuidance": "Secrets come from the deployment''s environment variables (Deno.env), never module constants — edge source ships to many isolates and bundles are inspectable in CI logs. Verify JWTs on every request (issuer, audience, expiry) rather than trusting forwarded headers, remember each isolate is stateless and globals are per-isolate (no in-memory session state), and outbound fetch from the edge runs with your credentials: allow-list the hosts your function calls rather than proxying arbitrary user-supplied URLs."}', '[{"kind": "code", "path": "main.ts", "language": "typescript", "description": "Deno.serve entrypoint with per-request JWT verification"}, {"kind": "config", "path": "deno.json", "language": "json", "description": "Tasks, imports map, compiler options"}]', '{"imports": {"type": "multiselect", "label": "Import sources", "options": ["npm-specifiers", "jsr", "https-urls"], "description": "How dependencies enter the function — npm: specifiers cover most needs; jsr for Deno-native packages"}, "boundResources": {"type": "multiselect", "label": "Talks to", "options": ["supabase-db", "supabase-storage", "external-apis"], "description": "What the function reaches — drives the env/secret checklist in the packet"}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''/api/orders'':84C ''401'':98C ''404'':110C ''50ms'':24B ''access'':51B ''allow'':177C ''allow-list'':176C ''api'':21B ''arbitrari'':187C ''async'':74C ''audienc'':142C ''author'':90C ''await'':87C,101C ''base'':8B ''belong'':44B ''built'':29B ''bundl'':130C ''call'':183C ''ci'':134C ''client'':28B ''cold'':25B ''come'':112C ''connect'':41B,60B ''const'':77C,85C ''constant'':122C ''constraint'':31B ''credenti'':175C ''crypto'':69C ''databas'':50B ''deno'':1A,4A,7B,61C ''deno-bas'':6B ''deno.env'':119C ''deno.serve'':73C ''deploy'':72C,115C ''design'':34B ''edg'':3A,5A,9B,13B,123C,171C ''environ'':117C ''everi'':139C ''execut'':36B ''expiri'':143C ''fetch'':168C ''first'':17B ''forward'':147C ''found'':108C ''function'':14B,71C,182C ''global'':155C ''goe'':52B ''header'':148C ''held'':59B ''host'':180C ''in-memori'':161C ''inspect'':132C ''isol'':128C,151C,159C ''issuer'':141C ''js'':65C ''jwts'':137C ''limit'':35B ''list'':178C ''listord'':102C ''log'':135C ''long'':42B ''mani'':127C ''memori'':163C ''modul'':121C ''never'':120C ''new'':79C,94C,105C ''node'':48B ''npm'':66C ''outbound'':167C ''per'':158C ''per-isol'':157C ''persist'':40B ''pooler'':55B ''postgrest'':57B ''proxi'':186C ''rather'':144C,184C ''rememb'':149C ''req'':75C ''req.headers.get'':89C ''req.url'':81C ''request'':76C,140C ''respons'':95C,106C ''response.json'':100C ''return'':93C,99C,104C ''run'':172C ''runtim'':10B,62C ''secret'':111C ''session'':164C ''ship'':125C ''sourc'':124C ''specifi'':67C ''standard'':20B ''start'':26B ''state'':165C ''stateless'':153C ''status'':97C,109C ''sub'':23B ''sub-50ms'':22B ''supabas'':2A,12B,27B,64C,70C ''supabase-j'':63C ''suppli'':190C ''time'':37B ''trust'':146C ''typescript'':16B ''typescript-first'':15B ''unauthor'':96C ''url'':78C,80C,191C ''url.pathname'':83C ''user'':86C,92C,189C ''user-suppli'':188C ''user.id'':103C ''variabl'':118C ''verifi'':136C ''verifyjwt'':88C ''web'':19B,68C ''web-standard'':18B ''work'':43B ''worker'':47B');
INSERT INTO public.technology_catalog VALUES ('argocd', 'ArgoCD', NULL, '#6b7280', '["ci-cd-pipeline"]', '{"purpose": "Declarative GitOps continuous delivery tool for Kubernetes. Monitors Git repositories and automatically synchronizes cluster state to match the desired state defined in manifests.", "configMode": "definition-as-code", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Kubernetes", "Helm", "Kustomize", "YAML"], "antiPatterns": ["Storing secrets in Git without encryption", "Manual syncs defeating GitOps purpose", "Not using health checks for sync status", "Running ArgoCD without RBAC configured"], "apiReference": {"docsUrl": "https://argo-cd.readthedocs.io/"}, "bestPractices": ["Separate app manifests from application code repos", "Use ApplicationSets for multi-cluster deployments", "Configure sync policies with self-heal and auto-prune", "Use Argo Rollouts for progressive delivery", "Enable SSO via OIDC for team access"], "securityGuidance": "Argo CD deploys whatever the tracked repo says — repo write access IS cluster deploy access, so the git review gate is your change control. Constrain each AppProject to its allowed source repos, destination clusters/namespaces, and resource kinds (a project that can deploy ClusterRoles can escalate). Disable the built-in admin after wiring SSO, map RBAC roles least-privilege, and never store secrets in git plaintext — pair with sealed-secrets/external-secrets. The API/UI is a deploy console: SSO in front, and the cluster credentials it holds are its crown jewels.", "setupInstructions": [{"url": "https://argo-cd.readthedocs.io/en/stable/getting_started/", "type": "toolchain_install", "title": "Install ArgoCD", "commands": ["kubectl create namespace argocd", "kubectl apply -n argocd -f https://raw.githubusercontent.com/argoproj/argo-cd/stable/manifests/install.yaml"], "required": true, "instructions": "Install ArgoCD into your Kubernetes cluster using kubectl or Helm. Creates the argocd namespace with all required components."}, {"type": "permissions", "title": "Get Initial Admin Password", "commands": ["kubectl -n argocd get secret argocd-initial-admin-secret -o jsonpath=\"{.data.password}\" | base64 -d"], "required": true, "instructions": "Retrieve the auto-generated admin password from the Kubernetes secret. Change it after first login."}, {"type": "dashboard_config", "title": "Add Repository Credentials", "commands": ["argocd repo add https://github.com/org/repo --username git --password <token>"], "required": true, "instructions": "In ArgoCD UI (Settings > Repositories) or via CLI, add your Git repository. For private repos, provide SSH key or HTTPS token credentials."}, {"type": "manual_workflow", "title": "Create Application Resource", "commands": ["argocd app create my-app --repo https://github.com/org/repo --path k8s/overlays/production --dest-server https://kubernetes.default.svc --dest-namespace default"], "required": true, "instructions": "Create an ArgoCD Application custom resource pointing to your Git repo path containing Kubernetes manifests, Helm chart, or Kustomize config."}], "configurationTemplate": "# argocd/app.yaml\napiVersion: argoproj.io/v1alpha1\nkind: Application\nmetadata:\n  name: api\n  namespace: argocd\nspec:\n  project: platform\n  source:\n    repoURL: https://github.com/example/deploy\n    targetRevision: main\n    path: k8s/api\n  destination:\n    server: https://kubernetes.default.svc\n    namespace: api\n  syncPolicy:\n    automated: { prune: true, selfHeal: true }"}', '[{"kind": "config", "path": "argocd/app.yaml", "language": "yaml", "description": "Application manifest — project-constrained source and destination"}]', '{"scope": {"type": "enum", "label": "Install scope", "default": "cluster-wide", "options": ["cluster-wide", "namespaced"]}, "structure": {"type": "enum", "label": "App structure", "default": "applicationsets", "options": ["app-of-apps", "applicationsets", "flat-apps"]}, "syncPolicy": {"type": "enum", "label": "Sync policy", "default": "auto-prune-selfheal", "options": ["auto-prune-selfheal", "manual-approval"], "description": "Full GitOps = auto-sync with prune + self-heal; manual gates for regulated flows"}}', '[]', false, NULL, NULL, '2026-05-18 02:39:19.313183+00', '2026-08-30 12:07:23.877005+00', 'ArgoCD', NULL, '''/external-secrets'':102C ''access'':40C,44C ''admin'':80C ''allow'':59C ''api/ui'':104C ''appproject'':56C ''argo'':30C ''argocd'':1A,2A ''automat'':14B ''built'':78C ''built-in'':77C ''cd'':31C ''chang'':52C ''cluster'':16B,42C,114C ''clusterrol'':72C ''clusters/namespaces'':63C ''consol'':108C ''constrain'':54C ''continu'':5B ''control'':53C ''credenti'':115C ''crown'':120C ''declar'':3B ''defin'':23B ''deliveri'':6B ''deploy'':32C,43C,71C,107C ''desir'':21B ''destin'':62C ''disabl'':75C ''escal'':74C ''front'':111C ''gate'':49C ''git'':11B,47C,95C ''gitop'':4B ''helm'':27C ''hold'':117C ''jewel'':121C ''kind'':66C ''kubernet'':9B,26C ''kustom'':28C ''least'':88C ''least-privileg'':87C ''manifest'':25B ''map'':84C ''match'':19B ''monitor'':10B ''never'':91C ''pair'':97C ''plaintext'':96C ''privileg'':89C ''project'':68C ''rbac'':85C ''repo'':36C,38C,61C ''repositori'':12B ''resourc'':65C ''review'':48C ''role'':86C ''say'':37C ''seal'':100C ''sealed-secret'':99C ''secret'':93C,101C ''sourc'':60C ''sso'':83C,109C ''state'':17B,22B ''store'':92C ''synchron'':15B ''tool'':7B ''track'':35C ''whatev'':33C ''wire'':82C ''write'':39C ''yaml'':29C');
INSERT INTO public.technology_catalog VALUES ('rabbitmq', 'RabbitMQ', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/rabbitmq.png', '#ff6600', '["message-broker", "queue"]', '{"purpose": "Traditional message queuing with flexible routing (direct, topic, fanout, headers exchange types), request-reply patterns, and priority queues. Best for architectures needing complex message routing, delivery guarantees, and per-message acknowledgments. Ideal when routing complexity matters more than raw throughput. Not suited for event replay or log-based streaming; use Kafka for those.", "configMode": "declarative", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["RabbitMQ 3.13+", "AMQP 0-9-1", "amqplib", "Management Plugin", "Shovel/Federation"], "antiPatterns": ["Not implementing message acknowledgments", "Unbounded queue growth without limits", "Auto-ack without processing confirmation", "Creating too many connections instead of channels", "Using auto-delete queues for important messages"], "apiReference": {"docsUrl": "https://www.rabbitmq.com/docs"}, "bestPractices": ["Use appropriate exchange types for routing patterns", "Configure dead letter exchanges for failed messages", "Implement publisher confirms for reliability", "Use prefetch count to control consumer throughput", "Set message TTL and queue length limits", "Use durable queues and persistent messages", "Implement proper connection/channel management"], "freshnessNote": "RabbitMQ 4.x: Khepri (Raft metadata store) replaced Mnesia as the default — the historical split-brain/recovery outage class is addressed; quorum queues are the production default and classic queues legacy; 4.1 (2026-02) advances native streams. Previous inspector schema was host/port connection fields — replaced with architecture decisions.", "sdkInitPattern": "import amqp from ''amqplib'';\n\nconst conn = await amqp.connect(process.env.AMQP_URL); // amqps:// with per-service credentials\nconst ch = await conn.createChannel();\nawait ch.assertQueue(''orders'', { durable: true, arguments: { ''x-dead-letter-exchange'': ''orders.dlx'' } });\nch.sendToQueue(''orders'', Buffer.from(JSON.stringify({ orderId })), { persistent: true });", "securityGuidance": "Delete the default guest user (it only works on localhost, but its existence invites config drift) and create per-service users with vhost-scoped configure/write/read permissions — the vhost is your isolation boundary. TLS on AMQP and the management UI, management plugin reachable only from admin networks (it is a full broker admin surface), dead-letter exchanges + bounded retries so poison messages surface, and messages carry references, not secrets.", "setupInstructions": [{"type": "toolchain_install", "title": "Install RabbitMQ", "commands": ["docker run -d --name rabbitmq -p 5672:5672 -p 15672:15672 rabbitmq:3-management"], "required": true, "instructions": "Install via Docker (recommended) or system package. The Docker image includes the management plugin by default."}, {"url": "http://localhost:15672", "type": "dashboard_config", "title": "Access Management UI", "required": true, "instructions": "Open http://localhost:15672 in your browser. Default credentials are guest/guest (only works from localhost). Create a new admin user for production."}, {"type": "permissions", "title": "Create Virtual Host and User", "required": true, "instructions": "Create a dedicated vhost for your application. Create a user with appropriate permissions (configure, write, read) scoped to that vhost. Remove the default guest user in production."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export RABBITMQ_URL=amqp://myuser:mypass@localhost:5672/myvhost", "export RABBITMQ_USER=myuser", "export RABBITMQ_PASS=mypass"], "required": true, "instructions": "Add RabbitMQ connection details to your application environment."}]}', '[{"kind": "source", "path": "src/messaging/rabbitmq-client.ts", "priority": "essential", "description": "RabbitMQ connection and channel management"}, {"kind": "source", "path": "src/messaging/consumers/", "priority": "essential", "description": "Message consumer handlers"}]', '{"protocol": {"type": "enum", "label": "Protocol", "default": "amqp-0-9-1", "options": ["amqp-0-9-1", "amqp-1-0", "mqtt"]}, "queueType": {"type": "enum", "label": "Queue type", "default": "quorum", "options": ["quorum", "streams", "classic-legacy"], "description": "Quorum queues are the production default (Raft-replicated); streams for high-throughput append/replay; classic queues are the legacy tier"}, "clustering": {"type": "enum", "label": "Clustering", "default": "single-node", "options": ["single-node", "three-node-cluster"], "description": "Quorum queues need 3+ nodes to mean anything — a single node with quorum queues is a naming exercise"}}', '["backend-service", "worker"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#CC5200', '''-1'':62C ''-9'':61C ''0'':60C ''3.13'':58C ''acknowledg'':35B ''admin'':151C,158C ''amqp'':59C,68C,141C ''amqp.connect'':74C ''amqplib'':63C,70C ''architectur'':24B ''argument'':91C ''await'':73C,84C,86C ''base'':53B ''best'':22B ''bound'':164C ''boundari'':138C ''broker'':157C ''buffer.from'':100C ''carri'':172C ''ch'':83C ''ch.assertqueue'':87C ''ch.sendtoqueue'':98C ''complex'':26B,39B ''config'':119C ''configure/write/read'':131C ''conn'':72C ''conn.createchannel'':85C ''const'':71C,82C ''creat'':122C ''credenti'':81C ''dead'':94C,161C ''dead-lett'':160C ''default'':107C ''delet'':105C ''deliveri'':29B ''direct'':9B ''drift'':120C ''durabl'':89C ''event'':48B ''exchang'':13B,96C,163C ''exist'':117C ''fanout'':11B ''flexibl'':7B ''full'':156C ''guarante'':30B ''guest'':108C ''header'':12B ''ideal'':36B ''import'':67C ''invit'':118C ''isol'':137C ''json.stringify'':101C ''kafka'':56B ''letter'':95C,162C ''localhost'':114C ''log'':52B ''log-bas'':51B ''manag'':64C,144C,146C ''matter'':40B ''messag'':4B,27B,34B,168C,171C ''need'':25B ''network'':152C ''order'':88C,99C ''orderid'':102C ''orders.dlx'':97C ''pattern'':18B ''per'':33B,79C,124C ''per-messag'':32B ''per-servic'':78C,123C ''permiss'':132C ''persist'':103C ''plugin'':65C,147C ''poison'':167C ''prioriti'':20B ''process.env.amqp'':75C ''queu'':5B ''queue'':21B ''rabbitmq'':1A,2A,57C ''raw'':43B ''reachabl'':148C ''refer'':173C ''replay'':49B ''repli'':17B ''request'':16B ''request-repli'':15B ''retri'':165C ''rout'':8B,28B,38B ''scope'':130C ''secret'':175C ''servic'':80C,125C ''shovel/federation'':66C ''stream'':54B ''suit'':46B ''surfac'':159C,169C ''throughput'':44B ''tls'':139C ''topic'':10B ''tradit'':3B ''true'':90C,104C ''type'':14B ''ui'':145C ''url'':76C ''use'':55B ''user'':109C,126C ''vhost'':129C,134C ''vhost-scop'':128C ''work'':112C ''x'':93C ''x-dead-letter-exchang'':92C');
INSERT INTO public.technology_catalog VALUES ('astro', 'Astro', NULL, '#ff5d01', '["frontend-app"]', '{"purpose": "Content-focused web framework that ships zero JavaScript by default, with island architecture for interactive components", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Astro 4+", "TypeScript", "MDX", "React/Vue/Svelte islands"], "antiPatterns": ["Using client:load on every component negating Astro zero-JS advantage", "Building a heavily interactive SPA in Astro instead of using React/Vue/Svelte directly", "Not using content collections for blog/docs content", "Importing heavy JS libraries in Astro component frontmatter when they should be in islands", "Using set:html with user-provided content without sanitization"], "apiReference": {"docsUrl": "https://docs.astro.build"}, "bestPractices": ["Use content collections for structured content", "Implement islands architecture for interactive components", "Leverage zero-JS by default", "Use proper image optimization with astro:assets", "Implement view transitions for smooth navigation"], "sdkInitPattern": "npm create astro@latest my-app && cd my-app && npm install\\n---\\n// src/pages/index.astro\\nconst title = \"Hello Astro\";\\n---\\n<html>\\n  <body><h1>{title}</h1></body>\\n</html>", "securityGuidance": "Astro components render static HTML by default with no client-side JS -- minimal attack surface. Use set:html only with sanitized content. Validate input in API endpoints and server-side logic. Use environment variables via import.meta.env with PUBLIC_ prefix only for client-safe values. Set security headers via middleware or hosting configuration.", "commonApiPatterns": [{"name": "Astro Component with Data", "description": "Dynamic route with content collection data loading", "codeTemplate": "---\\n// src/pages/blog/[slug].astro\\nimport { getEntry } from \"astro:content\";\\nconst { slug } = Astro.params;\\nconst post = await getEntry(\"blog\", slug!);\\nif (!post) return Astro.redirect(\"/404\");\\nconst { Content } = await post.render();\\n---\\n<article>\\n  <h1>{post.data.title}</h1>\\n  <Content />\\n</article>"}, {"name": "Interactive Island", "description": "Partial hydration with client directives for interactive islands", "codeTemplate": "---\\nimport Counter from \"../components/Counter.tsx\";\\n---\\n<Counter client:visible />\\n<!-- Also: client:load, client:idle, client:media -->"}, {"name": "API Endpoint", "description": "Server endpoint for API routes in SSR mode", "codeTemplate": "// src/pages/api/users.ts\\nimport type { APIRoute } from \"astro\";\\nexport const GET: APIRoute = async () => {\\n  const users = await db.user.findMany();\\n  return new Response(JSON.stringify(users), {\\n    headers: { \"Content-Type\": \"application/json\" },\\n  });\\n};"}], "integrationPatterns": ["Content Collections for type-safe Markdown/MDX content management", "React, Vue, Svelte, or Solid components as interactive islands", "Tailwind CSS integration for utility-first styling", "Adapters for Vercel, Netlify, Cloudflare, or Node.js deployment", "View Transitions API for SPA-like page transitions"], "configurationTemplate": "// astro.config.mjs\\nimport { defineConfig } from \"astro/config\";\\nimport react from \"@astrojs/react\";\\nimport tailwind from \"@astrojs/tailwind\";\\nimport node from \"@astrojs/node\";\\nexport default defineConfig({\\n  output: \"hybrid\",\\n  adapter: node({ mode: \"standalone\" }),\\n  integrations: [react(), tailwind()],\\n});"}', '[{"kind": "source", "path": "src/pages/index.astro", "language": "astro", "description": "Home page"}, {"kind": "config", "path": "astro.config.mjs", "language": "javascript", "description": "Astro configuration"}]', '{"output": {"type": "enum", "label": "Output", "default": "static", "options": ["static", "server", "hybrid-prerender"], "description": "Astro is static-first; server output only when real request-time work exists"}, "islandFrameworks": {"type": "multiselect", "label": "Island frameworks", "options": ["react", "vue", "svelte", "solid", "none-zero-js"], "description": "Which frameworks hydrate islands — none is a legitimate and fast answer"}, "contentCollections": {"type": "boolean", "label": "Content collections", "default": true}}', '["rest-api", "cdn"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-30 12:07:23.877005+00', NULL, '#D64E01', '''4'':21C ''api'':77C ''app'':32C,36C ''architectur'':16B ''astro'':1A,2A,20C,28C,45C,51C ''attack'':65C ''cd'':33C ''client'':61C,95C ''client-saf'':94C ''client-sid'':60C ''compon'':19B,52C ''configur'':105C ''content'':4B,73C ''content-focus'':3B ''creat'':27C ''default'':13B,57C ''endpoint'':78C ''environ'':85C ''focus'':5B ''framework'':7B ''header'':100C ''hello'':44C ''host'':104C ''html'':55C,69C ''import.meta.env'':88C ''input'':75C ''instal'':38C ''interact'':18B ''island'':15B,25C ''javascript'':11B ''js'':63C ''latest'':29C ''logic'':83C ''mdx'':23C ''middlewar'':102C ''minim'':64C ''my-app'':30C,34C ''n'':39C,40C,46C,47C,48C,50C ''nconst'':42C ''npm'':26C,37C ''prefix'':91C ''public'':90C ''react/vue/svelte'':24C ''render'':53C ''safe'':96C ''sanit'':72C ''secur'':99C ''server'':81C ''server-sid'':80C ''set'':68C,98C ''ship'':9B ''side'':62C,82C ''src/pages/index.astro'':41C ''static'':54C ''surfac'':66C ''titl'':43C,49C ''typescript'':22C ''use'':67C,84C ''valid'':74C ''valu'':97C ''variabl'':86C ''via'':87C,101C ''web'':6B ''zero'':10B');
INSERT INTO public.technology_catalog VALUES ('aws', 'Amazon Web Services', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws.png', '#FF9900', '["aws"]', '{"purpose": "AWS cloud provider identifier for infrastructure container nodes. Use this as the technology for cloud-project, vpc, and subnet roles when the deployment target is AWS. Individual AWS managed services (Aurora, SQS, Lambda, EC2, etc.) have their own technology entries and should be assigned to their respective leaf-role nodes, NOT to infrastructure containers.", "lifecycle": "platform-umbrella", "provenance": {"notes": "B10 lifecycle stamp; body content predates provenance tracking. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS CloudFormation", "AWS CDK", "Terraform", "AWS Organizations", "AWS Control Tower"], "antiPatterns": ["Using a single AWS account for all environments", "Assigning IAM policies directly to users instead of roles/groups", "Running workloads in default VPCs with public IPs", "Ignoring resource tagging making cost attribution impossible", "Using long-lived access keys instead of IAM roles and temporary credentials"], "bestPractices": ["Use VPCs with private subnets for workloads", "Enable CloudTrail for audit logging", "Use AWS Organizations for multi-account strategy", "Tag all resources for cost allocation"], "sdkInitPattern": "aws configure --profile my-project && export AWS_PROFILE=my-project && aws sts get-caller-identity", "securityGuidance": "Enable AWS CloudTrail in all regions for audit logging. Use AWS Organizations with SCPs to enforce guardrails. Never use root account credentials for day-to-day operations. Enable GuardDuty for threat detection. Use AWS Config rules for compliance monitoring. Enforce MFA on all IAM users. Use AWS SSO for centralized access management.", "commonApiPatterns": [{"name": "Create Organization", "description": "Set up AWS Organizations for multi-account strategy", "codeTemplate": "aws organizations create-organization --feature-set ALL && aws organizations create-account --email prod@company.com --account-name production"}, {"name": "CloudFormation Stack", "description": "Deploy infrastructure via CloudFormation", "codeTemplate": "aws cloudformation deploy --template-file infra.yml --stack-name my-stack --capabilities CAPABILITY_NAMED_IAM --parameter-overrides Env=prod"}, {"name": "Cost Explorer", "description": "Query cost and usage data grouped by tag", "codeTemplate": "aws ce get-cost-and-usage --time-period Start=2024-01-01,End=2024-02-01 --granularity MONTHLY --metrics BlendedCost --group-by Type=TAG,Key=Environment"}], "integrationPatterns": ["AWS Organizations + Control Tower for multi-account governance", "CloudTrail + CloudWatch for centralized logging and monitoring", "IAM Identity Center (SSO) for federated access across accounts", "AWS Config for continuous compliance evaluation", "AWS Cost Explorer + Budgets for cost governance"], "configurationTemplate": "# AWS Landing Zone pattern (Terraform)\\nprovider \"aws\" {\\n  region = var.primary_region\\n  default_tags {\\n    tags = {\\n      Environment = var.environment\\n      ManagedBy   = \"terraform\"\\n    }\\n  }\\n}\\nresource \"aws_organizations_organization\" \"root\" {\\n  feature_set = \"ALL\"\\n  enabled_policy_types = [\"SERVICE_CONTROL_POLICY\"]\\n}"}', '[]', '{}', '[]', false, NULL, NULL, '2026-02-20 14:25:20.585755+00', '2026-08-30 12:07:23.877005+00', NULL, '#EC7211', '''access'':140C ''account'':109C ''amazon'':1A ''assign'':49B ''audit'':96C ''aurora'':36B ''aw'':4A,5B,31B,33B,61C,63C,66C,68C,71C,78C,83C,90C,99C,123C,136C ''caller'':87C ''cdk'':64C ''central'':139C ''cloud'':6B,20B ''cloud-project'':19B ''cloudform'':62C ''cloudtrail'':91C ''complianc'':127C ''config'':124C ''configur'':72C ''contain'':11B,60B ''control'':69C ''credenti'':110C ''day'':113C,115C ''day-to-day'':112C ''deploy'':28B ''detect'':121C ''ec2'':39B ''enabl'':89C,117C ''enforc'':104C,129C ''entri'':45B ''etc'':40B ''export'':77C ''get'':86C ''get-caller-ident'':85C ''guardduti'':118C ''guardrail'':105C ''iam'':133C ''ident'':88C ''identifi'':8B ''individu'':32B ''infrastructur'':10B,59B ''lambda'':38B ''leaf'':54B ''leaf-rol'':53B ''log'':97C ''manag'':34B,141C ''mfa'':130C ''monitor'':128C ''my-project'':74C,80C ''never'':106C ''node'':12B,56B ''oper'':116C ''organ'':67C,100C ''profil'':73C,79C ''project'':21B,76C,82C ''provid'':7B ''region'':94C ''respect'':52B ''role'':25B,55B ''root'':108C ''rule'':125C ''scps'':102C ''servic'':3A,35B ''sqs'':37B ''sso'':137C ''sts'':84C ''subnet'':24B ''target'':29B ''technolog'':17B,44B ''terraform'':65C ''threat'':120C ''tower'':70C ''use'':13B,98C,107C,122C,135C ''user'':134C ''vpc'':22B ''web'':2A');
INSERT INTO public.technology_catalog VALUES ('aws-api-gateway', 'AWS API Gateway', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-api-gateway.png', '#ff9900', '["api-gateway"]', '{"purpose": "Fully managed AWS service for creating, publishing, and managing APIs at any scale with built-in authorization and throttling", "configMode": "declarative", "provenance": {"notes": "Phase B5 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS API Gateway", "REST API/HTTP API", "Lambda Proxy", "Cognito Authorizer", "AWS SAM/CDK"], "antiPatterns": ["Not implementing rate limiting", "Using REST API when HTTP API suffices", "Not validating request models", "Ignoring CORS configuration", "Not monitoring 4xx/5xx error rates"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/apigateway/"}, "bestPractices": ["Use HTTP API for simple proxying (cheaper, faster)", "Use REST API when you need request/response transformation", "Implement proper throttling and usage plans", "Use Lambda authorizers for custom auth", "Enable CloudWatch logging", "Use stages for deployment management"], "securityGuidance": "Every production route gets an authorizer — IAM, JWT, or Lambda; authorization NONE is for public content decisions, not a default. Enable throttling and usage plans so one client cannot exhaust the backend, validate request models at the gateway so garbage never reaches your functions, and attach WAF on internet-facing REST APIs. Access logs should capture caller identity, not request bodies.", "configurationTemplate": "# HTTP API with a JWT authorizer\r\naws apigatewayv2 create-api --name my-api --protocol-type HTTP\r\naws apigatewayv2 create-authorizer --api-id API_ID --authorizer-type JWT \\\r\n  --identity-source ''$request.header.Authorization'' --name jwt-auth \\\r\n  --jwt-configuration Audience=my-audience,Issuer=https://issuer.example.com"}', '[{"kind": "config", "path": "infra/aws/api-gateway.tf"}]', '{"cors": {"type": "boolean", "label": "CORS", "default": true, "description": "Enable cross-origin access for browser clients"}, "apiType": {"type": "enum", "label": "API type", "default": "HTTP", "options": ["HTTP", "REST", "WebSocket"], "description": "HTTP: cheapest/simplest for Lambda+HTTP backends (~71% cheaper); REST: adds management features (usage plans, API keys, per-client throttling); WebSocket: bidirectional real-time"}, "customDomain": {"type": "boolean", "label": "Custom domain", "default": false, "description": "Attach an ACM-certified custom domain"}, "authorization": {"type": "enum", "label": "Authorization", "default": "jwt-cognito", "options": ["none", "iam", "jwt-cognito", "lambda-authorizer"], "description": "How callers authenticate at the gateway"}, "throttleRateRps": {"type": "number", "label": "Throttle rate (req/s)", "default": 100, "description": "Steady-state request rate limit"}}', '["serverless-function", "backend-service", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#C0125F', '''access'':92C ''api'':2A,5A,16B,28C,32C,91C ''api/http'':31C ''attach'':84C ''author'':24B,36C,44C,49C ''aw'':1A,4A,9B,27C,37C ''backend'':70C ''bodi'':100C ''built'':22B ''built-in'':21B ''caller'':96C ''cannot'':67C ''captur'':95C ''client'':66C ''cognito'':35C ''content'':54C ''creat'':12B ''decis'':55C ''default'':58C ''enabl'':59C ''everi'':39C ''exhaust'':68C ''face'':89C ''fulli'':7B ''function'':82C ''garbag'':78C ''gateway'':3A,6A,29C,76C ''get'':42C ''iam'':45C ''ident'':97C ''internet'':88C ''internet-fac'':87C ''jwt'':46C ''lambda'':33C,48C ''log'':93C ''manag'':8B,15B ''model'':73C ''never'':79C ''none'':50C ''one'':65C ''plan'':63C ''product'':40C ''proxi'':34C ''public'':53C ''publish'':13B ''reach'':80C ''request'':72C,99C ''rest'':30C,90C ''rout'':41C ''sam/cdk'':38C ''scale'':19B ''servic'':10B ''throttl'':26B,60C ''usag'':62C ''valid'':71C ''waf'':85C');
INSERT INTO public.technology_catalog VALUES ('aws-cloudfront', 'AWS CloudFront', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-cloudfront.png', '#8C4FFF', '["cdn"]', '{"purpose": "AWS''s global content delivery network (CDN) that caches and delivers content from edge locations worldwide. Use when you need low-latency delivery of static assets (images, CSS, JS), dynamic API acceleration, or DDoS protection at the edge. CloudFront integrates natively with S3, ALB, API Gateway, and Lambda@Edge/CloudFront Functions for edge compute. Ideal for web applications needing global performance, video streaming, and any workload where proximity to end users matters. CloudFront also provides SSL/TLS termination at the edge with AWS Certificate Manager. Don''t use when your users are all in a single region and latency is already acceptable -- a simple ALB or S3 with Transfer Acceleration may suffice. Don''t use for real-time bidirectional communication (WebSockets) unless you specifically configure it. Avoid when cost sensitivity is extreme and CloudFlare or a simpler CDN would meet your needs at lower cost.", "configMode": "declarative", "provenance": {"notes": "Schema kept to stable API surface (queue/topic types, price classes, managed cache policies, record/routing basics); full live fetch upgrades this in the 4a-3 verification pass.", "method": "model-knowledge", "sources": ["https://docs.aws.amazon.com/"], "verifiedAt": "2026-07-27"}, "typicalTech": ["AWS CloudFront", "CloudFront Functions", "Lambda@Edge", "AWS Certificate Manager", "S3 Origin", "ALB Origin", "AWS WAF", "Terraform aws_cloudfront_distribution"], "antiPatterns": ["Using CloudFront without Origin Access Control allowing direct S3 access", "Setting excessively long TTLs for dynamic content causing stale data", "Not invalidating cache after deployments leaving users on old versions", "Forwarding unnecessary headers/cookies to origin defeating cache effectiveness", "Using a single behavior for all content instead of separating static and dynamic paths", "Not enabling compression wasting bandwidth on text assets"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/cloudfront/"}, "bestPractices": ["Use Origin Access Control (OAC) to restrict S3 access exclusively through CloudFront", "Set appropriate Cache-Control headers on origins to control edge caching behavior", "Use cache policies and origin request policies instead of legacy cache behavior settings", "Enable compression (gzip, brotli) for text-based content", "Use Lambda@Edge or CloudFront Functions for URL rewriting, auth, and A/B testing", "Configure custom error pages for 4xx/5xx responses", "Use CloudFront access logs in S3 for traffic analysis and debugging"], "sdkInitPattern": "# AWS CLI create distribution\\naws cloudfront create-distribution --distribution-config file://dist-config.json\\n# Terraform is preferred for CloudFront configuration (see configurationTemplate)", "securityGuidance": "Use Origin Access Control (OAC) to prevent direct access to S3 origins. Attach AWS WAF to CloudFront for bot protection, rate limiting, and IP filtering. Enforce HTTPS with redirect-to-https viewer protocol policy. Use TLS 1.2+ minimum protocol version. Use signed URLs or signed cookies for private content. Set appropriate security headers via response headers policy (CSP, HSTS, X-Frame-Options).", "commonApiPatterns": [{"name": "Create Invalidation", "description": "Invalidate all cached content after a deployment", "codeTemplate": "aws cloudfront create-invalidation --distribution-id E1234567890 --paths \"/*\""}, {"name": "CloudFront Function", "description": "CloudFront Function for SPA URL rewriting", "codeTemplate": "function handler(event) {\\n  var request = event.request;\\n  var uri = request.uri;\\n  // SPA routing: rewrite paths without extensions to /index.html\\n  if (!uri.includes(''.'')) {\\n    request.uri = ''/index.html'';\\n  }\\n  return request;\\n}"}, {"name": "Signed URL", "description": "Generate signed URL for private content access", "codeTemplate": "import { getSignedUrl } from \"@aws-sdk/cloudfront-signer\";\\nconst signedUrl = getSignedUrl({\\n  url: `https://d123.cloudfront.net/private/file.pdf`,\\n  keyPairId: process.env.CF_KEY_PAIR_ID!,\\n  privateKey: process.env.CF_PRIVATE_KEY!,\\n  dateLessThan: new Date(Date.now() + 3600000).toISOString()\\n});"}], "integrationPatterns": ["S3 + CloudFront for static website hosting with global edge delivery", "ALB + CloudFront for dynamic API acceleration with edge caching", "AWS WAF for web application firewall protection at the CDN edge"], "configurationTemplate": "resource \"aws_cloudfront_distribution\" \"main\" {\\n  enabled             = true\\n  default_root_object = \"index.html\"\\n  aliases             = [\"app.example.com\"]\\n  origin {\\n    domain_name              = aws_s3_bucket.assets.bucket_regional_domain_name\\n    origin_id                = \"s3-assets\"\\n    origin_access_control_id = aws_cloudfront_origin_access_control.main.id\\n  }\\n  default_cache_behavior {\\n    allowed_methods        = [\"GET\", \"HEAD\"]\\n    cached_methods         = [\"GET\", \"HEAD\"]\\n    target_origin_id       = \"s3-assets\"\\n    cache_policy_id        = \"658327ea-f89d-4fab-a63d-7e88639e58f6\" # CachingOptimized\\n    viewer_protocol_policy = \"redirect-to-https\"\\n    compress               = true\\n  }\\n  viewer_certificate {\\n    acm_certificate_arn      = aws_acm_certificate.main.arn\\n    ssl_support_method       = \"sni-only\"\\n    minimum_protocol_version = \"TLSv1.2_2021\"\\n  }\\n  restrictions {\\n    geo_restriction { restriction_type = \"none\" }\\n  }\\n}"}', '[{"kind": "config", "path": "infra/aws/cloudfront.tf"}]', '{"originType": {"type": "enum", "label": "Origin", "default": "s3", "options": ["s3", "alb", "api-gateway", "custom"], "description": "What CloudFront fronts"}, "priceClass": {"type": "enum", "label": "Price class", "default": "PriceClass_100", "options": ["PriceClass_100", "PriceClass_200", "PriceClass_All"], "description": "Edge-location coverage vs cost (100 = NA+EU)"}, "cachePolicy": {"type": "enum", "label": "Cache policy", "default": "CachingOptimized", "options": ["CachingOptimized", "CachingDisabled", "custom"], "description": "Managed policy; disable for dynamic APIs"}, "edgeCompute": {"type": "enum", "label": "Edge compute", "default": "none", "options": ["none", "cloudfront-functions", "lambda-edge"], "description": "Lightweight request rewrites (Functions) vs full logic (Lambda@Edge)"}, "httpsPolicy": {"type": "enum", "label": "Viewer HTTPS", "default": "redirect-to-https", "options": ["redirect-to-https", "https-only"]}}', '["frontend-app", "backend-service", "rest-api", "storage"]', false, NULL, NULL, '2026-02-16 19:35:14.881443+00', '2026-08-30 12:07:23.877005+00', NULL, '#7340D6', '''1.2'':228C ''acceler'':37B,113B ''accept'':105B ''access'':193C,199C ''alb'':49B,108B,161C ''alreadi'':104B ''also'':78B ''api'':36B,50B ''applic'':62B ''appropri'':242C ''asset'':31B ''attach'':203C ''avoid'':131B ''aw'':1A,3A,5B,86B,150C,156C,163C,166C,169C,204C ''bidirect'':123B ''bot'':209C ''cach'':13B ''cdn'':11B,142B ''certif'':87B,157C ''cli'':170C ''cloudflar'':138B ''cloudfront'':2A,4A,44B,77B,151C,152C,167C,174C,187C,207C ''communic'':124B ''comput'':58B ''config'':180C ''configur'':129B,188C ''configurationtempl'':190C ''content'':8B,16B,240C ''control'':194C ''cooki'':237C ''cost'':133B,149B ''creat'':171C,176C ''create-distribut'':175C ''csp'':249C ''css'':33B ''ddos'':39B ''deliv'':15B ''deliveri'':9B,28B ''direct'':198C ''dist-config.json'':181C ''distribut'':168C,172C,177C,179C ''distribution-config'':178C ''dynam'':35B ''edg'':18B,43B,57B,84B,155C ''edge/cloudfront'':54B ''end'':74B ''enforc'':216C ''extrem'':136B ''filter'':215C ''frame'':253C ''function'':55B,153C ''gateway'':51B ''global'':7B,64B ''header'':244C,247C ''hsts'':250C ''https'':217C,222C ''ideal'':59B ''imag'':32B ''integr'':45B ''ip'':214C ''js'':34B ''lambda'':53B,154C ''latenc'':27B,102B ''limit'':212C ''locat'':19B ''low'':26B ''low-lat'':25B ''lower'':148B ''manag'':88B,158C ''matter'':76B ''may'':114B ''meet'':144B ''minimum'':229C ''n'':182C ''nativ'':46B ''naw'':173C ''need'':24B,63B,146B ''network'':10B ''oac'':195C ''option'':254C ''origin'':160C,162C,192C,202C ''perform'':65B ''polici'':225C,248C ''prefer'':185C ''prevent'':197C ''privat'':239C ''protect'':40B,210C ''protocol'':224C,230C ''provid'':79B ''proxim'':72B ''rate'':211C ''real'':121B ''real-tim'':120B ''redirect'':220C ''redirect-to-http'':219C ''region'':100B ''respons'':246C ''s3'':48B,110B,159C,201C ''secur'':243C ''see'':189C ''sensit'':134B ''set'':241C ''sign'':233C,236C ''simpl'':107B ''simpler'':141B ''singl'':99B ''specif'':128B ''ssl/tls'':80B ''static'':30B ''stream'':67B ''suffic'':115B ''termin'':81B ''terraform'':165C,183C ''time'':122B ''tls'':227C ''transfer'':112B ''unless'':126B ''url'':234C ''use'':21B,91B,118B,191C,226C,232C ''user'':75B,94B ''version'':231C ''via'':245C ''video'':66B ''viewer'':223C ''waf'':164C,205C ''web'':61B ''websocket'':125B ''workload'':70B ''worldwid'':20B ''would'':143B ''x'':252C ''x-frame-opt'':251C');
INSERT INTO public.technology_catalog VALUES ('clickhouse', 'ClickHouse', NULL, '#6b7280', '["data-warehouse"]', '{"purpose": "Column-oriented OLAP database for real-time analytics at very large scale — extremely fast aggregations over compressed columnar data with real-time ingestion. Open source. NOT for OLTP: point updates/deletes are second-class (mutations), and the design assumes append-heavy workloads; the app''s transactional store stays Postgres/MySQL, ClickHouse answers the analytical questions.", "configMode": "declarative", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["MergeTree family", "materialized views", "async inserts", "Kafka table engine", "TTL retention", "clickhouse-client"], "antiPatterns": ["OLTP patterns: row-by-row inserts, frequent UPDATE/DELETE, SELECT * point lookups", "Joining huge tables without understanding distributed join semantics", "Self-hosting a replicated cluster casually — ZooKeeper/Keeper coordination is real ops (the cloud offering exists for a reason)"], "apiReference": {"docsUrl": "https://clickhouse.com/docs"}, "bestPractices": ["Batch inserts (thousands+ rows per insert, or async_insert) — the ingestion model is the #1 thing AIs get wrong", "ORDER BY in the table definition IS the index — design it from the dominant query, not the insert shape", "Use ReplacingMergeTree/AggregatingMergeTree for dedup/rollups instead of UPDATE-style thinking", "Materialized views for continuous aggregation at insert time", "TTL clauses for retention — analytics tables grow forever otherwise"], "sdkInitPattern": "import { createClient } from ''@clickhouse/client'';\n\nconst clickhouse = createClient({\n  url: process.env.CLICKHOUSE_URL,\n  username: process.env.CLICKHOUSE_USER,\n  password: process.env.CLICKHOUSE_PASSWORD,\n});\nconst rows = await clickhouse.query({\n  query: ''SELECT route, count() FROM events WHERE tenant_id = {tenant:String} GROUP BY route'',\n  query_params: { tenant: tenantId },\n  format: ''JSONEachRow'',\n});", "securityGuidance": "The default user ships passwordless — set a password or disable it, and define per-service users with database/table grants plus quotas and complexity limits (max_memory_usage, max_execution_time) so one analyst query cannot starve the cluster. Always query_params, never interpolated SQL. Bind HTTP (8123) and native (9000) interfaces to internal networks with TLS; analytics tables concentrate the business — row policies or tenant-filtered views for shared access."}', '[{"kind": "config", "path": "config.d/server.xml", "language": "xml", "description": "Listen hosts, TLS, storage"}, {"kind": "config", "path": "users.d/app-users.xml", "language": "xml", "description": "Per-service users with grants, quotas, query limits"}]', '{"ingestion": {"type": "enum", "label": "Ingestion path", "default": "batch-inserts", "options": ["batch-inserts", "kafka-engine", "async-inserts"], "description": "ClickHouse wants BIG batches — thousands of tiny inserts is the classic misuse"}, "deployment": {"type": "enum", "label": "Deployment", "default": "single-node", "options": ["single-node", "cluster-replicated", "clickhouse-cloud"], "description": "Single node goes surprisingly far; cluster management is the real cost of self-hosting (the reason ClickHouse Cloud exists)"}, "tableEngine": {"type": "enum", "label": "Primary engine", "default": "mergetree", "options": ["mergetree", "replacingmergetree", "aggregatingmergetree"]}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''8123'':162C ''9000'':165C ''access'':186C ''aggreg'':19B ''alway'':154C ''analyst'':148C ''analyt'':12B,59B,172C ''answer'':57B ''app'':50B ''append'':46B ''append-heavi'':45B ''assum'':44B ''async'':65C ''await'':93C ''bind'':160C ''busi'':176C ''cannot'':150C ''class'':39B ''clickhous'':1A,2A,56B,73C,80C ''clickhouse-cli'':72C ''clickhouse.query'':94C ''clickhouse/client'':78C ''client'':74C ''cluster'':153C ''column'':4B ''column-ori'':3B ''columnar'':22B ''complex'':138C ''compress'':21B ''concentr'':174C ''const'':79C,91C ''count'':98C ''createcli'':76C,81C ''data'':23B ''databas'':7B ''database/table'':133C ''default'':116C ''defin'':127C ''design'':43B ''disabl'':124C ''engin'':69C ''event'':100C ''execut'':144C ''extrem'':17B ''famili'':62C ''fast'':18B ''filter'':182C ''format'':113C ''grant'':134C ''group'':106C ''heavi'':47B ''http'':161C ''id'':103C ''import'':75C ''ingest'':28B ''insert'':66C ''interfac'':166C ''intern'':168C ''interpol'':158C ''jsoneachrow'':114C ''kafka'':67C ''larg'':15B ''limit'':139C ''materi'':63C ''max'':140C,143C ''memori'':141C ''mergetre'':61C ''mutat'':40B ''nativ'':164C ''network'':169C ''never'':157C ''olap'':6B ''oltp'':33B ''one'':147C ''open'':29B ''orient'':5B ''param'':110C,156C ''password'':88C,90C,122C ''passwordless'':119C ''per'':129C ''per-servic'':128C ''plus'':135C ''point'':34B ''polici'':178C ''postgres/mysql'':55B ''process.env.clickhouse'':83C,86C,89C ''queri'':95C,109C,149C,155C ''question'':60B ''quota'':136C ''real'':10B,26B ''real-tim'':9B,25B ''retent'':71C ''rout'':97C,108C ''row'':92C,177C ''scale'':16B ''second'':38B ''second-class'':37B ''select'':96C ''servic'':130C ''set'':120C ''share'':185C ''ship'':118C ''sourc'':30B ''sql'':159C ''starv'':151C ''stay'':54B ''store'':53B ''string'':105C ''tabl'':68C,173C ''tenant'':102C,104C,111C,181C ''tenant-filt'':180C ''tenantid'':112C ''time'':11B,27B,145C ''tls'':171C ''transact'':52B ''ttl'':70C ''updates/deletes'':35B ''url'':82C,84C ''usag'':142C ''user'':87C,117C,131C ''usernam'':85C ''view'':64C,183C ''workload'':48B');
INSERT INTO public.technology_catalog VALUES ('gcp-cloud-sql', 'Google Cloud SQL', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/gcp-cloud-sql.png', '#4285F4', '["database"]', '{"purpose": "Cloud SQL is Google Cloud''s fully managed relational database service for MySQL, PostgreSQL, and SQL Server workloads. Use it for transactional applications, web backends, line-of-business systems, and managed relational databases that benefit from automated backups, patching, replication, and operational simplicity. Choose Cloud SQL over Spanner when you need a familiar single-region relational database instead of globally scaled strongly consistent architecture, and over AlloyDB when extreme PostgreSQL performance is not the primary driver. Do not use it for petabyte-scale analytical stores, wide-column NoSQL workloads, or globally distributed horizontally scaled OLTP systems where Bigtable or Spanner are better fits.", "configMode": "declarative", "provenance": {"notes": "Phase B1 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Cloud SQL", "App Engine", "Cloud Run", "Google Kubernetes Engine", "Database Migration Service", "Secret Manager", "Cloud Monitoring"], "antiPatterns": ["Using Cloud SQL as a cache, queue, or event streaming backbone instead of purpose-built services", "Allowing many autoscaled services to connect directly without connection pooling or limits", "Opening public network access broadly without private networking or strict authorized sources", "Choosing Cloud SQL for globally distributed high-scale OLTP that requires horizontal scale-out", "Treating the database as the integration point for every asynchronous workflow in the platform", "Skipping query tuning and index design because the service is managed"], "apiReference": {"docsUrl": "https://cloud.google.com/sql/docs"}, "bestPractices": ["Use private IP connectivity or tightly scoped network access instead of broad public exposure", "Choose the database engine and edition based on application compatibility and operational requirements", "Apply schema migrations through versioned deployment workflows rather than manual console changes", "Monitor query performance, connection counts, storage growth, and replication health continuously", "Use connection pooling and managed connectors to avoid exhausting database connections from autoscaled services", "Separate production, staging, and development instances to reduce blast radius and configuration drift", "Design backup, failover, and maintenance windows around explicit recovery objectives"], "securityGuidance": "Private IP plus the Cloud SQL Auth Proxy or language connectors is the connection model — do not open a public IP with password auth. Use IAM database authentication where the engine supports it so access follows identity, not shared passwords. Enforce SSL for any path that is not the proxy, and keep automated backups + point-in-time recovery on for production instances.", "configurationTemplate": "# Private-IP instance; connect through the Cloud SQL connector/proxy, not a public IP\r\ngcloud sql instances create my-postgres \\\r\n  --database-version=POSTGRES_16 --region=us-central1 \\\r\n  --network=projects/my-project/global/networks/my-vpc --no-assign-ip"}', '[{"kind": "schema", "path": "db/schema.sql", "priority": "essential", "description": "Core relational schema definitions for Cloud SQL engines"}, {"kind": "schema", "path": "db/migrations/", "priority": "essential", "description": "Versioned migration scripts for Cloud SQL schema evolution"}, {"kind": "config", "path": "infra/cloud-sql.yaml", "priority": "recommended", "description": "Infrastructure-as-code definition for Cloud SQL instances, networking, and backups"}]', '{"engine": {"type": "string", "label": "Database Engine", "default": "postgresql", "options": ["postgresql", "mysql", "sqlserver"], "description": "Primary database engine for the Cloud SQL instance"}, "edition": {"type": "enum", "label": "Edition", "default": "enterprise", "options": ["enterprise", "enterprise-plus"], "description": "Enterprise Plus adds the local-SSD data cache (up to 4x read performance), performance- and memory-optimized machine series, sub-second maintenance downtime, cross-region DR with near-zero RTO, and 30-day query insights"}, "privateIp": {"type": "boolean", "label": "Private IP", "default": true, "description": "Use private IP connectivity for application access"}, "availability": {"type": "string", "label": "Availability", "default": "regional", "options": ["zonal", "regional"], "description": "Instance availability configuration"}, "readReplicas": {"type": "number", "label": "Read replicas", "default": 0, "description": "Cross-region replicas double as the DR story"}, "connectionMethod": {"type": "enum", "label": "Connection method", "default": "cloud-sql-auth-proxy", "options": ["cloud-sql-auth-proxy", "private-ip-direct", "public-ip-authorized-networks"], "description": "The Auth Proxy gives IAM-based connections without managing SSL or IP allowlists"}, "backupRetentionDays": {"type": "number", "label": "Backup retention (days)", "default": 7}, "pointInTimeRecovery": {"type": "boolean", "label": "Point-in-time recovery", "default": true}}', '["backend-service", "worker", "monitoring", "auth-provider", "api-gateway"]', false, NULL, NULL, '2026-03-14 21:18:17.549457+00', '2026-08-30 12:07:23.877005+00', NULL, '#2F6AD8', '''access'':164C ''alloydb'':75B ''analyt'':93B ''app'':116C ''applic'':29B ''architectur'':72B ''auth'':136C,153C ''authent'':157C ''autom'':44B,182C ''backend'':31B ''backup'':45B,183C ''benefit'':42B ''better'':112B ''bigtabl'':108B ''busi'':35B ''choos'':51B ''cloud'':2A,5A,7B,11B,52B,114C,118C,128C,134C ''column'':97B ''connect'':143C ''connector'':140C ''consist'':71B ''databas'':16B,40B,65B,123C,156C ''distribut'':102B ''driver'':84B ''enforc'':170C ''engin'':117C,122C,160C ''extrem'':77B ''familiar'':60B ''fit'':113B ''follow'':165C ''fulli'':13B ''gcp'':4A ''global'':68B,101B ''googl'':1A,10B,120C ''horizont'':103B ''iam'':155C ''ident'':166C ''instanc'':192C ''instead'':66B ''ip'':131C,150C ''keep'':181C ''kubernet'':121C ''languag'':139C ''line'':33B ''line-of-busi'':32B ''manag'':14B,38B,127C ''migrat'':124C ''model'':144C ''monitor'':129C ''mysql'':19B ''need'':58B ''nosql'':98B ''oltp'':105B ''open'':147C ''oper'':49B ''password'':152C,169C ''patch'':46B ''path'':174C ''perform'':79B ''petabyt'':91B ''petabyte-scal'':90B ''plus'':132C ''point'':185C ''point-in-tim'':184C ''postgresql'':20B,78B ''primari'':83B ''privat'':130C ''product'':191C ''proxi'':137C,179C ''public'':149C ''recoveri'':188C ''region'':63B ''relat'':15B,39B,64B ''replic'':47B ''run'':119C ''scale'':69B,92B,104B ''secret'':126C ''server'':23B ''servic'':17B,125C ''share'':168C ''simplic'':50B ''singl'':62B ''single-region'':61B ''spanner'':55B,110B ''sql'':3A,6A,8B,22B,53B,115C,135C ''ssl'':171C ''store'':94B ''strong'':70B ''support'':161C ''system'':36B,106B ''time'':187C ''transact'':28B ''use'':25B,87B,154C ''web'':30B ''wide'':96B ''wide-column'':95B ''workload'':24B,99B');
INSERT INTO public.technology_catalog VALUES ('gcp-bigquery', 'Google BigQuery', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/gcp-bigquery.png', '#4285F4', '["data-warehouse"]', '{"purpose": "BigQuery is Google Cloud''s fully managed and serverless enterprise data warehouse and analytics platform for SQL-based analysis across large structured and semi-structured datasets. Use it for reporting, ELT, interactive analytics, data lakehouse patterns, and AI-assisted analysis where separation of storage and compute and massive query scale are important. Choose BigQuery over Cloud SQL when workloads are analytical rather than transactional, and over Bigtable when SQL, warehousing, and ad hoc analytics matter more than low-latency wide-column access. Do not use it as an OLTP database, low-latency request store, or cache for operational application traffic.", "configMode": "declarative", "provenance": {"notes": "Phase B1 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["BigQuery", "Dataflow", "Cloud Storage", "Looker", "Vertex AI", "Cloud Monitoring", "Dataplex"], "antiPatterns": ["Using BigQuery as a transactional application database for frequent row-level updates and point lookups", "Running unpartitioned full-table scans on large datasets without cost guardrails", "Treating one shared dataset as a dumping ground for unrelated domains without ownership boundaries", "Expecting sub-millisecond request latency for operational application paths", "Skipping data modeling and governance because the platform is serverless", "Using BigQuery as a substitute for cache, queue, or high-frequency operational state storage"], "apiReference": {"docsUrl": "https://cloud.google.com/bigquery/docs"}, "bestPractices": ["Partition and cluster tables based on dominant filter and scan patterns to control cost and improve performance", "Separate raw, curated, and serving datasets with clear ownership and lifecycle boundaries", "Use scheduled queries, materialized views, and data transfer patterns for repeatable analytics pipelines", "Model access controls at dataset, table, and column levels for governed multi-team analytics", "Monitor slot usage, query cost, and scan volume continuously for workload optimization", "Use external tables and lakehouse patterns intentionally rather than mixing unmanaged file access with critical curated tables", "Treat SQL transformations, schema evolution, and semantic models as versioned assets in delivery workflows"], "sdkInitPattern": "import { BigQuery } from ''@google-cloud/bigquery'';\r\n\r\n// Application Default Credentials: workload identity in GCP, or a service account locally.\r\nconst bigquery = new BigQuery();\r\nconst [rows] = await bigquery.query({\r\n  query: ''SELECT name FROM `my-project.my_dataset.users` WHERE id = @id'',\r\n  params: { id: userId }, // ALWAYS parameterized — never string-built SQL\r\n});", "securityGuidance": "Always use parameterized queries — string-building SQL from user input is injection, in BigQuery like anywhere else. Grant dataset-level IAM narrowly and expose subsets through authorized views or row-level access policies rather than widening dataset roles. Authenticate with Application Default Credentials / workload identity — avoid exporting long-lived service-account JSON keys. Set maximum-bytes-billed on ad-hoc query paths so a bad query cannot become a cost incident."}', '[{"kind": "schema", "path": "analytics/bigquery-schema.sql", "priority": "essential", "description": "BigQuery dataset, table, partitioning, and clustering definitions"}, {"kind": "config", "path": "analytics/scheduled-queries.json", "priority": "recommended", "description": "Scheduled query and transformation configuration for recurring analytics jobs"}, {"kind": "config", "path": "infra/bigquery.yaml", "priority": "recommended", "description": "Infrastructure-as-code definition for BigQuery datasets, tables, and access controls"}]', '{"edition": {"type": "enum", "label": "Edition", "default": "none-on-demand", "options": ["none-on-demand", "standard", "enterprise", "enterprise-plus"], "description": "Capacity pricing is bought through editions. Standard for ad-hoc/dev; Enterprise adds security, governance and ML; Enterprise Plus for mission-critical uptime and regulatory needs. Legacy flat-rate and flex commitments stopped being purchasable on 2023-07-05"}, "clustering": {"type": "boolean", "label": "Clustering", "default": true}, "pricingModel": {"type": "enum", "label": "Pricing model", "default": "on-demand", "options": ["on-demand", "capacity-autoscaling", "capacity-commitment"], "description": "On-demand bills per TiB scanned with up to ~2000 shared slots per project; capacity bills per slot-hour and needs an edition"}, "storageLayout": {"type": "enum", "label": "Storage layout", "default": "managed-tables", "options": ["managed-tables", "external-tables", "biglake", "hybrid"]}, "partitionedTables": {"type": "boolean", "label": "Partitioned Tables", "default": true, "description": "Use partitioning for large analytical tables"}, "partitioningStrategy": {"type": "enum", "label": "Partitioning", "default": "time-column", "options": ["time-ingestion", "time-column", "integer-range", "none"], "description": "The single biggest lever on on-demand cost — an unpartitioned table scans in full"}}', '["object-storage", "ml-pipeline", "monitoring", "backend-service", "worker"]', false, NULL, NULL, '2026-03-14 21:41:53.531106+00', '2026-08-30 12:07:23.877005+00', NULL, '#2F6AD8', '''/bigquery'':127C ''access'':91B,200C ''account'':138C,221C ''across'':25B ''ad'':79B,231C ''ad-hoc'':230C ''ai'':45B,117C ''ai-assist'':44B ''alway'':159C,166C ''analysi'':24B,47B ''analyt'':18B,39B,68B,81B ''anywher'':182C ''applic'':109B,128C,209C ''assist'':46B ''authent'':207C ''author'':194C ''avoid'':214C ''await'':146C ''bad'':237C ''base'':23B ''becom'':240C ''bigqueri'':2A,4A,5B,61B,111C,122C,141C,143C,180C ''bigquery.query'':147C ''bigtabl'':74B ''bill'':228C ''build'':172C ''built'':164C ''byte'':227C ''cach'':106B ''cannot'':239C ''choos'':60B ''cloud'':8B,63B,113C,118C,126C ''column'':90B ''comput'':53B ''const'':140C,144C ''cost'':242C ''credenti'':130C,211C ''data'':15B,40B ''databas'':99B ''dataflow'':112C ''dataplex'':120C ''dataset'':32B,186C,205C ''dataset-level'':185C ''default'':129C,210C ''els'':183C ''elt'':37B ''enterpris'':14B ''export'':215C ''expos'':191C ''fulli'':10B ''gcp'':3A,134C ''googl'':1A,7B,125C ''google-cloud'':124C ''grant'':184C ''hoc'':80B,232C ''iam'':188C ''id'':154C,155C,157C ''ident'':132C,213C ''import'':59B,121C ''incid'':243C ''inject'':178C ''input'':176C ''interact'':38B ''json'':222C ''key'':223C ''lakehous'':41B ''larg'':26B ''latenc'':87B,102B ''level'':187C,199C ''like'':181C ''live'':218C ''local'':139C ''long'':217C ''long-liv'':216C ''looker'':115C ''low'':86B,101B ''low-lat'':85B,100B ''manag'':11B ''massiv'':55B ''matter'':82B ''maximum'':226C ''maximum-bytes-bil'':225C ''monitor'':119C ''my-project.my_dataset.users'':152C ''name'':150C ''narrowli'':189C ''never'':161C ''new'':142C ''oltp'':98B ''oper'':108B ''param'':156C ''parameter'':160C,168C ''path'':234C ''pattern'':42B ''platform'':19B ''polici'':201C ''queri'':56B,148C,169C,233C,238C ''rather'':69B,202C ''report'':36B ''request'':103B ''role'':206C ''row'':145C,198C ''row-level'':197C ''scale'':57B ''select'':149C ''semi'':30B ''semi-structur'':29B ''separ'':49B ''serverless'':13B ''servic'':137C,220C ''service-account'':219C ''set'':224C ''sql'':22B,64B,76B,165C,173C ''sql-base'':21B ''storag'':51B,114C ''store'':104B ''string'':163C,171C ''string-build'':170C ''string-built'':162C ''structur'':27B,31B ''subset'':192C ''traffic'':110B ''transact'':71B ''use'':33B,94B,167C ''user'':175C ''userid'':158C ''vertex'':116C ''view'':195C ''wareh'':77B ''warehous'':16B ''wide'':89B ''wide-col