INSERT INTO public.technology_catalog VALUES ('gcp-cloud-storage', 'Google Cloud Storage', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/gcp-cloud-storage-for-archive.png', '#6b7280', '["object-storage"]', '{"purpose": "Unified object storage for live and archived data. Supports multiple storage classes (Standard, Nearline, Coldline, Archive) for cost optimization based on access patterns.", "configMode": "declarative", "provenance": {"notes": "Schemas held to the stable API surface (release channels, machine families, storage types, database modes, processing units); live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Google Cloud SDK", "gsutil", "Client Libraries", "signed URLs"], "antiPatterns": ["Using Standard class for infrequently accessed data", "Making buckets publicly accessible without CDN", "Not setting retention policies for compliance data", "Using ACLs instead of IAM for access control"], "apiReference": {"docsUrl": "https://cloud.google.com/storage/docs"}, "bestPractices": ["Use lifecycle policies to transition objects between storage classes", "Use signed URLs for temporary access", "Enable uniform bucket-level access for simpler IAM", "Use Cloud CDN for frequently accessed public content"], "setupInstructions": [{"url": "https://console.cloud.google.com/storage/create-bucket", "type": "dashboard_config", "title": "Create Storage Bucket", "required": true, "instructions": "In GCP Console > Cloud Storage > Create Bucket. Choose a globally unique name, location type (region, dual-region, or multi-region), and default storage class."}, {"type": "permissions", "title": "Configure IAM Bindings", "required": true, "instructions": "Grant your service account the appropriate role: Storage Object Viewer (read), Storage Object Creator (write), or Storage Object Admin (full). Use bucket-level IAM for least privilege."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export GOOGLE_CLOUD_PROJECT=my-project-id", "export GCS_BUCKET_NAME=my-bucket-name", "export GOOGLE_APPLICATION_CREDENTIALS=/path/to/service-account-key.json"], "required": true, "instructions": "Add GCP project and bucket details to your application environment."}]}', '[{"kind": "config", "path": "storage/archive-lifecycle.json", "priority": "essential", "description": "Lifecycle policies and retention settings for archival Cloud Storage buckets"}, {"kind": "config", "path": "storage/archive-objects-manifest.json", "priority": "recommended", "description": "Object catalog and metadata manifest for archived content discovery"}, {"kind": "config", "path": "infra/cloud-storage-archive.yaml", "priority": "recommended", "description": "Infrastructure-as-code definition for archive-class buckets, policies, and access controls"}]', '{"bucketLock": {"type": "boolean", "label": "Bucket Lock", "default": false, "description": "Apply retention lock to protect archived objects from deletion or modification"}, "storageClass": {"type": "string", "label": "Storage Class", "default": "archive", "options": ["archive", "coldline", "nearline", "standard"], "description": "Primary Cloud Storage class for archived objects"}, "lifecycleManaged": {"type": "boolean", "label": "Lifecycle Managed", "default": true, "description": "Use lifecycle rules to control archival transitions and retention behavior"}}', '["database", "logging", "monitoring", "backend-service", "worker"]', false, NULL, NULL, '2026-05-18 02:38:14.715381+00', '2026-08-30 12:07:23.877005+00', 'Google Cloud Storage', NULL, '''access'':28B ''archiv'':13B,22B ''base'':26B ''class'':18B ''client'':34C ''cloud'':2A,5A,31C ''coldlin'':21B ''cost'':24B ''data'':14B ''gcp'':4A ''googl'':1A,30C ''gsutil'':33C ''librari'':35C ''live'':11B ''multipl'':16B ''nearlin'':20B ''object'':8B ''optim'':25B ''pattern'':29B ''sdk'':32C ''sign'':36C ''standard'':19B ''storag'':3A,6A,9B,17B ''support'':15B ''unifi'':7B ''url'':37C');
INSERT INTO public.technology_catalog VALUES ('html-css', 'HTML/CSS/JS', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/html-css.png', '#e34c26', '["frontend-app"]', '{"purpose": "Basic static website with no framework dependencies", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["HTML5", "CSS3", "Vanilla JavaScript", "ES6+"], "antiPatterns": ["Using innerHTML with unsanitized user input creating XSS vulnerabilities", "Inline event handlers (onclick) instead of addEventListener", "Loading render-blocking scripts in the head without defer/async", "Using !important extensively instead of managing CSS specificity", "Not using semantic HTML elements affecting accessibility"], "apiReference": {"docsUrl": "https://developer.mozilla.org/en-US/docs/Web"}, "bestPractices": ["Use semantic HTML elements", "Follow CSS naming conventions (BEM)", "Implement responsive design with CSS Grid/Flexbox", "Add meta tags for SEO", "Optimize images and assets", "Use local storage for state if needed"], "sdkInitPattern": "<!DOCTYPE html>\\n<html lang=\"en\">\\n<head>\\n  <meta charset=\"UTF-8\">\\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\\n  <title>My App</title>\\n  <link rel=\"stylesheet\" href=\"styles.css\">\\n</head>\\n<body>\\n  <div id=\"app\"></div>\\n  <script type=\"module\" src=\"main.js\"></script>\\n</body>\\n</html>", "securityGuidance": "Sanitize all user-generated content before DOM insertion to prevent XSS. Use textContent instead of innerHTML for dynamic text. Set Content Security Policy headers to restrict script sources. Use SameSite cookie attributes and CSRF tokens for forms. Validate and sanitize URL parameters before use. Use Subresource Integrity (SRI) for external scripts and stylesheets.", "commonApiPatterns": [{"name": "Fetch API Call", "description": "Fetch API with auth header and error handling", "codeTemplate": "async function fetchUsers() {\\n  const res = await fetch(\"/api/users\", {\\n    headers: { \"Authorization\": `Bearer ${token}` }\\n  });\\n  if (!res.ok) throw new Error(`HTTP ${res.status}`);\\n  return res.json();\\n}"}, {"name": "Responsive Layout", "description": "CSS Grid responsive layout with auto-fit and media query fallback", "codeTemplate": ".container {\\n  display: grid;\\n  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\\n  gap: 1.5rem;\\n  padding: 1rem;\\n}\\n@media (max-width: 768px) {\\n  .container { grid-template-columns: 1fr; }\\n}"}, {"name": "Custom Element", "description": "Web Component with Shadow DOM encapsulation", "codeTemplate": "class MyComponent extends HTMLElement {\\n  connectedCallback() {\\n    this.attachShadow({ mode: \"open\" });\\n    this.shadowRoot.innerHTML = `<style>:host { display: block; }</style><slot></slot>`;\\n  }\\n}\\ncustomElements.define(\"my-component\", MyComponent);"}], "integrationPatterns": ["Vite for build tooling with HMR and optimized production builds", "Fetch API for HTTP communication with REST backends", "Web Components for framework-agnostic reusable UI components", "Service Workers for offline support and caching strategies", "CSS custom properties for theming and design tokens"], "configurationTemplate": "// vite.config.js (for vanilla HTML/CSS/JS)\\nimport { defineConfig } from \"vite\";\\nexport default defineConfig({\\n  root: \"src\",\\n  build: {\\n    outDir: \"../dist\",\\n    emptyOutDir: true,\\n    rollupOptions: {\\n      input: { main: \"src/index.html\" }\\n    }\\n  }\\n});"}', '[{"kind": "source", "path": "index.html", "language": "html", "description": "Main HTML entry point"}, {"kind": "source", "path": "styles/main.css", "language": "css", "description": "Main stylesheet"}, {"kind": "source", "path": "scripts/app.js", "language": "javascript", "description": "Main JavaScript"}]', '{"bundling": {"type": "enum", "label": "Bundling", "default": "none-plain-files", "options": ["none-plain-files", "vite"]}, "jsPosture": {"type": "enum", "label": "JavaScript posture", "default": "progressive-enhancement", "options": ["progressive-enhancement", "vanilla-spa", "minimal-none"]}, "cssApproach": {"type": "enum", "label": "CSS approach", "default": "vanilla-css", "options": ["vanilla-css", "tailwind", "sass", "bootstrap"]}}', '["rest-api", "cdn"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-30 12:07:23.877005+00', 'HTML/CSS', '#C94020', '''app'':22C ''attribut'':62C ''basic'':4B ''content'':35C,51C ''cooki'':61C ''csrf'':64C ''css'':3A ''css3'':12C ''depend'':10B ''dom'':37C ''dynam'':48C ''es6'':15C ''extern'':80C ''form'':67C ''framework'':9B ''generat'':34C ''header'':54C ''html'':2A ''html/css/js'':1A ''html5'':11C ''innerhtml'':46C ''insert'':38C ''instead'':44C ''integr'':77C ''javascript'':14C ''n'':16C,17C,18C,19C,20C,23C,24C,25C,26C,27C,28C,29C ''paramet'':72C ''polici'':53C ''prevent'':40C ''restrict'':56C ''samesit'':60C ''sanit'':30C,70C ''script'':57C,81C ''secur'':52C ''set'':50C ''sourc'':58C ''sri'':78C ''static'':5B ''stylesheet'':83C ''subresourc'':76C ''text'':49C ''textcont'':43C ''token'':65C ''url'':71C ''use'':42C,59C,74C,75C ''user'':33C ''user-gener'':32C ''valid'':68C ''vanilla'':13C ''websit'':6B ''xss'':41C');
INSERT INTO public.technology_catalog VALUES ('jenkins', 'Jenkins', NULL, '#6b7280', '["ci-cd-pipeline"]', '{"purpose": "Self-hosted automation server for building, testing, and deploying software. Highly extensible via plugins. Supports both declarative and scripted pipeline syntax.", "configMode": "definition-as-code", "provenance": {"notes": "Phase B8c additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Groovy", "Docker", "Jenkinsfile", "Java"], "antiPatterns": ["Configuring jobs through the UI instead of code", "Running builds on the controller node", "Installing too many plugins without maintenance plan", "Hardcoding credentials in Jenkinsfile"], "apiReference": {"docsUrl": "https://www.jenkins.io/doc/"}, "bestPractices": ["Use declarative pipeline syntax in Jenkinsfile", "Store pipeline as code in the repository", "Use credentials plugin for secret management", "Run builds in Docker agents for isolation", "Configure shared libraries for reusable pipeline code"], "freshnessNote": "Self-hosted CI with a huge plugin surface — the maintenance cost IS the product decision. For NEW pipelines, GitHub Actions/GitLab CI are the defaults; Jenkins earns its place where it already runs or where on-prem/plugin requirements force it.", "securityGuidance": "Keep Jenkins itself patched and plugins minimal — the plugin ecosystem is the historical breach vector, and the script console is remote code execution by design: admin access is production access. Secrets live in the Credentials store consumed via withCredentials (never echoed), builds of untrusted PRs run on isolated agents without credential access, controller executors set to zero so builds never run on the controller, and matrix-based authorization scopes who can configure jobs — job config edits are arbitrary code on your agents.", "setupInstructions": [{"url": "https://www.jenkins.io/doc/book/installing/docker/", "type": "toolchain_install", "title": "Install Jenkins", "commands": ["docker run -d --name jenkins -p 8080:8080 -p 50000:50000 -v jenkins_home:/var/jenkins_home jenkins/jenkins:lts"], "required": true, "instructions": "Install Jenkins via Docker (recommended) or system package. The Docker approach provides isolation and easy upgrades."}, {"type": "dashboard_config", "title": "Complete Initial Setup", "commands": ["docker exec jenkins cat /var/jenkins_home/secrets/initialAdminPassword"], "required": true, "instructions": "Open http://localhost:8080, retrieve the initial admin password from the container logs or /var/jenkins_home/secrets/initialAdminPassword. Install suggested plugins and create the first admin user."}, {"type": "dashboard_config", "title": "Install Required Plugins", "required": true, "instructions": "In Manage Jenkins > Plugins, install: Git, Docker Pipeline, Pipeline, Credentials Binding, and Blue Ocean (optional UI). Restart Jenkins after installation."}, {"type": "permissions", "title": "Configure Credentials", "required": true, "instructions": "In Manage Jenkins > Credentials, add credentials for Git repositories (SSH key or token), Docker registries, and deployment targets. Reference them in Jenkinsfile using credentials() binding."}], "configurationTemplate": "// Jenkinsfile\npipeline {\n  agent { label ''linux'' }\n  stages {\n    stage(''Test'') { steps { sh ''npm ci && npm test'' } }\n    stage(''Deploy'') {\n      when { branch ''main'' }\n      steps {\n        withCredentials([string(credentialsId: ''deploy-token'', variable: ''TOKEN'')]) {\n          sh ''./deploy.sh''\n        }\n      }\n    }\n  }\n}"}', '[{"kind": "config", "path": "Jenkinsfile", "language": "groovy", "description": "Declarative pipeline; secrets via withCredentials only"}]', '{"agents": {"type": "enum", "label": "Agents", "default": "kubernetes-dynamic", "options": ["kubernetes-dynamic", "static-nodes"]}, "pipelineStyle": {"type": "enum", "label": "Pipeline style", "default": "declarative-jenkinsfile", "options": ["declarative-jenkinsfile", "scripted-legacy"]}}', '[]', false, NULL, NULL, '2026-05-18 02:39:19.313183+00', '2026-08-30 12:07:23.877005+00', 'Jenkins', NULL, '''access'':55C,58C,80C ''admin'':54C ''agent'':77C,111C ''arbitrari'':107C ''author'':97C ''autom'':6B ''base'':96C ''breach'':42C ''build'':9B,70C,87C ''code'':50C,108C ''config'':104C ''configur'':101C ''consol'':47C ''consum'':65C ''control'':81C,92C ''credenti'':63C,79C ''declar'':20B ''deploy'':12B ''design'':53C ''docker'':26C ''echo'':69C ''ecosystem'':38C ''edit'':105C ''execut'':51C ''executor'':82C ''extens'':15B ''groovi'':25C ''high'':14B ''histor'':41C ''host'':5B ''isol'':76C ''java'':28C ''jenkin'':1A,2A,30C ''jenkinsfil'':27C ''job'':102C,103C ''keep'':29C ''live'':60C ''matrix'':95C ''matrix-bas'':94C ''minim'':35C ''never'':68C,88C ''patch'':32C ''pipelin'':23B ''plugin'':17B,34C,37C ''product'':57C ''prs'':73C ''remot'':49C ''run'':74C,89C ''scope'':98C ''script'':22B,46C ''secret'':59C ''self'':4B ''self-host'':3B ''server'':7B ''set'':83C ''softwar'':13B ''store'':64C ''support'':18B ''syntax'':24B ''test'':10B ''untrust'':72C ''vector'':43C ''via'':16B,66C ''withcredenti'':67C ''without'':78C ''zero'':85C');
INSERT INTO public.technology_catalog VALUES ('keycloak', 'Keycloak', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/keycloak.png', '#4d4d4d', '["auth-provider"]', '{"purpose": "Open-source identity and access management solution providing SSO, LDAP/AD federation, OIDC/SAML/OAuth 2.0 support, custom themes, user federation, and fine-grained authorization with self-hosted or cloud deployment", "configMode": "declarative", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Keycloak", "keycloak-js", "keycloak-connect", "OpenID Connect", "SAML 2.0", "LDAP", "Keycloak Admin REST API", "Docker", "Helm", "Quarkus"], "antiPatterns": ["Running Keycloak without HTTPS in production", "Not configuring proper session limits", "Using SAML when OIDC is available and simpler", "Not implementing proper backup strategy for the database", "Exposing admin console publicly without IP restrictions", "Not testing realm exports before promoting to production", "Using embedded H2 database in production (use PostgreSQL)"], "apiReference": {"docsUrl": "https://www.keycloak.org/documentation"}, "bestPractices": ["Use realms for tenant isolation in multi-tenant applications", "Implement OIDC for modern applications (preferred over SAML)", "Configure proper session timeouts and token lifetimes", "Use client scopes to control token claims", "Implement custom themes for brand-consistent login experience", "Export realm configuration as JSON for version control and environment promotion", "Use Docker Compose for local development, Helm for Kubernetes production", "Configure user federation (LDAP/AD) for enterprise deployments", "Use Keycloak Admin REST API for automated user management", "Enable brute-force detection and account lockout policies"], "securityGuidance": "Never run start-dev in production — production mode enforces HTTPS and a real hostname. The bootstrap admin is a break-glass identity: create named admins and disable it. Realm config is your access policy — version realm-export.json and review changes like code (a rogue client or relaxed redirect URI is an account-takeover primitive): exact redirect URIs (no wildcards), confidential clients with rotated secrets or JWT auth, PKCE required for public clients, and brute-force protection plus MFA policies on from the start. The token issuer''s database holds credential hashes — lock it like the identity system it is.", "setupInstructions": [{"url": "https://www.keycloak.org/getting-started", "type": "manual_workflow", "title": "Deploy Keycloak Server", "commands": ["docker run -p 8080:8080 -e KEYCLOAK_ADMIN=admin -e KEYCLOAK_ADMIN_PASSWORD=admin quay.io/keycloak/keycloak:latest start-dev"], "required": true, "instructions": "Deploy Keycloak on your infrastructure (Docker, Kubernetes, or bare metal). Requires Java 17+ runtime."}, {"type": "dashboard_config", "title": "Create Realm and Client", "required": true, "instructions": "Create a new realm in the Keycloak admin console, then create a client with the appropriate access type (public or confidential) and valid redirect URIs."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export KEYCLOAK_URL=https://your-keycloak-host/auth", "export KEYCLOAK_REALM=your-realm", "export KEYCLOAK_CLIENT_ID=your-client-id"], "required": true, "instructions": "Configure Keycloak connection details in your application environment."}, {"type": "dashboard_config", "title": "Configure Roles and Permissions", "required": false, "instructions": "Define realm roles and client roles in the Keycloak admin console. Assign roles to users or groups as needed for your authorization model."}], "configurationTemplate": "# start with a versioned realm import\nkc.sh start --hostname=https://auth.example.com --https-certificate-file=/certs/tls.crt \\\n  --https-certificate-key-file=/certs/tls.key\n# realm-export.json (versioned in git) is imported at boot:\nkc.sh import --file /opt/keycloak/data/import/realm-export.json"}', '[{"kind": "config", "path": "keycloak/realm-export.json", "language": "json", "priority": "essential", "description": "Keycloak realm configuration export for environment promotion"}, {"kind": "config", "path": "keycloak/docker-compose.yml", "language": "yaml", "priority": "essential", "description": "Docker Compose for local Keycloak development"}, {"kind": "config", "path": "keycloak/themes/custom/login/theme.properties", "language": "properties", "priority": "recommended", "description": "Custom login theme properties"}, {"kind": "doc", "path": "keycloak/themes/custom/login/login.ftl", "language": "html", "priority": "recommended", "description": "Custom login page FreeMarker template"}, {"kind": "config", "path": "src/auth/keycloak-config.ts", "language": "typescript", "priority": "essential", "description": "Keycloak JS adapter configuration"}, {"kind": "source", "path": "src/auth/keycloak-provider.tsx", "language": "typescript", "priority": "essential", "description": "React provider wrapping Keycloak initialization"}, {"kind": "source", "path": "src/middleware/keycloak-verify.ts", "language": "typescript", "priority": "essential", "description": "Backend middleware to validate Keycloak tokens"}, {"kind": "config", "path": "infra/keycloak/helm-values.yaml", "language": "yaml", "priority": "recommended", "description": "Helm chart values for Keycloak Kubernetes deployment"}]', '{"mfa": {"type": "boolean", "label": "MFA Enabled", "default": false, "description": "Require multi-factor authentication"}, "clientId": {"type": "string", "label": "Client ID", "description": "Keycloak client identifier"}, "realmName": {"type": "string", "label": "Realm Name", "description": "Keycloak realm name for tenant isolation"}, "serverUrl": {"type": "string", "label": "Server URL", "description": "Keycloak server base URL"}, "selfHosted": {"type": "boolean", "label": "Self-Hosted", "default": true, "description": "Self-hosted Keycloak deployment"}, "ldapIntegration": {"type": "boolean", "label": "LDAP Integration", "default": false, "description": "Integrate with LDAP or Active Directory"}}', '["backend-service", "frontend-app", "api-gateway", "rest-api", "database"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#3D3D3D', '''2.0'':16B,44C ''access'':8B,87C ''account'':106C ''account-takeov'':105C ''admin'':47C,70C,79C ''api'':49C ''auth'':121C ''author'':26B ''bootstrap'':69C ''break'':74C ''break-glass'':73C ''brute'':129C ''brute-forc'':128C ''chang'':93C ''client'':98C,115C,126C ''cloud'':32B ''code'':95C ''confidenti'':114C ''config'':84C ''connect'':40C,42C ''creat'':77C ''credenti'':145C ''custom'':18B ''databas'':143C ''deploy'':33B ''dev'':57C ''disabl'':81C ''docker'':50C ''enforc'':62C ''exact'':109C ''feder'':14B,21B ''fine'':24B ''fine-grain'':23B ''forc'':130C ''glass'':75C ''grain'':25B ''hash'':146C ''helm'':51C ''hold'':144C ''host'':30B ''hostnam'':67C ''https'':63C ''ident'':6B,76C,151C ''issuer'':141C ''js'':37C ''jwt'':120C ''keycloak'':1A,2A,34C,36C,39C,46C ''keycloak-connect'':38C ''keycloak-j'':35C ''ldap'':45C ''ldap/ad'':13B ''like'':94C,149C ''lock'':147C ''manag'':9B ''mfa'':133C ''mode'':61C ''name'':78C ''never'':53C ''oidc/saml/oauth'':15B ''open'':4B ''open-sourc'':3B ''openid'':41C ''pkce'':122C ''plus'':132C ''polici'':88C,134C ''primit'':108C ''product'':59C,60C ''protect'':131C ''provid'':11B ''public'':125C ''quarkus'':52C ''real'':66C ''realm'':83C ''realm-export.json'':90C ''redirect'':101C,110C ''relax'':100C ''requir'':123C ''rest'':48C ''review'':92C ''rogu'':97C ''rotat'':117C ''run'':54C ''saml'':43C ''secret'':118C ''self'':29B ''self-host'':28B ''solut'':10B ''sourc'':5B ''sso'':12B ''start'':56C,138C ''start-dev'':55C ''support'':17B ''system'':152C ''takeov'':107C ''theme'':19B ''token'':140C ''uri'':102C,111C ''user'':20B ''version'':89C ''wildcard'':113C');
INSERT INTO public.technology_catalog VALUES ('kubernetes', 'Kubernetes', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/kubernetes.png', '#326ce5', '["k8s-cluster", "k8s-namespace"]', '{"purpose": "Container orchestration platform for automating deployment, scaling, and management of containerized applications", "configMode": "definition-as-code", "provenance": {"notes": "docsUrl is the vendor''s canonical documentation root, stamped from model knowledge and checked by scripts/n10-verify-docs-urls.ts; pre-existing body content not yet live-docs verified — upgrade at this row''s enrichment chunk.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Kubernetes", "kubectl", "Helm", "Kustomize", "ArgoCD", "Prometheus"], "antiPatterns": ["Running pods without resource requests and limits", "Using latest tag for container images in production", "Not configuring liveness and readiness probes", "Running all workloads in the default namespace without RBAC separation", "Storing secrets in ConfigMaps or plain YAML files in git"], "apiReference": {"docsUrl": "https://kubernetes.io/docs/"}, "bestPractices": ["Use namespaces for environment isolation", "Implement resource requests and limits", "Use Helm charts for packaging", "Implement proper RBAC", "Use horizontal pod autoscaling", "Implement proper liveness and readiness probes", "Use ConfigMaps and Secrets for configuration", "Implement proper network policies"], "sdkInitPattern": "kubectl cluster-info && kubectl create namespace my-app\\n# Apply manifests\\nkubectl apply -k overlays/production/", "securityGuidance": "Use NetworkPolicies to restrict pod-to-pod communication. Run containers as non-root with readOnlyRootFilesystem. Use RBAC with least-privilege service accounts per workload. Store secrets in external secret managers (Vault, AWS Secrets Manager) with External Secrets Operator. Enable Pod Security Standards (restricted) at namespace level. Scan images in CI and enforce admission policies with OPA/Gatekeeper or Kyverno.", "commonApiPatterns": [{"name": "Deployment + Service", "description": "Deployment with resource limits, probes, and ClusterIP Service", "codeTemplate": "apiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  name: my-app\\nspec:\\n  replicas: 3\\n  selector:\\n    matchLabels: { app: my-app }\\n  template:\\n    metadata:\\n      labels: { app: my-app }\\n    spec:\\n      containers:\\n      - name: app\\n        image: registry/my-app:v1.0.0\\n        ports: [{ containerPort: 3000 }]\\n        resources:\\n          requests: { cpu: 100m, memory: 128Mi }\\n          limits: { cpu: 500m, memory: 512Mi }\\n        livenessProbe:\\n          httpGet: { path: /health, port: 3000 }\\n        readinessProbe:\\n          httpGet: { path: /ready, port: 3000 }\\n---\\napiVersion: v1\\nkind: Service\\nmetadata:\\n  name: my-app\\nspec:\\n  selector: { app: my-app }\\n  ports: [{ port: 80, targetPort: 3000 }]"}, {"name": "HPA Autoscaling", "description": "Horizontal Pod Autoscaler based on CPU utilization", "codeTemplate": "apiVersion: autoscaling/v2\\nkind: HorizontalPodAutoscaler\\nmetadata:\\n  name: my-app\\nspec:\\n  scaleTargetRef:\\n    apiVersion: apps/v1\\n    kind: Deployment\\n    name: my-app\\n  minReplicas: 2\\n  maxReplicas: 20\\n  metrics:\\n  - type: Resource\\n    resource:\\n      name: cpu\\n      target: { type: Utilization, averageUtilization: 70 }"}, {"name": "Ingress", "description": "Ingress with TLS termination via cert-manager", "codeTemplate": "apiVersion: networking.k8s.io/v1\\nkind: Ingress\\nmetadata:\\n  name: my-app\\n  annotations:\\n    cert-manager.io/cluster-issuer: letsencrypt-prod\\nspec:\\n  tls: [{ hosts: [app.example.com], secretName: app-tls }]\\n  rules:\\n  - host: app.example.com\\n    http:\\n      paths:\\n      - path: /\\n        pathType: Prefix\\n        backend:\\n          service: { name: my-app, port: { number: 80 } }"}], "setupInstructions": [{"url": "https://kubernetes.io/docs/tasks/tools/", "type": "toolchain_install", "title": "Install kubectl", "commands": ["curl -LO https://dl.k8s.io/release/$(curl -L -s https://dl.k8s.io/release/stable.txt)/bin/linux/amd64/kubectl", "chmod +x kubectl && sudo mv kubectl /usr/local/bin/"], "required": true, "instructions": "Install the Kubernetes CLI tool for cluster management."}, {"type": "environment_variable", "title": "Configure Cluster Access", "commands": ["aws eks update-kubeconfig --name your-cluster --region us-east-1", "gcloud container clusters get-credentials your-cluster --zone us-central1-a"], "required": true, "instructions": "Set up kubeconfig to access your cluster. For managed services, use the provider CLI to generate credentials."}, {"type": "dashboard_config", "title": "Create Namespace", "commands": ["kubectl create namespace your-app"], "required": false, "instructions": "Create a dedicated namespace for your application to isolate resources."}], "integrationPatterns": ["Helm or Kustomize for templating and environment-specific configuration", "cert-manager for automated TLS certificate management", "Prometheus + Grafana for cluster and workload monitoring", "ArgoCD or Flux for GitOps-based continuous deployment", "External Secrets Operator for syncing secrets from external vaults"], "configurationTemplate": "# kustomization.yaml\\napiVersion: kustomize.config.k8s.io/v1beta1\\nkind: Kustomization\\nnamespace: my-app\\nresources:\\n  - deployment.yaml\\n  - service.yaml\\n  - ingress.yaml\\nconfigMapGenerator:\\n  - name: app-config\\n    envs: [.env]\\nimages:\\n  - name: registry/my-app\\n    newTag: v1.0.0"}', '[{"kind": "config", "path": "k8s/deployment.yaml", "language": "yaml", "description": "Kubernetes deployment manifest"}, {"kind": "config", "path": "k8s/service.yaml", "language": "yaml", "description": "Kubernetes service manifest"}]', '{"gitops": {"type": "enum", "label": "GitOps delivery", "default": "argocd", "options": ["argocd", "flux", "ci-applies-directly"], "description": "Cluster state pulled from git vs pushed by CI — an architecture stance, not tooling trivia"}, "packaging": {"type": "enum", "label": "Manifest packaging", "default": "helm", "options": ["helm", "kustomize", "plain-manifests"]}, "distribution": {"type": "enum", "label": "Distribution", "default": "managed-cloud", "options": ["managed-cloud", "k3s-lightweight", "self-managed-kubeadm"], "description": "Managed control planes (EKS/GKE/AKS) unless there is a reason; k3s for edge/small; kubeadm only with real platform-team capacity"}}', '["backend-service", "database", "cache", "monitoring"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-30 12:07:23.877005+00', NULL, '#2857B6', '''account'':62C ''admiss'':93C ''app'':30C ''appli'':32C,35C ''applic'':14B ''argocd'':19C ''autom'':7B ''aw'':72C ''ci'':90C ''cluster'':23C ''cluster-info'':22C ''communic'':46C ''contain'':3B,48C ''container'':13B ''creat'':26C ''deploy'':8B ''enabl'':79C ''enforc'':92C ''extern'':68C,76C ''helm'':17C ''imag'':88C ''info'':24C ''k'':36C ''kubectl'':16C,21C,25C ''kubernet'':1A,2A,15C ''kustom'':18C ''kyverno'':98C ''least'':59C ''least-privileg'':58C ''level'':86C ''manag'':11B,70C,74C ''manifest'':33C ''my-app'':28C ''n'':31C ''namespac'':27C,85C ''networkpolici'':39C ''nkubectl'':34C ''non'':51C ''non-root'':50C ''opa/gatekeeper'':96C ''oper'':78C ''orchestr'':4B ''overlays/production'':37C ''per'':63C ''platform'':5B ''pod'':43C,45C,80C ''pod-to-pod'':42C ''polici'':94C ''privileg'':60C ''prometheus'':20C ''rbac'':56C ''readonlyrootfilesystem'':54C ''restrict'':41C,83C ''root'':52C ''run'':47C ''scale'':9B ''scan'':87C ''secret'':66C,69C,73C,77C ''secur'':81C ''servic'':61C ''standard'':82C ''store'':65C ''use'':38C,55C ''vault'':71C ''workload'':64C');
INSERT INTO public.technology_catalog VALUES ('langgraph', 'LangGraph', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/langchain.png', '#1D3C3E', '["inference-service", "ai-agent-service"]', '{"purpose": "LangGraph is a low-level framework for building stateful, multi-step LLM applications and agents as explicit graphs with nodes, edges, shared state, checkpoints, and human-in-the-loop control. Use it when you need durable execution, branching workflows, retries, resumability, memory, and explicit orchestration across tools and models rather than a simple prompt-in and response-out chain. Choose LangGraph over plain LangChain chains when agent state, control flow, and long-running orchestration are first-class concerns, and over bespoke workflow code when you want a graph-native runtime for agent systems. Do not use it when the problem is a single synchronous model call, a thin wrapper around one API, or a static pipeline with minimal branching where simpler code is easier to maintain.", "configMode": "code", "provenance": {"notes": "Phase B8c additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["LangChain", "LangSmith", "OpenAI", "Anthropic", "LiteLLM", "PostgreSQL", "Redis", "FastAPI"], "antiPatterns": ["Using LangGraph for a single prompt-response interaction that does not need persistent state or graph control flow", "Putting all planning, tool selection, memory management, and side effects into one giant node", "Skipping checkpointing and then treating long-running agents as if they were stateless request handlers", "Allowing unbounded recursive loops or tool retries without explicit stop conditions and guardrails", "Mixing business-critical side effects directly into exploratory reasoning nodes without approval or validation boundaries", "Treating LangGraph as a replacement for model providers, vector stores, or API gateways instead of an orchestration layer"], "apiReference": {"docsUrl": "https://langchain-ai.github.io/langgraph/"}, "bestPractices": ["Model agent workflows as explicit state transitions with well-defined node responsibilities instead of opaque monolithic agent loops", "Use durable checkpointing and thread or run identifiers so long-running workflows can resume safely after failure or interruption", "Keep tool invocation, memory updates, and model calls separate within graph nodes so debugging and testing remain tractable", "Define typed state schemas and validation boundaries so node inputs and outputs stay predictable as the graph grows", "Instrument graph execution with tracing and structured observability to understand branching, retries, and failure hotspots", "Use human-in-the-loop interrupts and approval gates for sensitive actions such as external writes, billing changes, or autonomous tool use", "Start with a narrow workflow graph and add branching and subgraphs incrementally instead of overdesigning a large agent topology up front"], "sdkInitPattern": "import { StateGraph, MessagesAnnotation, START, END } from ''@langchain/langgraph'';\n\nconst graph = new StateGraph(MessagesAnnotation)\n  .addNode(''agent'', callModel)\n  .addNode(''tools'', toolNode)\n  .addEdge(START, ''agent'')\n  .addConditionalEdges(''agent'', shouldContinue, [''tools'', END])\n  .addEdge(''tools'', ''agent'')\n  .compile({ checkpointer });", "securityGuidance": "Checkpointed state persists every message and tool result — the checkpointer''s store (Postgres/Redis) holds conversation data at rest, so lock it like a database and key threads by authenticated user, never client-chosen thread ids (thread access IS conversation access). Bound graphs with recursion limits so a looping agent cannot burn unbounded tokens, gate state-mutating tool nodes behind interrupts (human approval) where the blast radius warrants it, and validate tool arguments as untrusted model output at every node boundary."}', '[{"kind": "source", "path": "src/agents/support-graph.ts", "priority": "essential", "description": "Primary LangGraph workflow definition with nodes, edges, state transitions, and routing logic"}, {"kind": "schema", "path": "src/agents/state-schema.ts", "priority": "essential", "description": "Typed shared state schema and validation rules used across the LangGraph workflow"}, {"kind": "config", "path": "src/agents/checkpointer.ts", "priority": "recommended", "description": "Checkpointing and persistence configuration for resumable LangGraph execution"}, {"kind": "doc", "path": "docs/agent-workflow.md", "priority": "recommended", "description": "Design notes describing graph nodes, branching logic, memory strategy, and human-in-the-loop controls"}]', '{"checkpointing": {"type": "boolean", "label": "Checkpointing", "default": true, "description": "Persist workflow state to support resumability, replay, and human review"}, "executionModel": {"type": "string", "label": "Execution Model", "default": "stateful-graph", "options": ["stateful-graph", "react-agent", "supervisor", "subgraph-composition"], "description": "Primary orchestration style used by LangGraph workflows"}, "humanInTheLoop": {"type": "boolean", "label": "Human In The Loop", "default": false, "description": "Pause graph execution for approval or intervention at controlled boundaries"}}', '["llm-gateway", "backend-service", "vector-database", "monitoring", "ai-service"]', false, NULL, NULL, '2026-03-16 01:16:17.70804+00', '2026-08-30 12:07:23.877005+00', NULL, '#173033', '''access'':213C,216C ''across'':51B ''addconditionaledg'':166C ''addedg'':163C,171C ''addnod'':157C,160C ''agent'':19B,74B,102B,158C,165C,167C,173C,225C ''anthrop'':140C ''api'':122B ''applic'':17B ''approv'':239C ''argument'':249C ''around'':120B ''authent'':204C ''behind'':236C ''bespok'':90B ''blast'':242C ''bound'':217C ''boundari'':257C ''branch'':43B,129B ''build'':11B ''burn'':227C ''call'':116B ''callmodel'':159C ''cannot'':226C ''chain'':66B,72B ''checkpoint'':28B,175C,176C,185C ''choos'':67B ''chosen'':209C ''class'':86B ''client'':208C ''client-chosen'':207C ''code'':92B,132B ''compil'':174C ''concern'':87B ''const'':152C ''control'':35B,76B ''convers'':190C,215C ''data'':191C ''databas'':199C ''durabl'':41B ''easier'':134B ''edg'':25B ''end'':149C,170C ''everi'':179C,255C ''execut'':42B ''explicit'':21B,49B ''fastapi'':144C ''first'':85B ''first-class'':84B ''flow'':77B ''framework'':9B ''gate'':230C ''graph'':22B,98B,153C,218C ''graph-nat'':97B ''hold'':189C ''human'':31B,238C ''human-in-the-loop'':30B ''id'':211C ''import'':145C ''interrupt'':237C ''key'':201C ''langchain'':71B,137C ''langchain/langgraph'':151C ''langgraph'':1A,2A,3B,68B ''langsmith'':138C ''level'':8B ''like'':197C ''limit'':221C ''litellm'':141C ''llm'':16B ''lock'':195C ''long'':80B ''long-run'':79B ''loop'':34B,224C ''low'':7B ''low-level'':6B ''maintain'':136B ''memori'':47B ''messag'':180C ''messagesannot'':147C,156C ''minim'':128B ''model'':54B,115B,252C ''multi'':14B ''multi-step'':13B ''mutat'':233C ''nativ'':99B ''need'':40B ''never'':206C ''new'':154C ''node'':24B,235C,256C ''one'':121B ''openai'':139C ''orchestr'':50B,82B ''output'':253C ''persist'':178C ''pipelin'':126B ''plain'':70B ''postgres/redis'':188C ''postgresql'':142C ''problem'':110B ''prompt'':60B ''prompt-in'':59B ''radius'':243C ''rather'':55B ''recurs'':220C ''redi'':143C ''respons'':64B ''response-out'':63B ''rest'':193C ''result'':183C ''resum'':46B ''retri'':45B ''run'':81B ''runtim'':100B ''share'':26B ''shouldcontinu'':168C ''simpl'':58B ''simpler'':131B ''singl'':113B ''start'':148C,164C ''state'':12B,27B,75B,177C,232C ''state-mut'':231C ''stategraph'':146C,155C ''static'':125B ''step'':15B ''store'':187C ''synchron'':114B ''system'':103B ''thin'':118B ''thread'':202C,210C,212C ''token'':229C ''tool'':52B,161C,169C,172C,182C,234C,248C ''toolnod'':162C ''unbound'':228C ''untrust'':251C ''use'':36B,106B ''user'':205C ''valid'':247C ''want'':95B ''warrant'':244C ''workflow'':44B,91B ''wrapper'':119B');
INSERT INTO public.technology_catalog VALUES ('react', 'React', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/react.png', '#61dafb', '["frontend-app"]', '{"purpose": "Component-based UI library for building interactive single-page applications", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["React 18+", "TypeScript", "Vite", "React Router", "TanStack Query", "Zustand/Jotai"], "antiPatterns": ["Prop drilling through many levels instead of using Context or state management", "Using useEffect for derived state that should be computed during render", "Creating new object/function references in render causing unnecessary re-renders", "Using index as key in lists with dynamic ordering or mutations", "Putting business logic directly in components instead of custom hooks"], "apiReference": {"docsUrl": "https://react.dev/reference/react"}, "bestPractices": ["Use functional components with hooks", "Implement proper state management (lift state up, use context sparingly)", "Memoize expensive computations with useMemo/useCallback", "Use React.lazy for code splitting", "Follow the single responsibility principle per component", "Use TypeScript for type safety", "Implement error boundaries", "Use Suspense for async data loading"], "sdkInitPattern": "npm create vite@latest my-app -- --template react-ts && cd my-app && npm install\\n// src/App.tsx\\nexport default function App() {\\n  return <div>Hello React</div>;\\n}", "securityGuidance": "React auto-escapes JSX output preventing most XSS. Never use dangerouslySetInnerHTML with unsanitized input. Validate and sanitize URL-based props (href, src) to prevent javascript: injection. Use Content Security Policy headers. Avoid storing sensitive tokens in localStorage -- use httpOnly cookies. Sanitize user input before passing to third-party libraries that manipulate DOM directly.", "commonApiPatterns": [{"name": "Component with State", "description": "Functional component with useState hook", "codeTemplate": "function Counter() {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <button onClick={() => setCount(c => c + 1)}>\\n      Count: {count}\\n    </button>\\n  );\\n}"}, {"name": "Data Fetching", "description": "Custom hook for data fetching with loading state", "codeTemplate": "function useUsers() {\\n  const [users, setUsers] = useState<User[]>([]);\\n  const [loading, setLoading] = useState(true);\\n  useEffect(() => {\\n    fetch(\"/api/users\").then(r => r.json()).then(setUsers).finally(() => setLoading(false));\\n  }, []);\\n  return { users, loading };\\n}"}, {"name": "Context Provider", "description": "Context API for global state with typed custom hook", "codeTemplate": "const AuthContext = createContext<AuthState | null>(null);\\nexport function AuthProvider({ children }: { children: ReactNode }) {\\n  const [user, setUser] = useState<User | null>(null);\\n  return (\\n    <AuthContext.Provider value={{ user, setUser }}>\\n      {children}\\n    </AuthContext.Provider>\\n  );\\n}\\nexport const useAuth = () => useContext(AuthContext)!;"}], "integrationPatterns": ["React Router for client-side routing with lazy-loaded routes", "TanStack Query (React Query) for server state management and caching", "Zustand or Jotai for lightweight client state management", "Tailwind CSS or CSS Modules for scoped styling", "Vitest + React Testing Library for component testing"], "configurationTemplate": "// vite.config.ts\\nimport { defineConfig } from \"vite\";\\nimport react from \"@vitejs/plugin-react\";\\nexport default defineConfig({\\n  plugins: [react()],\\n  server: { port: 3000 },\\n  build: { sourcemap: true }\\n});\\n\\n// tsconfig.json\\n{\\n  \"compilerOptions\": {\\n    \"target\": \"ES2020\",\\n    \"module\": \"ESNext\",\\n    \"jsx\": \"react-jsx\",\\n    \"strict\": true,\\n    \"moduleResolution\": \"bundler\"\\n  }\\n}"}', '[{"kind": "source", "path": "src/App.tsx", "language": "typescript", "description": "Root application component"}, {"kind": "source", "path": "src/main.tsx", "language": "typescript", "description": "Application entry point"}, {"kind": "config", "path": "vite.config.ts", "language": "typescript", "description": "Vite build configuration"}, {"kind": "config", "path": "tsconfig.json", "language": "json", "description": "TypeScript configuration"}]', '{"routing": {"type": "enum", "label": "Routing", "default": "react-router", "options": ["react-router", "tanstack-router", "none-single-view"]}, "styling": {"type": "enum", "label": "Styling", "default": "tailwind", "options": ["tailwind", "css-modules", "styled-components", "vanilla-css"]}, "buildTool": {"type": "enum", "label": "Build tool", "default": "vite", "options": ["vite", "custom-webpack", "cra-legacy"], "description": "Vite is the standing default for React-without-a-metaframework; CRA is legacy. If the answer is Next.js, use the Next.js node instead"}, "typescript": {"type": "boolean", "label": "TypeScript", "default": true}, "stateManagement": {"type": "multiselect", "label": "State management", "options": ["zustand", "redux-toolkit", "tanstack-query", "jotai", "mobx", "context-only"], "description": "TanStack Query owns SERVER state; pick at most one CLIENT store beside it"}}', '["rest-api", "graphql-api", "auth-provider", "websocket-server"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-30 12:07:23.877005+00', NULL, '#4DC0E8', '''18'':16C ''app'':30C,38C,46C ''applic'':14B ''auto'':54C ''auto-escap'':53C ''avoid'':85C ''base'':5B,72C ''build'':9B ''cd'':35C ''compon'':4B ''component-bas'':3B ''content'':81C ''cooki'':93C ''creat'':25C ''dangerouslysetinnerhtml'':63C ''default'':44C ''direct'':107C ''dom'':106C ''escap'':55C ''function'':45C ''header'':84C ''hello'':49C '