INSERT INTO public.technology_catalog VALUES ('n8n', 'n8n', NULL, '#EA4B71', '["backend-service", "worker", "external-service"]', '{"purpose": "Source-available workflow automation with 400+ integrations, self-hostable via Docker", "configMode": "definition-as-code", "provenance": {"notes": "docsUrl is the vendor''s canonical documentation root, stamped from model knowledge and checked by scripts/n10-verify-docs-urls.ts; pre-existing body content not yet live-docs verified — upgrade at this row''s enrichment chunk.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Docker", "Webhook triggers", "Code nodes", "Queue mode", "PostgreSQL backend"], "antiPatterns": ["Embedding business-critical logic only in workflows with no code review", "Running production on the default SQLite database", "Exposing unauthenticated webhook URLs for sensitive operations"], "apiReference": {"docsUrl": "https://docs.n8n.io/"}, "bestPractices": ["Run queue mode with separate worker containers for production loads", "Back n8n with PostgreSQL instead of SQLite when self-hosting", "Version workflows by exporting JSON into the repository", "Use webhook triggers with authentication headers, not open endpoints", "Keep secrets in n8n credentials storage, not inline in nodes"], "sdkInitPattern": "docker run -d --name n8n -p 5678:5678 -e DB_TYPE=postgresdb -e N8N_ENCRYPTION_KEY=$KEY n8nio/n8n", "securityGuidance": "Set N8N_ENCRYPTION_KEY explicitly; place the editor behind SSO or basic auth", "treatmentOverride": "boundary"}', '[{"kind": "build", "path": "docker-compose.yml", "priority": "recommended", "description": "n8n service definition"}, {"kind": "config", "path": "workflows/*.json", "priority": "recommended"}]', '{"deployment": {"type": "enum", "label": "Deployment", "default": "self-hosted-docker", "options": ["self-hosted-docker", "n8n-cloud"], "description": "Self-hostable by design (fair-code license); cloud when ops time matters more than data locality"}, "executionMode": {"type": "enum", "label": "Execution mode", "default": "regular", "options": ["regular", "queue-mode-workers"], "description": "Queue mode (Redis + worker processes) is the scale-out story — switch before executions start timing out, not after"}, "workflowsInRepo": {"type": "boolean", "label": "Workflows exported to repo", "default": true, "description": "Workflow JSON exported and versioned — clicked-together automation nobody can restore is the n8n failure mode"}}', '[{"id": "postgresql", "reason": "Workflow persistence"}, {"id": "redis", "reason": "Queue mode broker"}]', false, NULL, NULL, '2026-08-30 12:07:21.442329+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''400'':9B ''5678'':31C,32C ''auth'':55C ''autom'':7B ''avail'':5B ''backend'':24C ''basic'':54C ''behind'':51C ''code'':19C ''d'':27C ''db'':34C ''docker'':15B,16C,25C ''e'':33C,37C ''editor'':50C ''encrypt'':39C,45C ''explicit'':47C ''hostabl'':13B ''integr'':10B ''key'':40C,41C,46C ''mode'':22C ''n8n'':1A,2A,29C,38C,44C ''n8nio/n8n'':42C ''name'':28C ''node'':20C ''p'':30C ''place'':48C ''postgresdb'':36C ''postgresql'':23C ''queue'':21C ''run'':26C ''self'':12B ''self-host'':11B ''set'':43C ''sourc'':4B ''source-avail'':3B ''sso'':52C ''trigger'':18C ''type'':35C ''via'':14B ''webhook'':17C ''workflow'':6B');
INSERT INTO public.technology_catalog VALUES ('nodejs', 'Node.js', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/nodejs.svg', '#339933', '["backend-service", "worker", "webhook-handler", "cli-tool", "shared-library", "realtime-service"]', '{"purpose": "JavaScript/TypeScript on the server — the default backend for product teams already writing TS on the frontend (one language, shared types end-to-end). Spans API services, workers, webhook handlers, CLIs and realtime services. TypeScript is the default; plain JS needs a reason.", "configMode": "code", "provenance": {"notes": "Runtime landscape verified via web search 2026-07-27 (Node LTS incumbent; Bun/Deno 2 production-real, npm-compatible) — carried as the runtime field. Row previously had EMPTY ai_context.", "method": "live-docs", "sources": ["https://nodejs.org/en/about/previous-releases"], "verifiedAt": "2026-07-27"}, "typicalTech": ["TypeScript", "Hono/Fastify", "zod", "pino", "pnpm workspaces", "vitest", "Prisma/Drizzle"], "antiPatterns": ["Blocking the event loop with sync CPU work — move it to a worker node or a queue", "Floating dependency ranges in production services", "Express-era callback patterns in new code — async/await everywhere", "Reading process.env at call sites instead of one validated config module"], "apiReference": {"docsUrl": "https://nodejs.org/docs/latest/api/"}, "bestPractices": ["TypeScript strict mode + a schema validator (zod) at every boundary — request bodies, env vars, queue payloads", "Share types with the frontend through a workspace package — the reason this stack wins is losing it is the anti-pattern", "Structured logging (pino) + graceful shutdown (SIGTERM drains in-flight work) — the two ops basics AIs skip", "Pin the runtime version in package.json engines + the lockfile committed", "Worker-role nodes: one queue consumer per process, scale horizontally — do not thread inside Node"], "sdkInitPattern": "npm init -y && npm install express typescript @types/express tsx && npx tsc --init\\n// src/server.ts\\nimport express from \"express\";\\nconst app = express();\\napp.use(express.json());\\napp.listen(3000);", "securityGuidance": "Use helmet middleware for secure HTTP headers. Validate all input with a schema library (zod, joi). Use parameterized queries to prevent SQL injection. Set rate limiting on public endpoints. Never expose stack traces in production error responses. Use environment variables for secrets, never hardcode. Enable CORS with explicit origin allowlists.", "commonApiPatterns": [{"name": "REST Endpoint", "description": "Express route handler with async DB query and error handling", "codeTemplate": "app.get(\"/api/users/:id\", async (req, res) => {\\n  const user = await db.users.findById(req.params.id);\\n  if (!user) return res.status(404).json({ error: \"Not found\" });\\n  res.json(user);\\n});"}, {"name": "Middleware", "description": "Authentication middleware pattern", "codeTemplate": "function authenticate(req, res, next) {\\n  const token = req.headers.authorization?.split(\" \")[1];\\n  if (!token) return res.status(401).json({ error: \"Unauthorized\" });\\n  try { req.user = verifyToken(token); next(); }\\n  catch { res.status(401).json({ error: \"Invalid token\" }); }\\n}"}, {"name": "Error Handler", "description": "Global error handling middleware", "codeTemplate": "app.use((err, req, res, _next) => {\\n  console.error(err.stack);\\n  res.status(err.status || 500).json({ error: err.message || \"Internal server error\" });\\n});"}], "integrationPatterns": ["Express or Fastify for HTTP server framework", "Prisma, Drizzle, or Knex for type-safe database access", "Bull/BullMQ for background job processing with Redis", "Pino or Winston for structured logging", "Jest or Vitest for testing with supertest for HTTP assertions"], "configurationTemplate": "// tsconfig.json\\n{\\n  \"compilerOptions\": {\\n    \"target\": \"ES2022\",\\n    \"module\": \"NodeNext\",\\n    \"moduleResolution\": \"NodeNext\",\\n    \"outDir\": \"./dist\",\\n    \"rootDir\": \"./src\",\\n    \"strict\": true,\\n    \"esModuleInterop\": true,\\n    \"skipLibCheck\": true\\n  },\\n  \"include\": [\"src/**/*\"]\\n}"}', '[{"kind": "source", "path": "src/index.ts", "language": "typescript", "description": "Server entry point"}, {"kind": "source", "path": "src/routes/index.ts", "language": "typescript", "description": "Route definitions"}, {"kind": "config", "path": "package.json", "language": "json", "description": "Node.js project manifest"}, {"kind": "config", "path": "tsconfig.json", "language": "json", "description": "TypeScript configuration"}]', '{"runtime": {"type": "enum", "label": "Runtime", "default": "node", "options": ["node", "bun", "deno"], "description": "Node LTS is the ecosystem incumbent; Bun (speed, all-in-one toolchain) and Deno 2 (security-by-default, npm-compatible) are real 2026 production alternatives — one node, runtime as configuration"}, "language": {"type": "enum", "label": "Language", "default": "typescript", "options": ["typescript", "javascript"]}, "framework": {"type": "enum", "label": "HTTP framework", "default": "hono", "options": ["hono", "fastify", "express", "nestjs", "plain-node-http"], "description": "Hono = modern, runtime-portable default; Fastify = Node-native performance; Express = the legacy-ecosystem choice; NestJS = batteries-included DI architecture for large teams"}, "packageManager": {"type": "enum", "label": "Package manager", "default": "pnpm", "options": ["pnpm", "npm", "bun", "yarn"]}}', '["database", "cache", "message-broker", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#3c873a', '''3000'':78C ''allowlist'':128C ''alreadi'':13B ''api'':28B ''app'':73C ''backend'':9B ''clis'':33B ''cor'':124C ''default'':8B,40B ''enabl'':123C ''end'':24B,26B ''end-to-end'':23B ''endpoint'':107C ''environ'':117C ''error'':114C ''explicit'':126C ''expos'':109C ''express'':59C,69C,71C,74C ''express.json'':76C ''frontend'':18B ''handler'':32B ''hardcod'':122C ''header'':85C ''helmet'':80C ''hono/fastify'':47C ''http'':84C ''init'':55C,65C ''inject'':101C ''input'':88C ''instal'':58C ''javascript/typescript'':3B ''joi'':94C ''js'':42B ''languag'':20B ''librari'':92C ''limit'':104C ''middlewar'':81C ''n'':66C ''napp.listen'':77C ''napp.use'':75C ''nconst'':72C ''need'':43B ''never'':108C,121C ''nimport'':68C ''node.js'':1A ''nodej'':2A ''npm'':54C,57C ''npx'':63C ''one'':19B ''origin'':127C ''parameter'':96C ''pino'':49C ''plain'':41B ''pnpm'':50C ''prevent'':99C ''prisma/drizzle'':53C ''product'':11B,113C ''public'':106C ''queri'':97C ''rate'':103C ''realtim'':35B ''reason'':45B ''respons'':115C ''schema'':91C ''secret'':120C ''secur'':83C ''server'':6B ''servic'':29B,36B ''set'':102C ''share'':21B ''span'':27B ''sql'':100C ''src/server.ts'':67C ''stack'':110C ''team'':12B ''trace'':111C ''ts'':15B ''tsc'':64C ''tsx'':62C ''type'':22B ''types/express'':61C ''typescript'':37B,46C,60C ''use'':79C,95C,116C ''valid'':86C ''variabl'':118C ''vitest'':52C ''webhook'':31B ''worker'':30B ''workspac'':51C ''write'':14B ''y'':56C ''zod'':48C,93C');
INSERT INTO public.technology_catalog VALUES ('nuxt', 'Nuxt', NULL, '#00dc82', '["frontend-app", "backend-service"]', '{"purpose": "Full-stack Vue framework with hybrid rendering, auto-imports, and file-based routing", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Nuxt 3", "Vue 3", "TypeScript", "Nitro", "UnJS"], "antiPatterns": ["Using axios instead of built-in useFetch breaking SSR hydration", "Putting secrets in public runtimeConfig exposing them to the client", "Not using auto-imports and manually importing Vue APIs and composables", "Creating API proxies when Nitro server routes handle it natively", "Using Options API instead of Composition API with script setup"], "apiReference": {"docsUrl": "https://nuxt.com/docs"}, "bestPractices": ["Use auto-imports for composables and components", "Leverage server routes for API endpoints", "Use useFetch/useAsyncData for data fetching", "Implement proper error handling with error.vue", "Use Nuxt modules for common functionality", "Configure proper SEO with useHead"], "sdkInitPattern": "npx nuxi@latest init my-app && cd my-app && npm install\\n<!-- app.vue -->\\n<template>\\n  <NuxtPage />\\n</template>\\n<!-- pages/index.vue -->\\n<template><h1>Hello Nuxt</h1></template>", "securityGuidance": "Use runtimeConfig for secrets (not public prefix) to keep them server-only. Validate all server route inputs with zod or similar. Use nuxt-security module for automatic security headers. Never expose database credentials in public runtime config. Use server middleware for authentication on API routes. Set CORS policies on Nitro server routes.", "commonApiPatterns": [{"name": "Data Fetching", "description": "useFetch composable for SSR-compatible data loading", "codeTemplate": "<script setup lang=\"ts\">\\nconst { data: users, pending } = await useFetch<User[]>(\"/api/users\");\\n</script>\\n<template>\\n  <div v-if=\"pending\">Loading...</div>\\n  <ul v-else>\\n    <li v-for=\"user in users\" :key=\"user.id\">{{ user.name }}</li>\\n  </ul>\\n</template>"}, {"name": "Server Route", "description": "File-based server API routes with Nitro", "codeTemplate": "// server/api/users.get.ts\\nexport default defineEventHandler(async (event) => {\\n  const users = await db.user.findMany();\\n  return users;\\n});\\n// server/api/users.post.ts\\nexport default defineEventHandler(async (event) => {\\n  const body = await readBody(event);\\n  return db.user.create({ data: body });\\n});"}, {"name": "Middleware", "description": "Route middleware for authentication guard", "codeTemplate": "// middleware/auth.ts\\nexport default defineNuxtRouteMiddleware((to, from) => {\\n  const { loggedIn } = useUserSession();\\n  if (!loggedIn.value) {\\n    return navigateTo(\"/login\", { query: { redirect: to.fullPath } });\\n  }\\n});"}], "integrationPatterns": ["Nitro server engine for API routes and server middleware", "Pinia for state management with SSR hydration support", "Nuxt Modules ecosystem for rapid feature integration", "useFetch/useAsyncData for SSR-safe data fetching", "Vitest + Nuxt Test Utils for component and integration testing"], "configurationTemplate": "// nuxt.config.ts\\nexport default defineNuxtConfig({\\n  devtools: { enabled: true },\\n  modules: [\\n    \"@nuxtjs/tailwindcss\",\\n    \"@pinia/nuxt\",\\n  ],\\n  runtimeConfig: {\\n    dbUrl: \"\",\\n    public: {\\n      apiBase: \"/api\",\\n    },\\n  },\\n});"}', '[{"kind": "source", "path": "app.vue", "language": "vue", "description": "Root component"}, {"kind": "source", "path": "nuxt.config.ts", "language": "typescript", "description": "Nuxt configuration"}]', '{"apiSurface": {"type": "boolean", "label": "server/api routes", "default": true}, "deployment": {"type": "enum", "label": "Deployment (Nitro preset)", "default": "node-server", "options": ["node-server", "static-hosting", "edge", "docker"], "description": "Nitro presets make the same app deployable to any of these — say which one is real"}, "renderingMode": {"type": "enum", "label": "Rendering", "default": "universal-ssr", "options": ["universal-ssr", "spa", "static"]}}', '["database", "cache", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-30 12:07:23.877005+00', NULL, '#00B36B', '''3'':20C,22C ''api'':92C ''app'':32C,36C ''authent'':90C ''auto'':12B ''auto-import'':11B ''automat'':75C ''base'':17B ''cd'':33C ''config'':85C ''cor'':95C ''credenti'':81C ''databas'':80C ''expos'':79C ''file'':16B ''file-bas'':15B ''framework'':7B ''full'':4B ''full-stack'':3B ''header'':77C ''hello'':45C ''hybrid'':9B ''import'':13B ''init'':29C ''input'':64C ''instal'':38C ''keep'':55C ''latest'':28C ''middlewar'':88C ''modul'':73C ''my-app'':30C,34C ''n'':39C,40C,41C,42C,43C,44C ''never'':78C ''nitro'':24C,98C ''npm'':37C ''npx'':26C ''nuxi'':27C ''nuxt'':1A,2A,19C,46C,71C ''nuxt-secur'':70C ''polici'':96C ''prefix'':53C ''public'':52C,83C ''render'':10B ''rout'':18B,63C,93C,100C ''runtim'':84C ''runtimeconfig'':48C ''secret'':50C ''secur'':72C,76C ''server'':58C,62C,87C,99C ''server-on'':57C ''set'':94C ''similar'':68C ''stack'':5B ''typescript'':23C ''unj'':25C ''use'':47C,69C,86C ''valid'':60C ''vue'':6B,21C ''zod'':66C');
INSERT INTO public.technology_catalog VALUES ('open-source-llm', 'Open Source LLM', NULL, '#1d4ed8', '["inference-service"]', '{"purpose": "A self-hosted open-source language model running on private infrastructure. Acts as an AI service component without sending data to third-party cloud APIs.", "typicalTech": ["Ollama", "vLLM", "llama.cpp", "HuggingFace TGI", "LangChain", "LiteLLM", "pgvector", "Docker"], "antiPatterns": ["Running large models on CPU-only instances in production — latency will be severe", "Exposing the inference endpoint directly to the internet without authentication", "Using full-precision models when quantized variants meet quality requirements", "Hardcoding model selection in application code rather than configuring via environment"], "bestPractices": ["Choose a model size that fits your available VRAM — quantized variants (Q4, Q5, Q8) allow larger models in less memory", "Pin a specific model version for reproducibility in production", "Front the model with an LLM gateway (LiteLLM) when exposing to multiple services", "Use a RAG pipeline with a vector database to ground responses in your own data", "Select the runtime (Ollama, vLLM) as a separate Runtime node connected to this one"]}', '[{"kind": "config", "path": "llm/Modelfile", "language": "dockerfile", "description": "Modelfile defining the base model, system prompt, and inference parameters for a custom model variant"}, {"kind": "source", "path": "src/llm/client.py", "language": "python", "description": "Python client for the OpenAI-compatible inference API exposed by the runtime"}, {"kind": "source", "path": "src/llm/client.ts", "language": "typescript", "description": "TypeScript client for the OpenAI-compatible inference API exposed by the runtime"}, {"kind": "config", "path": ".env", "language": "dotenv", "description": "Environment variables: LLM_BASE_URL, LLM_MODEL, LLM_API_KEY (if gated)"}]', '{"maxTokens": {"max": 131072, "min": 0, "type": "number", "label": "Max Tokens (Context)", "default": 4096, "description": "Maximum context window size; 0 uses the model default"}, "streaming": {"type": "boolean", "label": "Streaming", "default": true, "description": "Stream tokens as they are generated"}, "modelFamily": {"type": "enum", "label": "Model Family", "default": "llama3", "options": ["llama3.3", "llama3.2", "llama3.1", "llama3.2-vision", "gemma3", "gemma3:12b", "gemma3:27b", "gemma2", "mistral", "mistral-small", "mistral-nemo", "mixtral", "phi4", "phi4-mini", "phi3.5", "command-r", "command-r-plus", "granite3.3", "granite3.3:8b"], "required": true, "description": "Open-source model family to deploy"}, "temperature": {"max": 2, "min": 0, "type": "number", "label": "Temperature", "default": 0.7, "description": "Sampling temperature (0 = deterministic, 2 = very creative)"}}', '["backend-service", "ai-service", "vector-database", "llm-gateway", "llm-runtime"]', false, NULL, NULL, '2026-03-13 01:22:40.314709+00', '2026-08-30 12:07:23.877005+00', 'Open Source LLM', '#e0f2fe', '''act'':20B ''ai'':23B ''api'':34B ''cloud'':33B ''compon'':25B ''data'':28B ''docker'':43C ''host'':10B ''huggingfac'':38C ''infrastructur'':19B ''langchain'':40C ''languag'':14B ''litellm'':41C ''llama.cpp'':37C ''llm'':3A,6A ''model'':15B ''ollama'':35C ''open'':1A,4A,12B ''open-sourc'':11B ''parti'':32B ''pgvector'':42C ''privat'':18B ''run'':16B ''self'':9B ''self-host'':8B ''send'':27B ''servic'':24B ''sourc'':2A,5A,13B ''tgi'':39C ''third'':31B ''third-parti'':30B ''vllm'':36C ''without'':26B');
INSERT INTO public.technology_catalog VALUES ('prometheus', 'Prometheus', NULL, '#E6522C', '["monitoring"]', '{"purpose": "The standing open-source metrics system: pull-based scraping, PromQL, and alerting via Alertmanager — the de facto exposition format the whole ecosystem (exporters, k8s, Grafana) speaks. Prometheus 3.x is current (native histograms, OTLP ingestion). Metrics only — logs and traces are separate concerns (Loki/Tempo class), and long-term/HA storage is Thanos/Mimir territory.", "configMode": "definition-as-code", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["PromQL", "client libraries", "node_exporter + ecosystem exporters", "Alertmanager", "kube-prometheus-stack", "remote-write (Thanos/Mimir)"], "antiPatterns": ["High-cardinality labels (per-user, per-request IDs) — the #1 way Prometheus falls over", "Push-gateway as a default pattern — it exists for batch jobs, not as an architecture", "Alerting on every metric — ungrouped noisy alerts get muted, muted monitoring is no monitoring", "Treating Prometheus as long-term storage — it is an operational window, not a data warehouse"], "apiReference": {"docsUrl": "https://prometheus.io/docs/"}, "bestPractices": ["Instrument the app with the client library and expose /metrics — counters and histograms over gauges where possible", "WATCH CARDINALITY: every label combination is a time series — user IDs/emails as label values is the classic meltdown", "Alert rules on symptoms (error rate, latency SLO burn) not causes (CPU%); route through Alertmanager with grouping + inhibition", "prometheus.yml + rule files versioned in the repo and deployed like code", "Retention is local and finite by design — remote-write to Thanos/Mimir when you need long-term or HA"], "securityGuidance": "Prometheus has no built-in auth — front the UI and API with a reverse proxy enforcing authentication, or bind to internal interfaces only; /api/v1 exposes every scraped series and the admin API can delete data. Metrics must never carry secrets or PII in label values (labels are forever and high-cardinality), scrape over TLS with credentials where exporters support it, and lock down remote-write receivers — an open one accepts fabricated series.", "configurationTemplate": "# prometheus.yml\nglobal:\n  scrape_interval: 15s\nscrape_configs:\n  - job_name: api\n    metrics_path: /metrics\n    static_configs:\n      - targets: [''api:9464'']"}', '[{"kind": "config", "path": "prometheus/prometheus.yml"}, {"kind": "config", "path": "prometheus/rules/"}]', '{"alerting": {"type": "enum", "label": "Alerting", "default": "alertmanager", "options": ["alertmanager", "grafana-alerting", "none-dashboards-only"]}, "deployment": {"type": "enum", "label": "Deployment", "default": "single-server", "options": ["single-server", "ha-with-thanos-mimir", "agent-mode-remote-write"]}, "scrapeTargets": {"type": "multiselect", "label": "Scrape targets", "options": ["app-custom-metrics", "node-exporter", "database-exporters", "kubernetes-objects"], "description": "What actually gets scraped — each target class is setup work"}}', '[{"id": "grafana", "reason": "The standing dashboard layer over Prometheus data"}]', false, NULL, NULL, '2026-08-30 12:07:22.167076+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''/api/v1'':99C ''/ha'':54B ''3'':32B ''accept'':147C ''admin'':106C ''alert'':16B ''alertmanag'':18B,66C ''api'':86C,107C ''auth'':81C ''authent'':92C ''base'':12B ''bind'':94C ''built'':79C ''built-in'':78C ''cardin'':127C ''carri'':114C ''class'':49B ''client'':60C ''concern'':47B ''credenti'':132C ''current'':35B ''data'':110C ''de'':20B ''delet'':109C ''ecosystem'':26B,64C ''enforc'':91C ''everi'':101C ''export'':27B,63C,65C,134C ''expos'':100C ''exposit'':22B ''fabric'':148C ''facto'':21B ''forev'':123C ''format'':23B ''front'':82C ''grafana'':29B ''high'':126C ''high-cardin'':125C ''histogram'':37B ''ingest'':39B ''interfac'':97C ''intern'':96C ''k8s'':28B ''kube'':68C ''kube-prometheus-stack'':67C ''label'':119C,121C ''librari'':61C ''lock'':138C ''log'':42B ''loki/tempo'':48B ''long'':52B ''long-term'':51B ''metric'':8B,40B,111C ''must'':112C ''nativ'':36B ''never'':113C ''node'':62C ''one'':146C ''open'':6B,145C ''open-sourc'':5B ''otlp'':38B ''pii'':117C ''prometheus'':1A,2A,31B,69C,75C ''promql'':14B,59C ''proxi'':90C ''pull'':11B ''pull-bas'':10B ''receiv'':143C ''remot'':72C,141C ''remote-writ'':71C,140C ''revers'':89C ''scrape'':13B,102C,128C ''secret'':115C ''separ'':46B ''seri'':103C,149C ''sourc'':7B ''speak'':30B ''stack'':70C ''stand'':4B ''storag'':55B ''support'':135C ''system'':9B ''term'':53B ''territori'':58B ''thanos/mimir'':57B,74C ''tls'':130C ''trace'':44B ''ui'':84C ''valu'':120C ''via'':17B ''whole'':25B ''write'':73C,142C ''x'':33B');
INSERT INTO public.technology_catalog VALUES ('redis', 'Redis', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/redis.png', '#dc382d', '["cache", "database", "message-broker", "queue"]', '{"purpose": "Sub-millisecond in-memory data store serving as cache, session store, message broker, and real-time data engine. Use as a caching layer to reduce database load for frequently accessed data, for session management, rate limiting, real-time leaderboards, pub/sub messaging, and ephemeral data that benefits from extreme speed. Redis Streams add event sourcing capabilities. Use Redis as a complement alongside a persistent primary database, not as a replacement. Don''t use as your sole database for data that must survive restarts without careful persistence configuration and backup strategies. Don''t use for large datasets that exceed available memory -- Redis stores everything in RAM. Avoid for complex querying or relational operations. For a fully open-source drop-in alternative, consider Valkey.", "configMode": "declarative", "provenance": {"notes": "docsUrl stamped from model knowledge (B2 guard bug skipped this row); body content predates provenance tracking. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Redis 7+", "Redis Stack", "ioredis", "AWS ElastiCache", "Azure Cache for Redis", "Redis Cluster", "Redis Sentinel", "Valkey"], "antiPatterns": ["Using as primary database without a persistent backing store for critical data", "Storing large objects (>1MB) as single keys consuming excessive memory", "Using KEYS command in production causing blocking scans (use SCAN instead)", "Ignoring memory limits leading to OOM kills or uncontrolled eviction", "Not setting TTL on cache entries causing memory to grow indefinitely", "Using Redis pub/sub for durable messaging (messages are lost if no subscriber is listening)"], "apiReference": {"docsUrl": "https://redis.io/docs/"}, "bestPractices": ["Use appropriate data structures for each use case (strings, hashes, sets, sorted sets, streams)", "Set TTL on all cache keys to prevent unbounded memory growth", "Use pipelining for batch operations to reduce round-trip latency", "Enable persistence (RDB snapshots + AOF) when data durability matters", "Use Redis Cluster for horizontal scaling beyond single-node memory limits", "Monitor memory usage and configure maxmemory-policy for eviction behavior", "Use Lua scripting for atomic multi-step operations"], "freshnessNote": "Licensing state 2026: Redis 8.x carries AGPLv3 (open source again after the 2024 SSPL episode; 8.2 GA 2026-02); Valkey is the BSD Linux Foundation fork at v9 and the default for Redis-compatible workloads. Protocol-compatible — the engine field is the decision, the client code is the same.", "sdkInitPattern": "// Node.js with ioredis\\nimport Redis from \"ioredis\";\\nconst redis = new Redis(process.env.REDIS_URL!);\\n// [Tailor to project language: Python=redis-py, Go=go-redis, Rust=fred, Java=Lettuce, .NET=StackExchange.Redis]", "securityGuidance": "Always set a strong password with requirepass. Enable TLS for all connections. Bind to specific interfaces, never 0.0.0.0 in production without firewall rules. Use ACLs (Redis 6+) to create users with minimal command and key permissions. Disable dangerous commands (FLUSHALL, KEYS, CONFIG) for application users. Place Redis in a private subnet accessible only to application servers.", "commonApiPatterns": [{"name": "Cache Pattern", "description": "Cache-aside pattern with TTL for any async data source", "codeTemplate": "async function getCached<T>(key: string, fetcher: () => Promise<T>, ttl = 300): Promise<T> {\\n  const cached = await redis.get(key);\\n  if (cached) return JSON.parse(cached);\\n  const data = await fetcher();\\n  await redis.setex(key, ttl, JSON.stringify(data));\\n  return data;\\n}"}, {"name": "Rate Limiter", "description": "Simple sliding window rate limiter", "codeTemplate": "async function checkRateLimit(userId: string, limit: number, windowSec: number): Promise<boolean> {\\n  const key = `ratelimit:${userId}`;\\n  const count = await redis.incr(key);\\n  if (count === 1) await redis.expire(key, windowSec);\\n  return count <= limit;\\n}"}, {"name": "Session Store", "description": "Hash-based session storage with expiry", "codeTemplate": "await redis.hset(`session:${sessionId}`, { userId, email, role, expiresAt: Date.now() + 3600000 });\\nawait redis.expire(`session:${sessionId}`, 3600);\\nconst session = await redis.hgetall(`session:${sessionId}`);"}, {"name": "Pub/Sub", "description": "Pub/sub messaging for real-time notifications", "codeTemplate": "const sub = new Redis(process.env.REDIS_URL!);\\nsub.subscribe(\"notifications\");\\nsub.on(\"message\", (channel, message) => {\\n  console.log(`${channel}: ${message}`);\\n});\\nawait redis.publish(\"notifications\", JSON.stringify({ userId, type: \"alert\" }));"}], "setupInstructions": [{"url": "https://redis.io/docs/getting-started/", "type": "manual_workflow", "title": "Provision Redis Instance", "commands": ["docker run -d -p 6379:6379 redis:latest"], "required": true, "instructions": "Provision a Redis instance either locally (for development) or via a managed service (Redis Cloud, ElastiCache, Upstash) for production."}, {"type": "environment_variable", "title": "Set Connection URL", "commands": ["export REDIS_URL=redis://localhost:6379"], "required": true, "instructions": "Configure the Redis connection URL in your environment. For TLS connections, use the rediss:// protocol."}], "integrationPatterns": ["Application cache layer between HTTP handlers and the primary database", "BullMQ or Celery for background job queues backed by Redis", "Redis Streams for lightweight event sourcing and log-based messaging", "Session store for web applications behind a load balancer"], "configurationTemplate": "# redis.conf key settings\\nmaxmemory 256mb\\nmaxmemory-policy allkeys-lru\\nsave 900 1\\nsave 300 10\\nappendonly yes\\nappendfsync everysec\\nrequirepass ${REDIS_PASSWORD}\\nbind 127.0.0.1\\ntls-port 6380\\ntls-cert-file /etc/redis/tls/redis.crt\\ntls-key-file /etc/redis/tls/redis.key"}', '[{"kind": "config", "path": "redis.conf", "language": "conf", "description": "Server configuration (self-hosted): bind address, ACLs/requirepass, persistence (AOF/RDB), maxmemory policy"}, {"kind": "config", "path": "docker-compose.redis.yml", "language": "yaml", "description": "Local/dev Redis service definition with a mounted redis.conf"}]', '{"engine": {"type": "enum", "label": "Engine", "default": "valkey", "options": ["valkey", "redis-8"], "description": "Valkey (BSD, Linux Foundation fork, v9 era) is the de facto open choice for Redis-compatible workloads; Redis 8.x is open source again (AGPLv3 since May 2025) — protocol-compatible, pick by licensing posture. Mirrors the GCP Memorystore ruling"}, "eviction": {"type": "enum", "label": "Eviction policy", "default": "noeviction", "options": ["noeviction", "allkeys-lru", "volatile-ttl"], "description": "allkeys-lru for caches; noeviction for queues/state where silent eviction is corruption"}, "topology": {"type": "enum", "label": "Topology", "default": "standalone", "options": ["standalone", "sentinel-ha", "cluster"], "description": "Standalone until memory or availability forces otherwise; cluster changes multi-key semantics — not a free upgrade"}, "persistence": {"type": "enum", "label": "Persistence", "default": "aof-everysec", "options": ["aof-everysec", "rdb-snapshots", "none-pure-cache"], "description": "none is CORRECT for a pure cache — declare it so the packet does not treat cache loss as data loss"}}', '["backend-service", "worker", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-30 12:07:23.877005+00', NULL, '#B82E25', '''0.0.0.0'':195C ''6'':204C ''7'':131C ''access'':35B,229C ''acl'':202C ''add'':58B ''alongsid'':67B ''altern'':127B ''alway'':178C ''applic'':221C,232C ''avail'':104B ''avoid'':111B ''aw'':135C ''azur'':137C ''backup'':94B ''benefit'':52B ''bind'':190C ''broker'':17B ''cach'':13B,27B,138C ''capabl'':61B ''care'':90B ''cluster'':142C ''command'':210C,216C ''complement'':66B ''complex'':113B ''config'':219C ''configur'':92B ''connect'':189C ''consid'':128B ''creat'':206C ''danger'':215C ''data'':9B,22B,36B,50B,84B ''databas'':31B,71B,82B ''dataset'':101B ''disabl'':214C ''drop'':125B ''drop-in'':124B ''elasticach'':136C ''enabl'':185C ''engin'':23B ''ephemer'':49B ''event'':59B ''everyth'':108B ''exceed'':103B ''extrem'':54B ''firewal'':199C ''flushal'':217C ''fred'':173C ''frequent'':34B ''fulli'':120B ''go'':168C,170C ''go-redi'':169C ''in-memori'':6B ''interfac'':193C ''ioredi'':134C,148C,152C ''java'':174C ''key'':212C,218C ''languag'':163C ''larg'':100B ''layer'':28B ''leaderboard'':45B ''lettuc'':175C ''limit'':41B ''load'':32B ''manag'':39B ''memori'':8B,105B ''messag'':16B,47B ''millisecond'':5B ''minim'':209C ''must'':86B ''n'':159C ''nconst'':153C ''net'':176C ''never'':194C ''new'':155C ''nimport'':149C ''node.js'':146C ''open'':122B ''open-sourc'':121B ''oper'':117B ''password'':182C ''permiss'':213C ''persist'':69B,91B ''place'':223C ''primari'':70B ''privat'':227C ''process.env.redis'':157C ''product'':197C ''project'':162C ''pub/sub'':46B ''py'':167C ''python'':164C ''queri'':114B ''ram'':110B ''rate'':40B ''real'':20B,43B ''real-tim'':19B,42B ''redi'':1A,2A,56B,63B,106B,130C,132C,140C,141C,143C,150C,154C,156C,166C,171C,203C,224C ''redis-pi'':165C ''reduc'':30B ''relat'':116B ''replac'':75B ''requirepass'':184C ''restart'':88B ''rule'':200C ''rust'':172C ''sentinel'':144C ''serv'':11B ''server'':233C ''session'':14B,38B ''set'':179C ''sole'':81B ''sourc'':60B,123B ''specif'':192C ''speed'':55B ''stack'':133C ''stackexchange.redis'':177C ''store'':10B,15B,107B ''strategi'':95B ''stream'':57B ''strong'':181C ''sub'':4B ''sub-millisecond'':3B ''subnet'':228C ''surviv'':87B ''tailor'':160C ''time'':21B,44B ''tls'':186C ''url'':158C ''use'':24B,62B,78B,98B,201C ''user'':207C,222C ''valkey'':129B,145C ''without'':89B,198C');
INSERT INTO public.technology_catalog VALUES ('svelte', 'Svelte', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/svelte.png', '#ff3e00', '["frontend-app"]', '{"purpose": "Compiler-based framework that shifts work from runtime to build time, producing minimal vanilla JavaScript", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Svelte 5", "SvelteKit", "TypeScript", "Vite"], "antiPatterns": ["Using onMount for data that should load via SvelteKit load functions", "Overusing stores when component-local $state is sufficient", "Using {@html} with user-provided content without sanitization", "Not using TypeScript with lang=\"ts\" losing type safety benefits", "Creating deeply nested component hierarchies instead of using slots and composition"], "apiReference": {"docsUrl": "https://svelte.dev/docs"}, "bestPractices": ["Use runes ($state, $derived, $effect) in Svelte 5", "Leverage SvelteKit for routing and SSR", "Use stores for shared state", "Keep components small and focused", "Use TypeScript for type safety", "Implement proper loading states with SvelteKit"], "sdkInitPattern": "npx sv create my-app && cd my-app && npm install\\n<!-- src/routes/+page.svelte -->\\n<script lang=\"ts\">\\n  let count = $state(0);\\n</script>\\n<button onclick={() => count++}>Count: {count}</button>", "securityGuidance": "Svelte auto-escapes template expressions. Never use {@html ...} with unsanitized user content. Validate form inputs server-side in SvelteKit form actions. Use SvelteKit hooks for centralized authentication checks. Set CSP headers via SvelteKit hooks.server.ts. Use environment variables via $env/static/private for server-only secrets.", "commonApiPatterns": [{"name": "Reactive Component", "description": "Component with Svelte 5 runes: $props, $state, $derived", "codeTemplate": "<script lang=\"ts\">\\n  let { data }: { data: PageData } = $props();\\n  let search = $state(\"\");\\n  let filtered = $derived(data.items.filter(i => i.name.includes(search)));\\n</script>\\n<input bind:value={search} placeholder=\"Search...\" />\\n{#each filtered as item (item.id)}\\n  <div>{item.name}</div>\\n{/each}"}, {"name": "SvelteKit Load Function", "description": "Server-side data loading with SvelteKit", "codeTemplate": "// src/routes/users/+page.server.ts\\nexport async function load({ fetch }) {\\n  const res = await fetch(\"/api/users\");\\n  if (!res.ok) throw error(res.status, \"Failed to load users\");\\n  const users: User[] = await res.json();\\n  return { users };\\n}"}, {"name": "Store Pattern", "description": "Writable store with derived computed value", "codeTemplate": "import { writable, derived } from \"svelte/store\";\\nexport const cart = writable<CartItem[]>([]);\\nexport const total = derived(cart, $cart =>\\n  $cart.reduce((sum, item) => sum + item.price * item.qty, 0)\\n);"}], "integrationPatterns": ["SvelteKit for full-stack framework with SSR and file-based routing", "Svelte stores for reactive state management", "Tailwind CSS or vanilla CSS scoped by default in Svelte components", "Superforms for type-safe form handling with validation", "Vitest + Svelte Testing Library for component testing"], "configurationTemplate": "// svelte.config.js\\nimport adapter from \"@sveltejs/adapter-auto\";\\nimport { vitePreprocess } from \"@sveltejs/vite-plugin-svelte\";\\nexport default {\\n  preprocess: vitePreprocess(),\\n  kit: {\\n    adapter: adapter(),\\n    alias: { \"$components\": \"src/lib/components\" }\\n  }\\n};"}', '[{"kind": "source", "path": "src/routes/+page.svelte", "language": "svelte", "description": "Home page"}, {"kind": "source", "path": "src/routes/+layout.svelte", "language": "svelte", "description": "Root layout"}, {"kind": "config", "path": "svelte.config.js", "language": "javascript", "description": "Svelte configuration"}]', '{"framework": {"type": "enum", "label": "Framework", "default": "sveltekit", "options": ["sveltekit", "svelte-standalone"], "description": "SvelteKit is the standing answer for apps; standalone Svelte for embedding components elsewhere"}, "deployment": {"type": "enum", "label": "Deployment (adapter)", "default": "node-server", "options": ["node-server", "static", "edge", "vercel"]}, "typescript": {"type": "boolean", "label": "TypeScript", "default": true}, "reactivityModel": {"type": "enum", "label": "Reactivity model", "default": "runes", "options": ["runes", "legacy-stores"], "description": "Runes ($state/$derived/$effect) are the Svelte 5+ model — pick before writing components, the authoring style differs"}}', '["rest-api", "graphql-api", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-30 12:07:23.877005+00', NULL, '#CC3200', '''5'':20C ''action'':66C ''app'':29C,33C ''authent'':72C ''auto'':46C ''auto-escap'':45C ''base'':5B ''build'':13B ''button'':39C ''cd'':30C ''central'':71C ''check'':73C ''compil'':4B ''compiler-bas'':3B ''content'':56C ''count'':41C,42C,43C ''creat'':26C ''csp'':75C ''env/static/private'':84C ''environ'':81C ''escap'':47C ''express'':49C ''form'':58C,65C ''framework'':6B ''header'':76C ''hook'':69C ''hooks.server.ts'':79C ''html'':52C ''input'':59C ''instal'':35C ''javascript'':18B ''minim'':16B ''my-app'':27C,31C ''n'':36C,37C,38C ''never'':50C ''npm'':34C ''npx'':24C ''onclick'':40C ''produc'':15B ''runtim'':11B ''secret'':89C ''server'':61C,87C ''server-on'':86C ''server-sid'':60C ''set'':74C ''shift'':8B ''side'':62C ''sv'':25C ''svelt'':1A,2A,19C,44C ''sveltekit'':21C,64C,68C,78C ''templat'':48C ''time'':14B ''typescript'':22C ''unsanit'':54C ''use'':51C,67C,80C ''user'':55C ''valid'':57C ''vanilla'':17B ''variabl'':82C ''via'':77C,83C ''vite'':23C ''work'':9B');
INSERT INTO public.technology_catalog VALUES ('swift-ios', 'Swift (iOS)', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/swift-ios.png', '#F05138', '["mobile-app"]', '{"purpose": "Apple''s native programming language for iOS, iPadOS, macOS, watchOS, and tvOS application development. Use when building apps that need the deepest integration with Apple platform features -- ARKit, HealthKit, CarPlay, Widgets, App Clips, and advanced camera/CoreML capabilities. SwiftUI provides a declarative UI framework for building modern Apple apps. Native Swift apps deliver the best performance, smallest memory footprint, and most polished user experience on Apple devices. Don''t use when you need cross-platform Android support from the same codebase -- use Flutter or React Native instead. Don''t use for simple content-only apps where a cross-platform solution would be more cost-effective. Avoid Swift for backend services unless the team specifically wants server-side Swift (Vapor) -- Node.js, Go, or Python are more common choices.", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (UI model, concurrency model, persistence, distribution); live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Swift 5.9+", "SwiftUI", "Xcode", "UIKit", "Combine", "Swift Package Manager", "CoreData/SwiftData", "XCTest"], "antiPatterns": ["Massive view controllers (or massive views in SwiftUI) without proper decomposition", "Using singletons everywhere instead of dependency injection", "Force-unwrapping optionals (!) without safety checks", "Not using structured concurrency causing data races and thread-safety issues", "Ignoring memory management (retain cycles) with closures and delegates", "Blocking the main thread with synchronous network or file operations"], "apiReference": {"docsUrl": "https://developer.apple.com/documentation/"}, "bestPractices": ["Use SwiftUI with MVVM pattern for new projects targeting iOS 16+", "Use Swift concurrency (async/await, actors) instead of completion handlers", "Follow Human Interface Guidelines for navigation and layout patterns", "Use Swift Package Manager for dependency management", "Implement proper error handling with typed throws and Result types", "Write unit tests with XCTest and UI tests with XCUITest", "Use Instruments for performance profiling (Time Profiler, Memory Graph)"], "sdkInitPattern": "// Xcode: File > New > Project > App (SwiftUI)\\n// ContentView.swift\\nimport SwiftUI\\nstruct ContentView: View {\\n    var body: some View {\\n        NavigationStack {\\n            Text(\"Hello Swift\")\\n                .navigationTitle(\"Home\")\\n        }\\n    }\\n}\\n#Preview { ContentView() }", "securityGuidance": "Use Keychain Services for storing credentials and tokens. Enable App Transport Security (ATS) to enforce HTTPS. Use certificate pinning for sensitive API communications. Never store secrets in UserDefaults or plain files. Use biometric authentication (FaceID/TouchID) via LocalAuthentication framework for sensitive operations. Code-sign all releases and enable Hardened Runtime.", "commonApiPatterns": [{"name": "SwiftUI View with State", "description": "SwiftUI view with @State for local reactive state", "codeTemplate": "struct CounterView: View {\\n    @State private var count = 0\\n    var body: some View {\\n        VStack {\\n            Text(\"Count: \\\\(count)\").font(.title)\\n            Button(\"Increment\") { count += 1 }\\n        }\\n    }\\n}"}, {"name": "Async Data Loading", "description": "Observable view model with async data fetching", "codeTemplate": "@Observable class UserViewModel {\\n    var users: [User] = []\\n    var isLoading = false\\n    func loadUsers() async throws {\\n        isLoading = true\\n        defer { isLoading = false }\\n        let (data, _) = try await URLSession.shared.data(from: URL(string: \"https://api.example.com/users\")!)\\n        users = try JSONDecoder().decode([User].self, from: data)\\n    }\\n}"}, {"name": "Navigation", "description": "Type-safe navigation with NavigationStack", "codeTemplate": "NavigationStack {\\n    List(users) { user in\\n        NavigationLink(value: user) {\\n            Text(user.name)\\n        }\\n    }\\n    .navigationDestination(for: User.self) { user in\\n        UserDetailView(user: user)\\n    }\\n}"}], "setupInstructions": [{"url": "https://developer.apple.com/programs/enroll/", "type": "console", "title": "Enroll in the Apple Developer Program", "required": true, "instructions": "Required before any device install or store upload ($99/yr, org verification can take days — start early). Individual vs Organization changes the seller name on the listing."}, {"url": "https://appstoreconnect.apple.com", "type": "console", "title": "Create the App Store Connect app record", "required": true, "instructions": "Reserve the bundle ID and app name in App Store Connect. The bundle ID is permanent once shipped — decide it deliberately."}, {"type": "console", "title": "Signing: certificates + provisioning profiles", "required": true, "instructions": "Distribution certificate + provisioning profile per bundle ID. Prefer automation (Xcode managed signing, or fastlane match with an encrypted certs repo) over hand-managed .p12 files — hand-managed signing is the top cause of broken mobile CI."}, {"type": "console", "title": "TestFlight before review", "required": false, "instructions": "Internal testers are instant; external testing needs a lightweight beta review. Ship the first build to TestFlight days before the store submission, not the same day."}, {"type": "manual", "title": "App Review submission", "required": true, "instructions": "Privacy nutrition labels, export-compliance question, screenshots per device class, review notes with a demo account. First reviews commonly take 1-3 days and REJECTIONS ARE NORMAL — budget an iteration."}], "integrationPatterns": ["Supabase Swift SDK or Firebase iOS SDK for backend services", "Swift concurrency (async/await) for clean networking with URLSession", "TestFlight for beta distribution and App Store Connect for release"], "configurationTemplate": "// Package.swift (for SPM dependencies)\\n// swift-tools-version: 5.9\\nimport PackageDescription\\nlet package = Package(\\n    name: \"MyApp\",\\n    platforms: [.iOS(.v17)],\\n    dependencies: [\\n        .package(url: \"https://github.com/supabase/supabase-swift\", from: \"2.0.0\"),\\n    ]\\n)"}', '[{"kind": "config", "path": "Package.swift", "language": "swift", "description": "Swift Package Manager manifest"}, {"kind": "source", "path": "Sources/App/App.swift", "language": "swift", "description": "Application entry point"}, {"kind": "source", "path": "Sources/App/ContentView.swift", "language": "swift", "description": "Main content view"}, {"kind": "config", "path": "Info.plist", "language": "xml", "description": "Application configuration plist"}, {"kind": "source", "path": "Tests/AppTests.swift", "language": "swift", "description": "Unit test suite"}]', '{"concurrency": {"type": "enum", "label": "Concurrency", "default": "swift-concurrency", "options": ["swift-concurrency", "combine-legacy", "mixed"], "description": "async/await + actors is the current model; Combine survives in older code"}, "persistence": {"type": "enum", "label": "Persistence", "default": "swiftdata", "options": ["swiftdata", "coredata-legacy", "grdb-sqlite", "none-api-only"]}, "uiFramework": {"type": "enum", "label": "UI framework", "default": "swiftui", "options": ["swiftui", "uikit-legacy", "mixed"], "description": "SwiftUI is the standing default for new apps; UIKit interop where a control genuinely needs it"}, "distribution": {"type": "enum", "label": "Distribution", "default": "app-store", "options": ["app-store", "testflight-only", "enterprise"], "description": "Signing, provisioning profiles and App Store review are MANUAL console/Xcode steps, not code"}}', '["web.rest-api", "auth.supabase-auth", "database.firebase"]', false, NULL, NULL, '2026-02-16 02:23:50.361867+00', '2026-08-30 12:07:23.877005+00', NULL, '#D63B25', '''5.9'':137C ''advanc'':39B ''android'':80B ''api'':201C ''app'':22B,36B,52B,55B,100B,151C,189C ''appl'':5B,29B,51B,69B ''applic'':17B ''arkit'':32B ''at'':192C ''authent'':213C ''avoid'':113B ''backend'':116B ''best'':58B ''biometr'':212C ''bodi'':162C ''build'':21B,49B ''camera/coreml'':40B ''capabl'':41B ''carplay'':34B ''certif'':197C ''choic'':135B ''clip'':37B ''code'':222C ''code-sign'':221C ''codebas'':85B ''combin'':141C ''common'':134B ''communic'':202C ''content'':98B ''content-on'':97B ''contentview'':158C,179C ''contentview.swift'':154C ''coredata/swiftdata'':145C ''cost'':111B ''cost-effect'':110B ''credenti'':185C ''cross'':78B,104B ''cross-platform'':77B,103B ''declar'':45B ''deepest'':26B ''deliv'':56B ''develop'':18B ''devic'':70B ''effect'':112B ''enabl'':188C,227C ''enforc'':194C ''experi'':67B ''faceid/touchid'':214C ''featur'':31B ''file'':148C,210C ''flutter'':87B ''footprint'':62B ''framework'':47B,217C ''go'':129B ''harden'':228C ''healthkit'':33B ''hello'':169C ''home'':173C ''https'':195C ''instead'':91B ''integr'':27B ''io'':2A,4A,11B ''ipado'':12B ''keychain'':181C ''languag'':9B ''localauthent'':216C ''maco'':13B ''manag'':144C ''memori'':61B ''modern'':50B ''n'':153C,160C,165C,167C,171C,174C,175C,176C,177C ''nativ'':7B,53B,90B ''navigationstack'':166C ''navigationtitl'':172C ''need'':24B,76B ''never'':203C ''new'':149C ''nimport'':155C ''node.js'':128B ''nstruct'':157C ''oper'':220C ''packag'':143C ''perform'':59B ''pin'':198C ''plain'':209C ''platform'':30B,79B,105B ''polish'':65B ''preview'':178C ''program'':8B ''project'':150C ''provid'':43B ''python'':131B ''react'':89B ''releas'':225C ''runtim'':229C ''secret'':205C ''secur'':191C ''sensit'':200C,219C ''server'':124B ''server-sid'':123B ''servic'':117B,182C ''side'':125B ''sign'':223C ''simpl'':96B ''smallest'':60B ''solut'':106B ''specif'':121B ''store'':184C,204C ''support'':81B ''swift'':1A,3A,54B,114B,126B,136C,142C,170C ''swiftui'':42B,138C,152C,156C ''team'':120B ''text'':168C ''token'':187C ''transport'':190C ''tvos'':16B ''ui'':46B ''uikit'':140C ''unless'':118B ''use'':19B,73B,86B,94B,180C,196C,211C ''user'':66B ''userdefault'':207C ''vapor'':127B ''var'':161C ''via'':215C ''view'':159C,164C ''want'':122B ''watcho'':14B ''widget'':35B ''would'':107B ''xcode'':139C,147C ''xctest'':146C');
INSERT INTO public.technology_catalog VALUES ('traefik', 'Traefik', NULL, '#24A1C1', '["load-balancer", "api-gateway"]', '{"purpose": "Container-native reverse proxy / edge router (v3 era): discovers routes from Docker labels or Kubernetes resources and reconfigures live — no config reloads — with built-in Let''s Encrypt automation and middleware chain (rate-limit, auth-forward, redirect). The default edge for docker-compose and small-k8s stacks; nginx remains the static-config classic, HAProxy the raw-TCP/HA specialist.", "configMode": "definition-as-code", "provenance": {"notes": "Phase B8a additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Docker provider (labels)", "Kubernetes IngressRoute CRDs", "Let''s Encrypt resolvers", "middlewares", "v3 rule syntax"], "antiPatterns": ["Hand-writing a static file config that mirrors what labels would declare — you lose live discovery, the reason to pick Traefik", "Exposing the dashboard/API publicly without auth", "Using Traefik as an app-level API gateway with business logic — routing yes, transformation logic belongs in services"], "apiReference": {"docsUrl": "https://doc.traefik.io/traefik/"}, "bestPractices": ["Declare routes as Docker labels / IngressRoute CRDs next to the service they route — the discovery model IS the point", "Let''s Encrypt automation with the resolver declared once; DNS challenge for wildcard certs", "Middlewares for cross-cutting edge concerns (rate limiting, forward-auth to your auth service, compression) instead of app-level re-implementation", "Pin the image major version; v2 → v3 changed the rule syntax — mixed-version label sets fail quietly"], "securityGuidance": "Set exposedByDefault: false — implicit exposure of every container is the classic Traefik incident. Keep the dashboard/API off public entrypoints (api.insecure must stay false; put auth middleware in front if you route it at all). acme.json holds your private keys — mode 600 on a persistent volume. Attach security middlewares (headers, rate limit, basic/forward auth) per router, and pin the Docker/K8s provider''s scope so Traefik only reads the namespaces it serves.", "configurationTemplate": "# traefik.yml (static)\nentryPoints:\n  websecure:\n    address: '':443''\nproviders:\n  docker:\n    exposedByDefault: false\ncertificatesResolvers:\n  le:\n    acme:\n      email: ops@example.com\n      storage: /data/acme.json\n      httpChallenge:\n        entryPoint: web"}', '[{"kind": "config", "path": "traefik/traefik.yml"}, {"kind": "config", "path": "docker-compose.yml"}]', '{"tls": {"type": "enum", "label": "TLS", "default": "lets-encrypt-auto", "options": ["lets-encrypt-auto", "manual-certs"]}, "middlewares": {"type": "multiselect", "label": "Middlewares", "options": ["rate-limit", "forward-auth", "https-redirect", "compression", "ip-allowlist"], "description": "Edge concerns handled at the proxy — each is config, not app code"}, "configSource": {"type": "enum", "label": "Route discovery", "default": "docker-labels", "options": ["docker-labels", "kubernetes-crds", "static-file"]}}', '[{"id": "docker", "reason": "Label-based route discovery on the compose stack"}]', false, NULL, NULL, '2026-08-30 12:07:22.167076+00', '2026-08-30 12:07:23.877005+00', NULL, NULL, '''/ha'':68B ''600'':124C ''acme.json'':118C ''api.insecure'':103C ''attach'':129C ''auth'':41B,108C,136C ''auth-forward'':40B ''autom'':33B ''basic/forward'':135C ''built'':28B ''built-in'':27B ''chain'':36B ''classic'':62B,94C ''compos'':50B ''config'':24B,61B ''contain'':4B,91C ''container-n'':3B ''crds'':75C ''dashboard/api'':99C ''default'':45B ''discov'':12B ''docker'':15B,49B,70C ''docker-compos'':48B ''docker/k8s'':142C ''edg'':8B,46B ''encrypt'':32B,78C ''entrypoint'':102C ''era'':11B ''everi'':90C ''exposedbydefault'':85C ''exposur'':88C ''fals'':86C,106C ''forward'':42B ''front'':111C ''haproxi'':63B ''header'':132C ''hold'':119C ''implicit'':87C ''incid'':96C ''ingressrout'':74C ''k8s'':54B ''keep'':97C ''key'':122C ''kubernet'':18B,73C ''label'':16B,72C ''let'':30B,76C ''limit'':39B,134C ''live'':22B ''middlewar'':35B,80C,109C,131C ''mode'':123C ''must'':104C ''namespac'':151C ''nativ'':5B ''nginx'':56B ''per'':137C ''persist'':127C ''pin'':140C ''privat'':121C ''provid'':71C,143C ''proxi'':7B ''public'':101C ''put'':107C ''rate'':38B,133C ''rate-limit'':37B ''raw'':66B ''raw-tcp'':65B ''read'':149C ''reconfigur'':21B ''redirect'':43B ''reload'':25B ''remain'':57B ''resolv'':79C ''resourc'':19B ''revers'':6B ''rout'':13B,114C ''router'':9B,138C ''rule'':82C ''scope'':145C ''secur'':130C ''serv'':153C ''set'':84C ''small'':53B ''small-k8s'':52B ''specialist'':69B ''stack'':55B ''static'':60B ''static-config'':59B ''stay'':105C ''syntax'':83C ''tcp'':67B ''traefik'':1A,2A,95C,147C ''v3'':10B,81C ''volum'':128C');
INSERT INTO public.technology_catalog VALUES ('weaviate', 'Weaviate', NULL, '#00C78C', '["vector-database"]', '{"purpose": "Weaviate is an open-source vector database for storing and querying vector embeddings alongside structured data. Supports hybrid search combining vector similarity with keyword filtering.", "configMode": "declarative", "provenance": {"notes": "docsUrl stamped from model knowledge, checked by n10:verify-urls; body content predates provenance tracking. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Storing raw documents without chunking -- leads to poor retrieval quality", "Using auto-schema in production -- causes inconsistent property types", "Running without backups -- vector data is expensive to regenerate", "Ignoring distance metrics -- choose cosine, dot, or L2 based on your embedding model"], "apiReference": {"docsUrl": "https://weaviate.io/developers/weaviate"}, "bestPractices": ["Define explicit schemas with typed properties rather than relying on auto-schema", "Use batch imports for bulk data ingestion to maximize throughput", "Choose vectorizer modules that match your embedding model (text2vec-openai, text2vec-cohere, etc.)", "Set alpha parameter in hybrid search to balance vector vs keyword relevance (0=keyword, 1=vector)", "Use multi-tenancy for SaaS workloads to isolate tenant data at the collection level"], "sdkInitPattern": "import weaviate from \"weaviate-client\"; const client = await weaviate.connectToLocal({ host: \"localhost\", port: 8080 });", "securityGuidance": "Disable anonymous access in production. Use OIDC or API key authentication. Enable TLS for all client connections. Restrict network access to Weaviate ports (8080 HTTP, 50051 gRPC). Use RBAC when available for fine-grained access control.", "commonApiPatterns": [{"name": "Create Collection", "description": "Define a collection with vectorizer and typed properties", "codeTemplate": "await client.collections.create({ name: \"Articles\", vectorizers: weaviate.configure.vectorizer.text2VecOpenAI(), properties: [{ name: \"title\", dataType: \"text\" }, { name: \"body\", dataType: \"text\" }] });"}, {"name": "Insert Objects", "description": "Batch insert objects into a collection", "codeTemplate": "const collection = client.collections.get(\"Articles\"); await collection.data.insertMany([{ title: \"...\", body: \"...\" }]);"}, {"name": "Vector Search", "description": "Semantic similarity search using nearText", "codeTemplate": "const result = await collection.query.nearText(\"search query\", { limit: 10, returnProperties: [\"title\", \"body\"] });"}, {"name": "Hybrid Search", "description": "Combine vector and keyword search with alpha weighting", "codeTemplate": "const result = await collection.query.hybrid(\"search query\", { limit: 10, alpha: 0.5 });"}], "integrationPatterns": ["LangChain/LlamaIndex vector store adapter for RAG pipelines", "OpenAI or Cohere embedding APIs via built-in vectorizer modules", "Kubernetes StatefulSet for production deployment with persistent volumes", "Backup and restore via Weaviate backup API to S3 or GCS"], "configurationTemplate": "docker run -d -p 8080:8080 -p 50051:50051 -e AUTHENTICATION_ANONYMOUS_ACCESS_ENABLED=false -e AUTHENTICATION_OIDC_ENABLED=true -e DEFAULT_VECTORIZER_MODULE=text2vec-openai cr.weaviate.io/semitechnologies/weaviate:latest"}', '[{"kind": "client", "path": "src/vectordb/weaviate-client.ts"}, {"kind": "schema", "path": "src/vectordb/collections.ts"}, {"kind": "config", "path": "docker-compose.weaviate.yml"}]', '{"searchMode": {"type": "enum", "label": "Search mode", "default": "hybrid-bm25-vector", "options": ["hybrid-bm25-vector", "pure-vector", "pure-keyword"], "description": "Hybrid is the honest default for RAG — pure vector search loses exact-term matches"}, "multiTenancy": {"type": "boolean", "label": "Multi-tenancy", "default": false, "description": "Native tenant isolation per collection — decide before data lands, not after"}, "vectorization": {"type": "enum", "label": "Vectorization", "default": "bring-your-own-vectors", "options": ["bring-your-own-vectors", "built-in-modules"], "description": "BYO vectors keeps the embedding model choice in YOUR pipeline; built-in modules call providers from inside the database"}}', '[{"targetRole": "backend-service", "contractKind": "sdk"}, {"targetRole": "ai-service", "contractKind": "rest_api"}, {"targetRole": "llm-gateway", "contractKind": "sdk"}]', false, NULL, NULL, '2026-02-16 23:46:48.04289+00', '2026-08-30 12:07:23.877005+00', NULL, '#00A675', '''50051'':68C ''8080'':42C,66C ''access'':45C,62C,78C ''alongsid'':17B ''anonym'':44C ''api'':51C ''authent'':53C ''avail'':73C ''await'':37C ''client'':34C,36C,58C ''combin'':23B ''connect'':59C ''const'':35C ''control'':79C ''data'':19B ''databas'':10B ''disabl'':43C ''embed'':16B ''enabl'':54C ''filter'':28B ''fine'':76C ''fine-grain'':75C ''grain'':77C ''grpc'':69C ''host'':39C ''http'':67C ''hybrid'':21B ''import'':29C ''key'':52C ''keyword'':27B ''localhost'':40C ''network'':61C ''oidc'':49C ''open'':7B ''open-sourc'':6B ''port'':41C,65C ''product'':47C ''queri'':14B ''rbac'':71C ''restrict'':60C ''search'':22B ''similar'':25B ''sourc'':8B ''store'':12B ''structur'':18B ''support'':20B ''tls'':55C ''use'':48C,70C ''vector'':9B,15B,24B ''weaviat'':1A,2A,3B,30C,33C,64C ''weaviate-cli'':32C ''weaviate.connecttolocal'':38C');
INSERT INTO public.technology_catalog VALUES ('supabase', 'Supabase (Managed)', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_managed.png', '#3ECF8E', '["supabase"]', '{"purpose": "The managed Supabase platform as a CONTAINER: place it, then nest only the services this system actually adopts - Auth, Database, Storage, Realtime, Edge Functions are separate contained nodes because the platform sells a-la-carte and architectures should say which parts they rent. The platform node carries project-level facts (region, environment tiers, API gateway surface); each service node carries its own doctrine and configuration.", "configMode": "declarative", "provenance": {"notes": "Platform-container rewrite for the Supabase round (owner direction 2026-08-11): services are contained nodes, adopted a-la-carte. Prior thin platform context superseded.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Project + environment tiers", "supabase-js / service clients", "CLI migrations (supabase db push)", "Row Level Security", "API gateway (PostgREST/Kong surface)"], "antiPatterns": ["One platform node standing for auth+db+storage+realtime with the adoption story invisible", "service_role key in client code or edge-exposed configuration", "Dashboard-authored schema changes that never land in migration history", "Treating Supabase as only-a-database while its Auth/Storage/Realtime go unmodeled beside a duplicate stack"], "apiReference": {"docsUrl": "https://supabase.com/docs"}, "bestPractices": ["Model each adopted service as its own contained node - a lone platform box hides the real architecture", "One Supabase project per environment (dev/staging/prod) with config promoted by migration, not console drift", "Treat the service_role key as a server-only secret and the anon key as public-by-design - RLS is the real boundary", "Keep schema in migrations under git; the dashboard SQL editor is for reading, not for production change"]}', '[]', '{"region": {"type": "string", "label": "Region", "description": "Supabase project region (e.g. us-east-1)"}, "services": {"type": "multiselect", "label": "Services Used", "options": ["database-postgres", "auth", "storage", "edge-functions", "realtime", "vector"], "required": true, "description": "Which Supabase services this architecture actually uses — using only a portion is expected; each service is its own config and cost surface"}, "environment": {"type": "string", "label": "Environment", "default": "production", "description": "production, staging, development"}}', '[]', false, NULL, NULL, '2026-08-30 12:07:22.498732+00', '2026-08-30 12:07:24.245143+00', 'Supabase (Managed)', NULL, '''a-la-cart'':36B ''actual'':20B ''adopt'':21B ''api'':59B,87C ''architectur'':41B ''auth'':22B ''carri'':51B,65B ''cart'':39B ''cli'':79C ''client'':78C ''configur'':70B ''contain'':10B,30B ''databas'':23B ''db'':82C ''doctrin'':68B ''edg'':26B ''environ'':57B,72C ''fact'':55B ''function'':27B ''gateway'':60B,88C ''js'':76C ''la'':38B ''level'':54B,85C ''manag'':2A,5B ''migrat'':80C ''nest'':14B ''node'':31B,50B,64B ''part'':45B ''place'':11B ''platform'':7B,34B,49B ''postgrest/kong'':89C ''project'':53B,71C ''project-level'':52B ''push'':83C ''realtim'':25B ''region'':56B ''rent'':47B ''row'':84C ''say'':43B ''secur'':86C ''sell'':35B ''separ'':29B ''servic'':17B,63B,77C ''storag'':24B ''supabas'':1A,3A,6B,75C,81C ''supabase-j'':74C ''surfac'':61B,90C ''system'':19B ''tier'':58B,73C');
INSERT INTO public.technology_catalog VALUES ('supabase-db', 'Supabase Database', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_managed.png', '#3ECF8E', '["database"]', '{"purpose": "Managed PostgreSQL platform with built-in auth (GoTrue), auto-generated RESTful API (PostgREST), real-time subscriptions (Realtime), Edge Functions (Deno), object storage, and vector embeddings (pgvector). Ideal when you want a full backend-as-a-service built on PostgreSQL with Row Level Security as the authorization layer.", "configMode": "declarative", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["PostgreSQL 15+", "@supabase/supabase-js", "PostgREST", "GoTrue", "Supabase Realtime", "Supabase Edge Functions", "Supabase Storage", "pgvector", "pg_net", "pg_cron", "pgBouncer"], "antiPatterns": ["Using service_role key in client-side code (exposes full database access)", "Creating RLS policies with USING (true) which defeats the purpose of RLS", "Not enabling RLS on new tables (tables are public by default without RLS)", "Using the dashboard SQL editor for production schema changes instead of migrations", "Storing large files in database columns instead of Supabase Storage", "Not using connection pooling for serverless or high-concurrency deployments", "Directly querying auth.users table instead of using auth.uid() in RLS", "Skipping foreign key indexes which degrades join and RLS policy performance", "Using single() when the query might return zero rows (throws error instead of null)"], "apiReference": {"docsUrl": "https://supabase.com/docs/guides/database"}, "bestPractices": ["Use Row Level Security (RLS) policies on every table as the primary authorization mechanism", "Use auth.uid() in RLS policies to scope data to the authenticated user", "Use Supabase client library instead of raw PostgREST for type safety", "Create database functions for complex business logic to keep it close to the data", "Use Supabase Realtime subscriptions for live data updates instead of polling", "Use Edge Functions for server-side logic that needs secrets or external API calls", "Use Supabase Storage with RLS-protected buckets for file uploads", "Use pg_net for async HTTP calls from database functions", "Use pgvector for AI embedding storage and similarity search", "Configure connection pooling via Supabase dashboard for production workloads", "Use database migrations for schema changes instead of the dashboard SQL editor", "Use maybeSingle() instead of single() when a query might return zero rows"], "freshnessNote": "PLACEMENT decides the lane (owner ruling 2026-07-28): inside the Supabase (Managed) platform container this is the managed product (dashboard, branching, PITR backups); inside a Docker/self-managed container it is the open-source stack (docker-compose of Postgres + GoTrue + storage-api + edge-runtime + postgrest) with the capability deltas noted on each service row. Same client SDKs either way. There is NO managed-vs-OSS config field — the container the node lives in IS the answer.", "securityGuidance": "RLS on every exposed table with policies for each operation — a table without RLS in the public schema is world-readable through the anon key, which ships in every client bundle by design. The service-role key bypasses RLS: server-side only, never in client code or logs. Write schema as versioned migrations (the dashboard is for reading, git is for truth), use security-definer functions sparingly and audit them (each is an RLS bypass), and keep the auth.uid() calls wrapped in selects so policies stay performant at scale.", "configurationTemplate": "-- supabase/migrations/0001_orders.sql\ncreate table public.orders (\n  id uuid primary key default gen_random_uuid(),\n  owner_id uuid not null references auth.users (id),\n  total numeric not null,\n  created_at timestamptz not null default now()\n);\nalter table public.orders enable row level security;\ncreate policy \"owners read own orders\" on public.orders\n  for select using ((select auth.uid()) = owner_id);\ncreate policy \"owners insert own orders\" on public.orders\n  for insert with check ((select auth.uid()) = owner_id);"}', '[{"kind": "config", "path": "supabase/config.toml", "language": "toml", "priority": "essential", "description": "Supabase project configuration for local development and CI"}, {"kind": "schema", "path": "supabase/migrations/", "language": "sql", "priority": "essential", "description": "Database migration files with schema changes and RLS policies"}, {"kind": "config", "path": "supabase/seed.sql", "language": "sql", "priority": "recommended", "description": "Seed data for local development and testing"}, {"kind": "source", "path": "src/lib/supabase.ts", "language": "typescript", "priority": "essential", "description": "Supabase client singleton initialization with environment variables"}, {"kind": "source", "path": "src/types/database.types.ts", "language": "typescript", "priority": "essential", "description": "Auto-generated TypeScript types from database schema (supabase gen types)"}, {"kind": "source", "path": "supabase/functions/", "language": "typescript", "priority": "recommended", "description": "Edge Functions directory for server-side Deno functions"}, {"kind": "config", "path": ".env.local", "language": "text", "priority": "essential", "description": "Environment variables with SUPABASE_URL and SUPABASE_ANON_KEY"}, {"kind": "schema", "path": "supabase/migrations/rls-policies.sql", "language": "sql", "priority": "essential", "description": "Row Level Security policies using auth.uid() for data access control"}]', '{"region": {"type": "string", "label": "Region", "description": "Supabase project hosting region"}, "projectUrl": {"type": "string", "label": "Project URL", "description": "Supabase project API URL (e.g., https://xxx.supabase.co)"}, "rlsEnabled": {"type": "boolean", "label": "Row Level Security", "default": true, "description": "Enable RLS on all tables (strongly recommended)"}, "vectorEnabled": {"type": "boolean", "label": "pgvector", "default": false, "description": "Enable pgvector extension for AI embedding storage and similarity search"}, "storageEnabled": {"type": "boolean", "label": "Storage", "default": false, "description": "Use Supabase Storage for file uploads with RLS-protected buckets"}, "realtimeEnabled": {"type": "boolean", "label": "Realtime", "default": true, "description": "Enable real-time subscriptions for live data updates"}, "connectionPooling": {"type": "boolean", "label": "Connection Pooling", "default": true, "description": "Use Supavisor connection pooling for production workloads"}, "edgeFunctionsEnabled": {"type": "boolean", "label": "Edge Functions", "default": true, "description": "Use Supabase Edge Functions for server-side logic"}}', '["auth-provider", "backend-service", "frontend-app", "edge-function"]', false, NULL, NULL, '2026-02-20 20:35:26.902667+00', '2026-08-30 12:07:35.06843+00', 'Supabase', '#32A872', '''15'':57C ''anon'':98C ''api'':18B ''audit'':146C ''auth'':12B ''auth.uid'':156C ''author'':54B ''auto'':15B ''auto-gener'':14B ''backend'':41B ''backend-as-a-servic'':40B ''built'':10B,45B ''built-in'':9B ''bundl'':105C ''bypass'':113C,152C ''call'':157C ''client'':104C,121C ''code'':122C ''cron'':72C ''dashboard'':131C ''databas'':2A ''db'':4A ''defin'':142C ''deno'':27B ''design'':107C ''edg'':25B,64C ''embed'':32B ''everi'':76C,103C ''expos'':77C ''full'':39B ''function'':26B,65C,143C ''generat'':16B ''git'':135C ''gotru'':13B,60C ''ideal'':34B ''keep'':154C ''key'':99C,112C ''layer'':55B ''level'':50B ''log'':124C ''manag'':5B ''migrat'':129C ''net'':70C ''never'':119C ''object'':28B ''oper'':83C ''perform'':164C ''pg'':69C,71C ''pgbouncer'':73C ''pgvector'':33B,68C ''platform'':7B ''polici'':80C,162C ''postgresql'':6B,47B,56C ''postgrest'':19B,59C ''public'':90C ''read'':134C ''readabl'':95C ''real'':21B ''real-tim'':20B ''realtim'':24B,62C ''rest'':17B ''rls'':74C,87C,114C,151C ''role'':111C ''row'':49B ''scale'':166C ''schema'':91C,126C ''secur'':51B,141C ''security-defin'':140C ''select'':160C ''server'':116C ''server-sid'':115C ''servic'':44B,110C ''service-rol'':109C ''ship'':101C ''side'':117C ''spare'':144C ''stay'':163C ''storag'':29B,67C ''subscript'':23B ''supabas'':1A,3A,61C,63C,66C ''supabase/supabase-js'':58C ''tabl'':78C,85C ''time'':22B ''truth'':138C ''use'':139C ''vector'':31B ''version'':128C ''want'':37B ''without'':86C ''world'':94C ''world-read'':93C ''wrap'':158C ''write'':125C');
INSERT INTO public.technology_catalog VALUES ('github-actions', 'GitHub Actions', NULL, '#6b7280', '["ci-cd-pipeline", "scheduled-trigger"]', '{"purpose": "CI/CD automation platform built into GitHub. Define workflows as YAML files that trigger on events (push, PR, schedule, manual). Supports matrix builds, reusable workflows, and marketplace actions.", "configMode": "definition-as-code", "provenance": {"notes": "Phase B1 additions authored from model knowledge — this row had no prior provenance. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["YAML", "Docker", "Node.js", "bash"], "antiPatterns": ["Hardcoding secrets in workflow files", "Using latest tag for actions", "Running workflows with excessive permissions", "Not caching between workflow runs"], "apiReference": {"docsUrl": "https://docs.github.com/actions"}, "bestPractices": ["Pin action versions to full SHA for security", "Use repository secrets for sensitive values", "Cache dependencies between runs", "Use environment protection rules for production deployments", "Minimize workflow permissions with permissions key"], "securityGuidance": "Pin third-party actions to a full commit SHA — tags are mutable and have been hijacked. Set explicit least-privilege permissions at the workflow/job level (contents: read as the floor). Never expose secrets to workflows triggerable from forks; treat pull_request_target as a loaded weapon. Prefer OIDC federation to cloud providers over long-lived cloud credentials stored as repository secrets.", "setupInstructions": [{"type": "manual_workflow", "title": "Create Workflow Directory", "commands": ["mkdir -p .github/workflows"], "required": true, "instructions": "Create .github/workflows/ directory in your repository root. Workflow YAML files in this directory are automatically detected by GitHub."}, {"url": "https://docs.github.com/en/actions/security-for-github-actions/security-guides/using-secrets-in-github-actions", "type": "environment_variable", "title": "Configure Repository Secrets", "required": true, "instructions": "In your repo Settings > Secrets and Variables > Actions, add secrets for API keys, deployment credentials, and tokens. These are available as secrets.MY_SECRET in workflows."}, {"type": "permissions", "title": "Set Up Environment Protection Rules", "required": false, "instructions": "In Settings > Environments, create environments (staging, production). Add protection rules: required reviewers, wait timer, and branch restrictions. Reference environments in deploy jobs."}, {"type": "permissions", "title": "Configure Workflow Permissions", "required": false, "instructions": "In Settings > Actions > General > Workflow permissions, set the default token permission to read-only. Explicitly grant write permissions per workflow using the permissions key."}], "configurationTemplate": "# .github/workflows/ci.yml\r\nname: CI\r\non: [push, pull_request]\r\npermissions:\r\n  contents: read   # default-deny; widen per job only as needed\r\njobs:\r\n  test:\r\n    runs-on: ubuntu-latest\r\n    steps:\r\n      - uses: actions/checkout@v4\r\n      - run: npm ci && npm test"}', '[{"kind": "config", "path": ".github/workflows/ci.yml", "language": "yaml", "description": "CI workflow — test on push/PR; pin third-party actions to commit SHAs; permissions: contents: read as the floor"}]', '{"supplyChainSecurity": {"type": "multiselect", "label": "Supply-chain security steps", "options": ["vulnerability-scan-trivy-grype", "sbom-generation-syft", "artifact-signing-cosign", "iac-scanning", "none-yet"], "description": "Security steps IN this pipeline (owner IaC ruling: scanners/signers are pipeline configuration, not canvas nodes) — each selected step is a concrete pipeline stage the packet will direct"}}', '[]', false, NULL, NULL, '2026-05-18 02:39:19.313183+00', '2026-08-30 12:07:28.798647+00', 'GitHub Actions', NULL, '''action'':2A,4A,31B,40C ''autom'':6B ''bash'':35C ''build'':26B ''built'':8B ''ci/cd'':5B ''cloud'':88C,94C ''commit'':44C ''content'':63C ''credenti'':95C ''defin'':11B ''docker'':33C ''event'':19B ''explicit'':54C ''expos'':69C ''feder'':86C ''file'':15B ''floor'':67C ''fork'':75C ''full'':43C ''github'':1A,3A,10B ''hijack'':52C ''least'':56C ''least-privileg'':55C ''level'':62C ''live'':93C ''load'':82C ''long'':92C ''long-liv'':91C ''manual'':23B ''marketplac'':30B ''matrix'':25B ''mutabl'':48C ''never'':68C ''node.js'':34C ''oidc'':85C ''parti'':39C ''permiss'':58C ''pin'':36C ''platform'':7B ''pr'':21B ''prefer'':84C ''privileg'':57C ''provid'':89C ''pull'':77C ''push'':20B ''read'':64C ''repositori'':98C ''request'':78C ''reusabl'':27B ''schedul'':22B ''secret'':70C,99C ''set'':53C ''sha'':45C ''store'':96C ''support'':24B ''tag'':46C ''target'':79C ''third'':38C ''third-parti'':37C ''treat'':76C ''trigger'':17B,73C ''weapon'':83C ''workflow'':12B,28B,72C ''workflow/job'':61C ''yaml'':14B,32C');

ALTER TABLE public.node_roles ENABLE TRIGGER USER;
ALTER TABLE public.technology_catalog ENABLE TRIGGER USER;

-- ── verification: the m5 canonical-gate checks, re-run against the seeded data ──
DO $$
DECLARE bad text; n int;
BEGIN
  SELECT count(*) INTO n FROM public.node_roles;
  IF n = 0 THEN RAISE EXCEPTION 'starter seed: node_roles is empty'; END IF;
  SELECT count(*) INTO n FROM public.deployment_targets;
  IF n = 0 THEN RAISE EXCEPTION 'starter seed: deployment_targets is empty'; END IF;
  SELECT count(*) INTO n FROM public.scope_archetypes;
  IF n = 0 THEN RAISE EXCEPTION 'starter seed: scope_archetypes is empty'; END IF;
  SELECT count(*) INTO n FROM public.cloud_provider_patterns;
  IF n = 0 THEN RAISE EXCEPTION 'starter seed: cloud_provider_patterns is empty'; END IF;
  SELECT count(*) INTO n FROM public.technology_catalog;
  IF n = 0 THEN RAISE EXCEPTION 'starter seed: technology_catalog is empty'; END IF;

  SELECT string_agg(DISTINCT t.id, ', ') INTO bad
  FROM public.technology_catalog t,
       jsonb_array_elements_text(COALESCE(t.role_affinities, '[]'::jsonb)) aff
  WHERE NOT EXISTS (SELECT 1 FROM public.node_roles r WHERE r.id = aff);
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'starter seed: technologies with unresolved roles (invisible in the palette): %', bad;
  END IF;

  SELECT string_agg(DISTINCT nr.id, ', ') INTO bad
  FROM public.node_roles nr,
       jsonb_array_elements_text(
         CASE jsonb_typeof(nr.can_contain)
           WHEN 'array'  THEN nr.can_contain
           WHEN 'object' THEN COALESCE(nr.can_contain -> 'roleIds', '[]'::jsonb)
           ELSE '[]'::jsonb
         END) c
  WHERE NOT EXISTS (SELECT 1 FROM public.node_roles r WHERE r.id = c);
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'starter seed: node_roles can_contain references missing roles: %', bad;
  END IF;

END $$;
